\begin{definition}[Sequence]\label{analysis-unit-0001}
    \label{def:sequence}%
    A \emph{sequence} \(\pqty{x_n}_{n \in \NN}\) on a set \(X\) is an enumerated list where each element is in \(X\).
\end{definition}

