In this chapter, \(X \subseteq \RR\) or \(X \subseteq \CC\). An important example is \(X = \RR\), the real sequences. (We will see that the fact that we have an order on \(\RR\) is significant.)

What does it mean for \(\pqty{x_n}\) to converge to some \(x \in X\), or to diverge to infinity?

On convergence,
\begin{itemize}
    \item we need \(\abs{x_n - x}\) to be small, to be smaller than any given threshold \(\epsilon > 0\) that we choose;
    \item but for the comparison, only the `tail of the sequence', i.e. `larger \(n\)' behaviour matters: we can always ignore the first \(N\) terms of the sequence, for some \(N\) depending on \(\epsilon\).
\end{itemize}

On diverging to infinity,
\begin{itemize}
    \item we need \(\abs{x_n}\) to clear any threshold \(L > 0\) that we set for it;
    \item but similarly, only the `tail' matters; we can always ignore the first \(N\) terms, where \(N\) depends on \(L\).
\end{itemize}

\begin{remark}\label{analysis-unit-0004}
    We can replace \(<\) by \(\leq\), we can replace \(\epsilon\) by \(2 \epsilon\), \(3 \epsilon\), and same for \(L\).
\end{remark}

\begin{remarks}[Signed limits and divergence in modulus]\label{analysis-unit-0005}
For real sequences, \(x_n\to+\infty\) means that for every \(L>0\),
all sufficiently late terms satisfy \(x_n>L\); replace this by \(x_n<-L\)
for \(x_n\to-\infty\). The sequence \((-1)^n n\) has neither signed limit,
but its modulus tends to \(+\infty\). Likewise \(n e^{in}\) diverges in modulus.
If \(x_n\ne0\) and \(x_n\to0\), then \(|1/x_n|\to+\infty\): given \(L>0\),
eventually \(0<|x_n|<1/L\). This asserts no convergence of the complex direction.
\end{remarks}

\begin{lemma}[Limits of Sequences are Unique]\label{analysis-unit-0007}
    \label{lem:seq-limit-unique}%
    For a sequence \(\pqty{x_n}\), if \(x_n \to a\) and \(x_n \to b\), then \(a = b\).
\end{lemma}

\begin{proposition}[Sandwich Theorem for Sequences]\label{analysis-unit-0008}
    \label{prop:seq-sandwich-theorem}%
    Let \(\pqty{x_n}, \pqty{y_n}\) and \(\pqty{z_n}\) be real sequences. Then,
    \begin{itemize}
        \item \emph{Limits preserve weak order.} If \(x_n \leq y\) for all \(n \in \NN\), and \(x_n \to x\), then \(x \leq y\);
        \item \emph{Sandwich theorem.} If \(x_n \to x\) and \(z_n \to x\), and \(x_n \leq y_n \leq z_n\) for all \(n \in \NN\), then \(y_n \to x\).
    \end{itemize}
\end{proposition}

\begin{remark}\label{analysis-unit-0009}
    In the first part for \emph{limits preserve weak order}, note that \emph{limits does not preserve strong order}, i.e. we \emph{cannot} replace all \(\leq\)s with \(<\)s. Even if \(x_n < y\) for all \(n \in \NN\), we can only conclude \(x_n \to x \leq y\) if it converges.
\end{remark}

\begin{lemma}[Convergence in \(\CC\) is the same as Convergence in \(\RR\) for Sequences]\label{analysis-unit-0010}
    \label{lem:seq-convergence-in-c}%
    Let \(\pqty{x_n}\) be a complex sequence. Then \(x_n \to x\) if and only if \(\Re\pqty{x_n} \to \Re\pqty{x}\), and \(\Im \pqty{x_n} \to \Im\pqty{x}\).
\end{lemma}

\begin{lemma}[Convergent Sequences are Bounded]\label{analysis-unit-0012}
    \label{lem:seq-convergence-bounded}%
    If \(x_n \to x\), then \(\pqty{x_n}\) must be bounded.
\end{lemma}

\begin{lemma}[Limits preserve Arithmetic for Sequences]\label{analysis-unit-0013}
    \label{lem:seq-limits-arithmetic}%
    Let \(x_n \to x\) and \(y_n \to y\). Then \(x_n + y_n \to x + y\) and \(x_n y_n \to xy\). Furthermore, if \(x \neq 0\), then \(\frac{1}{x_n} \to \frac{1}{x}\).
\end{lemma}

\begin{proof}[\proofname\ for the Product]
    Notice that
    \begin{align*}
        \abs{x_n y_n - xy} &= \abs{x_n y_n - x y_n + x y_n - xy} \\
        &\leq \abs{x} \abs{y_n - y} + \abs{y_n} \abs{x - x_n}. && \text{Triangular Inequality}
    \end{align*}

    For any \(\epsilon > 0\), there exists \(N_1 = N_1 \pqty{\epsilon}\) and \(N_2 = N_2 \pqty{\epsilon}\), such that
    \begin{itemize}
        \item \(\abs{x_n - x} < \epsilon\) for all \(n \geq N_1\); and
        \item \(\abs{y_n - y} < \epsilon\) for all \(n \geq N_2\).
    \end{itemize}

    Hence, for any \(n \geq \max\Bqty{N_1, N_2}\), we have
    \[
        \abs{x_n y_n - xy} < \epsilon \pqty{\abs{x} + \abs{y_n}}.
    \]

    Hence, by \autoref{lem:seq-convergence-bounded}, we may replace \(\abs{y_n}\) with some bound on it, and so we are done.
\end{proof}

\begin{definition}[Monotone Sequence]\label{analysis-unit-0014}
    \label{def:seq-monotone}%
    We say a real sequence \(\pqty{x_n}\) is \emph{monotone}, if either
    \begin{itemize}
        \item it is \emph{increasing}: \(x_n \leq x_{n + 1}\) for all \(n \in \NN\); or
        \item it is \emph{decreasing}: \(x_n \geq x_{n + 1}\) for all \(n \in \NN\).
    \end{itemize}

    \emph{Strictly monotone} is when we replace the \(\leq, \geq\) symbols with \(<, >\).
\end{definition}

\begin{theorem}[Monotone Convergence Theorem]\label{analysis-unit-0015}
    \label{thm:monotone-convergence}%
    Bounded monotone real sequence converges.
\end{theorem}

\begin{proof}
    Without loss of generality, assume that the sequence is strictly increasing. Use the supremum axiom of \(\RR\) that every non-empty subset of \(\RR\) that is bounded above has a supremum in \(\RR\), and we would like to show that such supremum of the elements of the sequence is in fact the limit. (Numbers and Sets provide details for the proof.)
\end{proof}

We cannot say this about sequences that are bounded but not (eventually) monotonic. Indeed, from previously, the sequence \(\pqty{x_n} = \pqty{-1}^n\) is bounded with \(\abs{x_n} \leq 1\), but it does not converge. However,
\begin{itemize}
    \item if we delete the even terms: \(x_{2k + 1} = -1\) converge to \(-1\); and
    \item if we delete the odd terms: \(x_{2k} = 1\) converge to \(1\).
\end{itemize}

The constant subsequences converge. But is it necessary that some subsequence converges for \emph{every} sequence? We first formally define what a subsequence is.

\begin{definition}[Subsequence]\label{analysis-unit-0016}
    \label{def:seq-subsequence}%
    Given a sequence \(\pqty{x_n}\), a \emph{subsequence} of \(x_n\) is a sequence \(\pqty{x_{n_k}}_{k \in \NN}\), where \(\pqty{n_k}_{k \in \NN}\) is a strictly increasing natural number sequence.
\end{definition}

\begin{theorem}[Bolzano--Weierstrass Theorem]\label{analysis-unit-0017}
    \label{thm:bolzano-weierstrass}%
    If \(\pqty{x_n}\) is a real, bounded sequence, then it has at least one convergent subsequence.
\end{theorem}

\begin{lemma}[Subsequences Converge to the Same Limit]\label{analysis-unit-0018}
    \label{lem:seq-subsequence-same-limit}%
    If \(x_n \to x\), then any subsequence \(\pqty{x_{n_k}}\) of \(\pqty{x_n}\) must converge to the same limit.
\end{lemma}

\begin{proposition}[Convergence via Subsequences]\label{analysis-unit-0021}
    \label{prop:convergence-via-subsequences}%
    Let \(\pqty{x_n}\) be bounded. If all convergent subsequences converge to the same limit, then \(x_n\) converges to the same limit.

    In other words, if \(x_n\) does not converge, then there are two convergent subsequences that converge to different limits.
\end{proposition}

\begin{lemma}[Cauchy Sequences are Bounded]\label{analysis-unit-0024}
    \label{lem:seq-cauchy-sequences-are-bounded}%
    If \(\pqty{x_n}\) is Cauchy, then it is bounded.
\end{lemma}

\begin{lemma}[Complex Cauchy Sequences]\label{analysis-unit-0025}
    \label{lem:seq-cauchy-complex-real}%
    A complex sequence \(\pqty{x_n}\) is Cauchy, if and only if the real sequences \(\Re x_n\) and \(\Im x_n\) are Cauchy.
\end{lemma}

\begin{lemma}[Convergent Sequences are Cauchy]\label{analysis-unit-0026}
    \label{lem:seq-convergent-implies-cauchy}%
    If \(x_n \to x\), then \(x_n\) is Cauchy.
\end{lemma}

\begin{theorem}[Completeness of \(\RR\) and \(\CC\) / Cauchy Sequences are Convergent on \(\RR\) or \(\CC\)]\label{analysis-unit-0027}
    \label{thm:completeness-of-r-and-c}%
    Every Cauchy sequence on \(\RR\) or \(\CC\) is convergent.
\end{theorem}

\begin{remark}\label{analysis-unit-0028}
    This allows for a proof of convergence of sequences in \(\RR\) or \(\CC\), without having to guess what the limit is.
\end{remark}

\begin{remark}\label{analysis-unit-0029}
    Metric spaces in which Cauchy sequence implies convergence is called \emph{complete}. \(\QQ\) is \emph{not} a complete metric space. Separately, \(\mathbb R\) is the unique Dedekind-complete ordered field up to
order-preserving field isomorphism: here Dedekind completeness means that every
nonempty set bounded above has a supremum. This is a statement about order
completeness, not about an arbitrary choice of metric on a field.
\end{remark}

\begin{lemma}[Linear Combination of Convergent Series Converge]\label{analysis-unit-0032}
    \label{lem:seq-linear-combination-series}%
    Fix \(\lambda \in \CC\). If \(\sum_{n = 1}^{\infty} a_n\) and \(\sum_{n = 1}^{\infty} b_n\) converge, then the series
    \[
        \sum_{n = 1}^{\infty} \pqty{\lambda a_n + b_n}
    \]
    converges as well.
\end{lemma}

\begin{remark}\label{analysis-unit-0033}
    If \(\sum_{n = 1}^{\infty} a_n\) and \(\sum_{n = 1}^{\infty} b_n\) converges, the series \(\sum_{n = 1}^{\infty} \pqty{a_n b_n}\) \emph{need not} converge. (But it must converge if both of the previous two series \textit{absolutely} converges.)
\end{remark}

\begin{lemma}[Series Convergence only depends on Tail]\label{analysis-unit-0034}
    \label{lem:seq-series-convergence-tail}%
    If \(a_n = b_n\) for all \(n \geq N\), for some \(N \in \NN\), then their series convergence behaviour is identical, i.e., \(\sum_{n = 1}^{\infty} a_n\) and \(\sum_{n = 1}^{\infty} b_n\) both converge, or both fail to converge.
\end{lemma}

\begin{proposition}[The \(n\)-th Term Test]\label{analysis-unit-0035}
    \label{prop:ser-test-nth-term}%
    A necessary condition for the sum \(\sum_{n = 1}^{\infty} a_n\) to  converge, is that \(a_n \to 0\) as \(n \to \infty\).

    Equivalently, if \(a_n \notto 0\), then \(\sum_{n = 1}^{\infty} a_n\) does not converge.
\end{proposition}

\begin{remark}\label{analysis-unit-0036}
    Note that this test is not if and only if -- specifically, that \(a_n \to 0\) is \emph{not} a sufficient condition for the infinite series to converge \(\sum_{n = 1}^{\infty} a_n\). To see this, we consider \autoref{ex:seq-harmonic-series}, a famous counterexample.
\end{remark}

\begin{proposition}[Root Test]\label{analysis-unit-0040}
    \label{prop:ser-test-root}%
    Let \(a_n \geq 0\) for all \(n \in \NN\), such that \(\sqrt[n]{a_n} \to a\) is convergent. We have the following.

    \begin{itemize}
        \item If \(a < 1\), then \(\sum_{n = 1}^{\infty} a_n\) converges.
        \item If \(a > 1\), then \(\sum_{n = 1}^{\infty} a_n\) diverges.
    \end{itemize}
\end{proposition}

\begin{remark}\label{analysis-unit-0041}
    If \(a = 1\), then the test is inconclusive.
\end{remark}

\begin{example}[Root Test and Geometric Series]\label{analysis-unit-0042}
    \label{ex:ser-test-root-geo}%
    Let \(\pqty{a_n} = \frac{1}{2^n}\), then \(\sqrt[n]{a_n} = \frac{1}{2}\) is indeed the ratio of the geometric series.

    Let \(\pqty{b_n} = 4^n\), then \(\sqrt[n]{b_n} = 4\) is indeed the ratio of the geometric series.

    Although circular, \autoref{prop:ser-test-root} (Root Test) implies the convergence/divergence of the geometric series, apart from the case where \(r = 1\).
\end{example}

\begin{proposition}[Ratio Test]\label{analysis-unit-0043}
    \label{prop:ser-test-ratio}%
    Let \(a_n>0\) for all sufficiently large \(n\), and \(\frac{a_{n + 1}}{a_n} \to a\) as \(n \to \infty\).

    \begin{itemize}
        \item If \(a < 1\), then \(\sum_{n = 1}^{\infty} a_n\) converges.
        \item If \(a > 1\), then \(\sum_{n = 1}^{\infty} a_n\) diverges.
    \end{itemize}
\end{proposition}

\begin{remark}\label{analysis-unit-0044}
    If \(a = 1\), then the test is inconclusive.
\end{remark}

\begin{example}[Ratio Test and Geometric Series]\label{analysis-unit-0045}
    \label{ex:ser-test-ratio-geo}%
    Let \(\pqty{a_n} = \frac{1}{2^n}\), then \(\frac{a_{n + 1}}{a_n} = \frac{1}{2}\) is indeed the ratio of the geometric series.

    Let \(\pqty{b_n} = 4^n\), then \(\frac{b_{n + 1}}{b_n} = 4\) is indeed the ratio of the geometric series.

    Although circular, \autoref{prop:ser-test-ratio} (Ratio Test) implies the convergence/divergence of the geometric series, apart from the case where \(r = 1\).
\end{example}

\begin{remark}\label{analysis-unit-0047}
    If the ratio test is conclusive, then the root test is conclusive. However, the converse fails. For example, look at
    \[
        a_n = \begin{cases}
            2^{-n}, & n\text{ is even}, \\
            2^{-\pqty{n + 1}}, & n\text{ is odd}.
        \end{cases}
    \]
\end{remark}

