\begin{remarks}\label{analysis-unit-0049}
    \begin{itemize}
        \item On the right-hand side of the if and only if, we have something that we will see later (`improper integral'), which will come up later in the course.
        \item The last statement tells us that there is really a deep connection between series and integrals.
    \end{itemize}
\end{remarks}

\begin{examples}[Integral Test]\label{analysis-unit-0050}
    \label{ex:integral-test}%
    \begin{itemize}
        \item For real \(p\), the series \(\sum_{n=1}^{\infty}n^{-p}\) converges
if and only if \(p>1\). For \(p\le0\) its terms do not tend to zero.
For \(p>0\), apply the integral test to the decreasing function \(f(t)=t^{-p}\):
\[
\int_1^N t^{-p}\,dt=
\begin{cases}\log N,&p=1,\\(N^{1-p}-1)/(1-p),&p\ne1.\end{cases}
\]
Its limit is \(+\infty\) when \(p\le1\) and \(1/(p-1)\) when \(p>1\).
In particular the harmonic series diverges.

        \item We investigate \(\sum_{n = 2}^{\infty} \frac{1}{n \log n}\). Evaluating the integral gives
        \begin{align*}
            \int_{2}^{n} \frac{\dd{t}}{t \log t} &= \int_{\log 2}^{\log n} \frac{\dd{u}}{u} \\
            &= \bqty{\log u}_{\log 2}^{\log n} \\
            &= \log \log n - \log \log 2 \\
            &\to \plusinfty
        \end{align*}
        as \(n \to \infty\). By \autoref{prop:ser-test-integral} (Integral Test), this series diverges.

        \item The series \(\sum_{n = 2}^{\infty} \frac{1}{n \pqty{\log n}^2}\) converges by evaluating a similar integral.
    \end{itemize}
\end{examples}

\begin{proposition}[Cauchy Condensation Test]\label{analysis-unit-0051}
    \label{prop:ser-test-cauchy-condensation}%
    Let \(a_n \geq 0\) for all \(n \in \NN\), and let \(\pqty{a_n}\) be decreasing. Then \(\sum_{n = 1}^{\infty} a_n\) converges, if and only if the condensed series
    \[
        \sum_{n = 0}^{\infty} 2^n a_{2^n}
    \]
    converges.
\end{proposition}

\begin{example}[Alternating Harmonic Series]\label{analysis-unit-0053}
    \label{ex:alternating-harmonic}%
    \autoref{prop:ser-test-alternating} (Alternating Series Test) tells us that
    \[
        \sum_{n = 1}^{\infty} \frac{\pqty{-1}^{n + 1}}{n}
    \]
    converges (to \(\log 2\)), while the harmonic series \(\sum_{n = 1}^{\infty} \frac{1}{n}\) diverges.
\end{example}

\begin{definition}[Absolute Convergence]\label{analysis-unit-0054}
    \label{def:ser-absolute-convergence}%
    We say the series \(\sum a_n\) is \emph{absolutely convergent} if \(\sum \abs{a_n}\) converges.
\end{definition}

\begin{remark}\label{analysis-unit-0055}
    Since \(\abs{a_n} \geq 0\) for all \(n \in \NN\), \autoref{prop:ser-test-comparison} (Comparison Test), \autoref{prop:ser-test-root} (Root Test), \autoref{prop:ser-test-ratio} (Ratio Test), \autoref{prop:ser-test-integral} (Integral Test) and \autoref{prop:ser-test-cauchy-condensation} (Cauchy Condensation Test) are good tests on absolute convergence.
\end{remark}

\begin{theorem}[Absolute Convergence implies Convergence]\label{analysis-unit-0056}
    \label{thm:ser-absolute-convergence-implies-convergence}%
    Absolute convergence implies convergence.
\end{theorem}

\begin{remark}\label{analysis-unit-0057}
    The converse is false by examining \autoref{ex:alternating-harmonic} (Alternating Harmonic Series).
\end{remark}

\begin{proof}
    Let \(s_k = \sum_{n = 1}^{k} a_n\) and \(r_k = \sum_{n = 1}^{k} \abs{a_n}\). Since \(\pqty{r_k}\) converges, it is Cauchy, and to show \(\pqty{s_k}\) converges, we want to show that it is Cauchy.

    Note that
    \begin{align*}
        \abs{s_k - s_l} &= \abs{\sum_{n = l - 1}^{k} a_n} \\
        &\leq \sum_{n = l - 1}^{k} \abs{a_n} \\
        &= r_k - r_l
    \end{align*}
    which shows that \(\pqty{r_k}\) is Cauchy implies that \(\pqty{s_k}\) is Cauchy. This finishes the proof.
\end{proof}

\begin{definition}[Conditional Convergence]\label{analysis-unit-0058}
    \label{def:ser-conditional-convergence}%
    A series that is convergent but is not absolutely convergent is \emph{conditional convergent}.
\end{definition}

