\begin{itemize}
    \item Rearrange Terms (c.f. \autoref{prop:ser-rearrangement-absolute-convergence} and Riemann Series/Rearrangement Theorem);
    \item Multiply series to a Convergent Product Series;
    \item Put Brackets on Terms (i.e. only studying a subsequence of partial sums).
\end{itemize}

\begin{proposition}[Rearrangement under Absolute Convergence]\label{analysis-unit-0060}
    \label{prop:ser-rearrangement-absolute-convergence}%
    Let \(\functiondomain{\sigma}{\NN}{\NN}\) be a bijection, and let the series \(\sum_{n=1}^{\infty} a_n\) be absolutely convergent. Then the rearranged series given by terms \(a_n' = a_{\sigma\pqty{n}}\) is absolutely convergent, and converges to the same limit.
\end{proposition}

\begin{proof}
    For any \(1 \leq m \leq n\), we have
    \begin{align*}
        \text{Right-Hand Side} &= \sum_{j = m}^{n} S_j b_j - \sum_{j = m - 1}^{n - 1} S_j b_{j + 1} \\
        &= \sum_{j = m}^{n} S_j b_j - \sum_{j = m}^{n} S_{j - 1} b_j \\
        &= \sum_{j = m}^{n} \pqty{S_j - S_{j - 1}} b_j \\
        &= \sum_{j = m}^{n} a_j b_j \\
        &= \text{Left-Hand Side}
    \end{align*}
    as desired.
\end{proof}

\begin{lemma}[No Slowest Divergent Series]\label{analysis-unit-0063}
    \label{lem:no-slowest-divergent-series}%
    Suppose that \(\sum a_n\) diverges to infinity and \(a_n > 0\). Then there is a sequence \(\pqty{b_n}\) with \(\frac{b_n}{a_n} \to 0\) and \(\sum b_n\) divergent.
\end{lemma}

\begin{proposition}[Convergence of Product Series]\label{analysis-unit-0064}
    If both \(\sum a_n\) and \(\sum b_n\) both converges absolutely, then \(\sum a_n b_n\) converges absolutely.
\end{proposition}

\begin{remark}\label{analysis-unit-0065}
    This is not true for non-absolute convergent series, with the following counterexample. Let \(a_n = b_n = \pqty{-1}^{n + 1} \frac{1}{\sqrt{n}}\). By \autoref{prop:ser-test-alternating} (Alternating Series Test), since \(\frac{1}{\sqrt{n}} \to 0\) and is decreasing, \(\sum a_n\) and \(\sum b_n\) both converge.

    But \(a_n b_n = \frac{1}{n}\) and \(\sum a_n b_n\) is the harmonic series, which diverges.
\end{remark}

\begin{remark}\label{analysis-unit-0066}
    Note we only used the condition that \(a_n\) is bounded here, so the conditions can be weakened.
\end{remark}

\begin{remark}\label{analysis-unit-0067}
    The conditions for this can be weakened -- for example using H\"older's inequality, a more general version of Cauchy--Schwarz.
\end{remark}

Take \(\functiondomain{f}{X}{\CC}\) for some \(X \subseteq \CC\). We want to define what we mean by \(f\pqty{z} \to y\) as \(z \to a\), \emph{even if \(a \notin X\)}.

