\begin{corollary}[Sign of Derivative and Monotonicity] 

 Let \(\functiondomain{f}{\ccintv{a}{b}}{\RR}\) be continuous on \(\ccintv{a}{b}\) and differentiable on \(\oointv{a}{b}\). Then
 \begin{itemize}
 \item if \(f'\pqty{x} \geq 0\) on \(\oointv{a}{b}\), then \(f\) is increasing;
 \item if \(f'\pqty{x} > 0\) on \(\oointv{a}{b}\), then \(f\) is strictly increasing;
 \item if \(f'\pqty{x} \leq 0\) on \(\oointv{a}{b}\), then \(f\) is decreasing;
 \item if \(f'\pqty{x} < 0\) on \(\oointv{a}{b}\), then \(f\) is strictly decreasing;
 \item if \(f'\pqty{x} = 0\) on \(\oointv{a}{b}\), then \(f\) is constant.
 \end{itemize}
\end{corollary}

latex:
\begin{corollary}[Sign of Derivative and Monotonicity]\label{analysis-unit-0114}
    \label{cor:sign-of-derivative-monotonicity}%
    Let \(\functiondomain{f}{\ccintv{a}{b}}{\RR}\) be continuous on \(\ccintv{a}{b}\) and differentiable on \(\oointv{a}{b}\). Then
    \begin{itemize}
        \item if \(f'\pqty{x} \geq 0\) on \(\oointv{a}{b}\), then \(f\) is increasing;
        \item if \(f'\pqty{x} > 0\) on \(\oointv{a}{b}\), then \(f\) is strictly increasing;
        \item if \(f'\pqty{x} \leq 0\) on \(\oointv{a}{b}\), then \(f\) is decreasing;
        \item if \(f'\pqty{x} < 0\) on \(\oointv{a}{b}\), then \(f\) is strictly decreasing;
        \item if \(f'\pqty{x} = 0\) on \(\oointv{a}{b}\), then \(f\) is constant.
    \end{itemize}
\end{corollary}

\begin{remark}\label{analysis-unit-0115}
    We cannot always replace \(\ccintv{a}{b}\) with some set \(X \subseteq \RR\). For instance, the function
    \[
        \function{f}{\QQ}{\RR}{x}{\begin{cases}
            0, & x^2 > 2, \\
            1, & x^2 < 2.
        \end{cases}}
    \]

    This is continuous at any point in its domain, so it is continuous, and \(f'\pqty{x} = 0\) for any \(x \in \QQ\). However, this function is not constant.
\end{remark}

\begin{lemma}[Zero Derivative implies Constant]\label{analysis-unit-0116}
    \label{lem:zero-derivative-constant}%
    For a differentiable function \(\functiondomain{f}{\CC}{\CC}\), and that \(f'\pqty{z} = 0\) for all \(z \in \CC\), then \(f\) is constant.
\end{lemma}

Note that if we take \(g = \identity\) then this reduces to \autoref{thm:mean-value-thm} (Mean Value Theorem).

The way to visualise \autoref{thm:cauchy-mvt} (Cauchy Mean Value Theorem) is to view \(f\) and \(g\) not as two functions -- we view them as the coordinates of some parametric curve \(\pqty{f\pqty{t}, g\pqty{t}}\), and the gradient of that curve is given by \(\frac{g'\pqty{c}}{f'\pqty{c}}\), while the secant line is given by \(\frac{g\pqty{b} - g\pqty{a}}{f\pqty{b} - f\pqty{a}}\), as demonstrated in \autoref{fig:cauchy-mvt}

\begin{figure}[ht!]\centering\begin{minipage}{.94\linewidth}For the parametric curve \(t\mapsto(g(t),f(t))\), Cauchy\textquotesingle s mean value theorem states that at some interior parameter the determinant of the tangent vector and the endpoint chord is zero: \(g\prime(c)(f(b)-f(a))-f\prime(c)(g(b)-g(a))=0\). This includes the case of a zero tangent vector.\end{minipage}\caption{Mathematical description}\label{fig:cauchy-mvt}\end{figure}

The proof strategy is similar -- we aim to reduce this to \autoref{thm:rolle} (Rolle's Theorem).

\begin{theorem}[L'H\^{o}pital's Rule]\label{analysis-unit-0120}
    \label{thm:l-hopitals}%
    Let \(\minusinfty \leq a < b \leq \plusinfty\). Let \(\functiondomain{f, g}{\oointv{a}{b}}{\RR}\) be differentiable, and \(g'\pqty{x} \neq 0\) for all \(x \in \oointv{a}{b}\). Suppose:
    \begin{itemize}
        \item the limit
        \[
            \lim_{x \to a} \frac{f'\pqty{x}}{g'\pqty{x}} = l
        \]
        exists, where \(l \in \RR \cup \Bqty{\pminfty}\) could be infinite;
        \item \(\lim_{x \to a} f\pqty{x} = \lim_{x \to a} g\pqty{x} = 0\); or \(\lim_{x \to a} g\pqty{x} = \pminfty\).
    \end{itemize}

    Then we have
    \[
        \lim_{x \to a} \frac{f\pqty{x}}{g\pqty{x}} = l.
    \]
\end{theorem}

\begin{proposition}[Local Inverse Function Theorem]\label{analysis-unit-0122}
    \label{prop:local-ivt}%
    Let \(\functiondomain{f}{\ccintv{a}{b}}{\RR}\) be continuous on \(\ccintv{a}{b}\) and continuously differentiable on \(\oointv{a}{b}\). Suppose there is some \(x_0 \in \oointv{a}{b}\) such that \(f'\pqty{x_0} \neq 0\). Then there exists some \(\epsilon > 0\) with \(\ccintv{x_0 - \epsilon}{x_0 + \epsilon} \subseteq \oointv{a}{b}\) such that the restriction
    \[
        \functiondomain{f}{\oointv{x_0 - \epsilon}{x_0 + \epsilon}}{f\pqty{\oointv{x_0 - \epsilon}{x_0 + \epsilon}}}
    \]
    is bijective, and \(f\inverse\) is differentiable with derivative
    \[
        \pqty{f\inverse}'\pqty{y} = \frac{1}{f'\pqty{f\inverse\pqty{y}}}
    \]
    for all \(y \in f\pqty{\oointv{x_0 - \epsilon}{x_0 + \epsilon}}\).
\end{proposition}

\begin{theorem}[Darboux's Theorem]\label{analysis-unit-0123}
    If \(\functiondomain{f}{\ccintv{a}{b}}{\RR}\) is differentiable with \(a < b\), then for all \(f'\pqty{a} < z < f'\pqty{b}\) or \(f'\pqty{b} < z < f'\pqty{a}\), there exists some \(c\) with \(a < c < b\), such that \(f'\pqty{c} = z\).
\end{theorem}

\begin{definition}[Higher Order Derivatives]\label{analysis-unit-0124}
    \label{def:higher-order-derivatives}%
    Suppose \(\functiondomain{f}{X \subseteq \CC}{\CC}\) is differentiable on \(X\). We say the function \(f\) is \emph{twice differentiable} on \(X\), if
    \[
        \function{f'}{X}{\CC}{x}{f'\pqty{x}}
    \]
    is differentiable. We define \(f\) is \emph{\(k\)-times differentiable} similarly, and denote this as \(f \in \diffClass{k} \pqty{X}\).

    We say \(f\) is \emph{\(k\)-times continuously differentiable}, and denote this as \(f \in \contClass{k} \pqty{X}\), if \(f\) is \(k\)-times differentiable and the \(k\)-th derivative
    \[
        \function{f^{\pqty{k}}}{X}{\CC}{x}{f^{\pqty{k}}\pqty{x}}
    \]
    is continuous.
\end{definition}

\begin{remarks}\label{analysis-unit-0129}
    \begin{itemize}
        \item When \(n = 1\), this simply gives \autoref{thm:mean-value-thm} (Mean Value Theorem).
        \item Furthermore, there is nothing special about \(h > 0\): we could simply swap the bounds of the intervals (i.e. \(\ccintv{a}{a + h}\) to \(\ccintv{a + h}{a}\) and \(\oointv{a}{a + h}\) to \(\oointv{a + h}{a}\)), and we will still get a similar result.
        \item If \(f \in \contClass{n} \pqty{\oointv{c}{d}}\) with \(\ccintv{a}{a + h} \subset \oointv{c}{d}\), then note that \(f^{\pqty{n}}\) is continuous on the closed interval, hence bounded, and let
        \[
            M_n = \sup_{x \in \ccintv{a}{a + h}} \abs{f^{\pqty{n}} \pqty{x}}.
        \]

        Then
        \[
            \abs{R_{n, f, a} \pqty{h}} \leq M_n \cdot \frac{\abs{h}^n}{n!}
        \]
        and we have \(R_{n, f, a} \pqty{h} = \bigO \pqty{h^n}\) as \(h \to 0\), or in other words, the approximation gets better as the point \(a + h\) gets closer to \(a\). \textbf{However, this does not tell us that \(R_{n, f, a} \pqty{h} \to 0\) as \(n \to \infty\)}, or in other words, adding more terms does not necessarily make our approximation better. Even if \(f \in \smoothClass\), we still do not know how \(M_n\) behaves with \(n\). (In other words, there are smooth functions that are not analytic (on \(\RR\)).)
    \end{itemize}
\end{remarks}

\begin{proof}
    By putting \(p = 1\) into the second proof of \autoref{thm:taylor-thm-langrange-remainder}.
\end{proof}

\begin{remark}\label{analysis-unit-0131}
    Similarly, if we have \(f \in \contClass{n} \pqty{\oointv{c}{d}}\) with \(\ccintv{a}{a + h} \subset \oointv{c}{d}\), then as in previous remark, we may set
    \[
        M_n = \sup_{x \in \ccintv{a}{a + h}} \abs{f^{\pqty{n}} \pqty{x}}
    \]
    and by \autoref{thm:taylor-thm-cauchy-remainder}, then we have
    \[
        \abs{R_{n, f, a} \pqty{h}} \leq M_n \cdot \frac{\abs{h}^n}{\pqty{n - 1}!}.
    \]
\end{remark}

\begin{example}[Analytic Function]\label{analysis-unit-0134}
    \label{ex:analytic-fn}%
    As in \autoref{ex:application-taylor}, the function \(x^q\) is analytic in \(\oointv{0}{2}\) -- in other words, \(\pqty{1 + x}^q\) is analytic in \(\oointv{-1}{1}\).
\end{example}

\begin{proof}
    Identical to the second proof of \autoref{thm:taylor-thm-langrange-remainder}.
\end{proof}

\begin{definition}[Upper and Lower Riemann Sums]\label{analysis-unit-0138}
    \label{def:upper-lower-riemann-sum}%
    Let \(\functiondomain{f}{\ccintv{a}{b}}{\RR}\) be bounded. Let a \emph{partition/dissection} \(\partition = \Bqty{x_0, x_1, \ldots, x_n}\) with \(a = x_0 < x_1 < \cdots x_n = b\) be given. Then we let
    \[
        \upperSum \pqty{f, \partition} = \sum_{j = 1}^{n} \pqty{\sup_{x \in \ccintv{x_{j - 1}}{x_{j}}} f\pqty{x}} \cdot \pqty{x_j - x_{j - 1}}
    \]
    as the \emph{Upper Riemann Sum}, and similarly,
    \[
        \lowerSum \pqty{f, \partition} = \sum_{j = 1}^{n} \pqty{\inf_{x \in \ccintv{x_{j - 1}}{x_{j}}} f\pqty{x}} \cdot \pqty{x_j - x_{j - 1}}
    \]
    as the \emph{Lower Riemann Sum}, of the function \(f\) associated to the partition \(\partition\).
\end{definition}

\begin{definition}[Upper and Lower Integrals]\label{analysis-unit-0140}
    \label{def:upper-lower-int}%
    Let \(\functiondomain{f}{\ccintv{a}{b}}{\RR}\) be bounded. We say
    \[
        \upperI \pqty{f} = \upperInt_{a}^{b} f \pqty{x} \dd{x} = \inf_{\partition\text{ is a partition of }\ccintv{a}{b}} \upperSum \pqty{f, \partition}
    \]
    be the \emph{upper integral} of \(f\), and similarly,
    \[
        \lowerI \pqty{f} = \lowerInt_{a}^{b} f \pqty{x} \dd{x} = \sup_{\partition\text{ is a partition of }\ccintv{a}{b}} \lowerSum \pqty{f, \partition}
    \]
    be the \emph{lower integral} of \(f\).
\end{definition}

\begin{remark}\label{analysis-unit-0142}
    We define by convention
    \[
        \int_{a}^{b} f = - \int_{b}^{a} f.
    \]
\end{remark}

\begin{example}[Non-Riemann Integrable Function]\label{analysis-unit-0143}
    \label{ex:non-riemann-integrable-fn}%
    Continuing from \autoref{ex:riemann-sums}, we note that \(\upperI\pqty{f} = 1\) while \(\lowerI\pqty{f} = 0\). Hence, this function is not Riemann integrable.

    Just as a remark, it is Lebesgue integrable using the Lebesgue measure, and the result is \(0\) -- intuitively, there are `way too few' rational numbers (and this is saying \(\QQ\) has zero Lebesgue measure, since it is countable).
\end{example}

\begin{proof}
    We take the common refinement \(\partition \cup \partition'\). Therefore, by \autoref{lem:refinement-better-estimate},
    \[
        \lowerSum\pqty{f, \partition} \leq \upperSum\pqty{f, \partition \cup \partition'} \leq \upperSum\pqty{f, \partition \cup \partition'} \leq \upperSum\pqty{f, \partition'}.
    \]
\end{proof}

\begin{proposition}[Monotone Functions are Integrable]\label{analysis-unit-0150}
    \label{prop:monotonic-integrable}%
    Any monotonic \(\functiondomain{f}{\ccintv{a}{b}}{\RR}\) is integrable.
\end{proposition}

\begin{proposition}[Continuous Functions are Integrable]\label{analysis-unit-0151}
    \label{prop:continuous-integrable}%
    Any continuous \(\functiondomain{f}{\ccintv{a}{b}}{\RR}\) is integrable.
\end{proposition}

\begin{definition}[Piecewise Continuous]\label{analysis-unit-0152}
    \label{def:piecewise-continuous}%
    Let \(\functiondomain{f}{\ccintv{a}{b}}{\RR}\). We say \(f\) is \emph{piecewise continuous} if there is some partition \(\partition\) of \(\ccintv{a}{b}\), such that the restriction on every open interval
    \[
        \rightbar{f}_{\oointv{x_{j - 1}}{x_j}}
    \]
    is continuous and has finite one-sided limits at both endpoints: as \(x\downarrow x_{j-1}\) and as \(x\uparrow x_j\).
\end{definition}

\begin{proposition}[Countable Discontinuities implies Integrability]\label{analysis-unit-0157}
    \label{prop:countable-discontinuity-implies-integrability}%
    Let \(\functiondomain{f}{\ccintv{a}{b}}{\RR}\) be bounded, and let its set of discontinuities be
    \[
        D = \set{x \in \ccintv{a}{b}}{f \text{ is not continuous at }x}.
    \]

    If \(D\) is finite or countable, then \(f\) is Riemann integrable.

    \textit{[The countably infinite case is supplementary.]}
\end{proposition}

\begin{remark}\label{analysis-unit-0158}
    For bounded \(f:[a,b]\to\mathbb R\), if \(f\) is not Riemann integrable, then its set \(D\) of discontinuities must be uncountable. However, there are functions with \(D\) uncountable, yet \(f\) is Riemann integrable. One example of this is the indicator of the Cantor Set. (Since the Cantor Set has zero Lebesgue Measure.)
\end{remark}

\begin{proof}
    These are direct consequences of application of \autoref{lem:properties-supremum-infimum}.
\end{proof}

\begin{proof}
    From \autoref{lem:properties-upper-lower-sum}, we have \(\upperSum\pqty{f, \partition} \leq \upperSum\pqty{g, \partition}\), so taking infimum over all partitions gives us the result as desired.
\end{proof}

\begin{lemma}[Product of Integrable Functions is Integrable]\label{analysis-unit-0164}
    \label{lem:integral-product}%
    Let \(\functiondomain{f, g}{\ccintv{a}{b}}{\RR}\) be integrable. Then the product \(f\pqty{x} \cdot g\pqty{x}\) is integrable.
\end{lemma}

\begin{remark}\label{analysis-unit-0165}
    We do not have a formula for this case, and it is generally the case that
    \[
        \int_{a}^{b} f\pqty{x} g\pqty{x} \dd{x} \neq \int_{a}^{b} f\pqty{x} \dd{x} \cdot \int_{a}^{b} g\pqty{x} \dd{x}.
    \]
\end{remark}

\begin{proposition}[Indefinite Integral is Continuous]\label{analysis-unit-0166}
    \label{prop:indef-integral-continuous}%
    Let \(\functiondomain{f}{\ccintv{a}{b}}{\RR}\) be Riemann integrable, and let \(F\) be defined as above. Then \(F\) is continuous on \(\ccintv{a}{b}\).
\end{proposition}

\begin{proof}
    We have
    \begin{align*}
        \abs{F\pqty{x + h} - F\pqty{x}} &= \abs{\int_{a}^{x + h} f\pqty{t} \dd{t} - \int_{a}^{x} f\pqty{t} \dd{t}} \\
        &= \abs{\int_{x}^{x + h} f\pqty{t} \dd{t}} \\
        &\leq \int_{x}^{x + h} \abs{f\pqty{t}} \dd{t} \\
        &\leq \sup_{x \in \ccintv{a}{b}} \abs{f} \cdot \abs{h}.
    \end{align*}

    Hence, as \(h \to 0\), \(\abs{F\pqty{x + h} - F\pqty{x}} \to 0\), showing \(F\) is continuous.
\end{proof}

\begin{example}[Non-Differentiable Indefinite Integral]\label{analysis-unit-0168}
    \label{ex:non-differentiable-indefinite-integral}%
    Take \(\ccintv{a}{b} = \ccintv{-1}{1}\), with
    \[
        f\pqty{x} = \begin{cases}
            -1, & x \leq 0, \\
            1, & x > 0.
        \end{cases}
    \]

    \(f\) is piecewise continuous, and \(F\) defined above is given by
    \[
        F\pqty{x} = \int_{-1}^{x} f\pqty{t} \dd{t} = \begin{cases}
            -x - 1, & x \leq 0 \\
            x - 1, & x \geq 0
        \end{cases}
        = \abs{x} - 1.
    \]

    \(F\) is continuous on \(\ccintv{-1}{1}\), as expected from \autoref{prop:indef-integral-continuous}, but it is not differentiable at \(x = 0\).
\end{example}

