\begin{corollary}[Integral of Continuous Derivative]\label{analysis-unit-0169}
    \label{cor:integral-continuous-derivative}%
    If \(f\pqty{x} = g'\pqty{x}\) is continuous on \(\ccintv{a}{b}\), then
    \[
        F\pqty{x} = \int_{a}^{x} f\pqty{t} \dd{t} = g\pqty{x} - g\pqty{a}
    \]
    for all \(x \in \ccintv{a}{b}\).
\end{corollary}

\begin{theorem}[Taylor's Theorem with Integral Remainder]\label{analysis-unit-0173}
    \label{thm:taylor-thm-integral-remainder}%
    Let \(\functiondomain{f}{\ccintv{a}{a + h}}{\RR}\) be \(n\) times continuously differentiable on the closed interval \(\ccintv{a}{a+h}\), where \(n\ge1\) and \(h>0\). Then the \emph{Integral Form of the Remainder} gives the Taylor remainder in the form
    \begin{align*}
        R_{n, f, a} \pqty{h} &= \frac{h^{n}}{\pqty{n - 1}!} \cdot \int_{0}^{1} \pqty{1 - t}^{n - 1} f^{\pqty{n}} \pqty{a + th} \dd{t} \\
        &= \frac{1}{\pqty{n - 1}!} \cdot \int_{0}^{h} \pqty{h - u}^{n - 1} f^{\pqty{n}} \pqty{a + u} \dd{u}.
    \end{align*}
\end{theorem}

\begin{proof}
    Using \autoref{prop:integration-by-parts} (Integration by Parts), we have
    \begin{align*}
        &\phantom{=} \frac{1}{\pqty{n - 1}!} \cdot \int_{0}^{h} \pqty{h - u}^{n - 1} f^{\pqty{n}} \pqty{a + u} \dd{u} \\
        &= - h^{n - 1} \cdot \frac{f^{\pqty{n - 1}} \pqty{a}}{\pqty{n - 1}!} + \frac{1}{\pqty{n - 2}!} \int_{0}^{h} \pqty{h - u}^{n - 2} f^{\pqty{n - 1}} \pqty{a + u} \dd{u} \\
        &= \cdots \\
        &= - \sum_{k = 1}^{n - 1} \frac{f^{\pqty{k}} \pqty{a}}{k!} \cdot h^k + \int_{0}^{h} f'\pqty{a + u} \dd{u} \\
        &= - \sum_{k = 0}^{n - 1} \frac{f^{\pqty{k}} \pqty{a}}{k!} \cdot h^k + f\pqty{a + h},
    \end{align*}
    as desired.
\end{proof}

\begin{proof}[\proofname\ of \autoref{thm:taylor-thm-langrange-remainder} (Lagrange Form of the Remainder), assuming continuity of \(f^{\pqty{n}}\)]
    Let \(g\pqty{t} = \pqty{1 - t}^{n - 1}\). Then using \autoref{thm:taylor-thm-integral-remainder} (Integral Form of the Remainder) and \autoref{thm:cauchy-mvt-integrals} (Cauchy Mean Value Theorem for Integrals), there is some \(\theta \in \oointv{0}{1}\), such that
    \begin{align*}
        R_{n, f, a} \pqty{h} &= \frac{h^n}{\pqty{h - 1}!} f^{\pqty{n}} \pqty{a + \theta h} \int_{0}^{1} \pqty{1 - t}^n \dd{t} \\
        &= \frac{h^n}{n!} \cdot f^{\pqty{n}} \pqty{a + \theta h}.
    \end{align*}
\end{proof}

\begin{proof}[\proofname\ of \autoref{thm:taylor-thm-cauchy-remainder} (Cauchy Form of the Remainder), assuming continuity of \(f^{\pqty{n}}\)]
    Let \(g\pqty{t} = 1\) be constant. Then using \autoref{thm:taylor-thm-integral-remainder} (Integral Form of the Remainder) and \autoref{thm:mvt-integrals} (Mean Value Theorem for Integrals), there is some \(\theta \in \oointv{0}{1}\), such that
    \begin{align*}
        R_{n, f, a} \pqty{h} &= \frac{h^n}{\pqty{h - 1}!} \pqty{1 - \theta}^{h} f^{\pqty{n}} \pqty{a + \theta h} \int_{0}^{1} \dd{t} \\
        &= \frac{h^n}{\pqty{n - 1}!} \cdot \pqty{1 - \theta}^{n - 1} \cdot f^{\pqty{n}} \pqty{a + \theta h}.
    \end{align*}
\end{proof}

\begin{proof}[\proofname\ of \autoref{thm:taylor-thm-schlomilch-remainder} (Schl\"{o}milch Form of the Remainder), asusming continuitiy of \(f^{\pqty{n}}\)]
    Let \(g\pqty{t} = \pqty{1 - t}^{p - 1}\). Then using \autoref{thm:taylor-thm-integral-remainder} (Integral Form of the Remainder), and \autoref{thm:cauchy-mvt-integrals} (Cauchy Mean Value Theorem for Integrals), there is some \(\theta \in \oointv{0}{1}\), such that
    \begin{align*}
        R_{n, f, a} \pqty{h} &= \frac{h^n}{\pqty{n - 1}!} \cdot \int_{0}^{1} \pqty{1 - t}^{n - 1} f^{\pqty{n}} \pqty{a + th} \dd{t} \\
        &= \frac{h^n}{\pqty{n - 1}!} \cdot \int_{0}^{1} \bqty{f^{\pqty{n}} \pqty{a + th} \cdot \pqty{1 - t}^{n - p}} \cdot \pqty{1 - t}^{p - 1} \dd{t} \\
        &= \frac{h^n}{\pqty{n - 1}!} \cdot f^{\pqty{n}} \pqty{a + \theta h} \cdot \pqty{1 - \theta}^{n - p} \cdot \int_{0}^{1} \pqty{1 - t}^{p - 1} \dd{t} \\
        &= \frac{h^n}{p \pqty{n - 1}!} \cdot \pqty{1 - \theta}^{n - p} f^{\pqty{n}} \pqty{a + \theta h}.
    \end{align*}
\end{proof}

\begin{proposition}[Comparison Test for Integrals]\label{analysis-unit-0184}
    \label{prop:int-test-comparison}%
    Let \(\functiondomain{f, g}{\cointv{a}{\plusinfty}}{\RR}\) be integrable over any finite interval \(\ccintv{a}{R}\) for \(R \geq a\), and satisfies that \(0 \leq f\pqty{x} \leq g\pqty{x}\) for all \(x \in \cointv{a}{\plusinfty}\). Then the following holds.

    \begin{enumerate}
        \item If the improper integral of \(g\) to infinity exists, then so does the improper integral of \(f\), and we have
        \[
            \int_{a}^{\plusinfty} f\pqty{x} \dd{x} \leq \int_{a}^{\plusinfty} g\pqty{x} \dd{x}.
        \]

        \item If the improper integral of \(f\) to infinity diverges (to infinity), then so does the improper integral of \(g\).
    \end{enumerate}
\end{proposition}

\begin{proposition}[Root Test for Integrals]\label{analysis-unit-0189}
    \label{prop:int-test-root}%
    Let \(\functiondomain{f}{\cointv{a}{\plusinfty}}{\RR}\) be non-negative and integrable on \(\ccintv{a}{R}\) for any \(R \geq a\), and suppose the limit
    \[
        L = \lim_{x \to \plusinfty} f\pqty{x}^{\frac{1}{x}}
    \]
    exists. Considering the improper integral
    \[
        \int_{a}^{\plusinfty} f\pqty{x} \dd{x},
    \]
    \begin{itemize}
        \item if \(L < 1\), the improper integral converges; 
        \item if \(L > 1\), the improper integral diverges.
    \end{itemize}
\end{proposition}

\begin{remark}\label{analysis-unit-0190}
    When \(L = 1\), this test is inconclusive. A divergent case may be given by \(f\pqty{x} = 1\). A convergent case may be given by \(f\pqty{x} = \frac{1}{x^2}\) (its convergence can be shown by direct integration). As for the limit, we have
    \begin{align*}
        \lim_{x \to \plusinfty} \pqty{\frac{1}{x^2}}^{\flatfrac{1}{x}} &= \lim_{x \to \plusinfty} x^{- \flatfrac{2}{x}} \\
        &= \lim_{x \to \plusinfty} \exp\pqty{- 2 \cdot \frac{\log x}{x}} \\
        &= \exp\pqty{-2 \lim_{x \to \plusinfty} \frac{\log x}{x}} \\
        &= \exp\pqty{-2 \lim_{x \to \plusinfty} \frac{\flatfrac{1}{x}}{1}} \\
        &= \exp\pqty{-2 \cdot 0} \\
        &= 1
    \end{align*}
    by applying l'H\^{o}pital's rule.
\end{remark}

\begin{proof}
    This is a direct consequence of \autoref{prop:cauchy-criteria-funciton-limit-infinity} (Cauchy Criteria for Function Limit at Infinity).
\end{proof}

\begin{proof}[\proofname\ using \autoref{prop:int-cauchy} (Cauchy)]
    We define the indefinite integrals similarly as above, and using integration by parts (identically), we have
    \begin{align*}
        H\pqty{x} &= \int_{m}^{n} F'\pqty{t} g\pqty{t} \dd{t} \\
        &= F\pqty{n} g\pqty{n} - F\pqty{m} g\pqty{m} - \int_{m}^{n} F\pqty{t} g'\pqty{t} \dd{t}
    \end{align*}
    for all \(a \leq m \leq n\). Let \(M = \sup_{x \geq a} \abs{F\pqty{x}}\). We suppose \(g\) is positive and decreasing (the increasing case can be dealt with similarly). Taking absolute values, we have
    \begin{align*}
        \abs{\int_{m}^{n} F'\pqty{t} g\pqty{t} \dd{t}} &\leq M g\pqty{n} + M g\pqty{m} + \int_{m}^{n} M \cdot \pqty{- g'\pqty{t}} \dd{t} \\
        &= M \bqty{g\pqty{n} + g\pqty{m} + \int_{m}^{n} \pqty{- g'\pqty{t}} \dd{t}} \\
        &= M \bqty{g\pqty{n} + g\pqty{m} + \pqty{g\pqty{m} - g\pqty{n}}} \\
        &= 2 M g\pqty{m}.
    \end{align*}

    Let \(\epsilon > 0\) be arbitrary. Since \(g\pqty{n} \to 0\), we have some \(R \in \NN\) such that \(\abs{g\pqty{n}} < \frac{\epsilon}{2M}\) for all \(n \geq R\). Then, for all \(R \leq m \leq n\), we have
    \[
        \abs{\int_{m}^{n} F'\pqty{t} g\pqty{t} \dd{t}} \leq 2M g\pqty{m} < \epsilon,
    \]
    and this shows that the integrals over bounded domains are Cauchy, hence convergent.
\end{proof}

\begin{examples}[Improper Integrals over Isolated Singularity]\label{analysis-unit-0196}
    \label{ex:improper-integral-isolated-singularity}%
    \begin{itemize}
        \item We investigate the convergence of the improper integral \(\int_{0}^{1} \frac{1}{x^p} \dd{x}\) for \(p > 0\). Note that
        \[
            \int_{\delta}^{1} \frac{1}{x^p} \dd{x} = \begin{cases}
                \log 1 - \log \delta, & p = 1, \\
                \frac{1-\delta^{1-p}}{1-p}, & p\ne1.
            \end{cases}
        \]

        So this integral converges if and only if \(p < 1\).

        \item We have, using the substitution \(u = \log\pqty{\flatfrac{1}{x}}\), that
        \[
            \int_{0}^{\frac12}\frac{\dd{x}}{x[\log(1/x)]^p} = \int_{\plusinfty}^{\log 2} \pqty{- \frac{1}{u^p}} \dd{u} = \int_{\log 2}^{\plusinfty} \frac{1}{u^p} \dd{u}
        \]
        converges if and only if \(p > 1\).
    \end{itemize}
\end{examples}

\begin{definition}[Sequence of Functions]\label{analysis-unit-0198}
    \label{def:seq-of-fn}%
    We say \(\pqty{f_n}_{n \in \NN} = \pqty{f_1, f_2, \ldots}\) is a \emph{sequence of \(\CC\)-valued functions on \(X \subseteq \CC\)}, if we have \(\functiondomain{f_n}{X}{\CC}\) for each \(n \in \NN\).
\end{definition}

\begin{definition}[Pointwise Convergence]\label{analysis-unit-0199}
    \label{def:pointwise-convergence}%
    If, for any \(x \in Y \subseteq X \subseteq \CC\), the numerical sequence \(\pqty{f_n \pqty{x}}_{n}\) converges, then we say the sequence \emph{pointwise converges} on \(Y\) to the function
    \[
        \function{f}{Y}{\CC}{x}{\lim_{n \to \infty} f_n \pqty{x},}
    \]
    and we say \(f_n \to f\) pointwise on \(Y\).
\end{definition}

\begin{lemma}[Convergence at one Point implies Absolute Convergence in Smaller Radius]\label{analysis-unit-0203}
    \label{lem:convergence-one-point-implies-convergence-smaller-radius}%
    If the power series
    \[
        \sum_{n = 0}^{\infty} c_n \pqty{x - a}^{n}
    \]
    converges for some \(x\), and we have \(\abs{y - a} < \abs{x - a}\), then the series
    \[
        \sum_{n = 0}^{\infty} c_n \pqty{y - a}^{n}
    \]
    converges absolutely.
\end{lemma}

\begin{proposition}[Existence of Radius of Convergence]\label{analysis-unit-0204}
    \label{prop:existence-radius-convergence}%
    Let \(\sum_{n = 0}^{\infty} c_n \pqty{x - a}^{n}\) be a power series. Then there is some \(R \in \ccintv{0}{\plusinfty}\), which is known as the \emph{radius of convergence} of the power series, such that
    \begin{itemize}
        \item the series converges absolutely for \(\abs{x - a} < R\); and
        \item the series diverges for \(\abs{x - a} > R\).
    \end{itemize}
\end{proposition}

\begin{remark}\label{analysis-unit-0205}
    On the circle \(\abs{x - a} = R\) on the complex plane (or two points in \(\RR\)), we do not claim any behaviour on the convergence/divergence of those points -- it may diverge, converge absolutely, or converge conditionally on different points on the circle.
\end{remark}

\begin{example}[Differentiating Power Series Term-by-Term]\label{analysis-unit-0211}
    \label{ex:differentiating-power-series-term-by-term}%
    \begin{itemize}
        \item The power series \(\sum_{n = 0}^{\infty} \frac{x^n}{n!}\) converges on all of \(\CC\). Then we have
        \[
            \sum_{n = 0}^{\infty} \frac{1}{n!} \dv{x} \pqty{x^n} = \sum_{n = 1}^{\infty} \frac{x^{n - 1}}{\pqty{n - 1}!} = \sum_{n = 0}^{\infty} \frac{x^n}{n!}
        \]
        convergences on \(\CC\).

        \item The power series \(\sum_{n = 1}^{\infty} \frac{x^n}{n^2}\) converges on the unit closed disk. Differentiating term-by-term, we have
        \[
            \sum_{n = 1}^{\infty} \frac{1}{n^2} \dv{x} \pqty{x^n} = \sum_{n = 1}^{\infty} \frac{x^{n - 1}}{n}.
        \]

        Although this has the same radius of convergence (which is \(1\)), it does not converge on the whole of the \emph{closed} unit disk -- but it does converge on the open unit disk.
    \end{itemize}
\end{example}

\begin{proposition}[Continuity of Power Series]\label{analysis-unit-0213}
    \label{prop:continuity-of-power-series}%
    Let
    \[
        \sum_{n = 0}^{\infty} c_n \pqty{x - a}^{n}
    \]
    be a power series with a non-zero radius of convergence \(R > 0\). Then the function
    \[
        \function{f}{B_R \pqty{a}}{\CC}{x}{\sum_{n = 0}^{\infty} c_n \pqty{x - a}^n}
    \]
    is continuous on \(D_r(a)\) for every \(0<r<R\). In particular, it is continuous on the whole open disk \(B_R(a)\).
\end{proposition}

\begin{proof}[\proofname\ (Supplementary, Using Integrability, Real Power Series)]
    We let \(g\) be the series we claim to be the derivative. If \(g\) has radius of convergence at least \(R\), then \(g\) is continuous on \(\ccintv{a - r}{a + r}\) for all \(r < R\) by \autoref{prop:continuity-of-power-series} (Continuity of Power Series), and using \autoref{prop:integrability-of-power-series-term-by-term} (Integrability of Power Series), we have
    \[
        \int_{a}^{x} g\pqty{t} \dd{t} = \sum_{n = 1}^{\infty} n c_n \frac{\pqty{x - a}^{n}}{n} = f\pqty{x} - c_0.
    \]

    Hence, \autoref{thm:ftc-1} (Fundamental Theorem of Calculus), we have
    \[
        f'\pqty{x} = g\pqty{x}
    \]
    for all \(x \in \ccintv{a - r}{a + r}\) for all \(r < R\), and hence
    \[
        f'\pqty{x} = g\pqty{x}
    \]
    for all \(x \in \oointv{a - R}{a + R}\).

    Now, it remains to show that the new series has radius of convergence at least \(R\). Take \(r < R\), and let \(s \in \oointv{r}{R}\). We have
    \begin{align*}
        \abs{n c_n \pqty{x - a}^{n - 1}} &= \abs{c_n} s^n \frac{n}{s} \pqty{\frac{\abs{x - a}}{s}}^{n - 1} \\
        &\leq \abs{c_n} s^n \frac{n}{s} \pqty{\frac{r}{s}}^{n - 1}
    \end{align*}
    for all \(\abs{x - a} < r\). Since \(s < R\), \(\abs{c_n} s^n \to 0\), and in particular, \(\abs{c_n} s^n\) is bounded. Hence,
    \[
        \sum_{n = 1}^{\infty} M \frac{n}{s} \pqty{\frac{r}{s}}^{n - 1}
    \]
    converges based on the assumption \(\frac{r}{s} < 1\). Hence, the series
    \[
        \sum_{n = 1}^{\infty} n c_n \pqty{x - a}^{n - 1}
    \]
    converges also in \(\abs{x - a} < r\), for all \(r < R\).
\end{proof}

\begin{definition}[Exponential Function]\label{analysis-unit-0217}
    \label{def:exponential-function}%
    We define the \emph{exponential function}, denoted as \(\exp\), as
    \[
        \function{\exp}{\CC}{\CC}{z}{\sum_{n = 0}^{\infty} \frac{z^n}{n!}.}
    \]
\end{definition}

\begin{remarks}\label{analysis-unit-0218}
    This definition of the exponential agrees with our high-school understanding of \(e^x\) in the following ways.
    \begin{itemize}
        \item Since \(e^x\) differentiates to \(e^x\), evaluating the derivatives at \(x = 0\) tells us that the Taylor series would be equal to
        \[
            \sum_{n = 0}^{\infty} \frac{z^n}{n!}
        \]
        which agrees with our definition of \(\exp\).

        \item Using \autoref{thm:taylor-thm-langrange-remainder} (Taylor's Theorem) with Lagrange's Remainder, we may evaluate the remainder term as
        \[
            R_{n, 0} \pqty{x} = \frac{e^c x^n}{n!}
        \]
        for some \(c \in \ccintv{0}{x}\). Hence,
        \[
            \abs{R_{n, 0} \pqty{x}} = \abs{e^c} \frac{\abs{x}^n}{n!} \to 0
        \]
        as \(n \to \infty\). Hence,
        \[
            e^x = \sum_{n = 0}^{\infty} \frac{x^n}{n!}
        \]
        for all real number \(x \in \RR\).
    \end{itemize}
\end{remarks}

\begin{lemma}[Properties of Exponential Function]\label{analysis-unit-0219}
    \label{lem:properties-exp}%
    We have
    \begin{itemize}
        \item \(\exp\) is smooth, with \(\exp'\pqty{z} = \exp\pqty{z}\);
        \item \(\exp\pqty{0} = 1\); and
        \item \(\exp\pqty{a + b} = \exp\pqty{a} \cdot \exp\pqty{b}\).
    \end{itemize}
\end{lemma}

