        \item \emph{Associativity.} For all \(a, b, c \in G\), we have \(\pqty{a \cdot b} \cdot c = a \cdot \pqty{b \cdot c}\);
        \item \emph{Identity.} For all \(a \in G\), we have \(e \cdot a = a \cdot e = a\);
        \item \emph{Inverses.} For all \(a \in G\), there exists \(a \inverse \in G\), such that \(a \cdot a \inverse = a \inverse \cdot a = e\).
    \end{itemize}

    The size of \(G\) is called the \emph{order} of \(\pqty{G, \cdot, e}\), written by \(\abs{G}\).
\end{definition}

\begin{proof}
    Left as an exercise. Outline: let \(a \in G\) have inverses \(x, y \in G\), and we expand \(x \cdot a \cdot y\) in different ways.
\end{proof}

\begin{definition}[Subgroup]
    \label{def:subgroup}%
    If \(G\) is a group, and \(H \subseteq G\) is a subset of \(G\), then we say \(H\) is a \emph{subgroup} of \(G\), if the following three conditions hold:
    \begin{itemize}
        \item \emph{Identity.} \(e \in H\);
        \item \emph{Closure.} For any \(a, b \in H\), we have \(a \cdot b \in H\).
        \item \emph{Inverses.} For every \(h\in H\), its inverse \(h^{-1}\) belongs to \(H\).
    \end{itemize}
\end{definition}

\begin{proof}
    Left as an exercise.
\end{proof}

\begin{remark}
    For \(H \normalsub G\), observe that
    \[
        \function{q_H}{G}{\flatfrac{G}{H}}{g}{gH}
    \]
    is a homomorphism.
\end{remark}

\begin{proof}
    We have already shown the normality part previously.

    We first show \(\phi\) is well-defined. Indeed, if \(g \ker f = g' \ker f\), then \(g' g\inverse \in \ker \pqty{f}\), so \(f\pqty{g' g\inverse} = e\). This gives \(f\pqty{g} = f\pqty{g'}\).

    For the surjectivity of \(\phi\), let \(h \in \img \pqty{f}\), then \(h = f \pqty{g}\) for some \(g \in G\), and hence \(h = \phi\pqty{g \ker f}\).

    For the injectivity of \(\phi\), if \(\phi\pqty{g \ker f} = \phi\pqty{g' \ker f}\), then \(f\pqty{g} = f\pqty{g'}\), which shows that \(g' g\inverse \in \ker f\). So \(g \ker f = g' \ker f\) and this gives injectivity.
\end{proof}

\begin{proof}
    If \(G \isomorphic C_p\), then any non-identity element generates \(G\) (by \autoref{thm:lagrange} (Lagrange's Theorem)). So \(G\) is simple.

    Conversely, if \(G\) is simple and abelian, take \(g \in G\) which is not in the identity. We look at the subgroup generated by \(g\), which is
    \[
        \angBrac{g} = \set{g^n}{n \in \ZZ}
    \]

    This is a subgroup of \(G\), and since \(G\) is abelian, the normality is automatic. Therefore, this subgroup must be \(G\) itself.

    If \(G\) is an infinite cyclic group, then \(G \isomorphic \ZZ\) which is not simple, for example \(2\ZZ \subgroup \ZZ\).

    If \(G\) is finite of order \(n\), say \(G \isomorphic C_m\). If \(q \divides m\) for any \(q\), take the subgroup generated by \(g^{\frac{m}{q}}\), where \(g\) generates \(G\). Normality is then automatic. Therefore, \(q = 1\) or \(m\) by simplicity, so \(m\) is prime.
\end{proof}

\begin{theorem}
    \label{thm:infinite-chain-normal-subgroup}%
    Let \(G\) be a finite group. Then there exist subgroups
    \[
        G = H_1 \normalsup H_2 \normalsup H_3 \normalsup \cdots \normalsup H_n = \Bqty{e}
    \]
    such that \(\flatfrac{H_i}{H_{i + 1}}\) is simple.
\end{theorem}

\begin{remark}
    We also have another infinite class of finite simple groups, that \(A_m\) for \(m \geq 5\) are all simple. We will prove this shortly.
\end{remark}

\begin{definition}[Sign of Permutation]
    \label{def:sign-of-permutation}%
    The \emph{sign} of a permutation is defined as
    \[
        \function{\sign}{S_n}{\Bqty{\pm 1}}{\sigma}{\sign\pqty{\sigma} = \begin{cases}
            1, & \sigma \text{ is a product of an even number of transpositions}, \\
            -1, & \sigma \text{ is a product of an odd number of transpositions}.
        \end{cases}}
    \]
\end{definition}

\begin{definition}[Action]
    An \emph{action} of a group \(G\) on a set \(X\) is a function
    \[
        \function{\alpha}{G \times X}{X}{\pqty{g, x}}{g \ast x}
    \]
    satisfying
    \begin{itemize}
        \item \(e \ast x = x\) for all \(x \in X\);
        \item \(\pqty{g_1 \cdot g_2} \ast x = g_1 \ast \pqty{g_2 \ast x}\) for all \(g_1, g_2 \in G\) and all \(x \in X\).
    \end{itemize}
\end{definition}

We denote this as \(G \actson X\).

Now, we think of the relation between
\[
    H = \Bqty{\text{Homomorphisms } G \to \Sym\pqty{X}} \qand \Bqty{\text{Actions } G \actson X} = A.
\]

These are just sets. But we are going to define some relationship between them. Let
\[
    \function{a}{H}{A}{
        \functiondomain{f}{G}{\Sym\pqty{X}}}{
            \function{a\pqty{\phi}}{G\times X}{X}{\pqty{g, x}}{\pqty{\phi\pqty{g}}\pqty{x}.}
        }
\]

Note that \(a\pqty{\phi}\) is a group action by the homomorphism property, so this is a well-defined map.

