\begin{definition}[Ring]

 A ring is a quintuple \(\pqty{R, +, \cdot, 0_R, 1_R}\) where \(R\) is a set, \(0_R, 1_R \in R\), and
 \begin{align*}
 \functiondomain{+&}{R \times R}{R} && ``addition'' \\
 \functiondomain{\cdot&}{R \times R}{R}, && ``multiplication''
 \end{align*}
 such that
 \begin{itemize}
 \item \(\pqty{R, +, 0_R}\) is an abelian group;
 \item the operation \(\cdot\) is associative: for all \(a, b, c \in R\), \(a \cdot \pqty{b \cdot c} = \pqty{a \cdot b} \cdot c\);
 \item \(1_R\) is a multiplicative identity for \(R\): for all \(a \in R\), \(1_R \cdot a = a \cdot 1_R = a\);
 \item multiplication is distributive over addition: for all \(r_1, r_2, r_3 \in R\), \(r_1 \cdot \pqty{r_2 + r_3} = r_1 \cdot r_2 + r_1 \cdot r_3\), and \(\pqty{r_1 + r_2} \cdot r_3 = r_1 \cdot r_3 + r_2 \cdot r_3\).
 \end{itemize}
\end{definition}

