    \label{def:ring}%
    A \emph{ring} is a quintuple \(\pqty{R, +, \cdot, 0_R, 1_R}\) where \(R\) is a set, \(0_R, 1_R \in R\), and
    \begin{align*}
        \functiondomain{+&}{R \times R}{R} && \text{``addition''} \\
        \functiondomain{\cdot&}{R \times R}{R}, && \text{``multiplication''}
    \end{align*}
    such that
    \begin{itemize}
        \item \(\pqty{R, +, 0_R}\) is an abelian group;
        \item the operation \(\cdot\) is associative: for all \(a, b, c \in R\), \(a \cdot \pqty{b \cdot c} = \pqty{a \cdot b} \cdot c\);
        \item \(1_R\) is a multiplicative identity for \(R\): for all \(a \in R\), \(1_R \cdot a = a \cdot 1_R = a\);
        \item multiplication is distributive over addition: for all \(r_1, r_2, r_3 \in R\), \(r_1 \cdot \pqty{r_2 + r_3} = r_1 \cdot r_2 + r_1 \cdot r_3\), and \(\pqty{r_1 + r_2} \cdot r_3 = r_1 \cdot r_3 + r_2 \cdot r_3\).
    \end{itemize}
\end{definition}

\begin{notation}
    We will denote this as ``\(R\) is a ring''. The symbol \(-r\) will mean the additive inverse of \(r\), and note \(r - s = r + \pqty{-s}\).
\end{notation}

\begin{remark}
    In this course, all rings are assumed to \emph{commutative}, that \(r_1 \cdot r_2 = r_2 \cdot r_1\) for all \(r_1, r_2 \in R\).
\end{remark}

\begin{remark}
    Note that \(2 \in \ZZ \subring \QQ\), and \(2\) is a unit in \(\QQ\), but \textbf{not in \(\ZZ\)}. A unit of a ring need not be a unit of a subring containing it. Conversely, a unital inclusion sends units of the subring to units of the larger ring: the inverse already present in the subring is still an inverse in the larger ring.
\end{remark}

\begin{remark}
    For \(f \pqty{x} \in R\bqty{x}\), not only do we get an algebraic object for the polynomial, we also get a function
    \[
        \function{f}{R}{R}{x}{f\pqty{x}}
    \]
    but note that this does \emph{not} give the same information as the algebraic object itself.
\end{remark}

