\begin{definition}[Ring Homomorphism]

 Let \(R\) and \(S\) be rings. A function \(\functiondomain{f}{R}{S}\) is a ring homomorphism if
 \begin{enumerate}
 \item \(f\pqty{r_1 + r_2} = f\pqty{r_1} + f\pqty{r_2}\);
 \item \(f\pqty{0} = 0\);
 \item \(f\pqty{r_1 r_2} = f\pqty{r_1} f\pqty{r_2}\);
 \item \(f\pqty{1} = 1\).
 \end{enumerate}
\end{definition}

