\begin{definition}[Unique Factorisation Domain]
    \label{def:ufd}%
    An integral domain \(R\) is a \emph{unique factorisation domain} (UFD) if:
    \begin{enumerate}
        \item Every non-unit in \(R\) is a product of (finitely many) irreducibles.
        \item If \(p_1 \cdot \cdots p_n = q_1 \cdot \cdots q_m\), with all \(p_i\) and \(q_j\)s are irreducible, then \(n = m\), and after some possible re-ordering, we have \(p_i\) and \(q_i\) are associates for all \(i\).
    \end{enumerate}
\end{definition}

\begin{remark}
    In any UFD, irreducibles implies primes. This follows from the factorisation.
\end{remark}

Recall that is \(K\) is a field, then \(K\bqty{x}\) is Euclidean (recall \autoref{prop:euclidean-algorithm-polynomials}). Therefore, we have
\begin{itemize}
    \item any ideal \(I \idealsub K\bqty{x}\) is principal (so \(I = \pqty{f}\)), by \autoref{prop:euclidean-pid};
    \item \(f \in K\bqty{x}\) is irreducible if and only if it is prime, by \autoref{lem:irreducible-primes-pid} and \autoref{prop:primes-are-irreducible};
    \item let \(f\) be irreducible, and we consider \(\pqty{f} \idealsub K\bqty{x}\). Suppose \(\pqty{f} \subseteq J \idealsub k\bqty{x}\), then \(J = \pqty{g}\), so \(f = gh\). But either \(g\) and \(f\) are associates, or \(g\) is a unit. So \(\pqty{f}\) must be maximal. In fact, this is true for all PIDs.
\end{itemize}

In particular, for \(f \in K\bqty{x}\),
\[
    f \text{ is irreducible} \iff \flatfrac{K\bqty{x}}{\pqty{f}} \text{ is a field}.
\]

\begin{remark}
    For example, in \(\pqty{2x + 2} \in \ZZ\bqty{x}\) is \emph{not} primitive, since \(\gcd\Bqty{2, 2} = 2\) is not a unit, and is reducible. However, \(\pqty{2x + 2} \in \QQ\bqty{x}\) \emph{is} primitive, but is irreducible.
\end{remark}

\begin{lemma}[Gauss's Lemma on Primitivity]
    \label{lem:gauss-lemma-primitive}
    Let \(R\) be a UFD, and \(f, g \in R\bqty{x}\). If \(f\) and \(g\) are primitive, then \(fg\) is primitive.
\end{lemma}

