\begin{theorem}[Hilbert Basis Theorem]
    If \(R\) is noetherian, then \(R\bqty{x}\) is noetherian.
\end{theorem}

\begin{proof}
    Let \(J \idealsub \flatfrac{R}{I}\), and let \(J' \idealsub \flatfrac{R}{I}\) be the corresponding ideal in \(R\). If \(r_1, \ldots, r_m\) generates \(J'\), then because \(J\) is the image (as a set) of \(J'\) under the homomorphism \(R \to \flatfrac{R}{I}\), then \(r_1 + I, \ldots, r_m + I\) must generate \(J\).
\end{proof}

\begin{remark}
    Although \autoref{prop:quotient-noetherian-by-ideal-noetherian} tells us that noetherian properties pass to quotients by ideals, but note that \textbf{subrings need not be noetherian}. Take \(R = \CC\bqty{x_1, x_2, \ldots}\) be a polynomial ring of countably many variables. Let \(F\) be a fraction field of \(R\). \(F\) is noetherian, but \(R \subring F\) is not.
\end{remark}

\begin{example*}[\(k\)-Vector Space as a \(k\bqty{x}\)-Module]
    Let \(V\) be a \(k\)-vector space, and we fix \(\alpha \in \End\pqty{V}\) be an endomorphism of \(V\), i.e., a linear map \(\functiondomain{\alpha}{V}{V}\). We can make \(V\) into a \(k\bqty{x}\)-module as follows
    \[
        \function{\cdot_{\alpha}}{k\bqty{x} \times V}{V}{\pqty{f, \vb{v}}}{\pqty{f\pqty{\alpha} \vb{v}}.}
    \]
\end{example*}

