\begin{proposition}[Basis, Linear Independence, and Unique Linear Combination]

 Let \(S = \Bqty{m_1, \ldots, m_k} \subseteq M\). Then, the following are equivalent:
 \begin{enumerate}
 \item \(S\) generates \(M\) freely;
 \item \(S\) generates \(M\), and \(S\) is linearly independent;
 \item every \(m \in M\) is uniquely expressible as ab \(R\)-linear combination
 \[
 m = \sum_{i = 1}^{k} r_i m_i.
 \]
 \end{enumerate}
\end{proposition}

