\begin{definition}[Reflective, Symmetric, Transitive]
 A relation \(R\) on a set \(X\) is
 \begin{itemize}
 \item reflexive, if \(xRx\) for all \(x \in X\);
 \item symmetric, if \(xRy \implies yRx\) for all \(x, y \in X\);
 \item transitive if \(\pqty{aRb} \land \pqty{bRc} \implies aRc\) for all \(a, b, c \in X\).
 \end{itemize}
\end{definition}

