\begin{definition}[Commutative, Associative]
    Let \(\ast\) be a binary operation on a set \(A\).
    \begin{itemize}
        \item If for all \(x, y \in A\), we have \(x \ast y = y \ast x\), then we say \(\ast\) is \emph{commutative}.
        \item If for all \(x, y, z \in A\), we have \(x \ast \pqty{y \ast z} = \pqty{x \ast y} \ast z\), then we say \(\ast\) is \emph{associative}.
    \end{itemize}
\end{definition}

\begin{definition}[Distributive]
    Let \(\ast\) and \(\odot\) be binary operations on \(A\). We say \emph{\(\ast\) is distributive over \(\odot\)} if for all \(x, y, z \in A\), we have
    \begin{align*}
        x \ast \pqty{y \odot z} &= \pqty{x \ast y} \odot \pqty{x \ast z}, \\
        \pqty{y \odot z} \ast x &= \pqty{y \ast x} \odot \pqty{z \ast x}.
    \end{align*}
\end{definition}

\begin{remark}
    The first line is called \emph{left distributivity}, and the second line is \emph{right distributivity}.
\end{remark}

\begin{example}[Distributivity]
    Multiplication \(\times\) is \emph{distributive} over addition \(+\).
\end{example}

\begin{definition}[The Natural Numbers, \(\NN\)]
    The \emph{natural numbers} \(\NN\) is a set containing a special element \(1 \in \NN\), together with a \emph{successor function} (intuitively, \(+ 1\)) \(\functiondomain{s}{\NN}{\NN}\), such that:
    \begin{enumerate}
        \item For all \(n \in \NN\), \(s \pqty{n} \neq 1\). (\(1\) is not the successor of any element.)
        \item For all \(m, n \in \NN\), if \(s\pqty{m} = s\pqty{n}\), then \(m = n\). (The successor function is injective.)
        \item Let \(A \subseteq \NN\) such that \(1 \in A\), and if \(n \in A\) then \(s\pqty{n} \in A\). Then \(A = \NN\).
    \end{enumerate}

    These are the \emph{Peano Axioms}, and specifically (iii) is the \emph{Axiom of Induction}.
\end{definition}

\begin{definition}[Addition and Multiplication on \(\NN\)]
    We define \(\functiondomain{+}{\NN \times \NN}{\NN}\) recursively (on the second element) by
    \begin{itemize}
        \item \(n + 1 = s\pqty{n}\), and
        \item \(n + s\pqty{m} = s\pqty{n + m}\).
    \end{itemize}

    Similarly, we define \(\functiondomain{\cdot}{\NN \times \NN}{\NN}\) recursively by
    \begin{itemize}
        \item \(n \cdot 1 = n\), and
        \item \(n \cdot s\pqty{m} = n \cdot m + n\).
    \end{itemize}
\end{definition}

We may show by induction that these operations satisfy the usual rules of arithmetics, that
\begin{itemize}
    \item \(+\) and \(\cdot\) are commutative and associative; and
    \item \(\cdot\) is distributive over \(+\).
\end{itemize}

\begin{example}[\(1 + 2 = 2 + 1\)]
    As an example, we have
    \begin{align*}
        1 + 2 &= 1 + s\pqty{1} \\
        &= s\pqty{1 + 1} \\
        &= s\pqty{s\pqty{1}} \\
        &= s\pqty{1} + 1 \\
        &= 2 + 1.
    \end{align*}
\end{example}

\begin{definition}[Ordering on \(\NN\)]
    We may define an \emph{ordering} on \(\NN\) as follows: for any \(m, n \in \NN\), if there is some \(k \in \NN\) such that \(m + k = n\), then \(m < n\).
\end{definition}

\begin{proposition}[\(<\) is a strict total order on \(\NN\)]
    For \(m, n \in \NN\), exactly one of \(m = n\), \(m < n\) and \(m > n\) holds.
\end{proposition}

\begin{theorem}[SPI Implies WOP]
    The Strong Principle of Induction implies the Well--Ordering Principle.
\end{theorem}

\begin{claim}[Fundamental Theorem of Arithmetic]
    Any natural number \(> 1\) can be written as a product of primes.
\end{claim}

\begin{proposition}[Size of Power Set]
    A set of size \(n\) has exactly \(2^n\) subsets.
\end{proposition}

\begin{examples}[Examples of Binomial Coefficients]
    \begin{enumerate}
        \item We have \(\binom{4}{2} = 6\), since the size-\(2\) subsets of \(\Bqty{1, 2, 3, 4}\) are
        \[
            \Bqty{1, 2}, \Bqty{1, 3}, \Bqty{1, 4}, \Bqty{2, 3}, \Bqty{2, 4}, \Bqty{3, 4}.
        \]

        \item We have \(\binom{n}{0} = \binom{n}{n} = 1\), since the only subset of size \(0\) is \(\emptyset\), and the only subset of size \(n\) is the set itself.
        \item We have \(\binom{n}{1} = n\) for \(n > 0\), since the size-\(1\) subsets are precisely the sets containing one element.
    \end{enumerate}
\end{examples}

The formula allows to approximate the binomial coefficient for big \(n\). For example, for \(n \gg 1\), we have
\begin{align*}
    \binom{n}{2} &= \frac{n \pqty{n - 1}}{2!} \sim \frac{n^2}{2}, \\
    \binom{n}{3} &= \frac{n \pqty{n - 1} \pqty{n - 2}}{3!} \sim \frac{n^3}{6}.
\end{align*}

\begin{proof}[\proofname\ by counting elements]
    Let \(x \in S_1 \cup \cdots \cup S_n\), and say \(x \in S_i\) for exactly \(k\) of \(S_i\). We aim to show that \(x\) gets counted exactly once on the right-hand side.

    Indeed,
    \begin{align*}
        \abs{\set{A}{\abs{A} = 1 \land x \in S_A}} &= k, \\
        \abs{\set{A}{\abs{A} = 2 \land x \in S_A}} &= \binom{k}{2},
    \end{align*}
    and in general,
    \[
        \abs{\set{A}{\abs{A} = r \land x \in S_A}} = \begin{cases}
            \binom{k}{r}, & 1 \leq r \leq k, \\ 0, & r > k.
        \end{cases}
    \]

    Hence, the number of times \(x\) is counted on the right-hand side is
    \begin{align*}
        & \phantom{=} k - \binom{k}{2} + \binom{k}{3} - \cdots + \pqty{-1}^{k + 1} \binom{k}{k} \\
        &= 1 - \pqty{1 - k + \binom{k}{2} - \binom{k}{3} + \cdots + \pqty{-1}^{k} \binom{k}{k}} \\
        &= 1 - \pqty{1 - 1}^k \\
        &= 1 - 0^k \\
        &= 1
    \end{align*}
    for \(k \geq 1\).
\end{proof}

\begin{definition}[Proper Factors]
    For any \(b \in \ZZ\), \(\pqty{\pm 1}\) and \(\pqty{\pm b}\) are always factors of \(b\). We call those the \emph{trivial factors} of \(b\), and the rest \emph{proper/non-trivial factors}.
\end{definition}

\begin{definition}[Prime, Composite]
    A natural number \(n \geq 2\) is \emph{prime} if its only divisors are trivial. Otherwise, we say \(n\) is \emph{composite}.
\end{definition}

\begin{proposition}[Fundamental Theorem of Arithmetics, Part 1]
    Every natural number \(\geq 2\) can be written as a product of primes.
\end{proposition}

\begin{theorem}[Infinitely Many Primes]
    There are infinitely many primes.
\end{theorem}

\begin{proposition}[Euclid's Lemma]
    If \(p\) is prime and \(p \divides ab\), then \(p \divides a\) or \(p \divides b\).
\end{proposition}

\begin{theorem}[Euclid's Algorithm gives the Greatest Common Divisor]
    The output of Euclid's algorithm with input \(a, b\) is \(\gcd\pqty{a, b}\).
\end{theorem}

\begin{proof}
    We show that it satisfies the two defining properties of the greatest common divisor.

    \begin{enumerate}
        \item We must have \(r_n \divides r_{n - 1}\), as \(r_{n + 1} = 0\) at step \(n + 1\). Therefore, \(r_N \divides r_{n - 2}\) by step \(n\).

        Hence, inductively, \(r_n \divides r_i\) for \(i = 1, 2, \ldots, n - 1\), and hence \(r_n \divides b\) by step 2, and \(r_n \divides a\) by step 1.

        \item Given any \(d\) such that \(d \divides a\) and \(d \divides b\). From step 1 we see \(d \divides r_1\), and from step 2 we have \(d \divides r_2\).

        Hence, inductively, \(d \divides r_i\) for all \(i = 1, 2, \ldots, n\), and in particular, \(d \divides r_n\).
    \end{enumerate}
\end{proof}

\begin{example}[Greatest Common Divisor of \(87\) and \(52\)]
    Suppose we want to find \(\gcd\pqty{87, 52}\). We run Euclid's Algorithm:
    \begin{align*}
        87 &= 1 \cdot 52 + 35, \\
        52 &= 1 \cdot 35 + 17, \\
        35 &= 2 \cdot 17 + \boxed{1}, \\
        17 &= 17 \cdot \boxed{1},
    \end{align*}
    so \(\gcd\pqty{87, 52} = 1\). Note we may terminate the algorithm one step early, outputting the final non-zero divisor, which is the greatest common divisor.
\end{example}

\begin{definition}[Coprime]
    When \(\gcd\pqty{a, b} = 1\), we say \(a\) and \(b\) are \emph{coprime}.
\end{definition}

