\begin{proposition}[Properties on Units Modulo \(n\)]
    If \(a\) is a unit modulo \(n\), then
    \begin{enumerate}
        \item its inverse is unique modulo \(n\);
        \item if \(ab \equiv ac \pmod{n}\), then \(b \equiv c \pmod{n}\).
    \end{enumerate}
\end{proposition}

\begin{proof}
    \begin{enumerate}
        \item Suppose that there is \(b, b' \in \ZZ_n\) such that
        \[
            ab \equiv ab' \equiv 1 \pmod{n}.
        \]

        Then,
        \[
            b \equiv bab \equiv bab' \equiv b' \pmod{n}.
        \]

        \item We left-multiply both sides by the inverse.
    \end{enumerate}
\end{proof}

