\begin{proposition}[Integers Modulo \(p\) are Invertible]
    Let \(p\) be a prime. Then every \(a \nequiv 0 \pmod{p}\) is a unit modulo \(p\).
\end{proposition}

\begin{proposition}[Integers Coprime to \(n\) are Invertible modulo \(n\)]
    Let \(n \geq 2\) be a natural number. Then \(a\) is a unit modulo \(n\), if and only if \(\gcd\pqty{a, n} = 1\).
\end{proposition}

\begin{proof}
    We have
    \begin{align*}
        \gcd\pqty{a, b} = 1 &\iff \exists x, y \in \ZZ: ax + ny = 1 && \text{B\'{e}zout's Identity} \\
        &\iff \exists x, y \in \ZZ: ax = 1 - ny \\
        &\iff \exists x \in \ZZ: ax \equiv 1 \pmod{n}.
    \end{align*}
\end{proof}

\begin{corollary}[Solution to Congruence involving Unit is Unique]
    If \(\gcd\pqty{a, n} = 1\), then the congruence \(ax \equiv b \pmod{n}\) has a unique solution. In particular, if \(\gcd\pqty{a, n} = 1\), there exists a unique inverse of \(a\) modulo \(n\).
\end{corollary}

\begin{examples}[Solving Congruences]
    \begin{enumerate}
        \item We solve \(7x \equiv 4 \pmod{30}\). Notice \(\gcd\pqty{7, 30} = 1\), so \(7\) is a unit modulo \(30\). We note \(13 \cdot 7 \equiv 1 \pmod{30}\), and hence \(x \equiv 4 \cdot 13 \equiv 22 \pmod{30}\).

        We now explicitly show that there are no other solutions. Suppose \(x'\) is also a solution to \(7 x' \equiv 4 \pmod{30}\), then \(7x \equiv 7x' \pmod{30}\), and hence \(x \equiv x' \pmod{30}\) since \(7\) is a unit modulo \(30\).

        Writing up, we can write this as
        \begin{align*}
            &\phantom{\iff} 7x \equiv 4 \pmod{30} \\
            &\iff 13 \cdot 7x \equiv 13 \cdot 4 \pmod{30} \\
            &\iff x \equiv 22 \pmod{30}.
        \end{align*}

        \item We solve \(10 x \equiv 12 \pmod{34}\). We have
        \begin{align*}
            &\phantom{\iff} 10x \equiv 12 \pmod{34} \\
            &\iff 10x = 12 + 34y && \text{for some } y \in \ZZ \\
            &\iff 5x = 6 + 17y && \text{for some } y \in \ZZ \\
            &\iff 5x \equiv 6 \pmod{17}.
        \end{align*}

        We are back in the previous case, where we solve as before.
    \end{enumerate}
\end{examples}

\begin{example}[Han Xin]
    A famous example is as following.

    "How many soldiers are there in Han Xin's army? If you let them parade in rows of \(3\), then \(2\) are left; if you let them parade in rows of \(4\), then \(1\) is left."

    We may model this as the following system of linear congruences:
    \begin{align*}
        x \equiv 1 \pmod{4} &\implies x \equiv 1, \boxed{5}, 9, 13, \ldots \\
        x \equiv 2 \pmod{3} &\implies x \equiv 2, \boxed{5}, 8, 11, \ldots
    \end{align*}
\end{example}

What about the following system?

\begin{align*}
    x \equiv 1 \pmod{4} &\implies x \equiv 1, 5, 9, 13, \ldots \\
    x \equiv 2 \pmod{6} &\implies x \equiv 2, 8, 14, 20, \ldots
\end{align*}

Here, \(4\) and \(6\) are not coprime, and there are not any solutions.

\begin{theorem}[Chinese Remainder Theorem]
    Let \(m, n\) be coprime, and let \(a, b \in \ZZ\). Then there is a unique solution in \(\ZZ_{mn}\) to the simultaneous congruences
    \begin{align*}
        x &\equiv a \pmod{m}, \\
        x &\equiv b \pmod{n}.
    \end{align*}

    In other words, \(y\) is a solution to the same system of equations if and only if \(x \equiv y \pmod{mn}\).
\end{theorem}

