\begin{examples}[Powers of Integers Modulo \(p\)]
    \begin{enumerate}
        \item Under modulo \(7\), we have
        \[
            2^1 \equiv 2, 2^2 \equiv 4, 2^3 \equiv 1, 2^4 \equiv 2, 2^5 \equiv 4, 2^6 \equiv 1
        \]
        and this repeats.

        \item Under modulo \(11\), we have
        \begin{align*}
            2^1 \equiv 2, 2^2 \equiv 4, & 2^3 \equiv 8, 2^4 \equiv 5, \\
            2^5 \equiv 10, 2^6 \equiv 9, & 2^7 \equiv 7, 2^8 \equiv 3, \\
            2^9 \equiv 6, 2^{10} \equiv 1, & 2^{11} \equiv 2, 2^{12} \equiv 4,
        \end{align*}
        and this repeats.
    \end{enumerate}
\end{examples}

\begin{theorem}[Fermat--Euler Theorem]
    Let \(\gcd\pqty{a, m} = 1\), then we have \(a^{\totient\pqty{m}} \equiv 1 \pmod{m}\).
\end{theorem}

\begin{remark}
    This does not necessarily hold for non-primes: in modulo \(8\),
    \[
        1^2 \equiv 3^2 \equiv 5^2 \equiv 7^2 \equiv 1 \pmod{8}.
    \]
\end{remark}

\begin{proof}
    We have by factorisation
    \begin{align*}
        x^2 \equiv 1 \pmod{p} &\iff x^2 - 1 \equiv 0 \pmod{p} \\
        &\iff \pqty{x + 1} \pqty{x - 1} \equiv 0 \pmod{p}.
    \end{align*}

    Recall that Euclid's Lemma states that \(p \divides ab\) if and only if \(p \divides a\) or \(p \divides b\).

    Equivalently, if \(p\) is prime, then \(ab \equiv 0 \pmod{p}\) if and only if \(a \equiv 0 \pmod{p}\) or \(b \equiv 0 \pmod{p}\).

    Hence,
    \begin{align*}
        x^2 \equiv 1 \pmod{p} &\iff x + 1 \equiv 0 \text{ or } x - 1 \equiv 0 \pmod{p} \\
        &\iff x \equiv -1 \text{ or } x \equiv 1 \pmod{p},
    \end{align*}
    as desired.
\end{proof}

