\begin{remark}
    More generally, a non-zero polynomial of degree \(k\) over \(\ZZ_p\) has \emph{at most} \(k\) roots in \(\ZZ_p\) for any prime \(p\).
\end{remark}

\begin{theorem}[Wilson's Theorem]
    Let \(p\) be a prime. Then \(\pqty{p - 1}! \equiv -1 \pmod{p}\).
\end{theorem}

\begin{proposition}
    Let \(p\) be an odd prime. Then \(-1\) is a square modulo \(p\), if and only if \(p \equiv 1 \pmod{4}\).
\end{proposition}

\begin{remark}
    When \(p \equiv 1 \pmod{4}\), Wilson's theorem gives us \emph{a} solution to \(x^2 \equiv -1 \pmod{p}\), namely \(\pqty{\frac{p - 1}{2}}!\).

    For example, if \(p = 29\), then \(x = 14!\) is a solution.
\end{remark}

\begin{proposition}[Correctness for every message representative]
For every integer $M$, $M^{ed}\equiv M\pmod n$.
\end{proposition}

\begin{proof}
Write $ed=1+k\varphi(n)$ with $k\geq0$. Modulo $p$, if $p\mid M$ then both sides vanish. Otherwise Fermat's theorem gives $M^{p-1}\equiv1\pmod p$, hence $M^{ed}=M(M^{p-1})^{k(q-1)}\equiv M\pmod p$.
The same argument works modulo $q$. Since $p$ and $q$ are distinct primes, the Chinese remainder theorem gives the result modulo $pq$.
\end{proof}

\begin{remark}[Scope of this construction]
This is the deterministic textbook arithmetic of RSA, not a complete secure encryption protocol. In particular, someone who knows that a plaintext is one of two candidates can encrypt both with the public key and compare the results with the ciphertext. Correctness alone therefore does not establish confidentiality.
\end{remark}

\begin{proposition}[Factoring and the totient for a product of two distinct primes]
Given $n=pq$, knowing $p,q$ gives $\varphi(n)$. Conversely, knowing $n$ and $\varphi(n)$ recovers the factors.
\end{proposition}

\begin{proof}
Set $s=n-\varphi(n)+1=p+q$. Then $p,q$ are the roots of $X^2-sX+n$, namely $(s\pm\sqrt{s^2-4n})/2$.
\end{proof}

\begin{proposition}[\(\sqrt{2}\) is irrational]
    There is no rational \(x\) with \(x^2 = 2\).    
\end{proposition}

