\begin{proposition}[Limits Preserve Weak Inequalities]
    If \(a_n \leq d\) for all \(n \in \NN\), and \(a_n \to c\) as \(n \to \infty\), then \(c \leq d\).
\end{proposition}

\begin{proposition}[Limits Preserve Sums]
    If \(a_n \to c\) as \(n \to \infty\), and \(b_n \to d\) as \(n \to \infty\), then \(a_n + b_n \to c + d\) as \(n \to \infty\).
\end{proposition}

\begin{proof}
    The partial sums
    \[
        s_m = \sum_{n = 1}^{m} \frac{d_n}{10^n}
    \]
    are increasing, and they are bounded below (trivially) by \(0\) and above by
    \[
        \sum_{n = 1}^{\infty} \frac{9}{10^n} = \frac{9}{10} \cdot \frac{1}{1 - \frac{1}{10}} = 1.
    \]
\end{proof}

\begin{definition}[Decimal Expansion]
    We say that \(0.d_1 d_2 d_3 \ldots\) is a \emph{decimal expansion} of \(x\).
\end{definition}

\begin{proposition}[Reals in \(\ccintv{0}{1}\) have Decimal Expansions]
    Any real \(x\) with \(0 \leq x \leq 1\) have a decimal expansion.
\end{proposition}

\begin{proposition}[Decimal Expansions are not Unique precisely for Finite Decimals]
    If a number has two decimal expansions
    \[
        0.a_1 a_2 a_3 \ldots = 0.b_1 b_2 b_3 \ldots
    \]
    that are not identical, then there is some \(k\) such that
    \begin{itemize}
        \item \(a_j = b_j\) for \(j < k\);
        \item \(a_j = b_j - 1\) for \(j = k\); and
        \item \(a_j = 9, b_j = 0\) for \(j > k\);
    \end{itemize}
    or reversed (i.e. swapping the \(a\) and \(b\) above).
\end{proposition}

\begin{proposition}[Periodic Decimals are Rational]
    A periodic decimal is rational.
\end{proposition}

\begin{proposition}[Rationals have Periodic Decimal Expansion]
    A rational has a periodic decimal expansion.
\end{proposition}

\begin{proposition}[\(e\) exists]
    The infinite series for \(e\) converges.
\end{proposition}

\begin{notation}
    If we use the convention \(0! = 1\), we have
    \[
        e = \sum_{j = 0}^{\infty} \frac{1}{j!}.
    \]
\end{notation}

\begin{proposition}[Euler, 1740s: \(e\) is irrational]
    \(e\) is irrational.
\end{proposition}

\begin{examples}[Examples of Algebraic Numbers]
    \begin{enumerate}
        \item Every rational number is algebraic, since
        \[
            x = \frac{p}{q} \implies qx - p = 0.
        \]

        \item \(x = \sqrt{2}\) is algebraic since it satisfies \(x^2 - 2 = 0\).
    \end{enumerate}
\end{examples}

\begin{lemma}
    For any polynomial \(p\), there exists a constant \(k\) such that
    \[
        \abs{p\pqty{x} - p\pqty{y}} \leq k \abs{x - y}
    \]
    for all \(0 \leq x, y \leq 1\).
\end{lemma}

\begin{proof}
    Suppose that
    \[
        p\pqty{x} = a_d x^d + a_{d - 1} x^{d - 1} + \cdots + a_1 x + a_0.
    \]

    Then we have
    \begin{align*}
        p\pqty{x} - p\pqty{y} &= a_d \pqty{x^d - y^d} + a_{d - 1} \pqty{x^{d - 1} - y^{d - 1}} + \cdots + a_1 \pqty{x - y} \\
        &= \pqty{x - y} \bqty{a_d \pqty{x^{d - 1} + x^{d - 2} y + \cdots + y^{d - 1}} + \cdots + a_1},
    \end{align*}
    and hence
    \begin{align*}
        \abs{p \pqty{x} - p \pqty{y}} &= \abs{x - y} \abs{a_d \pqty{x^{d - 1} + x^{d - 2} y + \cdots + y^{d - 1}} + \cdots + a_1} \\
        &\leq \abs{x - y} \bqty{\abs{a_d} \cdot d + \abs{a_{d - 1}} \cdot \pqty{d - 1} + \cdots + \abs{a_1}}.
    \end{align*}

    The second term is a constant.
\end{proof}

\begin{lemma}[Corollary of Fundamental Theorem of Algebra]
    A non-zero polynomial of degree \(d\) has at most \(d\) real roots.
\end{lemma}

