\begin{definition}[Complex Numbers, \(\CC\)]
 The complex numbers \(\CC\) consists of \(\RR^2 = \set{\pqty{a, b}}{a, b \in \RR}\) together with operation \(+\) and \(\times\):
 \begin{align*}
 \pqty{a, b} + \pqty{c, d} &= \pqty{a + c, b + d}, \\
 \pqty{a, b} \times \pqty{c, d} &= \pqty{ac - bd, ad + bc}.
 \end{align*}
\end{definition}

