\begin{definition}[Complex Numbers, \(\CC\)]
    The \emph{complex numbers} \(\CC\) consists of \(\RR^2 = \set{\pqty{a, b}}{a, b \in \RR}\) together with operation \(+\) and \(\times\):
    \begin{align*}
        \pqty{a, b} + \pqty{c, d} &= \pqty{a + c, b + d}, \\
        \pqty{a, b} \times \pqty{c, d} &= \pqty{ac - bd, ad + bc}.
    \end{align*}
\end{definition}

\begin{remarks}
    \begin{enumerate}
        \item \(\CC\) obeys all the usual rules of arithmetic, meaning in particular that \(\CC\) is a field. Specifically, for any \(z \in \CC \setminus \Bqty{0}\), then there is some \(w \in \CC\) with \(zw = 1\). Indeed, let \(z = a + ib\), note that
        \[
            \pqty{a + ib} \pqty{a - ib} = a^2 + b^2
        \]
        so
        \[
            \pqty{a + ib} \cdot \frac{a - ib}{a^2 + b^2} = 1.
        \]

        \item Every non-constant polynomial with complex coefficients has a root in \(\CC\). This is known as the \emph{fundamental theorem of algebra}.
    \end{enumerate}
\end{remarks}

\begin{definition}[Countable]
    A set \(X\) is \emph{countable}, if \(X\) satisfies one of the following two conditions:
    \begin{itemize}
        \item \(X\) is finite; or
        \item there is a bijection \(X \to \NN\).
    \end{itemize}

    The second case is called \emph{countably infinite}.
\end{definition}

\begin{lemma}[Subsets of \(\NN\) are Countable]
    Any subset of \(\NN\) is countable.
\end{lemma}

