\begin{theorem}[Countability, Injection and Surjection]
 The following are equivalent:
 \begin{enumerate}
 \item \(X\) is countable;
 \item there is an injection \(X \to \NN\);
 \item \(X = \emptyset\) or there is a surjection \(\NN \to X\).
 \end{enumerate}
\end{theorem}

