\begin{algorithm}[ht!]
 \caption{Newton's Algorithm} 
 \begin{algorithmic}
 \Function{NewtonAlgorithm}{\(f, \vb{x}_0\)}
 \State \(t \gets 0\)
 \Repeat
 \State \(\vb{x}_{t + 1} \gets \vb{x}_t - \pqty{\grad^2 f\pqty{\vb{x}_t}}\inverse \grad f\pqty{\vb{x}_t}\)
