\begin{definition}[Matrix Norm]\label{optim-unit-0020}
    \label{def:matirx-norm}%
    For a matrix \(\vb{A} \in \RR^{n \times n}\), \(\norm{\vb{A}}\) is the smallest \(a \geq 0\), such that
    \[
        \norm[2]{\vb{Az}} \leq a \norm[2]{\vb{z}}
    \]
    for all \(\vb{z} \in \RR^n\), where \(\norm[2]{\cdot}\) denotes the usual \(\ell^2\)-norm on \(\RR^n\). For positive semi-definite matrices \(\vb{A}\), this is simply the largest eigenvalue.
\end{definition}

\begin{example}[Application in Machine Learning]\label{optim-unit-0023}
    Suppose we have data points \(\pqty{x_1, y_1}, \pqty{x_2, y_2}, \ldots, \pqty{x_n, y_n}\). Most machine learning algorithms are trying to minimise
    \[
        \min_{\theta} \sum_{i = 1}^{n} \ell\pqty{f_{\theta} \pqty{x_i}, y_i}
    \]
    where \(\ell\) is a suitable loss function. But we almost always use gradient descent, rather than Newton's method.
\end{example}

\begin{definition}[Lagrangian, Lagrange Multiplier]\label{optim-unit-0024}
    We define the \emph{Lagrangian} as
    \[
        L \pqty{\vb{x}, \vb*{\lambda}} = f\pqty{\vb{x}} - \vb*{\lambda}\transpose \pqty{\vb{h}\pqty{\vb{x}} - \vb{b}}
    \]
    where \(\vb*{\lambda} \in \RR^m\) is the \emph{Lagrange multiplier}.
\end{definition}

