        \EndFor

        \State \textbf{find} \(\vb*{\lambda}^{\ast} \in \Lambda\) \textbf{such that} \(\vb{h} \pqty{\vb{x}} + \vb{s} = \vb{b}\) \textbf{and} \(\vb{s} \geq \vb{0}\)

        \State \Return{\(\vb{x}^{\ast} \pqty{\vb*{\lambda}^{\ast}}\)}

