\begin{definition}[Supporting Hyperplane]\label{optim-unit-0035}
    A function \(\functiondomain{\phi}{\RR^m}{\RR\cup\{+\infty\}}\) is said to have a \emph{supporting hyperplane} at a point \(\vb{b} \in \RR^m\), if there is some \(\vb*{\lambda} \in \RR^m\), such that for all \(\vb{c} \in \RR^m\), we have
    \[
        \phi\pqty{\vb{c}} \geq \phi\pqty{\vb{b}} + \vb*{\lambda}\transpose \pqty{\vb{c} - \vb{b}}.
    \]
\end{definition}

