 \inf_{\vb{x} \in X \pqty{\vb{c}}} f\pqty{\vb{x}} = \phi\pqty{\vb{c}} \qand \forall \vb{x} \in X\pqty{\vb{c}}: \vb{h}\pqty{\vb{x}} - \vb{c} = \vb{0},
