 g\pqty{\vb*{\lambda}} &= \inf_{\vb{c} \in \RR^m} \phi\pqty{\vb{c}} - \vb*{\lambda}\transpose \pqty{\vb{c} - \vb{b}} \\
 &\geq \phi\pqty{\vb{b}}
 \end{align*}
