\begin{theorem}[Convexity of the equality-constrained value function]\label{optim-unit-0039}
If \(\mathcal X\) is convex, \(f\) is convex and \(h\) is affine, then
\(\phi(c)=\inf\{f(x):x\in\mathcal X,h(x)=c\}\) is convex, provided it never takes
value \(-\infty\). An empty feasible set has value \(+\infty\).
\end{theorem}

\begin{remark}\label{optim-unit-0040}
Convex components of \(h\) suffice for the inequality-constrained value function,
not generally for equality constraints. A counterexample is \(\mathcal X=[0,\infty)\), \(f(x)=x\), \(h(x)=x^2\):
\(\phi(c)=\sqrt c\) for \(c\ge0\), which is not convex since
\(\phi(1/2)=1/\sqrt2>1/2=(\phi(0)+\phi(1))/2\).
\end{remark}

\begin{definition}[Linear Program]\label{optim-unit-0041}
    A \emph{linear program} is a constrained optimisation problem where we \textbf{minimise} \(\vb{c}\transpose \vb{x}\), subject to \textbf{constraints} of the form
    \begin{itemize}
        \item \(\vb{a}_i\transpose \vb{x} \geq b_i\), for all \(i \in M_1\),
        \item \(\vb{a}_i\transpose \vb{x} \leq b_i\), for all \(i \in M_2\),
        \item \(\vb{a}_i\transpose \vb{x} = b_i\), for all \(i \in M_3\),
        \item \(x_j \geq 0\), for all \(j \in N_1\),
        \item \(x_j \leq 0\), for all \(j \in N_2\),
        \item \(x_j \in \RR\), for all \(j \in N_3\).
    \end{itemize}

    We denote \(m = \abs{M_1} + \abs{M_2} + \abs{M_3}\) as the \textbf{number of constraints}, and \(n = \abs{N_1} + \abs{N_2} + \abs{N_3}\) as the \textbf{dimension}.
\end{definition}

We may put the constraint vectors into a matrix
\[
    \vb{A} = \pmqty{
        \text{---} & \vb{a}_1\transpose & \text{---} \\
        \text{---} & \vb{a}_2\transpose & \text{---} \\
         & \vdots & \\
        \text{---} & \vb{a}_m\transpose & \text{---}
    }
\]
and we denote its columns as \(\vb{A}_1, \vb{A}_2, \ldots, \vb{A}_n\).

\begin{theorem}[Dual Form of a Linear Program]\label{optim-unit-0042}
    The dual of the linear program defined above is given by maximising \(\vb{b}\transpose \vb*{\lambda}\), subject to the constraints
    \begin{itemize}
        \item \(\lambda_i \geq 0\) for all \(i \in M_1\),
        \item \(\lambda_i \leq 0\) for all \(i \in M_2\),
        \item \(\lambda_i \in \RR\) for all \(i \in M_3\),
        \item \(\vb*{\lambda}\transpose \vb{A}_j \leq c_j\) for all \(j \in N_1\),
        \item \(\vb*{\lambda}\transpose \vb{A}_j \geq c_j\) for all \(j \in N_2\),
        \item \(\vb*{\lambda}\transpose \vb{A}_j = c_j\) for all \(j \in N_3\).
    \end{itemize}
\end{theorem}

\begin{definition}[General Form of a Linear Program]\label{optim-unit-0044}
    The \emph{general form} of a linear program is a linear program re-written as \textbf{minimising} \(\vb{c}\transpose \vb{x}\) subject to a constraint \(\vb{A}\vb{x} \leq \vb{b}\).
\end{definition}

\begin{definition}[Standard Form of a Linear Program]\label{optim-unit-0045}
    The \emph{standard form} of a linear program is a linear program re-written as \textbf{minimising} \(\vb{c}\transpose \vb{x}\) subject to a constraint \(\vb{A}\vb{x} = \vb{b}\) and \(\vb{x} \geq 0\).
\end{definition}

\begin{definition}[Extreme Point in Convex Set]\label{optim-unit-0046}
    A point \(\vb{x} \in C\) where \(C \subseteq \RR^n\) is convex, is called an \emph{extreme point}, if it \emph{cannot} be written as a convex combination of two distinct points in \(C\), i.e., for \(\vb{y}, \vb{z} \in C\) and \(\delta \in \oointv{0}{1}\),
    \[
        \vb{x} = \delta \vb{y} + \pqty{1 - \delta} \vb{z} \implies \vb{x} = \vb{y} = \vb{z}.
    \]
\end{definition}

\begin{proposition}[Convex maximisation over a polytope]\label{optim-unit-0047}
Let \(C\) be a nonempty polytope with vertices \(v_1,\ldots,v_N\), and let
\(f:C\to\RR\) be convex. Then \(\max_C f=\max_i f(v_i)\).
\end{proposition}

\begin{proof}
Write \(x=\sum_i\theta_i v_i\), with \(\theta_i\ge0\), \(\sum_i\theta_i=1\).
Repeated application of convexity gives \(f(x)\le\sum_i\theta_i f(v_i)\le\max_i f(v_i)\).
A vertex attaining the finite maximum proves equality.
\end{proof}

\begin{figure}[ht!]\centering\begin{minipage}{0.94\linewidth}The extreme points of a closed Euclidean disk of positive radius are precisely its boundary circle. Interior points lie between two disk points; a nontrivial convex combination of distinct disk points cannot lie on the boundary, by strict convexity of the squared Euclidean norm.\end{minipage}\caption{Extreme Point of a Circle (mathematical description)}\label{fig:circle-extreme-point}\end{figure}

\begin{figure}[ht!]\centering\begin{minipage}{0.94\linewidth}The extreme points of a nondegenerate closed filled triangle are precisely its three vertices. Every other point is a nontrivial convex combination of vertices.\end{minipage}\caption{Extreme Point of a Triangle (mathematical description)}\label{fig:triangle-extreme-point}\end{figure}

A convex set may have infinitely many extreme points (such as a closed disk, in \autoref{fig:circle-extreme-point}), which does not really help. In linear programs, since the constraints are linear, the regions are polyhedra, possibly unbounded, which means the extreme points are in fact finite (for example, in \autoref{fig:triangle-extreme-point} for a triangle) -- For a standard-form LP with a nonempty feasible set and a finite optimum, an optimal basic feasible solution exists. Arbitrary polyhedra can have no extreme points.

\begin{definition}[Basic Solution, Basic Feasible Solution]\label{optim-unit-0048}
    Under assumption (B), a point \(\vb{x}\in\RR^n\) satisfying \(\vb{Ax}=\vb{b}\) and having at most \(m\) nonzero entries is called a \emph{basic solution}. A basic solution \(\vb{x}\) that satisfies \(\vb{x} \geq \vb{0}\) is called a \emph{basic feasible solution}.
\end{definition}

\begin{definition}[Basic Matrix, Basic Variables]\label{optim-unit-0049}
    We fix a choice of \(\mathcal{B}\). The variables \(x_{\mathcal{B}\pqty{1}}, x_{\mathcal{B}\pqty{2}}, \ldots, x_{\mathcal{B}\pqty{m}}\) are the \emph{basic variables}. The matrix \(\vb{B}\) is the \emph{basic matrix}, and its columns, \(\vb{A}_{\mathcal{B}\pqty{1}}, \vb{A}_{\mathcal{B}\pqty{2}}, \ldots, \vb{A}_{\mathcal{B}\pqty{m}}\), are the \emph{basic columns}.
\end{definition}

\begin{theorem}[Extreme Points of Feasible Set are precisely Basic Feasible Solutions]\label{optim-unit-0050}
    A vector \(\vb{x}\) is a basic feasible solution, if and only if it is an extreme point of the set
    \[
        \mathcal{X} \pqty{\vb{b}} = \set{\vb{x} \in \RR^n}{\vb{Ax} = \vb{b}, \vb{x} \geq 0}.
    \]
\end{theorem}

