        \item list all \(\binom{n}{m}\) basic solutions;
        \item filter out basic feasible solutions (BFS) from this list;
        \item evaluate \(\vb{c}\transpose \vb{x}\) for each BFS and choose the best one.
    \end{itemize}

    But even if \(m \approx \flatfrac{n}{2}\), then the time taken would grow exponentially.
\end{remark}

\begin{definition}[Reduced Costs Vector]\label{optim-unit-0052}
    We define the \emph{vector of reduced costs} as a row vector
    \[
        \bar{\vb{c}}\transpose = \vb{c}\transpose - \vb{c}_{\mathcal{B}}
        \transpose \vb{B}\inverse \vb{A}.
    \]
\end{definition}

\begin{theorem}[Reduced Costs Vector being Non-Negative implies Optimality]\label{optim-unit-0053}
    If for some basic feasible solution \(\vb{x}\) we have \(\bar{\vb{c}} \geq \vb{0}\), then such solution \(\vb{x}\) must be optimal.
\end{theorem}

