Content:
We sit at a basic feasible solution \(\vb{x}\), and we construct a tableau of the form in [REF:tab:simplex-tableau] .

\begin{table}[ht!]
 \centering
 \[\begin{array}{c|c}
 - \vb{c}_{B}\transpose \vb{x}_{B} & \bar{\vb{c}} \\
 \hline
 \vb{B}\inverse \vb{b} & \vb{B}\inverse \vb{A}
 \end{array}
 \equiv
 \begin{array}{c|cccc}
 - \vb{c}_{B}\transpose \vb{x}_{B} & \bar{c}_1 & \bar{c}_2 & \cdots & \bar{c}_n \\
 \hline
 x_{B\pqty{1}} & | & | & & | \\
 \vdots & \vb{B}\inverse \vb{A}_1 & \vb{B}\inverse \vb{A}_2 & \cdots & \vb{B}\inverse \vb{A}_n \\
 x_{B\pqty{m}} & | & | & & |
 \end{array}
 \]
 \caption{Simplex Tableau}

\end{table}

The table keeps track of:
\begin{enumerate}
 \item the current basic feasible solution characterised by \(\vb{x}_{B}\);
 \item the (negative) current cost \(- \vb{c}_{B}\transpose \vb{x}_{B}\);
 \item the possible directions \(\vb{d}_{B}\) given by \(-\vb{B}\inverse \vb{A}_j\); and
 \item the vector of reduced costs \(\bar{c}\).
\end{enumerate}

 [REF:alg:simplex-algorithm] outlines the simplex algorithm after slack variables are introduced and a first basic feasible solution was found (if \(\vb{b} \geq 0\), by simply setting the slack variable components to the components of \(\vb{b}\)). (In this case, \(B\) will be equal to the slack variable components.)

\begin{algorithm}[ht!]
 \caption{Simplex Algorithm} 
 \begin{algorithmic}
 \Function{SimplexAlgorithm}{\(\vb{A} \in \RR^{m \times n}, \vb{b} \in \RR^m, \vb{c} \in \RR^n, \functiondomain{B}{\bqty{m}}{\bqty{n}}\)}
 \LComment{Initialise Table}
 \LComment{Comments give the value where we choose the slack variables as the initial basic components}
 \LComment{In this case, \(B\pqty{1, 2, \ldots, m} = \pqty{n - m + 1, n - m + 2, \ldots, n}\)}
 \State \(\vb{B} \gets \vb{A}_{B}\) \Comment{\(\vb{B} = \identityM\)}
 \State \(\vb{x}_{B} \gets \vb{B}\inverse\vb{b}\) \Comment{\(\vb{x}_{B} = \vb{b}\)}
 \State compute \(\vb{B}\inverse \vb{A}\) \Comment{\(\vb{B}\inverse \vb{A} = \vb{A}\)}
 \State compute \(-\vb{c}_{B}\transpose \vb{x}_{B}\) \Comment{\(-\vb{c}_{B}\transpose \vb{x}_{B} = 0\)}
 \State \(\vb{\bar{c}}\transpose \gets \vb{c}\transpose - \vb{c}_{B}\transpose \vb{B}\inverse \vb{A}\) \Comment{\(\vb{\bar{c}} = \vb{c}\)}

 \Statex

 \While{some reduced cost is negative}
 \State \(j \gets \min_{\bar{c}_j < 0} j\) \Comment{Find the Basic Direction to Proceed}
 \State \(\vb{d} \gets \vb{B}\inverse \vb{A}_j\) \Comment{The Column in the Table}

 \If{no component of \(\vb d\) is positive}\State \Return{unbounded below}\EndIf
\Statex

 \ForAll{\(i \in \bqty{m}, d_i > 0\)}
 \Comment{Find the Step Size to Proceed}

 \State \(r_i \gets \flatfrac{x_{B\pqty{i}}}{d_i}\)
 \EndFor

 \State \(l \gets \argmin_{d_i > 0} r_i\) \Comment{Find Pivot Element}

 \Statex

 \LComment{Using Row Operations to Update Table}
 \State relabel \(x_{B\pqty{l}}\) with \(x_j\)
 \State update \(B\) by replacing \(B\pqty{l} = j\)
 \State divide the \(l\)-th row by \(d_l\) \Comment{This would make the \(j\)-th entry one}
 \Statex
 \ForAll{\(i \in \bqty{m} \cup \Bqty{cost}, i \neq l\)} \Comment{Including the Cost Row}
 \State subtract the \(i\)-th row by \(d_i\) times the \(l\)-th row \Comment{Special Case: \(d_{cost} = \bar{c}_{j}\)}
 \Statex \Comment{This would make the \(j\)-th entry zero}
 \EndFor

 \LComment{The \(j\)-th column should now have precisely one non-zero entry, being one on the \(l\)-th row}

 \EndWhile

 \Statex

 \State \Return{\(\vb{x}\)}
 \EndFunction
 \end{algorithmic}
\end{algorithm}

