We sit at a basic feasible solution \(\vb{x}\), and we construct a tableau of the form in \autoref{tab:simplex-tableau}.

\begin{table}[ht!]
    \centering
    \[\begin{array}{c|c}
        - \vb{c}_{\mathcal{B}}\transpose \vb{x}_{\mathcal{B}} & \bar{\vb{c}} \\
        \hline
        \vb{B}\inverse \vb{b} & \vb{B}\inverse \vb{A}
    \end{array}
    \equiv
    \begin{array}{c|cccc}
        - \vb{c}_{\mathcal{B}}\transpose \vb{x}_{\mathcal{B}} & \bar{c}_1 & \bar{c}_2 & \cdots & \bar{c}_n \\
        \hline
        x_{\mathcal{B}\pqty{1}} & | & | & & | \\
        \vdots & \vb{B}\inverse \vb{A}_1 & \vb{B}\inverse \vb{A}_2 & \cdots & \vb{B}\inverse \vb{A}_n \\
        x_{\mathcal{B}\pqty{m}} & | & | & & |
    \end{array}
    \]
    \caption{Simplex Tableau}
    \label{tab:simplex-tableau}
\end{table}

The table keeps track of:
\begin{enumerate}
    \item the current basic feasible solution characterised by \(\vb{x}_{\mathcal{B}}\);
    \item the (negative) current cost \(- \vb{c}_{\mathcal{B}}\transpose \vb{x}_{\mathcal{B}}\);
    \item the possible directions \(\vb{d}_{\mathcal{B}}\) given by \(-\vb{B}\inverse \vb{A}_j\); and
    \item the vector of reduced costs \(\bar{c}\).
\end{enumerate}

\autoref{alg:simplex-algorithm} outlines the simplex algorithm after slack variables are introduced and a first basic feasible solution was found (if \(\vb{b} \geq 0\), by simply setting the slack variable components to the components of \(\vb{b}\)). (In this case, \(\mathcal{B}\) will be equal to the slack variable components.)

\begin{algorithm}[ht!]
    \caption{Simplex Algorithm}\label{alg:simplex-algorithm}%
    \begin{algorithmic}
        \Function{SimplexAlgorithm}{\(\vb{A} \in \RR^{m \times n}, \vb{b} \in \RR^m, \vb{c} \in \RR^n, \functiondomain{\mathcal{B}}{\bqty{m}}{\bqty{n}}\)}
            \LComment{Initialise Table}
            \LComment{Comments give the value where we choose the slack variables as the initial basic components}
            \LComment{In this case, \(\mathcal{B}\pqty{1, 2, \ldots, m} = \pqty{n - m + 1, n - m + 2, \ldots, n}\)}
            \State \(\vb{B} \gets \vb{A}_{\mathcal{B}}\) \Comment{\(\vb{B} = \identityM\)}
            \State \(\vb{x}_{\mathcal{B}} \gets \vb{B}\inverse\vb{b}\) \Comment{\(\vb{x}_{\mathcal{B}} = \vb{b}\)}
            \State \textbf{compute} \(\vb{B}\inverse \vb{A}\) \Comment{\(\vb{B}\inverse \vb{A} = \vb{A}\)}
            \State \textbf{compute} \(-\vb{c}_{\mathcal{B}}\transpose \vb{x}_{\mathcal{B}}\) \Comment{\(-\vb{c}_{\mathcal{B}}\transpose \vb{x}_{\mathcal{B}} = 0\)}
            \State \(\vb{\bar{c}}\transpose \gets \vb{c}\transpose - \vb{c}_{\mathcal{B}}\transpose \vb{B}\inverse \vb{A}\) \Comment{\(\vb{\bar{c}} = \vb{c}\)}

            \Statex

            \While{some reduced cost is negative}
                \State \(j \gets \min_{\bar{c}_j < 0} j\) \Comment{Find the Basic Direction to Proceed}
                \State \(\vb{d} \gets \vb{B}\inverse \vb{A}_j\) \Comment{The Column in the Table}

                \If{no component of \(\vb d\) is positive}\State \Return{unbounded below}\EndIf
\Statex

                \ForAll{\(i \in \bqty{m}, d_i > 0\)}
                    \Comment{Find the Step Size to Proceed}

                    \State \(r_i \gets \flatfrac{x_{\mathcal{B}\pqty{i}}}{d_i}\)
                \EndFor

                \State \(l \gets \argmin_{d_i > 0} r_i\) \Comment{Find Pivot Element}

                \Statex

                \LComment{Using Row Operations to Update Table}
                \State \textbf{relabel} \(x_{\mathcal{B}\pqty{l}}\) \textbf{with} \(x_j\)
                \State \textbf{update} \(\mathcal{B}\) \textbf{by} replacing \(\mathcal{B}\pqty{l} = j\)
                \State \textbf{divide} the \(l\)-th row \textbf{by} \(d_l\) \Comment{This would make the \(j\)-th entry one}
                \Statex
                \ForAll{\(i \in \bqty{m} \cup \Bqty{\text{cost}}, i \neq l\)}  \Comment{Including the Cost Row}
                    \State \textbf{subtract} the \(i\)-th row \textbf{by} \(d_i\) times the \(l\)-th row \Comment{Special Case: \(d_{\text{cost}} = \bar{c}_{j}\)}
                    \Statex \Comment{This would make the \(j\)-th entry zero}
                \EndFor

                \LComment{The \(j\)-th column should now have precisely one non-zero entry, being one on the \(l\)-th row}

            \EndWhile

            \Statex

            \State \Return{\(\vb{x}\)}
        \EndFunction
    \end{algorithmic}
\end{algorithm}

\begin{definition}[Zero-Sum Game, Payoff Matrix]\label{optim-unit-0055}
    We consider a game between players P1 and P2, where P1 has \(m\) actions labelled by \(\Bqty{1, 2, \ldots, m}\) and P2 has \(n\) actions labelled by \(\Bqty{1, 2, \ldots, n}\), where the \emph{payoff  matrix} \(\vb{A} = \pqty{a_{ij}} \in \RR^{m \times n}\) records the amount earned by P1 and lost by P2, if P1 plays \(i\) and \(P2\) plays \(j\).
\end{definition}

\begin{example}[Rock-Paper-Scissors]\label{optim-unit-0056}
    The payoff matrix given for the rock-paper-scissors game is given by
    \[
        \pqty{
            \begin{array}{c|ccc}
                & \text{R} & \text{P} & \text{S} \\
                \hline
                \text{R} & 0 & -1 & +1 \\
                \text{P} & +1 & 0 & -1 \\
                \text{S} & -1 & +1 & 0
            \end{array}
        }.
    \]
\end{example}

\begin{definition}[Saddle Point, Value of a Game]\label{optim-unit-0058}
    For a payoff matrix \(\vb{A}\), \(\pqty{i^{\ast}, j^{\ast}}\) is called a \emph{saddle point}, if it is both the minimum entry in row \(i^{\ast}\) and maximum entry in column \(j^{\ast}\). In this case,
    \[
        \max_{i \in \bqty{m}} \min_{j \in \bqty{n}} a_{ij} = \min_{j \in \bqty{n}} \max_{i \in \bqty{m}} a_{ij} = a_{i^{\ast}j^{\ast}}
    \]
    is called the \emph{value} of the game.
\end{definition}

\begin{definition}[Pure and Mixed Strategies]\label{optim-unit-0060}
    A \emph{pure} strategy for P1 is when they pick a fixed action \(i \in \bqty{m}\).

    A \emph{mixed} strategy P1 picks a probability distribution \(\vb{p}\) on their action
    \[
        \vb{p} = \begin{pmatrix}
            p_1 \\ p_2 \\ \vdots \\ p_m
        \end{pmatrix}.
    \]
\end{definition}

\begin{proposition}[Optimisation Problems for P1 and P2 are Duals]\label{optim-unit-0061}
    The optimisation problems for P1 and P2's mixed strategies are duals of each other.
\end{proposition}

\begin{proof}
    The Lagrangian of P2's problem is given by
    \begin{align*}
        L\pqty{w, \vb{q}, \vb{s}, \vb*{\lambda}_1, \lambda_2} &= w + \vb*{\lambda}_1\transpose \pqty{\vb{Aq} + \vb{s} - w \vb{1}_m} - \lambda_2 \pqty{\vb{1}_n\transpose \vb{q} - 1} \\
        &= w \pqty{1 - \vb*{\lambda}_1\transpose \vb{1}_m} + \pqty{\vb*{\lambda}_1\transpose \vb{A} - \lambda_2 \vb{1}_n\transpose} \vb{q} + \vb*{\lambda}_1\transpose \vb{s} + \lambda_2.
    \end{align*}

    The set
    \[
        \Lambda = \set{\vb*{\lambda} \in \RR^m}{
            \begin{aligned}
                \vb*{\lambda}_1\transpose \vb{1}_m &= 1 \\
                \vb*{\lambda}_1\transpose \vb{A} &\geq \lambda_2 \vb{1}_n\transpose \\
                \vb*{\lambda}_1 &\geq 0
            \end{aligned}}
    \]
    and we have if \(\vb*{\lambda_1} \in \Lambda\), then
    \[
        \min_{w, \vb{q}, \vb{s}} L = \lambda_2.
    \]

    Therefore, the dual problem is to maximise \(\lambda_2\), subject to the constraints stated in \(\Lambda\), which is precisely P1's optimisation problem, with \(\vb{p}\) as \(\vb*{\lambda}_1\), and \(v\) as \(\lambda_2\).
\end{proof}

\begin{theorem}[Optimal Strategies]\label{optim-unit-0062}
    A strategy \(\vb{p}\) is optimal for P1, if and only if there exist \(\vb{q}\), \(v\), and \(w\), such that
    \begin{enumerate}
        \item Primal Feasibility: \(\vb{A}\transpose \vb{p} \geq v \vb{1}_n\), \(\vb{1}_m\transpose \vb{p} = 1\) and \(\vb{p} \geq \vb{0},\)
        \item Dual Feasibility: \(\vb{A} \vb{q} \leq w \vb{1}_m\), \(\vb{1}_n\transpose \vb{q} = 1\) and \(\vb{q} \geq \vb{0}.\)
        \item Zero duality gap: \(w=v=\vb{p}\transpose\vb{Aq}\).
    \end{enumerate}
\end{theorem}

