Section: Calculus on \(\RR^n\)
Type: proposition
Title: Classification of Stationary Point using Hessian Matrix
Label: variation-unit-0003
Local macros: \pqty := \left(#1\right)
Content:
\begin{proposition}[Classification of Stationary Point using Hessian Matrix] 

 Using the Hessian matrix, at a stationary point,
 \begin{itemize}
 \item if \(\lambda_i > 0\) for all \(i\), then \(f\pqty{\vb{x}} > f\pqty{\vb{0}}\) for sufficiently small nonzero \(\vb{x}\), and hence \(\vb{x} = \vb{0}\) is a local minimum;
 \item if \(\lambda_i < 0\) for all \(i\), then \(\vb{x} = \vb{0}\) is a local maximum;
 \item if there is some \(\lambda_i > 0\) and some other \(\lambda_j < 0\), then \(\vb{x} = \vb{0}\) is a saddle point.
 \end{itemize}
\end{proposition}

latex:
\begin{proposition}[Classification of Stationary Point using Hessian Matrix]\label{variation-unit-0003}
    \label{prop:classification-stationary-point}%
    Using the Hessian matrix, at a stationary point,
    \begin{itemize}
        \item if \(\lambda_i > 0\) for all \(i\), then \(f\pqty{\vb{x}} > f\pqty{\vb{0}}\) for sufficiently small nonzero \(\vb{x}\), and hence \(\vb{x} = \vb{0}\) is a \emph{local minimum};
        \item if \(\lambda_i < 0\) for all \(i\), then \(\vb{x} = \vb{0}\) is a \emph{local maximum};
        \item if there is some \(\lambda_i > 0\) and some other \(\lambda_j < 0\), then \(\vb{x} = \vb{0}\) is a \emph{saddle point}.
    \end{itemize}
\end{proposition}

\begin{remark}\label{variation-unit-0004}
    The remaining cases are \emph{degenerate} stationary points -- the quadratic test is inconclusive; higher-order behaviour must be examined.
\end{remark}

