\begin{remark}\label{variation-unit-0006}
    If a local minimum is not a global minimum, then either:
    \begin{itemize}
        \item there is another stationary point that is the global minimum; or
        \item the global minimum occurs on the boundary of the domain of \(f\); or
        \item \(f\) does not have a global minimum.
    \end{itemize}
\end{remark}

\begin{definition}[Graph of Function]\label{variation-unit-0009}
    \label{def:graph-of-fn}%
    Let \(f\) be a function with domain \(\dom\pqty{f} \subseteq \RR^n\), i.e., \(\functiondomain{f}{\dom\pqty{f}}{\RR}\). The \emph{graph} of \(f\) is the surface
    \[
        z = f\pqty{\vb{x}}
    \]
    in \(\RR^{n + 1}\), with coordinates \(\pqty{\vb{x}, z}\). A \emph{chord} of \(f\) is a line segment joining \(2\) points of its graph.
\end{definition}

