\begin{corollary}[Convex Functions have Stationary Points as Global Minimums]\label{variation-unit-0013}
    \label{cor:stationary-point-global-minimum}%
    If \(f\) is convex and differentiable, then any stationary point is a global minimum.
\end{corollary}

\begin{proof}
    If \(\vb{a}\) is a stationary point, \(\grad f\pqty{\vb{a}} = \vb{0}\), so \autoref{eq:first-order-condition} implies that \(f\pqty{\vb{y}} \geq f\pqty{\vb{a}}\), for all \(\vb{y} \in \dom\pqty{f}\).
\end{proof}

\begin{proof}[\proofname\ that \autoref{eq:first-order-condition} implies \autoref{eq:convex-condition}]
    In this direction, note that \autoref{eq:first-order-condition} implies that
    \begin{align*}
        f\pqty{\vb{x}} &\geq f\pqty{\vb{z}} + \pqty{\vb{x} - \vb{z}} \vdot \grad f\pqty{\vb{z}} \\
        f\pqty{\vb{y}} &\geq f\pqty{\vb{z}} + \pqty{\vb{y} - \vb{z}} \vdot \grad f\pqty{\vb{z}}
    \end{align*}
    for all \(\vb{x}, \vb{y}\) and \(\vb{z} \in \dom\pqty{f}\).

    Taking a linear combination, we have
    \[
        \pqty{1 - t} f\pqty{\vb{x}} + t f \pqty{\vb{y}} \geq f\pqty{z} + \bqty{\pqty{1 - t} \vb{x} + t \vb{y} - \vb{z}} \vdot \grad f\pqty{\vb{z}}.
    \]

    We now choose \(\vb{z} = \pqty{1 - t} \vb{x} + t \vb{y}\), which implies \autoref{eq:convex-condition}.
\end{proof}

\begin{proposition}[Alternative First Order Condition]\label{variation-unit-0014}
    An alternative way to write \autoref{eq:first-order-condition} is that
    \begin{equation}
        \pqty{\vb{y} - \vb{x}} \vdot \pqty{\grad f\pqty{\vb{y}} - \grad f\pqty{\vb{x}}} \geq 0
        \label{eq:first-order-condition-alternative}
    \end{equation}
    for all \(\vb{x}, \vb{y} \in \dom\pqty{f}\).
\end{proposition}

\begin{proof}[\proofname\ that \autoref{eq:first-order-condition} implies \autoref{eq:first-order-condition-alternative}]
    From \autoref{eq:first-order-condition}, we have
    \begin{align*}
        f\pqty{\vb{y}} &\geq f\pqty{\vb{x}} + \pqty{\vb{y} - \vb{x}} \vdot \grad f\pqty{\vb{x}}, \\
        f\pqty{\vb{x}} &\geq f\pqty{\vb{y}} + \pqty{\vb{x} - \vb{y}} \vdot \grad f\pqty{\vb{y}}.
    \end{align*}

    Adding these give \autoref{eq:first-order-condition-alternative}.
\end{proof}

\begin{theorem}[Second Order Condition]\label{variation-unit-0015}
    \label{thm:second-order-condition}%
    If \(f\) is \(\contClass{2}\), then \autoref{eq:convex-condition} is equivalent to all eigenvalues of the Hessian \(\vb{H} \pqty{\vb{x}}\) is non-negative, for all \(\vb{x} \in \dom\pqty{f}\). In other words, the Hessian is positive semi-definite.
\end{theorem}

\begin{definition}[Legendre Transform]\label{variation-unit-0017}
    \label{def:legendre-transform}%
    The \emph{Legendre Transform} of \(\functiondomain{f}{\dom\pqty{f} \subseteq \RR^n}{\RR}\) is
    \[
        \legendre{f} \pqty{\vb{p}} = \sup_{\vb{x} \in \dom \pqty{f}} \bqty{\vb{p} \vdot \vb{x} - f\pqty{\vb{x}}}
    \]
    with its domain as \(\dom \pqty{\legendre{f}} = \set{\vb{p} \in \RR^n}{\text{the supremum exists and is finite}}\).
\end{definition}

\begin{proposition}[Legendre Transform is Convex]\label{variation-unit-0018}
    \label{prop:legendre-convex}%
    \(\legendre{f}\) is convex.
\end{proposition}

\begin{proof}
    Let \(\vb{p}, \vb{q} \in \dom \pqty{\legendre{f}}\), and \(t \in \oointv{0}{1}\). We note that
    \begin{align*}
        \sup_{\vb{x} \in \dom \pqty{f}} \Bqty{\bqty{\pqty{1 - t} \vb{p} + t \vb{q}} \cdot \vb{x} - f\pqty{\vb{x}}} &= \sup_{\vb{x} \in \dom \pqty{f}} \Bqty{\pqty{1 - t} \bqty{\vb{p} \vdot \vb{x} - f\pqty{\vb{x}}} + t \bqty{\vb{q} \vdot \vb{x} - f \pqty{\vb{x}}}} \\
        &\leq \pqty{1 - t} \sup_{\vb{x} \in \dom \pqty{f}} \pqty{\vb{p} \vdot \vb{x} - f\pqty{\vb{x}}} + t \sup_{\vb{x} \in \dom \pqty{f}} \pqty{\vb{q} \vdot \vb{x} - f\pqty{\vb{x}}}.
    \end{align*}

    Since the right-hand side is finite, so must be the left-hand side, and hence \(\pqty{1 - t} \vb{p} + t \vb{q} \in \dom \pqty{\legendre{f}}\). In particular, the previous inequality also showed that
    \[
        \legendre{f} \pqty{\pqty{1 - t} \vb{p} + t \vb{q}} \leq \pqty{1 - t} \legendre{f} \pqty{\vb{p}} + t \legendre{f} \pqty{\vb{q}}
    \]
    so \(\legendre{f}\) is indeed convex.
\end{proof}

\begin{proposition}\label{variation-unit-0019}
    \label{prop:dot-product-convex}%
    If \(f\) is convex, then so is
    \[
        F_{\vb{p}} \pqty{\vb{x}} = f\pqty{\vb{x}} - \vb{p} \vdot \vb{x}
    \]
    where \(\vb{p} \in \RR^n\) is fixed.
\end{proposition}

\begin{proof}
    We have \(\dom \pqty{F_{\vb{p}}} = \dom \pqty{f}\). Note
    \begin{align*}
        F_{\vb{p}} \pqty{\pqty{1 - t} \vb{x} + t \pqty{\vb{y}}} &= f\pqty{\pqty{1 - t} \vb{x} + t \vb{y}} - \vb{p} \vdot \pqty{\pqty{1 - t} \vb{x} + t \vb{y}} \\
        &\leq \pqty{1 - t} f \pqty{\vb{x}} + t f \pqty{\vb{y}} - \vb{p} \vdot \pqty{\pqty{1 - t} \vb{x} + t \vb{y}} \\
        &= \pqty{1 - t} F_{\vb{p}} \pqty{\vb{x}} + t F_{\vb{p}} \pqty{\vb{y}}.
    \end{align*}
\end{proof}

\begin{corollary}[Legendre Transform of convex functions]\label{variation-unit-0020}
    \label{cor:legendre-transform-of-convex-function}
    If \(f\) is convex and differentiable, then any stationary point of \(\vb{p} \vdot \vb{x} - f \pqty{\vb{x}}\) (which is a concave function, by \autoref{prop:dot-product-convex}) is a global maximum occurring at \(\vb{x} \pqty{\vb{p}}\) given by solving
    \begin{equation}
        \grad f\pqty{\vb{x}} = \vb{p}.
        \label{eq:legendre-transform-of-convex-function}
    \end{equation}

    Hence, we have
    \[
        \legendre{f} \pqty{\vb{p}} = \vb{p} \vdot \vb{x} \pqty{\vb{p}} - f\pqty{\vb{x} \pqty{\vb{p}}}.
    \]
\end{corollary}

\begin{remark}\label{variation-unit-0021}
    If \(f\) is \emph{strictly} convex, then any solution to \autoref{eq:legendre-transform-of-convex-function}, if it exists, is unique. The idea is to consider the chord joining the two maxima of the function, and use the concave version of \autoref{eq:strict-convex-condition}.
\end{remark}

