\begin{theorem}[Biconjugacy on the original open convex domain]\label{variation-unit-0023}
\label{thm:legendre-transform-of-legendre-transform}
Let \(f\) be differentiable and convex on a nonempty open convex set \(D\).
Then \(f^{**}(x)=f(x)\) for every \(x\in D\). This statement does not assert
that the effective domains of \(f\) and \(f^{**}\) are identical.
\end{theorem}

\begin{remark}\label{variation-unit-0024}
Domain equality is not automatic. For \(f=0\) on \((0,1)\),
\(f^*(p)=\max(0,p)\), so \(f^{**}=0\) on \([0,1]\) and \(+\infty\) outside.
This follows directly by taking the supremum of \(px-\max(0,p)\).
\end{remark}

\begin{example}[Double Legendre Transform of the Line]\label{variation-unit-0025}
    We note that
    \[
        \llegendre{f} \pqty{x} = \sup_{p \in \Bqty{c}} \pqty{xp - \legendre{f} \pqty{p}} = cx = f\pqty{x}
    \]
    indeed.
\end{example}

\begin{definition}[Entropy]\label{variation-unit-0026}
    We define the \emph{entropy} as
    \begin{equation}
        \label{eq:entropy}%
        S\pqty{E, V} = k_{\text{B}} \log \Omega \pqty{E, V},
    \end{equation}
    where \(k_{\text{B}} = 1.380649\times10^{-23}\,\mathrm{J\,K^{-1}}\) is the Boltzmann constant.
\end{definition}

On the positive-temperature branch considered here, \((\partial S/\partial E)_V=1/T>0\). Thus entropy is locally strictly increasing with energy, allowing local inversion to define
\begin{equation}
    \label{eq:energy}%
    E = E \pqty{S, V}.
\end{equation}

