\begin{proposition}[Fundamental Thermodynamic Relation]\label{variation-unit-0028}
    We have
    \begin{equation}
        \label{eq:fundamental-thermodynamic-relation}%
        \dd{E} = T \dd{S} - P \dd{V}
    \end{equation}
\end{proposition}

\begin{example}[Legendre Transforms for Pressure -- Enthalpy]\label{variation-unit-0030}
    Similarly, we forget \autoref{eq:pressure} (for pressure). Consider the Legendre Transform of \(E\pqty{S, V}\) with respect to \(V\) at fixed \(S\), with parameter \(-P\). We call this \(-H\), i.e.,
    \[
        -H \pqty{S, P} = \sup_{V} \Bqty{-PV - E\pqty{S,V}}
    \]

    Similarly, applying \autoref{eq:legendre-transform-of-convex-function} maximises for \(V\) satisfying \autoref{eq:pressure}, and
    \[
        H\pqty{S, P} = E + PV
    \]
    is called the \emph{enthalpy}. It is very useful in chemistry.

    Now, \autoref{eq:fundamental-thermodynamic-relation} implies that
    \[
        \dd{H} = T \dd{S} + V \dd{P}
    \]
    and hence
    \begin{align*}
        T &= \pqty{\pdv{H}{S}}_{P}, \\
        V &= \pqty{\pdv{H}{P}}_{S}.
    \end{align*}
\end{example}

\begin{definition}[Thermodynamic Potentials]\label{variation-unit-0032}
    \(E, F, G, H\) are called \emph{thermodynamic potentials}.
\end{definition}

\begin{definition}[Maxwell Relations]\label{variation-unit-0033}
    The four equations derived from the four thermodynamic potentials are the \emph{Maxwell relations}.
\end{definition}

\begin{proposition}[Maximum/Minimum of Function on Surface]\label{variation-unit-0034}
    \label{prop:max-min-of-function-on-surface}%
    \(\vb{x}_0 \in S\) is a stationary point of \(f\) on \(S\), if and only if \(\grad f\pqty{\vb{x}_0}\) is normal to \(S\).
\end{proposition}

\begin{lemma}[Gradient is Perpendicular to Level Surface]\label{variation-unit-0035}
    \label{lem:gradient-perpendicular-level-surface}%
    \(\grad g\) is normal to the surface \(S\).
\end{lemma}

\begin{proof}
    Since \(g\pqty{\vb{x} \pqty{u, v}} = 0\), differentiating with respect to \(u\) and \(v\) just like above gives the result.
\end{proof}

\begin{definition}[Lagrange Multiplier]\label{variation-unit-0036}
    \label{def:lagrange-multiplier}%
    The \(\lambda\) defined above is a \emph{Lagrange multiplier}.
\end{definition}

\begin{definition}[Differentiability Classes]\label{variation-unit-0040}
    For \(\Omega \subseteq \RR^n\), we define
    \begin{align*}
        \contClass{k} \pqty{\Omega} &= \set{\functiondomain{y}{\Omega}{\RR}}{y \text{ is }k\text{ times continuously differentiable}}, \\
        \smoothClass \pqty{\Omega} &= \set{\functiondomain{y}{\Omega}{\RR}}{y \text{ is smooth (infinitely differentiable)}}
    \end{align*}
\end{definition}

\begin{definition}[Functional]\label{variation-unit-0041}
    A \emph{functional} is a map
    \[
        \function{F}{\contClassSymb}{\RR}{y}{F\bqty{y},}
    \]
    i.e. \(F\) maps a function to a number. More generally, a functional can take inputs of the form \(\pqty{f_1, \ldots, f_n}\) and output a number.
\end{definition}

\begin{definition}[Functional Derivative]\label{variation-unit-0042}
    \label{def:functional-derivative}%
    We define
    \[
        \fdv{F\bqty{y}}{y\pqty{x}} = \pdv{f}{y} - \dv{x} \pdv{f}{y'}
    \]
    to be the \emph{functional derivative} of \(F\bqty{y}\) w.r.t \(y\pqty{x}\). This is a function in \(x\).
\end{definition}

So \(\var{F\bqty{y}}\) vanishes to first order for \emph{arbitrary} \(\var{y\pqty{x}}\), if and only if \(y\pqty{x}\) satisfies
\begin{equation}
    \fdv{F\bqty{y}}{y\pqty{x}} = \pdv{f}{y} - \dv{x} \pdv{f}{y'} = 0,
    \label{eq:euler-lagrange}
\end{equation}
the \emph{Euler--Lagrange Equation}. This is an ODE of order at most two for \(y\pqty{x}\).

\begin{remark}\label{variation-unit-0044}
    There is a good reason why we start with \(t\) -- since if we use \(l\) initially, then the upper limit of the integration \emph{will depend on the curve}, but our derivation of \autoref{eq:euler-lagrange} assumed that the boundaries are fixed.
\end{remark}

\begin{proof}
    We have
    \begin{align*}
        \dv{f}{x} &= \pdv{f}{x} + \pdv{f}{y} y' + \pdv{f}{y'} y'' \\
        &= \pdv{f}{x} + y' \pqty{\pdv{f}{y} - \dv{x} \pdv{f}{y'}} + \dv{x} \pqty{y' \pdv{f}{y'}}.
    \end{align*}

    If \autoref{eq:euler-lagrange} holds, we have
    \[
        \dv{x} \pqty{f - y' \pdv{f}{y'}} = \pdv{f}{x},
    \]
    and if \(\pdv*{f}{x} = 0\), we have \(f - y' \pdv*{f}{y'}\) is constant indeed.
\end{proof}

\begin{definition}[Refraction Index]\label{variation-unit-0046}
    We define the \emph{refractive index} to be
    \[
        n\pqty{\vb{x}} = \frac{c}{c\pqty{\vb{x}}}.
    \]
\end{definition}

\begin{theorem}[Fermat's Principle]\label{variation-unit-0047}
    In the geometrical-optics setting considered here, light rays make the optical path \(P\) stationary (equivalently \(T\) in this nondispersive model). Stationarity need not imply a local minimum.
\end{theorem}

\begin{example}[Dido's Problem]\label{variation-unit-0051}
    If we have a wall along the \(x\)-axis, and we build a fence around that wall, but we only have a fixed total length of fence \(L\), what shape should the fence to be to maximise the area enclosed? (See Example Sheet 1.)
\end{example}

\begin{example}[Isoperimetric Problem]\label{variation-unit-0052}
    A simple closed curve has length \(L\). What shape should it be to maximise its enclosed area? (See Example Sheet 2)
\end{example}

