Type: prose
Local macros: \RR := \mathbb{R}; \bqty := \left[#1\right]; \ccintv := [#1,#2]; \contClass := C^{#1}; \contClassSymb := \mathcal{C}; \functiondomain := #1:#2\to #3; \pqty := \left(#1\right); \set := \left\{#1\mid #2\right\}
Content:
Consider the class of functions
\[
 \contClassSymb = \set{\functiondomain{y}{\ccintv{\alpha}{\beta}}{\RR}}{y is \contClass{2} and y\pqty{\alpha} = y\pqty{\beta} = 0}.
\]

Let
\begin{subequations}

 \begin{equation}
 F\bqty{y} = \int_{\alpha}^{\beta} \bqty{\rho y'^2 + \sigma y^2} \dd{x}
 \end{equation}
 \begin{equation}
 G\bqty{y} = \int_{\alpha}^{\beta} w y^2 \dd{x}
 \end{equation}
\end{subequations}
Assume the regular Sturm--Liouville setting: \(\alpha<\beta\) are finite, \(\rho\in C^1\), \(\sigma,w\in C^0\), and \(\rho,w>0\) on the closed interval \([\alpha,\beta]\). We want to minimise \(F\bqty{y}\) in \(\contClassSymb\) subject to constraint \(G\bqty{y} = 1\).

latex:
Consider the class of functions
\[
    \contClassSymb = \set{\functiondomain{y}{\ccintv{\alpha}{\beta}}{\RR}}{y \text{ is }\contClass{2}\text{ and }y\pqty{\alpha} = y\pqty{\beta} = 0}.
\]

Let
\begin{subequations}
    \label{eq:sturm-liouville}%
    \begin{equation}
        F\bqty{y} = \int_{\alpha}^{\beta} \bqty{\rho y'^2 + \sigma y^2} \dd{x}
    \end{equation}
    \begin{equation}
        G\bqty{y} = \int_{\alpha}^{\beta} w y^2 \dd{x}
    \end{equation}
\end{subequations}
Assume the regular Sturm--Liouville setting: \(\alpha<\beta\) are finite, \(\rho\in C^1\), \(\sigma,w\in C^0\), and \(\rho,w>0\) on the closed interval \([\alpha,\beta]\). We want to minimise \(F\bqty{y}\) in \(\contClassSymb\) subject to constraint \(G\bqty{y} = 1\).

\begin{example}[Sturm--Liouville using Unconstrained Optimisation]\label{variation-unit-0054}
    Define
    \[
        \Lambda \bqty{y} = \frac{F\bqty{y}}{G\bqty{y}},
    \]
    and we would like to optimise \(\Lambda\).

    We have (using chain rule)
    \begin{align*}
        0 &= \fdv{\Lambda}{y} \\
        &= \frac{1}{G} \pqty{\fdv{F}{y} - \frac{F}{G} \fdv{G}{y}} \\
        &= \frac{2}{G} \pqty{\mathcal{L} y - \Lambda w y}
    \end{align*}
    and the minimal value of \(\Lambda\) is indeed the lowest eigenvalue of the Sturm--Liouville problem.
\end{example}

\begin{definition}[Configuration Space]\label{variation-unit-0057}
    The \emph{configuration space} is the space of \(N\)-tuples of positions of the \(N\) particles in the system.
\end{definition}

\begin{definition}[Lagrangian, Action]\label{variation-unit-0058}
    We define the \emph{Lagrangian}
    \begin{equation}
        \label{eq:lagrangian}%
        L \pqty{\vb{q}, \dot{\vb{q}}, t} = T - V
    \end{equation}
    and the \emph{action} of a path \(\vb{q}\pqty{t}\) in the configuration space between \(\vb{q}_{A}\) and \(\vb{q}_{B}\) is
    \[
        I \bqty{\vb{q}} = \int_{t_A}^{t_B} L \pqty{\vb{q}\pqty{t}, \dot{\vb{q}} \pqty{t}, t} \dd{t}
    \]
    which has dimension \(\dimM \dimL^2 \dimT^{-1}\) (which has the same dimension as \(\hbar\) in quantum mechanics -- this is not a coincidence).
\end{definition}

\begin{theorem}[Principle of Least Action]\label{variation-unit-0059}
    For fixed endpoint positions and times, the physical trajectory makes the action stationary. The traditional name ``least action does not guarantee a minimum.
\end{theorem}

\begin{proof}
    Consider the total derivative with respect to \(t\). We have
    \begin{align*}
        \dv{L}{t} &= \dv{t} L\pqty{\vb{q}, \dot{\vb{q}}, t} \\
        &= \pdv{L}{t} + \sum_{i = 1}^{3N} \pqty{\pdv{L}{q_i} \dot{q}_i + \pdv{L}{\dot{q}_i} \ddot{q}_i} \\
        &= \pdv{L}{t} + \sum_{i = 1}^{3N} \dot{q}_i \pqty{\pdv{L}{q_i} - \dv{t} \pdv{L}{\dot{q}_i}} + \dv{t} \sum_{i = 1}^{3N} \dot{q}_i \pdv{L}{\dot{q}_i}.
    \end{align*}

    By the Euler--Lagrange equations, the term in the brackets vanishes, and hence
    \[
        \dv{t} \pqty{L - \sum_{i = 1}^{3N} \dot{q}_i \pdv{L}{\dot{q}_i}} = \pdv{L}{t}.
    \]

    If \(L\) has no explicit \(t\)-dependence, the right-hand side reduces to zero, as desired.
\end{proof}

\begin{example}[Conserved Energy in Conservative Forces]\label{variation-unit-0062}
    If \(V = V\pqty{\vb{x}}\) from above, we have
    \begin{align*}
        -E &= \frac{1}{2} m \dot{\vb{x}}^2 - V\pqty{\vb{x}} - \sum_{i = 1}^{3N} \dot{x}_i m \dot{x}_i \\
        &= - \frac{1}{2} m \dot{\vb{x}}^2 - V\pqty{\vb{x}} \\
        &= - \pqty{T + V}.
    \end{align*}

    So \(E\) is the \emph{total energy} of the particle.
\end{example}

\begin{definition}[Hamiltonian]\label{variation-unit-0064}
    The \emph{Hamiltonian} \(H \pqty{\vb{q}, \vb{p}, t}\) is defined as the Legendre transform of \(L\) w.r.t. \(\dot{\vb{q}}\), i.e.
    \begin{equation}
        \label{eq:hamiltonian}%
        H \pqty{\vb{q}, \vb{p}, t} = \sup_{\dot{\vb{q}}} \bqty{\vb{p} \vdot \dot{\vb{q}} - L \pqty{\vb{q}, \dot{\vb{q}}, t}}.
    \end{equation}
\end{definition}

