\[
 H\pqty{\vb{q}, \vb{p}, t} = \vb{p} \vdot \dot{\vb{q}} - L\pqty{\vb{q}, \dot{\vb{q}}, t}
\]
for the stationary point of the brackets in \(\dot{q}_i\), i.e., where \(\vb{p}\) satisfies
\begin{equation}

 p_i = \pdv{L}{\dot{q}_i}
\end{equation}

latex:
Using \autoref{eq:legendre-transform-of-convex-function}, we have
\[
    H\pqty{\vb{q}, \vb{p}, t} = \vb{p} \vdot \dot{\vb{q}} - L\pqty{\vb{q}, \dot{\vb{q}}, t}
\]
for the stationary point of the brackets in \(\dot{q}_i\), i.e., where \(\vb{p}\) satisfies
\begin{equation}
    \label{eq:conjugate-momentum}%
    p_i = \pdv{L}{\dot{q}_i}
\end{equation}

\begin{definition}[Conjugate Momentum]\label{variation-unit-0067}
    We call the variable \(p_i\) the \emph{conjugate momentum} to \(q_i\).
\end{definition}

\begin{proof}
    We have
    \begin{align*}
        \pqty{\pdv{H}{p_i}}_{\vb{q}} &= \dot{q}_i + \sum_{j = 1}^{3N} p_j \pdv{\dot{q}_j}{p_i} - \sum_{j = 1}^{3N} \pdv{L}{\dot{q}_j} \pdv{\dot{q}_j}{p_i} \\
        &= \dot{q}_i
    \end{align*}
    by \autoref{eq:conjugate-momentum}.
\end{proof}

\begin{proof}
    We have
    \begin{align*}
        \pqty{\pdv{H}{q_i}}_{\vb{p}} &= \sum_{j = 1}^{3N} p_j \pdv{\dot{q}_j}{q_i} - \pdv{L}{q_i} - \sum_{j = 1}^{3N} \pdv{L}{\dot{q}_j} \pdv{\dot{q}_j}{q_i} = - \pdv{L}{q_i}
    \end{align*}
    by \autoref{eq:conjugate-momentum}.

    By Euler--Lagrange Equations, we have
    \[
        - \pdv{L}{q_i} = - \dv{t} \pdv{L}{\dot{q}_i} = - \dot{p}_i
    \]
    again by using \autoref{eq:conjugate-momentum}.
\end{proof}

