\begin{theorem}[Hamilton's Equations]\label{variation-unit-0070}
    We have
    \begin{equation}
        \label{eq:hamilton-equations}
        \dot{q}_i = \pdv{H}{p_i} \qand \dot{p}_i = - \pdv{H}{q_i}
    \end{equation}
\end{theorem}

\begin{definition}[Phase Space]\label{variation-unit-0071}
    The \(6N\)-dimensional space that Hamilton's equations (in \(\pqty{\vb{q}, \vb{p}}\)) is called \emph{phase space}.
\end{definition}

\begin{proposition}[Time-Independent Hamiltonian is Conserved]\label{variation-unit-0072}
    If \(H\) has no explicit time-dependence, then the Hamiltonian is conserved for any solution to Hamilton's equations.
\end{proposition}

