 &= \sum_{i = 1}^{3N} \pqty{\pdv{H}{q_i} \dot{q}_i + \pdv{H}{p_i} \dot{p}_i} + \pdv{H}{t} \\
 &= \pdv{H}{t}
 \end{align*}
 by using [REF:eq:hamilton-equations] . Therefore, if \(H\) has no explicit time-dependence, the Hamiltonian is conserved.
\end{proof}

