\begin{theorem}[Finite Jensen Inequality]\label{probability-theorem-009}
    \label{probability-thm:am-gm}
    Let \(f:I\to\RR\) be convex on an open interval \(I\). Then for all \(x_1, \ldots, x_n \in I\), we have
    \[
        \frac{1}{n} \sum_{k = 1}^{n} f\pqty{x_k} \geq f\pqty{\frac{\sum_{k = 1}^{n} x_k}{n}}.
    \]
\end{theorem}

\begin{definition}[Joint Distribution for Discrete Variables]\label{probability-definition-031}
    \label{probability-def:joint-distribution-discrete}%
    Let \(X_1, \ldots, X_n\) be discrete random variables. Their \emph{joint distribution} is defined to be
    \[
        \Prob\pqty{X_1 = x_1, \ldots, X_n = x_n}
    \]
    for all possible values of \(x_1, x_2, \ldots, x_n\).
\end{definition}

\begin{definition}[Conditional Distribution for Discrete Variables]\label{probability-definition-032}
    \label{probability-def:conditional-distribution-discrete}%
    Let \(X\) and \(Y\) be two discrete random variables. The \emph{conditional distribution} of \(X\), given \(Y = y\) (where \(y\) is fixed and \(\Prob(Y=y)>0\)) is defined to be
    \[
        \Prob\pqty{\Conditional{X = x}{Y = y}} = \frac{\Prob\pqty{X = x, Y = y}}{\Prob\pqty{Y = y}}
    \]
    for all possible values of \(x\).
\end{definition}

\begin{example}[Distribution of Sum of Random Variables]\label{probability-example-025}
    \label{probability-ex:distribution-sum-discrete}%
    Let \(X\) and \(Y\) be two independent random variables. We want to understand the distribution of \(X + Y\). We have
    \begin{align*}
        \Prob\pqty{X + Y = z} &= \sum_{y \in \RR} \Prob\pqty{X + Y = z, Y = y} \\
        &= \sum_{y \in \RR} \Prob\pqty{X = z - y, Y = y} \\
        &= \sum_{y \in \RR} \Prob\pqty{X = z - y} \cdot \Prob\pqty{Y = y}.
    \end{align*}
\end{example}

\begin{definition}[Convolution of Distribution for Discrete Variables]\label{probability-definition-033}
    \label{probability-def:convolution-distribution-discrete}%
    Let \(X, Y\) be two independent discrete random variables. Then the distribution of \(X + Y\), given by
    \[
        \sum_{y \in \RR} \Prob\pqty{X = z - y} \cdot \Prob\pqty{Y = y}
    \]
    is the \emph{convolution} of their probability laws (represented here by their mass functions or densities).
\end{definition}

\begin{definition}[Conditonal Expectation upon an Event]\label{probability-definition-034}
    \label{probability-def:conditional-expectation-upon-event}
Assume \(X\) is integrable; any conditioning variable here is discrete. Conditional equalities hold almost surely.
%
    The \emph{conditional expectation} of a random variable \(X\) with respect to an event \(B\), where \(\Prob\pqty{B} > 0\), is given by
    \[
        \Expt\bqty{\Conditional{X}{B}} = \frac{\Expt\bqty{X \cdot \indicator\pqty{B}}}{\Prob\pqty{B}}.
    \]
\end{definition}

\begin{theorem}[Law of Total Expectation]\label{probability-theorem-010}
    \label{probability-thm:law-of-total-expectation}
Assume \(X\) is integrable; any conditioning variable here is discrete. Conditional equalities hold almost surely.
%
    Let \(X\) be a random variable, \(\pqty{\Omega_i}\) be a partition of \(\Omega\) into disjoint sets, with \(\Prob\pqty{\Omega_i} > 0\) for all \(i = 1, 2, \ldots ,n\). Then we have
    \[
        \Expt\bqty{X} = \sum_{i = 1}^{n} \Expt\bqty{\Conditional{X}{\Omega_i}} \cdot \Prob\pqty{\Omega_i}.
    \]
\end{theorem}

