\begin{proposition}[Conditional Expectation upon Random Variable Event]\label{probability-proposition-017}
    \label{probability-prop:conditional-expectation-random-variable}
For the pointwise formula require \(\Prob(Y=y)>0\).

Assume \(X\) is integrable; any conditioning variable here is discrete. Conditional equalities hold almost surely.
%
    We have
    \[
        \Expt\bqty{\Conditional{X}{Y = y}} = \sum_{x \in \RR} x \cdot \Prob\pqty{\Conditional{X = x}{Y = y}}.
    \]
\end{proposition}

\begin{proof}\label{probability-proof-034}
    We have
    \begin{align*}
        \Expt\bqty{\Conditional{X}{Y = y}} &= \frac{\Expt\bqty{X \cdot \indicator\pqty{Y = y}}}{\Prob\pqty{Y = y}} \\
        &= \sum_{x \in \RR} x \cdot \frac{\Prob\pqty{X = x, Y = y}}{\Prob\pqty{Y = y}} \\
        &= \sum_{x \in \RR} x \cdot \Prob\pqty{\Conditional{X = x}{Y = y}}.
    \end{align*}
\end{proof}

\begin{proposition}[Properties of Conditional Expectation Distribution]\label{probability-proposition-018}
    \label{probability-prop:conditional-expectation-distribution-property}
All variables inside a conditional expectation are integrable.
%
    For any \(c \in \RR\), we have
    \begin{itemize}
        \item \(\Expt\bqty{\Conditional{cX}{Y}} = c \Expt\bqty{\Conditional{X}{Y}}\).
        \item \(\Expt\bqty{\Conditional{c + X}{Y}} = c + \Expt\bqty{\Conditional{X}{Y}}\) and \(\Expt\bqty{\Conditional{c}{Y}} = c\).
        \item If \(X_1, X_2, \ldots, X_n\) and \(Y\) are random variables, then we have
        \[
            \Expt\bqty{\Conditional{\sum_{i = 1}^{n} X_i}{Y}} = \sum_{i = 1}^{n} \Expt\bqty{\Conditional{X_i}{Y}}.
        \]
    \end{itemize}
\end{proposition}

\begin{proposition}[Expectation of Conditional Expectation Distribution]\label{probability-proposition-019}
    \label{probability-prop:expectation-conditional-expectation-distribution}
Assume \(X\) is integrable; any conditioning variable here is discrete. Conditional equalities hold almost surely.
%
    We have
    \[
        \Expt\bqty{\Expt\bqty{\Conditional{X}{Y}}} = \Expt\bqty{X}.
    \]
\end{proposition}

\begin{proposition}[Conditional Expectation Distribution of Independent Variables]\label{probability-proposition-020}
    \label{probability-prop:conditional-expectation-distribution-independent}
Assume \(X\) is integrable; any conditioning variable here is discrete. Conditional equalities hold almost surely.
%
    Let \(X\) and \(Y\) be independent. Then
    \[
        \Expt\bqty{\Conditional{X}{Y}} = \Expt\bqty{X}.
    \]
\end{proposition}

\begin{proof}\label{probability-proof-036}
    Recall that by definition,
    \begin{align*}
        \Expt\bqty{\Conditional{X}{Y = y}} &= \sum_{x \in \RR} x \cdot \Prob\pqty{\Conditional{X = x}{Y = y}} \\
        &= \sum_{x \in \RR} x \cdot \Prob\pqty{X = x} \\
        &= \Expt\bqty{X}.
    \end{align*}

    Hence,
    \[
        \Expt\bqty{\Conditional{X}{Y}} = \Expt\bqty{X} \sum_{y \in \RR} \indicator\pqty{Y = y} = \Expt\bqty{X}
    \]
    as desired.
\end{proof}

\begin{proposition}[Conditional Expectation upon Independent Conditions]\label{probability-proposition-021}
    \label{probability-prop:conditional-expectation-independent-conditions}
Assume also that \(Y\) and \(Z\) are discrete.

Assume \(X\) is integrable; any conditioning variable here is discrete. Conditional equalities hold almost surely.
%
    Let \(Y\) and \(Z\) be two independent random variables. Then
    \[
        \Expt\bqty{\Conditional{\Expt\bqty{\Conditional{X}{Y}}}{Z}} = \Expt\bqty{X}.
    \]
\end{proposition}

\begin{proof}\label{probability-proof-038}
    We have
    \begin{align*}
        \Expt\bqty{\Conditional{h\pqty{Y} \cdot X}{Y}} &= \sum_{y \in \RR} \indicator\pqty{Y = y} \cdot \Expt\bqty{\Conditional{h\pqty{Y} \cdot X}{Y = y}} \\
        &= \sum_{y \in \RR} \indicator\pqty{Y = y} \cdot h\pqty{Y} \cdot \Expt\bqty{\Conditional{X}{Y = y}} \\
        &= h\pqty{Y} \cdot \sum_{y \in \RR} \indicator\pqty{Y = y} \cdot \Expt\bqty{\Conditional{X}{Y = y}} \\
        &= h\pqty{Y} \cdot \Expt\bqty{\Conditional{X}{Y}}.
    \end{align*}
\end{proof}

\begin{corollary}[Conditional Expectation upon Same Condition]\label{probability-corollary-005}
    \label{probability-cor:conditional-expecation-upon-same-condition}
Assume \(X\) is integrable; any conditioning variable here is discrete. Conditional equalities hold almost surely.
%
    We have
    \[
        \Expt\bqty{\Conditional{\Expt\bqty{\Conditional{X}{Y}}}{Y}} = \Expt\bqty{\Conditional{X}{Y}}.
    \]
\end{corollary}

\begin{corollary}[Conditional Expectation upon Itself]\label{probability-corollary-006}
    \label{probability-cor:conditional-expectation-upon-itself}
Assume \(X\) is integrable; any conditioning variable here is discrete. Conditional equalities hold almost surely.
%
    We have
    \[
        \Expt\bqty{\Conditional{X}{X}} = X.
    \]    
\end{corollary}

\begin{proposition}[Conditional mean as least-squares predictor]\label{probability-proposition-023}
For square-integrable \(X\) and discrete \(Y\), set \(g(Y)=\Expt[X\mid Y]\).
For every square-integrable function \(h(Y)\),
\[\Expt[(X-h(Y))^2]=\Expt[(X-g(Y))^2]+\Expt[(g(Y)-h(Y))^2].\]
Thus \(g(Y)\) uniquely minimises mean squared error, up to almost-sure equality.
\end{proposition}

\begin{proof}\label{probability-proof-039}
Conditional Cauchy--Schwarz on each event \(\{Y=y\}\) gives
\(g(y)^2\le\Expt[X^2\mid Y=y]\), so \(g(Y)\) is square-integrable.
Expand the square with \(X-h=(X-g)+(g-h)\). The cross term vanishes since
\(\Expt[X-g(Y)\mid Y]=0\) and \(g-h\) is a function of \(Y\).
\end{proof}

\begin{definition}[Random/Stochastic Process]\label{probability-definition-036}
    \label{probability-def:random-stochastic-process}%
    A discrete-time \emph{random/stochastic process} is a sequence of random variables \(\pqty{X_n}_{n \in \NN}\).
\end{definition}

\begin{definition}[Simple Random Walk]\label{probability-definition-038}
    \label{probability-def:simple-random-walk}%
    A random walk is \emph{simple} if the steps can only take values \(\pm 1\).
\end{definition}

\begin{notation}\label{probability-notation-002}
    \(\Prob_x\) denotes the law of the walk started deterministically at \(x\), and \(\Expt_x\) its expectation. This does not require conditioning a single reference law on a possibly null event.
\end{notation}

\begin{remark}[Deterministic endpoint cases]\label{probability-remark-006}
For \(0<x<a\), if \(p=0\) then \(h(x)=0\) and \(k(x)=x\);
if \(p=1\) then \(h(x)=1\) and \(k(x)=a-x\). At the absorbing endpoints
\(k(0)=k(a)=0\), \(h(0)=0\), \(h(a)=1\).
\end{remark}

\begin{theorem}[Uniqueness of Probability Generating Function]\label{probability-theorem-011}
    \label{probability-thm:pgf-uniqueness}%
    The probability generating function uniquely determines the distribution of the random variable \(X\).
\end{theorem}

