\begin{definition}[Moment Generating Function]\label{probability-definition-062}
    \label{probability-def:moment-generating-fn}%
    Let \(X\) be a real random variable. The integral expression below applies when it has a density \(f\). The \emph{moment generating function} of \(X\) is defined to be
    \[
        m\pqty{\theta} = \Expt\bqty{e^{\theta X}} = \int_{\RR} e^{\theta x} f\pqty{x} \dd{x}
    \]
    where it is finite; the non-negative expectation may otherwise be \(+\infty\). Always \(m\pqty{0} = 1\).
\end{definition}

\begin{theorem}[Uniqueness of Moment Generating Function]\label{probability-theorem-022}
    \label{probability-thm:uniqueness-mgf}%
    The moment generating function uniquely determines the distribution of a random variable, provided it is finite on an open interval containing \(0\). This uniqueness theorem is used here without proof.
\end{theorem}

\begin{definition}[Gamma Distribution]\label{probability-definition-063}
    \label{probability-def:gamma-distribution}
The density is zero for \(x\le0\); the integer shape \(n\) satisfies \(n\ge1\).
%
    The \emph{Gamma Distribution} with parameters \(n \in \NN\) and \(\lambda > 0\), denoted by \(\Gamma\pqty{n, \lambda}\), is given by the density function
    \[
        f\pqty{x} = \frac{e^{-\lambda x} \cdot \lambda^n \cdot x^{n - 1}}{\pqty{n - 1}!}
    \]
    for \(x > 0\).
\end{definition}

\begin{proposition}[Gamma Distribution is a Distribution]\label{probability-proposition-041}
    \label{probability-prop:gamma-distribution-integral}%
    The Gamma Distribution is a distribution. In particular, its density function integrates to \(1\).
\end{proposition}

\begin{example}[Moment Generating Function of Gamma Distribution]\label{probability-example-040}
    \label{probability-ex:gamma-distribution-mgf}%
    We have
    \begin{align*}
        m\pqty{\theta} = \Expt\bqty{e^{\theta X}} &= \int_{0}^{\plusinfty} e^{\theta x} \cdot e^{- \lambda x} \cdot \frac{\lambda^n \cdot x^{n - 1}}{\pqty{n - 1}!} \dd{x} \\
        &= \int_{0}^{\plusinfty} e^{- \pqty{\lambda - \theta} x} \cdot \frac{\pqty{\lambda - \theta}^n \cdot x^{n - 1}}{\pqty{n - 1}!} \dd{x} \cdot \frac{\lambda^n}{\pqty{\lambda - \theta}^n}.
    \end{align*}

    Therefore, if \(\theta < \lambda\), then
    \[
        m \pqty{\theta} = \pqty{\frac{\lambda}{\lambda - \theta}}^n
    \]
    for \(\theta < \lambda\).
\end{example}

\begin{example}[Sum of Gamma Random Variables]\label{probability-example-041}
    \label{probability-ex:sum-gamma}%
    Let \(X \sim \Gamma\pqty{n, \lambda}\) and \(Y \sim \Gamma\pqty{m, \lambda}\), with \(n, m \in \NN\) and \(\lambda > 0\), and \(X \indp Y\).

    We have
    \begin{align*}
        \Expt\bqty{e^{\theta \pqty{X + Y}}} &= \Expt\bqty{e^{\theta X}} \cdot \Expt\bqty{e^{\theta Y}} \\
        &= \pqty{\frac{\lambda}{\lambda - \theta}}^n \cdot \pqty{\frac{\lambda}{\lambda - \theta}}^m \\
        &= \pqty{\frac{\lambda}{\lambda - \theta}}^{n + m},
    \end{align*}
    and hence \(X + Y \sim \Gamma\pqty{n + m, \lambda}\).
\end{example}

\begin{remark}\label{probability-remark-008}
    We specified for \(\Gamma\pqty{n, \lambda}\), that \(n \in \NN\). In fact, we may define \(\Gamma\pqty{\alpha, \lambda}\) for \(\alpha > 0\), where \(n\) is replaced by \(\alpha\), with the density function
    \[
        f\pqty{x} = \frac{e^{-\lambda x} \cdot \lambda^{\alpha} \cdot x^{\alpha - 1}}{\Gamma\pqty{\alpha}}
    \]
    where \(\Gamma\) is the \emph{Gamma Function}
    \[
        \Gamma\pqty{\alpha} = \int_{0}^{\plusinfty} e^{-x} \cdot x^{\alpha - 1} \dd{x}.
    \]
\end{remark}

\begin{definition}[Cauchy Distribution]\label{probability-definition-064}
    The \emph{Cauchy Distribution} is the continuous random variable defined by the density function
    \[
        f\pqty{x} = \frac{1}{\pi \pqty{1 + x^2}}
    \]
    for \(x \in \RR\).
\end{definition}

\begin{example}[Moment Generating Function of Normal Distribution]\label{probability-example-043}
    \label{probability-ex:mgf-normal}%
    For a normal distribution \(X \sim \Normal\pqty{\mu, \sigma^2}\), we have
    \[
        f\pqty{x} = \frac{1}{\sqrt{2 \pi \sigma^2}} \exp\pqty{- \frac{\pqty{x - \mu}^2}{2 \sigma^2}}
    \]
    for \(x \in \RR\). Therefore, we have
    \begin{align*}
        m\pqty{\theta} &= \Expt\bqty{e^{\theta X}} \\
        &= \int_{\minusinfty}^{\infty} e^{\theta x} \cdot \frac{1}{\sqrt{2 \pi \sigma^2}} \exp\pqty{- \frac{\pqty{x - \mu}^2}{2 \sigma^2}} \dd{x}.
    \end{align*}

    We may simplify the exponent as
    \begin{align*}
        \theta x - \frac{\pqty{x - \mu}^2}{2 \sigma^2} &= \theta x - \frac{x^2}{2 \sigma^2} + \frac{2 x \mu}{2 \sigma^2} - \frac{\mu^2}{2 \sigma^2} \\
        &= - \frac{x^2}{2 \sigma^2} + 2 \cdot \frac{x}{2 \sigma^2} \pqty{\mu + \theta \sigma^2} - \frac{\mu^2}{2 \sigma^2} \\
        &= - \frac{x^2}{2 \sigma^2} + 2 \cdot \frac{x}{2 \sigma^2} \pqty{\mu + \theta \sigma^2} - \frac{\pqty{\mu + \theta \sigma^2}^2}{2 \sigma^2} + \frac{\pqty{\mu + \theta \sigma^2}^2}{2 \sigma^2} - \frac{\mu^2}{2 \sigma^2} \\
        &= - \frac{1}{2 \sigma^2} \pqty{x - \pqty{\mu + \theta \sigma^2}}^2 + \frac{\mu^2}{2 \sigma^2} + \frac{2 \mu \theta \sigma^2}{2 \sigma^2} + \frac{\theta^2 \sigma^2}{2} - \frac{\mu^2}{2 \sigma^2} \\
        &= - \frac{1}{2 \sigma^2} \pqty{x - \pqty{\mu + \theta \sigma^2}}^2 + \mu \theta + \frac{\theta^2 \sigma^2}{2}.
    \end{align*}

    Therefore, we have
    \begin{align*}
        m\pqty{\theta} &= \int_{\minusinfty}^{\plusinfty} \frac{1}{\sqrt{2 \pi \sigma^2}} \exp\pqty{- \frac{\pqty{x - \pqty{\mu + \theta \sigma^2}}^2}{2 \sigma^2}} \dd{x}  \cdot \exp \pqty{\mu \theta + \frac{\theta^2 \sigma^2}{2}} \\
        &= \exp\pqty{\mu \theta + \frac{\theta^2 \sigma^2}{2}}.
    \end{align*}

    Now, suppose \(X \sim \Normal\pqty{\mu, \sigma^2}\) and \(Y \sim \Normal\pqty{\nu, \tau^2}\), and \(X \indp Y\).

    Then, we have
    \begin{align*}
        m\pqty{\theta} &= \Expt\bqty{e^{\theta \pqty{X + Y}}} \\
        &= \exp\pqty{\mu \theta + \frac{\theta^2 \sigma^2}{2}} \cdot \exp\pqty{\nu \theta + \frac{\theta^2 \tau^2}{2}} \\
        &= \exp\pqty{\pqty{\mu + \nu} \theta + \frac{\theta^2}{2} \pqty{\sigma^2 + \tau^2}}.
    \end{align*}

    Therefore, \(X + Y \sim \Normal\pqty{\mu + \nu, \sigma^2 + \tau^2}\).
\end{example}

\begin{definition}[Multivariate Moment Generating Function]\label{probability-definition-065}
    \label{probability-def:multivariate-mgf}%
    Let \(\vb{X} = \pqty{X_1, \ldots, X_n} \in \RR^n\) be an \(n\)-dimensional random variable. Its \emph{moment generating function} is defined to be
    \[
        m\pqty{\vb*{\theta}} = \Expt\bqty{e^{\vb*{\theta}\transpose \vb{X}}} = \Expt\bqty{e^{\sum_{i = 1}^{n} \theta_i X_i}}
    \]
    where \(\vb*{\theta} = \pqty{\theta_1, \ldots, \theta_n} \transpose\).
\end{definition}

\begin{theorem}[Uniqueness of Multivariate Moment Generating Function]\label{probability-theorem-024}
    \label{probability-thm:uniqueness-multivarite-mgf-moments}
Uniqueness is used without proof here. The derivative identities follow by dominated differentiation using exponential integrability in a neighbourhood of the origin.
%
    If the moment generating function is finite on an open neighbourhood of \(\vb{0}\), then it uniquely determines the distribution, and we have
    \[
        \rightbar{\pdv[r]{m}{\theta_i}}_{\vb*{\theta} = \vb{0}} = \Expt\bqty{X_i^r}
    \]
    and
    \[
        \rightbar{\frac{\partial^{r + s} m}{\partial \theta_i^r \partial \theta_j^s}}_{\vb*{\theta} = \vb{0}} = \Expt\bqty{X_i^r \cdot X_j^s}.
    \]
\end{theorem}

\begin{claim}[Independent Random Variables give Separable Moment Generating Function]\label{probability-claim-006}
    \label{probability-claim:independent-rv-separable-mgf}%
Assume the joint MGF is finite on a neighbourhood of the origin, and require the factorisation throughout that neighbourhood.
    Let \(\vb{X} = \pqty{X_1, \ldots, X_n} \in \RR^n\) be a random variable. Then
    \[
        m\pqty{\vb*{\theta}} = \prod_{i = 1}^{n} \Expt\bqty{e^{\theta_i X_i}}
    \]
    if and only if \(X_1, \ldots, X_n\) are independent.
\end{claim}

\begin{proof}\label{probability-proof-079}
    If they are independent, this statement is straightforward.

    If \(m\pqty{\vb*{\theta}}\) factorises, then by \autoref{probability-thm:uniqueness-multivarite-mgf-moments} (Uniqueness of Moment Generating Functions), we get that this \(\vb{X}\) agrees with the distribution when the \(X_i\)s are independent, so they must be independent.
\end{proof}

\begin{claim}[Affine Transformation of Gaussian is Gaussian]\label{probability-claim-007}
    \label{probability-claim:affine-transformation-preserves-gaussian}%
    Let \(\vb{X} = \pqty{X_1, \ldots, X_n} \in \RR^n\) be Gaussian. Let \(\vb{A}\) be an \(m \times n\) matrix, and \(\vb{b} \in \RR^m\). Then the result
    \[
        \vb{A} \vb{X} + \vb{b}
    \]
    is also Gaussian.
\end{claim}

\begin{proof}\label{probability-proof-081}
    Note that \(\vb*{\lambda \transpose \vb{X}}\) is a normal distribution with parameters
    \[
        \Normal\pqty{\vb*{\lambda}\transpose\vb*{\mu}, \vb*{\lambda}\transpose \vb{V} \vb*{\lambda}}
    \]
    by \autoref{probability-prop:expt-var-transform-multivariate-rv}. The result follows.
\end{proof}

\begin{notation}\label{probability-notation-003}
    We write the Multivariate Gaussian distribution \(\vb{X}\) with mean \(\vb*{\mu} \in \RR^n\), and non-negative definite matrix \(\vb{V}\), as
    \[
        \vb{X} \sim \Normal\pqty{\vb*{\mu}, \vb{V}}.
    \]
\end{notation}

\begin{proof}\label{probability-proof-082}
    We find the moment generating function of \(\vb{u} \transpose \vb{Z}\). We have
    \begin{align*}
        m\pqty{\lambda} &= \Expt\bqty{e^{\lambda \vb{u}\transpose \vb{Z}}} \\
        &= \Expt\bqty{e^{\lambda \sum_{i = 1}^{n} u_i Z_i}} \\
        &= \prod_{i = 1}^{n} \Expt\bqty{e^{\lambda u_i Z_i}} \\
        &= \prod_{i = 1}^{n} \exp\pqty{\frac{\lambda^2 u_i^2}{2}} \\
        &= \exp\pqty{\frac{\lambda^2 \abs{\vb{u}}^2}{2}}.
    \end{align*}

    Hence,
    \[
        \vb{u}\transpose \vb{Z} \sim \Normal \pqty{0, \abs{\vb{u}}^2}
    \]
    is normal, with the desired parameters, as desired.
\end{proof}

\begin{lemma}[Construction of Multivariate Gaussian]\label{probability-lemma-011}
    \label{probability-lem:construction-multivariate-gaussian}%
    Let \(\vb*{\mu} \in \RR^n\), and \(\vb{V}\) be a non-negative definite matrix. Let \(Z_1, \ldots, Z_n\) be identically and independently distributed with \(\Normal\pqty{0, 1}\). Let \(\vb{Z} = \pqty{Z_1, \ldots, Z_n}\).

    Then the random variable
    \[
        \vb{X} = \vb*{\mu} + \vb*{\sigma} \vb{Z}
    \]
    is Gaussian, with \(X \sim \Normal\pqty{\vb*{\mu}, \vb{V}}\), where \(\vb*{\sigma}\) is the square-root of \(\vb{V}\).
\end{lemma}

\begin{proof}\label{probability-proof-083}
    First, \(\vb{X}\) is Gaussian since it is a linear transformation of a Gaussian vector. We have \(\Expt\bqty{\vb{X}} = \vb*{\mu}\). For the variance, we have
    \begin{align*}
        \Var\pqty{\vb{X}} &= \Expt\bqty{\pqty{\vb{X} - \vb*{\mu}} \pqty{\vb{X} - \vb*{\mu}}\transpose} \\
        &= \Expt\bqty{\pqty{\vb*{\sigma} \vb{Z}} \pqty{\vb{Z}\transpose \vb*{\sigma}\transpose}} \\
        &= \vb*{\sigma} \Expt\bqty{\vb{Z} \vb{Z}\transpose} \vb*{\sigma}\transpose \\
        &= \vb*{\sigma} \identityM_n \vb*{\sigma}\transpose \\
        &= \vb*{\sigma} \vb*{\sigma}\transpose \\
        &= \vb{V}.
    \end{align*}
\end{proof}

\begin{proposition}[Density of Multivariate Gaussian with Positive Definite Variance]\label{probability-proposition-043}
    If \(\vb{V}\) is positive definite, then the density of \(\Normal\pqty{\vb*{\mu}, \vb{V}}\) is given by
    \[
        f_{\vb{X}}\pqty{\vb{x}} = \frac{1}{\sqrt{\pqty{2\pi}^n \det \vb{V}}} \exp\pqty{- \frac{\pqty{\vb{x} - \vb*{\mu}}\transpose \vb{V}\inverse \pqty{\vb{x} - \vb*{\mu}}}{2}}.
    \]
\end{proposition}

\begin{lemma}[Diagonal Variance implies Independence for Gaussian]\label{probability-lemma-012}
    \label{probability-lem:diagonal-variance-independence-gaussian}%
    Let \(\vb{X} \sim \Normal\pqty{\vb*{\mu}, \vb{V}}\) where \(\vb{V}\) is non-negative definite. If \(\vb{V}\) is diagonal, then the \(X_i\)s are independent.
\end{lemma}

\begin{proof}[\proofname\ using Moment Generating Function]\label{probability-proof-086}
    We inspect the moment generation function. Recall that
    \[
        \vb*{\theta}\transpose \vb{X} \sim \Normal\pqty{\vb*{\theta}\transpose \vb*{\mu}, \vb*{\theta}\transpose \vb{V} \vb*{\theta}}.
    \]

    We have
    \begin{align*}
        m\pqty{\vb*{\theta}} &= \exp\pqty{\vb*{\theta}\transpose \vb*{\mu} + \frac{\vb*{\theta}\transpose \vb{V} \vb*{\theta}}{2}} \\
        &= \exp\pqty{\sum_{i = 1}^{n} \theta_i \mu_i + \sum_{i = 1}^{n} \frac{\theta_i^2 \lambda_i}{2}} \\
        &= \prod_{i = 1}^{n} \exp\pqty{\theta_i \mu_i + \frac{\theta_i^2 \lambda_i}{2}}
    \end{align*}
    factorised into moment generating functions for \(\Normal\pqty{\mu_i, \lambda_i}\). Therefore, \(X_1, \ldots, X_n\) are independent.
\end{proof}

\begin{definition}[Bivariate Gaussian Vector]\label{probability-definition-067}
    \label{probability-def:bivariate-gaussian-vector}%
    The 2-Dimensional case of a multivariate Gaussian random variable, defined in \autoref{probability-def:multivariate-gaussian-rv}, is known as a \emph{Bivariate Gaussian Vector}.
\end{definition}

\begin{proof}\label{probability-proof-087}
    Let \(Y = X_2 - a X_1\) for some \(a \in \RR\). Then the vector
    \[
        \pmqty{X_1 \\ Y}
        =
        \pmqty{
            1 & 0 \\
            -a & 1
        }
        \pmqty{X_1 \\ X_2}
    \]
    is Gaussian. The covariance satisfies
    \[
        \Cov\pqty{X_1, Y} = \Cov\pqty{X_1, X_2 - a X_1} = \Cov\pqty{X_1, X_2} - a \Var\pqty{X_1}.
    \]

    Taking
    \[
        a = \frac{\Cov\pqty{X_1, X_2}}{\Var\pqty{X_1}}
    \]
    gives \(\Cov\pqty{X_1, Y} = 0\), which in turn makes them independent. Hence,
    \begin{align*}
        \Expt\bqty{\Conditional{X_2}{X_1}} &= \Expt\bqty{\Conditional{X_2 - a X_1}{X_1}} + \Expt\bqty{\Conditional{a X_1}{X_1}} \\
        &= \Expt\bqty{X_2 - a X_1} + a X_1 \\
        &= \mu_2 - a \mu_1 + a X_1.
    \end{align*}
\end{proof}

\begin{remark}[Degenerate conditioning coordinate]\label{probability-remark-010}
If \(\Var(X_1)=0\), then \(X_1=\mu_1\) almost surely, and
\(\Expt[X_2\mid X_1]=\mu_2\) almost surely. No division by \(\Var(X_1)\) is used.
A singular Gaussian covariance gives a law on a proper affine subspace and
no density with respect to full-dimensional Lebesgue measure.
\end{remark}

\begin{proof}[\proofname\ for Finite Variance]\label{probability-proof-088}
    We give the proof when there is a finite variance. This is not a necessary assumption, but we are using this fact in our proof.

    Let \(\sigma^2\) be the variance and is finite. Then we have
    \begin{align*}
        \Prob\pqty{\abs{\frac{S_n}{n} - \mu} > \epsilon} &= \Prob\pqty{\abs{S_n - n \mu} > n \epsilon} \\
        &\leq \frac{\Var\pqty{S_n}}{n^2 \epsilon^2} \\
        &= \frac{n \sigma^2}{n^2 \epsilon^2} \\
        &= \frac{\sigma^2}{n \epsilon^2} \\
        &\to 0,
    \end{align*}
    by Chebyshev's Inequality, as desired.
\end{proof}

\begin{claim}[Almost Sure Convergence to \(0\) implies Convergence in Probability]\label{probability-claim-008}
    \label{probability-claim:almost-sure-convergence-implies-convergence-in-probability}%
    If \(X_n \toAlmostSure 0\) as \(n \to \infty\), then \(X_n \toProb 0\) as \(n \to \infty\).
\end{claim}

\begin{claim}[Convergence in Probability implies Convergence in Distribution]\label{probability-claim-009}
    \label{probability-claim:convergence-in-probability-implies-converges-in-distribution}%
    If \(X_n \toProb X\) as \(n \to \infty\), then \(X_n \toDist X\) as \(n \to \infty\).
\end{claim}

\begin{theorem}[Continuity Property for Moment Generating Functions]\label{probability-theorem-028}
    \label{probability-thm:continuity-property-mgf}
Let \(X_n,X\) be real random variables. Suppose that for some \(\delta>0\),
\(m_n(t)=\Expt[e^{tX_n}]\) and \(m(t)=\Expt[e^{tX}]\) are finite for every
\(t\in(-\delta,\delta)\), and \(m_n(t)\to m(t)\) for every such \(t\).
Then \(X_n\toDist X\). This continuity theorem is used without proof.
\end{theorem}

\begin{remark}[Termination and numerical endpoints]\label{probability-remark-012}
For rejection from the unit cube, \(N\sim\GeomOne(|A|)\), hence termination
is almost sure and \(\Expt[N]=1/|A|\). In inverse-transform and Box--Muller
simulation use uniforms strictly between zero and one; a numerical generator
that can return zero needs explicit handling before taking a logarithm.
\end{remark}

\begin{definition}[Bernoulli reference]\label{probability-definition-071}
For \(0\le p\le1\), \(X\sim\Bernoulli(p)\) has support \(\{0,1\}\):
\[\Prob(X=x)=p^x(1-p)^{1-x},\quad
\Expt[X]=p,\quad \Var(X)=p(1-p),\quad G_X(z)=1-p+pz.\]
Use \(0^0=1\) at the parameter endpoints.
\end{definition}

\begin{proof}[Moments of the hypergeometric law]\label{probability-proof-094}
Write \(X=\sum_{i=1}^K I_i\), where \(I_i\) indicates inclusion of marked
object \(i\). Then \(\Expt[I_i]=n/N\), and, for \(i\ne j\),
\(\Expt[I_iI_j]=n(n-1)/(N(N-1))\). Expanding \(\Expt[X^2]\) and
subtracting \((nK/N)^2\) gives the stated variance.
\end{proof}

\begin{proof}\label{probability-proof-095}
The final trial is a success and the preceding \(x+r-1\) trials contain
\(r-1\) successes, giving the PMF. Equivalently, \(X\) is the sum of
\(r\) independent \(\GeomZero(p)\) variables; multiplying PGFs and adding
means and variances gives the other formulas.
\end{proof}

\begin{definition}[Poisson reference]\label{probability-definition-076}
For \(\lambda>0\), \(X\sim\Poisson(\lambda)\) has support \(\NN_0\) and
\[\Prob(X=x)=e^{-\lambda}\frac{\lambda^x}{x!},\quad
\Expt[X]=\Var(X)=\lambda,\quad G_X(z)=e^{\lambda(z-1)}.\]
\end{definition}

\begin{proof}[Covariances]\label{probability-proof-096}
Write each count as a sum of trial indicators. Indicators from distinct trials
are independent. Within a trial two distinct categories cannot both occur,
so their covariance is \(-p_ip_j\). Summing over trials proves the formula.
\end{proof}

\begin{definition}[Evenly Covered Set]
Suppose $p:\hat X\to X$ is continuous. An open set $U\subseteq X$ is evenly covered if $p^{-1}(U)=\bigsqcup_\alpha V_\alpha$, where the $V_\alpha$ are pairwise disjoint open subsets of $\hat X$ and each restriction $p|_{V_\alpha}:V_\alpha\to U$ is a homeomorphism.
\end{definition}

\begin{definition}[Covering Map]
  A map $p: \hat{X} \rightarrow X$ is a covering map if for all $x \in X$, there exists an open neighbourhood $U_x$ which is evenly covered. In this case, we call $\hat{X}$ a covering space for $X$.
\end{definition}

\begin{definition}[Lift]
  Suppose $p: \hat{X} \rightarrow X$ is a covering map, $f: Z \rightarrow X$ continuous. Then we say that $\hat{f}: Z \rightarrow \hat{X}$ is a lift of $f$ if $p \circ \hat{f}=f$, that is,
  {\color{red} DIAGRAM}
  commutes.
\end{definition}

\begin{lemma}[Lebesgue Covering]
Suppose $X$ is a compact metric space, $\left\{U_\alpha\right\}_\alpha$ is an open cover of $X$. Then there exists $\delta>0$ such that for all $x \in X, B_\delta(x) \subseteq U_\alpha$ for some $\alpha$.
\end{lemma}

\begin{proof}
  Given $x \in X$, let $\alpha(x)$ and $\delta(x)>0$ be such that $B_{2 \delta(x)}(x) \subseteq U_{\alpha(x)}$. Then $\left\{B_{\delta(x)}\right\}_{x \in X}$ is an open cover of $X$. Therefore, by compactness there exists a finite subcover $\left\{B_{\delta\left(x_i\right)}\left(x_i\right)\right\}_{i=1}^n$. Let $\delta=\min \{\delta\left(x_1\right),$ $\ldots, \delta\left(x_n\right)\}$. Then for all $y \in X, y \in B_{\delta\left(x_i\right)}\left(x_i\right)$ for all $i$. Then
  $$
  B_\delta(y) \subseteq B_{2 \delta\left(x_i\right)}\left(x_i\right) \subseteq U_{\alpha\left(x_i\right)}
  $$
\end{proof}

\begin{notation}
 We say a path $\gamma$ with $\gamma(0)=x_0$ has the (unique) lifting property if for all $\hat{x}_0 \in p^{-1}\left(x_0\right)$, there exists a (unique) lift $\hat{\gamma}$ of $\gamma$ with $\hat{\gamma}(0)=\hat{x}_0$.
\end{notation}

\begin{lemma}
If $f: Z \rightarrow U, Z$ connected, $\operatorname{im}(f) \subseteq U$, where $U$ is evenly covered, then $\gamma$ has the unique lifting property.
\end{lemma}

\begin{proof}
Since $U$ is evenly covered, $p^{-1}(U)=\sqcup_\alpha V_\alpha$. Then $\hat{x} \in V_{\alpha_0}$ for some $\alpha_0$. Then $p^{\prime}=\left(p \mid v_{\alpha_0}\right)^{-1}: U \rightarrow \hat{X}$ is continuous, with $p^{\prime}\left(x_0\right)=\hat{x}_0$, so $\hat{f}=p^{\prime} \circ f$ is a lift of $f$.

For uniqueness, notice that $p^{-1}(U)=U_{\alpha_0} \sqcup\left(\sqcup_{\alpha \neq \alpha_0} V_\alpha\right)$, which disconnects $p^{-1}(U)$, and as $\mathrm{im}(f)$ is connected, $\operatorname{im}(\hat{f}) \subseteq V_{\alpha_0}$. But $p^{\prime}$ above is a homeomorphism, so $\hat{\gamma}$ is unique.
\end{proof}

\begin{lemma}
  Suppose $\gamma:[a, b] \rightarrow X$ with $a^{\prime} \in[a, b]$, if $\left.\gamma\right|_{\left[a, a^{\prime}\right]}$ has the ULP at $a$ and $\left.\gamma\right|_{\left[a^{\prime}, b\right]}$ has the ULP at $a^{\prime}$, then $\gamma$ has the ULP at $a$.
\end{lemma}

\begin{proof}
  We have a lift $\hat{\gamma}_1:\left[a, a^{\prime}\right] \rightarrow \hat{X}$ of $\left.\gamma\right|_{\left[a, a^{\prime}\right]}$ at $a$, and a lift $\hat{\gamma}_2:\left[a^{\prime}, b\right] \rightarrow \hat{X}$ of $\left.\gamma\right|_{\left[a^{\prime}, b\right]}$ at $a^{\prime}$, such that $\hat{\gamma}_1\left(a^{\prime}\right)=\hat{\gamma}_2\left(a^{\prime}\right)$. So $\hat{\gamma}_1 \hat{\gamma}_2$ is a lift of $\gamma$ at $a$.

For uniqueness, suppose $\hat{\eta}$ is any other lift. Then $\left.\hat{\eta}\right|_{\left[a, a^{\prime}\right]}$ is a lift of $\left.\gamma\right|_{\left[a^{\prime}, a\right]}$, so $\left.\hat{\hat{n}}\right|_{\left[a, a^{\prime}\right]}=\hat{\gamma}_1$. This means that
\end{proof}

\begin{theorem}[Path Lifting]
  Any $\gamma: I \rightarrow X$ has the ULP.
\end{theorem}

\begin{proof}
  $p: \hat{X} \rightarrow X$ is a covering map, so every $x \in X$ has an evenly covered neighbourhood $U_x$. Then $\left\{U_x \mid x \in X\right\}$, so $\left\{\gamma^{-1}\left(U_x\right) \mid x \in X\right\}$ is an open cover of $I$. Thus, by the Lebesgue covering lemma, there exists $\delta>0$ such that $B_\delta(t) \subseteq \gamma^{-1}\left(U_{x(t)}\right)$ for any $t$

Choose $n$ such that $1 / n<\delta, a_i=i / n \in I$. Then $\left[a_i, a_{i+1}\right] \subseteq B_\delta\left(a_i\right)$, so $\gamma\left(\left[a_i, a_{i+1}\right]\right) \subseteq U_{x_i}$, where $a_i=\gamma\left(a_i\right)$. As $U_{x_i}$ is evenly covered, $\left.\gamma\right|_{\left[a_i, a_{i+1}\right]}$ has the ULP at $a_i$. By induction and the previous lemma, $\gamma$ has the ULP.
\end{proof}

\begin{theorem}[Homotopy Lifting]
   Suppose $p: \hat{X} \rightarrow X$ is a covering map, $H: I \times I \rightarrow X$ is a homotopy, then $H$ has the lifting property at $(0,0)$.
\end{theorem}

\begin{proof}
  Suppose $\left\{U_x \mid x \in X\right\}$ is an open cover of $X$ by evenly covered neighbourhoods. Since $l^2$ is compact, by the Lebesgue covering lemma, there exists $\delta>0$ such that $B_\delta(v) \subseteq H^{-1}\left(U_{H(v)}\right)$ for each $v \in R^2$.

Choose $n$ such that $\sqrt{2} / n<\delta$. Then divide $R^2$ into squares with side lengths $1 / n$. Enumerate them $A_1$, $A_2$, $\ldots$, $A_{n^2}$, starting from the bottom left and going right then up. Label the bottom left corner of $A_i$ as $v_i$. Now note that $H\left(A_i\right) \subseteq H\left(B_\delta\left(v_i\right)\right) \subseteq U_{x_i}$ is evenly covered. Thus, $H_{A_i}$ has the ULP at $v_i$, as $l^2$ is connected. Let $B_k=\bigcup_{i=1}^k A_i$

We will prove by induction that $\left.H\right|_{B_k}$ has $L P$ at $(0,0)$. For $k=1, B_1=A_1$, so we are done. Now suppose $\left.H\right|_{B_k}$ has a lift $\hat{H}: B_k \rightarrow X$ with $\hat{H}_k(0,0)=\hat{X}$. Now as $\left.H\right|_{A_k}$ has the lifting property at $v_{k+1}$. So choose a lift $\hat{h}_k: A_{k+1} \rightarrow \hat{X}$ with $\hat{h}_k\left(v_{k+1}\right)=\hat{H}^k\left(v_{k+1}\right)$.

Now note that $B_k \cap A_{k+1}$ is either one or two edges of $A_{k+1}$, both coming from $v_{k+1}$. By uniqueness of path lifting, $\left.\hat{H}_k\right|_{A_{k+1} \cap B_k}=\hat{h}_k \mid A_{k+1} \cap B_k$, so by the gluing lemma we have a well defined lift $\hat{H}_{k+1}$ of $H$ on $B_{k+1}$.
\end{proof}

