\begin{lemma}[Key Lemma]
Let $L/K$ be an extension of fields, and $f\in K[x]$ be irreducible. There is a bijection:
\begin{align*}
\{K-homomorphisms \phi:K_f \rightarrow L\} \longleftrightarrow roots of $f$ in L = \{\tilde{\alpha}\in L|f(\tilde{\alpha}) = 0 \}
\end{align*}
\end{lemma}

