\begin{corollary}
If $K=\mathbb{Q}, L=\mathbb{Q}(\xi)$, then $[L:\mathbb{Q}] = \#(\mathbb{Z}/n\mathbb{Z})^{\ast}$, and $\chi:\aut(L/\mathbb{Q}) \to (\mathbb{Z}/n\mathbb{Z})^{\ast}$ is an isomorphism.
\end{corollary}

If we write $\mathbb{Q}(\xi_n)$ for the $n\th$ cyclotomic field, the extension of $\mathbb{Q}$ by a primitive $n\th$ root of $1$ called $\xi_n$, then this is the splitting field of $x^n-1$.

We've shown that $[\mathbb{Q}(\xi_n):\mathbb{Q}] = (\mathbb{Z}/n\mathbb{Z})^{\ast}$, so the fundamental theorem of Galois theory says that for all subgroups $H \leq (\mathbb{Z}/n\mathbb{Z})^{\ast}$, we have an intermediate field $M = \mathbb{Q}(\xi_n)^H$, and as $(\mathbb{Z}/n\mathbb{Z})^{\ast}$ is abelian, in fact $H \trianglelefteq G$, so we have $M/\mathbb{Q}$ is Galois with Galois group $(\mathbb{Z}/n\mathbb{Z})^{\ast}/H$.

So now the natural thing to consider is the structure of $(\mathbb{Z}/n\mathbb{Z})^{\ast}$, and the corresponding subfields.

\underline{Examples:}
\begin{enumerate}
\item $n=p$, a prime. Then $(\mathbb{Z}/p\mathbb{Z})^{\ast} = \F_p^{\ast} \cong \mathbb{Z}_{p-1}$. Then there is a unique intermediate subfield $\mathbb{Q} \subseteq M \subseteq \mathbb{Q}(\xi_n)$ with $[M:\mathbb{Q}] = k$ for each $k|(p-1)$.
\begin{enumerate}
\item $p=5$, so we have $\mathbb{Z}_4$, giving a unique intermediate field of degree 2 over $\mathbb{Q}$. It is generated by $\xi+\xi^{-1} = \frac{1}{2}(-1+\sqrt{5})$, and so we have $\mathbb{Q} \subsetneq \mathbb{Q}(\sqrt{5})\subsetneq \mathbb{Q}(\xi_5)$.

More generally,

\begin{lemma}
For any $n \geq 3$, the unique subfield $M \leq \mathbb{Q}(\xi_n)$ with $[M:\mathbb{Q}] = \frac{\#(\mathbb{Z}/n\mathbb{Z})^{\ast}}{2}$ is $M = \mathbb{Q}(\cos(2\pi/n)) = \mathbb{Q}(\eta)$, where $\eta  = \xi+\xi^{-1}$. In particular, $2 | \#(\mathbb{Z}/n\mathbb{Z})^{\ast}$.
\end{lemma}

\begin{proof}
By the fundamental theorem of Galois theory, there is some unique M with $[\mathbb{Q}(\xi):M] = 2$. But $\xi$ is a root of the quadratic polynomial $x^2-\eta x+1 = 0$, and so $[\mathbb{Q}(\xi):\mathbb{Q}(\eta)] \leq 2$. But note that complex conjugation fixes $\mathbb{Q}(\eta)$ but not $\mathbb{Q}(\xi)$, hence $\mathbb{Q}(\xi)\neq \mathbb{Q}(\eta)$, so $M = \mathbb{Q}(\eta)$.
\end{proof}

\begin{proposition}
Let $p$ be prime $>2$. Then the unique quadratic extension of $\mathbb{Q}$ contained in $\mathbb{Q}(\xi_p)$ is $\mathbb{Q}(\sqrt{\pm p})$ where the sign is $(-1)^{(p-1)/2}$.
\end{proposition}

\begin{corollary}
Take $f(x) = x^p-1$, so that $f'(x) = px^{p-1}$. Then $\Delta(f) = (-1)^{p(p-1)/2} p^p \xi^{(1+2+\ldots +p-1)(p-1)} = \pm 1 p^p = (-1)^{(p-1)/2} p^p$
\end{corollary}

\begin{corollary}
$\aut(\mathbb{Q}_p(\xi_p)/\mathbb{Q}) \not\subseteq A_n$.
\end{corollary}

\begin{theorem}[Gauss]
A regular $n$-gon is constructible iff it is of the form:
\begin{center}
$n = 2^k p_1\ldots p_r$ where $p_i$ are distinct primes of the form $2^{2^\ell} + 1$.
\end{center}
These primes are known as Fermat primes, and the only known ones are 3, 5, 17, 257, 65537.
\end{theorem}

