Title: Subdivision
Content:
\begin{definition}[Subdivision]
 A subdivision of a compact topological surface $\Sigma$ consists of 
 \begin{enumerate}[label=(\roman*)]
 \item A finite set $V \subseteq \Sigma$ of vertices;
 \item A finite collection of continuous embeddings $\{e_i : [0, 1] \rightarrow \Sigma\}$ called edges, each of which has endpoints in $V$, and any two of which meet at endpoints;
 \item The connected components of $\Sigma \backslash \left[V \cup \bigcup_i e_i([0, 1])\right]$ are each homeomorphic to an open disk called a face.
 \end{enumerate}
\end{definition}

latex:
\begin{definition}[Subdivision]
    A \vocab{subdivision} of a compact topological surface $\Sigma$ consists of 
    \begin{enumerate}[label=(\roman*)]
        \item A finite set $V \subseteq \Sigma$ of \vocab{vertices};
        \item A finite collection of continuous embeddings $\{e_i : [0, 1] \rightarrow \Sigma\}$ called \vocab{edges}, each of which has endpoints in $V$, and any two of which meet at endpoints;
        \item The connected components of $\Sigma \backslash \left[V \cup \bigcup_i e_i([0, 1])\right]$ are each homeomorphic to an open disk called a \vocab{face}.
    \end{enumerate}
\end{definition}

\begin{definition}[Triangulation]
    A subdivision is a \vocab{triangulation} if each \emph{closed} face (the closure of a face) contains exactly 3 edges and two closed faces are either disjoint or meet in exactly one edge.    
\end{definition}

