\begin{theorem}[Euler's Relation]~
    \vspace*{-1.5\baselineskip}
\begin{enumerate}[label=(\roman*)]
    \item Every compact topological surface admits subdivisions, and indeed triangulations.
    \item The Euler characteristic, denoted $\chi(\Sigma)$, does not depend on the choice of subdivision, and thus defines a topological invariant of the surface.
\end{enumerate}
\end{theorem}

\begin{example}[Euler's Relation for Various Surfaces]
    Considering some of our previous examples, we can see that
    \begin{enumerate}[label=(\roman*)]
        \item $\chi(S^2) = 2$;
        \item $\chi(T^2) = 0$;
        \item If $\Sigma_1$ and $\Sigma_2$ are compact topological surfaces, we can form $\Sigma_1 \# \Sigma_2$ by removing an open disk which is the face of a triangulation, and gluing the boundary circles gives us that
        $$
        \chi(\Sigma_1 \# \Sigma_2) = \chi(\Sigma_1) + \chi(\Sigma_2) - 2.
        $$
        In particular, if a surface has $g$ holes, then considering it as homeomorphic to connect sum of $g$ copies of $T^2$, we get that $\chi(\Sigma_g) = 2 - 2g$. The number $g$ is called the \vocab{genus} of $\Sigma$.
    \end{enumerate}
\end{example}

\begin{definition}[Chart]
    A pair $(U, \phi)$ where $U \subseteq \Sigma$ and $\phi$ is a homeomorphism $\phi: U \rightarrow V$ where $V$ is open in $\mathbb{R}^2$ is called a \vocab{chart} for $\Sigma$.
\end{definition}

\begin{definition}[Atlas]
    A collection of charts $\{(U_i, \phi_i) \mid i \in I\}$ such that $\bigcup_{i \in I} U_i = \Sigma$ is called an \vocab{atlas} for $\Sigma$.
\end{definition}

\begin{example}[Trivial Example of an Atlas]
    Recall that any open subset $U$ of $\mathbb{R}^2$ is a topological surface. Then taking $(U, \operatorname{Id})$ gives us an atlas with one chart. 
\end{example}

\begin{example}[Atlas for $S^2$]
    For $S^2$, we have an atlas with 2 charts, the 2 stereographic projections.
\end{example}

