\begin{definition}[Abstract Smooth Surface]
    An \vocab{abstract smooth surface} $\Sigma$ is a topological surface with an atlas of charts $\{(U_i, \phi_i) \mid i \in I\}$ with $\bigcup_{i \in I} U_i = \Sigma$ such that all of the transition maps $\phi_j(U_i \cap U_j) \rightarrow \phi_i(U_i \cap U_j)$ are diffeomorphisms of open sets in $\mathbb{R}^2$.
\end{definition}

\begin{remark}
    It would \emph{not} make sense to ask for the maps $\phi_i$ themselves to be smooth, as $\Sigma$ is just a topological space.
\end{remark}

\begin{example}[$S^2$ with Stereographic Projection]
    The atlas of 2 charts with stereographic projection gives $S^2$ the structure of an abstract smooth surface.
\end{example}

\begin{remark}[Philosophical]
    Being a topological surface is \emph{structure}, one can ask if a topological space $X$ is a topological surface or not. But being an abstract smooth surface is \emph{data}, in that one has to be given an atlas of charts with smooth transition maths with smooth inverses, and there could be many.
\end{remark}

\begin{definition}[Smooth at a Point]
    Let $\Sigma$ be an abstract smooth surface, and if $f: \Sigma \rightarrow \mathbb{R}^n$ is a continuous map then we say that $f$ is \vocab{smooth} at $p \in \Sigma$ if whenever $(U, \phi)$ is a chart at $p$ belonging to the smooth atlas for $\Sigma$, the map $f \circ \phi^{-1}: \phi(U) \rightarrow \mathbb{R}^n$ is smooth.
\end{definition}

\begin{definition}[Diffeomorphic]
    Two abstract smooth surfaces $\Sigma_1$ and $\Sigma_2$ are \vocab{diffeomorphic} if there exists a homeomorphism $f: \Sigma_1 \rightarrow \Sigma_2$ which is smooth and has a smooth inverse.
\end{definition}

\begin{remark}
    We often pass from a given smooth atlas for an abstract smooth surfaces $\Sigma$ to the maximal `compatible' such atlas, that is, I add to the atlas $\{(U_i, \phi_i) \mid i \in I\}$ for $\Sigma$ \emph{all} charts $(V, \psi)$ with the property that the transition maps are  still all diffeomorphisms. Such a process technically involved Zorn's lemma.
\end{remark}

\begin{definition}[Graph]
	A \vocab{graph} is an ordered pair $G = (V, E)$ where $V$ is the set of \vocab{vertices}, and $E \subseteq \{ \{x,y\} \mid x, y \in V, x \neq y \}$ is a set of unordered pairs of vertices called \vocab{edges}.
\end{definition}

