\begin{definition}[Edge Disjoint Paths]
	We say that the $uv$ paths $P_1, \dots, P_k$ are \vocab{edge disjoint} if $E(P_i) \cap E(P_j) = \emptyset$ for all $i \neq j$.
\end{definition}

