This clearly doesn't have a monochromatic $K_t$ subgraph, and we can compute the number of vertices is $(t - 1)^2$, giving
$$
R(t) \geq (t - 1)^2.
$$
However, it turns out that this quadratic bound is, quite frankly, awful. To show something better, we are going to need a new idea -- considering random graphs and using probability.

\begin{theorem}[Erdős]
	$R(t) \geq 2^{\frac t2}$.
\end{theorem}

\begin{proof}
	We will show that for a random colouring of the edges of $K_n$,
	$$
	\PP(\text{there exists a monochromatic $K_t \subset K_n$}) \leq 2 \binom{n}{t} 2^{-\binom{t}{2}}.
	$$
	Once we have shown this, we will then note for $n = 2^{t/2}$ that the RHS of this inequality is strictly less than 1, which implies that is \emph{some} colouring of $K_n$ with no monochromatic $K_t$.

	To prove this inequality, we first fix some $A \subseteq K_n$ with $|A| = t$, and note that
	$$
\mathbb{P}(A^{(2)}\text{ is monochromatic}) = 2 \cdot 2^{-\binom{t}{2}}.
	$$
	Applying the union bound then gives us our desired result
	\begin{align*}
		\PP(\text{there exists a monochromatic $K_t \subset K_n$}) &\leq \sum_{A \in K_n^{(t)}} 2 \cdot 2^{-\binom{t}{2}} = 2 \binom{n}{t} 2^{-\binom{t}{2}}.
	\end{align*}
	Then to show that this is less than 1 for $n = 2^{t/2}$, we can take
	\begin{align*}
		2 \binom{n}{t} 2^{-\binom{t}{2}} \leq 2 \frac{n^t}{t!}2^{\frac{t(t-1)}{2}} = \left(\frac{2^{1/t}}{t!^{1/t}} \cdot n 2^{-\frac{t - 1}{2}}\right)^t,
	\end{align*}
	and thus it is indeed less than 1 for $n = 2^{t/2}$.
\end{proof}

\begin{definition}[Binomial Random Graph]
	Let $n \in \N$ and $p \in [0, 1]$, let $\GG(n, p)$ be the probability space on all graphs with vertex set $\{1, 2, \dots, n\}$, with $\PP(ij \in E(\GG)) = p$, and every edge included/excluded independently.
\end{definition}

\begin{remark}
	For our `$R(t) \geq 2^{t/2}$' result, we were working with $G(n, 1/2)$, which is the same as sampling uniformly on a graph on $\{1, \dots, n\}$.
\end{remark}

\begin{theorem}
	We have $Z(n, t) \geq \frac{1}{4}n^{2 - \frac{2}{t + 1}}$.
\end{theorem}

\begin{definition}[Girth]
	The \vocab{girth} of a graph $G$ is the length of the shortest cycle in $G$, denoted $\girth(G)$.
\end{definition}

\begin{definition}[Independent Set]
	An \vocab{independent set} in a graph is a subset of vertices no two of which are adjacent. We will denote the size of the largest independent set $\alpha(G)$.
\end{definition}

\begin{theorem}
	For every $k, G \in \N$, there exists a graph $G$ with $\girth(G) \geq g$ and $\chi(G) \geq k$.
\end{theorem}

So what does a typical graph sampled from $\GG(n, p)$ look like? What does its structure look like as $p$ varies from 0 to 1? As a first example, we will consider the following more precise question:

\begin{center}
	For what $p$ does $G$ sampled from $\GG(n, p)$ contain a $K_t$?
\end{center}

\begin{theorem}
	Let $G$ be sampled from $\GG(n, p(n))$, and let $t \in \N$. Then
	$\lim_{n \to \infty} \PP(G \text{ contains a $K_t$}) \rightarrow 1$ if $p(n)n^{\frac{2}{t - 1}} \rightarrow \infty$.
	Moreover, $\lim_{n \to \infty} \PP(\text{$G$ contains $K_t$}) \rightarrow 0$ if $p(n) n^{\frac{2}{t - 1}} \rightarrow 0$.
\end{theorem}

This is an example of a threshold result, where almost suddenly when $p$ goes to a  certain value, we start to see some consistent structure in the random graphs.
Another somewhat similar question is:
\begin{center}
	What is the threshold for the graph to be connected?
\end{center}
We will find that this `transition' will be much faster than with the previous example.

\begin{theorem}
	Let $G$ be sampled from $\GG(n, p(n))$, then $\lim_{n \to \infty} \PP(\text{$G$ is connected}) = 1$ if $p > (1 + \epsilon)\frac{\log n}{n}$ and $\lim_{n \to \infty} \PP(\text{$G$ is disconnected}) = 0$ if $p < (1 - \epsilon) \frac{\log n}{n}$. 
\end{theorem}

\begin{definition}[Moore Graph]
	A \vocab{Moore graph} is a $k$-regular graph on $k^2 + 1$ vertices that has diameter 2.
\end{definition}

\begin{remark}
	A Moore graph is a $k$-regular graph for which any $x \neq y$ with $x, y \in V(G)$ has exactly one path of length $\leq 2$ between $x$ and $y$.
\end{remark}

\begin{definition}[Adjacency Matrix]
	Given a graph $G = (V, E)$ on $n$ vertices, we define the \vocab{adjacency matrix} of $G$ to be the $n \times n$ matrix
	$$
	A_{ij} = \begin{cases}
		1 &\mbox{if } ij \in E, \\
		0 &\mbox{otherwise}.
	   \end{cases}
	$$
\end{definition}

