\begin{theorem}[The Fundamental Theorem of Finite Abelian Groups]
	Every finite abelian group is isomorphic to the direct product of cyclic groups.
\end{theorem}

\begin{lemma}
	If $m$ and $n$ are coprime, then $C_{mn} = C_m \times C_n$.
\end{lemma}

\begin{proof}
	Let $g$ and $h$ be generators of $C_m$ and $C_n$. Then we have $(g, h) \in C_m \times C_n$, and $(g, h)^r = (g^r, h^r)$. In particular, $(g, h)^r = e$ if and only if $m \mid r$ and $n \mid r$, that is, if $mn \mid r$ since they are coprime. Thus $(g, h)$ has order $mn$, which is $|C_m \times C_n|$.
\end{proof}

\begin{corollary}
	Let $G$ be a finite abelian group.
	Then $G \cong C_{n_1} \times C_{n_2} \times \cdots \times C_{n_k}$ where each $n_i$ is a prime power.
\end{corollary}

\begin{proof}
	If $n = p_1^{a_1} \cdots p_r^{a_r}$, with $p_i$ prime, then we can (by the previous lemma) write $C_{n} \cong C_{p_1^{a_1}} \times \cdots \times C_{p_r^{a_r}}$. Writing each of the cyclic groups in the fundamental theorem of abelian groups then gives the result.
\end{proof}

\begin{remark}
	The integers $n_1, \dots, n_k$ in the previous corollary and $d_1, \dots, d_t$ in the previous theorem are uniquely determined by $G$.
	The proof (which we omit) works by counting the number of elements of each prime power order.
\end{remark}

\begin{example}[Abelian Groups of Order 8]
	The abelian groups of order 8 are $C_8$, $C_2 \times C_4$ and $C_2 \times C_2 \times C_2$.
\end{example}

\begin{example}[Abelian Groups of Order 12]
	The abelian groups of order 12 are $C_{2} \times C_6 \cong C_2 \times C_2 \times C_3$, $C_4 \times C_3 \cong C_{12}$.
\end{example}

\begin{definition}[Exponent]
	The \vocab{exponent} of a group $G$ is the least integer $n \geq 1$ such that $g^n = e$ for all $g \in G$. That is, it is the lowest common multiple of all of the orders of elements in $G$.
\end{definition}

\begin{example}
	$A_4$ has exponent 6.
\end{example}

\begin{corollary}
	Every finite abelian group contains an element whose order is the exponent of the group.
\end{corollary}

\begin{proof}
	If $G \cong C_{d_1} \times \cdots \times C_{d_t}$ with $d_1 \mid d_2 \mid \cdots \mid d_t$, then every $g \in G$ has order dividing $d_t$, and if $h \in C_{d_t}$ is a generator, then $(1, 1, 1, \dots, h) \in G$ has order $d_t$. So $G$ has exponent $d_t$.
\end{proof}

\begin{definition}[Ring]
	A \vocab{ring} is a triple $(R, +, \cdot)$ consisting of a set $R$ and two binary operations\footnote{Again this has an implicit \emph{closure} axiom} $+, \cdot: \mathbb{R} \times \mathbb{R} \rightarrow R$, refereed to as \emph{addition} and \emph{multiplication}, that satisfy
	\begin{itemize}
		\item $(R, +)$ is an abelian group, with identity $0$.
		\item Multiplication is associative and has an identity $1$.
		\item \emph{Distributivity}. For $x, y, z \in \mathbb{R}$, we have $x \cdot (y + z) = x \cdot y + x \cdot z$ and $(x + y)\cdot z = x \cdot z + y \cdot z$.
	\end{itemize}
\end{definition}

\begin{remark}[Notation]
	For $x \in R$, we write $-x$ for its inverse under addition, and we abbreviate $x + (-y) = x - y$.
\end{remark}

\begin{definition}[Commutative Ring]
	A ring $R$ is \vocab{commutative} if $x \cdot y = y \cdot x$ for all $x, y \in R$.
\end{definition}

In this course, we will \emph{only consider} commutative rings. So whenever we refer to an arbitrary ring, we will be referring to a commutative ring.\footnote{There are some notable non-commutative rings such as ones made up of matrices, but they will not be considered in this course.}


% We can begin to prove some basic facts about rings.

%

\begin{proposition}[Basic Properties of Rings]
% 	For a ring $R$, 
% 	\begin{enumerate}
% 		\item $0 \cdot x = 0$ for all $x \in R$.
% 		\item $(-1) \cdot x = -x$ for all $x \in R$.
% 	\end{enumerate}
% \end{proposition}

\begin{proof}
% 	For the first claim, we have $0 \cdot x = (0 + 0) \cdot x = 0 \cdot x + 0\cdot x$, so we must have $0 \cdot x = 0$.
% 	For the second claim, note that $0 = 0 \cdot x = (1 - 1) \cdot x = 1 \cdot x + (-1) \cdot x = x + (-1) \cdot x$, so $(-1) \cdot x = -x$.
% \end{proof}

\begin{definition}[Subrings]
	A subset $S \subset R$ is a \vocab{subring}, written $S \leq R$, if it is a ring under the same operations $+$ and $\cdot$, with the same identity elements $0$ and $1$.
 \end{definition}

\begin{remark}
	 Note that $R \times \{0 \}$ is \emph{not} a subring of $R \times S$ -- this doesn't have the same identity elements.
 \end{remark}

\begin{definition}
	If $R$ is a ring and $X$ is a set, then the set of all functions $X \rightarrow R$ is a ring under pointwise operations, $(f + g)(x) = f(x) + g(x)$, and $(f \cdot g)(x) = f(x) \cdot g(x)$.  
 \end{definition}

\begin{definition}[Ring of Polynomials]
	Let $R$ be a ring and define $S$ to be  the set of all sequences $(a_0, a_1, \dots)$ with $a_i \in R$ with $a_i = 0$ for all $i \geq N$ for some $N$. Then defining addition and multiplication as
		 \begin{align*}
			 (a_0, a_1, \dots) + (b_0, b_1, \dots) &= (a_0 + b_0, a_1 + b_1, \dots) \\
			 (a_0, a_1, \dots) \cdot (b_0, b_1, \dots) &= (c_0, c_1, \dots),
		 \end{align*}
		 where $c_n = \sum_{i = 0}^n a_i b_{n - i}$ gives us $R[X]$, the \vocab{ring of polynomials in $X$ with coefficients in $R$}.
\end{definition}

\begin{definition}[Ring of Polynomials]
	If $R$ is a ring then $R[X_1, \dots, X_n]$ is the \emph{ring of polynomials} in $X_1, \dots, X_n$ with coefficients in $R$.
\end{definition}

\begin{remark}
We can define this inductively as $R[X_1, \dots, X_n] = R[X_1, \dots, X_{n - 1}][X_n]$ using our careful construction for $R[X]$ above.
\end{remark}

\begin{definition}[Power Series and Laurent Polynomials]
	The \vocab{power series ring} is the ring $R[[X]] = \{a_0 + a_1 X + a_2X^2 + \cdots \mid a_i \in R\}$ and the \vocab{ring of Laurent polynomials} is $R[X, X^{-1}] = \{\sum_{i \in Z}a_iX^{i} \mid a_i \in R, \text{ and only finitely many $a_i \neq 0$}\}$.
\end{definition}

\begin{definition}[Unit]
	An element $r \in R$ is a \vocab{unit} if it has an inverse under multiplication. That is, if there exists $s \in R$ such that $r\cdot s = 1$.
\end{definition}

\begin{definition}[Field]
	A \vocab{field} is a ring with $0 \neq 1$ such that every non-zero element is a unit.
\end{definition}

\begin{remark}
	Note that we require $0 \neq 1$ in the definition of a field. If we did not have this, then if $0 = 1$, $x = 1 \cdot x = 0 \cdot x = 0$, for all $x \in R$. So if a ring has $0 = 1$, then it is the trivial ring $R = \{0\}$. And we don't want this to be a field.
\end{remark}

\begin{lemma}[Polynomial Division Algorithm]
	Let $f, g \in R[X]$. Suppose that the leading coefficient of $g$ is a unit. Then there exists $q, r \in R[X]$ such that $f(X) = q(X) g(X) + r(X)$, where $\deg(r) < \deg(g)$.
\end{lemma}

\begin{proof}
	We induct on the degree of $f$. If the degree is $n$, then we write $f(X) = a_n X^n + \cdots + a_1 X + a_0$ with $a_n \neq 0$, and $g(X) = b_m X^m + \cdots + b_1  X + b_0$, where $b_m \in R^\times$.

	If $n < m$, put $q = 0$ and $r = f$, and we are done. Otherwise, we put $f_1(X) = f(X) - a_n b_m^{-1}X^{n - m}g(x)$. Then the coefficient of $X^n$ is $0$, and $\deg(f_1) < n$, and we apply the induction hypothesis to get $f_1(X) = q_1(X)g(X) + r(X)$, with $\deg(r) < \deg(g)$.

	Then $f(X) =(q_1(X) + a_n b_{m}^{-1} X^{n - m})g(X) + r(X)$.
\end{proof}

\begin{remark}
	If $R$ is a field, then the we only need $g \neq 0$.
\end{remark}

\begin{definition}[Group]
	A \vocab{group} is a set $G$ with a binary operation\footnote{Some texts include an additional \emph{closure} axiom, but this is implied by $*$ being a binary operation on $G$.} $*$ which satisfies the axioms:
	\begin{itemize}
		\item \emph{Identity}. There is an element $e \in G$ such that $g * e = e * g = g$ for every $g \in G$.
		\item \emph{Inverses}. For every element $g \in G$, there is an element $g^{-1} \in G$ such that $g * g^{-1} = g^{-1} * g = e$.
		\item \emph{Associativity}. The operation $*$ is associative.
	\end{itemize}
\end{definition}

\begin{proposition}[Uniqueness of the Identity and Inverse]
	Let $(G, *)$ be a group. Then there is a unique identity element, and for every $g \in G$, $g^{-1}$ is unique.
\end{proposition}

\begin{proof}
	To prove that the identity element is unique, let $e$ and $e'$ be identity elements of $G$. Then $e* e' = e$ and $e* e' = e'$ by definition, giving $e = e'$. 

	To prove that the inverses are unique, suppose that for some $g, h, k \in G$ we have $g* h = g *k = e$. Then $g^{-1}* g *h = g^{-1} *g * k$, implying $h = k$. The case of $h * g = k * g = e$ follows analogously.
\end{proof}

\begin{proposition}[Cancellation Law]
	If $(G, *)$ is a group, and $a, b, c \in G$, then $a*b = a*c$ and $b*a = c*a$ both imply $b = c$.
\end{proposition}

\begin{proof}
	Taking $a * b = a * c$ and left-multiplying by $a^{-1}$ we have $a^{-1} * a * b = a^{-1} * a * c$, that is, $b = c$. The other case follows analogously.
\end{proof}

\begin{proof}$ $\phantom{\qedhere}
	\begin{enumerate}[label=(\roman*)]
		\item We have $(g*h) * (h^{-1} * g^{-1}) =  g * (h * h^{-1}) * g^{-1} = g * g^{-1} = e$, so $(g*h)^{-1} = h^{-1} * g^{-1}$.
		\item Similarly, $g^{-1} * g = e$, so $(g^{-1})^{-1} = g$. \hfill \qedsymbol
	\end{enumerate}
\end{proof}

\begin{definition}[Abelian Groups]
	We say a group $(G, *)$ is \vocab{abelian} if $*$ is commutative, that is, if for any $g, h \in G$, $g * h = h * g$.
\end{definition}

\begin{example}[The Trivial Group]
	The \vocab{trivial group} is a group whose only element is the identity, $\{ e \}$.
\end{example}

\begin{example}[Additive Group of Integers]
	$(\mathbb{Z}, +)$ is an group. We have
	\begin{itemize}
		\item The identity element $0 \in Z$, as $a + 0 = 0 + a = a$ for any $a \in \mathbb{Z}$
		\item The inverse of $a \in \mathbb{Z}$ being $-a$, as $a + (-a) = (-a) + a = 0$. 
		\item The operation $+$ is associative and commutative.
	\end{itemize}
\end{example}

\begin{example}[Addition Modulo $n$]
	Let $n \in \N$, and let $\mathbb{Z}/n \mathbb{Z} = \{0, 1, \dots, n - 1\}$ denote the set of residues modulo $n$. Then $(\mathbb{Z}/n\mathbb{Z}, +)$ is a group (where addition is done modulo $n$). We have
	\begin{itemize}
		\item The identity element is $0 \pmod{n}$, as $a + 0 \equiv 0 + a \equiv a \pmod{n}$.
		\item The inverse of $a \in \mathbb{Z}/n\mathbb{Z}$ is $-a$, as $a + (-a) \equiv 0 \pmod{n}$.
		\item Addition modulo $n$ is associative.
	\end{itemize}
\end{example}

\begin{example}[Non-Zero Rationals]
	Let $\mathbb{Q}^\times$ denote the set of non-zero rationals. Then $(\mathbb{Q}^\times, \times)$ is a group.
\end{example}

\begin{example}[Multiplication Modulo $p$]
	Let $p$ be a prime, and let $(\mathbb{Z} / p \mathbb{Z})^\times$ denote the set of non-zero residues modulo $p$. Then $((\mathbb{Z} / p \mathbb{Z})^\times, \times)$ is a group (where multiplication is done modulo $p$).
\end{example}

\begin{example}[General Linear Group]
	Let $\GL_n(\mathbb{R})$ be the set of $n \times n$ matrices with non-zero determinant. Then $(\GL_n(\mathbb{R}), \times)$ is the \vocab{general linear group}\footnote{Using matrix multiplication}.
\end{example}

\begin{example}[Special Linear Group]
	Let $\SL_n(\mathbb{R})$ be the set of $n \times n$ matrices with determinant 1. Then $(\SL_n(\mathbb{R}), \times)$ is the \vocab{special linear group}.
\end{example}

\begin{example}[Non-Examples of Groups]
	The following are are all \emph{not} groups.
	\begin{itemize}
		\item $(\mathbb{Z}, \times)$
		\item $(\mathbb{Q}, \times)$
		\item The set of $2\times 2$ matrices with matrix multiplication.
		\item $(\mathbb{R}, *)$ where $r  * s = r\times r \times s$
		\item $(\N, *)$ where $n * m = |n - m|$.
	\end{itemize}
\end{example}

\begin{definition}[Subgroups]
	Let $(G, *)$ be a group. A subset $H \subseteq G$ is a \vocab{subgroup} of $G$ if $(H, *)$ is also a group. If $H$ is a subgroup of $G$, we will write $H \leq G$.
\end{definition}

\begin{example}[Examples of Subgroups]
	The following are subgroups.
	\begin{itemize}
		\item For any group $G$, we have the \vocab{trivial subgroups} $\{ e \} \leq G$ and $G \leq G$.
		\item $\mathbb{Z} \leq \mathbb{Q} \leq \mathbb{R} \leq \mathbb{C}$ with addition.
		\item $\{ 0, 2, 4, \dots \} \leq \mathbb{Z}$ with addition.
		\item $\SL_n(\mathbb{R}) \leq \GL_n(\mathbb{R})$ with matrix multiplication.
	\end{itemize}
\end{example}

\begin{lemma}[Subgroup Criterion]
	A subset $H$ of a set $G$ is a subgroup of $(G, *)$ if and only if $H$ is non-empty and $x * y^{-1} \in H$ for all $x, y \in H$.
\end{lemma}

\begin{proof}[Proof Sketch]
	First check that the conditions of $H$ being non-empty and $x * y^{-1} \in H$ imply that it's a subgroup. Then, show that if $H$ is not a subgroup, then either $H$ is empty or $x * y^{-1} \not\in H$ for some $x, y \in H$.
\end{proof}

\begin{theorem}[Subgroups of $\mathbb{Z}$]\label{thm:subgroups-of-z}
	The subgroups of $(\mathbb{Z}, +)$ are precisely the subsets of the form $n \mathbb{Z}$ for $n \in N$, where $n\mathbb{Z} = \{n k \; : \; k \in \mathbb{Z}\}$.
\end{theorem}

\begin{proof}
	First, we prove that $n \mathbb{Z}$ is a subgroup. Fix $n \in \N$.
	\begin{itemize}
		\item \emph{Closure}. Given $n k_{1}, n k_{2} \in n \mathbb{Z},$ then $n k_{1}+n k_{2}=n\left(k_{1}+k_{2}\right) \in n \mathbb{Z}$.
		\item \emph{Identity}. $0 =n \cdot 0 \in n \mathbb{Z}$.
		\item \emph{Inverses}. The inverse of $n k$ is $-n k=n(-k) \in n \mathbb{Z}$.
	\end{itemize}
Thus each is subgroup. Now we prove that there is no other subgroups.

Let $H \leq Z$. If $H=\{0\}$, then $H \equiv 0 \mathbb{Z}$. If not, then take the smallest positive element in $H$ (namely $n$). Since $H$ is a subgroup, it's closed and contains inverses, so $n+n+\cdots+n \in$ $H$ and $-n-n-n-\cdots-n \in H,$ so $n \mathbb{Z} \subseteq H$.

Suppose, for a contradiction, there is some $k \in H$ such that $k \neq n \mathbb{Z} .$ So, there is some integer $n$ such that $n m<k<n(m+1) .$ But then $0 \leq k-n m<n,$ and $k-n m \in H$ which is a contradiction, so $H=n \mathbb{Z}$.
\end{proof}

\begin{proof} There is multiple ways to prove these, but we will use the subgroup criterion as an example of it being used.\phantom{\qedhere}
	\begin{enumerate}[label=(\roman*)]
		\item Note that $H \cap K$ is not empty as $e \in H$ and $e \in K$. Then, for any $x, y \in H \cap K$, it suffices to show that $x * y^{-1} \in H$. By the subgroup criterion, we have $x * y^{-1} \in H$ and $x*y^{-1} \in K$, thus $x * y^{-1} \in H \cap K$, and we are done.
		\item If $K \leq H$, then for any $x, y \in K$, we have $x * y^{-1} \in K$. Then as $K \subset H \subset G$, we must have $x * y^{-1} \in G$, and thus $K \leq G$.
		\item As $K \leq G$, we know $K$ is non-empty. Thus it suffices to show that $x * y^{-1} \in K$ for any $x, y \in H$. But this is implied by $K \leq G$ and the subgroup criterion, and thus as $K \subset H$, $K \leq H$. \hfill \qedsymbol
	\end{enumerate}
\end{proof}

\begin{definition}[Subgroup Generated By A Subset]
	For some set $X \subseteq G$, we define the \vocab{subgroup generated by $X$}, $\langle X \rangle$, to be the smallest subgroup of $G$ which contains $X$.
\end{definition}

\begin{proposition}
	Let $X$ be a non-empty subset of $G$. Then $\langle X \rangle$ is the set of elements of $G$ of the form 
	$x_1^{\alpha_1} x_2^{\alpha_2} \cdots x_k^{\alpha_k}$ where $x_i \in X$ (not necessarily distinct), $\alpha_i = \pm 1$ and $k \geq 0$
	(For $k = 0$, we say the element is $e$).
\end{proposition}

\begin{proof}
	Let $T$ be the set of such elements. Clearly $T \subseteq \langle X \rangle$, and also clearly $T$ is a subgroup of $G$. We also have that $X \subseteq T$ so $\langle X \rangle \subseteq T$. Thus $T = \langle X \rangle$.
\end{proof}

\begin{example}
	We have $(\mathbb{Z}, +) = \langle 1 \rangle = \langle 2, 3 \rangle$\footnote{Note that we write $\langle 2, 3\rangle$ instead of $\langle \{2, 3\} \rangle$.}, and $\mathbb{Z}/5\mathbb{Z} = \langle 1 \rangle = \langle 3 \rangle$.
\end{example}

\begin{definition}[Generators]\label{def:generator}
	If $X$ is a subset of $G$ such that $\langle X \rangle = G$, then we call $X$ a \vocab{generating set} of $G$.
\end{definition}

\begin{example}[Inclusion Function]
	If $H \leq G$, then the function $\iota : H \rightarrow G$ that has $\iota(h) = h$ for $h \in H$ is a homomorphism. It is also injective.
\end{example}

