\begin{proposition}
	Möbius maps are bijections $\hat{\mathbb{C}} \rightarrow \hat{\mathbb{C}}$.
\end{proposition}

\begin{proof}[Proof Sketch]
	Define $f^{-1}(z) = \frac{dz - b}{-cz + a}$, and check that $f^{-1}(f(z)) = z$.
\end{proof}

\begin{theorem}[Möbius Group]
	The set of Möbius maps forms a group $\mathcal{M}$ under composition.
\end{theorem}

\begin{remark}
	When working with Möbius maps in $\hat{\mathbb{C}}$, we will (somewhat improperly) use the notation `$\frac{1}{\infty} = 0$', `$\frac{1}{0} = \infty$' and `$\frac{a\infty}{c \infty} = \frac{a}{c}$' -- but take care not to use this notation accidentally in other circumstances.
\end{remark}

