\begin{theorem}[Generators of $M$]
 Every Möbius map can be written as a composition of maps of the following forms:
 \begin{enumerate}
 \item $f(z) = az$, $a \neq 0$ -- dilation/rotation;
 \item $f(z) = z + b$ -- translation;
 \item $f(z) = \frac{1}{z}$ -- inversion;
 \end{enumerate}
\end{theorem}

