\begin{corollary}
	$\mathcal{M} \cong \SL_2(\mathbb{C}) / \{\pm I\}$.
\end{corollary}

\begin{proof}
	Follows from the first isomorphism theorem.
\end{proof}

\begin{proposition}
	$\GL_n(\F)$ acts on $M_{n \times n}$ by conjugation. The orbit of a matrix $A \in M_{n \times n}(\F)$ is the set of matrices representing the same linear map as $A$ with respect to different bases.
\end{proposition}

\begin{proposition}
	$P \in \OO_n$ if and only if the columns of $P$ form an orthonormal basis.
\end{proposition}

\begin{proposition}
	Consider $\OO_n$ acting on $M_{n \times n}(\mathbb{R})$ by conjugation\footnote{This is an action as $\OO_n$ is a subgroup of $\GL_n$}. Then two matrices will be in the same orbit if and only if they represent the same linear map with respect to two orthonormal bases.
\end{proposition}

\begin{proposition}[$\OO_n$ preserves inner products]
	$P \in \OO_n$ if and only of $(Px) \cdot (Py) = x \cdot y$ for any $x, y \in \mathbb{R}^n$.
\end{proposition}

\begin{corollary}
	For $P \in \OO_n$, $P$ preserves the length of vectors and the angle between vectors.
\end{corollary}

\begin{proof}
	This follows directly from the preservation of inner product.
\end{proof}

