\begin{definition}[Language]
 Let $\Omega$ (function symbols) and $\Pi$ (relation symbols) be disjoint sets and $\alpha: \Omega \cup \Pi \rightarrow \N$ a function (arity).

 The Language $L = L(\Omega, \Pi, \alpha)$ is the set of formulae, defined as follows:
 \begin{itemize}
 \item Variables. We have some variables $x_1, x_2, \dots$ (also written $x, y, z, \dots$)
 \item Terms. These are defined inductively by
 \begin{enumerate}
 \item Every variable is a term;
 \item If $f \in \Omega$, $\alpha(f) = n$ and $t_1, \dots, t_n$ are terms, then $f(t_1, \dots, t_n)$ is a term.
 \end{enumerate}
 \item Atomic formulae. There are three sorts:
 \begin{enumerate}
 \item $\bot$;
 \item $(s = t)$ for any terms $s, t$;
 \item $\phi(t_1, \dots, t_n)$ for any $\phi \in \Pi$ with $\alpha(\phi) = n$ and $t_1, \dots, t_n$ terms.
 \end{enumerate}
 \item Formulae. These are defined inductively by
 \begin{enumerate}
 \item Atomic formulae are formulae;
 \item $(p \Rightarrow q)$ is a formula for any formulae $p, q$;
 \item $(\forall x) p$ is a formula for any formula $p$ and variable $x$.
 \end{enumerate}
 \end{itemize}
\end{definition}

