\begin{definition}[Function]
 We say $f$ is a function if
 \begin{align*}
 (\forall x)(x \in f \Rightarrow x is an ordered pair)\\
 \land (\forall x)(\forall y)(\forall z) [((x, y) \in f\land (x, z) \in f) \Rightarrow y = z].
 \end{align*}
\end{definition}

