\begin{definition}[$\N$ and $\Z$]
%     We denote by $\N$ the set of \emph{natural numbers} $1, 2, 3, \dots$ and by $\Z$ the set of \emph{integers}.
% \end{definition}

\begin{definition}[Division]
%     For $a, b \in \N$, we say that $b$ \emph{divides} $a$ if there exists $c \in \N$ such that $a = bc$. We then write $b \mid a$. If $b$ does not divide $a$, we write $b \nmid a$. 
% \end{definition}

\begin{theorem}[Division Algorithm]
    Given $a, b \in \mathbb{Z}$ with $b > 0$, there exists $q, r \in \mathbb{Z}$ with $a = bq + r$ and $0 \leq r < b$.
\end{theorem}

\begin{proof}
Let $S=\{a-nb:n\in\mathbb Z\}\cap\mathbb Z_{\geq0}$. Taking $n$ sufficiently negative shows that $S$ is nonempty. By well-ordering, $S$ has a least element $r=a-qb$. If $r\geq b$, then $r-b=a-(q+1)b$ belongs to $S$ and is smaller than $r$, a contradiction. Thus $0\leq r<b$. Moreover, if $a=bq'+r'$ with $0\leq r'<b$, then $b(q-q')=r'-r$. The right-hand side has absolute value less than $b$, so both sides vanish and $(q,r)=(q',r')$.
\end{proof}

\begin{definition}
  If $r = 0$, we write $b \mid a$ (``$b$ \emph{divides} $a$''), otherwise we write $b \nmid a$.
\end{definition}

\begin{lemma}
  $I = d \mathbb{Z} = \{md \mid m \in \mathbb{Z}\}$ for some $d > 0$.
\end{lemma}

\begin{proof}
  Let $d$ be the least positive element in $I$. Then $d\mathbb{Z} \subset I$. Conversely, if $a \in I$, write $a = qd + r$ for some $0 \leq r < a$. If $r = 0$, then $a \in d \mathbb{Z}$. Otherwise, $r = a - qd \in I$ is positive and smaller than $d$, contradiction.
\end{proof}

\begin{definition}
  We write $d = \gcd(a_1, \dots, a_n)$ or $(a_1$, $\dots$, $a_n)$ and say $d$ is the \emph{greatest common divisor} of $a_1, \dots, a_n$.
\end{definition}

\begin{corollary}[Bézout]
  Suppose $a, b, c \in \mathbb{Z}$ and $a, b$ not both 0. There exists $x, y \in \mathbb{Z}$ such that $ax + by = c$ if and only if $(a, b) \mid c$.
\end{corollary}

\begin{definition}
%     The \emph{greatest common divisor} $(a, b)$ of natural numbers $a, b$ is the largest integer $d$ such that $d\mid a$ and $d\mid b$.
% \end{definition}

