With this mental picture, we can begin to build up some properties of modular arithmetic.

\begin{proposition}[Arithmetic Modulo $n$]
	If $a \equiv a' \pmod{n}$ and $b \equiv b' \pmod{n}$, then $a + b \equiv a' + b' \pmod{n}$ and $ab \equiv a'b' \pmod{n}$.
\end{proposition}

\begin{proof}
	We have $a' = a + kn$ and $b' = b + jn$, for some $k, j \in \mathbb{Z}$.
	So $a' + b' = a + b + (k + j)n \equiv a + b \pmod{n}$, and $a'b' = (a + kn)(b + jn) = ab + (bk + aj + kjn)n\equiv ab \pmod{n}$.
\end{proof}

\begin{example}[Euclid's Lemma in Modular Arithmetic]
	The statement that for a prime $p$, `$p \mid ab \implies p \mid a$ or $p \mid b$' is equivalent saying that $ab \equiv 0 \pmod{p}$ implies that $a \equiv 0 \pmod{p}$ or $b \equiv 0 \pmod{0}$.
\end{example}

\begin{definition}[Modular Inverses]
	For $a, b \in \mathbb{Z}$, we say that $b$ is an \vocab{inverse} of $a$ if $ab \equiv 1 \pmod{n}$.\footnote{This should be reminiscent of the notion of inverses from group theory.}
\end{definition}

\begin{example}
	In $\mathbb{Z}/10\mathbb{Z}$, the inverse of $3$ is $7$, as $3\times 7 = 21\equiv 1 \pmod{10}$. The inverse of $4$ does not exist, as for all $x \in \mathbb{Z}$, $4x \not\equiv 1 \pmod{10}$, as $4x$ is even.

	This example shows that inverses do not always exist for an arbitrary modulus $n$.
\end{example}

\begin{notation}
	We write $a^{-1}$ to mean the inverse of $a$ (modulo some $n$).
\end{notation}

\begin{proposition}[Properties of Modular Inverses]
	In $\mathbb{Z}/n\mathbb{Z}$,
	\begin{enumerate}[label=(\roman*)]
		\item If a modular inverse exists, then it is unique modulo $n$.
		\item If $a$ has an inverse, and $ab \equiv ac \pmod{n}$, then $b \equiv c \pmod{n}$. That is, we can cancel invertible elements.\footnote{We \emph{cannot} cancel elements in general.}
	\end{enumerate}
\end{proposition}

\begin{proof}
	To show (i),
	suppose there exists $b, c \in \mathbb{Z}$ such that for some $a$, $ab \equiv ac \equiv n \pmod{n}$. Then $b(ac) \equiv bab \implies c \equiv b \pmod{n}$. Then to show (ii), we can just multiply both sides by $a^{-1}$.
\end{proof}

\begin{proposition}
	Let $p$ be a prime, then every $a \neq 0 \pmod{p}$ has an inverse modulo $p$.
\end{proposition}

\begin{proof}
	We have $\gcd(a, p) = 1$, so we can write $ax + py = 1$ for some $x,y \in \mathbb{Z}$. But then $ax = 1 - py$, and thus $ax \equiv 1 \pmod{p}$.\hfill\qed

	\emph{Alternate Proof}. 
	In $\mathbb{Z}/n\mathbb{Z}$, consider the multiplies of a: $0\times a$, $1 \times a$, $2 
	\times a$, $\dots$, $(p - 1)\times a$. We wish to show that one of them is $1$. We have $p$ items written down, and I claim these are all \emph{distinct} in $\mathbb{Z}/p\mathbb{Z}$. If $ia = ja \implies (i - j)a \equiv 0$, which implies $a \equiv 0$ or $i -j \equiv 0 \implies i \equiv j \pmod{p}$. Hence, there must be $0$, $1$, $\dots$, $p - 1$ in this list, in some order. Thus $xa \equiv 1 \pmod{p}$, for some $x \in \mathbb{Z}/n\mathbb{Z}$.
\end{proof}

\begin{proposition}
	Let $n \in \N$. Then $a$ has an inverse modulo $n$ if and only if $\gcd(a, n) = 1$.
\end{proposition}

\begin{proof}
	We have $\gcd(a, n) = 1 \iff ax + ny = 1$, for some $x, y \in \mathbb{Z}$. Then $ax = 1 - ny \equiv 1 \pmod{n}$.
\end{proof}

\begin{example}
	If $p$ is a prime, then $\phi(p) = p - 1$, $\phi(p^2) = p^2 - p$ (we cannot have $p, 2p, \dots, pp$). If $p$ and $q$ are distinct primes, then $\phi(pq) = pq - p - q + 1$.
\end{example}

