\begin{definition}[Injectivity]
	A function $f: A \rightarrow B$ is \vocab{injective} if for any $a, a' \in A$, then $a \neq a' \implies f(a) \neq f(a')$.
\end{definition}

\begin{definition}[Surjectivity]
	A function $f : A \rightarrow B$ is \vocab{surjective} if for all $b \in B$, there exists $a \in A$ such that $f(a) = b$.
\end{definition}

\begin{definition}[Bijectivity]
	A function $f: A \rightarrow B$ is \vocab{bijective} if it is injective and surjective.
\end{definition}

\begin{definition}
	For $f: A \rightarrow B$, we say $A$ is the \vocab{domain}, and $B$ is the \vocab{range}. We also say the \vocab{image} of $f$ is the set $\{f(a) \mid a \in A\}$.
\end{definition}

\begin{proposition}
	For $A$ and $B$ finite, the following are true:
	\begin{enumerate}[label=(\roman*)]
		\item There is no surjection from $A \rightarrow B$ if $|B| > |A|$.
		\item There is no injection from $A \rightarrow B$ if $|A| > |B|$.
		\item For $f: A \rightarrow A$, if $f$ is injective then $f$ is also surjective (and vice versa).
		\item There is no bijection from $A$ to any proper subset of $A$.
	\end{enumerate}
\end{proposition}

\begin{proof}[Proof Sketch]
	Check definitions.
\end{proof}

\begin{definition}
	Given $f : A \rightarrow B$ and $g : B \rightarrow C$, the \vocab{composition} $g \circ f : A \rightarrow C$ is defined by
	$$
	(g \circ f)(a) = g(f(a)).
	$$
\end{definition}

\begin{example}
	If $f: \mathbb{R} \rightarrow \mathbb{R}$ is defined as $f(x) = 2x$, and $g: \mathbb{R} \rightarrow R$ is defined as $g(x) = x + 1$, then
	$$
	(g \circ f)(x) = 2x + 1, \quad \text{and}\quad (f \circ g)(x) = 2x + 2.
	$$
\end{example}

\begin{definition}
	We say a function $f: A \rightarrow B$ is \vocab{invertible} if there exists a function $g: B \rightarrow A$ such that $g \circ f = 1_A$ and $f \circ g = 1_B$.
\end{definition}

\begin{remark}
	It is not sufficient to show just that $g \circ f = 1_A$ or $f \circ g = 1_B$. Both must be checked.
\end{remark}

\begin{proposition}
	A function $f : A \rightarrow B$ is invertible if and only if it is bijective.
\end{proposition}

\begin{proof}
	Let's say that $g$ is inverse to $f$. Then for any $b \in B$, we have $f(g(b)) = b$, so $f$ is surjective. Also, $f(a) = f(a')$ implies $g(f(a)) = g(f(a'))$, and $a = a'$, so $f$ is injective and thus bijective.

	Now let's suppose that $f$ is bijective, and let $g(b)$ be the unique $a \in A$ with $f(a) = b$. Then $g$ is the inverse of $f$.
\end{proof}

\begin{definition}[Relation]
	A \vocab{relation} on a set $X$ is a subset $R$ of $X \times X$.
\end{definition}

\begin{example}
	The following are all relations.
	\begin{enumerate}[label=(\roman*)]
		\item On $\N$, $a R b$ if $a \cong b \pmod{5}$. For example, $2 R 12$ but not $2 R 11$.
		\item On $\N$, $aR b$ if $a \mid b$.
		\item On $\N$, $aRb$ if $a = b \pm 1$.
	\end{enumerate}
\end{example}

\begin{definition}[Reflexive]
	A relation $R$ is \vocab{reflexive} if for all $x \in X$, $x R x$.
\end{definition}

\begin{definition}[Symmetric]
	A relation $R$ is \vocab{symmetric} if for all $x, y \in X$, then $xRy \implies y R x$.
\end{definition}

\begin{definition}[Transitive]
	A relation $R$ is \vocab{transitive} if for all $x, y, z \in X$, then $x R y$ and $y R z$ implies $x R z$.
\end{definition}

\begin{definition}[Equivalence Relation]
	An equivalence relation is a relation that is reflexive, symmetric and transitive.
\end{definition}

