\begin{example}
	Let $X$ be a set, and let $\{C_i \mid i \in I \}$ be a \vocab{partition} of $X$, such that each $C_i$ is non-empty, they are disjoint, and $\bigcup_{i \in I} C_i = X$.

	Then $a R b$ if there exists $i$ such that $a, b \in C_i$ is an equivalence relation on $X$.
\end{example}

\begin{definition}[Equivalence Class]
	For an equivalence relation $R$ on a set $X$, and $x \in X$, the \vocab{equivalence class}, $[x]$, is the set $\{y \in X \mid y R x \}$. That is, the set of everything in $X$ that is related to $x$.
\end{definition}

\begin{proposition}[Equivalence Classes Partition a Set]
	Let $R$ be an equivalence relation on a set $X$. Then the equivalence classes of $R$ partition $X$.
\end{proposition}

\begin{proof}
	Each equivalence class $[x]$ is non-empty (as $x \in [x]$), and $\cup_{x \in X} [x] = X$, as $x \in [x]$ for all $x \in X$. Thus it suffices to show that all equivalence classes are either disjoint or equal.

	Given $x, y$ with $[x] \cap [y] \neq \emptyset$. We wish to show $[x] = [y]$. Take $z \in [x] \cap [y]$. Then $z R x$ and $z R y$ so $x R y$. Thus $[x] = [y]$.
\end{proof}

\begin{definition}[Countability]
	We say that a set $X$ is \vocab{countable} if $X$ is finite or if there is a bijection with $\N$. Equivalently, $X$ is countable if and only if we can list $X$ as $a_1, a_2, \dots$ which might terminate.
\end{definition}

\begin{example}[Trivially Countable Sets]
	Any finite set is countable, and $\N$ is countable, by definition.
\end{example}

\begin{example}[$\mathbb{Z}$ is Countable]
	$\mathbb{Z}$ is countable, as we can list it as $0, 1, -1, 2, -2, \dots$.
\end{example}

\begin{proposition}
	A set $X$ is countable if and only if there exists an injection $f : X \rightarrow \N$.
\end{proposition}

\begin{proof}
If $X$ is finite or bijects with $\N$, then of course $X$ injects in $\N$.

Now assume that $X$ is not finite (if it was finite, then it's already countable), and has an injection $f : X \rightarrow \N$. Then we have a bijection from $X$ with its image $f(X) = \{f(x) \mid x \in X \}$. 

Set $a_1$ to be $\min f(X)$, $a_2$ to be $\min f(X) \backslash \{a_1\}$, and so on. Then $f(X) = \{a_1, a_2, \dots \}$ -- each $a \in X$ is $a_n$ for some $n$, because $a = a_n$ for some $n \leq a$.
So $f(x)$ is countable.
\end{proof}

\begin{remark}[A Warning]
	In $\mathbb{R}$, let $X = \{\frac{1}{2}, \frac{2}{3}, \frac{3}{4}, \dots \} \cup \{1\}$. Then $X$ is countable, as we can list it as $1, 1/2, 2/3, \dots$. But if we counted by `least element', 1 would not be on the list. So the counting method used in the proof above does not always work.
\end{remark}

\begin{theorem}
	$\N \times \N$ is countable.
\end{theorem}

\begin{proof}
	Define $a_1 = (1, 1)$, and inductively letting $a_{n - 1} = (p, q)$, 
	$$
a_n = \begin{cases}
	(p - 1, q + 1) &\mbox{if } p \neq 1, \\
	(1, p + 1) &\mbox{if } p = 1.
   \end{cases}
	$$
	Then $a_n$ hits every point $(x, y) \in \N \times \N$, by induction on $x + y$, so we have listed $\N \times \N$, and thus it is countable. \qedhere

	\emph{Alternate Proof}. We will look for an injection $f : \N \times \N \rightarrow \N$. Indeed, $f(x, y) = 2^x 3^y$ works, and thus $\N \times \N$ is countable.\hfill \qed
\end{proof}

\begin{theorem}
	Let $A_1, A_2, \dots$ be countable sets. Then $A_1 \cup A_2 \cup \dots$ is countable.
\end{theorem}

\begin{proof}
	For each $i$, we have $A_i$ countable, so we can list $A_i$ as $a_{i, 1}, a_{i, 2}, \dots$, which might terminate.
	Then define $f : \bigcup_{n \in \N} A_n \rightarrow \N$, so that $x \rightarrow 2^i 3^j$, where $x = a_{ij}$ for the least such $i$.
This is an injection.
\end{proof}

\begin{example}
	$\mathbb{Q}$ is countable, as $\mathbb{Q} = \mathbb{Z} \cup \frac{1}{2}\mathbb{Z} \cup \frac{1}{3}\mathbb{Z} \cup \dots$, where $\frac{1}{k}\mathbb{Z} = \{\frac{x}{k} \mid x \in \mathbb{Z}\}$. So $Q$ is countable.
\end{example}

\begin{example}
	The set $\mathbb{A}$ of all algebraic numbers is countable. 

	Indeed, it's enough to show that the set of all integer polynomials is countable, as each has finitely many roots, so $\mathbb{A}$ would be a countable union of finite sets.

	So, to show that the collection of integer polynomials is countable, it's enough to show that for each $d$, the set of all integer polynomials of degree $d$ is countable. But this set injects into $\mathbb{Z}^{d + 1}$ with it's coefficients, and $\mathbb{Z}^n$ is countable for any $n$, by our previous theorem.
\end{example}

\begin{definition}[Uncountability]
	A set $X$ is \vocab{uncountable} if it is not countable.
\end{definition}

\begin{theorem}
	$\mathbb{R}$ is uncountable.
\end{theorem}

\begin{theorem}
	The power set of $\N$, $\power(\N)$ is uncountable.
\end{theorem}

\begin{proof}
	Suppose $\power(\N)$ is listed as $S_1, S_2, \dots$. We wish to find some $S \subset \N$ that's not on this list.
	For every $i \in \N$, we take $i \in S$ iff $i \not \in S_i$. Then $S$ cannot be on this list, since $S \neq S_n$ for all $n$, as they differ at element $n$.
	Hence $\power(\N)$ is uncountable.
\end{proof}

\begin{theorem}
	For any set $X$, there is no bijection from $X$ to $\power(X)$.
\end{theorem}

\begin{proof}
	Given any function $f: X \rightarrow \power(X)$, we will show $f$ is not surjective.

	Let $S = \{x \in X \mid x \not \in f(x) \}$. Then $S$ does not belong to the image of $f$, since for every $x$, $S \neq f(x)$, as $S$ and $f(x)$ differ at element $x$.
\end{proof}

\begin{remark}
	This proof is vaguely reminiscent of Russell's paradox. In fact, this theorem proves that there is no universal set, just as Russell's paradox did. This is because otherwise, we would have $\power(V) \subset V$, where certain that $V$ would surject to $\power(V)$.
\end{remark}

\begin{example}
	Let $A_i$, $i \in I$ be a family of open intervals that are pairwise disjoint. Must the family be countable?

	The answer is yes. Each $A_i$ contains a rational, and $\mathbb{Q}$ is countable. So this family is countable. 

	Another proof is that we can note the set $\{i \in I \mid A_i \text{has length} \geq \frac{1}{k} \}$ is countable (it injects into $\mathbb{Z}$). So the family be countable.
\end{example}

In general, to show a set $X$ is uncountable, we had two approaches.
\begin{enumerate}
	\item Run the diagonal argument on $X$.
	\item Inject your favorite uncountable set into $X$.
\end{enumerate}
To show a set $X$ is countable, we could do something like
\begin{enumerate}
	\item List it (which can be ugly)
	\item Inject it into $\N$
	\item Use `countable union of countable sets is countable'. This is usually the best one.
	\item If in or near $\mathbb{R}$, sometimes using the countability of $\mathbb{Q}$ helps.
\end{enumerate}

\begin{theorem}[Schröder-Bernstein Theorem]
	If $f : A \rightarrow B$ and $g : B \rightarrow A$ are injections, then there exists a bijection $h : A \rightarrow B$.
\end{theorem}

\begin{example}
	Do $[0, 1]$ and $[0, 1] \cup [2, 3]$ biject?

	By Schröder-Bernstein this is trivial. Consider the identity function $f: [0, 1] \rightarrow [0, 1] \cup [2, 3]$, and the function $g : [0, 1] \cup [2, 3] \rightarrow [0, 1]$ with $g(x) = x/3$ are both injections, so there is a bijection between these sets.
\end{example}

