\begin{corollary}[Triangle variants, B\&S 2.2.4] 
For all $a,b,c\in\R$:
\textup{(i)} $\bigl|\,\abs a-\abs b\,\bigr|\le\abs{a-b}$ (reverse triangle inequality);
\textup{(ii)} $\abs{a-b}\le\abs a+\abs b$;
\textup{(iii)} $\abs{a-c}\le\abs{a-b}+\abs{b-c}$ (distance is subadditive).
\end{corollary}

