\begin{theorem}[Bohr--Mollerup, Rudin 8.19] 
$\Gamma$ is the unique function $f:(0,\infty)\to(0,\infty)$ satisfying all three:
\begin{enumerate}
\item $f(x+1)=x f(x)$;
\item $f(1)=1$;
\item $\log f$ is convex.
\end{enumerate}
\end{theorem}

