\begin{proposition} 
For $f,g\in\Lone(\Rd)$: \textup{(i)} $\norm{af}=\abs a\,\norm f$; \textup{(ii)}
$\norm{f+g}\le\norm f+\norm g$; \textup{(iii)} $\norm f=0$ iff $f=0$ a.e.; \textup{(iv)}
$d(f,g)=\norm{f-g}$ is a metric on $\Lone(\Rd)$.
\end{proposition}

