\begin{corollary} 
For any measurable $E\subseteq\Rd$: \textup{(i)} a.e.\ $x\in E$ is a density point of $E$;
\textup{(ii)} a.e.\ $x\notin E$ is not a density point of $E$.
\end{corollary}

