\begin{proposition} 
If $E\in\sA_{\sigma\delta}$ then $E^{x_2}$ is $\mu_1$-measurable for every $x_2$,
$x_2\mapsto\mu_1(E^{x_2})$ is $\mu_2$-measurable, and
\begin{equation} 
 \int_{X_2}\mu_1(E^{x_2})\dmu_2=(\mu_1\times\mu_2)(E).
\end{equation}
For an arbitrary measurable $E\in\sM$ the same holds, except that measurability of
$E^{x_2}$ and the value $\mu_1(E^{x_2})$ are asserted only for almost every $x_2$.
\end{proposition}

