\begin{proposition}[Ces\`aro means average the partial sums]\label{p:cesaro@c34}
$\displaystyle\sigma_N(g)=\frac{S_0(g)+\cdots+S_{N-1}(g)}{N}
 =\sum_{\abs n\le N}\Bigl(1-\frac{\abs n}{N}\Bigr)a_n e^{inx}.$
\end{proposition}

