Type: proposition
Title: Operational rules
Label: p:oprules@c35
Local macros: \R := \mathbb{R}
Content:
\begin{proposition}[Operational rules] 
If $f\in\mathcal S(\R)$ and $h\in\R$, $\delta>0$:
\begin{align*}
&(i) f(x+h)\to \hat f(\xi)e^{2\pi i h\xi};
&&(ii) f(x)e^{-2\pi i xh}\to \hat f(\xi+h);\\
&(iii) f(\delta x)\to \delta^{-1}\hat f(\delta^{-1}\xi);
&&(iv) f'(x)\to 2\pi i\xi\,\hat f(\xi);\\
&(v) -2\pi i x f(x)\to \dfrac{d}{d\xi}\hat f(\xi). &&
\end{align*}
Thus, up to factors of $2\pi i$, the Fourier transform interchanges differentiation
and multiplication by $x$.
\end{proposition}

latex:
\begin{proposition}[Operational rules]\label{p:oprules@c35}
If $f\in\mathcal S(\R)$ and $h\in\R$, $\delta>0$:
\begin{align*}
&\text{(i) } f(x+h)\to \hat f(\xi)e^{2\pi i h\xi};
&&\text{(ii) } f(x)e^{-2\pi i xh}\to \hat f(\xi+h);\\
&\text{(iii) } f(\delta x)\to \delta^{-1}\hat f(\delta^{-1}\xi);
&&\text{(iv) } f'(x)\to 2\pi i\xi\,\hat f(\xi);\\
&\text{(v) } -2\pi i x f(x)\to \dfrac{d}{d\xi}\hat f(\xi). &&
\end{align*}
Thus, up to factors of $2\pi i$, the Fourier transform \emph{interchanges differentiation
and multiplication by $x$}.
\end{proposition}

