\begin{tikzcd}[row sep=large, column sep=huge]
Z(6) \arrow[r, "\sim"] \arrow[d, "\widehat{\phantom{x}}"'] & Z(2)\times Z(3) \arrow[d, "\widehat{\phantom{x}}"] \\
\widehat{Z(6)} \arrow[r, "\sim"'] & \widehat{Z(2)}\times\widehat{Z(3)}
\end{tikzcd}
