\begin{theorem} 
Each of the following is again a Brownian motion:
\begin{itemize}
\item[(a)] (scaling) $\delta^{-1/2}B_{t\delta}$, for fixed $\delta>0$;
\item[(b)] (rotation) $o(B_t)$, for an orthogonal $o$ on $\Rd$;
\item[(c)] (restart) $B_{t+\sigma_0}-B_{\sigma_0}$, for a constant $\sigma_0\ge0$.
\end{itemize}
\end{theorem}

