If $u$ is defined by [REF:e:usol@c44] , then
\begin{itemize}
\item[(a)] $u$ is harmonic in $R$;
\item[(b)] $u(x)\to f(y)$ as $x\to y$ ($x\in R$) whenever $y\in\partial R$ is regular.
\end{itemize}
\end{theorem}

