\begin{example}[Examples of Homomorphisms]
\begin{enumerate}
\item The identity map $g \mapsto g$;
\item The determinant $\det : \mathrm{GL}_n(\mathbb{R}) \to (R^\times, \times)$;
\item The map $(\mathbb{Z}, +) \to (\mathbb{Z}_n, +)$ where $a \mapsto \bar{a}$;
\item Let $g \in G$. Then we have a map $(\mathbb{Z}, +) \to G$ where $n \mapsto g^n$.
\end{enumerate}
\end{example}

\begin{definition}[Isomorphism]
An isomorphism is a bijective homomorphism. Note that the inverse of an isomorphism is also a group isomorphism.
\end{definition}

\begin{lemma}
Let $\phi : G \to H$ be a homomorphism where $g_i \mapsto h_i$. Then any relation on $\{g_i\}$ is satisfied by $\{h_i\}$. For example, if $G$ is abelian then $H$ is abelian as well.
\end{lemma}

\begin{corollary}
If $G = \langle g_1,\dotsc,g_n \mid \text{relations } \rangle$, and if $h_1,\dotsc,h_n \in H$ satisfy the same relations, then there exists a homomorphism $\phi : G \to H$ where $g_i \mapsto h_i$. However, any map which does preserve these relations need not be surjective nor injective. This means that presentations aren't enough to determine group isometry. Worse, minimal generating sets may not even have the same size for distinct generators. For example $\{1\}$ and $\{2,3\}$ both generate $\mathbb{Z}_6$.
\end{corollary}

\begin{corollary}
Homomorphisms don't actually preserve order, since if $g^n = 1$ then $\phi(g^n) = 1$, but the order of $\phi(g^n)$ might just be a divisor of $n$, not $n$ itself.
\end{corollary}

