\begin{theorem}
Let $G$ be a group with $H,K \leq G$ such that 
\begin{enumerate}
\item $H \normal G$,
\item $H \cap K = \{1\}$, and 
\item $G = HK$.
\end{enumerate}
Then $G \cong H \rtimes K$ where $k \cdot h = khk^{-1}$ for all $h \in H$ and for all $k \in K$.
\end{theorem}

