\begin{definition}[Zero Divisor]
An nonzero $a \in R$ is a zero divisor if there exists a nonzero $b \in R$ for which $ab = 0$ or $ba = 0$.
\end{definition}

\begin{definition}[Unit]
Let $R$ be a ring with identity. A unit is any element $x \in R$ if there exists a $u = x^{-1} \in R$ for which $xu = ux = 1$. We denote the set of units of $R$ by $R^\times$.
\end{definition}

\begin{example}
Consider $R = \mathbb{Z}/6\mathbb{Z}$. Find all units and zero divisors.
\end{example}

\begin{solution}
The units are $1,5$, and the zero divisors are $2,3,4$.
\end{solution}

\begin{proof}[Proof that $2$ is not a unit]
Suppose by way of contradiction that there exist $x \in R$ such that $2x = 1$. Then $3(2x) = 3 = (3 \cdot 2)x = 0$, which is a contradiction. Generally, if $x \in R$ is a zero divisor then it is not a unit. However, the converse is not true (consider $2 \in \mathbb{Z}$, which is neither a unit nor a zero divisor).
\end{proof}

\begin{definition}[Integral Domain]
A commutative ring $R$ with identity is an integral domain if it has no zero divisors. This gives us the cancellation law! [The proof is super short and intuitive.]
\end{definition}

\begin{proposition}
Any finite integral domain is a field. The proof is pretty chill. Check it out some time!
\end{proposition}

\begin{definition}[Subring]
A subring $S \subseteq R$ is an object where $(S,+) \leq (R,+)$ and $S$ is closed under multiplication. For example, $2\mathbb{Z} \subset \mathbb{Z}$, $\mathbb{Z} \subset \mathbb{Q}$, $\mathbb{Q} \subset \mathbb{R}$, $\mathbb{R} \subset \mathbb{C}$, the set of continuous functions from $\mathbb{R}$ to $\mathbb{R}$ is a subring of all functions from $\mathbb{R}$ to $\mathbb{R}$.
\end{definition}

\begin{example}
Consider $\mathbb{Q}(i) = \{a + bi \mid a,b \in \mathbb{Q}\}$ where $i^2 = 1$. We know how to add and multiply this from middle school. This is actually a field equal to $\mathbb{Q}[i]$, where $\mathbb{Q}[i]$ is actually the field of rational polynomials over $1$ and $i$. Now consider $\mathbb{Z}[i]$ (this won't be a field), which is integral polynomials in $1$ and $i$. This isn't a field since $2$ has no inverse.
\end{example}

\begin{definition}[Norm]
Let the norm of $\mathbb{Q}(i)$ be a map $N : \mathbb{Q}(i) \to \mathbb{Q}$ defined by $a + bi \mapsto (a+bi)(a-bi) = a^2+b^2$. This map is multiplicative.
\end{definition}

\begin{proposition}
$N(x) \in \mathbb{Z}$ for all $x \in \mathbb{Z}[i]$, and $x$ is a unit if and only if $N(x) = \pm 1$.
\end{proposition}

\begin{example}
Consider $\mathbb{Z}[\sqrt{5}] \subset \mathbb{Q}(\sqrt{5})$ where $N(a+b\sqrt{5}) = a^2 + 5b^2$. Then $(a+b\sqrt{5})^{-1} = (a-b\sqrt{5})/(a^2-5b^2)$ for anything where $a+b\sqrt{5} \not=0$. Then $x \in \mathbb{Z}[\sqrt{5}]$ is a unit if and only if the norm is $\pm 1$. Notice that this method depended on the fact that $5$ was square-free (no repeated primes).
\end{example}

