\begin{definition}[Multiplicative Subset]
A subset $D \subseteq R$ is multiplicative if 
\begin{itemize}
\item $D$ is closed under multiplication;
\item $D$ does not contain $0$;
\item $D$ does not contain any zero divisors from $R$.
\end{itemize}
\end{definition}

