\begin{theorem}
Let $m$ and $n$ be relatively prime to one another. Then $m^{\varphi(n)} = 1 \pmod{n}$. Recall that $\bar{m} \in (\mathbb{Z}/n\mathbb{Z})^\times$.
\end{theorem}

\begin{proposition}
If $n = p$ is prime, and you take $k \in \mathbb{Z}$, then $m^{k\varphi(n) + 1} = m \pmod{n}$.
\end{proposition}

\begin{proposition}
Let $n = pq$ where $p,q$ are prime, and let $k \in \mathbb{Z}$. Then $m^{k \varphi(n) + 1} \equiv m \pmod{n}$. This is very similar to the previous proposition except that now we don't care that $m$ and $n$ are relatively prime.
\end{proposition}

\begin{theorem}[RSA]
Let $n = pq$ where $p,q$ are distinct primes with very many digits. Note that $\lambda = \varphi(n) = (p-1)(q-1)$, which is very easy to calculate if you know that $p$ and $q$ are but very hard otherwise. Then pick an $e \in (\mathbb{Z}/\lambda\mathbb{Z})$. Picking this isn't always trivial since we don't know how to factor quickly, so we turn to the Euclidean algorithm to tell us if a chosen $e$ is actually relatively prime to $\lambda$. This is very efficient in the number of digits, so it's okay from a use perspective. Then, we need to find a $d = e^{-1} \in (\mathbb{Z}/n\mathbb{Z})^\times$. Since we have the Euclidean Algorithm, we know that $1 = xe + y\lambda$, and modulo lambda we know that $d = x$. Then our \textsc{public information} is again $(n,e)$ and our \textsc{private information} is $d$, but now it is extremely hard to calculate $d$ from $(n,e)$. Then you can post your public key online and take your message $M$ and break it into $\{m\}$ where $0 \leq m < n$ for all $m$, and encrypt each part of the message in turn by $c = m^e$. Then we can decode it by $m = c^d$.
\end{theorem}

\begin{theorem}
A number $n$ is Carmichael if and only if it is square-free and if $p$ is a prime which divides $p-n$ then $p-1$ divides $n-1$.
\end{theorem}

\begin{theorem}
Let $p$ be an odd prime. Then there exist integers $a,b$ such that $p = a^2 + b^2$ if and only if $p \equiv 1 \pmod{4}$.
\end{theorem}

\begin{proof}[Forward direction]
Suppose that $p$ is a sum of squares. If $x \in \mathbb{Z}$ then $x^2 \equiv 1$ or $0$ modulo $4$, which we check by squaring all $\bar{x} \in \mathbb{Z}/4\mathbb{Z}$. Since $p$ is the sum of two squares, $p$ is either $0$, $1$, or $2$ modulo $4$, and since $p$ is odd it must be $1 \pmod{4}$.
\end{proof}

\begin{definition}\label{d:group@c1}
A \emph{group} is an ordered pair $(G,\ast)$ where $G$ is a set and $\ast$ is a binary operation on $G$ (a function $\ast:G\times G\to G$) satisfying:
\begin{enumerate}
\item[(G0)] \textbf{Closure.} For all $a,b\in G$, $a\ast b\in G$. (This is built into ``$\ast$ is a binary operation $G\times G\to G$''.)
\item[(G1)] \textbf{Associativity.} For all $a,b,c\in G$, $(a\ast b)\ast c=a\ast(b\ast c)$.
\item[(G2)] \textbf{Identity.} There exists $e\in G$ with $e\ast a=a\ast e=a$ for all $a\in G$.
\item[(G3)] \textbf{Inverses.} For each $a\in G$ there exists $a^{-1}\in G$ with $a\ast a^{-1}=a^{-1}\ast a=e$.
\end{enumerate}
The group is \emph{abelian} (commutative) if in addition $a\ast b=b\ast a$ for all $a,b\in G$. We usually drop $\ast$ and write $ab$, and write $1$ (or $e$) for the identity.
\end{definition}

\begin{remark}\label{r:axiomstatus@c1}
A pair $(S,\ast)$ that satisfies (G0) and (G1) but not necessarily (G2),(G3) is a \emph{semigroup}; with (G2) added it is a \emph{monoid}. So a group is exactly a monoid in which every element is invertible. The single hardest axiom to verify in practice is associativity (G1); the easiest to \emph{disprove} a group with is the failure of one inverse (G3) or non-closure (G0).
\end{remark}

\begin{proposition}[Uniqueness of the identity]\label{p:idunique@c1}
If $(G,\ast)$ is a group, its identity element is unique.
\end{proposition}

\begin{proof}
Suppose $e$ and $f$ both satisfy (G2). Then $e=e\ast f$ (since $f$ is an identity, acting on the right of $e$) and $e\ast f=f$ (since $e$ is an identity, acting on the left of $f$). Hence $e=e\ast f=f$.
\end{proof}

\begin{proposition}[Uniqueness of inverses]\label{p:invunique@c1}
In a group, each $a\in G$ has a unique inverse.
\end{proposition}

\begin{pitfall}
The proof of Proposition~\ref{p:invunique@c1} uses associativity in the crucial middle step. Without (G1) inverses can genuinely fail to be unique, so never quote ``inverses are unique'' for a structure you have not checked is associative.
\end{pitfall}

