\begin{proposition}[Basic inverse identities] 
Let $G$ be a group and $a,b\in G$. Then:
\begin{enumerate}
\item[(a)] $(a^{-1})^{-1}=a$;
\item[(b)] $(ab)^{-1}=b^{-1} a^{-1}$ (the ``socks--shoes'' law).
\end{enumerate}
\end{proposition}

