\begin{remark}[Forward references: $S_n$, $D_{2n}$, $\GL$]\label{r:forwardgroups-mrg@c1}
Three families that D\&F flag here and construct in detail shortly:
\begin{enumerate}
\item[(i)] the \emph{symmetric group} $S_n$ of all bijections of $\{1,2,\dots,n\}$ to itself under composition, $|S_n|=n!$, nonabelian for $n\ge3$ (identity $\id$, inverse the inverse permutation);
\item[(ii)] the \emph{dihedral group} $D_{2n}$ of the $2n$ symmetries of a regular $n$-gon, with presentation $r^n=s^2=1$, $sr=r^{-1} s$ (so $|D_{2n}|=2n$), nonabelian for $n\ge3$;
\item[(iii)] the \emph{general linear group} $\GL_n(\mathbb{R})$ (more generally $\GL_n(F)$ over a field $F$) of invertible $n\times n$ matrices under matrix multiplication, identity the matrix $I$, inverse the matrix inverse, nonabelian for $n\ge2$.
\end{enumerate}
In each case associativity is inherited (composition of functions, multiplication of matrices), and the work is identifying the identity and confirming every element is invertible.
\end{remark}

\begin{remark}[$x^mx^n=x^{m+n}$ but NOT $(xy)^n=x^ny^n$]\label{r:powerlaws-mrg@c1}
The single-element laws above need no commutativity. The \emph{two}-element law $(xy)^n=x^ny^n$ does: it holds for all $n$ iff $xy=yx$. For example in $D_8$, $(rs)^2=rsrs=r(sr)s=r(r^{-1} s)s=s^2=1$, whereas $r^2s^2=r^2\ne1$. So never distribute a power over a product in a nonabelian group.
\end{remark}

\begin{definition}[Order of an element]\label{d:order-mrg@c1}
The \emph{order} of $x\in G$, written $\ord{x}$, is the least positive integer $n$ with $x^n=1$, if such an $n$ exists; otherwise $x$ has \emph{infinite order}, $\ord{x}=\infty$. Equivalently $\ord{x}=\bigl|\langle x\rangle\bigr|$, the size of the cyclic subgroup generated by $x$. The identity is the unique element of order $1$.
\end{definition}

\begin{proof}
($\Leftarrow$) If $k=qn$ then $x^k=(x^n)^q=1^q=1$. ($\Rightarrow$) Divide: $k=qn+r$ with $0\le r<n$. Then $1=x^k=(x^n)^q x^r=x^r$, and by minimality of $n$ this forces $r=0$, i.e.\ $n\mid k$. The last claims follow by applying this to $k=a-b$ and noting $1,x,\dots,x^{n-1}$ are pairwise distinct (a coincidence $x^i=x^j$, $0\le i<j<n$, would give $x^{j-i}=1$ with $0<j-i<n$).
\end{proof}

\begin{remark}[Order of $x$ versus order of $x^{-1}$]\label{r:orderfacts-mrg@c1}
A fact used constantly: $\ord{x^{-1}}=\ord{x}$, because $x^n=1\iff(x^{-1})^n=(x^n)^{-1}=1$, so $x$ and $x^{-1}$ have exactly the same powers equal to $1$. More generally, for any $g\in G$ the element $gxg^{-1}$ has the same order as $x$, since $(gxg^{-1})^n=gx^ng^{-1}$, which equals $1$ exactly when $x^n=1$. Thus order is unchanged by inversion -- the first reason orders organize the structure of a group.
\end{remark}

\begin{definition}\label{d:order@c1}
Let $G$ be a group (written multiplicatively, identity $1$) and $x\in G$. The \emph{order} of $x$, written $\ord{x}$, is the least integer $k>0$ with $x^k=1$, if such a $k$ exists; otherwise $\ord{x}=\infty$. In an additively written group (identity $0$) the same definition reads: $\ord{x}$ is the least $k>0$ with $kx=0$, else $\infty$.
\end{definition}

\begin{proposition}\label{p:unit-iff-coprime@c1}
$\bar a\in\mathbb{Z}/(n)\mathbb{Z}$ has a multiplicative inverse mod $n$ if and only if $\gcd(a,n)=1$. Hence $(\mathbb{Z}/(n)\mathbb{Z})^{\times}$ is exactly the set of such classes, and it is a group.
\end{proposition}

\begin{proof}
($\Leftarrow$) If $\gcd(a,n)=1$, Bezout gives integers $u,v$ with $au+nv=1$, so $\overline{a}\,\overline{u}=\overline{au}=\overline{1-nv}=\bar 1$; thus $\bar u=\bar a^{-1}$.
($\Rightarrow$) If $\bar a\,\bar b=\bar 1$ then $ab\equiv 1\pmod n$, i.e. $ab-1=nk$ for some $k\in\mathbb{Z}$, so $ab-nk=1$ and any common divisor of $a$ and $n$ divides $1$; hence $\gcd(a,n)=1$.
Closure: $\gcd(a,n)=\gcd(b,n)=1\Longrightarrow \gcd(ab,n)=1$. Associativity and $\bar 1$ are inherited from $\mathbb{Z}$, and inverses exist by the equivalence just proved. So $(\mathbb{Z}/(n)\mathbb{Z})^{\times}$ is a group of order $\varphi(n)=\#\{1\le a\le n\st \gcd(a,n)=1\}$.
\end{proof}

\begin{proposition}\label{p:order-zn@c1}
In $(\mathbb{Z}/(n)\mathbb{Z},+)$ the order of $\bar a$ is $\ord{\bar a}=\dfrac{n}{\gcd(a,n)}$. In particular $\ord{\bar 1}=n$, and $\bar a$ generates $\mathbb{Z}/(n)\mathbb{Z}$ iff $\gcd(a,n)=1$.
\end{proposition}

\begin{proof}
$\ord{\bar a}$ is the least $k>0$ with $k\bar a=\bar 0$, i.e. $n\mid ka$. Write $d=\gcd(a,n)$, $a=da'$, $n=dn'$ with $\gcd(a',n')=1$. Then $n\mid ka \Longleftrightarrow dn'\mid kda' \Longleftrightarrow n'\mid ka' \Longleftrightarrow n'\mid k$ (since $\gcd(a',n')=1$). The least such $k>0$ is $n'=n/d$.
\end{proof}

\begin{method}{How to compute $\ord{x}$ in any group}
Trigger: you are handed a specific element $x$ and asked ``what is $|x|$?'' or ``does $x$ have finite order?''
\begin{enumerate}
\item Compute the powers $x^1,x^2,x^3,\dots$ (additively: $1x,2x,3x,\dots$) one at a time.
\item The order is the FIRST exponent $k>0$ that returns the identity ($1$ multiplicatively, $0$ additively). Stop there.
\item Shortcut in $(\mathbb{Z}/(n)\mathbb{Z},+)$: $\ord{\bar a}=n/\gcd(a,n)$ (Prop.~\ref{p:order-zn@c1}); no power-listing needed.
\item Shortcut in $(\mathbb{Z}/(n)\mathbb{Z})^{\times}$: $\ord{\bar a}$ must divide $\varphi(n)$ (Lagrange), so only test exponents that divide $\varphi(n)$.
\item If no power ever returns the identity (e.g. a nonzero rational under $+$, or a real $\ne\pm1$ under $\times$), then $\ord{x}=\infty$.
\end{enumerate}
\end{method}

\begin{method}{How to identify the units $(\mathbb{Z}/(n)\mathbb{Z})^{\times}$}
Trigger: you must list $(\mathbb{Z}/(n)\mathbb{Z})^{\times}$, or decide whether a given $\bar a$ is invertible mod $n$.
\begin{enumerate}
\item List $a=1,2,\dots,n-1$ (and include $a=1$ always; never include $\bar 0$ for $n>1$).
\item Keep exactly those $a$ with $\gcd(a,n)=1$ (Prop.~\ref{p:unit-iff-coprime@c1}). Discard any $a$ sharing a prime factor with $n$.
\item Count: $\#(\mathbb{Z}/(n)\mathbb{Z})^{\times}=\varphi(n)$. Sanity-check via $\varphi(p^k)=p^k-p^{k-1}$ and $\varphi(mn)=\varphi(m)\varphi(n)$ for $\gcd(m,n)=1$.
\item To find an inverse of a unit $\bar a$, run the extended Euclidean algorithm on $a,n$ to get $au+nv=1$; then $\bar a^{-1}=\bar u$.
\end{enumerate}
\end{method}

\begin{pitfall}
Do not confuse the two groups. In $(\mathbb{Z}/(n)\mathbb{Z},+)$ every class is present and the operation is $+$; in $(\mathbb{Z}/(n)\mathbb{Z})^{\times}$ only the coprime classes are present and the operation is $\times$. ``$\ord{\bar 3}$ mod $12$'' is ambiguous until you say which group; additively $\ord{\bar 3}=4$, but $\bar 3$ is not even an element of $(\mathbb{Z}/(12)\mathbb{Z})^{\times}$ since $\gcd(3,12)=3\ne 1$.
\end{pitfall}

