\begin{proof}
Since $r^n=1$, the rotations are exactly $\{r^i:0\le i<n\}$, $n$ in number. The relation $sr=r^{-1} s$ lets us move every $s$ to the \emph{left} of every $r$: any word in $r,s$ collapses to $s^a r^i$ with $a\in\{0,1\}$ (using $s^2=1$) and $0\le i<n$ (using $r^n=1$). Hence every element is $r^i$ or $sr^i$, giving at most $2n$ elements. Geometrically $r$ has order $n$ (a rotation by $2\pi/n$) and $s\ne r^i$ for any $i$ (a reflection reverses orientation; rotations preserve it), so the two families are disjoint and the $2n$ listed symmetries are distinct. The polygon has exactly $2n$ symmetries (a vertex $0$ can go to any of $n$ positions, then orientation can be preserved or reversed: $n\cdot 2=2n$), so $|D_{2n}|=2n$ and the listing is complete; uniqueness of $r^i$ vs.\ $sr^i$ and of the exponent $i$ follows from $|D_{2n}|=2n$.
\end{proof}

\begin{method}{How to simplify a word and read off the order in $D_{2n}$}
\textit{Trigger.} Any product of $r$'s and $s$'s in $D_{2n}$, e.g.\ $(sr^a)(sr^b)$, $r^k s r^{-k}$, or $(sr^i)^m$.
\begin{enumerate}
\item \textbf{Push every $s$ left.} Repeatedly apply $r^k s = s r^{-k}$ to slide each $s$ past any $r$ on its left, flipping that $r$'s exponent sign.
\item \textbf{Cancel adjacent $s$'s} via $s^2=1$. You end with $s^a r^m$, $a\in\{0,1\}$.
\item \textbf{Reduce the exponent} $m$ modulo $n$ (since $r^n=1$) to land in $0\le m<n$.
\item \textbf{Read the answer:} $r^m$ is a rotation with $\ord{r^m}=n/\gcd(n,m)$; $sr^m$ is a reflection with order $2$.
\end{enumerate}
\textbf{Mnemonic:} ``$s$ flips the sign of every $r$ it jumps over.'' An \emph{even} number of $s$'s gives a rotation; an \emph{odd} number gives a reflection.
\end{method}

\begin{pitfall}
$D_{2n}$ is \emph{non-abelian} for $n\ge3$: $sr=r^{-1} s\ne rs$ unless $r=r^{-1}$. Never silently commute $r$ past $s$; you must use $rs=sr^{-1}$ (sign flip), not $rs=sr$.
\end{pitfall}

\begin{remark}\label{r:cyclic-normal@c1}
The rotation subgroup $\langle r\rangle=\{1,r,\dots,r^{n-1}\}\cong\mathbb{Z}/(n)\mathbb{Z}$ is normal in $D_{2n}$ (index $2$), and $D_{2n}/\langle r\rangle\cong\mathbb{Z}/(2)\mathbb{Z}$ records the rotation/reflection parity ($s$ flips parity). This is why an even number of $s$'s in any word yields a rotation and an odd number yields a reflection, the recognition shortcut used throughout.
\end{remark}

\begin{pitfall}
When reducing exponents, do it \emph{modulo} $n$, not arbitrarily: in $D_{8}$, $r^{-3}=r^{1}$ because $-3\equiv1\pmod4$, but in $D_{14}$, $r^{-3}=r^{4}$. Mixing up $n$ is the most common arithmetic slip.
\end{pitfall}

\begin{definition}[Symmetry of a polygon, as in D\&F]\label{d:symmetry-def-mrg@c1}
A \emph{symmetry} of the regular $n$-gon ($n\ge 3$) is a rigid motion of the plane that carries the polygon onto itself. Concretely, label the vertices $1,2,\dots,n$ consecutively, and record each symmetry by what it does to the vertices: it is a permutation $\sigma$ of $\{1,2,\dots,n\}$ that sends adjacent vertices to adjacent vertices. The set of all such symmetries, under composition of motions, is the dihedral group $D_{2n}$. (D\&F write the subscript $2n$ to display the order; some texts write $D_n$. Here $D_{2n}$ always has $2n$ elements.)
\end{definition}

\begin{proposition}[D\&F's adjacency count: there are exactly $2n$ symmetries]\label{p:count-2n-mrg@c1}
A symmetry of the regular $n$-gon is determined by where it sends vertex $1$ and where it sends the adjacent vertex $2$. Vertex $1$ may go to any of the $n$ vertices; once its image is fixed, the adjacent vertex $2$ must land on one of the two vertices adjacent to the image of $1$. Hence there are at most $n\cdot 2=2n$ symmetries, and since the $n$ rotations together with the $n$ reflections are all distinct symmetries, there are exactly $2n$.
\end{proposition}

\begin{proof}
Let $\sigma$ be a symmetry. Choose the image $\sigma(1)$: there are $n$ choices. Because $\sigma$ preserves adjacency and distances, $\sigma(2)$ must be one of the two neighbors of $\sigma(1)$, giving $2$ choices. Now $\sigma(1)$ and $\sigma(2)$ already determine $\sigma$ on every remaining vertex: vertex $3$ is the neighbor of $2$ other than $1$, so $\sigma(3)$ is forced to be the neighbor of $\sigma(2)$ other than $\sigma(1)$, and so on around the polygon. Thus $\sigma$ is determined by the pair $(\sigma(1),\sigma(2))$, so there are at most $2n$ symmetries. Exhibiting $2n$ distinct ones (the rotations $r^i$ and reflections $sr^i$, $0\le i<n$) shows the bound is met.
\end{proof}

\begin{remark}[Why D\&F insists $n\ge 3$ for the polygon picture]\label{r:n-ge-3-mrg@c1}
The geometric construction names $r$ as a rotation by $2\pi/n$ and $s$ as a reflection, which requires an honest regular $n$-gon, so $n\ge 3$. The same relations $r^n=s^2=1,\ rs=sr^{-1}$ make sense as an abstract presentation for $n=1,2$ as well, giving $D_2\cong\mathbb{Z}/(2)\mathbb{Z}$ and $D_4\cong\mathbb{Z}/(2)\mathbb{Z}\times\mathbb{Z}/(2)\mathbb{Z}$ (the Klein four-group, since $r^2=1$ forces $r=r^{-1}$, hence $rs=sr^{-1}=sr$ and the group is abelian); these degenerate cases are consistent but lie outside the polygon-symmetry picture that motivates the definition.
\end{remark}

\begin{definition}[Symmetric group]\label{d:sn@c1}
For $n\ge 1$, $S_n=\Sym(\{1,2,\dots,n\})$ is the group of all bijections
$\{1,\dots,n\}\to\{1,\dots,n\}$ under composition. Its identity is $\id$ (every point
fixed), and we compose \emph{right-to-left}: $(\sigma\tau)(x)=\sigma\big(\tau(x)\big)$,
so $\tau$ acts first.
\end{definition}

\begin{theorem}[Order of $S_n$]\label{t:order@c1}
$\ord{S_n}=n!$.
\end{theorem}

\begin{definition}[Cycle notation]\label{d:cycle@c1}
A \emph{$k$-cycle} $(a_1\,a_2\,\cdots\,a_k)$ is the permutation sending
$a_1\mapsto a_2\mapsto\cdots\mapsto a_k\mapsto a_1$ and fixing every other point. Two
cycles are \emph{disjoint} if they move no common point. A \emph{transposition} is a
$2$-cycle.
\end{definition}

\begin{theorem}[Disjoint-cycle decomposition]\label{t:dcd@c1}
Every $\sigma\in S_n$ is a product of disjoint cycles. This decomposition is unique up to
the order of the factors and up to cyclic rotation within each cycle (fixed points are
customarily omitted).
\end{theorem}

\begin{proposition}[Disjoint cycles commute]\label{p:comm@c1}
If cycles $\alpha,\beta$ are disjoint then $\alpha\beta=\beta\alpha$.
\end{proposition}

\begin{proof}
Let $x$ be arbitrary. If $\alpha$ moves $x$ then $\beta$ fixes $x$ and also fixes
$\alpha(x)$ (both lie in $\alpha$'s support, which $\beta$ avoids), so
$(\alpha\beta)(x)=\alpha(x)=(\beta\alpha)(x)$. Symmetrically if $\beta$ moves $x$. If
both fix $x$, both sides give $x$. Thus $\alpha\beta$ and $\beta\alpha$ agree everywhere.
\end{proof}

\begin{proposition}[Inverse reverses each cycle]\label{p:inv@c1}
$(a_1\,a_2\,\cdots\,a_k)^{-1}=(a_k\,a_{k-1}\,\cdots\,a_1)$, and for a product of disjoint
cycles $\sigma=\gamma_1\cdots\gamma_r$ we have
$\sigma^{-1}=\gamma_1^{-1}\cdots\gamma_r^{-1}$ (order is irrelevant since disjoint cycles
commute).
\end{proposition}

\begin{pitfall}
Do not read cycles left-to-right. D\&F applies the \emph{rightmost} factor first, so
$\sigma\tau$ means ``$\tau$ then $\sigma$.'' Reading the other way computes $\tau\sigma$,
which is usually a different permutation.
\end{pitfall}

\begin{method}{How to decompose a messy product into disjoint cycles}
Trigger: you are handed a product of several (possibly overlapping) cycles and asked for
its disjoint-cycle form, or you must compute an orbit structure / order.
\begin{enumerate}
\item Apply the multiply-method to get the single map $x\mapsto\sigma(x)$ for all $x$.
\item ``Follow the orbits'': start at the smallest point, write $a\mapsto\sigma(a)\mapsto
\sigma^2(a)\mapsto\cdots$ until you return; that closes one cycle.
\item Jump to the smallest unused point; repeat. Omit fixed points.
\item Sanity: the cycle lengths must sum to $n$ minus the number of fixed points; the order
of $\sigma$ is the $\lcm$ of the cycle lengths.
\end{enumerate}
\end{method}

\begin{method}{How to invert a permutation}
Trigger: you need $\sigma^{-1}$, or to solve $\sigma x=\tau$ (then $x=\sigma^{-1}\tau$).
\begin{enumerate}
\item Put $\sigma$ in disjoint-cycle form.
\item Reverse the entries of each cycle: $(a_1\,a_2\,\cdots\,a_k)\mapsto
(a_k\,\cdots\,a_2\,a_1)$. Equivalently keep $a_1$ first and reverse the rest:
$(a_1\,a_k\,a_{k-1}\,\cdots\,a_2)$.
\item Leave fixed points fixed. The reversed cycles are still disjoint.
\item Check: $\sigma\sigma^{-1}=\id$, i.e. composing should fix every point.
\end{enumerate}
\end{method}

\begin{pitfall}
Reverse each cycle \emph{individually}; do not reverse the whole written string across
cycle boundaries. And a transposition is its own inverse: $(a\,b)^{-1}=(a\,b)$.
\end{pitfall}

\begin{method}{How to compute a power $\sigma^m$}
Trigger: you want $\sigma^m$ or the order $\ord{\sigma}$.
\begin{enumerate}
\item If $\sigma$ is a single $k$-cycle, $\sigma^m$ advances each point by $m$ steps
around the wheel. When $\gcd(m,k)=1$, $\sigma^m$ is again a single $k$-cycle; in general
$\sigma^m$ splits into $\gcd(m,k)$ cycles each of length $k/\gcd(m,k)$.
\item If $\sigma=\gamma_1\cdots\gamma_r$ disjoint, then $\sigma^m=\gamma_1^m\cdots
\gamma_r^m$ (disjoint cycles commute), so power each factor separately.
\item $\ord{\sigma}=\lcm$ of the cycle lengths.
\end{enumerate}
\end{method}

\begin{definition}[Disjoint cycles, cycle type]\label{d:cyctype@c1}
Two cycles are \emph{disjoint} if no integer is moved by both. Every $\sigma\in S_n$ factors as a product of disjoint cycles, unique up to the order of the factors. Listing the lengths of those cycles (including the $1$-cycles, i.e.\ the fixed points) as a partition of $n$ gives the \emph{cycle type} of $\sigma$. For example $\sigma=(1\,2\,3)(4\,5)\in S_5$ has cycle type $3+2$; the identity of $S_5$ has cycle type $1+1+1+1+1$.
\end{definition}

\begin{lemma}[Order of a single cycle]\label{l:cycleorder@c1}
A $k$-cycle $\tau=(a_1\,a_2\,\cdots\,a_k)$ has order exactly $k$.
\end{lemma}

\begin{proof}
The cycle sends $a_i\mapsto a_{i+1}$ (indices mod $k$), so $\tau^m$ sends $a_i\mapsto a_{i+m}$. Thus $\tau^m=\id$ iff $a_{i+m}=a_i$ for all $i$ iff $m\equiv 0\pmod{k}$, i.e.\ iff $k\mid m$. The least positive such $m$ is $k$, so $\ord{\tau}=k$.
\end{proof}

\begin{theorem}[Order $=\lcm$ of disjoint cycle lengths]\label{t:lcm@c1}
If $\sigma=\tau_1\tau_2\cdots\tau_r$ is a product of \emph{disjoint} cycles of lengths $k_1,k_2,\dots,k_r$, then
\[
\ord{\sigma}=\lcm(k_1,k_2,\dots,k_r).
\]
\end{theorem}

\begin{pitfall}
The cycles must be \emph{disjoint} before you read off lengths. $(1\,2\,3)(2\,4)$ is NOT type $3+2$ of order $6$; the cycles share the point $2$, so you must first multiply them out: $(1\,2\,3)(2\,4)=(1\,2\,4\,3)$, a $4$-cycle of order $4$.
\end{pitfall}

\begin{pitfall}
Use $\lcm$, never the product. $\ord{(1\,2\,3)(4\,5\,6)}=\lcm(3,3)=3$, not $9$.
\end{pitfall}

\begin{method}{How to compute $\ord{\sigma}$ for $\sigma\in S_n$}
\begin{enumerate}
\item Write $\sigma$ in disjoint cycle notation. If a product is given with overlapping cycles, multiply it out first (right-to-left) until the cycles are disjoint.
\item Record the length of each disjoint cycle: $k_1,k_2,\dots,k_r$.
\item Output $\ord{\sigma}=\lcm(k_1,\dots,k_r)$.
\item Sanity check: $\ord{\sigma}\mid n!$ always holds, but $\ord{\sigma}\le n$ \emph{is false in general} (e.g.\ $\ord{(1\,2\,3)(4\,5)}=6>5$); what does hold is $k_j\le n$ for each $j$ and $\sum k_j\le n$. Verify by computing $\sigma^{\ord{\sigma}}$ on one moved point \emph{of every cycle} (it must fix each of them); a single moved point is not enough.
\end{enumerate}
\textit{Trigger.} Use this \emph{whenever} a problem asks for the order of an explicit permutation, or the order of an element of $S_n$, $A_n$, or any group of permutations.
\end{method}

\begin{wex}{Order in $A_8$, a $5+3$ element}
Compute $\ord{(1\,2\,3\,4\,5)(6\,7\,8)}$ and confirm the element lies in $A_8$.
\wrec Disjoint $5$-cycle and $3$-cycle. Order by Theorem~\ref{t:lcm@c1}; parity by counting transpositions.
\wsol $\lcm(5,3)=15$ since $\gcd(5,3)=1$ forces $\lcm=5\cdot3$. So $\ord{\sigma}=15$. Parity: a $5$-cycle is a product of $4$ transpositions (even), a $3$-cycle is a product of $2$ transpositions (even); total $6$ transpositions, so $\sgn(\sigma)=(+1)$ and $\sigma\in A_8$. Check: $\sigma^{15}=\id$ ($5\mid15$, $3\mid15$); $\sigma^5$ leaves $(6\,7\,8)^5=(6\,7\,8)^2=(6\,8\,7)\neq\id$; $\sigma^3$ leaves $(1\,2\,3\,4\,5)^3\neq\id$. Minimal exponent $15$.
\end{wex}

\begin{wex}{Count the $4$-cycles in $S_4$ and read off their order}
How many $4$-cycles does $S_4$ have, and what is their order?
\wrec Cycle type $4$ (one $4$-cycle, no fixed points): $m_4=1$. Order is $\lcm(4)=4$ by Theorem~\ref{t:lcm@c1}.
\wsol Count: a $4$-set yields $(4-1)!=3!=6$ distinct $4$-cycles, and there is only one way to choose all $4$ of the $4$ points. So $6$. Via formula: $4!/(4^1\cdot1!)=24/4=6$. Each has order $\lcm(4)=4$. Check: $S_4$ has $24$ elements; partitioning $24=1(\text{id})+6(\text{type }2)+3(\text{type }2{+}2)+8(\text{type }3{+}1)+6(\text{type }4)=24$, the $4$-cycle count $6$ fits.
\end{wex}

\begin{wex}{Count elements of order $3$ in $A_4$}
How many elements of order $3$ lie in $A_4$?
\wrec Order $3$ means $\lcm$ of lengths $=3$; in $S_4$ the only possibility is type $3+1$ (a $3$-cycle). All $3$-cycles are even, so they all lie in $A_4$. Count $3$-cycles in $S_4$.
\wsol Type $3+1$ in $S_4$: $m_3=1,m_1=1$. Formula: $4!/(3^1\cdot1!\cdot1^1\cdot1!)=24/3=8$. Constructive check: $\binom{4}{3}=4$ choices of moved points, each giving $(3-1)!=2$ cycles, total $4\cdot2=8$. Since every $3$-cycle is even, all $8$ lie in $A_4$. As $|A_4|=12$, the order-$3$ elements ($8$) plus the identity ($1$) plus the three double transpositions ($3$) give $8+1+3=12$, confirming the count.
\end{wex}

\begin{definition}[Cycle, $1$-cycles, and the standing notational conventions]\label{d:cyclenotation-mrg@c1}
A \emph{cycle} is a string of integers $(a_1\,a_2\,\cdots\,a_m)$ representing the permutation that sends $a_i\mapsto a_{i+1}$ for $1\le i<m$, sends $a_m\mapsto a_1$, and fixes every integer not appearing in the string. The number $m$ of entries is the \emph{length} of the cycle, and such a cycle is called an \emph{$m$-cycle}. Two conventions are used throughout:
\begin{enumerate}
\item Numbers fixed by a permutation are \emph{not} written; in particular a $1$-cycle is the identity. Written on its own, a single $1$-cycle $(a_1)$ \emph{is} the identity permutation.
\item The same cycle may be written starting at any of its entries: $(a_1\,a_2\,\cdots\,a_m)=(a_2\,a_3\,\cdots\,a_m\,a_1)$, and so on. Thus a cycle has $m$ equally valid notations.
\end{enumerate}
\end{definition}

\begin{remark}\label{r:notdisjoint-mrg@c1}
In a product of cycles a number \emph{may} appear in more than one cycle; the product is still a well-defined permutation, computed right-to-left, but it is not yet in the standard ``product of disjoint cycles'' form. One must multiply such an expression out before reading off cycle lengths. This is the situation flagged in the first Caution after Theorem~\ref{t:lcm@c1}, and the worked example ``Overlapping cycles: multiply first'' carries out the multiplication.
\end{remark}

\begin{proposition}[Powers of a single cycle]\label{p:cyclepower-mrg@c1}
Let $\tau=(a_1\,a_2\,\cdots\,a_m)$ be an $m$-cycle. Then $\tau^t$ has order $m/\gcd(m,t)$, and $\tau^t$ is itself a single $m$-cycle if and only if $\gcd(m,t)=1$. In general $\tau^t$ splits into $\gcd(m,t)$ disjoint cycles, each of length $m/\gcd(m,t)$.
\end{proposition}

\begin{proof}
Write $d=\gcd(m,t)$. The element $a_i$ moves under $\tau^t$ to $a_{i+t}$ (indices mod $m$), so the orbit of $a_1$ under $\tau^t$ is $\{a_1,a_{1+t},a_{1+2t},\dots\}$, whose size equals the additive order of $t$ in $\mathbb{Z}/(m)\mathbb{Z}$, namely $m/d$. The $m$ points thus partition into orbits all of this common size $m/d$, and there are $m/(m/d)=d$ of them. Hence $\tau^t$ is a product of $d$ disjoint $(m/d)$-cycles, of order $\lcm(m/d,\dots,m/d)=m/d$ by Theorem~\ref{t:lcm@c1}. It is a single $m$-cycle exactly when $d=1$.
\end{proof}

\begin{definition}\label{d:gln@c1}
$\GL_n(F)$ is the set of invertible $n\times n$ matrices with entries in $F$, under matrix multiplication. $\SL_n(F)=\{A\in\GL_n(F)\st \det A=1\}$ is the \emph{special linear group}.
\end{definition}

\begin{proposition}\label{p:glgroup@c1}
$\GL_n(F)$ is a group, and $A\in M_n(F)$ lies in $\GL_n(F)$ if and only if $\det A\neq 0$ (equivalently $\det A\in F^\times$).
\end{proposition}

 egin{proof}
Matrix multiplication is associative and the identity matrix $I$ is a two-sided identity, so we need only closure and inverses. A square matrix $A$ over a field has a two-sided inverse iff $\det A
eq 0$; in that case $\det(A^{-1})=(\det A)^{-1}
eq 0$, so $A^{-1}\in\GL_n(F)$. For closure, if $\det A
eq 0$ and $\det B
eq 0$ then $\det(AB)=\det A\,\det B
eq 0$ (a field has no zero divisors), so $AB\in\GL_n(F)$. Hence $\GL_n(F)$ is closed and contains inverses, so it is a group.
\end{proof}

\begin{proposition}\label{p:detsurj@c1}
The map $\det:\GL_n(F)\to F^\times$ is a surjective group homomorphism with kernel $\SL_n(F)$. Consequently $\SL_n(F)\nor\GL_n(F)$ and $\GL_n(F)/\SL_n(F)\cong F^\times$.
\end{proposition}

\begin{proof}
\emph{Homomorphism:} $\det(AB)=\det A\,\det B$ is the multiplicativity of the determinant, and the target operation on $F^\times$ is multiplication, so $\det$ is a homomorphism into $F^\times$ (the image is in $F^\times$ by Proposition~\ref{p:glgroup@c1}).
\emph{Surjective:} for $a\in F^\times$ the matrix $\diag(a,1,\dots,1)$ has determinant $a$, so every value is hit.
\emph{Kernel:} $\det A=1$ is exactly the defining condition of $\SL_n(F)$, so $\ker(\det)=\SL_n(F)$.
The kernel of a homomorphism is normal, and the First Isomorphism Theorem gives $\GL_n(F)/\SL_n(F)\cong\det(\GL_n(F))=F^\times$.
\end{proof}

\begin{method}{Recognize and invert/multiply in $\GL_2(F)$}
Use this whenever you must decide if a $2\times 2$ matrix is invertible, or multiply/invert one, over a field (especially $\F_p$).
\begin{enumerate}
\item \textbf{Invertibility test:} for $A=\begin{psmallmatrix}a&b\\c&d\end{psmallmatrix}$ compute $\det A=ad-bc$ \emph{in $F$}. Over $\F_p$, reduce $ad-bc$ mod $p$. Then $A\in\GL_2(\F_p)\iff ad-bc\not\equiv 0\pmod p$.
\item \textbf{Inverse formula:} if $\det A=\Delta\neq 0$, then $A^{-1}=\Delta^{-1}\begin{psmallmatrix}d&-b\\-c&a\end{psmallmatrix}$, where $\Delta^{-1}$ is the multiplicative inverse of $\Delta$ in $F^\times$. Over $\F_p$, find $\Delta^{-1}$ by solving $\Delta\,x\equiv 1\pmod p$.
\item \textbf{Product:} multiply rows-into-columns, then reduce each entry mod $p$.
\end{enumerate}
Trigger: ``invertible over $\F_p$,'' ``inverse mod $p$,'' or ``$\GL_2$/$\SL_2$.''
\end{method}

\begin{pitfall}
Over $\F_p$ a nonzero determinant is enough --- you do \emph{not} need $\det=\pm 1$. E.g.\ $\det=2$ over $\F_5$ is invertible because $2\not\equiv 0\pmod 5$ (indeed $2^{-1}\equiv 3$), although $2\not\equiv\pm 1\pmod 5$. The ``$\det=\pm 1$'' instinct is from $\GL_n(\mathbb{Z})$, a different group.
\end{pitfall}

\begin{wex}{Multiply and invert a specific matrix over $\F_3$}
Let $A=\begin{psmallmatrix}2&1\\1&1\end{psmallmatrix}$ and $B=\begin{psmallmatrix}0&2\\1&1\end{psmallmatrix}$ over $\F_3$. Compute $\det A$, $\det B$, $AB$, and $A^{-1}$.
\wrec Two $2\times 2$ matrices over $\F_3$: use the Method box. Determinant first (to confirm membership and to get $\Delta^{-1}$ for the inverse), then the row-into-column product, then the adjugate formula.
\wsol \textbf{Determinants:} $\det A=2\cdot 1-1\cdot 1=1\equiv 1\pmod 3$, so $A\in\SL_2(\F_3)$. $\det B=0\cdot 1-2\cdot 1=-2\equiv 1\pmod 3$, so $B\in\SL_2(\F_3)$ too.

\textbf{Product $AB$:}
\[
AB=\begin{pmatrix}2&1\\1&1\end{pmatrix}\begin{pmatrix}0&2\\1&1\end{pmatrix}
=\begin{pmatrix}2\cdot0+1\cdot1 & 2\cdot2+1\cdot1\\ 1\cdot0+1\cdot1 & 1\cdot2+1\cdot1\end{pmatrix}
=\begin{pmatrix}1&5\\1&3\end{pmatrix}
\equiv\begin{pmatrix}1&2\\1&0\end{pmatrix}\pmod 3 .
\]
(Check $\det(AB)\equiv 1\cdot 0-2\cdot 1=-2\equiv 1$, matching $\det A\,\det B=1\cdot 1$.)

\textbf{Inverse $A^{-1}$:} here $\Delta=\det A=1$, so $\Delta^{-1}=1$, and
\[
A^{-1}=1\cdot\begin{pmatrix}1&-1\\-1&2\end{pmatrix}\equiv\begin{pmatrix}1&2\\2&2\end{pmatrix}\pmod 3 .
\]
\textit{Check.} $A\,A^{-1}=\begin{psmallmatrix}2&1\\1&1\end{psmallmatrix}\begin{psmallmatrix}1&2\\2&2\end{psmallmatrix}=\begin{psmallmatrix}2\cdot1+1\cdot2 & 2\cdot2+1\cdot2\\ 1\cdot1+1\cdot2 & 1\cdot2+1\cdot2\end{psmallmatrix}=\begin{psmallmatrix}4&6\\3&4\end{psmallmatrix}\equiv\begin{psmallmatrix}1&0\\0&1\end{psmallmatrix}\pmod 3$. Correct.
\end{wex}

\begin{wex}{Inverse when $\det\neq 1$: a matrix over $\F_7$}
Invert $A=\begin{psmallmatrix}3&1\\2&4\end{psmallmatrix}$ over $\F_7$.
\wrec The adjugate formula needs $\Delta^{-1}$ in $F^\times$. Here $\Delta\neq 1$, so the real work is computing the modular inverse of $\Delta$ in $\F_7$. This is the case students mishandle by forgetting the scalar $\Delta^{-1}$.
\wsol $\Delta=\det A=3\cdot 4-1\cdot 2=12-2=10\equiv 3\pmod 7$, nonzero, so $A\in\GL_2(\F_7)$. Find $3^{-1}$ in $\F_7$: $3\cdot 5=15\equiv 1$, so $3^{-1}\equiv 5$. Then
\[
A^{-1}=3^{-1}\begin{pmatrix}4&-1\\-2&3\end{pmatrix}
=5\begin{pmatrix}4&-1\\-2&3\end{pmatrix}
=\begin{pmatrix}20&-5\\-10&15\end{pmatrix}
\equiv\begin{pmatrix}6&2\\4&1\end{pmatrix}\pmod 7 ,
\]
using $20\equiv 6$, $-5\equiv 2$, $-10\equiv 4$, $15\equiv 1\pmod 7$.
\textit{Check.} $A\,A^{-1}=\begin{psmallmatrix}3&1\\2&4\end{psmallmatrix}\begin{psmallmatrix}6&2\\4&1\end{psmallmatrix}=\begin{psmallmatrix}18+4 & 6+1\\12+16 & 4+4\end{psmallmatrix}=\begin{psmallmatrix}22&7\\28&8\end{psmallmatrix}\equiv\begin{psmallmatrix}1&0\\0&1\end{psmallmatrix}\pmod 7$. Correct.
\end{wex}

\begin{wex}{Noncommutativity is real}
With $A=\begin{psmallmatrix}2&1\\1&1\end{psmallmatrix}$, $B=\begin{psmallmatrix}0&2\\1&1\end{psmallmatrix}$ over $\F_3$ as above, show $AB\neq BA$.
\wrec $\GL_n(F)$ is nonabelian for $n\ge 2$; to \emph{prove} it for specific matrices, just compute both products and exhibit one differing entry.
\wsol We found $AB\equiv\begin{psmallmatrix}1&2\\1&0\end{psmallmatrix}$. Now
\[
BA=\begin{pmatrix}0&2\\1&1\end{pmatrix}\begin{pmatrix}2&1\\1&1\end{pmatrix}
=\begin{pmatrix}0+2 & 0+2\\ 2+1 & 1+1\end{pmatrix}
=\begin{pmatrix}2&2\\3&2\end{pmatrix}\equiv\begin{pmatrix}2&2\\0&2\end{pmatrix}\pmod 3 .
\]
The $(1,1)$ entries differ ($1$ vs $2$), so $AB\neq BA$.
\textit{Check.} Both have determinant $1\cdot 0-2\cdot 1=-2\equiv 1$ and $2\cdot 2-2\cdot 0=4\equiv 1$, as forced by $\det(AB)=\det(BA)=\det A\det B$; equal determinants but unequal matrices is exactly how noncommutativity shows up here.
\end{wex}

\begin{method}{Compute the order of an element of $\GL_2(\F_p)$}
Use this when asked for $\ord{A}$, $A\in\GL_2(\F_p)$.
\begin{enumerate}
\item By Lagrange, $\ord{A}$ divides $\ord{\GL_2(\F_p)}=(p^2-1)(p^2-p)$; this bounds the search.
\item Compute $A^2,A^3,\dots$ reducing mod $p$ each step until you reach $I$. The first $k$ with $A^k=I$ is $\ord{A}$.
\item Shortcuts: a diagonal matrix $\diag(\lambda,\mu)$ has order $\lcm(\ord{\lambda},\ord{\mu})$ in $F^\times$; a transvection $\begin{psmallmatrix}1&1\\0&1\end{psmallmatrix}$ has order $p$ since $\begin{psmallmatrix}1&1\\0&1\end{psmallmatrix}^k=\begin{psmallmatrix}1&k\\0&1\end{psmallmatrix}$.
\end{enumerate}
Trigger: ``order of this matrix,'' ``smallest $k$ with $A^k=I$.''
\end{method}

\begin{wex}{A transvection has order $p$}
Compute $\ord{T}$ for $T=\begin{psmallmatrix}1&1\\0&1\end{psmallmatrix}$ in $\GL_2(\F_3)$ and in $\GL_2(\F_5)$.
\wrec Upper-triangular unipotent matrix: use the transvection shortcut $T^k=\begin{psmallmatrix}1&k\\0&1\end{psmallmatrix}$ and find the smallest $k$ with $k\equiv 0$ in $F$.
\wsol By induction $T^k=\begin{psmallmatrix}1&k\\0&1\end{psmallmatrix}$ (each multiplication adds $1$ to the top-right). We need $k\equiv 0\pmod p$:
over $\F_3$, smallest such $k$ is $3$, so $\ord{T}=3$ (indeed $T^3=\begin{psmallmatrix}1&3\\0&1\end{psmallmatrix}\equiv I$);
over $\F_5$, smallest is $5$, so $\ord{T}=5$.
\textit{Check.} $3\mid 48$ and $5\mid\ord{\GL_2(\F_5)}=(25-1)(25-5)=24\cdot 20=480$. The element order equals the characteristic $p$ --- a hallmark of nonidentity unipotent elements of $\GL_2(\F_p)$.
\end{wex}

\begin{proof}
An $n\times n$ matrix is invertible iff its columns form a basis of $F^n=\F_p^n$, equivalently an ordered linearly independent list of $n$ vectors. Build the columns one at a time. The first column $v_1$ can be any nonzero vector: $p^n-1$ choices ($p^n$ vectors, minus the zero vector). Having chosen independent $v_1,\dots,v_k$, the next column $v_{k+1}$ must avoid their span, which has $p^k$ vectors; so there are $p^n-p^k$ choices. Multiplying, $\ord{\GL_n(\F_p)}=\prod_{k=0}^{n-1}(p^n-p^k)$.

For $n=2$ this is $(p^2-1)(p^2-p)$. Finally $\det:\GL_2(\F_p)\twoheadrightarrow\F_p^\times$ has $\ord{\F_p^\times}=p-1$, and by Proposition~\ref{p:detsurj@c1} all fibers of a surjective homomorphism have equal size $\ord{\SL_2(\F_p)}$; since the fibers are the cosets of $\ker\det=\SL_2(\F_p)$, Lagrange gives $\ord{\SL_2(\F_p)}=\ord{\GL_2(\F_p)}/(p-1)$.
\end{proof}

