Title: Count $\ord{\GL_2(\F_p)}$ and $\ord{\SL_2(\F_p)}$
Content:
\begin{method}{Count $\ord{\GL_2(\F_p)}$ and $\ord{\SL_2(\F_p)}$}
Use this whenever a group order over $\F_p$ is requested.
\begin{enumerate}
\item Columns-as-basis count: first column $p^2-1$ ways (any nonzero vector), second column $p^2-p$ ways (any vector outside the line spanned by the first). Multiply: $\ord{\GL_2(\F_p)}=(p^2-1)(p^2-p)$.
\item Divide by $\ord{F^\times}=p-1$ to get $\ord{\SL_2(\F_p)}$ (kernel of $\det$).
\end{enumerate}
Trigger: ``how many invertible matrices,'' ``order of $\GL_2(\F_p)$ or $\SL_2$.''
\end{method}

latex:
\begin{method}{Count $\ord{\GL_2(\F_p)}$ and $\ord{\SL_2(\F_p)}$}
Use this whenever a group order over $\F_p$ is requested.
\begin{enumerate}
\item Columns-as-basis count: first column $p^2-1$ ways (any nonzero vector), second column $p^2-p$ ways (any vector outside the line spanned by the first). Multiply: $\ord{\GL_2(\F_p)}=(p^2-1)(p^2-p)$.
\item Divide by $\ord{F^\times}=p-1$ to get $\ord{\SL_2(\F_p)}$ (kernel of $\det$).
\end{enumerate}
Trigger: ``how many invertible matrices,'' ``order of $\GL_2(\F_p)$ or $\SL_2$.''
\end{method}

\begin{pitfall}
$\GL_2(\F_5)/\SL_2(\F_5)\cong\F_5^\times$ is cyclic of order $4$, but $\GL_2(\F_5)$ itself is far from abelian. Do not confuse the quotient (which only remembers determinants) with the whole group. Two matrices in the same coset can fail to commute; they merely have the same determinant.
\end{pitfall}

\begin{definition}\label{d:fieldgl-mrg@c1}
A \emph{field} is a set $F$ with two operations $+$ and $\cdot$ such that $(F,+)$ is an abelian group with identity $0$, $F^\times=F\setminus\{0\}$ is an abelian group under $\cdot$ with identity $1$, and the distributive law $a\cdot(b+c)=a\cdot b+a\cdot c$ holds. The fields used below are $\mathbb{Q}$, $\mathbb{R}$, $\mathbb{C}$, and the finite fields $\F_p=\mathbb{Z}/(p)\mathbb{Z}$ for $p$ prime, where entries of a matrix are reduced mod $p$ and $\GL_n(\F_p)$ is a finite group.
\end{definition}

\begin{remark}\label{r:invcrit-mrg@c1}
The point the book stresses about the invertibility criterion $\det A\neq 0$ (Proposition~\ref{p:glgroup@c1}) is that ``invertible'' is relative to the field: the \emph{same} integer matrix can be invertible over one $\F_p$ and singular over another, because $\det A$ is computed in $\mathbb{Z}$ but tested in $F$. The fragment's first worked example shows exactly this for $\begin{psmallmatrix}2&4\\3&1\end{psmallmatrix}$ over $\F_5$ versus $\F_3$.
\end{remark}

\begin{proof}
If $F$ is infinite, the scalar matrices $aI$ for $a\in F^\times$ already give infinitely many distinct elements of $\GL_n(F)$, so the group is infinite. If $\ord{F}=q<\infty$, the columns-as-basis count of the fragment's Theorem~\ref{t:count@c1} applies verbatim with $p$ replaced by $q$: the first column is any nonzero vector ($q^n-1$ choices) and, having chosen independent columns $v_1,\dots,v_k$, the next must avoid their span of size $q^k$ ($q^n-q^k$ choices). The product is finite, so $\GL_n(F)$ is finite.
\end{proof}

\begin{wex}{A concrete product and inverse inside the list}
Inside $\GL_2(\F_2)$, multiply $A=\begin{psmallmatrix}1&1\\0&1\end{psmallmatrix}$ by $B=\begin{psmallmatrix}0&1\\1&0\end{psmallmatrix}$ both ways, and find $A^{-1}$.
\wrec Two members of the explicit list above: carry out the row-into-column products mod $2$ and read the results off the same six matrices. The inverse uses the $\F_2$ adjugate formula with $\Delta^{-1}=1$.
\wsol \textbf{Products.}
\[
AB=\begin{pmatrix}1&1\\0&1\end{pmatrix}\begin{pmatrix}0&1\\1&0\end{pmatrix}
=\begin{pmatrix}0+1&1+0\\0+1&0+0\end{pmatrix}
=\begin{pmatrix}1&1\\1&0\end{pmatrix},
\]
\[
BA=\begin{pmatrix}0&1\\1&0\end{pmatrix}\begin{pmatrix}1&1\\0&1\end{pmatrix}
=\begin{pmatrix}0+0&0+1\\1+0&1+0\end{pmatrix}
=\begin{pmatrix}0&1\\1&1\end{pmatrix}.
\]
Both lie in the six-element list, and $AB\neq BA$, so $\GL_2(\F_2)$ is nonabelian even though it has only $6$ elements.
\textbf{Inverse.} $\det A=1\cdot1-1\cdot0=1$, so $\Delta^{-1}=1$ and $A^{-1}=\begin{psmallmatrix}d&-b\\-c&a\end{psmallmatrix}=\begin{psmallmatrix}1&-1\\0&1\end{psmallmatrix}\equiv\begin{psmallmatrix}1&1\\0&1\end{psmallmatrix}\pmod 2$. Thus $A$ is its own inverse.
\textit{Check.} $A^2=\begin{psmallmatrix}1&1\\0&1\end{psmallmatrix}\begin{psmallmatrix}1&1\\0&1\end{psmallmatrix}=\begin{psmallmatrix}1&2\\0&1\end{psmallmatrix}\equiv\begin{psmallmatrix}1&0\\0&1\end{psmallmatrix}=I\pmod 2$, confirming $A^{-1}=A$ and $\ord{A}=2$. This is the transvection shortcut $T^k=\begin{psmallmatrix}1&k\\0&1\end{psmallmatrix}$ at $p=2$.
\end{wex}

\begin{proposition}\label{p:nonabelian-mrg@c1}
For every field $F$ and every $n\ge 2$, $\GL_n(F)$ is nonabelian. For $n=1$, $\GL_1(F)\cong F^\times$ is abelian.
\end{proposition}

\begin{remark}\label{r:slnonab-mrg@c1}
The witnesses $E,E'$ above both have determinant $1$, so they lie in $\SL_n(F)$; hence $\SL_n(F)$ is also nonabelian for every $n\ge 2$. The same pair witnesses noncommutativity over every field at once, which is why a single computation settles the claim for $\mathbb{Q},\mathbb{R},\mathbb{C}$ and all $\F_p$ simultaneously.
\end{remark}

\begin{pitfall}
The factorization $\ord{\GL_2(\F_p)}=p(p-1)^2(p+1)$ counts the group; it does \emph{not} by itself name a cyclic subgroup of each size. In particular, divisibility by $(p-1)^2$ reflects the diagonal matrices $\diag(a,b)$ with $a,b\in\F_p^\times$, which form an abelian subgroup of order $(p-1)^2$ that is \emph{not} cyclic when $p-1>1$ (it is a product of two copies of $\F_p^\times$). So do not read element orders off the factors of the count.
\end{pitfall}

