\begin{exers}{Additional exercises.}
\item Let $F$ be a field. Recall $\GL_n(F)=\{A\st A is n\times n over F with \det A\neq 0\}$.
 \begin{enumerate}
 \item[(a)] Verify directly from the axioms that $\GL_2(\F_2)$ is a group of order $6$ by listing all six matrices.
 \item[(b)] Exhibit two elements of $\GL_2(\F_2)$ that do not commute, and conclude $\GL_2(\F_2)$ is nonabelian.
 \item[(c)] Find an element of $\GL_2(\F_2)$ of order $3$ and an element of order $2$.
 \end{enumerate}

\item Let $A=\begin{pmatrix} 1 & 1 \\ 0 & 1\end{pmatrix}\in\GL_2(R)$.
 \begin{enumerate}
 \item[(a)] Compute $A^n$ for $n\inZ$ and prove your formula by induction.
 \item[(b)] Deduce $\ord{A}=\infty$ in $\GL_2(R)$.
 \item[(c)] Now regard $A$ as an element of $\GL_2(Z/(3)Z)$ (reduce entries mod $3$). Compute $\ord{A}$ there.
 \end{enumerate}

\item Let $p$ be a prime. Show that $|\GL_2(\F_p)|=(p^2-1)(p^2-p)$ by counting ordered pairs of linearly independent columns: the first column may be any nonzero vector and the second any vector not in the span of the first. Use this to compute $|\GL_2(\F_3)|$ and $|\GL_2(\F_5)|$.

\item Let $B=\left\{\begin{pmatrix} a & b \\ 0 & d\end{pmatrix}\st a,d\in F^\times,\ b\in F\right\}$, the upper-triangular invertible $2\times2$ matrices over a field $F$.
 \begin{enumerate}
