  \node[cglab,below left=2pt of j] {$j$};
  \node[cglab,below right=2pt of k] {$k$};
  \node[align=center] at (0,-2.6) {Forward arrows in the cyclic order $i\to j\to k\to i$ give a {\bf +}\\ ($ij=k$, $jk=i$, $ki=j$); going backward flips the sign to {\bf $-$}.};
\end{tikzpicture}
\end{center}

Reading the cycle $i\to j\to k\to i$: \emph{the product of two consecutive letters, in cyclic order, is the next letter with a $+$ sign}; reversing the two factors flips the sign. Squaring any of $i,j,k$ gives $-1$.

\begin{method}{How to multiply two quaternions $\pm a$ and $\pm b$}
To compute $(\varepsilon_1 a)(\varepsilon_2 b)$ where $\varepsilon_1,\varepsilon_2\in\{+1,-1\}$ and $a,b\in\{1,i,j,k\}$:
\begin{enumerate}
\item \textbf{Pull out the signs.} The total sign is $\varepsilon_1\varepsilon_2$; set it aside and multiply $a\cdot b$.
\item \textbf{If either factor is $1$:} the product is the other factor.
\item \textbf{If $a=b$ (same letter, both in $\{i,j,k\}$):} the product is $-1$.
\item \textbf{If $a\neq b$ are distinct letters in $\{i,j,k\}$:} read the cyclic order $i\to j\to k\to i$. If $a\to b$ is a \emph{forward} step (one of $ij$, $jk$, $ki$), the product is the third letter with sign $+$. If $a\to b$ is \emph{backward} (one of $ji$, $kj$, $ik$), the product is the third letter with sign $-$.
\item \textbf{Reattach the sign} $\varepsilon_1\varepsilon_2$ from step 1.
\end{enumerate}
\textit{Recognition trigger.} Use this whenever you see a product of two of the eight symbols $\pm1,\pm i,\pm j,\pm k$. The hard part is always one of the six products $ij,jk,ki,ji,kj,ik$; everything else is sign bookkeeping. Remember $Q_8$ is non-abelian, so \emph{order matters}: never assume $ab=ba$.
\end{method}

\begin{pitfall}
Do not import the rule $ab=ba$ from $\mathbb{Z}$ or from cyclic groups. In $Q_8$, $ij=k$ but $ji=-k\neq k$. Writing $ij=ji$ corrupts every later computation.
\end{pitfall}

\begin{wex}{The six core products}
Compute $ij$, $ji$, $jk$, $ki$, and $k^2$.
\wrec Each is a product of two of $i,j,k$, so step~4 (or step~3 for $k^2$) of the method applies. I just need to decide forward vs.\ backward in the cycle $i\to j\to k\to i$.
\wsol
\begin{itemize}
\item $ij$: step $i\to j$ is \emph{forward} (it is the listed relation $ij=k$). Third letter is $k$, sign $+$. So $ij=k$.
\item $ji$: step $j\to i$ is \emph{backward} (reverse of $ij$). Third letter $k$, sign $-$. So $ji=-k$.
\item $jk$: step $j\to k$ is \emph{forward} ($jk=i$). So $jk=i$.
\item $ki$: step $k\to i$ is \emph{forward} ($ki=j$). So $ki=j$.
\item $k^2$: same letter twice, step~3 gives $k^2=-1$.
\end{itemize}
\textit{Check.} $ij=k$ and $ji=-k$ are negatives of each other, confirming non-commutativity. Also $ij\cdot ji=k\cdot(-k)=-k^2=-(-1)=1$, consistent with $(ij)(ji)=i(j j)i=i(-1)i=-i^2=-(-1)=1$. Both routes give $1$. \checkmark
\end{wex}

\begin{proposition}[Element orders in $Q_8$]\label{p:q8orders@c1}
In $Q_8$: $\ord{1}=1$, $\ord{-1}=2$, and $\ord{i}=\ord{-i}=\ord{j}=\ord{-j}=\ord{k}=\ord{-k}=4$.
\end{proposition}

\begin{proof}
$1$ is the identity, so $\ord{1}=1$. For $-1$: $(-1)^1=-1\neq 1$ and $(-1)^2=1$, so $\ord{-1}=2$. For $i$: $i^1=i$, $i^2=-1$, $i^3=i^2 i=-i$, $i^4=(i^2)^2=(-1)^2=1$, and none of $i,i^2,i^3$ is $1$; hence $\ord{i}=4$. The same computation, replacing $i$ by any of $\pm i,\pm j,\pm k$, gives square $=-1$, fourth power $=1$: e.g.\ $(-i)^2=i^2=-1$, $(-i)^4=1$. So each of the six has order $4$.
\end{proof}

