\begin{wex}{Order of $-1$ vs.\ order of $i$}
Determine $\ord{-1}$ and $\ord{i}$ and explain why they differ even though both are ``minus-ish'' looking.
\wrec Apply the squaring method. The key difference: $(-1)^2=1$ but $i^2=-1\neq1$.
\wsol $(-1)^2=1$, and $-1\neq 1$, so $\ord{-1}=2$. For $i$: $i^2=-1\neq1$, so by step~3, $\ord{i}=4$.
\textit{Check.} $i^2=-1$ means $i$ is a square root of $-1$, so $i$ cannot have order $2$ (an order-$2$ element squares to $1$). Consistent. \checkmark
\end{wex}

\begin{wex}{Order of $-k$}
Compute $\ord{-k}$.
\wrec Single squaring. Watch the sign: $(-k)^2=(-1)^2k^2$.
\wsol $(-k)^2=(-1)^2 k^2=(+1)(-1)=-1\neq1$. By step~3, $(-k)^4=1$ and order is $4$. So $\ord{-k}=4$.
\textit{Check.} List the powers: $(-k)^1=-k$, $(-k)^2=-1$, $(-k)^3=(-k)^2(-k)=(-1)(-k)=k$, $(-k)^4=k(-k)=-k^2=1$. First return to $1$ at exponent $4$. \checkmark
\end{wex}

\begin{wex}{How many elements of each order?}
Count the elements of $Q_8$ of order $1$, $2$, and $4$.
\wrec Use Proposition~\ref{p:q8orders@c1}: tabulate.
\wsol Order $1$: only $\{1\}$ --- that is $1$ element. Order $2$: only $\{-1\}$ --- that is $1$ element. Order $4$: the remaining $\{\pm i,\pm j,\pm k\}$ --- that is $6$ elements.
\textit{Check.} $1+1+6=8=\ord{Q_8}$ counts every element exactly once. \checkmark This single-element-of-order-$2$ fact is the fingerprint we use later to distinguish $Q_8$ from $D_8$.
\end{wex}

\begin{wex}{Is there an element of order $8$?}
Decide whether $Q_8$ is cyclic.
\wrec A group of order $8$ is cyclic iff it has an element of order $8$. Check the maximal element order.
\wsol By Proposition~\ref{p:q8orders@c1} the largest order occurring is $4<8$. So no element generates $Q_8$; $Q_8$ is \emph{not} cyclic.
\textit{Check.} Also $Q_8$ is non-abelian ($ij\neq ji$), and every cyclic group is abelian, so it cannot be cyclic. Two independent reasons agree. \checkmark
\end{wex}

\begin{wex}{Square roots of $-1$}
Find every $x\in Q_8$ with $x^2=-1$.
\wrec ``$x^2=-1$'' is exactly the step-3 condition, which characterizes the order-$4$ elements.
\wsol An element satisfies $x^2=-1$ iff $\ord{x}=4$ (since $\ord{x}=1$ gives $x^2=1$ and $\ord{x}=2$ gives $x^2=1$). The order-$4$ elements are $\pm i,\pm j,\pm k$. So there are \emph{six} square roots of $-1$.
\textit{Check.} Verify two of them: $(-j)^2=j^2=-1$ and $i^2=-1$. \checkmark Contrast with $\mathbb{C}$, where $-1$ has only two square roots; the non-commutativity of $Q_8$ allows six.
\end{wex}

\begin{definition}[Center]\label{d:center@c1}
The \emph{center} of a group $G$ is $Z(G)=\{z\in G\st zx=xz\text{ for all }x\in G\}$.
\end{definition}

\begin{proposition}[Center of $Q_8$]\label{p:q8center@c1}
$Z(Q_8)=\{1,-1\}$.
\end{proposition}

\begin{method}{How to find the center of a small group}
\begin{enumerate}
\item The identity is always central; in $Q_8$ test the candidate $-1$ too (it is a scalar, hence central).
\item For each remaining $x$, exhibit ONE witness $y$ with $xy\neq yx$ to eliminate $x$.
\item For $Q_8$, the witnesses come free from the cycle: $i$ fails against $j$ ($ij=k\neq -k=ji$); $j$ fails against $k$; $k$ fails against $i$.
\item Collect the survivors. The center is always a subgroup, so its size must divide $\ord{Q_8}$ --- a useful sanity check.
\end{enumerate}
\textit{Recognition trigger.} Use this whenever asked for $Z(G)$, the set of elements commuting with $h$, or whether $G/Z(G)$ has a given order. In $Q_8$ the answer is always $\{1,-1\}$, so $|Q_8/Z(Q_8)|=4$.
\end{method}

\begin{pitfall}
A single product $xy=yx$ does NOT put $x$ in the center; $x$ must commute with \emph{every} element. For instance $i$ commutes with $-i$ and with $\pm1$, yet $i\notin Z(Q_8)$ because $i$ fails to commute with $j$.
\end{pitfall}

\begin{wex}{Verify $-1\in Z(Q_8)$ directly}
Show $-1$ commutes with $j$.
\wrec Apply the scalar rule: $-1$ behaves as a sign in front of any element.
\wsol $(-1)j=-j$ and $j(-1)=-j$. Equal, so $-1$ and $j$ commute.
\textit{Check.} The same scalar argument works against $i,k,\pm1$, so $-1$ commutes with all eight elements: $-1\in Z(Q_8)$. \checkmark
\end{wex}

\begin{wex}{Size of a conjugacy class}
The conjugacy class of $i$ has size $[Q_8:C_{Q_8}(i)]$. Compute it and list the class.
\wrec Orbit--stabilizer: the class size equals the index of the centralizer found above.
\wsol $[Q_8:C_{Q_8}(i)]=8/4=2$. So the class of $i$ has $2$ elements. Computing conjugates: $jij^{-1}=-i$ (done earlier), and $1\cdot i\cdot1=i$. So the class is $\{i,-i\}$.
\textit{Check.} Class sizes must sum to $8$. The classes are $\{1\}$, $\{-1\}$ (both central, size $1$), and $\{i,-i\},\{j,-j\},\{k,-k\}$ (size $2$ each): $1+1+2+2+2=8$. \checkmark
\end{wex}

\begin{wex}{Order of the quotient $Q_8/Z(Q_8)$}
Compute $|Q_8/Z(Q_8)|$ and decide whether it is cyclic.
\wrec Use Lagrange: $|G/N|=|G|/|N|$. Then check whether the quotient could be cyclic.
\wsol $|Q_8/Z(Q_8)|=8/2=4$. If it were cyclic of order $4$, then $Q_8/Z(Q_8)$ cyclic would force $Q_8$ abelian (a standard fact: $G/Z(G)$ cyclic $\Longrightarrow G$ abelian). But $Q_8$ is non-abelian, contradiction. So $Q_8/Z(Q_8)\cong V_4$ (the only non-cyclic group of order $4$).
\textit{Check.} In the quotient, $\bar i^2=\overline{i^2}=\overline{-1}=\bar 1$, and likewise $\bar j^2=\bar k^2=\bar1$; every nonidentity element has order $2$, the signature of $V_4$. \checkmark
\end{wex}

\begin{proof}
\emph{Order $1$ and $8$:} $\{1\}$ and $Q_8$ always occur.
\emph{Order $2$:} a subgroup of order $2$ is $\{1,x\}$ with $\ord{x}=2$; the only order-$2$ element is $-1$, giving $\{1,-1\}$ as the unique order-$2$ subgroup.
\emph{Order $4$:} by Lagrange the index is $2$. Any order-$4$ subgroup must contain an element of order $4$ (a group of order $4$ with no order-$4$ element is $V_4$, but $V_4$ would need three elements of order $2$, and $Q_8$ has only one). Such a subgroup is then cyclic, $\langle x\rangle$ with $\ord{x}=4$. Now $\langle i\rangle=\langle -i\rangle=\{1,i,-1,-i\}$, $\langle j\rangle=\langle -j\rangle$, $\langle k\rangle=\langle -k\rangle$ --- three distinct cyclic subgroups, and these exhaust the order-$4$ subgroups since the six order-$4$ elements pair off into these three.
\emph{Normality:} subgroups of index $2$ are automatically normal, so $\langle i\rangle,\langle j\rangle,\langle k\rangle$ are normal; $\{1\}$ and $Q_8$ are trivially normal. For $\{1,-1\}=Z(Q_8)$, the center is always normal (indeed $g(-1)g^{-1}=-1$ for all $g$). Hence all six are normal.
\end{proof}

\begin{method}{How to check a subgroup $H\nor G$ in $Q_8$}
\begin{enumerate}
\item \textbf{Index $2$ shortcut:} if $[G:H]=2$, then $H\nor G$ automatically (left cosets $=$ right cosets). In $Q_8$ this instantly handles $\langle i\rangle,\langle j\rangle,\langle k\rangle$.
\item \textbf{Center shortcut:} $Z(G)\nor G$ always; this handles $\{1,-1\}$.
\item \textbf{Trivial cases:} $\{1\}\nor G$ and $G\nor G$.
\item \textbf{General test} (if needed): verify $gHg^{-1}\subseteq H$ for $g$ ranging over a generating set of $G$.
\end{enumerate}
\textit{Recognition trigger.} Use the index-$2$ shortcut whenever $|H|=\tfrac12|G|$ --- it is the fastest normality proof in $Q_8$. Because $Q_8$ has only the six subgroups above, and each is caught by step~1, 2, or 3, EVERY subgroup of $Q_8$ is normal.
\end{method}

\begin{pitfall}
``All subgroups normal'' does NOT mean ``abelian.'' $Q_8$ is non-abelian yet every subgroup is normal. The implication only runs one way: abelian $\Longrightarrow$ all subgroups normal, not conversely.
\end{pitfall}

\begin{wex}{The order-$2$ subgroup is unique and normal}
Show $\{1,-1\}$ is the only subgroup of order $2$ and that it is normal.
\wrec A subgroup of order $2$ is determined by its unique order-$2$ element; $Q_8$ has exactly one such element. Normality follows from it being the center.
\wsol The only element of order $2$ is $-1$ (Worked Example counting orders). So $\{1,-1\}$ is the unique order-$2$ subgroup. It equals $Z(Q_8)$, and the center is normal: for any $g$, $g(-1)g^{-1}=(-1)gg^{-1}=-1\in\{1,-1\}$.
\textit{Check.} $g(-1)g^{-1}=-1$ uses that $-1$ is central (scalar). \checkmark
\end{wex}

\begin{wex}{Intersection of two order-$4$ subgroups}
Compute $\langle i\rangle\cap\langle j\rangle$.
\wrec An intersection of subgroups is a subgroup; list elements and keep the common ones.
\wsol $\langle i\rangle=\{1,i,-1,-i\}$ and $\langle j\rangle=\{1,j,-1,-j\}$. The common elements are $1$ and $-1$. So $\langle i\rangle\cap\langle j\rangle=\{1,-1\}=Z(Q_8)$.
\textit{Check.} $|\langle i\rangle\cap\langle j\rangle|=2$ divides both $|\langle i\rangle|=4$ and $|\langle j\rangle|=4$ \checkmark. Geometrically, every pair of distinct order-$4$ subgroups meets exactly in the center --- that is why $\{1,-1\}$ sits at the unique node below all three in the lattice. \checkmark
\end{wex}

\begin{wex}{Counting subgroups confirms the lattice}
Verify the total number of subgroups is $6$ by tallying by order.
\wrec Use Proposition~\ref{p:q8subs@c1} and Lagrange: possible orders divide $8$, i.e.\ $1,2,4,8$.
\wsol Order $1$: $\{1\}$ --- $1$ subgroup. Order $8$: $Q_8$ --- $1$. Order $2$: only $\{1,-1\}$ --- $1$. Order $4$: $\langle i\rangle,\langle j\rangle,\langle k\rangle$ --- $3$. Total $1+1+1+3=6$.
\textit{Check.} No order can be skipped that Lagrange forbids; $1,2,4,8$ are exactly the divisors of $8$, and we found at least one subgroup of each. \checkmark
\end{wex}

\begin{wex}{Every subgroup normal, fast}
Without case-checking each conjugate, argue that all six subgroups of $Q_8$ are normal.
\wrec Match each subgroup to a shortcut from the method box.
\wsol $\{1\}$ and $Q_8$: trivially normal. $\{1,-1\}=Z(Q_8)$: center, normal. $\langle i\rangle,\langle j\rangle,\langle k\rangle$: each has index $2$, hence normal. That covers all six.
\textit{Check.} The shortcuts are independent of any specific conjugation computation, yet they agree with the brute-force verification that $gHg^{-1}=H$ for every $g$ and every $H$. \checkmark
\end{wex}

\begin{proposition}[$Q_8\not\cong D_8$]\label{p:q8notd8@c1}
$Q_8$ and $D_8$ are non-isomorphic groups of order $8$.
\end{proposition}

\begin{proof}
The number of elements of order $2$ is an isomorphism invariant (an isomorphism $\varphi$ satisfies $\ord{\varphi(x)}=\ord{x}$, so it bijects order-$2$ elements to order-$2$ elements). In $Q_8$ there is exactly \emph{one} element of order $2$, namely $-1$ (Worked Example on counting orders). In $D_8$ the elements of order $2$ are $r^2$ and the four reflections $s,rs,r^2s,r^3s$ --- that is \emph{five} elements of order $2$ (each reflection squares to $1$, and $r^2$ is the half-turn). Since $1\neq 5$, no isomorphism $Q_8\to D_8$ can exist.
\end{proof}

