\begin{proposition}[Basic identities]\label{p:basic@c1}
Let $\varphi:G\to H$ be a homomorphism. Then
\begin{enumerate}
\item[(1)] $\varphi(1_G)=1_H$;
\item[(2)] $\varphi(x^{-1})=\varphi(x)^{-1}$ for all $x\in G$;
\item[(3)] $\varphi(x^n)=\varphi(x)^n$ for all $x\in G$ and all $n\in\mathbb{Z}$.
\end{enumerate}
\end{proposition}

\begin{proposition}[Inverse of an isomorphism is a homomorphism]\label{p:invhom@c1}
If $\varphi:G\to H$ is an isomorphism, then $\varphi^{-1}:H\to G$ is a homomorphism.
\end{proposition}

\begin{proof}
Let $a,b\in H$ and set $x=\varphi^{-1}(a)$, $y=\varphi^{-1}(b)$, so $\varphi(x)=a$,
$\varphi(y)=b$. Then $\varphi(xy)=\varphi(x)\varphi(y)=ab$, hence applying the bijection
$\varphi^{-1}$ gives $\varphi^{-1}(ab)=xy=\varphi^{-1}(a)\varphi^{-1}(b)$.
\end{proof}

\begin{proposition}[Kernel and image are subgroups]\label{p:subgroups@c1}
Let $\varphi:G\to H$ be a homomorphism. Then $\ker\varphi\sgr G$ and $\varphi(G)\sgr H$.
\end{proposition}

\begin{proposition}[Order divisibility]\label{p:orddiv@c1}
Let $\varphi:G\to H$ be a homomorphism and $x\in G$.
\begin{enumerate}
\item[(1)] If $\ord{x}=n<\infty$, then $\ord{\varphi(x)}$ divides $n$. In particular
$\ord{\varphi(x)}$ is finite.
\item[(2)] If $\varphi$ is injective, then $\ord{\varphi(x)}=\ord{x}$ (equality, allowing
$\infty=\infty$).
\end{enumerate}
\end{proposition}

\begin{method}{Compute the kernel and the image}
Trigger: a homomorphism is given and you want $\ker\varphi$ (the ``collapse'') or
$\varphi(G)$ (the ``reach''), e.g.\ to test injectivity/surjectivity.
\begin{enumerate}
\item \textbf{Kernel.} Solve the equation $\varphi(g)=1_H$ for $g$. The solution set
  \emph{is} $\ker\varphi$. Then $\varphi$ is injective $\Longleftrightarrow\ker\varphi=\{1_G\}$.
\item \textbf{Image.} Determine which $h\in H$ are hit: for each candidate $h$, decide
  whether $\varphi(g)=h$ has a solution $g\in G$. The set of solvable $h$ is $\varphi(G)$.
  Then $\varphi$ is surjective $\Longleftrightarrow\varphi(G)=H$.
\item Both are subgroups (Proposition~\ref{p:subgroups@c1}); use that as a check -- e.g.\ your
  kernel must contain $1_G$ and be closed under inverses.
\end{enumerate}
\end{method}

\begin{method}{Use order divisibility to rule maps out}
Trigger: you must decide whether \emph{any} homomorphism $\varphi:G\to H$ can send a given
element $x$ to a given target $y$, or whether a nontrivial hom can exist at all.
\begin{enumerate}
\item Compute $\ord{x}$ in $G$.
\item For a proposed value $\varphi(x)=y$, compute $\ord{y}$ in $H$.
\item If $\ord{y}\nmid\ord{x}$, then $\varphi(x)=y$ is \emph{impossible} for a homomorphism,
  by Proposition~\ref{p:orddiv@c1}(1).
\item To kill all nontrivial homs from a cyclic $G=\langle x\rangle$: a hom is determined by
  $\varphi(x)$, and $\ord{\varphi(x)}\mid\ord{x}$. If the only element of $H$ whose order
  divides $\ord{x}$ is $1_H$, then $\varphi(x)=1_H$, forcing $\varphi\equiv 1_H$ (trivial).
\end{enumerate}
\end{method}

\begin{pitfall}
$\ker\varphi$ lives in $G$ and always contains $1_G$; never write ``$\ker\varphi=\varnothing$.'' A
trivial kernel is $\ker\varphi=\{1_G\}$, not the empty set. The empty set is not a subgroup.
\end{pitfall}

\begin{pitfall}
The direction of divisibility is fixed: $\ord{\varphi(x)}\mid\ord{x}$, never the reverse. A
homomorphism can shrink an order ($\ord{x}=6\to\ord{\varphi(x)}=2$) but can never grow it.
\end{pitfall}

\begin{pitfall}
``$\varphi$ determined by $\varphi(\bar1)$'' only works because the source is \emph{cyclic}.
For a non-cyclic source you must specify (compatible) images of a generating set and check the
defining relations; you cannot pick generator images freely.
\end{pitfall}

