\begin{proposition}[What an isomorphism preserves]\label{p:preserved-mrg@c1}
Let $\varphi:G\to H$ be an isomorphism. Then:
\begin{enumerate}
\item[(1)] $|G|=|H|$ (as cardinalities; $\varphi$ is a bijection);
\item[(2)] $G$ is abelian if and only if $H$ is abelian;
\item[(3)] for every $x\in G$, $\ord{\varphi(x)}=\ord{x}$; hence for each $n$, $G$ and $H$ have
the \emph{same number} of elements of order $n$;
\item[(4)] $G$ is cyclic if and only if $H$ is cyclic.
\end{enumerate}
\end{proposition}

\begin{remark}\label{r:invariants@c1}
Isomorphism is an equivalence relation ($\id_G$ is an isomorphism; $\varphi^{-1}$ of an isomorphism is an isomorphism; a composite of isomorphisms is one). Two isomorphic groups are ``the same'' for every property defined purely from the multiplication. The properties below are \emph{isomorphism invariants}: if $G\cong H$ they must agree.
\begin{enumerate}
\item \textbf{Order:} $|G|=|H|$ (a bijection preserves cardinality).
\item \textbf{Abelian-ness:} $G$ abelian $\Longleftrightarrow$ $H$ abelian.
\item \textbf{Multiset of element orders:} for every $n$, the number of $x\in G$ with $\ord{x}=n$ equals the number of $y\in H$ with $\ord{y}=n$.
\item \textbf{Number of subgroups} (and of subgroups of each order), and the whole subgroup lattice up to relabeling.
\item \textbf{Being cyclic.}
\end{enumerate}
\end{remark}

\begin{proof}
From $\varphi(1_G)=\varphi(1_G\cdot 1_G)=\varphi(1_G)\varphi(1_G)$, cancel $\varphi(1_G)$ in $H$ to get $\varphi(1_G)=1_H$. Then $1_H=\varphi(1_G)=\varphi(x x^{-1})=\varphi(x)\varphi(x^{-1})$, so $\varphi(x^{-1})=\varphi(x)^{-1}$.

For orders, $\varphi(x^n)=\varphi(x)^n$ by induction. Hence $x^n=1_G\Longrightarrow \varphi(x)^n=1_H$. Conversely, since $\varphi$ is injective with $\varphi(1_G)=1_H$, $\varphi(x)^n=1_H=\varphi(1_G)$ forces $x^n=1_G$. Thus $\{n:x^n=1\}=\{n:\varphi(x)^n=1\}$, so the least positive such $n$ agrees: $\ord{\varphi(x)}=\ord{x}$ (and both are infinite together).

If $G$ is abelian and $a,b\in H$, write $a=\varphi(x),b=\varphi(y)$ (surjectivity); then $ab=\varphi(x)\varphi(y)=\varphi(xy)=\varphi(yx)=\varphi(y)\varphi(x)=ba$. By symmetry ($\varphi^{-1}$ is an isomorphism) the converse holds. If $G=\langle g\rangle$ then $H=\varphi(G)=\langle \varphi(g)\rangle$ is cyclic; symmetrically for the converse.
\end{proof}

