\begin{method}{To PROVE $G\cong H$: build an explicit bijective homomorphism}
\textit{Trigger.} You suspect two concretely given groups are the same, or the problem says ``show $G\cong H$.''
\begin{enumerate}
\item \textbf{Guess the map.} Match generators of $G$ to elements of $H$ that satisfy the same relations; or use a known structural formula ($\exp$, $\log$, $g^k\mapsto k$, a permutation action).
\item \textbf{Check well-defined + homomorphism:} verify $\varphi(xy)=\varphi(x)\varphi(y)$ for all $x,y\in G$, i.e.\ that the multiplication square commutes. If $\varphi$ is defined by images of generators, it suffices (and is necessary) to check that these images satisfy the defining relations of $G$; checking the product rule only on pairs of generators is not enough.
\item \textbf{Check bijective.} Easiest route: show $\varphi$ is injective ($\ker\varphi=\{1\}$, i.e.\ $\varphi(x)=1\Longrightarrow x=1$) AND $|G|=|H|$ finite; or exhibit an explicit two-sided inverse map.
\end{enumerate}
\end{method}

\begin{method}{To DISPROVE $G\cong H$: exhibit a differing invariant}
\textit{Trigger.} Two groups of the \emph{same order} that you suspect are different (different orders are settled by $|G|\ne|H|$ immediately).
\begin{enumerate}
\item Compare $|G|$ vs $|H|$. If unequal, done.
\item Is exactly one abelian? If so, done.
\item Compare the \emph{multiset of element orders}: tabulate ``how many elements of order $1,2,3,4,\dots$'' in each. One mismatch kills the isomorphism. (This is the workhorse.)
\item Compare the number of subgroups of a fixed order, or whether one is cyclic and the other is not.
\end{enumerate}
\textbf{Why it works:} by Proposition~\ref{p:preserve@c1} an isomorphism would carry each invariant across unchanged, so a single disagreement is a contradiction.
\end{method}

\begin{pitfall}
A map that happens to be a bijection of \emph{sets} is not enough unless it also respects multiplication; conversely a bijective \emph{set} map respecting multiplication is automatically an isomorphism --- but check both halves. Equal order alone does not prove $G\cong H$ in general (e.g.\ $\mathbb{Z}/(4)\mathbb{Z}\not\cong V_4$).
\end{pitfall}

\begin{wex}{$\GL_1(\mathbb{R})\cong(\mathbb{R}^\times,\cdot)$ --- a quick structural identification}
Show the group of invertible $1\times1$ real matrices is isomorphic to $(\mathbb{R}^\times,\cdot)$, the nonzero reals under multiplication.
\wrec A $1\times1$ matrix is just a scalar, and matrix multiplication is scalar multiplication; invertibility means nonzero. The ``forget the brackets'' identification is the trigger --- a tautological isomorphism.
\wsol Define $\varphi\colon\GL_1(\mathbb{R})\to\mathbb{R}^\times$ by $\varphi\big([a]\big)=a$ (necessarily $a\ne0$). \emph{Homomorphism:} $\varphi([a][b])=\varphi([ab])=ab=\varphi([a])\varphi([b])$. \emph{Bijective:} $a\mapsto[a]$ is an explicit two-sided inverse $\mathbb{R}^\times\to\GL_1(\mathbb{R})$. \textit{Check.} $\varphi$ sends the identity matrix $[1]$ to $1$, and $\varphi([a]^{-1})=\varphi([a^{-1}])=a^{-1}$. Both abelian. Consistent.
\end{wex}

 egin{wex}{$\mathbb{Z}
ot\cong\mathbb{Q}$ (cyclic / not cyclic)}
Both are infinite abelian groups under addition. Show $(\mathbb{Z},+)
ot\cong(\mathbb{Q},+)$.
\wrec Same cardinality (both countable), same abelian-ness --- those do not decide it. Use ``cyclic vs.\ not cyclic,'' which is an isomorphism invariant even for infinite groups.
\wsol $\mathbb{Z}=\langle 1angle$ is cyclic. Suppose $\mathbb{Q}=\langle p/qangle$ were cyclic, generated by $p/q$ (in lowest terms, $q>0$). Every element would be $n\cdot(p/q)=np/q$ for $n\in\mathbb{Z}$. But $\dfrac{p}{2q}\in\mathbb{Q}$ is not of this form: $np/q=p/(2q)$ would need $2np=p$, i.e.\ $2n=1$ (note $p
eq0$, since $\langle 0angle=\{0\}
eq\mathbb{Q}$), impossible for integer $n$. So $\mathbb{Q}$ is not cyclic. Since ``cyclic'' transfers across isomorphisms (Proposition~ef{p:preserve@c1}) and $\mathbb{Z}$ is cyclic while $\mathbb{Q}$ is not, $\mathbb{Z}
ot\cong\mathbb{Q}$. 	extit{Check.} Consistently, in $\mathbb{Z}$ every nonzero element generates a finite-index subgroup, whereas $\mathbb{Q}$ is divisible (every element is $2\cdot$ something) --- another invariant separating them.
\end{wex}

\begin{wex}{$\mathbb{Z}/(6)\mathbb{Z}\not\cong S_3$ (abelian vs.\ non-abelian)}
Both have order $6$. Show they are not isomorphic.
\wrec When the order ties, check abelian-ness first --- it is the cheapest invariant. One of these is abelian and the other is not.
\wsol $\mathbb{Z}/(6)\mathbb{Z}$ is abelian (addition mod $6$ commutes). $S_3$ is not: multiplying right-to-left, $(1\,2)(1\,3)=(1\,3\,2)$ while $(1\,3)(1\,2)=(1\,2\,3)$, and $(1\,3\,2)\ne(1\,2\,3)$. ``Abelian'' is an isomorphism invariant (Proposition~\ref{p:preserve@c1}); an abelian group cannot be isomorphic to a non-abelian one. Hence $\mathbb{Z}/(6)\mathbb{Z}\not\cong S_3$. \textit{Check (second invariant).} $\mathbb{Z}/(6)\mathbb{Z}$ is cyclic with an element of order $6$ ($\bar1$); $S_3$ has element orders only in $\{1,2,3\}$ (no order-$6$ element), so the order multisets differ too: $\{1,2,3,3,6,6\}$ vs.\ $\{1,2,2,2,3,3\}$.
\end{wex}

\begin{wex}{$\mathbb{Z}/(8)\mathbb{Z}\not\cong\mathbb{Z}/(4)\mathbb{Z}\times\mathbb{Z}/(2)\mathbb{Z}$ (largest element order)}
Both abelian of order $8$. Show they are not isomorphic.
\wrec Same order, both abelian. Compare the maximum element order (a clean special case of the order-multiset invariant): a cyclic group of order $8$ must contain an element of order $8$.
\wsol $\mathbb{Z}/(8)\mathbb{Z}$ is cyclic: $\ord{\bar1}=8$. In $\mathbb{Z}/(4)\mathbb{Z}\times\mathbb{Z}/(2)\mathbb{Z}$, the order of $(a,b)$ is $\lcm(\ord a,\ord b)$, where $\ord a\mid4$ and $\ord b\mid2$, so $\ord{(a,b)}=\lcm(\ord a,\ord b)\mid\lcm(4,2)=4$. Thus \emph{no} element of $\mathbb{Z}/(4)\mathbb{Z}\times\mathbb{Z}/(2)\mathbb{Z}$ has order $8$, while $\mathbb{Z}/(8)\mathbb{Z}$ has $\varphi(8)=4$ of them ($\bar1,\bar3,\bar5,\bar7$). The order-$8$ count differs ($4$ vs $0$), so by Proposition~\ref{p:preserve@c1} no isomorphism exists: $\mathbb{Z}/(8)\mathbb{Z}\not\cong\mathbb{Z}/(4)\mathbb{Z}\times\mathbb{Z}/(2)\mathbb{Z}$. \textit{Check.} Equivalently $\mathbb{Z}/(8)\mathbb{Z}$ is cyclic and $\mathbb{Z}/(4)\mathbb{Z}\times\mathbb{Z}/(2)\mathbb{Z}$ is not, since a finite abelian group is cyclic iff it has an element of order equal to the group order.
\end{wex}

\begin{pitfall}
Matching ``one element of order $2$ here with one element of order $2$ there'' is necessary but a full isomorphism must match \emph{all} counts simultaneously and respect multiplication. Conversely, to \emph{disprove} you need only \emph{one} invariant to differ --- never try to check ``all $|G|!$ bijections.''
\end{pitfall}

\begin{remark}\label{r:dnf-samegroup-mrg@c1}
The informal reading of $G\cong H$ is that $G$ and $H$ are ``the same group except for the names of the elements.'' Relabel each $x\in G$ as $\varphi(x)$ and the multiplication table of $G$ becomes the multiplication table of $H$: the entry in row $x$, column $y$ of $G$'s table is $xy$, and $\varphi$ sends it to $\varphi(xy)=\varphi(x)\varphi(y)$, which sits in row $\varphi(x)$, column $\varphi(y)$ of $H$'s table. So the homomorphism condition is precisely ``$\varphi$ carries one Cayley table onto the other.'' This is the picture behind every isomorphism proof below; for a fully worked instance see the $\mathbb{Z}/(2)\mathbb{Z}\times\mathbb{Z}/(2)\mathbb{Z}\cong V_4$ example.
\end{remark}

\begin{wex}{$\mathbb{Z}\cong 2\mathbb{Z}$ (the even integers)}
Show that the additive group $(\mathbb{Z},+)$ is isomorphic to its subgroup $2\mathbb{Z}=\{\dots,-4,-2,0,2,4,\dots\}$ of even integers, even though $2\mathbb{Z}\psgr\mathbb{Z}$ is a proper subgroup.
\wrec The point is that an infinite group can be isomorphic to a proper subgroup of itself --- impossible in the finite case, where $|G|=|H|$ forbids $H\psgr G$. The trigger is ``doubling'' as a structure-preserving relabeling: every even integer is uniquely $2n$.
\wsol Define $\varphi\colon\mathbb{Z}\to2\mathbb{Z}$ by $\varphi(n)=2n$. \emph{Homomorphism:} $\varphi(m+n)=2(m+n)=2m+2n=\varphi(m)+\varphi(n)$. \emph{Bijective:} $\varphi$ is injective ($2m=2n\Longrightarrow m=n$) and surjective (every even integer is $2n$ for some $n\in\mathbb{Z}$); the explicit inverse is $k\mapsto k/2$, defined on $2\mathbb{Z}$ and integer-valued there.

\textit{Check.} $\varphi(0)=0$, the identity of $2\mathbb{Z}$; $\varphi(-n)=-2n=-\varphi(n)$. Both groups are infinite cyclic, $\mathbb{Z}=\langle 1\rangle$ and $2\mathbb{Z}=\langle 2\rangle$, and $\varphi$ sends the generator $1$ to the generator $2$, as an isomorphism of cyclic groups must. The order of $G$ being infinite is exactly what permits $G\cong H$ with $H\psgr G$.
\end{wex}

\begin{wex}{$\mathbb{Z}/(n)\mathbb{Z}\cong\mu_n$, the $n$th roots of unity}
Let $\mu_n=\{\,z\in\mathbb{C} : z^n=1\,\}$ be the group of complex $n$th roots of unity under multiplication. Show $\mathbb{Z}/(n)\mathbb{Z}\cong\mu_n$.
\wrec This realizes the abstract cyclic group $\mathbb{Z}/(n)\mathbb{Z}$ concretely inside $\mathbb{C}^\times$. The trigger is De Moivre: $\zeta=e^{2\pi i/n}$ satisfies $\zeta^n=1$ and has order exactly $n$, so $\mu_n=\langle \zeta\rangle$ is cyclic of order $n$. ``Addition of exponents mod $n$ becomes multiplication of powers of $\zeta$'' is the matching.
\wsol Put $\zeta=e^{2\pi i/n}$, so $\mu_n=\{1,\zeta,\zeta^2,\dots,\zeta^{n-1}\}$ ($n$ distinct points). Define $\varphi\colon\mathbb{Z}/(n)\mathbb{Z}\to\mu_n$ by $\varphi(\bar k)=\zeta^k$. \emph{Well-defined:} if $\bar k=\bar\ell$ then $n\mid k-\ell$, and $\zeta^n=1\Longrightarrow\zeta^{k-\ell}=1\Longrightarrow\zeta^k=\zeta^\ell$. \emph{Homomorphism:} $\varphi(\bar k+\bar\ell)=\zeta^{k+\ell}=\zeta^k\zeta^\ell=\varphi(\bar k)\varphi(\bar\ell)$, so addition mod $n$ is sent to multiplication in $\mathbb{C}^\times$. \emph{Bijective:} the $n$ values $\zeta^0,\dots,\zeta^{n-1}$ are distinct and exhaust $\mu_n$, and $|\mathbb{Z}/(n)\mathbb{Z}|=n=|\mu_n|$.

\textit{Check.} $\varphi(\bar1)=\zeta$ has order $n$ in $\mu_n$ (its powers $1,\zeta,\dots,\zeta^{n-1}$ are distinct, $\zeta^n=1$), matching $\ord{\bar1}=n$; orders of generators agree as Proposition~\ref{p:preserve@c1} requires.
\end{wex}

\begin{remark}\label{r:dnf-hom-not-iso-mrg@c1}
Two reminders that a homomorphism need not be an isomorphism. The reduction map $\pi\colon\mathbb{Z}\to\mathbb{Z}/(n)\mathbb{Z}$, $\pi(a)=\bar a$, is a homomorphism but not injective for $n\ge1$ ($\pi(n)=\bar0=\pi(0)$); here $|\mathbb{Z}|\ne|\mathbb{Z}/(n)\mathbb{Z}|$ blocks $\cong$ outright. The trivial map $\varphi\colon G\to H$, $\varphi(g)=1_H$ for all $g$, is always a homomorphism ($1_H=1_H\cdot1_H$) but is an isomorphism only when $|G|=|H|=1$. In the other direction, a bijection that is \emph{not} a homomorphism also fails: no set bijection $\mathbb{Z}/(4)\mathbb{Z}\to V_4$ can respect multiplication, since the two groups are not isomorphic at all.
\end{remark}

\begin{remark}\label{r:dnf-no-converse-mrg@c1}
The invariants of Remark~\ref{r:invariants@c1} run only one way: matching them does \emph{not} prove $G\cong H$. Same order is not enough ($\mathbb{Z}/(4)\mathbb{Z}$ and $V_4$ both have order $4$ but are not isomorphic), and same order together with both being abelian is still not enough (again $\mathbb{Z}/(4)\mathbb{Z}\not\cong V_4$). A single \emph{disagreement} of any invariant disproves isomorphism instantly (Proposition~\ref{p:preserve@c1}); full \emph{agreement} of a finite list of invariants is only evidence, and an actual isomorphism must still be exhibited.
\end{remark}

\begin{theorem}[Actions $\leftrightarrow$ homomorphisms to $\Sym(A)$]\label{t:equiv@c1}
Let $G$ be a group and $A$ a nonempty set.
\begin{enumerate}
\item[(a)] If $G\times A\to A$ is a left action, then each $\sigma_g\in\Sym(A)$ and the map
$\rho\colon G\to\Sym(A)$, $g\mapsto\sigma_g$, is a group homomorphism.
\item[(b)] Conversely, if $\rho\colon G\to\Sym(A)$ is any homomorphism, then
$g\cdot a:=\rho(g)(a)$ defines a left action whose representation is $\rho$.
\end{enumerate}
Thus left actions of $G$ on $A$ correspond bijectively to homomorphisms $G\to\Sym(A)$. Moreover
the action is faithful iff $\rho$ is injective, and in that case $G\cong\rho(G)\sgr\Sym(A)$.
\end{theorem}

\begin{pitfall}
Right-to-left composition matters: (A2) forces $\rho(gh)=\rho(g)\rho(h)$ \emph{in that order}. A
\emph{right} action $a\cdot(gh)=(a\cdot g)\cdot h$ instead gives an anti-homomorphism; to convert a
right action to a left one use $g\cdot a:=a\cdot g^{-1}$, not $a\cdot g$.
\end{pitfall}

\begin{theorem}[Cayley]\label{t:cayley@c1}
Every group $G$ acts on itself by left multiplication, $g\cdot x=gx$. This action is faithful,
so $\rho\colon G\hookrightarrow\Sym(G)$ embeds $G$ as a subgroup of $\Sym(G)$. If $|G|=n$ then
$G\cong$ a subgroup of $S_n$.
\end{theorem}

\begin{proof}
(A1): $1\cdot x=1x=x$. (A2): $(gh)\cdot x=(gh)x=g(hx)=g\cdot(h\cdot x)$ by associativity.
Kernel: $g\cdot x=x$ for all $x$ means $gx=x$ for all $x$; taking $x=1$ gives $g=1$, so
$\ker\rho=1$ and $\rho$ is injective. With $|G|=n$, choosing a labeling $G\leftrightarrow\{1,\dots,n\}$
gives $\Sym(G)\cong S_n$, so $G\cong\rho(G)\sgr S_n$.
\end{proof}

\begin{wex}{Why ``left mult'' is needed: $g\cdot x=xg$ is \emph{not} a left action}
Show that $g\cdot x:=xg$ on $G$ fails (A2) unless $G$ is abelian, and fix it.
\wrec Test (A2) literally; a swapped order is the classic trap that produces an anti-homomorphism.
\wsol $(gh)\cdot x=x(gh)=xgh$, but $g\cdot(h\cdot x)=g\cdot(xh)=(xh)g=xhg$. These agree for all
$x$ iff $gh=hg$ for all $g,h$, i.e.\ iff $G$ abelian. So for nonabelian $G$ it is not a left action.
\textbf{Fix:} $g\cdot x:=xg^{-1}$ \emph{is} a left action: $(gh)\cdot x=x(gh)^{-1}=xh^{-1} g^{-1}
=(xh^{-1})g^{-1}=g\cdot(h\cdot x)$, and $1\cdot x=x1^{-1}=x$.
\textit{Check.} Kernel of the fixed action: $xg^{-1}=x$ for all $x$ $\Rightarrow g^{-1}=1\Rightarrow
g=1$, so it is also faithful (this is the right regular action recast on the left).
\end{wex}

