\begin{proposition}[Subgroup Criterion, long form]\label{p:subgrp-long@c2}
Let $G$ be a group and $H\subseteq G$. Then $H\sgr G$ if and only if all three of the following hold:
\begin{enumerate}
\item[(0)] $H\neq\varnothing$ (equivalently $1\in H$);
\item[(1)] $H$ is closed under products: for all $a,b\in H$, $ab\in H$;
\item[(2)] $H$ is closed under inverses: for all $a\in H$, $a^{-1}\in H$.
\end{enumerate}
\end{proposition}

\begin{proof}
($\Longrightarrow$) If $H\sgr G$ then $H$ is a group, so it is nonempty, its operation lands inside $H$ (giving (1)), and each $a\in H$ has an inverse in $H$ (giving (2)).

($\Leftarrow$) Assume (0),(1),(2). By (1) the restricted operation is a genuine binary operation on $H$. Associativity holds in $H$ because it already holds for \emph{all} elements of $G$, in particular for elements of $H$. Since $H\neq\varnothing$, pick $a\in H$; by (2) $a^{-1}\in H$, and by (1) $aa^{-1}=1\in H$, so $H$ contains an identity. For each $a\in H$, (2) gives $a^{-1}\in H$, which is a two-sided inverse. Hence $H$ is a group, i.e. $H\sgr G$.
\end{proof}

\begin{proposition}[Identity and inverses agree]\label{p:agree@c2}
If $H\sgr G$ then the identity $1_H$ of $H$ equals the identity $1_G$ of $G$, and for $h\in H$ the inverse of $h$ computed in $H$ equals the inverse $h^{-1}$ computed in $G$.
\end{proposition}

\begin{proof}
In $H$ we have $1_H\,1_H=1_H$. Viewing this equation in $G$ and multiplying both sides on the right by $(1_H)^{-1}$ (the inverse in $G$, which exists since $1_H\in G$) gives $1_H=1_G$. For $h\in H$ let $h'$ be its inverse in $H$, so $hh'=1_H=1_G$. Multiplying on the left in $G$ by $h^{-1}$ gives $h'=h^{-1}$.
\end{proof}

\begin{remark}\label{r:two-step@c2}
Conditions (1) and (2) of Proposition~\ref{p:subgrp-long@c2} can be merged into one (the ``one-step'' test): a \emph{nonempty} $H\subseteq G$ is a subgroup iff $ab^{-1}\in H$ for all $a,b\in H$. Indeed, taking $a=b$ gives $1\in H$; taking $a=1$ gives $b^{-1}\in H$ for all $b\in H$; and then $a(b^{-1})^{-1}=ab\in H$ gives closure. For \emph{finite} $H$ one may even drop (2): a nonempty finite subset closed under products is a subgroup, because powers $a,a^2,a^3,\dots$ must repeat, forcing some $a^k=1$ and $a^{-1}=a^{k-1}\in H$.
\end{remark}

\begin{method}{The ``Is $H$ a subgroup?'' checklist}
\textit{Recognition trigger.} Use this whenever you are handed a subset $H$ of a known group $G$ and asked whether $H\sgr G$, or asked to \emph{prove} some described set is a subgroup. Do NOT re-verify associativity --- it is inherited from $G$ for free.
\begin{enumerate}
\item \textbf{Nonempty / identity.} Exhibit a concrete element of $H$; the cleanest is to show $1_G\in H$. If $1_G\notin H$, stop: $H$ is \emph{not} a subgroup.
\item \textbf{Closed under products.} Take arbitrary $a,b\in H$ (write out what membership means), form $ab$, and verify $ab$ satisfies the defining condition of $H$.
\item \textbf{Closed under inverses.} Take arbitrary $a\in H$, form $a^{-1}$, and verify $a^{-1}\in H$.
\end{enumerate}
\textit{Shortcuts.} If $H$ is \emph{finite} and nonempty, step (3) is automatic once step (2) holds (Remark~\ref{r:two-step@c2}). To disprove, it suffices to break \emph{one} clause with a single explicit counterexample.
\end{method}

\begin{pitfall}
``Nonempty'' is not optional. The empty set is closed under products and inverses vacuously, yet $\varnothing$ is not a group (no identity). Always actually produce an element --- showing $1_G\in H$ kills two birds, since it proves nonemptiness too.
\end{pitfall}

\begin{pitfall}
A subset can contain $1_G$ and still fail to be a subgroup. Containing the identity gives you step (1) only; you must still check closure under products \emph{and} inverses. See the non-example $\{1,s,sr\}\subseteq D_8$ below.
\end{pitfall}

\begin{wex}{$n\mathbb{Z}\sgr\mathbb{Z}$}
Fix $n\in\mathbb{Z}$ and let $n\mathbb{Z}=\{nk\st k\in\mathbb{Z}\}$. Show $n\mathbb{Z}\sgr(\mathbb{Z},+)$.
\wrec A described subset of a known group $(\mathbb{Z},+)$: run the three-clause checklist. The operation is written additively, so ``product $ab$'' means the sum $a+b$, ``identity $1$'' means $0$, and ``inverse $a^{-1}$'' means $-a$.
\wsol \emph{Nonempty/identity:} $0=n\cdot 0\in n\mathbb{Z}$, so $0\in n\mathbb{Z}$ and $n\mathbb{Z}\neq\varnothing$. \emph{Closed under $+$:} take $a,b\in n\mathbb{Z}$, say $a=nk$ and $b=n\ell$ with $k,\ell\in\mathbb{Z}$. Then $a+b=nk+n\ell=n(k+\ell)$, and $k+\ell\in\mathbb{Z}$, so $a+b\in n\mathbb{Z}$. \emph{Closed under inverses:} for $a=nk\in n\mathbb{Z}$ we have $-a=-nk=n(-k)$ with $-k\in\mathbb{Z}$, so $-a\in n\mathbb{Z}$. All three clauses hold, hence $n\mathbb{Z}\sgr\mathbb{Z}$. \textit{Check.} For $n=3$, $6,9\in 3\mathbb{Z}$ and $6+9=15=3\cdot 5\in 3\mathbb{Z}$; also $-6=3\cdot(-2)\in 3\mathbb{Z}$. Note $n\mathbb{Z}=\mathbb{Z}$ when $n=\pm1$ and $n\mathbb{Z}=\{0\}$ when $n=0$.
\end{wex}

\begin{wex}{$\SL_n(\mathbb{R})\sgr\GL_n(\mathbb{R})$}
Let $\SL_n(\mathbb{R})=\{A\in\GL_n(\mathbb{R})\st\det A=1\}$. Show it is a subgroup of $\GL_n(\mathbb{R})$ (invertible real $n\times n$ matrices under multiplication).
\wrec A subset cut out by a condition ($\det=1$) inside a matrix group. Run the checklist, using the multiplicativity of $\det$: $\det(AB)=\det(A)\det(B)$ and $\det(A^{-1})=(\det A)^{-1}$.
\wsol \emph{Identity:} $\det(I)=1$, so $I\in\SL_n(\mathbb{R})$ and the set is nonempty. \emph{Closed under products:} if $A,B\in\SL_n(\mathbb{R})$ then $\det A=\det B=1$, so $\det(AB)=\det(A)\det(B)=1\cdot 1=1$, hence $AB\in\SL_n(\mathbb{R})$ (and $AB$ is invertible, so it lies in $\GL_n(\mathbb{R})$). \emph{Closed under inverses:} if $A\in\SL_n(\mathbb{R})$ then $\det A=1\neq 0$, so $A^{-1}$ exists, and $\det(A^{-1})=1/\det(A)=1/1=1$, hence $A^{-1}\in\SL_n(\mathbb{R})$. Therefore $\SL_n(\mathbb{R})\sgr\GL_n(\mathbb{R})$. \textit{Check.} $A=\begin{psmallmatrix}2&1\\1&1\end{psmallmatrix}$ has $\det A=2-1=1$, and $A^{-1}=\begin{psmallmatrix}1&-1\\-1&2\end{psmallmatrix}$ has $\det=2-1=1$; both lie in $\SL_2(\mathbb{R})$.
\end{wex}

\begin{wex}{Torsion subgroup of an abelian group}
Let $G$ be abelian and set $T=\{g\in G\st \ord{g}<\infty\}$ (the elements of finite order). Show $T\sgr G$.
\wrec Described as ``all elements satisfying a finiteness condition.'' The condition is about orders, so the tool is: $\ord{g}<\infty$ means $g^m=1$ for some $m\geq 1$. We will need commutativity to combine two finite-order elements --- this is exactly where abelianness is used.
\wsol \emph{Identity:} $\ord{1}=1<\infty$, so $1\in T$ and $T\neq\varnothing$. \emph{Closed under products:} let $a,b\in T$, say $a^m=1$ and $b^n=1$ with $m,n\geq 1$. Since $G$ is abelian, $a$ and $b$ commute, so $(ab)^{mn}=a^{mn}b^{mn}=(a^m)^n(b^n)^m=1^n\cdot 1^m=1$. Thus $\ord{ab}$ divides $mn$, in particular $\ord{ab}<\infty$, so $ab\in T$. \emph{Closed under inverses:} if $a\in T$ with $a^m=1$, then $(a^{-1})^m=(a^m)^{-1}=1^{-1}=1$, so $\ord{a^{-1}}<\infty$ and $a^{-1}\in T$. Hence $T\sgr G$. \textit{Check.} In $G=(\mathbb{Z}/(15)\mathbb{Z})^{\times}$ (abelian, order $8$), $2$ has order $4$ ($2,4,8,16\equiv1$) and $4$ has order $2$; their product $2\cdot4=8$ has order $4$ ($8,64\equiv4,512\equiv2,\dots$ returns to $1$ at the $4$th power), again of finite order, consistent with $T=G$ here.
\end{wex}

\begin{pitfall}
The torsion set need NOT be a subgroup if $G$ is \emph{nonabelian}: in $\GL_2(\mathbb{R})$, $a=\begin{psmallmatrix}-1&0\\0&1\end{psmallmatrix}$ and $b=\begin{psmallmatrix}-1&1\\0&1\end{psmallmatrix}$ both have order $2$, but $ab=\begin{psmallmatrix}1&-1\\0&1\end{psmallmatrix}$ has infinite order. Commutativity is essential in the closure step above.
\end{pitfall}

\begin{wex}{NON-example: the odd integers}
Let $O=\{\text{odd integers}\}=\{\dots,-3,\allowbreak-1,\allowbreak1,\allowbreak3,\dots\}\subseteq\mathbb{Z}$. Decide whether $O\sgr(\mathbb{Z},+)$.
\wrec A described subset of $(\mathbb{Z},+)$: run the checklist, but as soon as one clause fails we may stop and declare ``not a subgroup.'' Quickest clause to test for $O$ is the identity, since $0$ is even.
\wsol \emph{Identity fails:} the additive identity of $\mathbb{Z}$ is $0$, which is even, so $0\notin O$. By Proposition~\ref{p:agree@c2} a subgroup must contain $1_G=0$, so $O$ is \emph{not} a subgroup. \emph{Closure also fails, independently:} $1\in O$ and $3\in O$ but $1+3=4\notin O$ (sum of two odds is even). \textit{Conclusion.} $O\not\sgr\mathbb{Z}$: it lacks the identity $0$ (although $O\neq\varnothing$) and fails clause (1). \textit{Check.} Two failures confirm each other; a single one already suffices.
\end{wex}

\begin{wex}{NON-example vs example inside $D_8$}
In $D_8=\langle r,s\st r^4=s^2=1,\ srs=r^{-1}\rangle$, compare the subsets $A=\{1,s\}$ and $B=\{1,s,sr\}$.
\wrec Two finite subsets of a finite group. By the finite shortcut (Remark~\ref{r:two-step@c2}), once a nonempty finite set is closed under products it is automatically a subgroup, so closure under products is the decisive test. Use the relation $srs=r^{-1}$, i.e. $sr=r^{-1} s$, to simplify products.
\wsol \emph{For $A=\{1,s\}$:} it is nonempty and finite. Products: $1\cdot1=1$, $1\cdot s=s$, $s\cdot1=s$, and $s\cdot s=s^2=1$. Every product lands in $A$, so $A$ is closed; being finite and nonempty, $A\sgr D_8$ (indeed $\ord{s}=2$ so $A=\langle s\rangle$).
\emph{For $B=\{1,s,sr\}$:} test closure. Compute $s\cdot(sr)=(ss)r=s^2r=r$. But $r\notin B$ (the elements of $B$ are $1$, $s$, and $sr$, none equal to $r$ since $r\neq 1$, $r\neq s$, and $r\neq sr$ as that would force $s=1$). Closure under products fails, so $B\not\sgr D_8$. \textit{Check.} $|B|=3$ does not divide $|D_8|=8$, so by Lagrange's theorem (Chapter 3) $B$ could never have been a subgroup --- consistent with our direct computation.
\end{wex}

\begin{wex}{The unit circle $S^1\sgr\mathbb{C}^\times$}
Let $S^1=\{z\in\mathbb{C}^\times\st |z|=1\}$ where $\mathbb{C}^\times=\mathbb{C}\setminus\{0\}$ under multiplication. Show $S^1\sgr\mathbb{C}^\times$.
\wrec A subset of the multiplicative group $\mathbb{C}^\times$ cut out by the condition $|z|=1$. The relevant tool is multiplicativity of modulus: $|zw|=|z|\,|w|$ and $|z^{-1}|=|z|^{-1}$ for $z\neq0$.
\wsol \emph{Identity:} $|1|=1$, so $1\in S^1$ and $S^1\neq\varnothing$. \emph{Closed under products:} if $z,w\in S^1$ then $|z|=|w|=1$, so $|zw|=|z|\,|w|=1\cdot1=1$, hence $zw\in S^1$. \emph{Closed under inverses:} if $z\in S^1$ then $z\neq0$ and $|z^{-1}|=1/|z|=1/1=1$, so $z^{-1}\in S^1$. Therefore $S^1\sgr\mathbb{C}^\times$. \textit{Check.} $z=\tfrac{\sqrt2}{2}+\tfrac{\sqrt2}{2}i$ has $|z|^2=\tfrac12+\tfrac12=1$; its inverse is its conjugate $\bar z=\tfrac{\sqrt2}{2}-\tfrac{\sqrt2}{2}i$, which also has modulus $1$ and lies in $S^1$.
\end{wex}

\begin{wex}{A bare-definition / one-step variation: $\langle i\rangle\sgr Q_8$}
In $Q_8=\{\pm1,\pm i,\pm j,\pm k\}$, show $H=\{1,i,-1,-i\}$ is a subgroup, using the one-step test $ab^{-1}\in H$.
\wrec We are told to use the one-step criterion (Remark~\ref{r:two-step@c2}): for nonempty $H$, $H\sgr G$ iff $ab^{-1}\in H$ for all $a,b\in H$. Trigger: a finite explicit subset and an instruction (or convenience) to do a single combined check. Recall in $Q_8$: $i^2=-1$, $i^{-1}=-i$, $(-1)^{-1}=-1$, $(-i)^{-1}=i$.
\wsol $H\neq\varnothing$ since $1\in H$. Note $H=\{i^0,i^1,i^2,i^3\}=\langle i\rangle$, the cyclic group generated by $i$ (as $i$ has order $4$: $i,i^2=-1,i^3=-i,i^4=1$). For any $a,b\in H$, both are powers of $i$, say $a=i^p,b=i^q$; then $ab^{-1}=i^p(i^q)^{-1}=i^{p-q}$, which is again a power of $i$ and hence in $H$. Thus the one-step condition holds and $H\sgr Q_8$. \emph{Check, a sample:} $a=i$, $b=-1=i^2$ give $ab^{-1}=i\cdot(-1)^{-1}=i\cdot(-1)=-i\in H$; and $a=-i$, $b=i$ give $ab^{-1}=(-i)(i^{-1})=(-i)(-i)=i^2=-1\in H$. Both land in $H$, as predicted.
\end{wex}

The decisive computation in the $D_8$ non-example is a closure table: list the candidate elements down the side and across the top, fill in each product, and a subset is closed exactly when \emph{every} entry lies back in the subset. For $B=\{1,s,sr\}\subseteq D_8$ the table immediately exposes the escape $s\cdot sr=r\notin B$.

\begin{center}
\begin{tabular}{c|ccc}
$\cdot$ & $1$ & $s$ & $sr$\\
\hline
$1$ & $1$ & $s$ & $sr$\\
$s$ & $s$ & $1$ & $\mathbf{r}$\\
$sr$ & $sr$ & $\mathbf{r^{-1}}$ & $1$\\
\end{tabular}
\end{center}

The bold entries $r$ and $r^{-1}=r^3$ both lie \emph{outside} $B$, so $B$ is not closed; even one such entry would disqualify it. The entries are computed from $sr=r^{-1} s$: namely $s\cdot sr=s^2r=r$, and $sr\cdot s=s(rs)=s(s r^{-1})=s^2r^{-1}=r^{-1}$. The remaining product $sr\cdot sr=s\,r\,s\,r=s(rs)r=s(sr^{-1})r=s^2r^{-1} r=r^{-1} r=1$ lands back in $B$, but the two off-list entries $r$ and $r^{-1}$ already break closure.

