\begin{proposition}\label{p:subcrit@c2}
Let $G$ be a group and $H\subseteq G$. Then $H\sgr G$ if and only if
\[
\text{(a)}\quad H\neq\varnothing,\qquad\text{and}\qquad\text{(b)}\quad \forall\,x,y\in H,\ \ xy^{-1}\in H.
\]
\end{proposition}

\begin{proof}
($\Longrightarrow$) If $H\sgr G$ then $H$ contains the identity, so $H\neq\varnothing$, giving (a). For $x,y\in H$, subgroup closure under inverses gives $y^{-1}\in H$, and closure under the product gives $xy^{-1}\in H$, giving (b).

($\Leftarrow$, that is the substantive direction) Assume (a) and (b). By (a) pick some $a\in H$. Apply (b) with $x=y=a$: then $aa^{-1}=1\in H$, so $H$ contains the identity. Next, for any $a\in H$, apply (b) with $x=1$ and $y=a$: $1\cdot a^{-1}=a^{-1}\in H$, so $H$ is closed under inverses. Finally, for $a,b\in H$ we have just shown $b^{-1}\in H$; apply (b) with $x=a$, $y=b^{-1}$ to get $a(b^{-1})^{-1}=ab\in H$, so $H$ is closed under the product. Associativity holds in $H$ because it holds in $G$ and $H\subseteq G$. Thus $H$ is a group under the operation of $G$, i.e. $H\sgr G$.
\end{proof}

\begin{remark}
The single condition (b) is doing triple duty: $x=y$ forces $1\in H$; $x=1$ forces inverses; and then $x,\,y^{-1}$ forces products. This is why it is called the \emph{one-step} subgroup test.
\end{remark}

\begin{method}{One-step criterion vs. the full definition}
\textit{Recognition trigger.} You are handed a \emph{subset} $H$ of a known group $G$ and asked ``is $H$ a subgroup?'' Do NOT re-verify associativity --- it is inherited. Instead:
\begin{enumerate}
\item \textbf{Nonempty.} Exhibit one explicit element of $H$ (usually check $1\in H$; that already settles (a)).
\item \textbf{One-step closure.} Take \emph{arbitrary} $x,y\in H$, write the defining property each satisfies, and compute $xy^{-1}$. Show $xy^{-1}$ satisfies the same defining property.
\item Conclude $H\sgr G$ by Proposition~\ref{p:subcrit@c2}.
\end{enumerate}
\textbf{When to use which:} use the one-step criterion whenever $H$ is described by a \emph{closed-form condition} (a determinant value, a modulus, a divisibility, a matrix shape). Use the raw two-step version (check products and inverses separately) only when computing $xy^{-1}$ in one shot is awkward and splitting is clearer. Never bother re-proving associativity.
\end{method}

\begin{pitfall}
The criterion is $xy^{-1}\in H$, not $xy\in H$. A subset closed under products only (e.g.\ $\mathbb{Z}_{\ge 0}\subseteq\mathbb{Z}$) need not be a subgroup. Closure under products alone suffices ONLY in the finite case (Proposition~\ref{p:finsubcrit@c2} below).
\end{pitfall}

\begin{proposition}\label{p:finsubcrit@c2}
Let $G$ be a group and let $H$ be a \emph{finite} nonempty subset of $G$ that is closed under the operation of $G$ (i.e.\ $xy\in H$ for all $x,y\in H$). Then $H\sgr G$.
\end{proposition}

\begin{remark}
Finiteness is essential: $\mathbb{Z}_{\ge0}\subseteq\mathbb{Z}$ from the last worked example is nonempty and closed under $+$, but is not a subgroup --- it is infinite, so the powers $x,2x,3x,\dots$ never repeat and inverses never get forced.
\end{remark}

\begin{method}{When the finite criterion saves work}
\textit{Recognition trigger.} $H$ is a \emph{finite} subset of $G$ (e.g.\ an explicitly listed finite set, or any subset of a finite group) and you want to prove $H\sgr G$. Then:
\begin{enumerate}
\item Confirm $H$ is nonempty and finite.
\item Check closure under the product ONLY: verify $xy\in H$ for all $x,y\in H$ (for a small explicit set, fill in the multiplication table; for a structured set, give a closure argument).
\item Invoke Proposition~\ref{p:finsubcrit@c2}; inverses and the identity come for free.
\end{enumerate}
Use this whenever checking $x^{-1}\in H$ separately would be extra labor --- the finite criterion lets you skip the inverse check entirely.
\end{method}

