\begin{pitfall}
Do not apply the finite criterion to a finite \emph{subset of an infinite group} without first checking closure carefully, and never apply it to an infinite set. The set $\{1,2,4,\dots\}$ above is closed under products yet is not a subgroup --- its infiniteness is the whole reason.
\end{pitfall}

\begin{wex}{The chains $\mathbb{Z}\sgr\mathbb{Q}\sgr\mathbb{R}\sgr\mathbb{C}$ and $\mathbb{Q}^\times\sgr\mathbb{R}^\times\sgr\mathbb{C}^\times$}
Show that under addition $\mathbb{Z}\sgr\mathbb{Q}\sgr\mathbb{R}\sgr\mathbb{C}$, and that under multiplication $\mathbb{Q}^\times\sgr\mathbb{R}^\times\sgr\mathbb{C}^\times$ (nonzero elements).
\wrec Each link is a subset of a known group closed under the operation, so run the one-step criterion (Proposition~\ref{p:subcrit@c2}) on each inclusion; transitivity then chains them. Additively ``$xy^{-1}$'' means $x-y$; multiplicatively it means $x/y$.
\wsol \emph{Additive chain.} For $\mathbb{Z}\sgr\mathbb{Q}$: $0\in\mathbb{Z}$, and for $x,y\in\mathbb{Z}$, $x-y\in\mathbb{Z}$. For $\mathbb{Q}\sgr\mathbb{R}$: $0\in\mathbb{Q}$, and a difference of rationals is rational. For $\mathbb{R}\sgr\mathbb{C}$: $0\in\mathbb{R}$, and a difference of reals is real. By Proposition~\ref{p:subcrit@c2} each is a subgroup, and by transitivity $\mathbb{Z}\sgr\mathbb{C}$ as well. \emph{Multiplicative chain.} For $\mathbb{Q}^\times\sgr\mathbb{R}^\times$: $1\in\mathbb{Q}^\times$, and for nonzero rationals $x,y$ the quotient $x/y$ is a nonzero rational. For $\mathbb{R}^\times\sgr\mathbb{C}^\times$: $1\in\mathbb{R}^\times$, and a quotient of nonzero reals is a nonzero real. So $\mathbb{Q}^\times\sgr\mathbb{R}^\times\sgr\mathbb{C}^\times$, hence $\mathbb{Q}^\times\sgr\mathbb{C}^\times$. \textit{Check.} The additive and multiplicative chains are genuinely different containments --- e.g.\ $\tfrac12\in\mathbb{Q}$ but $\tfrac12\notin\mathbb{Z}$, while $\tfrac12\in\mathbb{Q}^\times$; and $0\in\mathbb{C}$ lies in every additive stage but in \emph{no} multiplicative stage, since $\mathbb{C}^\times=\mathbb{C}\setminus\{0\}$.
\end{wex}

\begin{remark}\label{r:union-not-subgroup-mrg@c2}
If $H,K\sgr G$ then $H\cup K\sgr G$ if and only if $H\subseteq K$ or $K\subseteq H$. Indeed, if neither contains the other, pick $h\in H\setminus K$ and $k\in K\setminus H$; the product $hk$ cannot lie in $H$ (else $k=h^{-1}(hk)\in H$) nor in $K$ (else $h=(hk)k^{-1}\in K$), so $hk\notin H\cup K$ and closure fails. The \emph{intersection} $H\cap K$ is, by contrast, always a subgroup, by a single one-step check valid in both $H$ and $K$ at once.
\end{remark}

\begin{wex}{A union of two subgroups that fails closure}
In the Klein four-group $V_4=\{1,a,b,ab\}$ (every nonidentity element of order $2$, $ab=ba$), let $H=\{1,a\}$ and $K=\{1,b\}$. Show $H,K\sgr V_4$ but $H\cup K\not\sgr V_4$.
\wrec Each of $H,K$ is finite and closed under products, hence a subgroup (Proposition~\ref{p:finsubcrit@c2}); the union illustrates Remark~\ref{r:union-not-subgroup-mrg@c2} since neither contains the other. To disprove, exhibit a product of an $H$-element and a $K$-element that escapes the union.
\wsol $H=\{1,a\}=\langle a\rangle$ and $K=\{1,b\}=\langle b\rangle$ are subgroups (each is $\{1,x\}$ with $x^2=1$, closed under products). Now $H\cup K=\{1,a,b\}$. Take $a\in H\cup K$ and $b\in H\cup K$: their product is $ab$, and $ab\notin\{1,a,b\}$ (it is the fourth, distinct element of $V_4$). So $H\cup K$ is not closed under products, hence $H\cup K\not\sgr V_4$. \textit{Check.} Neither $H\subseteq K$ nor $K\subseteq H$ holds, exactly the situation Remark~\ref{r:union-not-subgroup-mrg@c2} predicts will fail; and $|H\cup K|=3$ does not divide $|V_4|=4$, a second confirmation via Lagrange (Chapter~3).
\end{wex}

\begin{wex}{the diagonal $\Delta\sgr G\times G$}
Show $\Delta=\{(g,g)\st g\in G\}$ is a subgroup of $G\times G$.
\wrec A described subset of the known group $G\times G$; apply the one-step criterion.
Membership means ``both coordinates equal.''
\wsol Nonempty: $(1,1)\in\Delta$. For $(g,g),(h,h)\in\Delta$,
\[ (g,g)(h,h)^{-1}=(g,g)(h^{-1},h^{-1})=(gh^{-1},\,gh^{-1})\in\Delta, \]
since the two coordinates agree. By the criterion $\Delta\sgr G\times G$. \textit{Check.}
$g\mapsto(g,g)$ shows $\ord{\Delta}=\ord{G}$.
\end{wex}

\begin{definition}\label{d:cent@c2}
Let $G$ be a group and $A\subseteq G$ a nonempty subset. The \emph{centralizer of $A$ in $G$} is
\[
C_G(A)=\{g\in G\st gag^{-1}=a\ \text{for all }a\in A\}
=\{g\in G\st ga=ag\ \text{for all }a\in A\}.
\]
When $A=\{a\}$ is a single element we write $C_G(a)=\{g\in G\st gag^{-1}=a\}=\{g\in G\st ga=ag\}$. Thus $C_G(a)$ is the set of all elements that commute with $a$, and $C_G(A)$ is the set of elements that commute with \emph{every} element of $A$. The two displayed descriptions agree because $gag^{-1}=a\Longleftrightarrow ga=ag$ (multiply on the right by $g$).
\end{definition}

\begin{proposition}\label{p:cent-subgroup@c2}
For any nonempty $A\subseteq G$, $C_G(A)\sgr G$.
\end{proposition}

\begin{method}{How to compute a centralizer $C_G(a)$ (and $C_G(A)$)}
Use this whenever you must find all elements commuting with a fixed element $a$ (or with a whole subset $A$).
\begin{enumerate}
\item \textbf{Single element $C_G(a)$.} Test each $g\in G$ (or each coset/type of element) by checking $ga=ag$. In a group given by generators and relations (e.g.\ $D_{2n}$ with $sr=r^{-1} s$, or $Q_8$), push every product to a normal form and compare; do not test brute force if a relation settles it.
\item \textbf{Powers are free.} Every power of $a$ commutes with $a$, so $\langle a\rangle\subseteq C_G(a)$ automatically. You only need to test elements \emph{outside} $\langle a\rangle$.
\item \textbf{Use the relation to predict failures.} In $D_{2n}$, $s r^k=r^{-k}s$, so a reflection $s r^j$ commutes with $r^k$ iff $r^k=r^{-k}$, i.e.\ iff $r^{2k}=1$. This tells you instantly which rotations are centralized by reflections.
\item \textbf{Subset $A$: intersect.} Compute $C_G(a)$ for each $a$ in a generating set $S$ of $A$, then take $\bigcap_{a\in S}C_G(a)$ (Remark~\ref{r:cent-facts@c2}).
\item \textit{Sanity checks.} The answer must be a subgroup (closed, contains $1$, contains inverses), must contain $\langle a\rangle$, and (by Lagrange) its order must divide $|G|$.
\end{enumerate}
\end{method}

\begin{pitfall}
$C_G(a)$ is the set of elements that commute \emph{with $a$}, not the set of elements that commute with \emph{everything} (that is the center $Z(G)=C_G(G)$). Also $C_G(a)$ need not be abelian, and need not equal $\langle a\rangle$.
\end{pitfall}

\begin{pitfall}
When $A$ is a subgroup, do not assume $C_G(A)\supseteq A$; that holds only when $A$ is abelian (then every element of $A$ commutes with every other, so $A\subseteq C_G(A)$). For $A=\langle r\rangle$ above, $A$ is abelian and indeed $\langle r\rangle\subseteq C_{D_8}(\langle r\rangle)$ -- in fact equality. But for a nonabelian $A$ you would lose this containment.
\end{pitfall}

