\begin{proposition}\label{p:center-subgroup@c2}
For any group $G$, $Z(G)\sgr G$, and $Z(G)$ is abelian. Moreover $Z(G)\nor G$ (it is a normal subgroup).
\end{proposition}

\begin{proof}
Nonempty: $1x=x=x1$ for all $x$, so $1\in Z(G)$. Closed: if $g,h\in Z(G)$ and $x\in G$ then $(gh)x=g(hx)=g(xh)=(gx)h=(xg)h=x(gh)$, so $gh\in Z(G)$. Inverses: if $g\in Z(G)$ then $gx=xg$ for all $x$; multiply on both sides by $g^{-1}$ to get $xg^{-1}=g^{-1} x$, so $g^{-1}\in Z(G)$. Hence $Z(G)\sgr G$ by the subgroup criterion. It is abelian because any two of its elements each commute with everything in $G$, in particular with each other. For normality: if $g\in Z(G)$ and $a\in G$ then $aga^{-1}=ag a^{-1} = g a a^{-1} = g\in Z(G)$ (using $ag=ga$), so $aZ(G)a^{-1}\subseteq Z(G)$ for every $a$; thus $Z(G)\nor G$.
\end{proof}

\begin{remark}
$Z(G)$ measures how far $G$ is from being abelian: $Z(G)=G$ exactly when $G$ is abelian, and a ``small'' center signals a highly noncommutative group. Note $Z(G)=\bigcap_a C_G(a)$ is an intersection of subgroups, hence automatically a subgroup --- this is the practical formula we exploit below.
\end{remark}

\begin{method}{How to compute $Z(G)$ from a generating set}
\textit{Recognition trigger.} Use this whenever you are asked for $Z(G)$ and $G=\langle S\rangle$ for a small generating set $S$ (e.g.\ $D_{2n}=\langle r,s\rangle$, $Q_8=\langle i,j\rangle$, $S_3=\langle (1\,2),(1\,2\,3)\rangle$, $\GL_n(\F)$ generated by elementary/transvection-type matrices).
\begin{enumerate}
\item \textbf{Reduce the test set.} An element $g$ is central iff $gx=xg$ for \emph{all} $x\in G$. But if $g$ commutes with each generator in $S$, it commutes with every product of generators and their inverses, hence with all of $G$. So
\[
Z(G)=\bigcap_{x\in S}C_G(x).
\]
You only need to test commutation against the generators.
\item \textbf{Parametrize a general element} $g$ of $G$ (e.g.\ $g=r^k$ or $g=r^k s$ in $D_{2n}$; $g=\sum$ of basis quaternions; $g=$ general matrix).
\item \textbf{Impose $gx=xg$ for each generator $x\in S$} and solve the resulting equations for the parameters.
\item \textbf{Collect the surviving $g$'s}; that set is $Z(G)$. Always finish with $|Z(G)|$ and a sanity check (does $1$ lie in it? is the answer a subgroup?).
\end{enumerate}
\end{method}

\begin{theorem}[Center of the dihedral group]\label{t:center-dihedral@c2}
Let $D_{2n}=\langle r,s\st r^n=s^2=1,\ srs=r^{-1}\rangle$ with $n\ge3$. Then
\[
Z(D_{2n})=
\begin{cases}
\{1\}, & n\ \text{odd},\\[2pt]
\{1,\,r^{n/2}\}, & n\ \text{even}.
\end{cases}
\]
\end{theorem}

\begin{proof}
By the method box, $Z=C(r)\cap C(s)$. \emph{Step 1 (rotations).} For $r^k$: $r^k$ commutes with $r$ automatically; and $s r^k s^{-1} = (srs)^k = (r^{-1})^k = r^{-k}$, so $r^k$ commutes with $s$ iff $r^{-k}=r^{k}$, i.e.\ $r^{2k}=1$, i.e.\ $n\mid 2k$. For $0\le k<n$ this forces $k=0$, or $k=n/2$ when $n$ is even. \emph{Step 2 (reflections).} For a reflection $r^k s$: it does not commute with $r$, since $r(r^k s)=r^{k+1}s$ while $(r^k s)r = r^k (sr) = r^k r^{-1} s = r^{k-1}s$, and $r^{k+1}s=r^{k-1}s$ would force $r^2=1$, impossible for $n\ge3$. So no reflection is central. Combining, $Z=\{1\}$ if $n$ is odd and $Z=\{1,r^{n/2}\}$ if $n$ is even.
\end{proof}

\begin{pitfall}
Do not confuse $Z(G)$ with $C_G(a)$ for a single element $a$. The centralizer $C_G(a)$ can be large (it always contains $\langle a\rangle$) even when $Z(G)=1$. For example in $S_3$, $C_{S_3}((1\,2\,3))=\langle (1\,2\,3)\rangle$ has order $3$, yet $Z(S_3)=1$. The center is the intersection of \emph{all} the centralizers, so it is typically much smaller.
\end{pitfall}

