\begin{pitfall}
A reflection $r^k s$ in $D_{2n}$ is \emph{never} central for $n\ge3$, even when $n$ is even --- the lone central nontrivial element is the half-turn rotation $r^{n/2}$. Students sometimes guess that ``$s$ commutes with the half-turn so $s$ is central''; but centrality requires commuting with \emph{every} element, and $s$ fails against $r$ (since $rs=sr^{-1}\ne sr$).
\end{pitfall}

\begin{remark}
The single inclusion $gAg^{-1}\subseteq A$ already forces the reverse inclusion automatically: since $x\mapsto gxg^{-1}$ is injective and $A$ is finite (in our examples), $gAg^{-1}\subseteq A$ with equal cardinality gives $gAg^{-1}=A$. For infinite $A$ you must check both inclusions, or equivalently $gAg^{-1}\subseteq A$ AND $g^{-1} Ag\subseteq A$.
\end{remark}

\begin{proof}
\emph{$N_G(A)\sgr G$.} $1A1^{-1}=A$, so $1\in N_G(A)$. If $g,h\in N_G(A)$ then $(gh)A(gh)^{-1}=g(hAh^{-1})g^{-1}=gAg^{-1}=A$, so $gh\in N_G(A)$. If $gAg^{-1}=A$, conjugate by $g^{-1}$: $g^{-1} A g=g^{-1}(gAg^{-1})g=A$, so $g^{-1}\in N_G(A)$. Hence $N_G(A)\sgr G$.

\emph{$C_G(A)\sgr N_G(A)$.} $C_G(A)\sgr G$ by the same argument (identity is in it, and it is closed under products and inverses). If $g\in C_G(A)$ then $gag^{-1}=a\in A$ for every $a\in A$, so $gAg^{-1}=A$; thus $g\in N_G(A)$. Since $C_G(A)\subseteq N_G(A)$ and both are subgroups of $G$, $C_G(A)\sgr N_G(A)$.

\emph{$H\nor N_G(H)$.} For $H$ a subgroup, every $h\in H$ satisfies $hHh^{-1}=H$ (subgroups are conjugation-closed by themselves), so $H\subseteq N_G(H)$, hence $H\sgr N_G(H)$. The defining condition $gHg^{-1}=H$ for all $g\in N_G(H)$ is exactly normality of $H$ in $N_G(H)$. If $H\nor K\sgr G$ then $kHk^{-1}=H$ for all $k\in K$, so $K\subseteq N_G(H)$; thus $N_G(H)$ is the largest such $K$.
\end{proof}

\begin{method}{How to compute $N_G(H)$}
Use this whenever you must decide which $g$ conjugate a subgroup $H$ \emph{onto itself as a set} (e.g. to find the largest subgroup in which $H$ is normal, or to detect normality).
\begin{enumerate}
\item \textbf{Free wins first.} $H\subseteq N_G(H)$ always, and $C_G(H)\subseteq N_G(H)$ always. List those elements; they are in for free.
\item \textbf{Index-2 shortcut.} If $[G:H]=2$ then $H\nor G$, so $N_G(H)=G$. Stop. (Two cosets $H$ and $gH$; the only options force $gH=Hg$.)
\item \textbf{Generator test.} Write $H=\langle a\rangle$ (or list generators). For \emph{finite} $H$, $gHg^{-1}=H$ iff $gag^{-1}\in H$ for each generator $a$ (a homomorphic image of a generating set generates the image, so $gHg^{-1}\subseteq H$, and $|gHg^{-1}|=|H|$). So test ONLY the generators, not every element. (For infinite $H$ this gives only $gHg^{-1}\subseteq H$; also test $g^{-1} ag\in H$.)
\item \textbf{Setwise, not pointwise.} You only need $gag^{-1}$ to land \emph{somewhere} in $H$, not back at $a$. (Pointwise would be the centralizer.)
\item \textbf{Assemble a subgroup.} $N_G(H)$ is a subgroup containing $H$; use Lagrange to limit its possible order, then confirm with coset reps.
\end{enumerate}
\end{method}

\begin{pitfall}
$N_G(H)=G$ does NOT mean $G$ is abelian or that $H$ is central. It means $H$ is \emph{normal}: $gHg^{-1}=H$ setwise. Conjugation may still scramble the elements of $H$ (e.g. send $r\mapsto r^{-1}$), as long as it stays inside $H$.
\end{pitfall}

\begin{pitfall}
Do not confuse $gag^{-1}\in H$ (normalizer condition) with $gag^{-1}=a$ (centralizer condition). Testing the wrong one is the most common error: a generator can be moved to another element of $H$ and still be normalized.
\end{pitfall}

