\begin{proposition}\label{p:stab-subgroup@c2}
For each $a\in A$ the stabilizer $G_a\sgr G$. Consequently $\ker=\bigcap_{a\in A}G_a\sgr G$.
\end{proposition}

\begin{proof}
Use the subgroup criterion. First $1\in G_a$ since $1\cdot a=a$, so $G_a\neq\varnothing$. Let $x,y\in G_a$, so $x\cdot a=a$ and $y\cdot a=a$. From $y\cdot a=a$ apply $y^{-1}$: $y^{-1}\cdot a=y^{-1}\cdot(y\cdot a)=(y^{-1} y)\cdot a=1\cdot a=a$, so $y^{-1}\in G_a$. Then $(xy^{-1})\cdot a=x\cdot(y^{-1}\cdot a)=x\cdot a=a$, so $xy^{-1}\in G_a$. Hence $G_a\sgr G$. An arbitrary intersection of subgroups is a subgroup, so $\ker=\bigcap_a G_a\sgr G$.
\end{proof}

\begin{remark}\label{r:kernel-normal@c2}
The kernel is in fact \emph{normal}: it is the kernel of the homomorphism $G\to S_A$, and kernels of homomorphisms are normal subgroups (D\&F 3.1). A single stabilizer $G_a$ need not be normal -- see the conjugation examples, where $G_a=C_G(a)$ can fail to be normal.
\end{remark}

\begin{theorem}\label{t:conj@c2}
Let $G$ be a group.
\begin{enumerate}
\item[(a)] $G$ acts on the set $\mathcal P(G)$ of subsets of $G$ by $g\cdot S=gSg^{-1}$. For a fixed subset $A\subseteq G$ the stabilizer of $A$ under this action is the \textbf{normalizer}
\[
\mathrm{Stab}(A)=\{\,g\in G\st gAg^{-1}=A\,\}=N_G(A).
\]
\item[(b)] $G$ acts on the set $G$ itself by $g\cdot a=gag^{-1}$. For a fixed subset $A\subseteq G$, the subgroup fixing \emph{every} point of $A$ -- i.e.\ the kernel of the restricted action of $N_G(A)$ on the set $A$ -- is the \textbf{centralizer}
\[
\{\,g\st gag^{-1}=a\ \forall a\in A\,\}=\{\,g\st ga=ag\ \forall a\in A\,\}=C_G(A).
\]
In particular the stabilizer of a single point $a$ under conjugation is $\mathrm{Stab}(a)=C_G(a)=C_G(\{a\})$.
\end{enumerate}
\end{theorem}

\begin{method}{Stabilizer vs.\ kernel: which one is it, and how to compute it}
\textit{Recognition trigger.} You have a group $G$ acting on a set $A$ (a literal action like ``$S_n$ permutes $\{1,\dots,n\}$,'' or a conjugation action). Ask which question is being posed:
\begin{enumerate}
\item \emph{Which $g$ fix ONE chosen point $a$?} $\;\Rightarrow$ stabilizer $G_a$.
\item \emph{Which $g$ fix EVERY point at once?} $\;\Rightarrow$ kernel $=\bigcap_a G_a$.
\end{enumerate}
\textbf{Recipe to compute a stabilizer $G_a$.}
\begin{enumerate}
\item Write down the action rule $g\cdot a$ explicitly.
\item Set $g\cdot a=a$ and solve for the constraint on $g$.
\item Collect all such $g$; verify it is a subgroup (Prop.~\ref{p:stab-subgroup@c2} guarantees it, but listing elements is a check).
\item Identify the abstract group (often $S_{n-1}$, a small cyclic/reflection group, or a matrix block group).
\end{enumerate}
\textbf{Recipe to compute a kernel.} Either (a) intersect the stabilizers $\bigcap_a G_a$, or (b) find $\ker$ of the homomorphism $G\to S_A$ -- i.e.\ which $g$ induce the identity permutation. The action is \emph{faithful} exactly when this is $\{1\}$.
\textbf{Conjugation dictionary.} Conjugation on subsets: $\mathrm{Stab}(A)=N_G(A)$. Conjugation on points of $A$: kernel $=C_G(A)$; single point: $\mathrm{Stab}(a)=C_G(a)$.
\end{method}

\begin{pitfall}
``Stabilizer'' fixes a point \emph{setwise}/\emph{as a point}, not pointwise-inside-it. For conjugation on subsets, $g\in N_G(A)$ only requires $gAg^{-1}=A$ as a \emph{set} -- elements may be permuted. Requiring each element to be fixed gives the smaller $C_G(A)$. Always $C_G(A)\sgr N_G(A)$, and the inclusion is often strict.
\end{pitfall}

