\begin{wex}{$S_n$ on $\{1,\dots,n\}$: $\mathrm{Stab}(n)\cong S_{n-1}$}
Let $S_n$ act on $A=\{1,2,\dots,n\}$ in the natural way, $\sigma\cdot i=\sigma(i)$. Compute the stabilizer of the point $n$ and identify it up to isomorphism.
\wrec We are asked for the permutations fixing ONE chosen point $n$ -- trigger 1 of the method box, so this is a stabilizer $G_n$, not a kernel. The action rule is just ``apply the permutation,'' so set $\sigma(n)=n$.
\wsol Set the defining condition: $\sigma\in (S_n)_n$ iff $\sigma\cdot n=n$ iff $\sigma(n)=n$. Such a $\sigma$ permutes $\{1,\dots,n\}$ but pins $n$, hence it permutes the remaining $n-1$ symbols $\{1,\dots,n-1\}$ arbitrarily and bijectively. The map
\[
\Phi:(S_n)_n\to S_{\{1,\dots,n-1\}}=S_{n-1},\qquad \Phi(\sigma)=\sigma|_{\{1,\dots,n-1\}}
\]
is well defined (restriction of a bijection fixing $n$ is a bijection of the rest), a homomorphism (restriction respects composition), injective (a $\sigma$ fixing $n$ is determined by its action on the other $n-1$ points), and surjective (any permutation of $\{1,\dots,n-1\}$ extends by $n\mapsto n$). Hence $(S_n)_n\cong S_{n-1}$.

\textit{Check.} Orders: $|(S_n)_n|=(n-1)!=|S_{n-1}|$, consistent. Also the orbit-stabilizer count $|S_n|=|\text{orbit of }n|\cdot|(S_n)_n|=n\cdot(n-1)!=n!$ is correct, since the orbit of $n$ is all of $\{1,\dots,n\}$ (size $n$).
\end{wex}

\begin{remark}\label{r:os-preview@c2}
Each ``check'' above used \textbf{orbit-stabilizer}: $|G|=|\mathcal O_a|\cdot|G_a|$, where $\mathcal O_a$ is the orbit of $a$. For conjugation on points this reads $|G|=|\text{conjugacy class of }a|\cdot|C_G(a)|$, the class equation input (D\&F 4.3). Stabilizers and kernels are the gateway: the stabilizer measures ``how much of $G$ is wasted fixing $a$,'' and the kernel measures ``how much of $G$ acts invisibly.''
\end{remark}

\begin{definition}\label{d:cyclic@c2}
A group $H$ is \emph{cyclic} if there exists $x\in H$ with $H=\langle x\rangle=\{x^n \st n\in\mathbb{Z}\}$; such an $x$ is a \emph{generator}. We write the abstract cyclic group of order $n$ as $Z_n$, and use $\mathbb{Z}$ for the infinite cyclic group.
\end{definition}

\begin{pitfall}
``Cyclic'' is much stronger than ``abelian.'' $V_4$ is abelian but \emph{not} cyclic: no single element has order $4$, so no element generates all of $V_4$. Cyclic $\Longrightarrow$ abelian, never the reverse.
\end{pitfall}

\begin{proposition}[Order of a cyclic group equals the order of its generator]\label{p:ordgen@c2}
Let $x$ be an element of a group.
\begin{enumerate}
\item If $\ord{x}=n<\infty$, then $\langle x\rangle=\{1,x,x^2,\dots,x^{n-1}\}$ and these $n$ powers are distinct, so $\ord{\langle x\rangle}=n$.
\item If $\ord{x}=\infty$, then the powers $x^k$ ($k\in\mathbb{Z}$) are all distinct, so $\langle x\rangle$ is infinite.
\end{enumerate}
\end{proposition}

\begin{proof}
(1) Let $\ord{x}=n$. For any $t\in\mathbb{Z}$, divide $t=qn+k$ with $0\le k\le n-1$ (division algorithm). Then $x^t=(x^n)^q x^k=1^q x^k=x^k$, so every power of $x$ equals one of $1,x,\dots,x^{n-1}$; hence $\langle x\rangle\subseteq\{1,x,\dots,x^{n-1}\}$, and the reverse inclusion is clear. These $n$ powers are distinct: if $x^i=x^j$ with $0\le i<j\le n-1$, then $x^{j-i}=1$ with $0<j-i<n$, contradicting that $n$ is the \emph{least} positive integer with $x^n=1$. So $\ord{\langle x\rangle}=n$.

(2) If $\ord{x}=\infty$ and $x^i=x^j$ with $i<j$, then $x^{j-i}=1$ with $j-i>0$, forcing $x$ to have finite order, a contradiction. So all powers are distinct and $\langle x\rangle$ is infinite.
\end{proof}

\begin{lemma}[gcd Lemma]\label{l:gcd@c2}
Let $x$ be a group element. If $x^m=1$ and $x^n=1$, then $x^{\gcd(m,n)}=1$. Consequently, if $\ord{x}=d<\infty$, then $x^m=1$ if and only if $d\mid m$.
\end{lemma}

\begin{theorem}[Classification of cyclic groups]\label{t:classify@c2}
Any two cyclic groups of the same order are isomorphic. In particular every finite cyclic group of order $n$ is isomorphic to $Z_n$ (e.g. $\mathbb{Z}/(n)\mathbb{Z}$ under $+$), and every infinite cyclic group is isomorphic to $\mathbb{Z}$.
\end{theorem}

\begin{proof}
Let $H=\langle x\rangle$ and $K=\langle y\rangle$ with $\ord{\langle x\rangle}=\ord{\langle y\rangle}$. Define $\varphi:H\to K$ by $\varphi(x^a)=y^a$. \emph{Well-defined and injective (finite case $\ord{x}=\ord{y}=n$):} $x^a=x^b\Longleftrightarrow x^{a-b}=1\Longleftrightarrow n\mid(a-b)$ (Lemma~\ref{l:gcd@c2}) $\Longleftrightarrow y^{a-b}=1\Longleftrightarrow y^a=y^b$; the chain of equivalences gives both well-definedness and injectivity. (Infinite case: $x^a=x^b\Longleftrightarrow a=b\Longleftrightarrow y^a=y^b$ by Proposition~\ref{p:ordgen@c2}(2).) It is surjective since every $y^a\in K$ is hit, and a homomorphism since $\varphi(x^a x^b)=\varphi(x^{a+b})=y^{a+b}=y^a y^b$. Hence $\varphi$ is an isomorphism, so $H\cong K$.
\end{proof}

\begin{method}{How to recognize a cyclic group and reduce a power $x^t$}
\textit{Recognition trigger.} Use this whenever a group (or subgroup) is presented as ``all powers of a single element,'' or you can exhibit one element whose order equals the order $|G|$ of the (finite) group, e.g.\ $n=|\mu_n|$. Concretely:
\begin{enumerate}
\item \textbf{Find a candidate generator} $x$ and compute $\ord{x}=n$ (least $n>0$ with $x^n=1$).
\item \textbf{Check it fills the group:} if $G$ is finite and $\ord{x}=|G|$, then $\ord{\langle x\rangle}=\ord{x}=|G|$ (Prop.~\ref{p:ordgen@c2}), so $G=\langle x\rangle$ is cyclic with $G=\{1,x,\dots,x^{n-1}\}$.
\item \textbf{To reduce a power $x^t$:} divide $t=qn+k$ with $0\le k<n$ (division algorithm); then $x^t=(x^n)^q x^k=x^k$. The reduced exponent is $k=t\bmod n$.
\item \textbf{To test $x^t=1$:} by the gcd Lemma~\ref{l:gcd@c2}, $x^t=1\Longleftrightarrow n\mid t$.
\end{enumerate}
\end{method}

\begin{wex}{The $n$th roots of unity $\mu_n\sgr\mathbb{C}^\times$ are cyclic}
Let $\mu_n=\{z\in\mathbb{C}^\times \st z^n=1\}$. Show $\mu_n$ is a cyclic group of order $n$ under multiplication.
\wrec A subgroup is cyclic exactly when one element's powers exhaust it (Def.~\ref{d:cyclic@c2}). Here $\mu_n=\{e^{2\pi i k/n}\}$; the natural generator candidate is the primitive root $\zeta=e^{2\pi i/n}$. Verify $\ord{\zeta}=n$ and invoke Prop.~\ref{p:ordgen@c2}.
\wsol First, $\mu_n$ is a group: if $z^n=w^n=1$ then $(zw)^n=z^nw^n=1$ and $(z^{-1})^n=(z^n)^{-1}=1$, so it is closed under products and inverses. Let $\zeta=e^{2\pi i/n}$. Then $\zeta^k=e^{2\pi i k/n}$, and these satisfy $(\zeta^k)^n=e^{2\pi i k}=1$, so $\zeta^k\in\mu_n$ for all $k$. Order of $\zeta$: $\zeta^k=1\Longleftrightarrow e^{2\pi i k/n}=1\Longleftrightarrow n\mid k$, so the least positive such $k$ is $n$; thus $\ord{\zeta}=n$. By Prop.~\ref{p:ordgen@c2}(1), $\langle \zeta\rangle=\{1,\zeta,\dots,\zeta^{n-1}\}$ has $n$ distinct elements, all in $\mu_n$. Since a degree-$n$ polynomial $z^n-1$ has at most $n$ roots in the field $\mathbb{C}$, $|\mu_n|\le n$; combined with $|\langle \zeta\rangle|=n$ we get $\mu_n=\langle \zeta\rangle$. \textit{Check.} For $n=4$, $\zeta=i$ and $\langle i\rangle=\{1,i,-1,-i\}$, exactly the four solutions of $z^4=1$. By Theorem~\ref{t:classify@c2}, $\mu_n\cong Z_n$.
\end{wex}

\begin{wex}{$(\mathbb{Z},+)$ is cyclic with generators $\pm1$}
Show that $(\mathbb{Z},+)$ is an infinite cyclic group, and determine all of its generators.
\wrec Additively, ``powers of $x$'' means ``integer multiples $kx$.'' To prove cyclic, find one element whose multiples give all of $\mathbb{Z}$ (Def.~\ref{d:cyclic@c2}). To find \emph{all} generators, ask which $g$ has $\langle g\rangle=\mathbb{Z}$.
\wsol Take $x=1$. Its integer multiples are $k\cdot1=k$ for $k\in\mathbb{Z}$, which is all of $\mathbb{Z}$, so $\mathbb{Z}=\langle 1\rangle$ is cyclic. Since no positive multiple $k\cdot1=k$ equals the identity $0$ for $k>0$, the order is infinite, matching Prop.~\ref{p:ordgen@c2}(2). Generators: $\langle g\rangle=\{kg\st k\in\mathbb{Z}\}=g\mathbb{Z}$, and $g\mathbb{Z}=\mathbb{Z}$ requires $1\in g\mathbb{Z}$, i.e. $g\mid1$, forcing $g=\pm1$. Both work: $\langle -1\rangle=\{-k\st k\in\mathbb{Z}\}=\mathbb{Z}$, consistent with the identity $\langle x\rangle=\langle x^{-1}\rangle$ (here $x^{-1}=-1$). \textit{Check.} $\langle 2\rangle=2\mathbb{Z}=\{\dots,-2,0,2,\dots\}\ne\mathbb{Z}$ (it misses odd integers), confirming $2$ is \emph{not} a generator and that only $\pm1$ are.
\end{wex}

\begin{wex}{A group of prime order is cyclic}
Let $|G|=p$ with $p$ prime. Prove $G$ is cyclic; in fact $G=\langle x\rangle$ for \emph{any} $x\ne1$.
\wrec ``Prime order'' plus ``is it cyclic'' points to Prop.~\ref{p:ordgen@c2}: a nonidentity element generates a subgroup whose size is $\ord{x}$, and the only divisors of a prime are $1$ and $p$. (Here we use Lagrange: $\ord{\langle x\rangle}\mid|G|$.)
\wsol Since $p\ge2$, pick $x\in G$ with $x\ne1$. Let $H=\langle x\rangle$. By Lagrange's theorem $|H|=\ord{\langle x\rangle}$ divides $|G|=p$, so $|H|\in\{1,p\}$. But $x\ne1$ gives $\{1,x\}\subseteq H$, so $|H|\ge2$, ruling out $|H|=1$. Therefore $|H|=p=|G|$, and since $H\subseteq G$ with equal finite cardinality, $H=G$. Thus $G=\langle x\rangle$ is cyclic, and by Prop.~\ref{p:ordgen@c2} $\ord{x}=p$. \textit{Check.} $G=Z_5=\mathbb{Z}/(5)\mathbb{Z}$; any nonzero element, say $2$, generates: $2,4,6\equiv1,8\equiv3,10\equiv0$, i.e. $\langle 2\rangle=\{0,2,4,1,3\}=\mathbb{Z}/5\mathbb{Z}$. By Theorem~\ref{t:classify@c2}, every group of order $p$ is isomorphic to $Z_p$.
\end{wex}

