\begin{proposition}\label{p:orderpower@c2}
Let $x$ be an element of a group $G$ and let $a\in\mathbb{Z}$.
\begin{enumerate}
\item If $\ord{x}=n<\infty$, then $\ord{x^a}=\dfrac{n}{\gcd(n,a)}$.
\item If $\ord{x}=\infty$ and $a\neq 0$, then $\ord{x^a}=\infty$.
\end{enumerate}
\end{proposition}

\begin{proof}
(1) Write $d=\gcd(n,a)$, and set $a=d a'$, $n=d n'$ with $\gcd(a',n')=1$. We claim $\ord{x^a}=n'=n/d$. First, $(x^a)^{n'}=x^{a n'}=x^{d a' n'}=x^{a' n}=(x^n)^{a'}=1^{a'}=1$, so $\ord{x^a}$ divides $n'$. Conversely, suppose $(x^a)^k=1$, i.e. $x^{ak}=1$. Since $\ord{x}=n$, this forces $n\st ak$, that is $d n'\st d a' k$, hence $n'\st a' k$. As $\gcd(a',n')=1$, Euclid's lemma gives $n'\st k$. Thus every $k$ killing $x^a$ is a multiple of $n'$, so $\ord{x^a}=n'=n/d$.

\noindent(2) Suppose $\ord{x}=\infty$ and $a\neq 0$. If $(x^a)^k=x^{ak}=1$ for some $k>0$, then $ak\neq 0$ would be a positive or negative integer with $x^{ak}=1$, contradicting that no nonzero power of $x$ is the identity. Hence no positive $k$ works and $\ord{x^a}=\infty$.
\end{proof}

\begin{remark}
The factor that shrinks the order is $\gcd(n,a)$, \emph{not} $a$. Powering by $a$ ``uses up'' only the part of $a$ that overlaps $n$; the coprime part $a'$ is invisible to the order because it is a unit modulo $n'$.
\end{remark}

\begin{method}{Compute the order of a power $x^a$ when $\ord{x}=n$ is known}
\textit{Recognition trigger.} Use this whenever you must find the order of a power of an element \emph{whose own order you already know} -- e.g. $\ord{x^a}$ with $\ord{x}=n$ given, $\ord{\overline a}$ in $\mathbb{Z}/(n)\mathbb{Z}$ (here the ``base'' is $\overline 1$ with order $n$ and $\overline a=a\cdot\overline 1$), or $\ord{r^a}$ in $D_{2n}$ with $\ord{r}=n$. Also for $\ord{\sigma^a}$ where $\sigma$ is a single $n$-cycle in $S_m$.
\begin{enumerate}
\item Identify $n=\ord{x}$ (the order of the \emph{base}) and the exponent $a$. In $\mathbb{Z}/(n)\mathbb{Z}$, the operation is addition, so $x^a$ means the element $\overline a=\underbrace{\overline 1+\cdots+\overline 1}_{a}$ and $n$ is the modulus.
\item Compute $d=\gcd(n,a)$ (Euclidean algorithm).
\item Output $\ord{x^a}=n/d$.
\item \textit{Check.} Verify $d\st n$ so the answer is an integer, and confirm $(x^a)^{n/d}=x^{an/d}=x^{(a/d)n}=1$ since $d\st a$.
\end{enumerate}
\end{method}

\begin{pitfall}
Do \textbf{not} answer $n/a$. The shrink factor is $\gcd(n,a)$, never $a$ alone. E.g. $\ord{\overline 8}$ in $\mathbb{Z}/(12)\mathbb{Z}$ is $12/\gcd(12,8)=12/4=3$, not $12/8$ (which is not even an integer). Only when $a\st n$ \emph{and} $\gcd(n,a)=a$ do $n/a$ and $n/\gcd(n,a)$ coincide.
\end{pitfall}

\begin{remark}
The map $a\mapsto n/\gcd(n,a)$ shows the possible orders of elements of a cyclic group $\langle x\rangle$ of order $n$ are exactly the divisors of $n$: as $\gcd(n,a)$ ranges over the divisors $d\st n$, the order $n/d$ ranges over all divisors of $n$. The next diagram shows this for $n=12$: each subgroup $\langle x^d\rangle=\langle x^{n/(n/d)}\rangle$ has order $n/d$, and the lattice of subgroups of $\langle x\rangle$ mirrors the divisor lattice of $12$.
\end{remark}

