\begin{definition}\label{d:generator@c2}
Let $G$ be a group and $x\in G$. We say $x$ \emph{generates} $G$, and call $x$ a \emph{generator}, if $G=\langle x\rangle=\{x^k : k\in\mathbb{Z}\}$. A group with at least one generator is \emph{cyclic}.
\end{definition}

