\begin{proposition} 
Let $G=\langle x\rangle$ be cyclic and let $a\inZ$.
\begin{enumerate}
\item If $\ord{x}=n<\infty$, then $\langle x^a\rangle=\langle x\rangle$ if and only if $\gcd(a,n)=1$. Consequently the number of generators of $G$ equals $\varphi(n)$, the count of residues in $\{1,2,\dots,n\}$ coprime to $n$.
\item If $\ord{x}=\infty$, then $\langle x^a\rangle=\langle x\rangle$ if and only if $a=\pm1$. Thus an infinite cyclic group has exactly two generators, $x$ and $x^{-1}$.
\end{enumerate}
\end{proposition}

