\begin{proposition}\label{p:gens@c2}
Let $G=\langle x\rangle$ be cyclic and let $a\in\mathbb{Z}$.
\begin{enumerate}
\item If $\ord{x}=n<\infty$, then $\langle x^a\rangle=\langle x\rangle$ if and only if $\gcd(a,n)=1$. Consequently the number of generators of $G$ equals $\varphi(n)$, the count of residues in $\{1,2,\dots,n\}$ coprime to $n$.
\item If $\ord{x}=\infty$, then $\langle x^a\rangle=\langle x\rangle$ if and only if $a=\pm1$. Thus an infinite cyclic group has exactly two generators, $x$ and $x^{-1}$.
\end{enumerate}
\end{proposition}

\begin{proof}
\textbf{(1)} Recall the order formula: for $\ord{x}=n$, one has $\ord{x^a}=n/\gcd(a,n)$, so $\bigl|\langle x^a\rangle\bigr|=n/\gcd(a,n)$. Now $\langle x^a\rangle=\langle x\rangle$ iff these subgroups have equal order, i.e.\ iff $n/\gcd(a,n)=n$, i.e.\ iff $\gcd(a,n)=1$.

For the count: every element of $G=\langle x\rangle$ is $x^a$ for a unique residue $a\in\{0,1,\dots,n-1\}$, and $x^a$ is a generator iff $\gcd(a,n)=1$. The number of such $a$ is by definition $\varphi(n)$. (Equivalently, working in $\mathbb{Z}/(n)\mathbb{Z}$, the generators are exactly the units $(\mathbb{Z}/(n)\mathbb{Z})^{\times}$.)

\textbf{(2)} Suppose $\ord{x}=\infty$, so the map $k\mapsto x^k$ is injective and $\langle x^a\rangle=\{x^{ak}:k\in\mathbb{Z}\}=\{x^m : m\in a\mathbb{Z}\}$. Then $\langle x^a\rangle=\langle x\rangle$ iff $a\mathbb{Z}=\mathbb{Z}$ iff $a$ is a unit of $\mathbb{Z}$, i.e.\ $a=\pm1$. Since $x\ne x^{-1}$ here (else $x^2=1$, contradicting infinite order), there are exactly two generators.
\end{proof}

\begin{remark}\label{r:zn@c2}
The model case is $G=\mathbb{Z}/(n)\mathbb{Z}=\langle \overline1\rangle$ under addition, where $x=\overline1$ and ``$x^a$'' becomes ``$a\cdot\overline1=\overline a$.'' Proposition~\ref{p:gens@c2}(1) then reads: $\overline a$ generates $\mathbb{Z}/(n)\mathbb{Z}$ iff $\gcd(a,n)=1$. So the generators of $\mathbb{Z}/(n)\mathbb{Z}$ are precisely the residues coprime to $n$, and there are $\varphi(n)$ of them.
\end{remark}

\begin{method}{Find all generators of a cyclic group of order $n$ (and count them)}
\textit{Trigger.} Use this whenever you must list/count generators of $\mathbb{Z}/(n)\mathbb{Z}$, or decide which $x^a$ generate a cyclic group $\langle x\rangle$ with $\ord{x}=n$.
\begin{enumerate}
\item Identify $n=\ord{x}$ (for $\mathbb{Z}/(n)\mathbb{Z}$, $n$ is the modulus).
\item A power $x^a$ (resp.\ residue $\overline a$) is a generator $\Longleftrightarrow \gcd(a,n)=1$. List all $a\in\{1,2,\dots,n\}$ (or $\{0,\dots,n-1\}$) with $\gcd(a,n)=1$.
\item The \emph{number} of generators is $\varphi(n)$. To compute $\varphi(n)$ fast, factor $n=p_1^{e_1}\cdots p_r^{e_r}$ and use
\[
\varphi(n)=\prod_{i=1}^{r}\bigl(p_i^{e_i}-p_i^{e_i-1}\bigr)=n\prod_{i=1}^{r}\Bigl(1-\tfrac1{p_i}\Bigr).
\]
\item Sanity check: $\varphi(n)$ should equal the length of the list from step 2.
\end{enumerate}
\end{method}

\begin{method}{Compute $\varphi(n)$ from the prime factorization}
\textit{Trigger.} You need the \emph{count} of generators/units mod $n$ but listing them is impractical.
\begin{enumerate}
\item Factor $n=p_1^{e_1}\cdots p_r^{e_r}$ into distinct primes.
\item For each prime power use $\varphi(p^e)=p^e-p^{e-1}=p^{e-1}(p-1)$.
\item Multiply: $\varphi$ is multiplicative on coprime factors, so $\varphi(n)=\prod_i\varphi(p_i^{e_i})$.
\item Special case worth memorizing: $\varphi(p)=p-1$ for $p$ prime.
\end{enumerate}
\end{method}

\begin{pitfall}
$\gcd(a,n)=1$ is required, \emph{not} ``$a$ is prime'' and \emph{not} ``$a<n$.'' E.g.\ $\overline9$ generates $\mathbb{Z}/(10)\mathbb{Z}$ (since $\gcd(9,10)=1$) even though $9$ is composite, while $\overline2,\overline4,\overline6,\overline8$ do not. Always test the gcd, never primality.
\end{pitfall}

