\begin{theorem}[Subgroups of a cyclic group, D\&F 2.3 Thm.\ 7]\label{t:cycsub@c2}
Let $H=\langle x\rangle$ be cyclic.
\begin{enumerate}
\item Every subgroup of $H$ is cyclic. More precisely, if $K\sgr H$ and $K\neq\{1\}$, then $K=\langle x^d\rangle$ where $d$ is the smallest positive integer with $x^d\in K$.
\item If $\ord x=\infty$, then the distinct subgroups are $\langle x^d\rangle$ for $d=0,1,2,\dots$, all distinct.
\item If $\ord x=n<\infty$, then for each positive divisor $d\mid n$ there is a \emph{unique} subgroup of order $d$, namely $\langle x^{n/d}\rangle$. These are all of the subgroups, so the subgroups of $\langle x\rangle$ correspond bijectively to the positive divisors of $n$.
\end{enumerate}
\end{theorem}

\begin{proof}
(1) Let $K\sgr\langle x\rangle$. If $K=\{1\}=\langle x^0\rangle$ we are done; otherwise pick the least positive $d$ with $x^d\in K$ (such $d$ exists by well-ordering). Then $\langle x^d\rangle\sgr K$. Conversely take any $x^a\in K$ and divide: $a=qd+r$ with $0\le r<d$. Then $x^r=x^a(x^d)^{-q}\in K$, and minimality of $d$ forces $r=0$, so $x^a=(x^d)^q\in\langle x^d\rangle$. Hence $K=\langle x^d\rangle$ is cyclic.

(2) If $\ord x=\infty$ and $\langle x^d\rangle=\langle x^e\rangle$ with $d,e>0$, then $x^d=x^{ek}$ for some $k$, so $d=ek$, i.e.\ $e\mid d$, and symmetrically $d\mid e$, giving $d=e$; also $\langle x^0\rangle=1$ differs from every $\langle x^e\rangle$ with $e>0$, since $x^e\ne1$. Distinct $d$ give distinct subgroups, and by (1) every subgroup is some $\langle x^d\rangle$.

(3) Now $\ord x=n$. By the order formula $\ord{x^k}=n/\gcd(k,n)$. For $d\mid n$, set $k=n/d$; then $\gcd(n/d,n)=n/d$, so $\ord{x^{n/d}}=n/(n/d)=d$, giving a subgroup of order $d$. For uniqueness, suppose $K\sgr\langle x\rangle$ has $|K|=d$. By (1) $K=\langle x^m\rangle$ with $m$ the least positive exponent in $K$; the same minimality argument as in (1) shows $m\mid n$ (divide $n$ by $m$: $x^n=1\in K$ forces remainder $0$). Then $|K|=\ord{x^m}=n/\gcd(m,n)=n/m=d$, so $m=n/d$ and $K=\langle x^{n/d}\rangle$. Thus the subgroup of order $d$ is unique. Finally every subgroup has order dividing $n$ (Lagrange), so $d\mapsto\langle x^{n/d}\rangle$ is a bijection from divisors of $n$ to subgroups.
\end{proof}

\begin{proposition}[The $\gcd$ collapse and the containment rule]\label{p:gcd@c2}
Let $\ord x=n$ and write everything multiplicatively (additively in $\mathbb{Z}/(n)\mathbb{Z}$ this is $\overline a$).
\begin{enumerate}
\item $\langle x^a\rangle=\langle x^{\gcd(a,n)}\rangle$, and this subgroup has order $n/\gcd(a,n)$.
\item $\langle x^a\rangle\sgr\langle x^b\rangle\iff \gcd(b,n)\mid\gcd(a,n)$. Equivalently, writing $|\langle x^a\rangle|=n/\gcd(a,n)$, containment of the smaller into the larger matches divisibility of orders.
\end{enumerate}
\end{proposition}

\begin{proof}
(1) Let $g=\gcd(a,n)$. Since $g\mid a$, $x^a\in\langle x^g\rangle$, so $\langle x^a\rangle\sgr\langle x^g\rangle$. Conversely Bezout gives $g=au+nv$, hence $x^g=(x^a)^u(x^n)^v=(x^a)^u\in\langle x^a\rangle$, so $\langle x^g\rangle\sgr\langle x^a\rangle$. Thus they are equal; the order is $\ord{x^g}=n/\gcd(g,n)=n/g$ since $g\mid n$.

(2) By (1) we may assume $a=\gcd(a,n)$ and $b=\gcd(b,n)$ are divisors of $n$. Then $\langle x^a\rangle\sgr\langle x^b\rangle$ iff $x^a\in\langle x^b\rangle$ iff $x^a=x^{bk}$ for some $k$ iff $n\mid a-bk$ for some $k$ iff $\gcd(b,n)=b\mid a=\gcd(a,n)$ (the last by elementary number theory, since $b\mid n$). Note $\langle x^a\rangle\sgr\langle x^b\rangle$ means the $a$-subgroup is contained in the $b$-subgroup; as $|\langle x^a\rangle|=n/a$ and $|\langle x^b\rangle|=n/b$, $b\mid a$ says $n/a\mid n/b$, i.e.\ the order of the contained group divides the order of the container.
\end{proof}

\begin{remark}
Translation to $\mathbb{Z}/(n)\mathbb{Z}$ (additive): $x^k$ becomes $\overline k=k\cdot\overline 1$, the subgroup $\langle x^{n/d}\rangle$ becomes $\langle \overline{n/d}\rangle=\{0,\,n/d,\,2(n/d),\dots\}$, and the order formula reads $\ord{\overline k}=n/\gcd(k,n)$. The collapse is $\langle \overline a\rangle=\langle \overline{\gcd(a,n)}\rangle$.
\end{remark}

\begin{method}{List ALL subgroups of $\mathbb{Z}/(n)\mathbb{Z}$ (and draw the lattice)}
\textit{Recognition trigger.} The group is cyclic of finite order $n$ (e.g.\ $\mathbb{Z}/(n)\mathbb{Z}$, or any $\langle x\rangle$ with $\ord x=n$), and you must enumerate subgroups, find a specific subgroup of a given order, or decide a containment.
\begin{enumerate}
\item \textbf{Find the divisors} $d_1<d_2<\dots$ of $n$. There is exactly one subgroup per divisor, so $\#\text{subgroups}=\#\text{divisors of }n=\tau(n)$.
\item \textbf{Order $\to$ generator.} The unique subgroup of order $d$ is $\langle \overline{n/d}\rangle$ (the cyclic span of the step $n/d$). Its elements are the multiples of $n/d$ in $\mathbb{Z}/(n)\mathbb{Z}$.
\item \textbf{Generator $\to$ order.} For an arbitrary $\overline a$, first collapse: $\langle \overline a\rangle=\langle \overline{\gcd(a,n)}\rangle$, and $\ord{\overline a}=n/\gcd(a,n)$.
\item \textbf{Containment.} $\langle \overline a\rangle\sgr\langle \overline b\rangle\iff \gcd(b,n)\mid\gcd(a,n)$. Equivalently $|\langle \overline a\rangle|\,\big|\,|\langle \overline b\rangle|$ (smaller order sits inside larger order).
\item \textbf{Lattice.} Draw the divisor lattice of $n$ \emph{upside down}, with $\langle \overline s\rangle$ at the divisor $s$: $\mathbb{Z}/(n)\mathbb{Z}=\langle \overline 1\rangle$ (order $n$) goes on top, $\{0\}=\langle \overline n\rangle$ (order $1$) at the bottom; an edge goes between two subgroups when one order divides the other with prime index.
\end{enumerate}
\end{method}

\begin{pitfall}
The subgroup of order $d$ is $\langle \overline{n/d}\rangle$, NOT $\langle \overline d\rangle$. Mixing these up is the single most common error: in $\mathbb{Z}/(12)\mathbb{Z}$ the order-$3$ subgroup is $\langle \overline 4\rangle=\{0,4,8\}$, while $\langle \overline 3\rangle=\{0,3,6,9\}$ has order $4$. Always convert via $d\leftrightarrow n/d$.
\end{pitfall}

\begin{pitfall}
The containment direction is reversed from divisibility of the \emph{generators-as-steps}: a \emph{smaller} step $n/d$ generates a \emph{larger} subgroup. Trust the order test: $\langle \overline a\rangle\sgr\langle \overline b\rangle$ exactly when $|\langle \overline a\rangle|$ divides $|\langle \overline b\rangle|$ (a smaller order alone is not enough: in $\mathbb{Z}/(12)\mathbb{Z}$, $\langle \overline 4\rangle$ of order $3$ is not inside $\langle \overline 3\rangle$ of order $4$), and you check it via $\gcd(b,n)\mid\gcd(a,n)$.
\end{pitfall}

