\begin{remark}\label{r:notequal-mrg@c2}
``Isomorphic'' is not ``equal.'' Theorem~\ref{t:classify@c2} says any two cyclic groups of the same order are isomorphic, but they may be genuinely different groups sitting in different ambient sets. For instance $\langle (1\,2\,3)\rangle\sgr S_3$, $\mu_3\sgr\mathbb{C}^\times$, and $\mathbb{Z}/(3)\mathbb{Z}$ are three distinct cyclic groups of order $3$; all are isomorphic to $Z_3$, none is literally another. The isomorphism $x^a\mapsto y^a$ of Theorem~\ref{t:classify@c2} is what carries computations from one model to another.
\end{remark}

\begin{proposition}[Order is inversion- and conjugation-invariant]\label{p:orderinv-mrg@c2}
Let $x,y,g$ be elements of a group $G$.
\begin{enumerate}
\item $\ord{x}=\ord{x^{-1}}$.
\item $\ord{gxg^{-1}}=\ord{x}$, and more generally $\ord{xy}=\ord{yx}$.
\end{enumerate}
\end{proposition}

\begin{proof}
(1) Since $(x^{-1})^n=(x^n)^{-1}$, we have $x^n=1\Longleftrightarrow(x^{-1})^n=1$; the two elements are killed by exactly the same exponents, hence have the same order (this also reproves $\langle x\rangle=\langle x^{-1}\rangle$).

(2) Since $(gxg^{-1})^n=gx^ng^{-1}$, we have $(gxg^{-1})^n=1\Longleftrightarrow x^n=1$, giving $\ord{gxg^{-1}}=\ord{x}$. For the last claim, $yx=x^{-1}(xy)x$ is a conjugate of $xy$, so $\ord{xy}=\ord{x^{-1}(xy)x}=\ord{yx}$.
\end{proof}

\begin{proposition}[Order of a product of commuting elements of coprime order]\label{p:coprimeprod-mrg@c2}
Let $x,y$ be elements of a group with $xy=yx$, $\ord{x}=m<\infty$, $\ord{y}=n<\infty$, and $\gcd(m,n)=1$. Then $\ord{xy}=mn$, and $\langle x,y\rangle=\langle xy\rangle$ is cyclic of order $mn$.
\end{proposition}

\begin{proof}
Since $x,y$ commute, $(xy)^{mn}=x^{mn}y^{mn}=(x^m)^n(y^n)^m=1$, so $\ord{xy}\mid mn$. Let $k=\ord{xy}$, so $x^ky^k=1$, i.e.\ $x^k=y^{-k}$. Then $x^{kn}=(x^k)^n=(y^{-k})^n=(y^n)^{-k}=1$, so $m\mid kn$; as $\gcd(m,n)=1$ this forces $m\mid k$. Symmetrically $n\mid k$, and $\gcd(m,n)=1$ gives $mn\mid k$. Hence $k=mn$ and $\langle xy\rangle$ has order $mn$.

For $\langle x,y\rangle=\langle xy\rangle$: the inclusion $\langle xy\rangle\sgr\langle x,y\rangle$ is clear. Conversely, $(xy)^m=x^my^m=y^m$, and by Proposition~\ref{p:orderpower@c2} $\ord{y^m}=n/\gcd(n,m)=n$, so $\langle (xy)^m\rangle=\langle y^m\rangle=\langle y\rangle$ and thus $y\in\langle xy\rangle$. Likewise $(xy)^n=x^n$ has order $m/\gcd(m,n)=m$, so $x\in\langle xy\rangle$. Hence $\langle x,y\rangle\sgr\langle xy\rangle$, giving equality.
\end{proof}

\begin{wex}{The infinite cyclic group $\langle r\rangle$ inside a rotation group}
Let $r$ be ``rotation of the plane about the origin by $1$ radian'' inside the group $G$ of rotations about the origin (composition). Show $\langle r\rangle$ is infinite cyclic, and contrast with rotation by a rational multiple of $\pi$.
\wrec ``All powers of one element'' triggers Definition~\ref{d:cyclic@c2}; deciding finite vs.\ infinite is exactly Proposition~\ref{p:ordgen@c2}, i.e.\ whether some positive power is the identity.
\wsol Composing $k$ copies of $r$ rotates by $k$ radians, the identity element being rotation by $0$. Then $r^k=1$ iff $k$ is an integer multiple of $2\pi$. But $k$ is itself a positive integer and $2\pi$ is irrational, so $k=2\pi\cdot(\text{integer})$ is impossible for $k\ne 0$. Hence no positive power of $r$ is the identity: $\ord{r}=\infty$ and $\langle r\rangle\cong\mathbb{Z}$ by Theorem~\ref{t:classify@c2}. \emph{Contrast:} if instead $\rho$ is rotation by $2\pi/n$, then $\rho^n=1$ and $\ord{\rho}=n$, so $\langle \rho\rangle=\mu_n\cong Z_n$ is finite. \textit{Check.} The dividing line is rationality of (angle)$/2\pi$ --- rational gives a finite cyclic group, irrational gives the infinite one, matching Proposition~\ref{p:ordgen@c2}.
\end{wex}

\begin{wex}{Cyclic or not: $\mathbb{Z}/(8)\mathbb{Z}$, $V_4$, and is $\mathbb{Z}/(8)\mathbb{Z}\cong\mathbb{Z}/(9)\mathbb{Z}$?}
Decide whether $\mathbb{Z}/(8)\mathbb{Z}$ and $V_4=\mathbb{Z}/(2)\mathbb{Z}\times\mathbb{Z}/(2)\mathbb{Z}$ are cyclic, and whether $\mathbb{Z}/(8)\mathbb{Z}\cong\mathbb{Z}/(9)\mathbb{Z}$.
\wrec ``Is it cyclic'' and ``are these two isomorphic'' both reduce to the order of a generator (Prop.~\ref{p:ordgen@c2}) and the classification (Thm.~\ref{t:classify@c2}); equal order is necessary for isomorphism, and an element of order $|G|$ is necessary for cyclic.
\wsol $\mathbb{Z}/(8)\mathbb{Z}=\langle \overline 1\rangle$ has the order-$8$ element $\overline 1$, so it is cyclic of order $8$ ($\cong Z_8$). The Klein group $V_4$ has order $4$, and every nonidentity element satisfies $g^2=1$, so the largest order present is $2<4$: by Proposition~\ref{p:ordgen@c2} no element generates, hence $V_4$ is \emph{not} cyclic (reinforcing the earlier pitfall: abelian $\not\Rightarrow$ cyclic). Finally $\mathbb{Z}/(8)\mathbb{Z}\cong\mathbb{Z}/(9)\mathbb{Z}$ is \emph{false} on sight: $\ord{\mathbb{Z}/(8)\mathbb{Z}}=8\ne 9=\ord{\mathbb{Z}/(9)\mathbb{Z}}$, and isomorphic groups have equal order. \textit{Check.} Both $\mathbb{Z}/(8)\mathbb{Z}$ and $\mathbb{Z}/(9)\mathbb{Z}$ \emph{are} cyclic (each has a generator of full order), so they are isomorphic to $Z_8$ and $Z_9$ respectively --- isomorphic to each other only if $8=9$, which fails.
\end{wex}

\begin{remark}\label{r:countphi-mrg@c2}
The last example exhibits the general count: in a cyclic group of order $n$, the number of elements of order $d$ (for each $d\mid n$) is $\varphi(d)$, and $\sum_{d\mid n}\varphi(d)=n$. Each such element generates the unique subgroup of order $d$ (Theorem~\ref{t:cycsub@c2}(3)), so ``elements of order $d$'' $=$ ``generators of the order-$d$ subgroup,'' of which there are $\varphi(d)$ by Proposition~\ref{p:gens@c2}.
\end{remark}

\begin{wex}{$\ord{\overline{18}}$ in $\mathbb{Z}/(30)\mathbb{Z}$}
\wrec Order of a power in a cyclic group, $n=30$, $a=18$.
\wsol $\gcd(30,18)=6$, so $\ord{\overline{18}}=30/6=5$. \textit{Check.}
$5\cdot\overline{18}=\overline{90}=\overline0$, and no smaller positive multiple is $0$.
\end{wex}

\begin{wex}{$\ord{x^9}$ when $\ord{x}=24$}
\wrec Order of a power, $n=24$, $a=9$. ($24/9$ is not an integer --- a flag to use
$\gcd$.)
\wsol $\gcd(24,9)=3$, so $\ord{x^9}=24/3=8$. \textit{Check.} $(x^9)^8=x^{72}=(x^{24})^3=1$,
and $(x^9)^4=x^{36}=x^{12}\neq1$.
\end{wex}

\begin{wex}{$\ord{(1\,2\,3\,4\,5\,6\,7)^3}$ in $S_7$}
\wrec A $7$-cycle $\sigma$ has order $7$ (prime); order of the power $\sigma^3$ with
$n=7$, $a=3$.
\wsol $\gcd(7,3)=1$, so $\ord{\sigma^3}=7/1=7$. \textit{Check.} For prime order every
nonidentity power has the same order $7$.
\end{wex}

\begin{wex}{all generators of $\mathbb{Z}/(14)\mathbb{Z}$}
\wrec Generators of $\mathbb{Z}/(n)\mathbb{Z}$ are the residues coprime to $n$; here $n=14=2\cdot7$.
\wsol $\gcd(a,14)=1$ for $a\in\{1,3,5,9,11,13\}$, so these are the generators; there are
$\varphi(14)=\varphi(2)\varphi(7)=1\cdot6=6$ of them.
\end{wex}

\begin{wex}{the number of generators of $\mathbb{Z}/(360)\mathbb{Z}$}
\wrec Count generators $=\varphi(n)$; use the prime factorization $360=2^3\cdot3^2\cdot5$.
\wsol $\varphi(360)=\varphi(2^3)\varphi(3^2)\varphi(5)=(8-4)(9-3)(4)=4\cdot6\cdot4=96$. So
$\mathbb{Z}/(360)\mathbb{Z}$ has $96$ generators.
\end{wex}

