\begin{wex}{combining two relations}
Suppose $x^{24}=1$ and $x^{36}=1$. What does this force about $\ord{x}$?
\wrec Two vanishing powers; the gcd lemma says $x^{\gcd(m,n)}=1$.
\wsol $\gcd(24,36)=12$, so $x^{12}=1$ and therefore $\ord{x}\mid12$. \textit{Check.}
$12\mid24$ and $12\mid36$, consistent; e.g.\ an element of order exactly $12$ realizes
both relations.
\end{wex}

\begin{proposition}\label{p:int-sub@c2}
Let $G$ be a group and let $\{H_i\}_{i\in I}$ be a nonempty collection of subgroups of $G$. Then $K=\bigcap_{i\in I}H_i$ is a subgroup of $G$.
\end{proposition}

\begin{proof}
Use the subgroup criterion (nonempty; closed under $xy^{-1}$). Each $H_i\sgr G$ contains $1$, so $1\in H_i$ for every $i$, hence $1\in K$ and $K\neq\varnothing$. Now take $x,y\in K$. For each $i$ we have $x,y\in H_i$, and since $H_i$ is a subgroup, $xy^{-1}\in H_i$. As this holds for every $i$, we get $xy^{-1}\in\bigcap_i H_i=K$. By the one-step subgroup test, $K\sgr G$.
\end{proof}

\begin{pitfall}
The same argument fails for \emph{unions}: $\langle 2\rangle\cup\langle 3\rangle$ in $\mathbb{Z}$ contains $2$ and $3$ but not $2+3=5$, so it is not a subgroup. Intersections of subgroups are always subgroups; unions almost never are.
\end{pitfall}

\begin{proof}
In an abelian group we may sort the letters of any word and collect repeats: a word in $a_1,\dots,a_n$ and their inverses can be rearranged (commutativity) into $a_1$'s together, then $a_2$'s, and so on, and each block of $m_i$ copies of $a_i^{\pm1}$ sums to $m_ia_i$ with $m_i\in\mathbb{Z}$. Conversely each integer combination is visibly such a word. The result follows from Theorem~\ref{t:words@c2}.
\end{proof}

\begin{theorem}[The case $G=\mathbb{Z}$]\label{t:Zgcd@c2}
For integers $a,b$ not both $0$, in $(\mathbb{Z},+)$ we have $\langle a,b\rangle=\langle \gcd(a,b)\rangle=\gcd(a,b)\,\mathbb{Z}$. More generally $\langle a_1,\dots,a_n\rangle=\langle \gcd(a_1,\dots,a_n)\rangle$.
\end{theorem}

\begin{proof}
Let $d=\gcd(a,b)$. By Corollary~\ref{c:abelian@c2}, $\langle a,b\rangle=\{ma+nb\st m,n\in\mathbb{Z}\}$. Since $d\mid a$ and $d\mid b$, every $ma+nb$ is a multiple of $d$, so $\langle a,b\rangle\subseteq d\mathbb{Z}=\langle d\rangle$. Conversely, by B\'ezout there exist $m_0,n_0\in\mathbb{Z}$ with $m_0a+n_0b=d$, so $d\in\langle a,b\rangle$, hence $\langle d\rangle=d\mathbb{Z}\subseteq\langle a,b\rangle$. Therefore $\langle a,b\rangle=\langle d\rangle$. Induction on $n$ (using $\gcd(a_1,\dots,a_n)=\gcd(\gcd(a_1,\dots,a_{n-1}),a_n)$) gives the general statement.
\end{proof}

\begin{method}{How to compute $\langle A\rangle$ by hand (word closure)}
Use this whenever you see ``$\langle \,\cdot\,\rangle$,'' ``the subgroup generated by,'' or ``smallest subgroup containing.''
\begin{enumerate}
\item \textbf{Seed.} Start the candidate set $S$ with $1$, every generator $a\in A$, and every inverse $a^{-1}$.
\item \textbf{Close under products.} Multiply pairs from $S$ (in both orders if $G$ is nonabelian) and adjoin any new elements. Repeat until $S$ stops growing. Finiteness of $G$ (or a known order bound) guarantees this halts.
\item \textbf{Read off the subgroup.} The stabilized $S$ \emph{is} $\langle A\rangle$, by Theorem~\ref{t:words@c2}.
\item \textbf{Identify it.} Compute $\lvert S\rvert$, check whether it is abelian, and match against a known group ($V_4$, $\mathbb{Z}_n$, $S_3$, $Q_8$, $\dots$). If $\lvert S\rvert=\lvert G\rvert$ then $\langle A\rangle=G$.
\item \textit{Shortcuts.} In an abelian group, replace words by integer combinations (Cor.~\ref{c:abelian@c2}); in $\mathbb{Z}$ use $\langle a,b\rangle=\langle \gcd(a,b)\rangle$ (Thm.~\ref{t:Zgcd@c2}); in $\mathbb{Z}/(n)\mathbb{Z}$ use $\langle \overline a,\overline b\rangle=\langle \overline{\gcd(a,b,n)}\rangle$.
\end{enumerate}
\textbf{Recognizing $\langle A\rangle=G$:} it suffices that the generators reach an element of order $\lvert G\rvert$ (cyclic case), or that the closure already exhausts a known basis/generating pattern of $G$.
\end{method}

\begin{wex}{$\langle 2,3\rangle=\mathbb{Z}$}
Show that $2$ and $3$ generate all of $\mathbb{Z}$.
\wrec Ambient group is $\mathbb{Z}$ (abelian, additive). The trigger ``$\langle a,b\rangle$ in $\mathbb{Z}$'' fires Theorem~\ref{t:Zgcd@c2}: the answer is $\langle \gcd(a,b)\rangle$. Compute the gcd.
\wsol By Theorem~\ref{t:Zgcd@c2}, $\langle 2,3\rangle=\langle \gcd(2,3)\rangle=\langle 1\rangle=1\cdot\mathbb{Z}=\mathbb{Z}$. Explicit B\'ezout witness: $(-1)\cdot2+(1)\cdot3=1$, so $1\in\langle 2,3\rangle$; once $1$ is present, every integer $m=m\cdot1\in\langle 2,3\rangle$.
\textit{Check.} $\gcd(2,3)=1$ and $\langle 1\rangle=\mathbb{Z}$, consistent. Also $5=3+2$, $4=2+2$, $-1=2-3$ are all reachable, as expected.
\end{wex}

\begin{wex}{$\langle 4,6\rangle=2\mathbb{Z}$}
Compute $\langle 4,6\rangle$ in $\mathbb{Z}$.
\wrec Same trigger as the previous example: a two-generator subgroup of $(\mathbb{Z},+)$. Apply $\langle a,b\rangle=\langle \gcd(a,b)\rangle$.
\wsol $\gcd(4,6)=2$, so $\langle 4,6\rangle=\langle 2\rangle=2\mathbb{Z}=\{\dots,-4,-2,0,2,4,\dots\}$. B\'ezout witness for $2$: $(-1)\cdot4+(1)\cdot6=2$, so $2\in\langle 4,6\rangle$, giving $2\mathbb{Z}\subseteq\langle 4,6\rangle$. Conversely every $4m+6n=2(2m+3n)$ is even, so $\langle 4,6\rangle\subseteq2\mathbb{Z}$.
\textit{Check.} Both generators are even, so no odd number can appear --- $1\notin\langle 4,6\rangle$, matching $\langle 4,6\rangle=2\mathbb{Z}\neq\mathbb{Z}$. And $2=6-4\in\langle 4,6\rangle$, confirming $2$ is attained.
\end{wex}

\begin{wex}{$\langle \overline4,\overline6\rangle=\langle \overline2\rangle$ in $\mathbb{Z}/(12)\mathbb{Z}$}
Find $\langle \overline4,\overline6\rangle$ inside $\mathbb{Z}/(12)\mathbb{Z}$.
\wrec Ambient group is $\mathbb{Z}/(12)\mathbb{Z}$ (abelian, additive mod $12$). For $\mathbb{Z}/(n)\mathbb{Z}$ the gcd rule must include the modulus: $\langle \overline a,\overline b\rangle=\langle \overline{\gcd(a,b,n)}\rangle$, because adding the relation $n\equiv 0$ is the same as throwing $n$ into the gcd.
\wsol Compute $\gcd(4,6,12)=\gcd(\gcd(4,6),12)=\gcd(2,12)=2$. Hence $\langle \overline4,\overline6\rangle=\langle \overline2\rangle=\{\overline0,\overline2,\overline4,\overline6,\overline8,\overline{10}\}$, a subgroup of order $6$. Word/integer-combination check that $\overline2$ is reachable: $\overline6-\overline4=\overline2$. And $\overline2$ generates the listed set by repeated addition.
\textit{Check.} $\lvert\langle \overline2\rangle\rvert=12/\gcd(2,12)=12/2=6$, matching the six listed residues. Every generator lies in it: $\overline4=2\cdot\overline2$, $\overline6=3\cdot\overline2$. Good.
\end{wex}

\begin{wex}{$\langle \overline3,\overline5\rangle=\mathbb{Z}/(12)\mathbb{Z}$ (tricky: coprime generators)}
Compute $\langle \overline3,\overline5\rangle$ in $\mathbb{Z}/(12)\mathbb{Z}$.
\wrec Two-generator subgroup of $\mathbb{Z}/(12)\mathbb{Z}$; use $\langle \overline a,\overline b\rangle=\langle \overline{\gcd(a,b,n)}\rangle$. The subtlety: even though $3$ alone does not generate $\mathbb{Z}/(12)\mathbb{Z}$, the gcd of the two generators with the modulus may still be $1$.
\wsol $\gcd(3,5,12)=\gcd(\gcd(3,5),12)=\gcd(1,12)=1$, so $\langle \overline3,\overline5\rangle=\langle \overline1\rangle=\mathbb{Z}/(12)\mathbb{Z}$. Explicit reach: $\overline5-\overline3=\overline2$ and $\overline3-\overline2=\overline1$, so $\overline1\in\langle \overline3,\overline5\rangle$, and $\overline1$ generates everything.
\textit{Check.} $\langle \overline3\rangle=\{\overline0,\overline3,\overline6,\overline9\}$ has order $4$ and $\langle \overline5\rangle=\mathbb{Z}/(12)\mathbb{Z}$ already (since $\gcd(5,12)=1$); so together they certainly fill $\mathbb{Z}/(12)\mathbb{Z}$. Consistent.
\end{wex}

\begin{pitfall}
In a \emph{nonabelian} group you may not reorder letters: $\langle i,j\rangle$ in $Q_8$ needs both $ij=k$ \emph{and} $ji=-k$. Skipping the reversed products (or trying to ``collect exponents'' as in the abelian case) will undercount the subgroup. Only after you prove the elements commute --- as with $\{1,r^2,s,sr^2\}$ in $D_8$ --- may you treat the closure abelianly.
\end{pitfall}

