\begin{remark}[Generated-by language and ``finitely generated'']
Beyond the notation $\langle A\rangle$ and $\langle a_1,\dots,a_n\rangle$ already fixed in Definition~\ref{d:gen@c2}, D\&F uses two phrasings throughout:
\begin{itemize}
\item \emph{$G$ is generated by $A$} (equivalently \emph{$A$ generates $G$}) means $\langle A\rangle=G$.
\item A group $G$ is called \emph{finitely generated} if $G=\langle A\rangle$ for some finite set $A$.
\end{itemize}
The single-element case $\langle x\rangle$ is exactly the cyclic subgroup studied in the previous section; the present construction is its generalization to arbitrary $A$, and the next example checks that the two uses of the symbol $\langle x\rangle$ agree.
\end{remark}

\begin{wex}{$\langle x\rangle$ recovers the cyclic subgroup}
For a single element $x\in G$ (with $G$ possibly nonabelian), verify that the word description of $\langle \{x\}\rangle$ collapses to $\{x^n\st n\in\mathbb{Z}\}$.
\wrec Single generator, $A=\{x\}$. Theorem~\ref{t:words@c2} (word description) applies: words use only the one letter $x$ and its inverse $x^{-1}$, so commutativity of the ambient group is irrelevant here.
\wsol A word $a_1^{\varepsilon_1}\cdots a_k^{\varepsilon_k}$ with every $a_i=x$ is $x^{\varepsilon_1}x^{\varepsilon_2}\cdots x^{\varepsilon_k}=x^{\varepsilon_1+\cdots+\varepsilon_k}$, an integer power of $x$. Conversely every $x^n$ ($n\in\mathbb{Z}$) is such a word: take $n$ copies of $x$ if $n>0$, of $x^{-1}$ if $n<0$, and the empty word if $n=0$. Hence $\langle \{x\}\rangle=\{x^n\st n\in\mathbb{Z}\}=\langle x\rangle$.
\textit{Check.} This matches the cyclic-subgroup meaning of $\langle x\rangle$ from the prior section, so writing $\langle x\rangle$ for both is consistent. If $\ord{x}=m<\infty$ the distinct powers are $1,x,\dots,x^{m-1}$, recovering $\lvert\langle x\rangle\rvert=\ord{x}$.
\end{wex}

\begin{wex}{$\mathbb{Z}=\langle 1\rangle$ and $\mathbb{Z}/(n)\mathbb{Z}=\langle \overline 1\rangle$}
Exhibit single generators for the basic cyclic groups $\mathbb{Z}$ and $\mathbb{Z}/(n)\mathbb{Z}$.
\wrec One generator suffices for a cyclic group; here $G$ is cyclic with a named candidate generator, so $\langle x\rangle=G$ reduces to checking that $x$ reaches every element.
\wsol In $(\mathbb{Z},+)$, every integer is $m=m\cdot 1$, an integer multiple of $1$, so $\langle 1\rangle=\{m\cdot 1\st m\in\mathbb{Z}\}=\mathbb{Z}$. In $(\mathbb{Z}/(n)\mathbb{Z},+)$, every class is $\overline m=m\cdot\overline 1$, so $\langle \overline 1\rangle=\mathbb{Z}/(n)\mathbb{Z}$.
\textit{Check.} For $\mathbb{Z}/(n)\mathbb{Z}$ this agrees with $\lvert\langle \overline 1\rangle\rvert=n/\gcd(1,n)=n=\lvert\mathbb{Z}/(n)\mathbb{Z}\rvert$. More generally $\overline a$ generates $\mathbb{Z}/(n)\mathbb{Z}$ iff $\gcd(a,n)=1$; for $n=12$ the generators are $\overline 1,\overline 5,\overline 7,\overline{11}$, the four units mod $12$.
\end{wex}

\begin{wex}{$D_{2n}=\langle r,s\rangle$}
In $D_{2n}=\langle r,s\st r^n=s^2=1,\ sr=r^{-1} s\rangle$, show that the rotation $r$ and reflection $s$ generate the whole group.
\wrec Nonabelian ambient $D_{2n}$. The defining relations name $\{r,s\}$ as a generating set, so the task is to confirm the word closure already has all $2n$ elements. The tool is the master relation $r^k s=s\,r^{-k}$, used to put every word into normal form.
\wsol Take any word in $r,s,r^{-1},s^{-1}$. Since $s^{-1}=s$, every letter is a power of $r$ or a single $s$. Using $r^k s=s\,r^{-k}$ one moves each $s$ leftward past the $r$-powers; since $s^2=1$, at most one $s$ survives. Thus every element reduces to $r^i$ or $s\,r^i$ with $0\le i\le n-1$. These are the $n$ rotations $1,r,\dots,r^{n-1}$ and the $n$ reflections $s,sr,\dots,sr^{n-1}$, i.e.\ all $2n$ elements. Hence $\langle r,s\rangle=D_{2n}$.
\textit{Check.} The count is $n+n=2n=\lvert D_{2n}\rvert$. Concretely in $D_8$ ($n=4$) the eight elements $\{1,r,r^2,r^3,s,sr,sr^2,sr^3\}$ are all reached, matching $\lvert D_8\rvert=8$ and the normal form used throughout these notes.
\end{wex}

\begin{wex}{A single reflection generates only an order-$2$ subgroup}
In $D_{2n}$, compute $\langle s\rangle$ for a reflection $s$.
\wrec Single generator $s$ with $s^2=1$, so $\ord{s}=2$; by the single-generator description $\langle s\rangle=\{s^n\st n\in\mathbb{Z}\}$ has order $\ord{s}$.
\wsol Since $s^2=1$, the powers of $s$ are $s^0=1$ and $s^1=s$, so $\langle s\rangle=\{1,s\}$, a subgroup of order $2$.
\textit{Check.} $2\mid 2n$, as Lagrange requires, and a single reflection cannot produce any rotation $r^i$ with $i\not\equiv 0$, confirming $\langle s\rangle\neq D_{2n}$ for $n\ge 2$. So two generators (such as $r,s$) are genuinely needed to reach all of $D_{2n}$.
\end{wex}

\begin{proof}
By Theorem~\ref{t:words@c2} each element of $\langle A\rangle$ is a word in the $a_i^{\pm1}$. Because the generators commute pairwise, any two adjacent letters may be swapped; repeatedly swapping sorts every word so that all $a_1^{\pm1}$ come first, then all $a_2^{\pm1}$, and so on, and within the $a_i$-block the exponents add to a single integer $m_i$, giving $a_1^{m_1}\cdots a_n^{m_n}$. Two such collected expressions commute, since each $a_i$ commutes with every $a_j$, so $\langle A\rangle$ is abelian. (This refines Corollary~\ref{c:abelian@c2}: there the whole group was abelian, here only the chosen generators need commute.)
\end{proof}

\begin{remark}[Using ``smallest'' to identify $\langle A\rangle$ without listing words]
Definition~\ref{d:gen@c2} packages $\langle A\rangle$ as an intersection so that, to prove a candidate set $K$ equals $\langle A\rangle$, one need not enumerate words: show $K\sgr G$ and $A\subseteq K$ (forcing $\langle A\rangle\subseteq K$ by the smallest property), then show every generator's contributions land in $\langle A\rangle$ (forcing $K\subseteq\langle A\rangle$). The $D_{2n}=\langle r,s\rangle$ and $\mathbb{Z}=\langle 1\rangle$ computations above are both instances of this two-inclusion pattern.
\end{remark}

\begin{wex}{$\langle 6,8,10\rangle$ in $\mathbb{Z}$}
\wrec Generated subgroup of $(\mathbb{Z},+)$ from several integers; in $\mathbb{Z}$ every subgroup is
$\langle d\rangle=d\mathbb{Z}$, and $\langle a_1,\dots,a_k\rangle=\langle \gcd(a_1,\dots,a_k)\rangle$.
\wsol $\gcd(6,8,10)=2$, so $\langle 6,8,10\rangle=2\mathbb{Z}$. \textit{Check.} $2=8-6\in\langle 6,8\rangle$, so all
even numbers arise; and $6,8,10$ are even, so nothing odd arises. Hence exactly $2\mathbb{Z}$.
\end{wex}

\begin{definition}\label{d:poset@c2}
For a group $G$, write $H\sgr K$ to mean $H$ is a subgroup of $K$. The relation $\sgr$ on the set $\mathcal{L}(G)$ of all subgroups of $G$ is a \emph{partial order}: it is reflexive ($H\sgr H$), antisymmetric ($H\sgr K$ and $K\sgr H$ force $H=K$), and transitive ($H\sgr K\sgr L$ gives $H\sgr L$).
\end{definition}

\begin{definition}\label{d:cover@c2}
Let $B\psgr A$ (so $B$ is a proper subgroup of $A$). We say $A$ \emph{covers} $B$, written $B\lessdot A$, if there is no subgroup $C$ with $B\psgr C\psgr A$ --- that is, nothing strictly between them. The \emph{Hasse diagram} of $G$ has one vertex per subgroup, drawn so that $B$ sits lower than $A$ whenever $B\psgr A$, and an edge (segment) joins $B$ to $A$ exactly when $A$ covers $B$. The trivial subgroup $1=\{e\}$ is the unique bottom vertex; $G$ is the unique top vertex.
\end{definition}

\begin{remark}\label{r:transitive@c2}
We do \emph{not} draw an edge for every containment, only for coverings. A containment $B\psgr A$ that is not a covering is recovered from the diagram as an \emph{upward path} of two or more edges. For instance in $\mathbb{Z}/(12)\mathbb{Z}$ we have $\langle 6\rangle\psgr \mathbb{Z}/(12)\mathbb{Z}$ but the edge from $\langle 6\rangle$ does not go straight to the top; the containment is read off as a path through $\langle 2\rangle$ or through $\langle 3\rangle$. This is why Hasse diagrams stay readable: transitivity is encoded by paths, not by a tangle of extra segments.
\end{remark}

