\begin{definition}\label{d:meetjoin@c2}
Let $H,K\sgr G$.
\begin{itemize}
\item The \emph{meet} of $H$ and $K$ is their intersection $H\cap K$. It is the \emph{largest} subgroup contained in both: it lies below both $H$ and $K$ in the diagram, and any subgroup below both lies below $H\cap K$.
\item The \emph{join} of $H$ and $K$ is $\langle H,K\rangle$, the smallest subgroup containing both. It is the intersection of all subgroups that contain $H\cup K$; concretely it is the set of all finite products $x_1x_2\cdots x_m$ with each $x_i\in H\cup K$. It is the \emph{smallest} subgroup lying above both $H$ and $K$.
\end{itemize}
We write $H\wedge K=H\cap K$ and $H\vee K=\langle H,K\rangle$.
\end{definition}

\begin{proposition}\label{p:intersub@c2}
For any nonempty family $\{H_i\}_{i\in I}$ of subgroups of $G$, the intersection $\bigcap_{i\in I}H_i$ is a subgroup of $G$. Consequently $H\cap K$ and $\langle H,K\rangle$ both exist and are subgroups, so $\mathcal{L}(G)$ is a \emph{lattice}: every pair has a meet and a join.
\end{proposition}

\begin{proof}
Let $D=\bigcap_i H_i$. Since $e\in H_i$ for every $i$, $e\in D$, so $D\ne\varnothing$. If $a,b\in D$ then $a,b\in H_i$ for each $i$; each $H_i$ is a subgroup, so $ab^{-1}\in H_i$ for each $i$, hence $ab^{-1}\in D$. By the subgroup criterion $D\sgr G$. For the join, let $\mathcal{S}$ be the (nonempty, since $G\in\mathcal{S}$) collection of all subgroups containing $H\cup K$; then $\langle H,K\rangle=\bigcap_{S\in\mathcal{S}}S$ is a subgroup by the first part, and it is by construction the smallest subgroup above both $H$ and $K$. The meet $H\cap K$ is the case of two subgroups.
\end{proof}

\begin{proof}
By the classification of subgroups of a cyclic group, every subgroup of $\langle x\rangle$ is cyclic of the form $\langle x^m\rangle$, and $\langle x^m\rangle=\langle x^{\gcd(m,n)}\rangle$ has order $n/\gcd(m,n)$. As $\gcd(m,n)$ ranges over the divisors of $n$, the order $n/\gcd(m,n)$ ranges over the divisors of $n$, each occurring for a unique subgroup; so there is exactly one subgroup of each order $d\mid n$, equal to $\langle x^{n/d}\rangle$. For containment, $\langle x^{n/d_1}\rangle\sgr\langle x^{n/d_2}\rangle$ holds iff the order $d_1$ divides the order $d_2$ (a subgroup of a cyclic group of order $d_2$ has order dividing $d_2$, and there is a unique one of each such order), i.e. iff $d_1\mid d_2$. A covering corresponds to a divisibility $d_1\mid d_2$ with no divisor strictly between, i.e. $d_2/d_1$ prime.
\end{proof}

\begin{method}{How to build the subgroup lattice (Hasse diagram) of a finite group}
Use this whenever you are asked to ``draw the lattice of subgroups'' or to read a join/meet off a picture.
\begin{enumerate}
\item \textbf{List all subgroups, grouped by order.} By Lagrange every subgroup order divides $|G|$, so you only need to search orders $d\mid |G|$. For cyclic $G=\mathbb{Z}/(n)\mathbb{Z}$ this is automatic: one subgroup $\langle x^{n/d}\rangle$ per divisor $d$ (Proposition~\ref{p:cycliclattice@c2}). For non-cyclic $G$, find all subgroups of each allowed order directly (e.g. all cyclic $\langle g\rangle$, then larger ones).
\item \textbf{Place vertices vertically by order.} Bottom row: the trivial group $1$ (order $1$). Top: $G$ (order $|G|$). Subgroups of equal order sit at the same height; larger order sits higher.
\item \textbf{Draw covering edges only.} Join $B$ up to $A$ iff $B\psgr A$ with nothing in between (Definition~\ref{d:cover@c2}). A quick test: if $B\psgr A$ and the index $[A:B]$ is prime, then $A$ covers $B$ (no room for an intermediate subgroup by Lagrange). Never draw an edge for a containment that already factors through a third subgroup.
\item \textbf{Read joins and meets off the picture.} $H\wedge K=H\cap K$ is the highest vertex lying below both $H$ and $K$ (their highest common lower bound). $H\vee K=\langle H,K\rangle$ is the lowest vertex lying above both. ``Below/above'' means reachable by a downward/upward path of edges.
\end{enumerate}
\end{method}

\begin{pitfall}
Do not put an edge from $1$ straight up to $G$ unless $G$ has \emph{no} proper nontrivial subgroups (i.e. $G$ is cyclic of prime order). If any subgroup sits between them, that edge is wrong --- the containment $1\psgr G$ is a multi-edge path, not a covering.
\end{pitfall}

