\begin{remark}
Two left cosets are equal or disjoint, and $aN = bN \iff a^{-1} b \in N$. The cosets partition $G$, each has the same cardinality $|N|$, and when $G$ is finite Lagrange's theorem gives $|G| = [G:N]\,|N|$. None of this requires $N$ to be normal; normality is needed only to \emph{multiply} cosets.
\end{remark}

\begin{theorem}[Well-definedness of the coset product $\iff$ normality]\label{thm:welldef@c3}
Let $N \le G$. The following are equivalent:
\begin{enumerate}
  \item[(1)] The product $(aN)(bN) = (ab)N$ is well defined on $G/N$ (independent of representatives).
  \item[(2)] $gN g^{-1} = N$ for all $g \in G$ (equivalently $gNg^{-1} \subseteq N$ for all $g$); i.e.\ $N \nor G$.
  \item[(3)] $gN = Ng$ for all $g \in G$ (every left coset is a right coset).
\end{enumerate}
When these hold, $G/N$ with this product is a group, the \textbf{quotient group}, with identity $N = 1N$ and inverse $(aN)^{-1} = a^{-1} N$.
\end{theorem}

\begin{remark}[Quotient group via fibers, D\&F's viewpoint]
Equivalently, when $N \nor G$, the cosets are exactly the fibers of any homomorphism with kernel $N$, and ``multiply the cosets'' means ``multiply the fibers as subsets'': the subset product $(aN)(bN) = \{\, xy \st x \in aN,\ y \in bN \,\}$ is itself a single coset, namely $(ab)N$. The subset product $XY=\{\,xy \st x\in X,\ y\in Y\,\}$ being a single coset for all cosets $X,Y$ is yet another equivalent of normality.
\end{remark}

\begin{proof}
Homomorphism: $\pi(gh) = (gh)N = (gN)(hN) = \pi(g)\pi(h)$, using the quotient product. Surjective: every coset $gN$ equals $\pi(g)$. Kernel: $\pi(g) = N$ (the identity of $G/N$) $\iff gN = N \iff g \in N$, so $\ker\pi = N$. The number of cosets is $[G:N]$ by definition, hence $\ord{G/N} = [G:N]$. Finally, kernels are always normal, and $\pi$ exhibits any normal $N$ as a kernel, giving the ``iff.''
\end{proof}

\begin{method}{Computing inside $G/N$: reduce representatives}
\textit{Trigger.} You must add/multiply cosets, find the order of $gN$, or identify the isomorphism type of $G/N$.
\begin{enumerate}
  \item \textbf{Multiply by representatives.} $(aN)(bN) = (ab)N$; just multiply $a,b$ in $G$, then re-coset.
  \item \textbf{Reduce mod $N$.} Replace the answer $abN$ by the simplest name: $abN = cN$ whenever $c^{-1}(ab)\in N$. In $\mathbb{Z}$ this is ``reduce mod $n$.''
  \item \textbf{Identity test.} $gN = N \iff g \in N$. So in $G/N$ a relation $gN = 1$ means $g\in N$.
  \item \textbf{Order of a coset.} $\ord{gN}$ is the least $k\ge 1$ with $g^k \in N$ (it divides $\ord{g}$ when $g$ has finite order).
  \item \textbf{Identify the type.} Compute $|G/N| = [G:N]$, then match generators/orders to a known group of that order.
\end{enumerate}
\end{method}

