\begin{method}{Proving $N \nor G$}
Three standard routes; pick whichever matches the data you have.
\begin{enumerate}
\item[\textbf{(A)}] \textbf{Conjugation test.} Show $gng^{-1} \in N$ for every $g \in G$ and every $n \in N$. By Theorem~\ref{thm:normalchar@c3}$(4)$ the one-sided containment $gNg^{-1} \subseteq N$ (for \emph{all} $g$) suffices --- you need not separately prove $\supseteq$. Trigger: $N$ given by an explicit description you can plug into a conjugate.
\item[\textbf{(B)}] \textbf{Exhibit $N$ as a kernel.} Find a homomorphism $\varphi : G \to H$ with $\ker\varphi = N$. Then $N \nor G$ for free by Proposition~\ref{prop:kernelnormal@c3}(b). Trigger: $N$ is ``everything killed by'' some natural map (determinant, sign, reduction mod $m$, projection).
\item[\textbf{(C)}] \textbf{Index $2$.} If $[G:N] = 2$ then $N \nor G$ automatically (Worked Example below). Trigger: $|G| = 2|N|$, or $N$ is ``half'' of $G$.
\end{enumerate}
\textbf{Bonus:} characteristic subgroups (e.g. $Z(G)$, the commutator subgroup) are always normal, since every conjugation is an automorphism.
\end{method}

\begin{wex}{Every index-$2$ subgroup is normal}
Let $H \le G$ with $[G:H] = 2$. Show $H \nor G$.
\wrec Method (C): index $2$ leaves no room for a left coset to differ from a right coset.
\wsol Index $2$ means there are exactly two left cosets, namely $H$ and $G \setminus H$ (the second is a single coset because the cosets partition $G$ and there are only two). Likewise the two \emph{right} cosets are $H$ and $G \setminus H$. Take any $g \in G$.
\begin{itemize}
\item If $g \in H$: then $gH = H = Hg$.
\item If $g \notin H$: then $gH \ne H$, so $gH$ must be the other left coset, $gH = G\setminus H$. Similarly $Hg \ne H$ forces $Hg = G \setminus H$. Hence $gH = G\setminus H = Hg$.
\end{itemize}
In both cases $gH = Hg$, so by Theorem~\ref{thm:normalchar@c3}$(3)$, $H \nor G$.
\textit{Check.} This recovers $A_n \nor S_n$ ($[S_n:A_n] = 2$) and $\langle r\rangle \nor D_{2n}$ ($[D_{2n}:\langle r\rangle] = 2$, since $|\langle r\rangle| = n$ and $|D_{2n}| = 2n$) without any computation. \emph{Caution:} index $\ge 3$ does \emph{not} force normality --- $\langle s\rangle \le D_8$ has index $4$ and is not normal (next example), and $\langle (1\,2)\rangle \le S_3$ has index $3$ and is not normal.
\end{wex}

\begin{pitfall}
\textbf{(1) One $g$ is not enough.} To prove $N \nor G$ you need $gng^{-1} \in N$ for \emph{all} $g \in G$. Verifying it for a single $g$ is not a proof of normality. Checking every $g$ in a generating set $T$ of $G$ does suffice when $N$ is finite (Exercise~29 below), but for infinite $N$ one must in general also check the inverses $t^{-1}$ ($t \in T$). On the other hand, one well-chosen $g$ \emph{is} enough to \emph{disprove} normality.

\textbf{(2) $gNg^{-1} \subseteq N$ for all $g$ does give normality --- but mind infinite groups.} In Theorem~\ref{thm:normalchar@c3} the one-sided test $(4)$ works because the hypothesis is quantified over \emph{all} $g$ (we plugged in $g^{-1}$ too). For a \emph{fixed} $g$, the containment $gNg^{-1} \subseteq N$ alone does \emph{not} force $gNg^{-1} = N$ when $N$ is infinite. Standard example: in $G = \GL_2(\mathbb{Q})$ let $g = \left(\begin{smallmatrix} 2 & 0 \\ 0 & 1\end{smallmatrix}\right)$ and $N = \left\{ \left(\begin{smallmatrix} 1 & x \\ 0 & 1 \end{smallmatrix}\right) : x \in \mathbb{Z} \right\}$. Then $g \left(\begin{smallmatrix}1&x\\0&1\end{smallmatrix}\right) g^{-1} = \left(\begin{smallmatrix}1&2x\\0&1\end{smallmatrix}\right)$, so $gNg^{-1} = \left\{\left(\begin{smallmatrix}1&2x\\0&1\end{smallmatrix}\right):x\in\mathbb{Z}\right\} \subsetneq N$ --- proper containment. (Of course this particular $N$ is not normal in $G$; the point is that strict containment $gNg^{-1} \subsetneq N$ can genuinely happen, so for a single $g$ ``$\subseteq$'' is weaker than ``$=$''. The quantified test in $(4)$ closes the gap by also applying the inclusion at $g^{-1}$.)

\textbf{(3) $gN = Ng$ does not mean $gn = ng$.} Normality says the \emph{sets} $gN$ and $Ng$ coincide, not that $g$ commutes with each element of $N$. For each $n$ there is \emph{some} $n' \in N$ with $gn = n'g$, but typically $n' \ne n$.
\end{pitfall}

\begin{remark}
The same proof with right cosets $Hg$ shows there are equally many right cosets, so the
index is unambiguous. The bijection $gH\mapsto Hg^{-1}$ matches left to right cosets.
Lagrange's theorem needs no normality of $H$.
\end{remark}

\begin{method}{Using Lagrange to constrain structure}
\textit{Trigger.} You know $\ord{G}$ and want to limit subgroup orders, element orders, or
rule out a configuration.
\begin{enumerate}
\item \textbf{Subgroup orders} divide $\ord{G}$: list the divisors of $\ord{G}$; any
$H\sgr G$ has $\ord{H}$ among them. (Existence is a separate question --- see the pitfall.)
\item \textbf{Element orders} divide $\ord{G}$: $\ord{x}=|\langle x\rangle|$ divides $\ord{G}$, so
$x^{\ord{G}}=1$ for every $x$.
\item \textbf{Counting cosets:} $[G:H]=\ord{G}/\ord{H}$. Small index forces structure
(index $2\Longrightarrow H\nor G$; index = smallest prime dividing $\ord{G}\Longrightarrow H\nor G$).
\item \textbf{Prime order $\Longrightarrow$ cyclic} (no room for proper nontrivial subgroups).
\end{enumerate}
\end{method}

\begin{proof}
$\ord{x}=|\langle x\rangle|$ is the order of the cyclic subgroup $\langle x\rangle\sgr G$, which divides
$\ord{G}$ by Lagrange. Write $\ord{G}=\ord{x}\cdot m$; then
$x^{\ord{G}}=(x^{\ord{x}})^{m}=1^{m}=1$.
\end{proof}

\begin{corollary}[Groups of prime order]
If $\ord{G}=p$ is prime, then $G$ is cyclic; indeed $G=\langle x\rangle$ for any $x\neq 1$.
\end{corollary}

\begin{proof}
Pick $x\neq 1$. Then $\ord{x}\mid p$ and $\ord{x}>1$, so $\ord{x}=p$. Hence
$\langle x\rangle$ has $p$ elements and $\langle x\rangle=G$, i.e.\ $G$ is cyclic of order $p$, so
$G\cong\mathbb{Z}/(p)\mathbb{Z}$.
\end{proof}

\begin{proof}
The group $G=(\mathbb{Z}/(n)\mathbb{Z})^{\times}=(\mathbb{Z}/n\mathbb{Z})^{\times}$ of units mod $n$ has order $\varphi(n)$. The class
$\overline a$ is a unit exactly when $\gcd(a,n)=1$, and then by the previous corollary
$\overline a^{\,\varphi(n)}=\overline 1$, i.e.\ $a^{\varphi(n)}\equiv1\pmod n$. For $n=p$
prime, $\varphi(p)=p-1$.
\end{proof}

\begin{remark}
$HK$ is the product \emph{set}; it need not be a subgroup. The criterion is exactly the
next proposition.
\end{remark}

\begin{proposition}[When $HK$ is a subgroup]
For subgroups $H,K\sgr G$, the set $HK$ is a subgroup of $G$ if and only if $HK=KH$.
\end{proposition}

\begin{corollary}
If $H\nor G$ or $K\nor G$ (in particular if either is normal), then $HK=KH$, so
$HK\sgr G$.
\end{corollary}

\begin{proof}
If $K\nor G$ then $hK=Kh$ for all $h$, so $HK=\bigcup_h hK=\bigcup_h Kh=KH$; apply the
proposition. Symmetrically if $H\nor G$.
\end{proof}

