\begin{wex}{Pulling back: $\pi^{-1}$ of a subgroup}
Let $G=\mathbb{Z}$, $N=12\mathbb{Z}$, so $G/N=\mathbb{Z}/12\mathbb{Z}$. Take $\overline A=\langle 4\rangle=\{0,4,8\}\sgr\mathbb{Z}/12$.
Compute $\pi^{-1}(\overline A)$ and confirm it contains $N$.
\wrec Fourth Iso Theorem: the inverse correspondence $\overline A\mapsto\pi^{-1}(\overline
A)$ lands among subgroups of $\mathbb{Z}$ containing $12\mathbb{Z}$.
\wsol $\pi^{-1}(\overline A)=\{n\in\mathbb{Z}:n+12\mathbb{Z}\in\{0,4,8\}+12\mathbb{Z}\}=\{n:n\equiv0,4,\text{ or }8
\!\!\pmod{12}\}=4\mathbb{Z}$. Indeed $4\mathbb{Z}\supseteq12\mathbb{Z}=N$ (since $12\in4\mathbb{Z}$), as required. And
$\pi(4\mathbb{Z})=4\mathbb{Z}/12\mathbb{Z}=\{0,4,8\}=\overline A$, confirming the round trip. \emph{Index check:}
$[\mathbb{Z}:4\mathbb{Z}]=4$ upstairs and $[\mathbb{Z}/12:\langle 4\rangle]=12/3=4$ downstairs. \emph{Normality:}
both are abelian so all subgroups normal, consistent with clause (4). Good.
\end{wex}

\begin{method}{Choosing the right isomorphism theorem}
\begin{itemize}
\item \textbf{One homomorphism / one quotient, want $G/\ker\cong\im$:} First Iso Theorem.
\item \textbf{Two subgroups $A,B$ of one group; want the join $AB$, the product formula,
or to rewrite $AB/B$:} Second (Diamond) Theorem. Verify $A\sgr N_G(B)$.
\item \textbf{A quotient of a quotient $(G/N)/(M/N)$, or a chain $N\sgr M\sgr G$ of normals;
want to ``cancel'':} Third Theorem. Result $G/M$.
\item \textbf{Want \emph{all} subgroups / normal subgroups / indices of $G/N$, or to pull
subgroups of $G/N$ back to $G$:} Fourth (Lattice) Theorem. Work upstairs among subgroups
containing $N$.
\end{itemize}
\textbf{Tell-tale shapes:} ``$AB$'' or ``$A\cap B$'' $\Rightarrow$ Second; double slash
``$/\!\!/$'' i.e.\ $(\,\cdot/N)/(\cdot/N)$ $\Rightarrow$ Third; ``list every subgroup of a
quotient'' $\Rightarrow$ Fourth.
\end{method}

\begin{remark}
``Subnormal'' is genuinely weaker than ``normal.'' In $D_8$ the chain
$1\nor\langle s\rangle\nor\langle s,r^2\rangle\nor D_8$ is subnormal, but $\langle s\rangle$ is \emph{not} normal in
$D_8$ (since $rsr^{-1}=sr^2\notin\langle s\rangle$). Each step is normal only in the
\emph{immediately} larger group: $\langle s\rangle\nor\langle s,r^2\rangle$ because $[\langle s,r^2\rangle:\langle s\rangle]=2$.
\end{remark}

\begin{theorem}[Existence]
Every nontrivial finite group has a composition series.
\end{theorem}

\begin{definition}[Simple group]
A group $G\ne 1$ is \emph{simple} if its only normal subgroups are $1$ and $G$.
\end{definition}

\begin{proposition}[Abelian simple groups]
An abelian group is simple if and only if it is $\mathbb{Z}/(p)\mathbb{Z}$ (cyclic of prime order $p$).
\end{proposition}

\begin{proof}
In an abelian group every subgroup is normal, so simplicity means: the only subgroups are
$1$ and $G$. If $G=\mathbb{Z}/(p)\mathbb{Z}$ with $p$ prime, Lagrange forces every subgroup to have order
$1$ or $p$, so $G$ is simple. Conversely, if abelian $G$ is simple, take $1\ne x\in G$;
then $\langle x\rangle$ is a nontrivial subgroup, hence $\langle x\rangle=G$, so $G$ is cyclic. If $G$ were
infinite cyclic ($\cong\mathbb{Z}$) it would contain $2\mathbb{Z}\ne 1,G$; if $|G|=n$ were composite with
$1<d<n$ a divisor, the unique subgroup of order $d$ would be proper nontrivial. So
$|G|=p$ is prime, $G\cong\mathbb{Z}/(p)\mathbb{Z}$. \qedhere
\end{proof}

