\langle 6\rangle/0\cong\mathbb{Z}/(2)\mathbb{Z},\quad
\langle 3\rangle/\langle 6\rangle\ \text{has order } 4/2=2\cong\mathbb{Z}/(2)\mathbb{Z},\quad
\mathbb{Z}/(12)\mathbb{Z}/\langle 3\rangle\ \text{has order } 12/4=3\cong\mathbb{Z}/(3)\mathbb{Z}.
\]
Each factor is of prime order, hence simple. So this is a composition series, with factors
\[\boxed{\mathbb{Z}/(2)\mathbb{Z},\ \mathbb{Z}/(2)\mathbb{Z},\ \mathbb{Z}/(3)\mathbb{Z}}.\]
\textit{Check.} $2\cdot 2\cdot 3=12=|\mathbb{Z}/(12)\mathbb{Z}|$. A \emph{different} chain
$0\nor\langle 4\rangle\nor\langle 2\rangle\nor\mathbb{Z}/(12)\mathbb{Z}$ (with $|\langle 4\rangle|=3$, $|\langle 2\rangle|=6$) has indices $3,2,2$,
giving factors $\mathbb{Z}/(3)\mathbb{Z},\mathbb{Z}/(2)\mathbb{Z},\mathbb{Z}/(2)\mathbb{Z}$ --- the same multiset, as Jordan--H\"older requires.

Both chains are vertical towers, each rung labeled by its composition factor; the two
\emph{differ in the order} of the factors but produce the \emph{same multiset}
$\{\mathbb{Z}/(2)\mathbb{Z},\mathbb{Z}/(2)\mathbb{Z},\mathbb{Z}/(3)\mathbb{Z}\}$ --- exactly the Jordan--H\"older invariance.
\begin{center}\begin{tikzpicture}[yscale=1.25,xscale=1.0]
  % ---- chain 1:  0 <| <6> <| <3> <| Z/12  (orders 1,2,4,12) ----
  \node[ltdot] (Ab) at (0,0) {};
  \node[ltdot] (A6) at (0,1) {};
  \node[ltdot] (A3) at (0,2) {};
  \node[ltdot] (At) at (0,3) {};
  \begin{scope}[ltedge]
    \draw (Ab)--(A6); \draw (A6)--(A3); \draw (A3)--(At);
  \end{scope}
  \node[ltlab,below=1.5pt of Ab] {$0$};
  \node[ltlab,left=3pt of A6]    {$\langle 6\rangle$};
  \node[ltlab,left=3pt of A3]    {$\langle 3\rangle$};
  \node[ltlab,above=1.5pt of At] {$\mathbb{Z}/(12)\mathbb{Z}$};
  \node[ltlab,right=2pt of $(Ab)!0.5!(A6)$] {$\mathbb{Z}/(2)\mathbb{Z}$};
  \node[ltlab,right=2pt of $(A6)!0.5!(A3)$] {$\mathbb{Z}/(2)\mathbb{Z}$};
  \node[ltlab,right=2pt of $(A3)!0.5!(At)$] {$\mathbb{Z}/(3)\mathbb{Z}$};
  % ---- chain 2:  0 <| <4> <| <2> <| Z/12  (orders 1,3,6,12) ----
  \node[ltdot] (Bb) at (4,0) {};
  \node[ltdot] (B4) at (4,1) {};
  \node[ltdot] (B2) at (4,2) {};
  \node[ltdot] (Bt) at (4,3) {};
  \begin{scope}[ltedge]
    \draw (Bb)--(B4); \draw (B4)--(B2); \draw (B2)--(Bt);
  \end{scope}
  \node[ltlab,below=1.5pt of Bb] {$0$};
  \node[ltlab,left=3pt of B4]    {$\langle 4\rangle$};
  \node[ltlab,left=3pt of B2]    {$\langle 2\rangle$};
  \node[ltlab,above=1.5pt of Bt] {$\mathbb{Z}/(12)\mathbb{Z}$};
  \node[ltlab,right=2pt of $(Bb)!0.5!(B4)$] {$\mathbb{Z}/(3)\mathbb{Z}$};
  \node[ltlab,right=2pt of $(B4)!0.5!(B2)$] {$\mathbb{Z}/(2)\mathbb{Z}$};
