\noindent Orders climb $1,2,4,12$ on the left and $1,3,6,12$ on the right; the edge labels are
the successive quotients, and both towers list $\mathbb{Z}/(2)\mathbb{Z},\mathbb{Z}/(2)\mathbb{Z},\mathbb{Z}/(3)\mathbb{Z}$.
\end{wex}

\begin{pitfall}
Composition factors do \emph{not} pin down the group. $D_8$, $\mathbb{Z}/(8)\mathbb{Z}$, $\mathbb{Z}/(4)\mathbb{Z}\times\mathbb{Z}/(2)\mathbb{Z}$,
$\mathbb{Z}/(2)\mathbb{Z}^3$, and $Q_8$ are five \emph{non-isomorphic} groups of order $8$, and all have
composition factors $\mathbb{Z}/(2)\mathbb{Z},\mathbb{Z}/(2)\mathbb{Z},\mathbb{Z}/(2)\mathbb{Z}$. Equal factor multiset $\ne$ isomorphic group.
\end{pitfall}

\begin{remark}[Equivalent tests for finite $G$]
For a finite group the following are equivalent:
(i) $G$ is solvable;
(ii) $G$ has a subnormal series with abelian factors;
(iii) every composition factor of $G$ is cyclic of prime order;
(iv) the derived series $G\supseteq G'\supseteq G''\supseteq\cdots$ reaches $1$, where
$G'=[G,G]$ is the commutator subgroup and $G^{(n+1)}=[G^{(n)},G^{(n)}]$. We use (i)--(iii)
below; (iv) is the ``derived series'' formulation.
\end{remark}

\begin{proof}
A nonabelian simple group $G$ has exactly one composition series, $1\nor G$, whose only
factor is $G/1\cong G$ --- nonabelian. By Jordan--H\"older these are the composition factors,
and at least one (the only one) is nonabelian, so by the test (iii) above $G$ is not
solvable. \qedhere
\end{proof}

\begin{method}{Testing solvability}
\textit{Trigger.} ``Is $G$ solvable?'' or ``find a solvable/composition series.''\\[2pt]
\textit{Recipe.}
\begin{enumerate}
\item Try to build a subnormal series with \emph{abelian} factors (prime-order factors are
automatically abelian). If you succeed, $G$ is solvable.
\item Shortcut to ``yes'': $G$ abelian $\Rightarrow$ solvable; $|G|=p^a$ a prime power
$\Rightarrow$ solvable; $|G|=pq,\,p^2q,\dots$ small orders are solvable (Sylow/Burnside).
\item Shortcut to ``no'': if $G$ has \emph{any} composition factor that is nonabelian
simple (e.g.\ $G$ contains a subnormal copy of $A_5$ as a factor, or $G$ is itself
nonabelian simple), then $G$ is NOT solvable.
\item \textit{Check.} Multiply factor orders to recover $|G|$; confirm each factor is
$\mathbb{Z}/(p)\mathbb{Z}$ (solvable) or spot a nonabelian simple factor (not solvable).
\end{enumerate}
\end{method}

\begin{method}{Writing a permutation as a product of transpositions}
\textit{Trigger.} You are asked for a transposition factorization, or you need the parity
of $\sigma$.

\textit{Recipe.}
\begin{enumerate}
\item Write $\sigma$ in disjoint cycle notation.
\item Replace each $k$-cycle $(a_1\,a_2\,\cdots\,a_k)$ by the $k-1$ transpositions
$(a_1\ a_k)(a_1\ a_{k-1})\cdots(a_1\ a_2)$.
\item Concatenate. The total number of transpositions is $\sum(k_i-1)$ over the cycles.
\end{enumerate}
\end{method}

\begin{pitfall}
A $k$-cycle is a product of $k-1$ transpositions, \emph{not} $k$. So a $3$-cycle is
\emph{even} (two transpositions), a $4$-cycle is \emph{odd}, a $2$-cycle (transposition)
is odd. The off-by-one error ``$k$-cycle $=k$ transpositions'' flips every parity you
compute.
\end{pitfall}

\begin{proof}
$A_n=\ker(\sgn)$ is the kernel of a homomorphism, hence a normal subgroup of $S_n$. By
the First Isomorphism Theorem $S_n/\ker(\sgn)\cong\im(\sgn)=\{\pm1\}$, which has order
$2$, so $[S_n:A_n]=|S_n/A_n|=2$. Then $\ord{A_n}=|S_n|/2=n!/2$.
\end{proof}

\begin{wex}{Multiplicativity directly}
Verify $\sgn(\sigma\tau)=\sgn(\sigma)\sgn(\tau)$ for $\sigma=(1\ 2\ 3)$,
$\tau=(2\ 3\ 4)$ in $S_4$.
\wrec $\sgn$ is a homomorphism; check by computing the product permutation independently.
\wsol $\sgn(\sigma)=(-1)^2=+1$, $\sgn(\tau)=(-1)^2=+1$, so the predicted sign is
$(+1)(+1)=+1$. Now compute $\sigma\tau$ (apply $\tau$ first):
$1\xrightarrow{\tau}1\xrightarrow{\sigma}2$;
$2\xrightarrow{\tau}3\xrightarrow{\sigma}1$;
$3\xrightarrow{\tau}4\xrightarrow{\sigma}4$;
$4\xrightarrow{\tau}2\xrightarrow{\sigma}3$.
So $\sigma\tau=(1\ 2)(3\ 4)$, with $\sgn=(-1)^2=+1$.
\textit{Check.} Predicted $+1$ matches computed $+1$.
\end{wex}

\begin{remark}
The clean argument is worth isolating: in any group $G$ with $H\le G$ of index $2$, the
quotient $G/H$ has order $2$, so $x^2\in H$ for all $x\in G$. Applied to $G=A_4$, every
$3$-cycle $g$ satisfies $g=(g^2)^2\in H$, so all $3$-cycles lie in $H$; with the identity
that is at least $9$ elements, exceeding $6$.
\end{remark}

\begin{definition}[Group action]
A (left) \emph{action} of a group $G$ on a set $A$ is a map
\[
G\times A\to A,\qquad (g,a)\mapsto g\cdot a,
\]
satisfying the two axioms:
\begin{enumerate}
\item[(1)] $g_1\cdot(g_2\cdot a)=(g_1g_2)\cdot a$ for all $g_1,g_2\in G$ and $a\in A$;
\item[(2)] $1\cdot a=a$ for all $a\in A$, where $1$ is the identity of $G$.
\end{enumerate}
We say $G$ \emph{acts on} $A$, and $A$ is a $G$-set.
\end{definition}

\begin{remark}
Each fixed $g\in G$ gives a map $\sigma_g:A\to A$, $\sigma_g(a)=g\cdot a$. Axioms (1)--(2) force $\sigma_g$ to be a bijection: $\sigma_g\circ\sigma_{g^{-1}}=\sigma_{gg^{-1}}=\sigma_1=\id_A$ and likewise $\sigma_{g^{-1}}\circ\sigma_g=\id_A$, so $\sigma_g$ has two-sided inverse $\sigma_{g^{-1}}$. Thus every group element acts as a \emph{permutation} of $A$. This is the bridge to the next definition.
\end{remark}

\begin{proposition}[Actions $\Longleftrightarrow$ permutation representations]
For a group $G$ and a set $A$ there is a bijection between actions of $G$ on $A$ and homomorphisms $\rho:G\to\Sym(A)$, sending an action to the map $\rho$ with $\rho(g)(a)=g\cdot a$, with inverse $\rho\mapsto(g\cdot a:=\rho(g)(a))$.
\end{proposition}

\begin{method}{Showing a formula defines an action / computing the kernel}
\textit{Trigger.} A candidate rule $(g,a)\mapsto g\cdot a$, and you must verify it is an action or decide if it is faithful.
\begin{enumerate}
\item \textbf{Identity axiom:} check $1\cdot a=a$ for all $a$.
\item \textbf{Compatibility axiom:} compute $g_1\cdot(g_2\cdot a)$ and $(g_1g_2)\cdot a$ \emph{separately}, then confirm they agree. (Watch the order: a ``$g$ on the right'' formula like $a\cdot g$ usually needs $g^{-1}$ to be a \emph{left} action.)
\item \textbf{Kernel:} solve $g\cdot a=a$ \emph{for all} $a\in A$ simultaneously. The $g$ satisfying every equation form $\ker\rho\nor G$.
\item \textbf{Faithful?} Yes iff $\ker\rho=1$.
\end{enumerate}
\end{method}

\begin{proof}
\textbf{Reflexive:} $a=1\cdot a$, so $a\sim a$. \textbf{Symmetric:} if $b=g\cdot a$ then $g^{-1}\cdot b=g^{-1}\cdot(g\cdot a)=(g^{-1} g)\cdot a=1\cdot a=a$, so $b\sim a$. \textbf{Transitive:} if $b=g\cdot a$ and $c=h\cdot b$ then $c=h\cdot(g\cdot a)=(hg)\cdot a$, so $a\sim c$. An equivalence relation partitions $A$ into its classes, and the class of $a$ is exactly $\{b:a\sim b\}=\{g\cdot a:g\in G\}=\orb(a)$.
\end{proof}

\begin{proposition}[The stabilizer is a subgroup]
For each $a\in A$, $G_a\le G$. Moreover $\ker\rho=\bigcap_{a\in A}G_a$, and points in the same orbit have conjugate stabilizers: $G_{g\cdot a}=g\,G_a\,g^{-1}$.
\end{proposition}

\begin{proof}
$1\cdot a=a$ gives $1\in G_a$, so $G_a\ne\varnothing$. If $g,h\in G_a$ then $(gh)\cdot a=g\cdot(h\cdot a)=g\cdot a=a$, so $gh\in G_a$. If $g\in G_a$ then $a=1\cdot a=(g^{-1} g)\cdot a=g^{-1}\cdot(g\cdot a)=g^{-1}\cdot a$, so $g^{-1}\in G_a$. Thus $G_a\le G$. An element fixes \emph{all} points iff it lies in every $G_a$, giving $\ker\rho=\bigcap_a G_a$. Finally $x\in G_{g\cdot a}\iff x\cdot(g\cdot a)=g\cdot a\iff (g^{-1} xg)\cdot a=a\iff g^{-1} xg\in G_a\iff x\in gG_ag^{-1}$.
\end{proof}

\begin{remark}
The second triangle is the action's ``first isomorphism theorem'' shape: the orbit map $g\mapsto g\cdot a$ factors through the quotient $G/G_a$, and the induced map $\Phi$ is a bijection onto the image $\orb(a)$. Collapsing $G$ by the stabilizer exactly recovers the orbit.
\end{remark}

\begin{method}{Counting with Orbit--Stabilizer}
\textit{Trigger.} You want $|\orb(a)|$, or $|G|$, or $|G_a|$, and you can compute two of these three quantities; or you must show some orbit/index relationship.
\begin{enumerate}
\item Pick a convenient point $a\in A$.
\item Compute $\orb(a)$ directly (apply enough group elements until the orbit closes up) and read off $|\orb(a)|$.
\item Compute $G_a=\{g:g\cdot a=a\}$ and read off $|G_a|$.
\item Use $\ |\orb(a)|\cdot|G_a|=|G|\ $ to get the missing third number, or to \emph{check} the two you computed.
\item For an unknown $|G|$: $|G|=|\orb(a)|\cdot|G_a|$ when the action is understood geometrically (e.g. symmetries of a figure acting on its vertices/faces).
\end{enumerate}
\end{method}

\begin{pitfall}
\textbf{Orbit vs.\ stabilizer live in different worlds.} The orbit $\orb(a)\subseteq A$ is a set of \emph{points}; the stabilizer $G_a\le G$ is a set of \emph{group elements}. Orbit--Stabilizer relates their sizes via the \emph{index} $[G:G_a]$, not by any direct inclusion. Writing ``$\orb(a)=G/G_a$'' is only a bijection of sets, never an equality.
\end{pitfall}

\begin{pitfall}
\textbf{The stabilizer is a subgroup of $G$, but the orbit is not a subgroup of anything.} Students sometimes ``check $\orb(a)$ is a subgroup'' --- it usually is not even contained in $G$. Only $G_a$ (and $\ker\rho=\bigcap_a G_a$) are subgroups.
\end{pitfall}

\begin{pitfall}
\textbf{Left vs.\ right.} For axiom (1) you need $g_1\cdot(g_2\cdot a)=(g_1g_2)\cdot a$. A rule like $a\cdot g:=ag$ (right multiplication, written on the right) gives $(a\cdot g_1)\cdot g_2=ag_1g_2$, which corresponds to $(g_1g_2)$ acting as ``$g_1$ then $g_2$'' --- the \emph{wrong} order for a left action. To convert a right action to a left action, use $g\cdot a:=ag^{-1}$, so that $g_1\cdot(g_2\cdot a)=a g_2^{-1} g_1^{-1}=a(g_1g_2)^{-1}=(g_1g_2)\cdot a$.
\end{pitfall}

Show that the set of $H K$ double cosets partitions $G$.
\item[(d)] Prove that $|H x K| = |K| \cdot |H : H \cap x K x^{-1}|$.
\item[(e)] Prove that $|H x K| = |H| \cdot |K : K \cap x^{-1} H x|$.
\end{enumerate}
\end{exers}

\begin{remark}
Do not confuse the action with the group operation conceptually: $G$ acts \emph{on the set} of its own elements. The permutation attached to $g$ is left-translation $\lambda_g\colon x\mapsto gx$, which is a bijection of the set $G$ (with inverse $\lambda_{g^{-1}}$), but $\lambda_g$ is essentially never a group homomorphism $G\to G$.
\end{remark}

\begin{remark}[Image of Cayley's embedding]
Each nonidentity $\lambda_g$ is a \emph{fixed-point-free} permutation of $G$: if $gx=x$ then $g=1$. Consequently every nonidentity $\lambda_g$ is a product of cycles all of the same length $\ord{g}$, and there are exactly $n/\ord{g}$ of them. (This is the cycle structure of the regular representation.)
\end{remark}

\begin{method}{Using Cayley's theorem / the regular representation}
\textit{Trigger.} You want to realize an abstract group concretely inside a symmetric group, or you need a permutation whose cycle type encodes element orders.\\[2pt]
\textit{Recipe.}
\begin{enumerate}
\item Fix an ordering/labelling $x_1,\dots,x_n$ of the elements of $G$.
\item For each generator $g$, compute $\lambda_g(x_i)=g x_i$ and read off the permutation of indices.
\item Write $\lambda_g$ in cycle notation. Sanity check: $\lambda_g$ moves \emph{every} point unless $g=1$ (fixed-point free), and its cycles all have length $\ord{g}$, giving $n/\ord{g}$ cycles.
\item The map $g\mapsto\lambda_g$ is the embedding $G\hookrightarrow S_n$.
\end{enumerate}
\end{method}

\begin{wex}{Cayley for $S_3$ into $S_6$}
Describe the cycle type of $\lambda_g$ for the regular representation $S_3\hookrightarrow S_6$ as $g$ ranges over $S_3$.
\wrec Cayley plus the cycle-structure remark: nonidentity $\lambda_g$ is fixed-point free with all cycles of length $\ord{g}$.
\wsol Here $n=6$. By element orders in $S_3$:
\begin{itemize}
\item $g=1$: $\lambda_g=\id$.
\item $g$ a transposition ($\ord{g}=2$, three such $g$): $\lambda_g$ is $6/2=3$ transpositions, type $2^3$.
\item $g$ a $3$-cycle ($\ord{g}=3$, two such $g$): $\lambda_g$ is $6/3=2$ three-cycles, type $3^2$.
\end{itemize}
So the image consists of $\id$, three permutations of type $2^3$, and two of type $3^2$.

\textit{Check.} The element count matches $|S_3|=6=1+3+2$. For a transposition $g$, $\lambda_g$ has type $2^3$ with sign $(-1)^3=-1$, so $\lambda_g$ is an odd permutation of $S_6$; for a $3$-cycle $g$, $\lambda_g$ has type $3^2$ with sign $(+1)^2=+1$, an even permutation. Consistent with $S_3$ having a sign map. Good.
\end{wex}

\begin{wex}{Order $6$ with no $6$-cycle image? (cyclic vs. noncyclic)}
For which groups $G$ of order $6$ does the regular representation contain a $6$-cycle?
\wrec Cayley plus cycle structure: $\lambda_g$ is a single $n$-cycle iff $\ord{g}=n=\ord{G}$, i.e. iff $g$ generates $G$.
\wsol A nonidentity $\lambda_g$ is one $6$-cycle iff $\ord{g}=6$, i.e. $g$ generates $G$, i.e. $G$ is cyclic. For $G=\mathbb{Z}/(6)\mathbb{Z}$ the generator $1$ gives $\lambda_1=(1\,2\,3\,4\,5\,6)$, a $6$-cycle. For $G=S_3$ there is no element of order $6$ (orders are $1,2,3$), so \emph{no} $\lambda_g$ is a $6$-cycle: the regular representation of $S_3$ contains only types $2^3$ and $3^2$ (and $\id$).

\textit{Check.} $\mathbb{Z}/(6)\mathbb{Z}$ has $\phi(6)=2$ generators, giving two $6$-cycles $(1\,2\,3\,4\,5\,6)$ and its inverse; consistent with $\mathbb{Z}/(6)\mathbb{Z}$ cyclic. $S_3$ noncyclic, no $6$-cycle. Good.
\end{wex}

\begin{pitfall}
Cayley says $G\le S_n$ for $n=\ord G$, but $n$ is usually \emph{far} from optimal. E.g. $\mathbb{Z}/(6)\mathbb{Z}\hookrightarrow S_6$ via the regular action, yet $\mathbb{Z}/(6)\mathbb{Z}$ also embeds in $S_5$ (as $(1\,2)(3\,4\,5)$). Cayley gives \emph{an} embedding, not the smallest one. Do not claim ``the least $n$ with $G\le S_n$ is $\ord G$.''
\end{pitfall}

\begin{theorem}[Coset action; kernel is the core]\label{thm:coset@c4}
Let $G$ be a group, $H\le G$, and let $A=\{\,gH : g\in G\,\}$ be the set of left cosets of $H$, so $|A|=[G:H]$. Then $G$ acts on $A$ by left multiplication,
\[
g\cdot(xH)=(gx)H,
\]
and this affords a homomorphism
\[
\rho_H\colon G\longrightarrow \Sym(A)\cong S_{[G:H]}.
\]
Moreover:
\begin{enumerate}
\item the action is transitive;
\item the stabilizer of the coset $1H=H$ is exactly $H$;
\item $\displaystyle \ker\rho_H=\bigcap_{x\in G} xHx^{-1}$, and this is the \emph{largest normal subgroup of $G$ contained in $H$}. It is called the \emph{core} of $H$ in $G$, written $\operatorname{core}_G(H)$.
\end{enumerate}
\end{theorem}

\begin{corollary}[Index--order divisibility]\label{cor:divis@c4}
With $K=\ker\rho_H=\operatorname{core}_G(H)$, the induced map $\bar\rho_H\colon G/K\hookrightarrow S_{[G:H]}$ is injective, so
\[
[G:K]=\ord{G/K}\ \ \text{divides}\ \ [G:H]!\,.
\]
\end{corollary}

\begin{proof}
First Isomorphism Theorem: $G/K\cong\im\rho_H\le S_{[G:H]}$, of order $[G:H]!$. Lagrange in $S_{[G:H]}$ gives the divisibility.
\end{proof}

\begin{corollary}[Smallest-prime index forces normality]\label{cor:smallprime@c4}
Let $G$ be a finite group and $H\le G$ with $[G:H]=p$, where $p$ is the \emph{smallest} prime dividing $\ord G$. Then $H\nor G$.
\end{corollary}

\begin{proof}
Let $K=\operatorname{core}_G(H)$ and put $k=[H:K]$. By Cor.~\ref{cor:divis@c4}, $[G:K]\mid p!$. Also $[G:K]=[G:H]\cdot[H:K]=p\,k$, so $pk\mid p!$, giving $k\mid (p-1)!$. But $k=[H:K]$ divides $\ord G$ (since $K\le H\le G$), and every prime divisor of $\ord G$ is $\ge p$. A prime $q\mid k$ would satisfy $q\mid(p-1)!$, forcing $q\le p-1<p$, contradicting minimality of $p$ unless $k$ has no prime divisors, i.e. $k=1$. Hence $K=H$, so $H=\operatorname{core}_G(H)\nor G$.
\end{proof}

\begin{remark}
Taking $p=2$ recovers the familiar fact: \emph{every subgroup of index $2$ is normal}. Indeed $2$ is the smallest prime dividing any even order.
\end{remark}

\begin{method}{Coset (permutation) representation and the core}
\textit{Trigger.} A subgroup $H$ of small index $m=[G:H]$ appears; you want a homomorphism $G\to S_m$, a normal subgroup inside $H$, or a normality/non-simplicity conclusion.\\[2pt]
\textit{Recipe.}
\begin{enumerate}
\item List the $m$ left cosets $g_1H,\dots,g_mH$ (with $g_1=1$). This is the set $A$.
\item For each generator $g$, compute $g\cdot(g_iH)=(gg_i)H$ and identify which coset it equals; record the permutation $\rho_H(g)\in S_m$.
\item $\ker\rho_H=\bigcap_x xHx^{-1}=\operatorname{core}_G(H)$ is the largest normal subgroup inside $H$. In practice intersect the conjugates, or read it off as $\bigcap_i\Stab(g_iH)$.
\item \textit{Conclusions.} $[G:\ker\rho_H]\mid m!$ (Cor.~\ref{cor:divis@c4}); if $m$ is the least prime dividing $\ord G$ then $H\nor G$ (Cor.~\ref{cor:smallprime@c4}); if $m>1$ and $\ord G\nmid m!$ then $\rho_H$ has nontrivial kernel, contained in $H\ne G$, so $G$ has a proper nontrivial normal subgroup (not simple).
\end{enumerate}
\end{method}

\begin{wex}{Forcing non-simplicity from a small-index subgroup}
Suppose $\ord G=24$ and $G$ has a subgroup $H$ with $[G:H]=3$. Show $G$ is not simple.
\wrec Coset action $\rho_H\colon G\to S_3$ with $\ker\rho_H=\operatorname{core}_G(H)$; use the order obstruction $[G:\ker]\mid 3!$ (Cor.~\ref{cor:divis@c4}).
\wsol $\rho_H\colon G\to S_3$ has $\ord{G/\ker\rho_H}\mid 3!=6$. If $\ker\rho_H=\{1\}$ then $G\hookrightarrow S_3$, so $24=\ord G\mid 6$, false. Hence $\ker\rho_H\ne\{1\}$. Also $\ker\rho_H\le H\subsetneq G$, so $\ker\rho_H\ne G$. Thus $\ker\rho_H$ is a proper nontrivial normal subgroup of $G$: $G$ is not simple.

\textit{Check.} The obstruction is $24\nmid 6$. More precisely $[G:\ker]\mid\gcd(6,24)=6$, but $[G:\ker]\ge3$ and divides $24$, so $[G:\ker]\in\{3,6\}$; either way $\ker$ has order $8$ or $4$, a genuine normal subgroup. Good.
\end{wex}

