\begin{pitfall}
The core is built from \emph{conjugates} $xHx^{-1}$, not from $H$ alone. A common error is to take $\ker\rho_H=H$ ``because the stabilizer of $H$ is $H$.'' The stabilizer of the basepoint $1H$ is $H$, but the kernel is the intersection of the stabilizers of \emph{all} cosets, $\bigcap_x xHx^{-1}$, which can be much smaller. Equality $\ker\rho_H=H$ holds iff $H\nor G$.
\end{pitfall}

\begin{pitfall}
Cor.~\ref{cor:smallprime@c4} needs $p$ to be the \emph{smallest} prime dividing $\ord G$, not just any prime. In $A_4$ ($\ord{A_4}=12$) the subgroup of index $3$ (order $4$, the Klein four $V$) \emph{is} normal --- here $3$ is not the least prime, yet it happens to work --- but a subgroup of index $3$ is \emph{not} guaranteed normal in general when $3$ is not the smallest prime. The theorem only \emph{guarantees} normality at the least prime; e.g. $A_4$ has subgroups of index $4$ (order $3$) that are not normal, and $4$ is not a prime dividing $12$.
\end{pitfall}

\begin{method}{Computing one conjugacy class}
\textit{Trigger.} You are asked for the conjugacy class of a specific $x$, or for $|\mathcal{K}_x|$.
\begin{enumerate}
\item Find $C_G(x) = \{g : gx = xg\}$ -- list which elements commute with $x$. It always contains $\langle x\rangle$ and $Z(G)$.
\item Compute $|C_G(x)|$ and then $|\mathcal{K}_x| = [G:C_G(x)] = |G|/|C_G(x)|$.
\item Produce the conjugates by conjugating $x$ by a transversal of $C_G(x)$ (one $g$ per coset). Stop when you have collected $|\mathcal{K}_x|$ distinct elements.
\item \textit{Check.} Class size divides $|G|$; the class is a single element iff $x$ is central.
\end{enumerate}
\end{method}

\begin{pitfall}
Do not confuse the \emph{centralizer} $C_G(x)$ (the stabilizer, which governs class \emph{size}) with the \emph{normalizer} $N_G(H)$ (used for subgroup conjugation). For elements use $C_G(x)$; for subgroups use $N_G(H)$.
\end{pitfall}

\begin{wex}{A central element forms a singleton class}
In $Q_8 = \{\pm 1, \pm i, \pm j, \pm k\}$, find the class of $-1$.
\wrec Singletons come from the center: $|\mathcal{K}_x| = 1 \Longleftrightarrow x \in Z(G)$.
\wsol $-1$ commutes with every element of $Q_8$ (it is the unique element of order $2$ and lies in $Z(Q_8)$). So $C_{Q_8}(-1) = Q_8$ and $|\mathcal{K}_{-1}| = 8/8 = 1$, i.e.\ $\mathcal{K}_{-1} = \{-1\}$.
\textit{Check.} Singleton class $\Longleftrightarrow$ central; indeed $Z(Q_8) = \{1,-1\}$.
\end{wex}

\begin{wex}{Class of $i$ in $Q_8$}
Find the conjugacy class of $i$ in $Q_8$.
\wrec $|\mathcal{K}_i| = [Q_8:C_{Q_8}(i)]$; compute the centralizer first.
\wsol $C_{Q_8}(i) \supseteq \langle i\rangle = \{1,-1,i,-i\}$, of order $4$. Does $j$ commute with $i$? $ji = -k$ while $ij = k$, so $ji \ne ij$ and $j \notin C_{Q_8}(i)$. Thus $C_{Q_8}(i) = \{\pm 1, \pm i\}$, order $4$, and $|\mathcal{K}_i| = 8/4 = 2$. Conjugate $i$ by $j$ (with $j^{-1} = -j$): $j i j^{-1} = (ji)(-j) = (-k)(-j) = kj$, and $kj = -i$, so $j i j^{-1} = -i$. Hence $\mathcal{K}_i = \{i,-i\}$.
\textit{Check.} $2 \mid 8$; and $i,-i$ are exactly the two noncentral powers of $i$ -- consistent.
\end{wex}

\begin{wex}{Class of a $3$-cycle vs.\ the centralizer in $S_3$}
Find the conjugacy class of $(1\,2\,3)$ in $S_3$.
\wrec In $S_n$ conjugation preserves cycle type; class size $= [S_3:C_{S_3}((1\,2\,3))]$.
\wsol $|S_3| = 6$. The element $(1\,2\,3)$ commutes with the cyclic group it generates, $\langle (1\,2\,3)\rangle = \{e,(1\,2\,3),(1\,3\,2)\}$, of order $3$. No transposition commutes with it (e.g.\ $(1\,2)(1\,2\,3)(1\,2) = (2\,1\,3) = (1\,3\,2) \ne (1\,2\,3)$), so $C_{S_3}((1\,2\,3)) = \langle (1\,2\,3)\rangle$, order $3$. Thus $|\mathcal{K}| = 6/3 = 2$, and $\mathcal{K}_{(1\,2\,3)} = \{(1\,2\,3),(1\,3\,2)\}$ -- both $3$-cycles.
\textit{Check.} There are exactly two $3$-cycles in $S_3$; class size $2 \mid 6$. Good.
\end{wex}

\begin{theorem}[The Class Equation]\label{thm:classeqn@c4}
Let $G$ be a finite group and let $g_1,\dots,g_r$ be representatives of the distinct conjugacy classes of $G$ that are \emph{not} contained in $Z(G)$. Then
\[
\boxed{\;\ord{G} \;=\; \ord{Z(G)} \;+\; \sum_{i=1}^{r} [G:C_G(g_i)].\;}
\]
\end{theorem}

\begin{proof}
The conjugacy classes partition $G$, so $|G|$ is the sum of the sizes of the distinct classes. A class is a singleton exactly when its representative is central (Proposition~\ref{prop:classsize@c4}); the singleton classes are the $|Z(G)|$ one-element sets $\{z\}$ for $z \in Z(G)$, contributing $|Z(G)|$ in total. Every remaining class has size $> 1$, with representative $g_i \notin Z(G)$ and size $[G:C_G(g_i)]$. Summing,
\[
|G| = \underbrace{\sum_{z \in Z(G)} 1}_{=\,|Z(G)|} \;+\; \sum_{i=1}^{r} [G:C_G(g_i)] = |Z(G)| + \sum_{i=1}^{r}[G:C_G(g_i)]. \qedhere
\]
\end{proof}

