\begin{method}{Writing the class equation of a finite group}
\textit{Trigger.} ``find the class equation of $G$'' or ``how many conjugacy classes does $G$ have.''
\begin{enumerate}
\item Compute $|Z(G)|$; each central element is its own class (a $1$).
\item For each non-central element, find its class size $[G:C_G(g)]$; group elements into classes so you never double-count.
\item Write $|G| = |Z(G)| + (\text{non-central class sizes})$; every summand divides $|G|$, and the central part is $|Z(G)|$ copies of $1$.
\item \textit{Check.} The right side sums to $|G|$, and the count of summands equals the number of conjugacy classes.
\end{enumerate}
\end{method}

\begin{proof}
\emph{Formula.} For a $k$-cycle $(a_1\cdots a_k)$ and any $\tau$, evaluate $\tau\sigma\tau^{-1}$ at $\tau(a_j)$: $\tau\sigma\tau^{-1}(\tau(a_j)) = \tau\sigma(a_j) = \tau(a_{j+1})$ (indices mod $k$), so $\tau\sigma\tau^{-1} = (\tau(a_1)\cdots\tau(a_k))$, a $k$-cycle. Applying this to each disjoint cycle of $\sigma$ (and noting $\tau$ keeps the cycles disjoint, being a bijection) shows $\tau\sigma\tau^{-1}$ has the same cycle type as $\sigma$. \emph{Converse.} If $\sigma,\sigma'$ have the same cycle type, align their cycles and let $\tau$ be the bijection sending the entries of $\sigma$ to the correspondingly-placed entries of $\sigma'$; then $\tau\sigma\tau^{-1} = \sigma'$ by the formula. Hence ``same cycle type'' is exactly conjugacy, and cycle types are partitions of $n$.
\end{proof}

\begin{theorem}[Counting a cycle-type class]\label{thm:countclass@c4}
If a cycle type has $m_k$ cycles of length $k$ (so $\sum_k k\, m_k = n$, counting fixed points as $1$-cycles), the number of permutations of that type, equivalently the size of the conjugacy class, is
\[
\frac{n!}{\displaystyle \prod_{k\ge 1} k^{\,m_k}\, m_k!}.
\]
\end{theorem}

\begin{proof}
Fill the cycle skeleton with the $n$ symbols in one of $n!$ orders. Each cycle of length $k$ has $k$ cyclic rotations giving the same permutation, accounting for $\prod_k k^{m_k}$; and the $m_k$ cycles of equal length $k$ can be permuted among themselves without changing the permutation, accounting for $\prod_k m_k!$. Dividing removes the overcount.
\end{proof}

\begin{method}{Conjugacy in $S_n$}
\textit{Trigger.} ``are these two permutations conjugate in $S_n$?'' or ``how many elements / classes of a given type?''
\begin{enumerate}
\item Write each permutation in disjoint cycles (include fixed points to read the full type).
\item Conjugate by \emph{relabeling}: $\tau\sigma\tau^{-1}$ just applies $\tau$ to each entry -- so two are conjugate iff same multiset of cycle lengths.
\item Count a class by $n!/\prod_k k^{m_k} m_k!$. Sum over all partitions of $n$ to recover $n!$.
\item \textit{Check.} Class sizes are integers dividing $n!$ and sum to $n!$; the number of classes equals $p(n)$, the number of partitions.
\end{enumerate}
\end{method}

\begin{wex}{Are these conjugate in $S_5$?}
Decide whether $\sigma = (1\,2\,3)(4\,5)$ and $\tau = (1\,4)(2\,5\,3)$ are conjugate in $S_5$, and if so exhibit a conjugator.
\wrec Conjugate in $S_n$ $\Longleftrightarrow$ same cycle type; build the conjugator by aligning cycles.
\wsol Both have type $3+2$ (a $3$-cycle and a disjoint $2$-cycle): $\sigma$ acts as a $3$-cycle on $\{1,2,3\}$ and a $2$-cycle on $\{4,5\}$; $\tau = (2\,5\,3)(1\,4)$ acts as a $3$-cycle on $\{2,5,3\}$ and a $2$-cycle on $\{1,4\}$. Same type $\Longrightarrow$ conjugate. To build $\rho$ with $\rho\sigma\rho^{-1} = \tau$, map $\sigma$'s cycles onto $\tau$'s entry-by-entry: $1\mapsto 2,\,2\mapsto 5,\,3\mapsto 3,\,4\mapsto 1,\,5\mapsto 4$, i.e.\ $\rho = (1\,2\,5\,4)$. \textit{Check.} $\rho\sigma\rho^{-1} = (\rho(1)\,\rho(2)\,\rho(3))(\rho(4)\,\rho(5)) = (2\,5\,3)(1\,4) = \tau$. Correct.
\end{wex}

\begin{wex}{Counting $5$-cycles in $S_5$}
How many $5$-cycles are in $S_5$, and what is the centralizer of one?
\wrec Size of a cycle-type class $= n!/\prod k^{m_k}m_k!$; centralizer order $= |G|/|\text{class}|$.
\wsol Type $5$: $m_5 = 1$, all others $0$, so count $= 5!/(5^1\cdot 1!) = 120/5 = 24$. By orbit--stabilizer, $|C_{S_5}(\sigma)| = |S_5|/|\mathcal{K}_\sigma| = 120/24 = 5$, so the centralizer is exactly $\langle \sigma\rangle$ (a $5$-cycle commutes only with its own powers).
\textit{Check.} $24 \mid 120$; $|C| = 5 = |\langle \sigma\rangle|$. A $5$-cycle has order $5$, so $\langle \sigma\rangle$ has order $5$ -- matches.
\end{wex}

\begin{theorem}[$p$-groups have nontrivial center]\label{thm:pgroupcenter@c4}
If $p$ is a prime and $|G| = p^a$ with $a \ge 1$, then $Z(G) \ne 1$; that is, $p \mid |Z(G)|$.
\end{theorem}

\begin{corollary}[Groups of order $p^2$ are abelian]\label{cor:p2abelian@c4}
If $|G| = p^2$ for a prime $p$, then $G$ is abelian (so $G \cong \mathbb{Z}/(p^2)\mathbb{Z}$ or $G \cong \mathbb{Z}/(p)\mathbb{Z}\times\mathbb{Z}/(p)\mathbb{Z}$).
\end{corollary}

\begin{proof}
By Theorem~\ref{thm:pgroupcenter@c4}, $Z(G) \ne 1$, so $|Z(G)| \in \{p, p^2\}$. If $|Z(G)| = p^2$ then $G = Z(G)$ is abelian and we are done. Suppose instead $|Z(G)| = p$. Then $|G/Z(G)| = p^2/p = p$, so $G/Z(G)$ is cyclic. But it is a standard lemma that \emph{if $G/Z(G)$ is cyclic then $G$ is abelian}: write $G/Z(G) = \langle xZ(G)\rangle$; every $g \in G$ is $g = x^m z$ for some integer $m$ and $z \in Z(G)$, and two such elements $x^{m}z,\ x^{n}w$ commute because powers of $x$ commute with each other and $z,w$ are central. So $G$ is abelian, which forces $Z(G) = G$ and contradicts $|Z(G)| = p < p^2$. Hence the case $|Z(G)| = p$ is impossible, $|Z(G)| = p^2$, and $G$ is abelian. The classification into $\mathbb{Z}/(p^2)\mathbb{Z}$ and $\mathbb{Z}/(p)\mathbb{Z}\times\mathbb{Z}/(p)\mathbb{Z}$ follows from the structure of finite abelian groups.
\end{proof}

\begin{method}{Using the class equation modulo $p$}
\textit{Trigger.} $|G|$ is a prime power $p^a$ (or you need to show some central element exists).
\begin{enumerate}
\item Write $|G| = |Z(G)| + \sum [G:C_G(g_i)]$ over non-central classes.
\item Each non-central index $[G:C_G(g_i)]$ is a power $p^{b_i}$, $b_i \ge 1$, hence $\equiv 0 \pmod p$.
\item Reduce mod $p$: $0 \equiv |Z(G)| + 0$, so $p \mid |Z(G)|$, forcing $Z(G) \ne 1$.
\item \textit{Check.} Consistency -- the central summand $|Z(G)|$ plus a multiple of $p$ equals $p^a$, also a multiple of $p$.
\end{enumerate}
\end{method}

\begin{wex}{$Z(G) \ne 1$ for $|G| = 27$}
Show every group of order $27$ has nontrivial center.
\wrec $27 = 3^3$ is a $p$-group; apply the class-equation-mod-$p$ argument.
\wsol Class equation: $27 = |Z(G)| + \sum_i [G:C_G(g_i)]$ with each non-central index a power $3^{b_i}$, $b_i \ge 1$, so each is divisible by $3$. Reducing mod $3$: $0 \equiv |Z(G)| + 0 \pmod 3$, so $3 \mid |Z(G)|$. As $|Z(G)| \ge 1$, we get $|Z(G)| \in \{3, 9, 27\}$, in particular $Z(G) \ne 1$.
\textit{Check.} Possible class equations include $27 = 27$ (abelian) and $27 = 3 + 3+3+3+3+3+3+3+3$ (i.e.\ $|Z| = 3$ together with eight non-central classes of size $3$). Each summand divides $27$ and the centre is a multiple of $3$. Consistent.
\end{wex}

\begin{wex}{Order $p^2$ is abelian: $|G| = 25$}
Prove any group of order $25$ is abelian.
\wrec $25 = 5^2$; use $Z(G) \ne 1$ and the $G/Z(G)$-cyclic lemma.
\wsol By Theorem~\ref{thm:pgroupcenter@c4}, $Z(G) \ne 1$, so $|Z(G)| \in \{5,25\}$. If $|Z(G)| = 5$ then $|G/Z(G)| = 5$, hence $G/Z(G)$ is cyclic of prime order, which forces $G$ abelian and thus $Z(G) = G$ -- contradicting $|Z(G)| = 5$. So $|Z(G)| = 25$ and $G$ is abelian; concretely $G \cong \mathbb{Z}/(25)\mathbb{Z}$ or $\mathbb{Z}/(5)\mathbb{Z}\times\mathbb{Z}/(5)\mathbb{Z}$.
\textit{Check.} Both candidate groups are indeed abelian, and there is no nonabelian group of order $25$. Consistent with the theorem.
\end{wex}

\begin{wex}{A nonabelian group of order $p^3$}
Verify the center-of-$p$-group theorem is sharp at $p^3$ by examining $D_8$.
\wrec At $p^3$ the center can be exactly $p$; check $D_8$ ($p = 2$, $a = 3$).
\wsol $|D_8| = 8 = 2^3$. Its class equation $8 = 1+1+2+2+2$ has central part $|Z(D_8)| = 2 = p$, the smallest allowed. So $Z(D_8) \ne 1$ (as the theorem guarantees) but $D_8$ is nonabelian, showing the corollary ``$p^2 \Longrightarrow$ abelian'' cannot be pushed to $p^3$.
\textit{Check.} $2 \mid |Z(D_8)|$ holds; $|Z| = 2 < 8$ so nonabelian -- exactly the boundary case.
\end{wex}

\begin{pitfall}
For \emph{subgroup} conjugacy use the \emph{normalizer} $N_G(H)$, not the centralizer. Always $H \le N_G(H)$ and $C_G(H) \le N_G(H)$, but the number of conjugates is $[G:N_G(H)]$. Using $C_G(H)$ here is a common error.
\end{pitfall}

\begin{method}{Counting conjugates of a subgroup}
\textit{Trigger.} ``how many subgroups are conjugate to $H$'' or ``is $H$ normal.''
\begin{enumerate}
\item Compute $N_G(H) = \{g : gHg^{-1} = H\}$; note $H \le N_G(H) \le G$.
\item Number of conjugates $= [G:N_G(H)] = |G|/|N_G(H)|$.
\item $H \nor G \Longleftrightarrow$ this index is $1 \Longleftrightarrow N_G(H) = G$.
\item \textit{Check.} The count divides $|G|$; if you also have the count by direct listing, it must match.
\end{enumerate}
\end{method}

\begin{wex}{Conjugates of $\langle s\rangle$ in $D_8$}
Count the subgroups of $D_8$ conjugate to $H = \langle s\rangle = \{1,s\}$.
\wrec Number of conjugates $= [D_8:N_{D_8}(H)]$; find the normalizer.
\wsol $N_{D_8}(H) \supseteq H = \{1,s\}$ and contains $Z(D_8) = \{1,r^2\}$ since central elements normalize everything; so $\{1,s,r^2,r^2 s\} \le N_{D_8}(H)$, order $\ge 4$. Is $r \in N$? $r\langle s\rangler^{-1} = \langle rsr^{-1}\rangle = \langle r^2 s\rangle \ne \langle s\rangle$, so $r \notin N$, giving $N_{D_8}(H) = \{1,s,r^2,r^2 s\}$, order $4$. Hence the number of conjugates is $8/4 = 2$, namely $\langle s\rangle$ and $\langle r^2 s\rangle$.
\textit{Check.} $2 \mid 8$; $\langle s\rangle$ is not normal (the count exceeds $1$), and indeed conjugating gives $\langle r^2 s\rangle$. Consistent.
\end{wex}

\begin{wex}{Conjugates of $\langle (1\,2)\rangle$ in $S_3$}
Count the subgroups of $S_3$ conjugate to $H = \langle (1\,2)\rangle$.
\wrec $[S_3:N_{S_3}(H)]$; find which elements normalize $H$.
\wsol $N_{S_3}(H) \supseteq H = \{e,(1\,2)\}$, order $2$. A $3$-cycle conjugates $(1\,2)$ to a different transposition (e.g.\ $(1\,2\,3)(1\,2)(1\,3\,2) = (2\,3)$), so no $3$-cycle normalizes $H$; thus $N_{S_3}(H) = H$, order $2$, and the number of conjugates is $6/2 = 3$: namely $\langle (1\,2)\rangle,\langle (1\,3)\rangle,\langle (2\,3)\rangle$.
\textit{Check.} $3 \mid 6$; there are exactly three order-$2$ subgroups in $S_3$ and they are all conjugate -- matches.
\end{wex}

\begin{wex}{A normal subgroup has one conjugate}
Count the conjugates of $A_3 = \langle (1\,2\,3)\rangle$ in $S_3$.
\wrec Number of conjugates $=1 \Longleftrightarrow H \nor G \Longleftrightarrow N_G(H) = G$.
\wsol $A_3$ has index $2$ in $S_3$, hence is normal, so $N_{S_3}(A_3) = S_3$ and the number of conjugates is $6/6 = 1$. Directly: conjugating a $3$-cycle gives a $3$-cycle, so $gA_3 g^{-1} = A_3$ for all $g$.
\textit{Check.} index-$2$ subgroups are always normal; count $1$ as expected.
\end{wex}

\begin{wex}{Conjugates of a Sylow $2$-subgroup of $S_4$}
Count the subgroups of $S_4$ conjugate to a Sylow $2$-subgroup $P$ ($|P| = 8$), and identify $N_{S_4}(P)$.
\wrec $[S_4:N_{S_4}(P)]$ gives the count; for a Sylow subgroup the count is also the Sylow number $n_2$.
\wsol $|S_4| = 24 = 2^3\cdot 3$, so $|P| = 8$ and $[S_4:P] = 3$. Since $P \le N_{S_4}(P) \le S_4$, the order $|N_{S_4}(P)|$ is a multiple of $8$ dividing $24$, so it is $8$ or $24$. $P$ is not normal in $S_4$ (e.g.\ $S_4$ has more than one Sylow $2$-subgroup), so $|N_{S_4}(P)| \ne 24$; thus $N_{S_4}(P) = P$, order $8$, and the number of conjugates is $24/8 = 3$.
\textit{Check.} $3 \mid 24$; $n_2 = 3 \equiv 1 \pmod 2$ and $3 \mid 3$, consistent with Sylow's theorem. So $S_4$ has exactly three Sylow $2$-subgroups, all conjugate.
\end{wex}

\begin{wex}{Conjugates of $\langle i\rangle$ in $Q_8$}
Count the conjugates of $H = \langle i\rangle = \{1,-1,i,-i\}$ in $Q_8$.
\wrec $[Q_8:N_{Q_8}(H)]$; index-$2$ subgroups are normal.
\wsol $|H| = 4$ and $[Q_8:H] = 8/4 = 2$, so $H$ has index $2$ and is therefore normal: $N_{Q_8}(H) = Q_8$. The number of conjugates is $8/8 = 1$.
\textit{Check.} Every index-$2$ subgroup is normal, so a single conjugate -- and indeed $\langle i\rangle,\langle j\rangle,\langle k\rangle$ are three \emph{distinct} normal subgroups, each its own sole conjugate. Consistent.
\end{wex}

\begin{remark}
Proposition~\ref{prop:numconj@c4} is the engine behind Sylow's theorems: applying it to a Sylow $p$-subgroup $P$ shows the number of Sylow $p$-subgroups is $[G:N_G(P)]$, which combined with a counting argument yields $n_p \equiv 1 \pmod p$ and $n_p \mid |G|$. Conjugation -- of elements and of subgroups -- is thus the common thread running from the class equation through the structure of $p$-groups to the Sylow theory of the next section.
\end{remark}

\begin{remark}
$\Aut(G)$ records the symmetries of $G$ \emph{as a group}, not merely as a set: an
automorphism must preserve the multiplication, so it permutes elements of each order among
themselves and fixes $e$. If $|G|=n$ then $\Aut(G)\sgr S_n$, so $|\Aut(G)|$ divides $n!$, but
in practice it is far smaller because of these constraints.
\end{remark}

\begin{method}{Computing $\Aut(G)$ by hand}
\textit{Trigger.} ``find all automorphisms of this concrete (small or generated) group.''
\begin{enumerate}
\item An automorphism is determined by where it sends a \emph{generating set}; so list
  generators and where each can go.
\item A generator of order $k$ must map to an element of order $k$ (automorphisms preserve
  order). This bounds the possibilities.
\item Each candidate assignment that \emph{respects the defining relations} extends to a
  homomorphism; injectivity/surjectivity on a finite group then make it an automorphism.
\item Count the survivors; identify the group structure on $\Aut(G)$ (orders of the
  automorphisms, whether they commute) and match it to a known group.
\end{enumerate}
\end{method}

\begin{remark}
The quotient $\Aut(G)/\Inn(G)$ is the \emph{outer automorphism group} $\operatorname{Out}(G)$.
When every automorphism is inner (e.g.\ $G=S_n$ for $n\ne 6$, and the case $S_3$ above),
$\operatorname{Out}(G)=1$ and $\Aut(G)\cong G/Z(G)$.
\end{remark}

\begin{method}{Using $\Inn(G)\cong G/Z(G)$}
\textit{Trigger.} You want $\Inn(G)$, or you want a lower bound on $\Aut(G)$, or you must show
two conjugation maps are equal/distinct.
\begin{enumerate}
\item Compute $Z(G)$.
\item Then $\Inn(G)\cong G/Z(G)$ as groups; in particular $|\Inn(G)|=[G:Z(G)]$.
\item $\psi_g=\psi_h$ \emph{iff} $gh^{-1}\in Z(G)$; so inner automorphisms are parametrized by
  cosets of $Z(G)$.
\item Since $\Inn(G)\pnor\Aut(G)$, $|\Inn(G)|$ divides $|\Aut(G)|$ --- a quick consistency
  check.
\end{enumerate}
\end{method}

\begin{wex}{Distinguishing inner automorphisms by cosets}
In $D_8$ decide whether $\psi_r$ and $\psi_{r^3}$ are the same automorphism.
\wrec Two conjugations coincide iff the elements differ by a central factor: $\psi_g=\psi_h
\iff gh^{-1}\in Z(G)$.
\wsol $r(r^3)^{-1}=r\cdot r=r^2\in Z(D_8)$, so $\psi_r=\psi_{r^3}$. By contrast
$r\cdot 1^{-1}=r\notin Z(D_8)$, so $\psi_r\ne\psi_1=\id$.
\textit{Check.} Cosets of $Z(D_8)=\{1,r^2\}$ are $\{1,r^2\},\{r,r^3\},\{s,r^2s\},\{rs,r^3s\}$;
$r$ and $r^3$ share a coset, matching $\psi_r=\psi_{r^3}$, and there are $4$ cosets, matching
$|\Inn(D_8)|=4$. \checkmark
\end{wex}

\begin{pitfall}
$\Inn(G)\cong G/Z(G)$, \emph{not} $G$ in general. Forgetting the center collapses
distinct group elements to the same automorphism: in $D_8$, $r$ and $r^3$ give the same
conjugation. Also $\Inn(G)$ can be much smaller than $\Aut(G)$ --- abelian groups have
$\Inn(G)=1$ but often large $\Aut(G)$.
\end{pitfall}

\begin{proposition}[char $\Longrightarrow$ normal, and transitivity]
Let $H\sgr G$.
\begin{enumerate}
\item If $H\ \mathrm{char}\ G$ then $H\nor G$.
\item If $K\ \mathrm{char}\ H$ and $H\nor G$ then $K\nor G$.
\item If $K\ \mathrm{char}\ H$ and $H\ \mathrm{char}\ G$ then $K\ \mathrm{char}\ G$.
\end{enumerate}
\end{proposition}

\begin{method}{Proving $H\ \mathrm{char}\ G$}
\textit{Trigger.} ``show $H$ is preserved by every automorphism,'' or you need ``$K\nor G$''
where $K\nor H\nor G$.
\begin{enumerate}
\item Best route: describe $H$ by a property that automorphisms must preserve (order of
  elements, being the center, being generated by all commutators, the unique subgroup of a
  given order, etc.).
\item Then any $\sigma\in\Aut(G)$ sends that distinguished set to itself, so $\sigma(H)=H$.
\item Remember char $\Longrightarrow$ normal, and char is transitive --- use these to upgrade normality.
\end{enumerate}
\end{method}

\begin{theorem}
For each $n\ge1$, $\Aut(\mathbb{Z}_n)\cong(\mathbb{Z}/(n)\mathbb{Z})^{\times}$, the multiplicative group of units modulo $n$. In
particular $|\Aut(\mathbb{Z}_n)|=\varphi(n)$, and $\Aut(\mathbb{Z}_n)$ is abelian.
\end{theorem}

\begin{method}{Computing $\Aut(\mathbb{Z}_n)$}
\textit{Trigger.} Cyclic group; ``find/describe its automorphism group.''
\begin{enumerate}
\item $\Aut(\mathbb{Z}_n)\cong(\mathbb{Z}/(n)\mathbb{Z})^{\times}$, an abelian group of order $\varphi(n)$.
\item To get its \emph{structure}, use the CRT factorization
  $(\mathbb{Z}/(n)\mathbb{Z})^{\times}\cong\prod_p(\mathbb{Z}/(p^{k})\mathbb{Z})^{\times}$ over prime powers $p^k\,\|\,n$, with
  $(\mathbb{Z}/(p^k)\mathbb{Z})^{\times}$ cyclic of order $p^{k-1}(p-1)$ for odd $p$, and
  $(\mathbb{Z}/(2)\mathbb{Z})^{\times}\cong 1,\ (\mathbb{Z}/(4)\mathbb{Z})^{\times}\cong\mathbb{Z}_2,\ (\mathbb{Z}/(2^k)\mathbb{Z})^{\times}\cong\mathbb{Z}_2\times\mathbb{Z}_{2^{k-2}}\ (k\ge3)$.
\end{enumerate}
\end{method}

\begin{theorem}
$\Aut(V_4)\cong S_3$; equivalently $|\Aut(V_4)|=6$.
\end{theorem}

\begin{method}{Automorphisms of an elementary abelian group}
\textit{Trigger.} $G\cong(\mathbb{Z}_p)^k$ (elementary abelian $p$-group).
\begin{enumerate}
\item View $G$ as a vector space $\F_p^{\,k}$; group automorphisms $=$ linear automorphisms.
\item So $\Aut\bigl((\mathbb{Z}_p)^k\bigr)\cong\GL_k(\F_p)$, of order
  $(p^k-1)(p^k-p)\cdots(p^k-p^{k-1})$ (count ordered bases).
\item For $k=2,p=2$ this gives $6$, i.e.\ $S_3$.
\end{enumerate}
\end{method}

\begin{proof}
$Z(G)=G$ when $G$ is abelian, so $\Inn(G)\cong G/Z(G)=G/G=1$. Hence
$\operatorname{Out}(G)=\Aut(G)/\Inn(G)=\Aut(G)$.
\end{proof}

This subgroup was defined by J.\ Thompson in 1964 and it now plays a pivotal role in the study of finite groups, in particular, in the classification of finite simple groups. For any finite group $P$ let $d(P)$ be the minimum number of generators of $P$ (so, for example, $d(P) = 1$ if and only if $P$ is a nontrivial cyclic group and $d(Q_8) = 2$). Let $m(P)$ be the maximum of the integers $d(A)$ as $A$ runs over all abelian subgroups of $P$ (so, for example, $m(Q_8) = 1$ and $m(D_8) = 2$). Define
\[ J(P) = \langle A : A \text{ is an abelian subgroup of } P \text{ with } d(A) = m(P)\rangle. \]
($J(P)$ is called the \emph{Thompson subgroup} of $P$.)
\begin{enumerate}
\item[(a)] Prove that $J(P)$ is a characteristic subgroup of $P$.
\item[(b)] For each of the following groups $P$ list all abelian subgroups $A$ of $P$ that satisfy $d(A) = m(P)$: $Q_8$, $D_8$, $D_{16}$ and $QD_{16}$ (where $QD_{16}$ is the quasidihedral group of order 16 defined in Exercise 11 of Section 2.5). [Use the lattices of subgroups for these groups in Section 2.5.]
\item[(c)] Show that $J(Q_8) = Q_8$, $J(D_8) = D_8$, $J(D_{16}) = D_{16}$ and $J(QD_{16})$ is a dihedral subgroup of order 8 in $QD_{16}$.
\item[(d)] Prove that if $Q \le P$ and $J(P)$ is a subgroup of $Q$, then $J(P) = J(Q)$. Deduce that if $P$ is a subgroup (not necessarily normal) of the finite group $G$ and $J(P)$ is contained in some subgroup $Q$ of $P$ such that $Q \nor G$, then $J(P) \nor G$.
\end{enumerate}
\end{exers}

\begin{remark}
A Sylow $p$-subgroup is exactly a $p$-subgroup whose index in $G$ is coprime to $p$: if
$\ord P = p^a$ then $[G:P] = m$ with $p \nmid m$, and conversely a $p$-subgroup of
$p$-free index must have order $p^a$. Sylow's first theorem asserts these are never vacuous.
\end{remark}

\begin{corollary}[Normality criterion]\label{cor:normal@c4}
A Sylow $p$-subgroup $P$ is normal in $G$ if and only if $n_p = 1$ (equivalently
$N_G(P) = G$). More generally $P \nor G$ iff $P$ is the unique Sylow $p$-subgroup.
\end{corollary}

\begin{proof}
By Theorem~\ref{thm:sylow@c4}(2) all Sylow $p$-subgroups are conjugate, so $P \nor G$
($\iff$ $gPg^{-1} = P$ for all $g$) is equivalent to $P$ having no distinct conjugate, i.e.\
$n_p = 1$. The reformulation $n_p = [G:N_G(P)] = 1 \iff N_G(P) = G \iff P \nor G$ is
immediate.
\end{proof}

\begin{method}{Reading off $n_p$ from the constraints}
\textit{Trigger.} You know $\ord G = p^a m$ ($p \nmid m$) and want the possible values of
$n_p$, usually to find a normal Sylow subgroup or to rule out simplicity.

\textit{Recipe.}
\begin{enumerate}
\item Factor $\ord G = p^a m$ for the prime $p$ of interest.
\item List the positive divisors $d$ of $m$ (these are the candidates from $n_p \mid m$).
\item Keep only those $d$ with $d \equiv 1 \pmod p$. The surviving list is the complete set of
\emph{a priori} possibilities for $n_p$.
\item If $1$ is the only survivor, then $n_p = 1$: the Sylow $p$-subgroup is normal
(Corollary~\ref{cor:normal@c4}).
\item If more than one survives, combine with counting of elements (next method) or with
information about $N_G(P)$.
\end{enumerate}
\end{method}

\begin{method}{Counting elements to force a normal Sylow ($n_p$ non-simplicity recipe)}
\textit{Trigger.} You want to prove $G$ (of known order $p^a m \cdots$) is \emph{not simple}, or
that some Sylow subgroup is normal.
\textit{Recipe.}
\begin{enumerate}
\item For each prime, list the legal $n_p$ via the Method box ($n_p \mid m$, $n_p \equiv 1
\pmod p$). If any prime forces $n_p = 1$, that Sylow subgroup is normal --- stop.
\item Otherwise take a prime $q$ whose Sylow subgroups have \emph{prime} order $q$ (so distinct
ones meet trivially). If $n_q > 1$ they occupy $n_q (q-1)$ nonidentity elements. Add up the
forced element counts for several primes; if they exceed $\ord G - 1$ you get a contradiction,
pinning some $n_p$ to $1$.
\item If element-counting is inconclusive (Sylows overlap), use the \emph{coset action}: act on
the $[G:N_G(P)] = n_p$ Sylow $p$-subgroups, giving $\varphi\colon G \to S_{n_p}$. If
$\ord G \nmid n_p!$ the kernel is a nontrivial proper normal subgroup.
\end{enumerate}
\end{method}

\begin{pitfall}
$n_p \equiv 1 \pmod p$ does \emph{not} say $n_p$ is odd or prime --- it is congruent to $1$
modulo $p$ specifically. For $p = 2$ the congruence $n_2 \equiv 1 \pmod 2$ only says $n_2$ is
odd, which is weak; lean on $n_2 \mid m$ instead. Always intersect \emph{both} conditions.
\end{pitfall}

\begin{pitfall}
$n_p = [G:N_G(P)]$, \emph{not} $[G:P]$. These agree only when $N_G(P) = P$ (i.e.\ $P$
is self-normalizing). Confusing them gives wrong counts; e.g.\ in $S_4$, $[S_4:P_2] = 3 =
n_2$ because the Sylow $2$ is self-normalizing, but for the Sylow $3$, $[S_4:P_3] = 8 \ne 4
= n_3$ since $N_{S_4}(P_3) = S_3$ has order $6 > 3$.
\end{pitfall}

\begin{definition}[Simple group]
A group $G\neq\{1\}$ is \emph{simple} if its only normal subgroups are $\{1\}$ and $G$.
\end{definition}

\begin{proposition}[Splitting criterion in $A_n$]\label{prop:split@c4}
Let $\sigma\in A_n$ with $S_n$-conjugacy class $K$. Then:
\begin{itemize}
\item[(a)] If $C_{S_n}(\sigma)\not\subseteq A_n$ (i.e.\ \emph{some} odd permutation commutes with $\sigma$), then $K$ is a single $A_n$-class.
\item[(b)] If $C_{S_n}(\sigma)\subseteq A_n$ (i.e.\ \emph{every} permutation commuting with $\sigma$ is even), then $K$ splits into two $A_n$-classes of equal size $|K|/2$.
\end{itemize}
Concretely, $K$ splits iff the cycle type of $\sigma$ consists of \emph{distinct odd-length cycles} (each part odd, no part repeated, fixed points counting as $1$-cycles).
\end{proposition}

\begin{method}{Counting conjugacy classes of $A_n$}
\textit{Trigger.} You need the class sizes of $A_n$ (e.g.\ to test simplicity).\\
\textit{Recipe.}
\begin{enumerate}
\item List the cycle types appearing in $A_n$ (even permutations only: an $\ell$-cycle is even iff $\ell$ is odd, so a permutation is even iff total length minus number of cycles is even).
\item For each type compute the $S_n$-class size $\dfrac{n!}{\prod_i \ell_i \cdot \prod_\ell m_\ell!}$ where $m_\ell$ is the number of $\ell$-cycles.
\item Apply Proposition~\ref{prop:split@c4}: the type \emph{splits} into two halves iff its parts are \emph{distinct and all odd}; otherwise it stays one class.
\item Sanity check: the class sizes sum to $|A_n|=n!/2$, and every class size divides $|A_n|$.
\end{enumerate}
\end{method}

\begin{theorem}[Simplicity of $A_5$]\label{thm:a5@c4}
$A_5$ is a simple group of order $60$.
\end{theorem}

\begin{pitfall}
The two classes of $5$-cycles are \emph{genuinely distinct in $A_5$}: e.g.\ $(1\,2\,3\,4\,5)$ and $(1\,3\,5\,2\,4)=(1\,2\,3\,4\,5)^2$ are not conjugate by any even permutation, though they are conjugate in $S_5$ (by the odd permutation $(2\,3\,5\,4)$, which checks: $(2\,3\,5\,4)(1\,2\,3\,4\,5)(2\,3\,5\,4)^{-1}=(1\,3\,5\,2\,4)$). Forgetting the split and lumping the $5$-cycles into a single class of $24$ is simply wrong: the $A_5$-class of a $5$-cycle has size $12$, not $24$. Always apply the splitting criterion before reading off class sizes.
\end{pitfall}

\begin{method}{Proving a specific group is simple by class sizes}
\textit{Trigger.} A finite group $G$ whose conjugacy-class sizes you can list.\\
\textit{Recipe.}
\begin{enumerate}
\item Compute all class sizes; verify they sum to $|G|$.
\item A normal subgroup has order $=$ (a sub-sum of class sizes that \emph{includes the class $\{1\}$}) and that order must divide $|G|$ (Lagrange).
\item Enumerate sub-sums containing $1$; check which divide $|G|$.
\item If only $1$ and $|G|$ survive, $G$ is simple.
\end{enumerate}
\textbf{Why it works:} $N\nor G\Longrightarrow N$ is a union of classes; $1\in N$; $|N|\mid|G|$.
\end{method}

\begin{lemma}[$3$-cycles generate $A_n$]\label{lem:3cyc@c4}
For $n\ge 3$, $A_n=\langle \,3\text{-cycles}\,\rangle$.
\end{lemma}

\begin{proof}
Every element of $A_n$ is a product of an even number of transpositions. It suffices to show a product of two transpositions is a product of $3$-cycles. Two cases for $(a\,b)(c\,d)$:
\begin{itemize}
\item Share a point: $(a\,b)(a\,c)=(a\,c\,b)$, already a $3$-cycle.
\item Disjoint: insert $(b\,c)(b\,c)=1$ to get
\[
(a\,b)(c\,d)=(a\,b)\,(b\,c)\cdot(b\,c)\,(c\,d)=(a\,b\,c)\,(b\,c\,d),
\]
using $(a\,b)(b\,c)=(a\,b\,c)$ and $(b\,c)(c\,d)=(b\,c\,d)$ --- a product of two $3$-cycles.
\end{itemize}
Since $A_n$ is generated by such pairs, it is generated by $3$-cycles.
\end{proof}

\begin{method}{Reducing an even permutation to $3$-cycles}
\textit{Trigger.} You must express something in $A_n$ via $3$-cycles, or show a subgroup containing all $3$-cycles is $A_n$.\\
\textit{Recipe.}
\begin{enumerate}
\item Write the permutation as a product of transpositions (even count, since it's in $A_n$).
\item Pair the transpositions. For a pair sharing a point use $(a\,b)(a\,c)=(a\,c\,b)$.
\item For a disjoint pair $(a\,b)(c\,d)$, insert $(b\,c)(b\,c)=1$ to split into two overlapping pairs $=(a\,b\,c)(b\,c\,d)$.
\end{enumerate}
\textit{Sanity check.} Verify the resulting product on a couple of points (evaluating right-to-left).
\end{method}

\begin{pitfall}
Cycle products must be evaluated \emph{right-to-left} (our convention), and orientation matters: $(a\,b)(b\,c)=(a\,b\,c)$ while $(a\,b)(a\,c)=(a\,c\,b)$. When you derive a factorization symbolically, always re-verify by tracking each point through the final product. For instance $(1\,2)(3\,4)=(1\,2\,3)(2\,3\,4)$, confirmed point-by-point above.
\end{pitfall}

\begin{theorem}[Simplicity of $A_n$, $n\ge 5$]\label{thm:an@c4}
For every $n\ge 5$, the alternating group $A_n$ is simple.
\end{theorem}

\begin{remark}
The hypothesis $n\ge 5$ is essential. $A_4$ is \emph{not} simple: its subgroup
\[ V=\{e,(1\,2)(3\,4),(1\,3)(2\,4),(1\,4)(2\,3)\}\cong V_4 \]
has order $4\mid 12$ and is closed under $A_4$-conjugation (the three double transpositions form a single $A_4$-class of size $3$, and $3+1=4=|V|$), so $V\nor A_4$. The argument above fails at $n=4$ precisely because in Step 1 there is no transposition disjoint from a given $3$-cycle's support, and the double transpositions close up into a proper normal subgroup.
\end{remark}

\begin{method}{Showing every nontrivial $N\nor A_n$ contains a $3$-cycle (commutator trick)}
\textit{Trigger.} Proving $A_n$ ($n\ge5$) simple, Step 2.\\
\textit{Recipe.}
\begin{enumerate}
\item Pick $1\neq\sigma\in N$ moving the fewest points.
\item Choose a $3$-cycle $\tau$ overlapping the support of $\sigma$ cleverly; form $\sigma'=\sigma\,\tau\sigma^{-1}\tau^{-1}\in N$ (in $N$ by normality).
\item Show $\sigma'\neq 1$ yet $\sigma'$ fixes strictly more points than $\sigma$.
\item Minimality forces $\sigma$ to already be a $3$-cycle.
\end{enumerate}
\textit{Check.} A $3$-cycle on $n\ge 5$ points fixes $n-3\ge 2$ points; the trick can only terminate at one.
\end{method}

\begin{definition}[Isometry]
An \emph{isometry} of $\mathbb{R}^n$ is a distance-preserving map $f\colon \mathbb{R}^n \to \mathbb{R}^n$, i.e.\ $\lvert f(u) - f(v)\rvert = \lvert u - v\rvert$ for all $u,v \in \mathbb{R}^n$. The set of all isometries of $\mathbb{R}^n$ is a group under composition, denoted $M_n$ (write $M$ for $M_2$). An isometry carries a figure to a congruent figure.
\end{definition}

\begin{theorem}[Every isometry is $t_a\varphi$]\label{art:isometries:decomp@c4}
Let $f$ be an isometry of $\mathbb{R}^n$ and put $a = f(0)$. Then $f = t_a\varphi$ for a unique orthogonal operator $\varphi \in \mathrm{O}(n)$. In particular every isometry that fixes the origin is an orthogonal linear operator.
\end{theorem}

\begin{proof}
Set $\varphi = t_{-a}f$, so that $t_a\varphi = f$. As a composition of the isometries $t_{-a}$ and $f$, the map $\varphi$ is an isometry, and $\varphi(0) = t_{-a}(f(0)) = t_{-a}(a) = 0$, so $\varphi$ fixes the origin. An isometry fixing the origin preserves dot products: from $\lvert u-v\rvert^2 = \lvert \varphi(u)-\varphi(v)\rvert^2$ and $\varphi(0)=0$ one expands and cancels $\langle u,u\rangle,\langle v,v\rangle$ to get $\langle \varphi(u),\varphi(v)\rangle = \langle u,v\rangle$. A dot-product-preserving map is forced to be linear (if $w = u+v$ then $\varphi(w)$ and $\varphi(u)+\varphi(v)$ have equal pairwise dot products, hence are equal, and similarly $\varphi(cv) = c\varphi(v)$), so $\varphi$ is an orthogonal linear operator. Uniqueness: any decomposition $f = t_a\varphi$ has $\varphi(0)=0$, so $a = f(0)$ is forced and then $\varphi = t_{-a}f$.
\end{proof}

\begin{remark}
On $\mathbb{R}^2$ the orthogonal operators are exactly the rotations $\rho_\theta$ about the origin and the reflections $\rho_\theta r$ about lines through the origin, where $r$ is reflection in the $x$-axis. Thus by Theorem~\ref{art:isometries:decomp@c4} every plane isometry is $m = t_v\rho_\theta$ (when $\det\varphi = +1$) or $m = t_v\rho_\theta r$ (when $\det\varphi = -1$), for a uniquely determined vector $v$ and angle $\theta$. The map $\pi\colon M \to \mathrm{O}(2)$ dropping the translation part, $\pi(t_v\varphi) = \varphi$, is a surjective homomorphism with kernel the translation subgroup $T = \{t_v\}$, so $T \nor M$ and $M/T \cong \mathrm{O}(2)$.
\end{remark}

\begin{proof}
The first row is immediate: $t_v t_w(x) = x+w+v$; rotations about a fixed center add their angles; and $r$ is its own inverse. For the second row, apply $\varphi t_a = t_{\varphi(a)}\varphi$ with $\varphi = \rho_\theta$ and with $\varphi = r$. Finally $r\rho_\theta = \rho_{-\theta}r$ follows from the matrices: $r = \begin{psmallmatrix}1&0\\0&-1\end{psmallmatrix}$ conjugates the rotation matrix $\begin{psmallmatrix}c&-s\\s&c\end{psmallmatrix}$ ($c=\cos\theta,\ s=\sin\theta$) to $\begin{psmallmatrix}c&s\\-s&c\end{psmallmatrix}$, which is $\rho_{-\theta}$.
\end{proof}

\begin{method}{Reducing a product to normal form $t_v\rho_\theta$ or $t_v\rho_\theta r$}
\textit{Trigger.} You must compose isometries and name the result's type.
\begin{enumerate}
\item Write each factor as $t_v\rho_\theta$ or $t_v\rho_\theta r$.
\item Move all translations to the \emph{left} using $\rho_\theta t_v = t_{\rho_\theta(v)}\rho_\theta$ and $r t_v = t_{r(v)} r$; collect rotations with $\rho_\alpha\rho_\beta = \rho_{\alpha+\beta}$ and use $r\rho_\theta = \rho_{-\theta}r$, $r^2 = 1$ to leave at most one $r$ on the right.
\item Read off the result: $t_v\rho_\theta$ (orientation-preserving) or $t_v\rho_\theta r$ (orientation-reversing).
\item \textit{Check.} Orientation $= \det$ of the linear part $= (+1)$ for $\rho_\theta$, $(-1)$ for $\rho_\theta r$; it must equal the product of the input orientations.
\end{enumerate}
\end{method}

