\begin{pitfall}
The presence of $n$-fold rotational symmetry does \emph{not} by itself make the group $D_n$. Only
a figure that also admits a mirror line is dihedral; a chiral figure (like the pinwheel) with
$n$-fold rotation has the smaller group $C_n$ of order $n$, not $D_n$ of order $2n$. Always test
for an orientation-reversing symmetry before naming the group.
\end{pitfall}

\begin{definition}[Discrete group of isometries]
A subgroup $G\sgr M$ is \emph{discrete} if there is a real number $\varepsilon>0$ such that:
\begin{enumerate}
\item[(i)] if $t_a\in G$ is a translation by a nonzero vector $a$, then $\lvert a\rvert\ge\varepsilon$, and
\item[(ii)] if $g\in G$ is a rotation through a nonzero angle $\theta$ about some point of $P$, then $\lvert\theta\rvert\ge\varepsilon$.
\end{enumerate}
\end{definition}

\begin{remark}
The same $\varepsilon$ governs both vectors and angles; we do not care about optimal bounds, only that one positive bound works for all nonzero translations and rotations at once. No condition is imposed on the orientation-reversing isometries: if $m$ is a glide with glide vector $w$, then $m^2=t_{2w}$ is a translation, so the bound on translation lengths already controls the glides.
\end{remark}

\begin{remark}
Discreteness of $L$ is equivalently a \emph{separation} statement: distinct $a,b\in L$ satisfy $\lvert b-a\rvert\ge\varepsilon$, because $b-a\in L$ and $\lvert b-a\rvert\ge\varepsilon$ by hypothesis. So the points of a discrete $L$ are uniformly spread out, never accumulating.
\end{remark}

\begin{lemma}[Minimal vector]\label{art:discrete_groups:minvec@c4}
Let $L\sgr V$ be discrete.
\begin{enumerate}
\item[(a)] Any bounded region of the plane contains only finitely many points of $L$.
\item[(b)] If $L\ne\{0\}$, it contains a nonzero vector of \emph{minimal length}.
\end{enumerate}
\end{lemma}

\begin{proof}
(a) The points of $L$ are pairwise at distance $\ge\varepsilon$, so a square of side $<\varepsilon/2$ contains at most one point of $L$ (any two would be within distance $<\varepsilon$). A bounded region lies inside some large rectangle, which is covered by finitely many such squares; hence it meets $L$ in finitely many points.

(b) Pick any nonzero $a\in L$. The closed disk of radius $\lvert a\rvert$ about the origin is bounded, so by (a) it contains only finitely many points of $L$, among them $a$. Finitely many nonzero lengths occur, so a smallest one is attained; the corresponding vector is a nonzero vector of minimal length.
\end{proof}

\begin{lemma}[Fundamental domain]\label{art:discrete_groups:funddom@c4}
Let $B=(u,w)$ be a basis of $\mathbb{R}^2$ and let $L=\mathbb{Z} u+\mathbb{Z} w$ be the lattice of integer combinations. Every $v\in\mathbb{R}^2$ is written \emph{uniquely} as $v=x+v_0$ with $x\in L$ and $v_0\in\Pi'(B)$.
\end{lemma}

\begin{proof}
Since $B$ is a basis, $v=ru+sw$ for unique reals $r,s$. Split off integer parts: $r=m+r_0$, $s=n+s_0$ with $m,n\in\mathbb{Z}$ and $0\le r_0,s_0<1$. Then $v=x+v_0$ with $x=mu+nw\in L$ and $v_0=r_0u+s_0w\in\Pi'(B)$. Uniqueness: if $x+v_0=x'+v_0'$ with $x,x'\in L$ and $v_0,v_0'\in\Pi'(B)$, then $v_0-v_0'=x'-x\in L$ has integer coordinates in $B$, yet each coordinate lies strictly between $-1$ and $1$; the only such integer is $0$, so $v_0=v_0'$ and $x=x'$.
\end{proof}

\begin{theorem}[Classification of discrete subgroups of the plane]\label{art:discrete_groups:classify@c4}
Every discrete subgroup $L\sgr V$ (equivalently $L\sgr\mathbb{R}^2$) is exactly one of:
\begin{enumerate}
\item[(a)] the trivial group $L=\{0\}$;
\item[(b)] an infinite cyclic group $L=\mathbb{Z} a=\{\,ma \st m\in\mathbb{Z}\,\}$ for some nonzero $a$; or
\item[(c)] a \emph{lattice} $L=\mathbb{Z} a+\mathbb{Z} b=\{\,ma+nb \st m,n\in\mathbb{Z}\,\}$ for two linearly independent $a,b$.
\end{enumerate}
In case (c), $(a,b)$ is called a \emph{lattice basis}.
\end{theorem}

\begin{proof}
The trivial group is case (a). Assume $L\ne\{0\}$, and split on whether $L$ spans a line.

\emph{Case 1: all of $L$ lies on a line $\ell$ through the origin.} Identify $\ell$ with $\mathbb{R}$; then $L\sgr\mathbb{R}$ is discrete, so by Lemma~\ref{art:discrete_groups:minvec@c4} it has a shortest nonzero vector $a$. If some $v\in L$ were not an integer multiple of $a$, subtract the nearest multiple: $v-ma\in L$ would be nonzero with $\lvert v-ma\rvert<\lvert a\rvert$, contradicting minimality. Hence $L=\mathbb{Z} a$, case (b).

\emph{Case 2: $L$ does not lie on a line.} Then $L$ contains independent vectors, so we may choose coordinates with $a=(1,0)^t$ a shortest nonzero vector of $L$ on the horizontal axis $\ell$ (using Case~1 on $L\cap\ell=\mathbb{Z} a$). Among the vectors of $L$ with positive second coordinate, choose $b=(b_1,b_2)^t$ with $b_2$ \emph{as small as possible}; adding a multiple of $a$ we may also take $0\le b_1<1$. This $b$ exists: such vectors with $0\le b_1<1$ and $b_2$ bounded above by any fixed candidate lie in a bounded region, which meets $L$ finitely often by Lemma~\ref{art:discrete_groups:minvec@c4}(a).

Set $\widetilde L=\mathbb{Z} a+\mathbb{Z} b\subseteq L$; we show $\widetilde L=L$. By Lemma~\ref{art:discrete_groups:funddom@c4} applied to $B=(a,b)$, it suffices to show the only point of $L$ in $\Pi'(B)$ is $0$. Let $c=(c_1,c_2)^t\in L\cap\Pi'(B)$, so $0\le c_2<b_2$. Minimality of $b_2$ forces $c_2=0$, so $c$ lies on $\ell$, hence $c\in\mathbb{Z} a$; but $0\le c_1<1$ leaves only $c=0$. Therefore $L=\mathbb{Z} a+\mathbb{Z} b$ is a lattice, case (c).
\end{proof}

