Type: pitfall
Content:
\begin{pitfall}
The fixed-point count $\lvert\Fix(g)\rvert = c^{\operatorname{cyc}(g)}$ uses the cycle
decomposition of $g$ on the slots being colored (faces, beads), not on the vertices
or on abstract group elements. Using the wrong action's cycle type is the most common error;
always fix in your mind which set $S$ the group is permuting before counting cycles.
\end{pitfall}

latex:
\begin{pitfall}
The fixed-point count $\lvert\Fix(g)\rvert = c^{\operatorname{cyc}(g)}$ uses the cycle
decomposition of $g$ \emph{on the slots being colored} (faces, beads), \emph{not} on the vertices
or on abstract group elements. Using the wrong action's cycle type is the most common error;
always fix in your mind which set $S$ the group is permuting before counting cycles.
\end{pitfall}

\begin{pitfall}
Burnside counts orbits of the \emph{exact} group you average over. Including reflections
(dihedral) versus rotations only (cyclic) generally gives different answers; the necklace
examples above happened to agree, but for larger bead counts they diverge. Decide first whether
mirror images count as ``the same.''
\end{pitfall}

\begin{proposition}[It is a group; its order]\label{prop:dp-group@c5}
$G=G_1\times\cdots\times G_n$ is a group, and if every $G_i$ is finite then
\[
\ord{G}=\ord{G_1}\cdot\ord{G_2}\cdots\ord{G_n}=\prod_{i=1}^{n}\ord{G_i}.
\]
\end{proposition}

\begin{method}{Computing in a direct product}
\textit{Trigger.} The group is presented as a product $G_1\times\cdots\times G_n$, or you
must count its elements.
\begin{enumerate}
\item Work \emph{slot by slot}: multiply, invert, and reduce each coordinate inside its own
$G_i$. Coordinates never interact.
\item For the order of the group, multiply the orders: $\prod_i\ord{G_i}$.
\item Identity is the tuple of identities; inverse is the tuple of inverses.
\end{enumerate}
\end{method}

\begin{method}{Order of $(g_1,\dots,g_n)$}
\textit{Trigger.} You are asked for the order of a specific tuple, or the largest possible
order of an element.
\begin{enumerate}
\item Find each coordinate order $\ord{g_i}$ separately (in $\mathbb{Z}/(m)\mathbb{Z}$, $\ord{a}=m/\gcd(a,m)$).
\item Take the \textbf{lcm} of those numbers --- \emph{not} the product, and \emph{not} the
sum.
\item For the \emph{largest element order} in $\mathbb{Z}/(m_1)\mathbb{Z}\times\cdots\times\mathbb{Z}/(m_n)\mathbb{Z}$, the
exponent of the group is $\lcm(m_1,\dots,m_n)$; an element of that order exists (take a
generator in each slot), so the maximum equals $\lcm(m_1,\dots,m_n)$.
\end{enumerate}
\end{method}

\begin{wex}{Order in $\mathbb{Z}/(12)\mathbb{Z}\times\mathbb{Z}/(18)\mathbb{Z}$}
Problem. Find $\ord{(8,15)}$ in $\mathbb{Z}/(12)\mathbb{Z}\times\mathbb{Z}/(18)\mathbb{Z}$.
\wrec Coordinatewise orders via $m/\gcd(a,m)$, then $\lcm$.
\wsol In $\mathbb{Z}/(12)\mathbb{Z}$: $\gcd(8,12)=4$, so $\ord{8}=12/4=3$. In $\mathbb{Z}/(18)\mathbb{Z}$: $\gcd(15,18)=3$, so
$\ord{15}=18/3=6$. Hence $\ord{(8,15)}=\lcm(3,6)=6$. \textit{Check.}
$6\cdot(8,15)=(48,90)=(0,0)$ since $48=4\cdot12$ and $90=5\cdot18$; and
$3\cdot(8,15)=(24,45)=(0,9)\ne(0,0)$, so the order exceeds $3$, consistent with $6$.
\end{wex}

\begin{wex}{Order of a permutation/quaternion pair}
Problem. In $D_8\times Q_8$ find the order of $(r,i)$, where $r$ is the rotation of order $4$
in $D_8$ ($n=4$) and $i\in Q_8$.
\wrec Order of a tuple is the lcm of coordinate orders; read off $\ord{r}=4$ and $\ord{i}=4$.
\wsol In $D_8$ we have $r^4=1$ and $r,r^2,r^3\ne1$, so $\ord{r}=4$. In $Q_8$, $i^2=-1$ and
$i^4=1$ with $i,i^2,i^3\ne1$, so $\ord{i}=4$. Thus $\ord{(r,i)}=\lcm(4,4)=4$. \textit{Check.}
$(r,i)^4=(r^4,i^4)=(1,1)$ and $(r,i)^2=(r^2,i^2)=(r^2,-1)\ne(1,1)$, so the order is exactly
$4$.
\end{wex}

\begin{method}{Is $\mathbb{Z}/(m_1)\mathbb{Z}\times\cdots\times\mathbb{Z}/(m_k)\mathbb{Z}$ cyclic?}
\textit{Trigger.} A product of cyclic groups; you must decide if it is cyclic, or identify it
as some $\mathbb{Z}/(N)\mathbb{Z}$.
\begin{enumerate}
\item Compute $E=\lcm(m_1,\dots,m_k)$ and $N=m_1\cdots m_k$ (the group order).
\item Cyclic \Longleftrightarrow\ $E=N$ \Longleftrightarrow\ the $m_i$ are \emph{pairwise} coprime. If so, the group
$\cong\mathbb{Z}/(N)\mathbb{Z}$ and $(1,\dots,1)$ is a generator.
\item If $E<N$ the group is \emph{not} cyclic; the maximum element order is $E$.
\end{enumerate}
\textbf{Pairwise} coprime is essential: $\mathbb{Z}/(2)\mathbb{Z}\times\mathbb{Z}/(3)\mathbb{Z}\times\mathbb{Z}/(3)\mathbb{Z}$ has $\lcm=6<18$, not
cyclic, even though $\gcd(2,3)=1$.
\end{method}

\begin{method}{Mapping into a product}
\textit{Trigger.} You must build (or recognize the unique) homomorphism $T\to G_1\times\cdots
\times G_n$.
\begin{enumerate}
\item Specify the coordinate maps $f_i=\pi_i\circ\varphi:T\to G_i$ separately; each may be any
homomorphism.
\item Assemble $\varphi=(f_1,\dots,f_n)$. By Theorem~\ref{thm:up@c5} this is the only map with
those projections.
\item Kernel: $\ker\varphi=\bigcap_i\ker f_i$, since $\varphi(t)=1\Longleftrightarrow f_i(t)=1$ for all $i$.
\end{enumerate}
\end{method}

\begin{exers}{Additional exercises.}
  \item Let $G_1,G_2$ be groups. Prove directly that $G_1\times\{1\}\nor G_1\times G_2$ and that $(G_1\times G_2)/(G_1\times\{1\})\cong G_2$, by exhibiting $G_1\times\{1\}$ as the kernel of the projection $\pi_2$ and applying the first isomorphism theorem.
  \item Prove that the exponent of $\mathbb{Z}/(m_1)\mathbb{Z}\times\cdots\times\mathbb{Z}/(m_k)\mathbb{Z}$ equals $\lcm(m_1,\dots,m_k)$ and that some element attains it. Deduce that the group is cyclic $\Longleftrightarrow\lcm(m_1,\dots,m_k)=m_1\cdots m_k\Longleftrightarrow$ the $m_i$ are pairwise coprime.
  \item Let $A,B$ be groups, $a\in A$ of order $m$ and $b\in B$ of order $n$. Show that $\langle (a,b)\rangle$ has order $\lcm(m,n)$, and that $\langle (a,b)\rangle=\langle a\rangle\times\langle b\rangle$ $\Longleftrightarrow\gcd(m,n)=1$. (When $\gcd(m,n)>1$, conclude $\langle (a,b)\rangle$ is a proper cyclic subgroup of $\langle a\rangle\times\langle b\rangle$.)
  \item For finite groups $G,H$ recall $\ord{G\times H}=\ord{G}\,\ord{H}$. Fixing $p=2$, verify that a Sylow $2$-subgroup of $\mathbb{Z}/(4)\mathbb{Z}\times S_3$ has the form $P\times Q$ with $P\in\Syl_2(\mathbb{Z}/(4)\mathbb{Z})$, $Q\in\Syl_2(S_3)$, and compute $n_2(\mathbb{Z}/(4)\mathbb{Z}\times S_3)=n_2(\mathbb{Z}/(4)\mathbb{Z})\,n_2(S_3)$ as a concrete number.
\end{exers}

\begin{definition}[Free rank and finitely generated]
An abelian group $G$ is \emph{finitely generated} if there is a finite set $g_1,\dots,g_s\in G$ with $G=\langle g_1,\dots,g_s\rangle$. The group $\mathbb{Z}^r=\mathbb{Z}\times\cdots\times\mathbb{Z}$ ($r$ copies) is the \emph{free abelian group of rank $r$}; the integer $r$ is its \emph{free rank} (or \emph{Betti number}).
\end{definition}

\begin{remark}
$G$ is \emph{finite} $\Longleftrightarrow$ $r=0$. When $r=0$ the order is $|G|=n_1n_2\cdots n_k$, and the largest invariant factor $n_k$ equals the \emph{exponent} of $G$ (the lcm of all element orders). The factor $\mathbb{Z}^r$ is the \emph{free part}; $\mathbb{Z}/(n_1)\mathbb{Z}\times\cdots\times\mathbb{Z}/(n_k)\mathbb{Z}$ is the \emph{torsion part} (the torsion subgroup).
\end{remark}

\begin{proof}[Sketch]
Apply CRT (Theorem~\ref{thm:crt@c5} / the ring isomorphism $\mathbb{Z}/(ab)\mathbb{Z}\cong\mathbb{Z}/(a)\mathbb{Z}\times\mathbb{Z}/(b)\mathbb{Z}$ when $\gcd(a,b)=1$) to split each invariant factor $n_i=\prod_p p^{\,v_p(n_i)}$ into its prime-power pieces. This produces the elementary divisor form from the invariant factor form; uniqueness transfers because the two forms determine each other (see the conversion below). \qed
\end{proof}

\begin{proposition}[Equivalence via CRT]
The two decompositions are equivalent and interconvertible:
\begin{itemize}
\item[(a)] \textbf{Invariant $\to$ elementary.} Factor each invariant factor into prime powers; the resulting prime powers are the elementary divisors.
\item[(b)] \textbf{Elementary $\to$ invariant.} For each prime $p$ occurring, list the $p$-power elementary divisors in one row with exponents \emph{increasing} from left to right; align these rows flush-right; the product down each column (taking the $p$-power in that column, or $1$ if absent) gives the invariant factors $n_1,\dots,n_k$ from left to right, the rightmost column giving $n_k$. Equivalently: $n_k$ is the product of the \emph{largest} prime power for each prime, $n_{k-1}$ the product of the next-largest, etc.
\end{itemize}
\end{proposition}

\begin{proof}
Both directions are repeated application of $\mathbb{Z}/(a)\mathbb{Z}\times\mathbb{Z}/(b)\mathbb{Z}\cong\mathbb{Z}/(ab)\mathbb{Z}$ for $\gcd(a,b)=1$ (CRT) and its converse. In (b), for fixed prime $p$ the $p$-primary part is a fixed list of cyclic $p$-groups; distributing one such $p$-power into each invariant factor from the top down keeps the divisibility $n_1\mid\cdots\mid n_k$ because within each prime the exponents are nonincreasing as we go from $n_k$ to $n_1$. \qed
\end{proof}

