 \draw (bot) -- (a3);
 \end{scope}
 \node[ltlab,above=2pt of top] {$Z_2\timesZ_4$};
 \node[ltlab,left=2pt of c1] {$C_1$};
 \node[ltlab,above left=0pt and 0pt of c2] {$C_2$};
