\begin{method}{Classifying order $pq$ ($p<q$)}
Trigger. $|G|$ is a product of two distinct primes.
\begin{enumerate}
\item Order them $p<q$. The Sylow $q$-subgroup is always normal (since $n_q\mid p<q$).
\item Compute $q-1$ and test divisibility by $p$.
\item If $p\nmid q-1$: only $Z/(pq)Z$. If $p\mid q-1$: two groups, $Z/(pq)Z$ and $Z/(q)Z\sdpZ/(p)Z$.
\end{enumerate}
\end{method}

