\begin{wex}{Order $15$}
Classify all groups of order $15$.
\wrec This is $pq$ with $p=3,q=5$ (Theorem~\ref{thm:pq@c5}); check whether $3\mid 5-1$.
\wsol $q-1=4$ and $3\nmid 4$, so case (1) applies: the unique group is $\mathbb{Z}/(15)\mathbb{Z}\cong\mathbb{Z}/(3)\mathbb{Z}\times\mathbb{Z}/(5)\mathbb{Z}$. \\
\emph{Check via Sylow directly:} $n_5\equiv 1\pmod 5$, $n_5\mid 3\Longrightarrow n_5=1$; $n_3\equiv 1\pmod 3$, $n_3\mid 5\Longrightarrow n_3=1$. Both Sylow subgroups normal $\Longrightarrow G\cong\mathbb{Z}/(3)\mathbb{Z}\times\mathbb{Z}/(5)\mathbb{Z}\cong\mathbb{Z}/(15)\mathbb{Z}$. So $g(15)=1$. \checkmark
\end{wex}

\begin{wex}{Order $21$}
Classify all groups of order $21$.
\wrec $pq$ with $p=3,q=7$; test $3\mid 7-1=6$.
\wsol $3\mid 6$, so case (2): two groups. The cyclic $\mathbb{Z}/(21)\mathbb{Z}$, and the nonabelian $\mathbb{Z}/(7)\mathbb{Z}\sdp\mathbb{Z}/(3)\mathbb{Z}$. The nontrivial action: $\Aut(\mathbb{Z}/(7)\mathbb{Z})\cong\mathbb{Z}/(6)\mathbb{Z}$ has a unique subgroup of order $3$ (generated by $x\mapsto x^2$, since $2$ has order $3$ mod $7$: $2,4,8\equiv1$). So $\mathbb{Z}/(7)\mathbb{Z}\sdp\mathbb{Z}/(3)\mathbb{Z}=\langle a,b\st a^7=b^3=1,\ bab^{-1}=a^2\rangle$. \\
\textit{Check.} $b^3 a b^{-3}=a^{2^3}=a^8=a$, consistent with $b^3=1$. \checkmark\ Thus $g(21)=2$.
\end{wex}

\begin{wex}{Order $33$ vs.\ order $35$}
Determine $g(33)$ and $g(35)$.
\wrec Both are $pq$; apply the $p\mid q-1$ test to each.
\wsol $33=3\cdot 11$: $q-1=10$, $3\nmid 10\Longrightarrow g(33)=1$, only $\mathbb{Z}/(33)\mathbb{Z}$. $\quad 35=5\cdot 7$: $q-1=6$, $5\nmid 6\Longrightarrow g(35)=1$, only $\mathbb{Z}/(35)\mathbb{Z}$. \\
\textit{Check.} Both have all Sylow subgroups normal (e.g.\ for $33$: $n_{11}\mid 3$ and $\equiv1\,(11)\Longrightarrow n_{11}=1$; $n_3\mid 11$ and $\equiv1\,(3)\Longrightarrow n_3=1$). \checkmark
\end{wex}

\begin{wex}{The smallest nonabelian $pq$}
What is the smallest order $pq$ ($p<q$ distinct primes) admitting a nonabelian group, and exhibit it.
\wrec Need the least $q$ with a prime $p<q$ dividing $q-1$; the case-(2) condition.
\wsol Test $q=3$: $q-1=2$, $p=2\mid 2$ and $p<q$. So $pq=6$ works: the nonabelian group is $\mathbb{Z}/(3)\mathbb{Z}\sdp\mathbb{Z}/(2)\mathbb{Z}$ with the inversion action, i.e.\ $S_3\cong D_6$. \\
\textit{Check.} $\Aut(\mathbb{Z}/(3)\mathbb{Z})\cong\mathbb{Z}/(2)\mathbb{Z}$, nontrivial action sends $r\mapsto r^{-1}$, giving $\langle r,s\st r^3=s^2=1,\ srs^{-1}=r^{-1}\rangle=D_6\cong S_3$. \checkmark\ Smallest such order is $6$.
\end{wex}

\begin{pitfall}
The cyclic-uniqueness criterion is \emph{not} just ``the smaller prime $p$''; it is ``$p\mid q-1$'' with $p<q$. For $|G|=2q$ ($q$ odd), $p=2$ \emph{always} divides $q-1$, so there is \emph{always} a nonabelian group (dihedral). For odd $p<q$, you must actually check divisibility -- e.g.\ $|G|=15$ has \emph{no} nonabelian group even though both factors are odd primes.
\end{pitfall}

\begin{theorem}[Order $2p$, $p$ an odd prime]\label{thm:2p@c5}
If $|G|=2p$ with $p$ odd prime, then $G\cong\mathbb{Z}/(2p)\mathbb{Z}$ or $G\cong D_{2p}$. These are the only two classes.
\end{theorem}

\begin{proof}
This is the case $p=2$ of Theorem~\ref{thm:pq@c5} after relabelling: write the primes as $2<p$. Since $2\mid p-1$ always, there are exactly two groups. The Sylow $p$-subgroup $P=\langle r\rangle\cong\mathbb{Z}/(p)\mathbb{Z}$ is normal. Let $s$ have order $2$. Then $G=\langle r\rangle\sdp\langle s\rangle$, and $\Aut(\mathbb{Z}/(p)\mathbb{Z})\cong\mathbb{Z}/((p-1))\mathbb{Z}$ has a \emph{unique} element of order $2$, namely $r\mapsto r^{-1}$. If $s$ acts trivially, $srs^{-1}=r$ and $G$ is abelian $\cong\mathbb{Z}/(2p)\mathbb{Z}$. If $s$ acts by the order-$2$ automorphism, $srs^{-1}=r^{-1}$ and $G\cong D_{2p}$.
\end{proof}

