\begin{method}{Telling $\mathbb{Z}/(2p)\mathbb{Z}$ from $D_{2p}$}
\textit{Trigger.} $|G|=2p$, $p$ odd prime. Always exactly two groups.
\begin{itemize}
\item Find $r$ with $\ord{r}=p$ (Cauchy) and $s$ with $\ord{s}=2$.
\item Compute $srs^{-1}$. If $srs^{-1}=r$ (commute): $G\cong\mathbb{Z}/(2p)\mathbb{Z}$. If $srs^{-1}=r^{-1}$: $G\cong D_{2p}$.
\item Quick invariants: $\mathbb{Z}/(2p)\mathbb{Z}$ has an element of order $2p$ and is abelian with center $G$; $D_{2p}$ is nonabelian with center $1$ and has $p$ elements of order $2$.
\end{itemize}
\end{method}

\begin{wex}{Order $6$}
Classify all groups of order $6$.
\wrec $2p$ with $p=3$; Theorem~\ref{thm:2p@c5} gives exactly two.
\wsol By Cauchy take $r$ of order $3$ and $s$ of order $2$; $\langle r\rangle\nor G$ (index $2$, or $n_3=1$). Then $srs^{-1}\in\{r,r^{-1}\}$.
\begin{itemize}
\item $srs^{-1}=r$: abelian, $G\cong\mathbb{Z}/(2)\mathbb{Z}\times\mathbb{Z}/(3)\mathbb{Z}\cong\mathbb{Z}/(6)\mathbb{Z}$.
\item $srs^{-1}=r^{-1}$: $G\cong\langle r,s\st r^3=s^2=1,\ srs^{-1}=r^{-1}\rangle=D_6\cong S_3$.
\end{itemize}
\textit{Check.} In $S_3$, take $r=(1\,2\,3)$, $s=(1\,2)$. Then $srs^{-1}=(1\,2)(1\,2\,3)(1\,2)=(1\,3\,2)=r^{-1}$. Nonabelian. \checkmark\ So $g(6)=2$.
\end{wex}

\begin{wex}{Order $10$}
Classify all groups of order $10$.
\wrec $2p$ with $p=5$.
\wsol Sylow: $n_5\mid 2$, $n_5\equiv1\,(5)\Longrightarrow n_5=1$, so $\langle r\rangle\cong\mathbb{Z}/(5)\mathbb{Z}$ is normal. With $s$ of order $2$, $srs^{-1}\in\{r,r^2,r^3,r^4\}$ must have order $5$, and conjugating it once more by $s$ must give back $r$ (since $s^2=1\Longrightarrow s(srs^{-1})s^{-1}=r$); only $r\mapsto r$ and $r\mapsto r^{-1}=r^4$ satisfy $\varphi^2=\id$. Two groups: $\mathbb{Z}/(10)\mathbb{Z}$ and $D_{10}$. \\
\textit{Check.} $D_{10}$ is the symmetry group of the regular pentagon, $|D_{10}|=10$, nonabelian; $\mathbb{Z}/(10)\mathbb{Z}$ has the element $r+s$-style generator of order $10$. \checkmark\ $g(10)=2$.
\end{wex}

\begin{wex}{Order $14$ and order $22$}
Find all groups of orders $14$ and $22$.
\wrec Both are $2p$ ($p=7$, $p=11$).
\wsol Each gives exactly $\mathbb{Z}/(2p)\mathbb{Z}$ and $D_{2p}$: $\{\mathbb{Z}/(14)\mathbb{Z},D_{14}\}$ and $\{\mathbb{Z}/(22)\mathbb{Z},D_{22}\}$. \\
\textit{Check.} $n_7\mid 2,\equiv1\,(7)\Longrightarrow n_7=1$ (order $14$); $n_{11}\mid 2,\equiv1\,(11)\Longrightarrow n_{11}=1$ (order $22$). Normal Sylow $p$-subgroup, then the inversion-or-trivial dichotomy. \checkmark\ $g(14)=g(22)=2$.
\end{wex}

\begin{wex}{Why no third group of order $2p$?}
Explain why $G$ of order $2p$ cannot be a ``new'' nonabelian group beyond $D_{2p}$.
\wrec Uses that $\Aut(\mathbb{Z}/(p)\mathbb{Z})$ is \emph{cyclic} of order $p-1$, so has a unique involution.
\wsol The semidirect product $\mathbb{Z}/(p)\mathbb{Z}\sdp_\varphi\mathbb{Z}/(2)\mathbb{Z}$ is determined by $\varphi(s)\in\Aut(\mathbb{Z}/(p)\mathbb{Z})$ with $\varphi(s)^2=\id$. A cyclic group $\mathbb{Z}/((p-1))\mathbb{Z}$ has exactly one element of order $2$ (since $p$ is odd, $p-1$ is even). So there are exactly two choices for $\varphi(s)$: the identity ($\Longrightarrow\mathbb{Z}/(2p)\mathbb{Z}$) and the unique involution ($\Longrightarrow D_{2p}$). No room for a third. \\
\textit{Check.} $p=7$: $\Aut(\mathbb{Z}/(7)\mathbb{Z})\cong\mathbb{Z}/(6)\mathbb{Z}$, involution is $r\mapsto r^6=r^{-1}$, matching $D_{14}$. \checkmark
\end{wex}

\begin{wex}{Order $4$}
Classify all groups of order $4$.
\wrec $|G|=p^2$ with $p=2$; a $p^2$-group is abelian (Theorem on order $p^2$).
\wsol Abelian, so either an element of order $4$ ($G\cong\mathbb{Z}/(4)\mathbb{Z}$) or every non-identity element has order $2$ ($G\cong\mathbb{Z}/(2)\mathbb{Z}\times\mathbb{Z}/(2)\mathbb{Z}=V_4$). \\
\textit{Check.} $\mathbb{Z}/(4)\mathbb{Z}=\{0,1,2,3\}$ has the generator $1$ of order $4$. $V_4=\{1,a,b,ab\}$ with $a^2=b^2=(ab)^2=1$; e.g.\ $a=(1\,2)(3\,4),b=(1\,3)(2\,4)$ in $S_4$. \checkmark\ $g(4)=2$.
\end{wex}

\begin{wex}{Order $9$}
Classify all groups of order $9$.
\wrec $p^2$ with $p=3$.
\wsol Abelian; either $\mathbb{Z}/(9)\mathbb{Z}$ (an element of order $9$) or $\mathbb{Z}/(3)\mathbb{Z}\times\mathbb{Z}/(3)\mathbb{Z}$ (all non-identity elements have order $3$). \\
\textit{Check.} No nonabelian option since order $p^2\Longrightarrow$ abelian. $g(9)=2$. \checkmark
\end{wex}

\begin{proof}
\emph{Abelian case.} By the Fundamental Theorem of Finite Abelian Groups, the abelian groups of order $8=2^3$ correspond to partitions of $3$: $3\to\mathbb{Z}/(8)\mathbb{Z}$, $2+1\to\mathbb{Z}/(4)\mathbb{Z}\times\mathbb{Z}/(2)\mathbb{Z}$, $1+1+1\to\mathbb{Z}/(2)\mathbb{Z}^3$. That is three classes.

\emph{Nonabelian case.} Suppose $G$ is nonabelian of order $8$. No element has order $8$ (else cyclic). Not every non-identity element has order $2$ (that would force $G$ abelian, as $x^2=1\,\forall x\Longrightarrow$ abelian). So there is an element $r$ of order $4$; $\langle r\rangle\nor G$ (index $2$). Pick $s\notin\langle r\rangle$. Conjugation gives $srs^{-1}\in\langle r\rangle$ of order $4$, so $srs^{-1}\in\{r,r^3\}$; $r$ would make $G$ abelian, so $srs^{-1}=r^3=r^{-1}$. Now $s^2\in\langle r\rangle$ and $s^2$ is centralized by $s$, so $s^2\in\{1,r^2\}$ (as $r,r^3$ are not centralized by $s$).
\begin{itemize}
\item $s^2=1$: relations $r^4=s^2=1,\ srs^{-1}=r^{-1}\Longrightarrow G\cong D_8$.
\item $s^2=r^2$: relations $r^4=1,\ s^2=r^2,\ srs^{-1}=r^{-1}\Longrightarrow G\cong Q_8$.
\end{itemize}
These two are not isomorphic (counted below), giving exactly two nonabelian classes. Total: $5$.
\end{proof}

