\begin{method}{Distinguishing the five groups of order $8$}
\textit{Trigger.} $|G|=8$. First decide abelian vs.\ nonabelian (is there a nontrivial commutator?).
\begin{enumerate}
\item \textbf{Abelian?} Use the \emph{order spectrum} (how many elements of each order):
\[
\begin{array}{l|ccc}
 & \#\,\ord 1 & \#\,\ord 2 & \#\,\ord 4 \ (\#\,\ord 8)\\\hline
\mathbb{Z}/(8)\mathbb{Z} & 1 & 1 & 2\ (4)\\
\mathbb{Z}/(4)\mathbb{Z}\times\mathbb{Z}/(2)\mathbb{Z} & 1 & 3 & 4\\
\mathbb{Z}/(2)\mathbb{Z}^3 & 1 & 7 & 0
\end{array}
\]
\item \textbf{Nonabelian?} Both $D_8,Q_8$ have $|Z(G)|=2$ and $G/Z\cong V_4$. Separate by counting elements of order $2$:
\[
D_8:\ \text{five elements of order }2;\qquad Q_8:\ \text{exactly one element of order }2\ (\text{namely }{-1}=r^2).
\]
Equivalently: $Q_8$ has a \emph{unique} involution and \emph{every} subgroup is normal; $D_8$ has non-normal subgroups (the reflections).
\end{enumerate}
\end{method}

\begin{wex}{The five groups of order $8$ and how to tell them apart}
Exhibit all five groups of order $8$ and give a single invariant separating each from the others.
\wrec Theorem~\ref{thm:order8@c5}; use the order-spectrum table plus the unique-involution test.
\wsol
\emph{Abelian (3):}
\begin{itemize}
\item $\mathbb{Z}/(8)\mathbb{Z}$: cyclic, has elements of order $8$. Unique with $\ord{x}=8$.
\item $\mathbb{Z}/(4)\mathbb{Z}\times\mathbb{Z}/(2)\mathbb{Z}$: max order $4$, with $3$ involutions. (E.g.\ $(2,0),(0,1),(2,1)$ have order $2$.)
\item $\mathbb{Z}/(2)\mathbb{Z}^3$: exponent $2$, all $7$ non-identity elements are involutions.
\end{itemize}
\emph{Nonabelian (2):}
\begin{itemize}
\item $D_8=\langle r,s\st r^4=s^2=1,\ srs^{-1}=r^{-1}\rangle$: involutions are $r^2,s,rs,r^2s,r^3s$ -- \emph{five}.
\item $Q_8=\{\pm1,\pm i,\pm j,\pm k\}$ with $i^2=j^2=k^2=ijk=-1$: only $-1$ has order $2$ -- \emph{one}.
\end{itemize}
\emph{Separating invariant:} the number of elements of order $2$ is $1,3,7,5,1$ -- this distinguishes all pairs except $(\mathbb{Z}/(8)\mathbb{Z},Q_8)$, both having one involution; but $\mathbb{Z}/(8)\mathbb{Z}$ is abelian (or: $\mathbb{Z}/(8)\mathbb{Z}$ has elements of order $8$, $Q_8$ does not). \\
\textit{Check ($Q_8$ involution count).} $i^2=-1\ne1$, so $i,j,k,-i,-j,-k$ all have order $4$; $(-1)^2=1$. Exactly one involution. \checkmark\ And $D_8$: $(r^a s)^2=r^a s r^a s=r^a r^{-a}s^2=1$, so all four $r^a s$ are involutions, plus $r^2$, total five. \checkmark
\end{wex}

\begin{wex}{Is the dihedral group of the square $D_8$ or $Q_8$?}
The symmetry group $G$ of a square has order $8$. Which of the five is it?
\wrec Count involutions / use that reflections are non-central order-$2$ elements.
\wsol $G$ has rotations $1,r,r^2,r^3$ ($r=$ rotation by $90^\circ$) and four reflections $s,rs,r^2s,r^3s$. The four reflections and $r^2$ (rotation by $180^\circ$) are involutions: five of order $2$. Matches $D_8$. \\
\textit{Check.} A reflection $s$ is not central ($srs^{-1}=r^{-1}\ne r$), so $G$ is nonabelian with five involutions $\Longrightarrow G\cong D_8$, not $Q_8$. \checkmark
\end{wex}

\begin{wex}{$\mathbb{Z}/(4)\mathbb{Z}\times\mathbb{Z}/(2)\mathbb{Z}$ vs.\ $\mathbb{Z}/(8)\mathbb{Z}$ from a presentation}
Let $G=\langle a,b\st a^4=b^2=1,\ ab=ba\rangle$. Identify $G$.
\wrec Abelian (commuting generators); read off the order spectrum.
\wsol $G$ is abelian of order $|a|\cdot|b|/|\langle a\rangle\cap\langle b\rangle|=4\cdot2=8$ since $\langle a\rangle\cap\langle b\rangle=1$. Max element order is $\ord{ab}=\lcm(4,2)=4$ ($<8$), so $G\not\cong\mathbb{Z}/(8)\mathbb{Z}$. Three involutions: $a^2,b,a^2b$. Thus $G\cong\mathbb{Z}/(4)\mathbb{Z}\times\mathbb{Z}/(2)\mathbb{Z}$. \\
\textit{Check.} $(a^2)^2=(b)^2=(a^2b)^2=1$ and these are distinct nonidentity elements of order $2$; spectrum $(1,3,4)$ matches the table. \checkmark
\end{wex}

\begin{wex}{Every subgroup of $Q_8$ is normal}
Verify that $Q_8$ has the unusual property that all its subgroups are normal (it is \emph{Hamiltonian}), distinguishing it sharply from $D_8$.
\wrec Subgroups of order $4$ have index $2$ (automatically normal); the unique order-$2$ subgroup is central.
\wsol Subgroups: $\{1\},\ \langle -1\rangle=\{\pm1\},\ \langle i\rangle,\langle j\rangle,\langle k\rangle$ (each order $4$, index $2$, normal), and $Q_8$. The order-$2$ subgroup $\{\pm1\}=Z(Q_8)$ is central hence normal. So all six subgroups are normal. \\
\emph{Contrast:} in $D_8$, $\langle s\rangle=\{1,s\}$ is \emph{not} normal: $r s r^{-1}=r^2 s\notin\langle s\rangle$. \checkmark\ This non-normal reflection subgroup cleanly separates $D_8$ from $Q_8$.
\end{wex}

\begin{pitfall}
$D_8$ and $Q_8$ share many invariants: both have order $8$, center of order $2$, $G/Z\cong V_4$, derived subgroup $\langle r^2\rangle$ of order $2$, and the \emph{same} character table degrees. Do \emph{not} try to distinguish them by $|Z|$ or by $G/Z$. The clean separators are: number of involutions ($5$ vs.\ $1$), or ``has a non-normal subgroup'' ($D_8$ yes, $Q_8$ no).
\end{pitfall}

\begin{proof}[Proof sketch]
\emph{Abelian (2):} partitions of $2^2\cdot3$: $\mathbb{Z}/(4)\mathbb{Z}\times\mathbb{Z}/(3)\mathbb{Z}\cong\mathbb{Z}/(12)\mathbb{Z}$ and $\mathbb{Z}/(2)\mathbb{Z}\times\mathbb{Z}/(2)\mathbb{Z}\times\mathbb{Z}/(3)\mathbb{Z}\cong\mathbb{Z}/(2)\mathbb{Z}\times\mathbb{Z}/(6)\mathbb{Z}$.

\emph{Nonabelian.} Let $|G|=12=2^2\cdot3$. By Sylow, $n_3\in\{1,4\}$ and $n_2\in\{1,3\}$. \emph{Key step:} not both can fail to be normal -- if $n_3=4$ there are $4\cdot2=8$ elements of order $3$, leaving only $4$ elements (which must form the unique, hence normal, Sylow $2$-subgroup, so $n_2=1$). So either the Sylow $3$-subgroup $P_3$ or the Sylow $2$-subgroup $P_2$ is normal.
\begin{itemize}
\item \textbf{$P_3\nor G$} (i.e.\ $n_3=1$): then $G\cong\mathbb{Z}/(3)\mathbb{Z}\sdp P_2$ with $P_2\in\{\mathbb{Z}/(4)\mathbb{Z},\mathbb{Z}/(2)\mathbb{Z}^2\}$ and action $\varphi\colon P_2\to\Aut(\mathbb{Z}/(3)\mathbb{Z})\cong\mathbb{Z}/(2)\mathbb{Z}$. Nontrivial cases:
\begin{itemize}
\item $P_2=\mathbb{Z}/(4)\mathbb{Z}$, $\varphi$ nontrivial (kernel $\mathbb{Z}/(2)\mathbb{Z}$): $\mathbb{Z}/(3)\mathbb{Z}\sdp\mathbb{Z}/(4)\mathbb{Z}=\mathrm{Dic}_3$.
\item $P_2=\mathbb{Z}/(2)\mathbb{Z}^2$, $\varphi$ nontrivial: $\mathbb{Z}/(3)\mathbb{Z}\sdp\mathbb{Z}/(2)\mathbb{Z}^2\cong D_{12}$ (since $\mathbb{Z}/(3)\mathbb{Z}\sdp\mathbb{Z}/(2)\mathbb{Z}=S_3=D_6$, and $\times\mathbb{Z}/(2)\mathbb{Z}\Longrightarrow D_{12}\cong D_6\times\mathbb{Z}/(2)\mathbb{Z}$).
\end{itemize}
(Trivial $\varphi$ recovers the two abelian groups.)
\item \textbf{$P_3$ not normal} ($n_3=4$): forces $n_2=1$, $P_2\cong\mathbb{Z}/(2)\mathbb{Z}^2\nor G$, and $G\cong\mathbb{Z}/(2)\mathbb{Z}^2\sdp\mathbb{Z}/(3)\mathbb{Z}$ with $\mathbb{Z}/(3)\mathbb{Z}$ acting by an order-$3$ automorphism (a $3$-cycle on the three involutions). This is $A_4$.
\end{itemize}
Distinctness is checked by invariants (see the method box), giving exactly three nonabelian classes; total $5$.
\end{proof}

\begin{method}{Distinguishing the five groups of order $12$}
\textit{Trigger.} $|G|=12$.
\begin{enumerate}
\item \textbf{Abelian?} Element of order $12$ $\Longrightarrow\mathbb{Z}/(12)\mathbb{Z}$; else (max order $6$) $\mathbb{Z}/(2)\mathbb{Z}\times\mathbb{Z}/(6)\mathbb{Z}$.
\item \textbf{Nonabelian} -- use these separators:
\[
\begin{array}{l|cccc}
 & \text{normal Sylow } & n_3 & \#\,\ord 2 & \text{has elt of order} \\
 & 3\text{-subgrp?} & & & \\\hline
A_4 & \text{no } (n_3=4) & 4 & 3 & 1,2,3 \text{ only}\\
D_{12} & \text{yes} & 1 & 7 & 1,2,3,6\\
\mathrm{Dic}_3 & \text{yes} & 1 & 1 & 1,2,3,4,6
\end{array}
\]
Fast triage: $A_4$ has \emph{no} element of order $6$ and \emph{no} normal Sylow $3$-subgroup (it is the only one with $n_3=4$). $\mathrm{Dic}_3$ has a \emph{unique} involution (like $Q_8$). $D_{12}$ has \emph{seven} involutions.
\end{enumerate}
\end{method}

\begin{wex}{Triage drill: a nonabelian order-$12$ group}
A nonabelian group $G$ of order $12$ has a normal Sylow $3$-subgroup, exactly one element of order $2$, and an element of order $4$. Identify $G$.
\wrec Run the order-$12$ method box: unique involution $+$ order-$4$ element pins it down.
\wsol Normal Sylow $3$-subgroup rules out $A_4$ ($n_3=4$). A unique involution rules out $D_{12}$ (seven) and $\mathbb{Z}/(2)\mathbb{Z}\times\mathbb{Z}/(6)\mathbb{Z}$ (three); $\mathbb{Z}/(12)\mathbb{Z}$, which also has a unique involution, is excluded because $G$ is nonabelian. The only candidate with $\#\,\ord2=1$ and an order-$4$ element is $\mathrm{Dic}_3=\mathbb{Z}/(3)\mathbb{Z}\sdp\mathbb{Z}/(4)\mathbb{Z}$. So $G\cong\mathrm{Dic}_3$. \\
\textit{Check.} Consistency -- $\mathrm{Dic}_3$ has element orders $\{1,2,3,4,6\}$, a unique involution $b^2$, and $n_3=1$. All three given properties hold. \checkmark
\end{wex}

\begin{pitfall}
A semidirect product $H\sdp K$ collapsing to a \emph{direct} product (or to a smaller-looking group) is common: $\mathbb{Z}/(3)\mathbb{Z}\sdp\mathbb{Z}/(2)\mathbb{Z}=S_3$, and $\mathbb{Z}/(3)\mathbb{Z}\sdp\mathbb{Z}/(2)\mathbb{Z}^2\cong D_{12}\cong S_3\times\mathbb{Z}/(2)\mathbb{Z}$ -- but $D_{12}\not\cong\mathbb{Z}/(3)\mathbb{Z}\sdp\mathbb{Z}/(4)\mathbb{Z}=\mathrm{Dic}_3$ even though both are ``$\mathbb{Z}/(3)\mathbb{Z}\sdp$ (order-$4$ group)''. The \emph{group} $K$ and the \emph{action} $\varphi$ both matter: $\mathbb{Z}/(4)\mathbb{Z}$ vs.\ $\mathbb{Z}/(2)\mathbb{Z}^2$ as the complement gives genuinely different groups. Always record the full datum $(H,K,\varphi)$, never just $|H|$ and $|K|$.
\end{pitfall}

\begin{exers}{Exercises (from the text).}
\item Prove that $D_{16}$, $\mathbb{Z}_2 \times D_8$, $\mathbb{Z}_2 \times Q_8$, $\mathbb{Z}_4 \ast D_8$, $QD_{16}$ and $M$ are nonisomorphic non-abelian groups of order $16$ (where $\mathbb{Z}_4 \ast D_8$ is described in Exercise 12, Section 1 and $QD_{16}$ and $M$ are described in the exercises in Section 2.5).
\end{exers}

