\item Draw the abelianization short exact sequence $1\to G'\to G\to G/G'\to1$ and prove that every abelian quotient $G/N$ factors through it, i.e.\ $G/N$ is abelian $\iff G'\le N$. Indicate the induced commuting triangle when $G'\le N$. \\
\textit{Answer.} The sequence is exact: $G'\nor G$ with cokernel $G/G'$. By Proposition~\ref{prop:commutator@c5}(2), $G/N$ is abelian $\iff G'\le N$; in that case the third isomorphism theorem gives $G/N\cong(G/G')/(N/G')$, so $G\to G/N$ factors as $G\xrightarrow{\pi}G/G'\to G/N$, and the triangle below commutes. Functoriality: a homomorphism $G\to H$ carries $G'$ into $H'$, inducing $G/G'\to H/H'$.
\[\begin{tikzcd}[column sep=normal, row sep=large]
1 \arrow[r] & G' \arrow[r, hook] & G \arrow[r, two heads, "\pi"] \arrow[dr, two heads] & G/G' \arrow[d, dashed, two heads] \arrow[r] & 1 \\
& & & G/N &
\end{tikzcd}\]

\end{exers}

\begin{proposition}[$H\sdp_\varphi K$ is a group; D\&F Thm.~5.5.10]\label{prop:sdp@c5}
With $H,K,\varphi$ as above, $H\sdp_\varphi K$ is a group of order $\ord H\ord K$. Identifying
$h\leftrightarrow(h,1)$ and $k\leftrightarrow(1,k)$:
\begin{enumerate}
\item the maps $h\mapsto(h,1)$ and $k\mapsto(1,k)$ are injective homomorphisms, so $H$ and $K$
are (isomorphic to) subgroups; with these identifications every element factors uniquely as
$(h,k)=hk$;
\item $H\nor H\sdp K$ and $K\sgr H\sdp K$, with $H\cap K=1$ and $HK=H\sdp K$;
\item for $h\in H,\ k\in K$ one has $khk^{-1}=\varphi_k(h)$, i.e. conjugation by $k$ realizes
$\varphi_k$;
\item $H\sdp_\varphi K$ is abelian $\Longleftrightarrow$ $\varphi$ is trivial and both $H,K$ are abelian; in
particular $H\sdp_\varphi K=H\times K$ (direct product) $\Longleftrightarrow$ $\varphi$ is the trivial
homomorphism.
\end{enumerate}
\end{proposition}

\begin{remark}
The rule is forced once you decide $H\nor G$, $K$ a complement, and $khk^{-1}=\varphi_k(h)$. Indeed
$(h_1k_1)(h_2k_2)=h_1(k_1h_2k_1^{-1})k_1k_2=h_1\varphi_{k_1}(h_2)\,k_1k_2$. So the formula is not an
arbitrary convention -- it is exactly ``slide $h_2$ past $k_1$ by conjugating.''
\end{remark}

\begin{method}{Building an external semidirect product}
\textit{Trigger.} You want a group containing a normal copy of $H$ and a complementary copy of $K$ in
which $K$ acts on $H$ in a prescribed way (e.g. inversion, a cyclic permutation of generators, a
field automorphism).

\textit{Recipe.}
\begin{enumerate}
\item Pick $H,K$ and decide the desired action of each $k\in K$ as an automorphism of $H$.
\item Package it as a homomorphism $\varphi\colon K\to\Aut(H)$, $k\mapsto\varphi_k$. \emph{Check it is
a homomorphism}: $\varphi_{k_1k_2}=\varphi_{k_1}\circ\varphi_{k_2}$ and $\varphi_1=\id$. (Often you
only need to send a generator of $K$ to a chosen automorphism whose order divides the order of that
generator.)
\item Form $H\sdp_\varphi K$ with $(h_1,k_1)(h_2,k_2)=(h_1\varphi_{k_1}(h_2),k_1k_2)$.
\item Identify a presentation/known group via the relation $khk^{-1}=\varphi_k(h)$.
\end{enumerate}
\end{method}

\begin{pitfall}
A function $K\to\Aut(H)$ must be a \emph{homomorphism}. ``Send the generator $x$ of $K=\mathbb{Z}/(n)\mathbb{Z}$ to an
automorphism $\alpha$'' is well defined as a homomorphism \textbf{iff} $\alpha^{\,n}=\id$, i.e.
$\ord\alpha\mid n$ inside $\Aut(H)$. Choosing $\alpha$ of the wrong order does not give a semidirect
product at all.
\end{pitfall}

\begin{method}{Recognizing $G$ as an internal semidirect product}
\textit{Trigger.} You suspect a given $G$ is $H\sdp K$ for visible subgroups $H,K$ (e.g. a normal
Sylow subgroup and a complement).

\textit{Checklist (all four).}
\begin{enumerate}
\item $H\nor G$ (often: $H$ is a unique Sylow subgroup, hence normal).
\item $K\sgr G$ (any complementary subgroup).
\item $H\cap K=1$ (e.g. coprime orders force this).
\item $HK=G$, equivalently $\ord H\ord K=\ord G$ with $H\cap K=1$.
\end{enumerate}
Then read off the action $\varphi_k(h)=khk^{-1}$ to name the group. If $\varphi$ is trivial you have a
direct product; otherwise a genuine (nonabelian, when $H$ or $K$ is nontrivially acted on) semidirect
product.
\end{method}

\begin{pitfall}
You need \emph{both} $H\nor G$ and $HK=G$ and $H\cap K=1$. Dropping ``$HK=G$'' (equivalently the order
count) is fatal: in $\mathbb{Z}/(4)\mathbb{Z}=\{0,1,2,3\}$ take $H=\{0,2\}\nor\mathbb{Z}/(4)\mathbb{Z}$ and $K=\{0,2\}$; then $H\nor G$,
$K\sgr G$, but $H\cap K=H\neq1$ and $HK=H\neq G$ -- no decomposition. Also: $K$ need \emph{not} be
normal; if it is, you actually have a direct product.
\end{pitfall}

\begin{pitfall}
``$H\nor G$, $K\nor G$, $H\cap K=1$, $HK=G$'' (both normal) is the criterion for the \emph{direct}
product $G\cong H\times K$, not the semidirect one. For a genuine semidirect product you only get
$H\nor G$; the complement $K$ need not be normal, and is not when the action is nontrivial. Conversely,
do not assume $K\nor G$ ``for symmetry'' -- in $D_{2n}$ ($n\ge3$) the reflection subgroup $\langle s\rangle$ is
not normal.
\end{pitfall}

\begin{exers}{Additional exercises.}
  \item Let $1\to H\xrightarrow{\iota}G\xrightarrow{\pi}K\to1$ be a short exact sequence with $K$ cyclic of order $n$. Prove that the sequence splits if and only if $G$ contains an element $t$ of order $n$ with $\pi(t)$ a generator of $K$. (Hint: given such $t$, show $\langle t\rangle$ is a complement to $\iota(H)$ and define the splitting by $s\bigl(\pi(t)^j\bigr)=t^j$; conversely, $t=s(\text{generator})$ satisfies $t^n=s(1)=1$ and $\pi(t)$ generates $K$.) Use this to show the sequence $1\to\mathbb{Z}/(3)\mathbb{Z}\to\mathbb{Z}/(9)\mathbb{Z}\to\mathbb{Z}/(3)\mathbb{Z}\to1$ does not split, so $\mathbb{Z}/(9)\mathbb{Z}$ is a non-split extension of $\mathbb{Z}/(3)\mathbb{Z}$ by $\mathbb{Z}/(3)\mathbb{Z}$.
  \item For $n\ge3$ exhibit $S_n$ as an internal semidirect product $A_n\sdp\langle (1\,2)\rangle$. Verify $A_n\nor S_n$, $\langle (1\,2)\rangle\cong\mathbb{Z}/(2)\mathbb{Z}$, $A_n\cap\langle (1\,2)\rangle=1$, and $A_n\langle (1\,2)\rangle=S_n$ (note coprimality is \emph{not} needed), and identify the action $\varphi\colon\mathbb{Z}/(2)\mathbb{Z}\to\Aut(A_n)$ as conjugation by the transposition $(1\,2)$. Explain why $\varphi$ is nontrivial, so the product is not direct.
  \item Prove that $Q_8$ is not isomorphic to any nontrivial semidirect product $H\sdp K$ of proper subgroups. (Hint: such a decomposition would need $H\cap K=1$ with $\{\ord H,\ord K\}=\{2,4\}$; analyze the order-$2$ subgroups of $Q_8$ and show every subgroup of order $4$ contains the unique element $-1$ of order $2$.) Conclude that $Q_8$ is a non-split extension.
  \item Determine all isomorphism types of $\mathbb{Z}/(3)\mathbb{Z}\sdp_\varphi\mathbb{Z}/(4)\mathbb{Z}$, i.e.\ all groups of order $12$ with normal Sylow $3$-subgroup and cyclic complement $\mathbb{Z}/(4)\mathbb{Z}$. Using $\Aut(\mathbb{Z}/(3)\mathbb{Z})\cong\mathbb{Z}/(2)\mathbb{Z}$, count the homomorphisms $\mathbb{Z}/(4)\mathbb{Z}\to\Aut(\mathbb{Z}/(3)\mathbb{Z})$, show there are exactly two resulting groups, identify the trivial case as $\mathbb{Z}/(12)\mathbb{Z}$, and give the presentation $\langle x,y\st x^3=y^4=1,\ yxy^{-1}=x^{-1}\rangle$ of the nonabelian one (the dicyclic group of order $12$).

\end{exers}

\begin{definition}[Nilpotent group; nilpotency class]
A group $G$ is \emph{nilpotent} if $Z_c=G$ for some $c\ge 0$, i.e.\ the upper central series reaches $G$ in finitely many steps. The least such $c$ is the \emph{nilpotency class} of $G$. A nontrivial group has class $\ge 1$; class $1$ means $G=Z(G)$, i.e.\ $G$ is abelian (and nontrivial).
\end{definition}

\begin{proposition}[Upper and lower series have equal length]\label{prop:equal-length@c6}
For a group $G$ and an integer $c\ge 0$ the following are equivalent:
\begin{enumerate}
\item[(a)] $Z_c=G$ (upper central series reaches $G$ at step $c$);
\item[(b)] $\gamma_{c+1}=1$ (lower central series reaches $1$ at step $c+1$).
\end{enumerate}
Hence $G$ is nilpotent iff the lower central series terminates at $1$, and the two series have the same length: the class $c$ is the least $c$ with $Z_c=G$ and also the least $c$ with $\gamma_{c+1}=1$.
\end{proposition}

\begin{remark}
The two series ``zip'' past each other: in a class-$c$ group, $\gamma_{i+1}\le Z_{c-i}$ for $0\le i\le c$. Drawn as facing chains, the lower series descending on the left meets the upper series ascending on the right exactly at length $c$.
\end{remark}

\begin{method}{Building the upper central series of a finite group}
\textit{Trigger.} You are asked for $Z_i(G)$, the class of $G$, or to test nilpotency of a specific finite group.\\
\textit{Recipe.}
\begin{enumerate}
\item Compute $Z_1=Z(G)$ directly.
\item Form $\bar G=G/Z_1$ and compute $Z(\bar G)$; pull back to $G$ to get $Z_2$ (the preimage of $Z(\bar G)$).
\item Repeat: $Z_{i+1}=$ preimage in $G$ of $Z(G/Z_i)$. Stop when $Z_i=Z_{i-1}$ (stabilized) or $Z_i=G$ (reached the top).
\item If the series reaches $G$, the class is the index where it first equals $G$. If it stalls below $G$, $G$ is \emph{not} nilpotent.
\end{enumerate}
\end{method}

\begin{wex}{Center of $D_8$ and the start of its upper series}
Let $D_8=\langle r,s\mid r^4=s^2=1,\ srs=r^{-1}\rangle$. Find $Z(D_8)$.
\wrec Center first: $Z_1=Z(G)$ is step 1 of the upper central series, and for a $2$-group we expect it to be nontrivial.
\wsol We test each noncentral generator. Since $srs=r^{-1}\ne r$, $r\notin Z$; since $rs\ne sr$, $s\notin Z$. The element $r^2$ satisfies $s r^2 s=(srs)^2=r^{-2}=r^2$ (as $r^4=1$), and $r^2$ commutes with $r$, so $r^2\in Z$. The eight elements are $1,r,r^2,r^3,s,rs,r^2s,r^3s$; checking conjugation by $s$ sends $r^k\mapsto r^{-k}$ and conjugation by $r$ sends $r^k s\mapsto r^{k+2}s$, so only $1$ and $r^2$ are fixed by all conjugations. Thus $Z(D_8)=\{1,r^2\}\cong\mathbb{Z}/2\mathbb{Z}$.
\textit{Check.} $|Z|=2$ divides $|G|=8$, and $G/Z(G)$ has order $4$; if it were cyclic $G$ would be abelian, so $G/Z\cong V_4$. Consistent.
\end{wex}

