\begin{wex}{$S_3$ is NOT nilpotent}
Show $S_3$ is not nilpotent by computing both series.
\wrec If $Z(G)=1$ the upper series never leaves $1$; if $G'=G$ the lower series never leaves $G$. Either stalls $\Longrightarrow$ not nilpotent.
\wsol Center: $S_3$ is nonabelian with trivial center, $Z(S_3)=1$. Hence $Z_0=Z_1=1$, and since $G/Z_0=S_3$ has trivial center, every $Z_i=1$. The upper series stalls at $1\ne S_3$, so $S_3$ is not nilpotent. Lower series: $\gamma_2=[S_3,S_3]=A_3=\langle (1\,2\,3)\rangle\cong\mathbb{Z}/3\mathbb{Z}$, and $\gamma_3=[A_3,S_3]$. A transposition conjugates the $3$-cycle to its inverse, so $[(1\,2\,3),(1\,2)]=(1\,3\,2)(1\,2)(1\,2\,3)(1\,2)=(1\,3\,2)(1\,3\,2)=(1\,2\,3)\in A_3$; in fact $[A_3,S_3]=A_3$, so $\gamma_2=\gamma_3=A_3\ne 1$. The lower series stalls at $A_3$.
\textit{Check.} Both diagnostics agree: $Z_1=1$ and $\gamma_2$ does not descend to $1$. $S_3$ is solvable (its derived series is $S_3\ge A_3\ge 1$) but not nilpotent --- a clean separation of the two notions.
\end{wex}

\begin{theorem}[$p$-groups are nilpotent]\label{thm:pgrp-nilpotent@c6}
Every finite $p$-group is nilpotent. More precisely, if $|G|=p^n$ then the upper central series of $G$ reaches $G$, and the class is at most $n-1$ when $n\ge 2$ (and class $\le n$ in general).
\end{theorem}

\begin{proof}
The key fact is that a nontrivial finite $p$-group has nontrivial center: $G$ acts on itself by conjugation, the class equation gives $|G|=|Z(G)|+\sum[G:C_G(x_i)]$ over noncentral class representatives, every index $[G:C_G(x_i)]$ is a positive power of $p$, and $p\mid|G|$, so $p\mid|Z(G)|$, forcing $|Z(G)|>1$.

Now run the upper central series. If $Z_i\ne G$, then $G/Z_i$ is a nontrivial finite $p$-group, so $Z(G/Z_i)\ne 1$, i.e.\ $Z_{i+1}/Z_i\ne 1$ and $Z_{i+1}\gneq Z_i$. Thus the series \emph{strictly} increases at every step below $G$. Since $|G|=p^n$ is finite, the chain $1=Z_0\lneq Z_1\lneq\cdots$ cannot grow forever; it must reach $G$. Hence $G$ is nilpotent.

For the class bound, let $c$ be the class. Each strict step multiplies the order by at least $p$, so $|Z_i|\ge p^i$ for $i\le c$, whence $c\le n$. If $n\ge2$ and $c=n$, then $|Z_i|=p^i$ for every $i\le n$, so $G/Z_{n-2}$ has order $p^2$ and is therefore abelian; then $Z(G/Z_{n-2})=G/Z_{n-2}$, i.e.\ $Z_{n-1}=G$, contradicting $c=n$. Hence $c\le n-1$ when $n\ge2$.
\end{proof}

\begin{pitfall}
``$p$-group'' here means a finite group of prime-power order. Infinite $p$-groups (e.g.\ the semidirect product $\mathbb{Z}_{2^\infty}\sdp\mathbb{Z}/2\mathbb{Z}$ in which $\mathbb{Z}/2\mathbb{Z}$ acts on the Pr\"ufer $2$-group $\mathbb{Z}_{2^\infty}$ by inversion, or an infinite restricted wreath product) need not be nilpotent; the Pr\"ufer group $\mathbb{Z}_{p^\infty}$ itself is abelian, hence nilpotent of class $1$. The proof above uses finiteness twice: for the class equation and to guarantee the strictly increasing chain terminates.
\end{pitfall}

\begin{wex}{Class bound is sharp: $D_8$ has order $2^3$ and class $2$}
Verify the bound ``class $\le n-1$'' for $|G|=p^n$ on $G=D_8$.
\wrec Apply Theorem \ref{thm:pgrp-nilpotent@c6} with $p=2$, $n=3$.
\wsol Here $n=3$, so the bound predicts class $\le 2$. We computed class$(D_8)=2$. Sharp.
\textit{Check.} $Q_8$ also has order $8$ and class $2$, matching. The nonabelian groups of order $p^3$ all have class exactly $2$.
\end{wex}

\begin{wex}{An elementary abelian $p$-group is nilpotent of class $1$}
Let $E=(\mathbb{Z}/p\mathbb{Z})^k$ with $k\ge 1$. Find its class.
\wrec Abelian nontrivial $\Longrightarrow$ class $1$; it is also a $p$-group, so Theorem \ref{thm:pgrp-nilpotent@c6} applies trivially.
\wsol $E$ is abelian, so $Z(E)=E=Z_1$, and the upper series is $1\sgr E$ of length $1$. The class is $1$. The lower series is $E=\gamma_1\ge\gamma_2=[E,E]=1$, terminating at index $2=c+1$. Consistent.
\textit{Check.} Any nontrivial abelian group has class $1$; ``$p$-group of class $1$'' $\iff$ ``nontrivial abelian $p$-group''.
\end{wex}

\begin{theorem}[Characterization of finite nilpotent groups]\label{thm:nilpotent-char@c6}
Let $G$ be a finite group. The following are equivalent.
\begin{enumerate}
\item[(1)] $G$ is nilpotent.
\item[(2)] Every Sylow subgroup of $G$ is normal in $G$.
\item[(3)] $G$ is the (internal) direct product of its Sylow subgroups: if $|G|=p_1^{a_1}\cdots p_r^{a_r}$ with Sylow $p_i$-subgroup $P_i$, then $G\cong P_1\times\cdots\times P_r$.
\item[(4)] Every maximal subgroup of $G$ is normal in $G$.
\end{enumerate}
\end{theorem}

\begin{remark}
The class of a finite nilpotent group $G=P_1\times\cdots\times P_r$ equals $\max_i\,\operatorname{class}(P_i)$. So nilpotency of a finite group is ``Sylow-local'': it holds iff it holds prime-by-prime, after detaching the Sylow subgroups into a direct product.
\end{remark}

\begin{method}{Sylow-normal nilpotency test (finite groups)}
\textit{Trigger.} ``Is this finite group nilpotent?'' --- when you know $|G|$ and can count Sylow subgroups.\\
\textit{Recipe.}
\begin{enumerate}
\item Factor $|G|=p_1^{a_1}\cdots p_r^{a_r}$.
\item For each prime $p_i$, use Sylow's theorem: count $n_{p_i}$ (the number of Sylow $p_i$-subgroups), with $n_{p_i}\equiv 1\pmod{p_i}$ and $n_{p_i}\mid m_i$ where $m_i=|G|/p_i^{a_i}$.
\item $G$ is nilpotent $\iff n_{p_i}=1$ for \emph{every} $i$ (all Sylow subgroups normal).
\item If so, $G\cong P_1\times\cdots\times P_r$; the class is the max of the Sylow classes.
\end{enumerate}
\textit{Shortcut.} If even one prime forces $n_p>1$, $G$ is not nilpotent.
\end{method}

\begin{wex}{Nilpotent groups of order $12$: resolve carefully}
Decide which groups of order $12$ are nilpotent.
\wrec Sylow-normal test: $12=2^2\cdot 3$; nilpotent $\iff$ both the Sylow $2$- and Sylow $3$-subgroups are normal $\iff G\cong P_2\times P_3$.
\wsol The five groups of order $12$ are $\mathbb{Z}/12\mathbb{Z}$, $\mathbb{Z}/2\mathbb{Z}\times\mathbb{Z}/6\mathbb{Z}$, $A_4$, $D_{12}$, and $\operatorname{Dic}_3=Q_{12}$ (the dicyclic group). A nilpotent group of order $12$ would be $P_2\times P_3$ with $|P_2|=4$, $|P_3|=3$: that is $(\mathbb{Z}/4\mathbb{Z}\text{ or }V_4)\times\mathbb{Z}/3\mathbb{Z}$, giving exactly $\mathbb{Z}/4\mathbb{Z}\times\mathbb{Z}/3\mathbb{Z}\cong\mathbb{Z}/12\mathbb{Z}$ and $V_4\times\mathbb{Z}/3\mathbb{Z}\cong\mathbb{Z}/2\mathbb{Z}\times\mathbb{Z}/6\mathbb{Z}$. These two abelian groups \emph{are} nilpotent (class $1$). The three nonabelian groups are not: in $A_4$, $n_3=4\ne1$ (the four Sylow $3$-subgroups), so its Sylow $3$-subgroup is not normal; in $D_{12}$ and $Q_{12}$, the Sylow $2$-subgroup is not normal (equivalently their center is too small to climb to $G$).
\textit{Check.} So among order-$12$ groups, exactly the two abelian ones are nilpotent. In particular there is no \emph{nonabelian} nilpotent group of order $12$: that would need a nonabelian Sylow factor, impossible for $|P_2|=4,|P_3|=3$. Both $\mathbb{Z}/12\mathbb{Z}$ and $\mathbb{Z}/2\mathbb{Z}\times\mathbb{Z}/6\mathbb{Z}$ have class $1$.
\end{wex}

\begin{wex}{$A_4$ is not nilpotent}
Confirm $A_4$ (order $12$) fails the Sylow-normal test.
\wrec Count $n_3$ in $A_4$.
\wsol $|A_4|=12=2^2\cdot3$. The Sylow $3$-subgroups are generated by $3$-cycles; $A_4$ has eight $3$-cycles, grouped into four subgroups of order $3$ (each containing $2$ nonidentity elements). So $n_3=4$, which satisfies $4\equiv1\pmod 3$ and $4\mid 4$. Since $n_3=4\ne1$, the Sylow $3$-subgroup is not normal, so $A_4$ is not nilpotent.
\textit{Check.} Directly: $Z(A_4)=1$ (no nonidentity element is fixed by all conjugations in $A_4$), so the upper series stalls at $1$. $A_4$ is solvable but not nilpotent.
\end{wex}

\begin{wex}{$S_4$ is not nilpotent}
Test $S_4$ (order $24$) for nilpotency.
\wrec Sylow-normal test; $24=2^3\cdot3$.
\wsol $n_3$: Sylow $3$-subgroups are generated by $3$-cycles; $S_4$ has eight $3$-cycles in four order-$3$ subgroups, so $n_3=4\ne1$. Already this defeats nilpotency.
\textit{Check.} Also $Z(S_4)=1$, so the upper series stalls at $1$. So $S_4$ is not nilpotent; it \emph{is} solvable, illustrating again that solvable does not imply nilpotent.
\end{wex}

\begin{wex}{A nilpotent group of order $24$: $Q_8\times\mathbb{Z}/3\mathbb{Z}$}
Exhibit a nonabelian nilpotent group of order $24$ and give its class.
\wrec $G\cong P_2\times P_3$ with both Sylow normal; pick a nonabelian Sylow $2$-subgroup.
\wsol Take $G=Q_8\times\mathbb{Z}/3\mathbb{Z}$, order $8\cdot3=24$. Both factors are the (unique, hence normal) Sylow subgroups: $Q_8\in\Syl_2(G)$, $\mathbb{Z}/3\mathbb{Z}\in\Syl_3(G)$, and a direct factor is normal. By Theorem \ref{thm:nilpotent-char@c6}, $G$ is nilpotent. Its class is $\max(\operatorname{class}(Q_8),\operatorname{class}(\mathbb{Z}/3\mathbb{Z}))=\max(2,1)=2$.
\textit{Check.} $Z(G)=Z(Q_8)\times\mathbb{Z}/3\mathbb{Z}=\{\pm1\}\times\mathbb{Z}/3\mathbb{Z}$ has order $6$, and $G/Z(G)\cong V_4\times1=V_4$ is abelian, so $Z_2(G)=G$: class $2$, confirming the formula.
\end{wex}

\begin{pitfall}
``Every Sylow subgroup normal'' is much stronger than ``some Sylow subgroup normal''. A group can have a normal Sylow subgroup (even be solvable) without being nilpotent: $S_3$ has a normal Sylow $3$-subgroup but its Sylow $2$-subgroups (the three order-$2$ subgroups) are not normal, so $S_3$ is not nilpotent. You need \emph{all} primes to cooperate.
\end{pitfall}

\begin{proposition}[Nongenerators]\label{prop:nongen@c6}
$\Frat(G)$ is exactly the set of \emph{nongenerators} of $G$: an element $x$ such that whenever $G=\langle x,Y\rangle$ for a subset $Y$, already $G=\langle Y\rangle$. Consequently, if $\langle Y,\Frat(G)\rangle=G$ then $\langle Y\rangle=G$ (Frattini elements are dispensable in any generating set).
\end{proposition}

\begin{proof}
Let $g\in G$. Since $N\nor G$, conjugation by $g$ maps $N$ to itself, so $gPg^{-1}\le N$ and $gPg^{-1}\in\Syl_p(N)$ (conjugation preserves order and $p$-subgroup-ness). By Sylow's theorem applied \emph{inside $N$}, all Sylow $p$-subgroups of $N$ are $N$-conjugate, so there is $n\in N$ with $n(gPg^{-1})n^{-1}=P$, i.e.\ $(ng)P(ng)^{-1}=P$. Thus $ng\in N_G(P)$. Writing $g=n^{-1}(ng)$ with $n^{-1}\in N$ and $ng\in N_G(P)$ shows $g\in N\,N_G(P)$. As $g$ was arbitrary, $G=N\,N_G(P)$.
\end{proof}

\begin{theorem}[Frattini subgroup is nilpotent]\label{thm:frat-nilpotent@c6}
For a finite group $G$, $\Frat(G)$ is nilpotent.
\end{theorem}

