\begin{method}{Computing $\Frat(G)$}
\textit{Trigger.} You need $\Frat(G)$ for a specific $G$ (often a $p$-group or abelian group).\\
\textit{Recipe.}
\begin{enumerate}
\item List the maximal subgroups (in a $p$-group, maximal subgroups are exactly the index-$p$ subgroups, all normal).
\item Intersect them.
\item Shortcut for $p$-groups: $\Frat(G)=G'\,G^p$, where $G^p=\langle g^p:g\in G\rangle$. The quotient $G/\Frat(G)$ is the largest elementary abelian $p$-quotient.
\item Shortcut for finite abelian $G$: $\Frat(G)=\bigcap_{p\,\mid\,|G|}\,pG$; equivalently $G/\Frat(G)\cong\prod_p(\mathbb{Z}/p\mathbb{Z})^{r_p}$ where $r_p$ is the $p$-rank.
\end{enumerate}
\end{method}

\begin{wex}{$\Frat(\mathbb{Z}/p^n\mathbb{Z})$}
Compute the Frattini subgroup of the cyclic group $\mathbb{Z}/p^n\mathbb{Z}$.
\wrec Cyclic $p$-group: a unique maximal subgroup, of index $p$.
\wsol $\mathbb{Z}/p^n\mathbb{Z}$ is cyclic, so its subgroups are totally ordered: $0\le p^{n-1}\mathbb{Z}/p^n\mathbb{Z}\le\cdots\le\mathbb{Z}/p^n\mathbb{Z}$. The unique maximal subgroup is the index-$p$ subgroup $p\mathbb{Z}/p^n\mathbb{Z}\cong\mathbb{Z}/p^{n-1}\mathbb{Z}$. The intersection over the (single) maximal subgroup is itself, so $\Frat(\mathbb{Z}/p^n\mathbb{Z})=p\mathbb{Z}/p^n\mathbb{Z}\cong\mathbb{Z}/p^{n-1}\mathbb{Z}$.
\textit{Check.} The shortcut $\Frat=G'G^p=1\cdot G^p=pG$ gives the same answer, and $G/\Frat\cong\mathbb{Z}/p\mathbb{Z}$ is elementary abelian of rank $1$. For $n=1$, $\Frat(\mathbb{Z}/p\mathbb{Z})=0$.
\end{wex}

\begin{wex}{$\Frat$ of an elementary abelian $p$-group is trivial}
Compute $\Frat(E)$ for $E=(\mathbb{Z}/p\mathbb{Z})^k$.
\wrec Vector space over $\F_p$: maximal subgroups are the hyperplanes.
\wsol View $E$ as a $k$-dimensional $\F_p$-vector space. Its maximal subgroups are exactly the codimension-$1$ subspaces (hyperplanes). For any nonzero $v\in E$ there is a hyperplane avoiding $v$ (extend $v$ to a basis and drop it). Hence the intersection of all hyperplanes is $\{0\}$: $\Frat(E)=0$.
\textit{Check.} Shortcut: $E'=0$ (abelian) and $E^p=\langle x^p\rangle=0$ (every element has order dividing $p$), so $\Frat(E)=E'E^p=0$. Then $E/\Frat(E)=E$ is itself elementary abelian of rank $k$, matching ``$G/\Frat(G)$ is the largest elementary abelian quotient''.
\end{wex}

\begin{wex}{$\Frat(D_8)$ and the rank of $D_8/\Frat(D_8)$}
Compute $\Frat(D_8)$.
\wrec $2$-group: $\Frat=G'\,G^2$; maximal subgroups have index $2$.
\wsol The maximal (index-$2$) subgroups of $D_8$ are $\langle r\rangle\cong\mathbb{Z}/4\mathbb{Z}$, $\langle r^2,s\rangle\cong V_4$, and $\langle r^2,rs\rangle\cong V_4$. Their intersection: $\langle r\rangle\cap\langle r^2,s\rangle=\langle r^2\rangle$, and $\langle r^2\rangle\le\langle r^2,rs\rangle$, so $\Frat(D_8)=\langle r^2\rangle\cong\mathbb{Z}/2\mathbb{Z}$.
\textit{Check.} Shortcut: $G'=\langle r^2\rangle$ and $G^2=\langle g^2\rangle=\langle r^2\rangle$ (squares: $r^2$, and $(r^ks)^2=1$), so $\Frat=G'G^2=\langle r^2\rangle$. Then $D_8/\Frat(D_8)$ has order $4$ and exponent $2$, so it is $(\mathbb{Z}/2\mathbb{Z})^2$, elementary abelian of rank $2$ --- consistent with $D_8$ needing $2$ generators.
\end{wex}

\begin{wex}{$\Frat(\mathbb{Z}/12\mathbb{Z})$ via the abelian shortcut}
Compute $\Frat(\mathbb{Z}/12\mathbb{Z})$.
\wrec Finite abelian: $\Frat=\bigcap_p pG$ over $p\mid|G|$.
\wsol $|G|=12=2^2\cdot3$, so the primes are $2,3$. The maximal subgroups of $\mathbb{Z}/12\mathbb{Z}$ are the index-$2$ subgroup $2\mathbb{Z}/12\mathbb{Z}\cong\mathbb{Z}/6\mathbb{Z}$ and the index-$3$ subgroup $3\mathbb{Z}/12\mathbb{Z}\cong\mathbb{Z}/4\mathbb{Z}$. Their intersection is $6\mathbb{Z}/12\mathbb{Z}=\{0,6\}\cong\mathbb{Z}/2\mathbb{Z}$. So $\Frat(\mathbb{Z}/12\mathbb{Z})=\langle 6\rangle\cong\mathbb{Z}/2\mathbb{Z}$.
\textit{Check.} Shortcut $2G\cap 3G$: $2G=\{0,2,4,6,8,10\}$, $3G=\{0,3,6,9\}$, intersection $\{0,6\}$. Same. And $G/\Frat\cong\mathbb{Z}/6\mathbb{Z}\cong\mathbb{Z}/2\mathbb{Z}\times\mathbb{Z}/3\mathbb{Z}$ is a product of elementary abelian groups, one for each prime (abelian of squarefree exponent $6$), the largest such quotient.
\end{wex}

\begin{wex}{$\Frat(S_3)$}
Compute the Frattini subgroup of $S_3$.
\wrec List maximal subgroups and intersect; $S_3$ is not a $p$-group, so no $p$-group shortcut.
\wsol The proper nontrivial subgroups of $S_3$ are $A_3=\langle (1\,2\,3)\rangle$ (order $3$, index $2$) and the three order-$2$ subgroups $\langle (1\,2)\rangle,\langle (1\,3)\rangle,\langle (2\,3)\rangle$ (index $3$). All four are maximal. Their intersection: $A_3\cap\langle (1\,2)\rangle=1$ already, so $\Frat(S_3)=1$.
\textit{Check.} Consistent with $S_3$ being generated by a single transposition and a $3$-cycle with no redundancy; there are no nontrivial nongenerators. Note $\Frat(S_3)=1$ is nilpotent (trivially), matching Theorem \ref{thm:frat-nilpotent@c6}.
\end{wex}

\begin{pitfall}
The clean formula $\Frat(G)=G'G^p$ holds only for finite \emph{$p$-groups}. For a general finite group you must either intersect all maximal subgroups directly or, in the abelian case, intersect $pG$ over the primes $p$ dividing $|G|$. Applying ``$G'G^p$'' to a non-$p$-group (e.g.\ choosing a single $p$) gives the wrong subgroup.
\end{pitfall}

\begin{remark}[Why this matters]
For a finite $p$-group $G$, the quotient $G/\Frat(G)$ is a vector space over $\F_p$, and the \emph{Burnside Basis Theorem} says a subset of $G$ generates $G$ iff its image spans $G/\Frat(G)$, and a minimal generating set of $G$ maps onto a basis of $G/\Frat(G)$. Thus the minimal number of generators of a $p$-group equals $\dim_{\F_p}\!\big(G/\Frat(G)\big)$ --- the rank we computed above ($1$ for $\mathbb{Z}/p^n\mathbb{Z}$, $k$ for $(\mathbb{Z}/p\mathbb{Z})^k$, $2$ for $D_8$ and $Q_8$).
\end{remark}

\begin{remark}
Two identities used constantly: $[x,y]^{-1}=[y,x]$, and $g^{-1}[x,y]g=[g^{-1} xg,\,g^{-1} yg]$. The second says conjugation permutes commutators, which is exactly why $G'$ is normal.
\end{remark}

\begin{proposition}[Universal property of $G'$]\label{prop:gprime@c6}
Let $G$ be a group.
\begin{enumerate}
\item[(a)] $G'\nor G$ (in fact $G'$ is characteristic in $G$).
\item[(b)] $G/G'$ is abelian.
\item[(c)] If $N\nor G$ then $G/N$ is abelian $\Longleftrightarrow G'\le N$.
\end{enumerate}
Thus $G'$ is the unique smallest normal subgroup with abelian quotient: $G/G'$ is the largest abelian quotient of $G$ (the \emph{abelianization} $G^{\mathrm{ab}}$).
\end{proposition}

\begin{proof}
(a) For $g\in G$ and any generator $[x,y]$ we have $g^{-1}[x,y]g=[g^{-1} xg,g^{-1} yg]\in G'$; as conjugation by $g$ is an automorphism sending generators of $G'$ into $G'$, it maps $G'$ into $G'$, so $G'\nor G$. Replacing conjugation by an arbitrary $\varphi\in\Aut(G)$ gives $\varphi(G')\le G'$, hence characteristic.

(b) In $G/G'$ we have $\overline{x}\,\overline{y}\,\overline{x}^{-1}\overline{y}^{-1}=\overline{xyx^{-1} y^{-1}}=\overline{[x^{-1},y^{-1}]}=\overline{1}$ since $[x^{-1},y^{-1}]\in G'$. So any two cosets commute.

(c) Suppose $G/N$ abelian. For $x,y\in G$, $\overline{x}\,\overline{y}=\overline{y}\,\overline{x}$ gives $\overline{[x,y]}=\overline{1}$, i.e. $[x,y]\in N$; as $N$ contains all generators of $G'$, $G'\le N$. Conversely if $G'\le N$ then by the correspondence theorem $G/N$ is a quotient of the abelian group $G/G'$, hence abelian.
\end{proof}

\begin{method}{Computing $G'$ in practice}
To find $G'=[G,G]$:
\begin{enumerate}
\item \textbf{Use a known abelianization.} If you can spot the largest abelian quotient $G/N$ (e.g. via the sign map, a determinant, or a coordinate that becomes additive), then $G'\le N$; check generators of $N$ are commutators to get equality.
\item \textbf{Generate from a few commutators.} Compute $[g_i,g_j]$ for generators $g_i$ of $G$. Then $G'$ is the \emph{normal closure} of these commutators (the subgroup generated by them and all their conjugates): if $N$ is that normal closure, the images of the $g_i$ commute in $G/N$, so $G/N$ is abelian and $G'\le N\le G'$. The subgroup generated by the $[g_i,g_j]$ alone can be too small: for $A_4=\langle (1\,2\,3),(1\,2)(3\,4)\rangle$ it is $\langle (1\,4)(2\,3)\rangle$, of order $2$, whereas $A_4'$ is the Klein four-group of double transpositions, of order $4$.
\item \textbf{Read off $|G^{\mathrm{ab}}|$.} $|G/G'|=$ size of the abelianization; for a known presentation, abelianize the relations (make all generators commute) to compute $G^{\mathrm{ab}}$.
\item \textbf{Perfect check.} $G'=G$ ($G$ \emph{perfect}) iff $G$ has no nontrivial abelian quotient; true for nonabelian simple groups.
\end{enumerate}
\end{method}

\begin{wex}{$\GL_n$ is (almost) perfect: $\SL_2(\F_5)$}
Show $\SL_2(\F_5)$ is perfect, i.e. equals its own commutator subgroup.
\wrec Perfect check (Method, step 4): a nonabelian group with no nontrivial abelian quotient. $\SL_2(\F_5)$ has order $120$ and $\SL_2(\F_5)/\{\pm I\}\cong A_5$ is simple nonabelian; we use that $A_5$ is perfect plus the structure of the extension.
\wsol Let $G=\SL_2(\F_5)$, $|G|=120$, $Z=\{\pm I\}$, $G/Z\cong A_5$. The group $A_5$ is simple nonabelian, hence perfect: $(A_5)'=A_5$ (its only normal subgroups are $1$ and $A_5$, and $A_5$ is nonabelian so $(A_5)'\ne1$, forcing $(A_5)'=A_5$). Now $G'$ maps onto $(G/Z)'=(A_5)'=A_5$ under $G\to G/Z$, so $G'Z=G$ and $[G:G']\mid|Z|=2$. If $[G:G']=2$ then $G$ would have an index-$2$ (hence normal) subgroup $G'$ with $G/G'\cong\mathbb{Z}_2$; but in fact the transvections (elementary unipotent matrices) are products of commutators and generate all of $G$. Concretely $\SL_2(\F_q)$ is perfect for $q\ge4$, and $5\ge4$. Hence $G'=G$.
\textit{Check.} A perfect group has trivial abelianization $G^{\mathrm{ab}}=1$, consistent with $|G/G'|=1$. Its derived series is constant $G,G,G,\dots$, so $G$ is not solvable.
\end{wex}

\begin{theorem}[Characterization of solvability]\label{thm:solv-char@c6}
For a group $G$ the following are equivalent.
\begin{enumerate}
\item[(a)] $G$ is solvable: $G^{(n)}=1$ for some $n$.
\item[(b)] $G$ has a chain $1=G_0\nor G_1\nor\cdots\nor G_k=G$ in which each quotient $G_{i+1}/G_i$ is abelian (an \emph{abelian series}).
\item[(c)] (If $G$ is finite) $G$ has a chain as in (b) with each $G_{i+1}/G_i$ \emph{cyclic of prime order}.
\end{enumerate}
\end{theorem}

\begin{proof}
(a)$\Longrightarrow$(b): Take $G_i=G^{(n-i)}$. Then $1=G^{(n)}=G_0\nor\cdots\nor G_n=G$ and $G_{i+1}/G_i=G^{(n-i-1)}/G^{(n-i)}$ is abelian by Proposition~\ref{prop:gprime@c6}(b) applied to $G^{(n-i-1)}$.

(b)$\Longrightarrow$(a): We show $G^{(i)}\le G_{k-i}$ by induction. Base $G^{(0)}=G=G_k$. If $G^{(i)}\le G_{k-i}$, then since $G_{k-i}/G_{k-i-1}$ is abelian we have $(G_{k-i})'\le G_{k-i-1}$, so $G^{(i+1)}=(G^{(i)})'\le(G_{k-i})'\le G_{k-i-1}=G_{k-(i+1)}$. At $i=k$: $G^{(k)}\le G_0=1$, so $G$ is solvable.

(c)$\Longrightarrow$(b) is immediate (cyclic of prime order is abelian). (b)$\Longrightarrow$(c) for finite $G$: refine each abelian quotient. A finite abelian group $G_{i+1}/G_i$ has a composition series with quotients $\mathbb{Z}_p$ (e.g. via the structure theorem); pulling back gives intermediate normal subgroups whose successive quotients are cyclic of prime order. Inserting these refines the chain to the form (c).
\end{proof}

\begin{method}{Testing solvability via the derived series}
\textit{Trigger.} ``Is $G$ solvable?'' or ``find the derived length.''
\begin{enumerate}
\item Compute $G^{(1)}=G'$ (use the $G'$ method above).
\item Compute $G^{(2)}=(G')'$, then $G^{(3)}$, \dots, halting when you reach $1$ or detect a repeat.
\item \textbf{If the series reaches $1$:} $G$ is solvable; the derived length is the step count.
\item \textbf{If the series stabilizes at a nontrivial $H$} (i.e. $H'=H\ne1$, a perfect subgroup): $G$ is \emph{not} solvable. In particular any nonabelian simple subquotient is a fatal obstruction.
\item \textit{Shortcuts.} (i) $|G|=p^a$ ($p$-group) $\Longrightarrow$ nilpotent $\Longrightarrow$ solvable. (ii) $|G|=p^aq^b$ $\Longrightarrow$ solvable (Burnside). (iii) $|G|<60$ $\Longrightarrow$ solvable (smallest nonabelian simple group is $A_5$, order $60$). (iv) If $G$ has a nonabelian simple composition factor, $G$ is not solvable.
\end{enumerate}
\end{method}

\begin{theorem}[Closure properties of solvable groups]\label{thm:closure@c6}
Let $G$ be a group, $H\le G$ a subgroup, and $N\nor G$ a normal subgroup.
\begin{enumerate}
\item[(a)] If $G$ is solvable, then $H$ is solvable.
\item[(b)] If $G$ is solvable, then $G/N$ is solvable.
\item[(c)] (Extensions) If $N$ and $G/N$ are both solvable, then $G$ is solvable.
\end{enumerate}
\end{theorem}

\begin{proof}
(a) By induction, $H^{(i)}\le G^{(i)}$: clearly $H^{(0)}=H\le G=G^{(0)}$, and if $H^{(i)}\le G^{(i)}$ then $H^{(i+1)}=[H^{(i)},H^{(i)}]\le[G^{(i)},G^{(i)}]=G^{(i+1)}$. If $G^{(n)}=1$ then $H^{(n)}\le G^{(n)}=1$, so $H$ is solvable (derived length $\le$ that of $G$).

(b) Let $\pi\colon G\to G/N$. A commutator maps to a commutator: $\pi([x,y])=[\pi x,\pi y]$, so $\pi(G^{(i)})=(G/N)^{(i)}$ by induction. If $G^{(n)}=1$ then $(G/N)^{(n)}=\pi(G^{(n)})=1$, so $G/N$ is solvable.

(c) Suppose $(G/N)^{(m)}=1$ and $N^{(k)}=1$. From part (b)'s identity, $\pi(G^{(m)})=(G/N)^{(m)}=1$ means $G^{(m)}\le\ker\pi=N$. Then $G^{(m+k)}=(G^{(m)})^{(k)}\le N^{(k)}=1$. Hence $G$ is solvable with derived length $\le m+k$.
\end{proof}

\begin{pitfall}
Part (c) requires $N$ \emph{normal}. ``$H$ solvable and $G/H$ makes sense'' is meaningless for non-normal $H$. Also, ``solvable'' is NOT detected by a single quotient: $G/N$ solvable alone does not make $G$ solvable -- you also need $N$ solvable. Example: take $G=A_5\times\mathbb{Z}_2$ with $N=A_5$; then $G/N\cong\mathbb{Z}_2$ is solvable but $G$ is not, because $N=A_5$ is not.
\end{pitfall}

\begin{proposition}\label{prop:nilp-solv@c6}
Every nilpotent group is solvable. The converse is false.
\end{proposition}

\begin{wex}{Nilpotent $\Longrightarrow$ solvable, with $S_3$ as the converse counterexample}
(i) Verify $D_8$ is nilpotent and solvable. (ii) Verify $S_3$ is solvable but not nilpotent, exhibiting both series.
\wrec Compute the lower central series (tests nilpotence) AND the derived series (tests solvability) for each, per Proposition~\ref{prop:nilp-solv@c6}.
\wsol (i) \emph{$D_8$.} Lower central: $\gamma_1=D_8$, $\gamma_2=[D_8,D_8]=D_8'=\langle r^2\rangle$ (computed earlier), $\gamma_3=[\langle r^2\rangle,D_8]$. Since $r^2\in Z(D_8)$, every commutator $[r^2,g]=1$, so $\gamma_3=1$. Thus $D_8=\gamma_1\ge\langle r^2\rangle\ge1$ is nilpotent of class $2$. Derived: $D_8\ge\langle r^2\rangle\ge1$ (since $\langle r^2\rangle\cong\mathbb{Z}_2$ abelian), solvable of derived length $2$. Both terminate. \textbf{Nilpotent and solvable.}

(ii) \emph{$S_3$.} Derived series $S_3\ge A_3\ge1$ (quotients $\mathbb{Z}_2,\mathbb{Z}_3$): \textbf{solvable}, length $2$. Lower central series $S_3\ge A_3\ge A_3\ge\cdots$ stabilizes at $A_3$ (since $[A_3,S_3]=A_3\ne1$): \textbf{not nilpotent}.
\textit{Check.} A finite group is nilpotent iff it is the direct product of its Sylow subgroups iff every Sylow subgroup is normal. In $S_3$ the three Sylow $2$-subgroups (order $2$) are not normal ($n_2=3$), confirming non-nilpotence; in $D_8$ ($2$-group) every $p$-group is nilpotent, confirming nilpotence. Consistent.
\end{wex}

