\begin{definition}[Ring]
A \emph{ring} is a set $R$ together with two binary operations $+$ and $\cdot$ such that:
\begin{enumerate}
\item $(R,+)$ is an abelian group (with identity $0$ and inverses $-a$);
\item $\cdot$ is associative: $(ab)c = a(bc)$ for all $a,b,c\in R$;
\item the distributive laws hold: $(a+b)c = ac+bc$ and $a(b+c) = ab+ac$.
\end{enumerate}
$R$ is \emph{commutative} if $ab=ba$ for all $a,b$. $R$ \emph{has an identity} (or \emph{$1$}) if there is $1\in R$ with $1\cdot a = a\cdot 1 = a$ for all $a$. Unless stated otherwise our rings have an identity with $1\neq 0$.
\end{definition}

\begin{definition}[Units, zero divisors]
Let $R$ be a ring with $1$.
\begin{itemize}
\item $u\in R$ is a \emph{unit} if there is $v\in R$ with $uv=vu=1$; the units form a group $\units{R}$ under multiplication.
\item A nonzero $a\in R$ is a \emph{(left) zero divisor} if there exists $b\neq 0$ with $ab=0$ (or $ba=0$ for a right zero divisor).
\end{itemize}
\end{definition}

\begin{definition}[Domain, division ring, field]
Let $R$ be a ring with $1\neq 0$.
\begin{itemize}
\item $R$ is an \emph{integral domain} if $R$ is commutative and has no zero divisors.
\item $R$ is a \emph{division ring} if every nonzero element is a unit, i.e. $\units{R}=R\setminus\{0\}$.
\item $R$ is a \emph{field} if it is a commutative division ring.
\end{itemize}
Thus: field $=$ commutative division ring $\Longrightarrow$ integral domain.
\end{definition}

\begin{definition}[Subring]
A nonempty subset $S\subseteq R$ is a \emph{subring} if $S$ is closed under subtraction and multiplication (so $(S,+)\le(R,+)$ and $S$ is closed under $\cdot$). Then $S$ is itself a ring. (D\&F do not require $1_R\in S$.)
\end{definition}

