\begin{proposition}[D\&F 7.1, Prop.\ 1] 
Let $R$ be a ring. For all $a,b\in R$:
\begin{enumerate}
\item $0\cdot a = a\cdot 0 = 0$;
\item $(-a)b = a(-b) = -(ab)$;
\item $(-a)(-b) = ab$;
\item if $R$ has an identity $1$, then $1$ is unique and $(-1)a = -a$.
\end{enumerate}
\end{proposition}

