\begin{proposition}[D\&F 7.1, Prop.\ 1]\label{prop:basic@c7}
Let $R$ be a ring. For all $a,b\in R$:
\begin{enumerate}
\item $0\cdot a = a\cdot 0 = 0$;
\item $(-a)b = a(-b) = -(ab)$;
\item $(-a)(-b) = ab$;
\item if $R$ has an identity $1$, then $1$ is unique and $(-1)a = -a$.
\end{enumerate}
\end{proposition}

\begin{proof}
(1) $0\cdot a = (0+0)a = 0\cdot a + 0\cdot a$ by distributivity. Adding $-(0\cdot a)$ to both sides gives $0 = 0\cdot a$. Symmetrically $a\cdot 0 = 0$.

(2) $ab + (-a)b = (a+(-a))b = 0\cdot b = 0$ by (1), so $(-a)b$ is the additive inverse of $ab$, i.e. $(-a)b = -(ab)$. Likewise $ab + a(-b) = a(b+(-b)) = a\cdot 0 = 0$, so $a(-b) = -(ab)$.

(3) Using (2) twice: $(-a)(-b) = -(a(-b)) = -(-(ab)) = ab$.

(4) If $1,1'$ are identities then $1 = 1\cdot 1' = 1'$. By (2) with $a=1$, $(-1)b = -(1\cdot b) = -b$.
\end{proof}

\begin{proposition}[Cancellation in a domain]\label{prop:cancel@c7}
Let $R$ be an integral domain. If $a\neq 0$ and $ab = ac$, then $b=c$. (Nonzero elements cancel.)
\end{proposition}

\begin{proof}
$ab=ac \Longrightarrow a(b-c)=0$. Since $a\neq 0$ and $R$ has no zero divisors, $b-c=0$, i.e. $b=c$.
\end{proof}

\begin{theorem}[Finite domains are fields, D\&F 7.1 Cor.\ to Prop.\ 2]\label{thm:finite@c7}
Every finite integral domain is a field.
\end{theorem}

\begin{proof}
Let $R$ be a finite integral domain and fix $a\neq 0$. The map $\mu_a\colon R\to R$, $\mu_a(x)=ax$, is injective: $ax=ay \Longrightarrow x=y$ by cancellation (Prop.\ \ref{prop:cancel@c7}). An injective map from a finite set to itself is surjective, so some $b\in R$ has $ab=1$. As $R$ is commutative, $ba=1$ too, so $a\in\units{R}$. Every nonzero $a$ is a unit, hence $R$ is a field.
\end{proof}

\begin{definition}[Characteristic]\label{def:char@c7}
The \emph{characteristic} $\charac(R)$ of a ring with $1$ is the least $n>0$ with $n\cdot 1 = \underbrace{1+\cdots+1}_{n}=0$, if such $n$ exists; otherwise $\charac(R)=0$.
\end{definition}

\begin{proposition}[Characteristic of a domain]\label{prop:charprime@c7}
If $R$ is an integral domain then $\charac(R)$ is either $0$ or a prime $p$.
\end{proposition}

\begin{proof}
Suppose $\charac(R)=n=st$ with $1<s,t<n$. Then $0 = n\cdot 1 = (s\cdot 1)(t\cdot 1)$. Since $R$ has no zero divisors, $s\cdot 1=0$ or $t\cdot 1=0$, contradicting minimality of $n$. So $n$ is prime (or $0$).
\end{proof}

\begin{method}{Deciding: domain vs.\ field vs.\ neither}
Given a ring $R$ with $1\neq 0$:
\begin{enumerate}
\item \textbf{Commutative?} If not, the best you can hope for is a division ring (e.g.\ $\HH$); a field requires commutativity.
\item \textbf{Hunt for zero divisors.} Find $a,b\neq 0$ with $ab=0$. One pair kills ``domain'' (hence ``field''). In $\mathbb{Z}/(n)\mathbb{Z}$ look at $\gcd(a,n)>1$; in $\Mat_n$ look at $\det=0$; in products $R\times S$ try $(1,0)(0,1)=(0,0)$.
\item \textbf{If no zero divisors, it's a domain.} Now ask: is every nonzero element a unit? Solve $ax=1$. If always solvable $\Longrightarrow$ field; if some nonzero $a$ has no inverse $\Longrightarrow$ domain but not field.
\item \textit{Shortcut.} A \emph{finite} domain is automatically a field (Thm.\ \ref{thm:finite@c7}). So for finite $R$ you only need step 2.
\end{enumerate}
\end{method}

\begin{pitfall}
\emph{$1\neq 0$ is part of the definition of a field/domain.} The zero ring $\{0\}$ (where $1=0$) has no zero divisors and trivially every element is invertible, yet it is \emph{not} a field or domain. Always exclude it.
\end{pitfall}

\begin{pitfall}
\emph{A zero divisor is never a unit.} If $a$ is a unit with inverse $a^{-1}$ and $ab=0$, then $b = a^{-1}(ab) = a^{-1}\cdot 0 = 0$; symmetrically, $ba=0$ gives $b=(ba)a^{-1}=0\cdot a^{-1}=0$. So $a$ cannot kill a nonzero $b$ from either side. Consequently in any ring, $\units{R}$ and the set of zero divisors are disjoint.
\end{pitfall}

\begin{remark}
The condition ``no zero divisors'' is exactly cancellation (Prop.\ \ref{prop:cancel@c7}): nonzero elements cancel $\Longleftrightarrow$ there are no zero divisors. This is why $\mathbb{Z}/(n)\mathbb{Z}$ ($n\ge 2$) supports cancellation precisely when $n$ is prime, and why solving linear equations $ax=b$ behaves well only in domains.
\end{remark}

