\begin{theorem}[{Degree and integrality in $R[x]$}]\label{thm:Rx@c7}
Let $R$ be an integral domain and $p,q\in R[x]$ be nonzero. Then:
\begin{enumerate}
\item[(1)] $\deg(pq)=\deg p+\deg q$;
\item[(2)] the units of $R[x]$ are exactly the units of $R$: $\units{R[x]}=\units{R}$;
\item[(3)] $R[x]$ is an integral domain.
\end{enumerate}
\end{theorem}

\begin{pitfall}
All three statements can fail when $R$ has zero divisors. In $\mathbb{Z}/(4)\mathbb{Z}[x]$, $(2x)(2x)=4x^2=0$,
so $\deg$ drops (and $R[x]$ acquires zero divisors). And $\units{\mathbb{Z}/(4)\mathbb{Z}[x]}\supsetneq(\mathbb{Z}/(4)\mathbb{Z})^{\times}$:
indeed $(1+2x)(1+2x)=1+4x+4x^2=1$, so $1+2x$ is a unit of degree $1$. The hypothesis ``$R$ a
domain'' in Theorem~\ref{thm:Rx@c7} is essential.
\end{pitfall}

\begin{method}{Degree arguments in $R[x]$}
\textit{Trigger.} You must decide whether a product is nonzero, find its degree, or rule out
a unit/factorization in a polynomial ring.\\
\textit{Recipe.}
(1) Identify the ring $R$ of coefficients and ask: \emph{is $R$ an integral domain?}
(2) If yes, multiply leading coefficients: the leading coefficient of $pq$ is the product of
the leading coefficients, so $\deg(pq)=\deg p+\deg q$ and $pq\neq 0$.
(3) To test units: if $pq=1$ over a domain, take degrees to get $\deg p=\deg q=0$, so only
constant units of $R$ survive.
(4) If $R$ has zero divisors, do \emph{not} use these shortcuts -- compute the top coefficient
$a_m b_n$ explicitly and check whether it vanishes; the degree may drop and stray units may appear.
\end{method}

\begin{remark}
When $R$ is commutative, $A\in\GL_n(R)$ iff $\det A\in\units{R}$, and then
$A^{-1}=(\det A)^{-1}\operatorname{adj}(A)$. So $\GL_n(\mathbb{Z})=\{A:\det A=\pm 1\}$ and
$\GL_n(\mathbb{Q})=\{A:\det A\neq 0\}$. The bare definition $\units{\Mat_n(R)}=\GL_n(R)$ holds for any
$R$; the determinant criterion needs commutativity.
\end{remark}

\begin{method}{Detecting zero divisors / units in $\Mat_n(R)$}
\textit{Trigger.} A question about whether matrices commute, multiply to zero, or are invertible.\\
\textit{Recipe.}
(1) For zero divisors over $n\ge2$, reach for matrix units: $E_{ij}E_{k\ell}=0$ whenever
$j\neq k$. The pair $E_{11},E_{22}$ always gives $E_{11}E_{22}=0$.
(2) For noncommutativity, compute both $AB$ and $BA$ on a small example such as $E_{11},E_{12}$.
(3) For units when $R$ is commutative, compute $\det A$ and check $\det A\in\units{R}$.
(4) Never assume a nonzero matrix is a unit: in $\Mat_n(R)$ a matrix can be nonzero, even
nonzero-on-the-diagonal, yet singular.
\end{method}

\begin{proposition}\label{prop:group-ring@c7}
$RG$ is a ring with $1$; it is commutative iff $G$ is abelian. If $|G|>1$ then $RG$ is never a
domain: for $g\neq 1_G$ of order $m$, the element $1-g$ is a zero divisor.
\end{proposition}

