\begin{remark}
Since $\varphi$ is in particular a homomorphism of the additive groups $(R,+)\to(S,+)$, we automatically get $\varphi(0)=0$ and $\varphi(-a)=-\varphi(a)$. D\&F do \emph{not} build $\varphi(1_R)=1_S$ into the definition; it can fail (e.g. $r\mapsto 0$, or $\mathbb{Z}\to\mathbb{Z}\times\mathbb{Z}$, $n\mapsto(n,0)$). When $1_R$ is preserved one says $\varphi$ is \emph{unital}. Every surjective homomorphism onto a ring with $1$ \emph{is} unital, and every evaluation/quotient map below is unital.
\end{remark}

\begin{proposition}[Kernel is an ideal, image is a subring]\label{prop:ker-im@c7}
Let $\varphi:R\to S$ be a ring homomorphism. Then:
\begin{enumerate}
\item $\varphi(R)$ is a subring of $S$.
\item $\ker\varphi$ is a subring of $R$ that is closed under multiplication by arbitrary elements of $R$ on both sides: if $k\in\ker\varphi$ and $r\in R$ then $rk\in\ker\varphi$ and $kr\in\ker\varphi$.
\item $\varphi$ is injective $\Longleftrightarrow \ker\varphi=\{0\}$.
\end{enumerate}
\end{proposition}

\begin{proof}
(1) $\varphi(R)$ contains $0=\varphi(0)$ and is closed under the additive-subgroup operations because $(R,+)\to(S,+)$ is a group homomorphism. For products, $\varphi(a)\varphi(b)=\varphi(ab)\in\varphi(R)$. So $\varphi(R)$ is a subring.

(2) As above $\ker\varphi$ is an additive subgroup, and $0\in\ker\varphi$. If $k\in\ker\varphi$ and $r\in R$ then $\varphi(rk)=\varphi(r)\varphi(k)=\varphi(r)\cdot 0=0$, so $rk\in\ker\varphi$; symmetrically $kr\in\ker\varphi$. In particular $\ker\varphi$ is closed under products, hence a subring (without $1$, in general).

(3) Identical to the group statement applied to $(R,+)$: $\varphi(a)=\varphi(b)\Longleftrightarrow\varphi(a-b)=0\Longleftrightarrow a-b\in\ker\varphi$. Thus $\varphi$ is injective iff $\ker\varphi=\{0\}$.
\end{proof}

\begin{definition}[Ideal]
Let $R$ be a ring and $I\subseteq R$ a subset. Say $I$ is a \emph{left ideal} if $I$ is an additive subgroup and $rI\subseteq I$ for all $r\in R$; a \emph{right ideal} if instead $Ir\subseteq I$ for all $r\in R$; and a \emph{(two-sided) ideal} if it is both. In a commutative ring all three notions coincide; ``ideal'' then means ``two-sided ideal'' and we write $I\trianglelefteq R$.
\end{definition}

\begin{remark}[An ideal is rarely a subring with $1$]
An ideal $I$ is closed under the ring operations, but $1\in I$ forces $r=r\cdot 1\in I$ for every $r$, i.e. $I=R$. So a \emph{proper} ideal never contains $1$, i.e. it is never a subring containing the identity of $R$ (it can still have an identity of its own: the ideal $\mathbb{Z}\times 0$ of $\mathbb{Z}\times\mathbb{Z}$ has identity $(1,0)$). The point of Proposition~\ref{prop:ker-im@c7} is precisely that kernels are the right absorbing objects to quotient by.
\end{remark}

\begin{pitfall}
The well-definedness proof uses both sidedness conditions \emph{separately} ($rb$ needs left-absorption, $as$ needs right-absorption). If $I$ is only a left ideal, $r's'+I=rs+I$ can fail and $R/I$ is merely a left $R$-module, not a ring. This is exactly why one quotients by \emph{two-sided} ideals only.
\end{pitfall}

\begin{theorem}[First Isomorphism Theorem for rings]\label{thm:first-iso@c7}
Let $\varphi:R\to S$ be a ring homomorphism. Then $\ker\varphi$ is a two-sided ideal of $R$, $\varphi(R)$ is a subring of $S$, and there is a unique ring isomorphism $\overline\varphi:R/\ker\varphi\to\varphi(R)$ with $\overline\varphi(r+\ker\varphi)=\varphi(r)$, i.e. $\varphi=\overline\varphi\circ\pi$. Thus
\[
R/\ker\varphi \;\cong\; \varphi(R).
\]
\end{theorem}

\begin{proof}
$\overline\varphi$ is well defined: if $r+I=r'+I$ then $r-r'\in I\subseteq\ker\varphi$, so $\varphi(r)=\varphi(r')$. The homomorphism axioms transfer verbatim as in Theorem~\ref{thm:first-iso@c7}, and uniqueness follows since $\pi$ is surjective: $\varphi=\overline\varphi\circ\pi$ pins down $\overline\varphi$ on all of $R/I$. Finally $r+I\in\ker\overline\varphi\Longleftrightarrow\varphi(r)=0\Longleftrightarrow r\in\ker\varphi$, i.e. $\ker\overline\varphi=\{r+I:r\in\ker\varphi\}=\ker\varphi/I$.
\end{proof}

\begin{proof}
(2nd) Define $\varphi:A\to (A+I)/I$ by $a\mapsto a+I$ (restrict $\pi$ to $A$). It is a homomorphism, surjective because every $a+i+I=a+I$ lies in its image, and $\ker\varphi=\{a\in A:a\in I\}=A\cap I$. Theorem~\ref{thm:first-iso@c7} gives $A/(A\cap I)\cong(A+I)/I$.

(3rd) Apply Theorem~\ref{thm:univ@c7} to $\varphi=\pi_J:R\to R/J$, whose kernel is $J\supseteq I$, to get a surjection $\overline{\pi_J}:R/I\to R/J$ with kernel $J/I$. Then Theorem~\ref{thm:first-iso@c7} yields $(R/I)/(J/I)\cong R/J$.

(4th) Since $\pi$ is a surjective ring homomorphism (Theorem~\ref{thm:quotient@c7}), ideals/subrings of $R/I$ pull back along $\pi$ to ideals/subrings of $R$ containing $\ker\pi=I$, and push forward as $J\mapsto J/I$; these are mutually inverse and preserve inclusion. (Same argument as the group lattice theorem applied to the absorbing structure.)
\end{proof}

\begin{method}{Recognizing a quotient: identify $R/I$ via a surjection with the right kernel}
To prove $R/I\cong S$ (or to identify an unfamiliar quotient):
\begin{enumerate}
\item Build a \emph{surjective} ring homomorphism $\varphi:R\to S$ onto the target you suspect. Evaluation maps $p\mapsto p(c)$, reduction maps, and ``set this generator to $0$'' maps are the standard sources.
\item Compute $\ker\varphi$ exactly. Show $\ker\varphi=I$ by two inclusions: $I\subseteq\ker\varphi$ (check each generator of $I$ maps to $0$) and $\ker\varphi\subseteq I$ (often via a division/normal-form argument).
\item Conclude $R/I=R/\ker\varphi\cong\varphi(R)=S$ by Theorem~\ref{thm:first-iso@c7}.
\end{enumerate}
Recognition triggers: ``identify $R[x]/(f)$,'' ``show $\mathbb{Z}/n\mathbb{Z}\cong\dots$,'' ``compute a quotient'' --- almost always solved by a one-line evaluation/reduction surjection plus a kernel computation.
\end{method}

\begin{proposition}[Concrete description of $\langle A\rangle$]\label{prop:gendesc@c7}
Let $A \subseteq R$ where $R$ has identity $1$.
\begin{enumerate}
\item[(1)] $RA = \left\{ \sum_{i=1}^{n} r_i a_i \;:\; r_i \in R,\ a_i \in A,\ n \geq 0 \right\}$ is the left ideal generated by $A$.
\item[(2)] The (two-sided) ideal generated by $A$ is
\[
\langle A\rangle \;=\; RAR \;=\; \left\{ \sum_{i=1}^{n} r_i a_i s_i \;:\; r_i, s_i \in R,\ a_i \in A,\ n \geq 0 \right\}.
\]
\item[(3)] If $R$ is commutative, then $\langle A\rangle = RA = \left\{ \sum_{i=1}^{n} r_i a_i : r_i \in R,\ a_i \in A \right\}$. In particular for a single element, $\langle a\rangle = Ra = aR = \{ ra : r \in R\}$.
\end{enumerate}
\end{proposition}

\begin{proof}
The right side of (1), call it $J$, is closed under addition and under left multiplication by $R$ (since $r\sum r_i a_i = \sum (rr_i)a_i$), so it is a left ideal; it contains $A$ because $1 \in R$ gives $a = 1\cdot a \in J$. Any left ideal containing $A$ must contain every $r_i a_i$ and their sums, so it contains $J$; hence $J = RA$ is the smallest left ideal containing $A$. The argument for (2) is identical using two-sided products $r a s$, which form the smallest set closed under addition and under multiplication by $R$ on both sides; again $1 \cdot a \cdot 1 = a$ shows $A \subseteq RAR$. For (3), commutativity collapses $r a s = (rs)a$, so $RAR = RA$, and $Ra = aR$.
\end{proof}

\begin{method}{Computing $\langle A\rangle$ and recognizing principal/f.g.\ ideals}
\textit{Trigger.} You are handed a subset $A$ and asked for the ideal it generates, or asked whether an ideal is principal.
\begin{enumerate}
\item If $R$ is \emph{commutative with $1$}: $\langle a_1,\dots,a_n\rangle = Ra_1 + \cdots + Ra_n = \{ \sum r_i a_i \}$. This is the set of all $R$-linear combinations of the generators.
\item For a \emph{single} generator: $\langle a\rangle = \{ ra : r \in R\}$ --- the multiples of $a$.
\item To test ``\emph{is $I$ principal?}'' look for a single $d \in I$ with $I = \langle d\rangle$. In $\mathbb{Z}$ or any PID, take $d = \gcd$ of the generators.
\item Noncommutative warning: you must allow products on \emph{both} sides, $\sum r_i a_i s_i$.
\end{enumerate}
\end{method}

\begin{wex}{$\langle 6,10\rangle$ collapses to a principal ideal in $\mathbb{Z}$}
Find a single generator for $\langle 6,10\rangle \subseteq \mathbb{Z}$.
\wrec In $\mathbb{Z}$ a sum of multiples $6a + 10b$ ranges over all multiples of $\gcd(6,10)$; so the two-generator ideal is principal.
\wsol $\langle 6,10\rangle = 6\mathbb{Z} + 10\mathbb{Z} = \{6a + 10b : a,b\in\mathbb{Z}\}$. By B\'ezout this equals $\gcd(6,10)\mathbb{Z} = 2\mathbb{Z} = \langle 2\rangle$ (indeed $2 = 6\cdot 2 + 10\cdot(-1)$). \textit{Check.} $2 \mid 6$ and $2 \mid 10$ so $\langle 6,10\rangle\subseteq\langle 2\rangle$; and $2 \in \langle 6,10\rangle$ gives the reverse. So $\langle 6,10\rangle = \langle 2\rangle$.
\end{wex}

\begin{wex}{A non-principal ideal: $\langle 2,x\rangle$ is not principal in $\mathbb{Z}[x]$}
Show $\langle 2,x\rangle$ is \emph{not} principal in $\mathbb{Z}[x]$.
\wrec If $\langle 2,x\rangle = \langle d\rangle$ then $d \mid 2$ and $d \mid x$ in $\mathbb{Z}[x]$; analyze degrees and units.
\wsol Suppose $\langle 2,x\rangle = \langle d\rangle$. From $2 \in \langle d\rangle$ we get $d \mid 2$, so $d$ is a degree-$0$ polynomial dividing $2$ in $\mathbb{Z}[x]$: $d \in \{\pm 1, \pm 2\}$. From $x \in \langle d\rangle$ we get $d \mid x$, i.e.\ $x = d\,h(x)$; comparing leading coefficients forces $d \mid 1$, so $d = \pm 1$. But then $\langle d\rangle = \mathbb{Z}[x] \ni 1$, while $1 \notin \langle 2,x\rangle$ (constant term odd). Contradiction. \textit{Check.} $\langle 2,x\rangle$ needs two generators; $\mathbb{Z}[x]$ is not a PID.
\end{wex}

\begin{proposition}[Unit criterion: when is $I = R$?]\label{prop:unit@c7}
Let $I$ be an ideal of a ring $R$ with identity $1$.
\begin{enumerate}
\item[(1)] $I = R$ if and only if $I$ contains a unit.
\item[(2)] If $R$ is commutative, then $R$ is a field if and only if its only ideals are $0$ and $R$.
\end{enumerate}
\end{proposition}

\begin{proof}
(1) If $I = R$ then $1 \in I$ and $1$ is a unit. Conversely, if $u \in I$ is a unit with inverse $u^{-1}$, then $1 = u^{-1} u \in I$ (ideals absorb multiplication), so for any $r \in R$, $r = r\cdot 1 \in I$; thus $I = R$.

(2) ($\Longrightarrow$) Let $R$ be a field and $I \neq 0$ an ideal. Pick $0 \neq a \in I$; since $a$ is a unit, $I = R$ by (1). ($\Leftarrow$) Suppose the only ideals are $0$ and $R$, and let $0 \neq a \in R$. The principal ideal $\langle a\rangle \neq 0$, so $\langle a\rangle = R$, whence $1 \in \langle a\rangle = Ra$, i.e.\ $1 = ra$ for some $r$. Thus $a$ is a unit and $R$ is a field.
\end{proof}

\begin{pitfall}
The unit criterion needs an identity $1 \neq 0$. In a rng (ring without $1$), an ideal containing a left-invertible element need not be the whole ring. Also note ``$I$ contains a unit $\Longrightarrow I = R$'' is the workhorse for proving fields have no nontrivial ideals --- and for showing $R/M$ is a field below.
\end{pitfall}

\begin{wex}{$\langle 1/2\rangle$ in $\mathbb{Q}$, and ideals of a field}
What is the ideal $\langle 1/2\rangle$ in $\mathbb{Q}$? List all ideals of $\mathbb{Q}$.
\wrec $1/2$ is a unit in $\mathbb{Q}$; apply the unit criterion.
\wsol Since $1/2$ is a unit ($(1/2)^{-1}{} = 2$), Proposition~\ref{prop:unit@c7}(1) gives $\langle 1/2\rangle = \mathbb{Q}$. More generally every nonzero element of $\mathbb{Q}$ is a unit, so the only ideals of $\mathbb{Q}$ are $0$ and $\mathbb{Q}$. \textit{Check.} Consistent with Proposition~\ref{prop:unit@c7}(2): a field has exactly two ideals.
\end{wex}

\begin{wex}{A non-unit generates a proper ideal: $\langle 3\rangle$ in $\mathbb{Z}$}
Is $\langle 3\rangle \subsetneq \mathbb{Z}$?
\wrec $3$ is not a unit in $\mathbb{Z}$ (units are $\pm 1$); so by contrapositive of the unit criterion $\langle 3\rangle$ can be proper.
\wsol $\langle 3\rangle = 3\mathbb{Z} = \{\ldots,-3,0,3,6,\ldots\}$. Since $1 \notin 3\mathbb{Z}$ (no integer $n$ has $3n = 1$), $\langle 3\rangle \neq \mathbb{Z}$. \textit{Check.} $\units{\mathbb{Z}} = \{\pm 1\}$, and indeed $3\notin\units\mathbb{Z}$, consistent with $\langle 3\rangle \neq \mathbb{Z}$.
\end{wex}

\begin{definition}[Maximal ideal]
An ideal $M$ of $R$ is a \emph{maximal ideal} if $M \neq R$ and the only ideals containing $M$ are $M$ and $R$. Equivalently, $M$ is a maximal element (under inclusion) of the set of proper ideals of $R$.
\end{definition}

\begin{theorem}[Existence of maximal ideals via Zorn's Lemma]\label{thm:zorn@c7}
In a ring $R$ with identity $1 \neq 0$, every proper ideal $I \subsetneq R$ is contained in a maximal ideal. In particular, $R$ has at least one maximal ideal.
\end{theorem}

\begin{proof}[Proof sketch]
Let $\Sigma$ be the set of proper ideals of $R$ containing $I$, partially ordered by inclusion; $\Sigma \neq \varnothing$ since $I \in \Sigma$. Let $\mathcal C = \{J_\alpha\}$ be a chain in $\Sigma$ and put $J = \bigcup_\alpha J_\alpha$. A union of a chain of ideals is an ideal (any two elements lie in a common $J_\alpha$, so closure holds). Moreover $J$ is \emph{proper}: if $1 \in J$ then $1 \in J_\alpha$ for some $\alpha$, forcing $J_\alpha = R$, contradicting $J_\alpha \in \Sigma$. So $J \in \Sigma$ is an upper bound for $\mathcal C$. By Zorn's Lemma $\Sigma$ has a maximal element $M$, which is a maximal ideal containing $I$.
\end{proof}

\begin{theorem}[$M$ maximal $\Longleftrightarrow$ $R/M$ a field]\label{thm:maxfield@c7}
Let $R$ be a \emph{commutative} ring with $1 \neq 0$ and $M$ an ideal. Then
\[
M \text{ is maximal} \quad\Longleftrightarrow\quad R/M \text{ is a field}.
\]
\end{theorem}

\begin{proof}
By the lattice (correspondence) theorem, ideals of $R/M$ correspond bijectively, preserving inclusion, to ideals of $R$ containing $M$:
\[
\begin{tikzcd}[row sep=small,column sep=large]
\{\text{ideals } J \text{ with } M \subseteq J \subseteq R\} \arrow[r, leftrightarrow, "1\text{-}1"] & \{\text{ideals of } R/M\}
\end{tikzcd}
\]
\begin{dgx}
\dgi{Objects:} The left node is the poset of ideals $J$ of $R$ satisfying $M \subseteq J \subseteq R$; the right node is the poset of all ideals of the quotient ring $R/M$.  Both are sets of ideals, ordered by inclusion.
\dgi{Arrows:} A single double-headed left-right arrow labelled $1\text{-}1$ represents the lattice isomorphism (bijection preserving inclusion in both directions) $J \mapsto J/M = \{\,j + M : j \in J\,\}$ and its inverse $\bar I \mapsto \pi^{-1}(\bar I)$, where $\pi: R \to R/M$ is the quotient map.
\dgi{What commutes:} Because there is only one arrow, the content is the bijection itself: every ideal $J$ with $M \subseteq J$ maps to the ideal $J/M$ of $R/M$, and every ideal $\bar I$ of $R/M$ pulls back to the ideal $\pi^{-1}(\bar I)$ of $R$; these two operations are mutually inverse and inclusion-preserving.
\dgi{Why it commutes:} Well-definedness of $J \mapsto J/M$: for $j \in J$ and $r \in R$, $(r+M)(j+M) = rj + M \in J/M$ since $rj \in J$; closure under addition and the subgroup property are inherited similarly.  The inverse is well-defined because preimages of ideals under ring homomorphisms are ideals.  Inclusion-preservation: $J_1 \subseteq J_2 \Leftrightarrow J_1/M \subseteq J_2/M$ because adding the same coset class cannot create new containments.
\dgi{Why this matters here:} This correspondence is the core of the proof: $M$ maximal means the only $J$ with $M \subseteq J \subseteq R$ are $M$ and $R$ themselves, which by the bijection means the only ideals of $R/M$ are $M/M = 0$ and $R/M$ --- exactly the field condition.
\dgi{Concrete example:} Take $R = \mathbb{Z}$, $M = \langle 6\rangle$.  Ideals containing $\langle 6\rangle$ are $\langle 6\rangle, \langle 3\rangle, \langle 2\rangle, \langle 1\rangle = \mathbb{Z}$.  On the right, ideals of $\mathbb{Z}/6\mathbb{Z}$ are $\langle \bar 0\rangle, \langle \bar 3\rangle, \langle \bar 2\rangle, \langle \bar 1\rangle$ --- four ideals in bijection.  Since there are ideals strictly between $\langle 6\rangle$ and $\mathbb{Z}$, the ideal $\langle 6\rangle$ is not maximal.
\dgi{Common pitfall:} Students often confuse the correspondence with the isomorphism $R/M \cong$ something concrete: the diagram says nothing about what $R/M$ looks like internally, only that its ideal lattice mirrors the ideals of $R$ above $M$.  Also, the correspondence requires $M$ to be an \emph{ideal} (not just a subgroup) for $J/M$ to be a ring ideal.
\dgi{Takeaway:} The point of this diagram is that the ideal lattice of the quotient $R/M$ is an exact copy of the portion of $R$'s ideal lattice sitting above $M$, so maximality of $M$ translates into $R/M$ having the simplest possible ideal structure.
\end{dgx}
under $J \mapsto J/M$. Thus $M$ is maximal $\Longleftrightarrow$ the only ideals containing $M$ are $M, R$ $\Longleftrightarrow$ the only ideals of $R/M$ are $0 = M/M$ and $R/M$. Since $R/M$ is a commutative ring with $1$, Proposition~\ref{prop:unit@c7}(2) says this happens $\Longleftrightarrow R/M$ is a field.
\end{proof}

\begin{method}{Testing maximality via the quotient}
\textit{Trigger.} Asked whether $M$ is maximal in a commutative ring $R$.
\begin{enumerate}
\item Form the quotient $R/M$ and identify it as a familiar ring (use the First Isomorphism Theorem: realize $R/M$ as the image of a homomorphism with kernel $M$).
\item $M$ maximal $\Longleftrightarrow R/M$ is a field. So: simplify $R/M$, then ask ``is every nonzero element invertible?''
\item Shortcut in $\mathbb{Z}$: $\langle n\rangle$ maximal $\Longleftrightarrow \mathbb{Z}/n\mathbb{Z}$ a field $\Longleftrightarrow n$ prime.
\item Shortcut in $\F[x]$ ($\F$ a field): $\langle p(x)\rangle$ maximal $\Longleftrightarrow p$ irreducible.
\end{enumerate}
\end{method}

\begin{wex}{A maximal ideal of $\mathbb{Z}$ that is determined by primality}
Which principal ideals $\langle n\rangle$ of $\mathbb{Z}$ are maximal?
\wrec In $\mathbb{Z}$, $\langle n\rangle$ maximal $\Longleftrightarrow \mathbb{Z}/n\mathbb{Z}$ a field $\Longleftrightarrow n$ prime.
\wsol $\mathbb{Z}/n\mathbb{Z}$ is a field iff $n$ is prime (for $n$ prime every nonzero residue is a unit by B\'ezout; for $n = ab$ composite, $\bar a$ is a zero divisor, not a unit). So $\langle n\rangle$ is maximal exactly when $n = p$ is prime. \textit{Check.} $\langle 0\rangle = 0$ is not maximal since $0 \subsetneq \langle 2\rangle \subsetneq \mathbb{Z}$; $\langle 1\rangle = \mathbb{Z}$ is not proper; $\langle 6\rangle$ is not maximal since $\langle 6\rangle \subsetneq \langle 2\rangle \subsetneq \mathbb{Z}$.
\end{wex}

\begin{theorem}[$P$ prime $\Longleftrightarrow$ $R/P$ an integral domain]\label{thm:primedomain@c7}
Let $R$ be a commutative ring with $1 \neq 0$ and $P$ a proper ideal. Then
\[
P \text{ is prime} \quad\Longleftrightarrow\quad R/P \text{ is an integral domain}.
\]
\end{theorem}

\begin{proof}
Write $\bar r = r + P$ for the image in $R/P$, so $\bar r = \bar 0 \Longleftrightarrow r \in P$. Then:
\[
P \text{ prime}
\ \Longleftrightarrow\ \big(ab \in P \Longrightarrow a \in P \text{ or } b \in P\big)
\ \Longleftrightarrow\ \big(\bar a \bar b = \bar 0 \Longrightarrow \bar a = \bar 0 \text{ or } \bar b = \bar 0\big),
\]
which is precisely the statement that $R/P$ has \emph{no zero divisors}. Since $P \neq R$, the quotient $R/P$ has $1 \neq 0$ and is commutative, so this says $R/P$ is an integral domain.
\end{proof}

\begin{corollary}[Every maximal ideal is prime]\label{cor:maxprime@c7}
In a commutative ring $R$ with $1 \neq 0$, every maximal ideal is prime.
\end{corollary}

\begin{proof}
Let $M$ be maximal. By Theorem~\ref{thm:maxfield@c7}, $R/M$ is a field. Every field is an integral domain (a unit is never a zero divisor: if $ab = 0$ with $a \neq 0$, multiply by $a^{-1}$ to get $b = 0$). By Theorem~\ref{thm:primedomain@c7}, $M$ is prime.
\end{proof}

\begin{method}{Testing primality via the quotient}
\textit{Trigger.} Asked whether $P$ is prime in a commutative ring $R$.
\begin{enumerate}
\item Form $R/P$ and identify it. $P$ prime $\Longleftrightarrow R/P$ a domain (no zero divisors); $P$ maximal $\Longleftrightarrow R/P$ a field. Since field $\Longrightarrow$ domain, maximal $\Longrightarrow$ prime.
\item Direct test: assume $ab \in P$ and deduce $a \in P$ or $b \in P$.
\item In $\mathbb{Z}$: $\langle n\rangle$ prime $\Longleftrightarrow n = 0$ or $n = p$ prime (because $\mathbb{Z}/n\mathbb{Z}$ a domain $\Longleftrightarrow n = 0$ or $n$ prime).
\item To show \emph{not} maximal but prime: exhibit a domain quotient that is \emph{not} a field (e.g.\ $\mathbb{Z}[x]/\langle x\rangle \cong \mathbb{Z}$).
\end{enumerate}
\end{method}

\begin{wex}{The ideals of $\mathbb{Z}$: which are prime, which maximal}
Classify all ideals of $\mathbb{Z}$ and determine which are prime and which maximal.
\wrec $\mathbb{Z}$ is a PID, so every ideal is $\langle n\rangle$; test each via $\mathbb{Z}/n\mathbb{Z}$.
\wsol Every ideal of $\mathbb{Z}$ is principal: $I = \langle n\rangle = n\mathbb{Z}$ for a unique $n \geq 0$ (take $n$ the least positive element, or $n = 0$). Now use the quotients:
\begin{itemize}
\item $\langle 0\rangle = 0$: $\mathbb{Z}/0\mathbb{Z} \cong \mathbb{Z}$ is a domain but not a field, so $\langle 0\rangle$ is \emph{prime, not maximal}.
\item $\langle 1\rangle = \mathbb{Z}$: not a proper ideal, so neither prime nor maximal.
\item $\langle p\rangle$, $p$ prime: $\mathbb{Z}/p\mathbb{Z} = \F_p$ is a field, so \emph{prime and maximal}.
\item $\langle n\rangle$, $n = ab$ composite ($1 < a,b < n$): $\bar a \bar b = \bar n = \bar 0$ with $\bar a, \bar b \neq \bar 0$, so $\mathbb{Z}/n\mathbb{Z}$ has zero divisors --- \emph{neither prime nor maximal}.
\end{itemize}
\textit{Check.} Prime ideals of $\mathbb{Z}$ are exactly $\langle 0\rangle$ and $\langle p\rangle$; the maximal ones are exactly the $\langle p\rangle$. Consistent with maximal $\Longrightarrow$ prime, and $\langle 0\rangle$ shows the converse fails.
\end{wex}

\begin{pitfall}
``Prime'' does not imply ``maximal.'' The gap is exactly: $R/P$ a domain vs.\ $R/P$ a field. The standard counterexamples: $\langle 0\rangle$ in any domain that is not a field (e.g.\ $\mathbb{Z}$, $\F[x]$), and $\langle x\rangle \subsetneq \mathbb{Z}[x]$. The reverse implication \emph{maximal} $\Longrightarrow$ \emph{prime} always holds (Corollary~\ref{cor:maxprime@c7}) because every field is a domain. Also: the prime-ideal definition is only stated for \emph{commutative} rings in this section; do not apply $ab \in P \Longrightarrow a\in P$ or $b\in P$ as the definition in a noncommutative ring.
\end{pitfall}

\begin{pitfall}
$\langle 0\rangle$ (the zero ideal) is prime $\Longleftrightarrow R$ is an integral domain, and maximal $\Longleftrightarrow R$ is a field. So in $\mathbb{Z}$ the zero ideal is prime but not maximal; in $\mathbb{Q}$ it is both. Always check whether your ideal is proper before calling it prime or maximal --- $R$ itself is excluded by definition.
\end{pitfall}

\begin{corollary}[D\&F 7.5, Corollary 16: $\Frac(R)$ is a field]\label{cor:fracfield@c7}
If $R$ is an integral domain then $\Frac(R)$ is a field, and it is the \emph{smallest}
field containing (an isomorphic copy of) $R$ in the following sense: if $K$ is any field
containing $R$ as a subring, then the subfield of $K$ generated by $R$ is isomorphic to
$\Frac(R)$. Concretely $\Frac(R)=\{\,a/b : a\in R,\ b\in R,\ b\neq 0\,\}$.
\end{corollary}

\begin{method}{Using the universal property to embed a domain in a field}
\textit{Trigger.} You must show a domain $R$ sits inside a field, or you have a map
$f\colon R\to F$ into a field and want to extend it to fractions, or you need to prove two
fields-of-fractions are isomorphic.
\textit{Recipe.}
\begin{enumerate}
\item Confirm $R$ is an integral domain (so $\Frac(R)$ exists and is a field).
\item Produce an injective ring hom $f\colon R\to F$ into your target field $F$.
\item Invoke Theorem~\ref{thm:UP@c7}: get the unique $\bar f(\frac ab)=f(a)f(b)^{-1}$,
automatically injective, so $\Frac(R)\hookrightarrow F$.
\item For an isomorphism $\Frac(R)\cong K$: show $K$ is a field containing $R$ in which
every element is $a b^{-1}$ with $a,b\in R,\ b\neq0$; then $\bar f$ is onto, hence iso.
\end{enumerate}
\textit{Check.} Verify $\bar f\circ\iota=f$ on generators of $R$ and that $\bar f$ hits
every element of $K$ for surjectivity.
\end{method}

\begin{remark}
Comaximal means: no proper ideal (in particular no maximal ideal) contains both $I$ and $J$. Equivalently, $I+J=R$ iff $1\in I+J$ iff there exist $a\in I$, $b\in J$ with $a+b=1$. In $\mathbb{Z}$, where every ideal is $\langle n\rangle=n\mathbb{Z}$, we have $m\mathbb{Z}+n\mathbb{Z}=\gcd(m,n)\mathbb{Z}$, so $m\mathbb{Z}$ and $n\mathbb{Z}$ are comaximal exactly when $\gcd(m,n)=1$. Always $IJ\subseteq I\cap J$ (each generator $ab\in I$ and $ab\in J$); comaximality forces equality (Theorem~\ref{thm:crt@c7}), but it is not necessary for it: $(x)\cap(y)=(xy)=(x)(y)$ in $\mathbb{Q}[x,y]$, although $(x)+(y)=(x,y)\neq\mathbb{Q}[x,y]$.
\end{remark}

\begin{method}{Applying the Chinese Remainder Theorem}
\textit{Recognition trigger.} You see a quotient $R/N$ where the modulus $N$ factors as a product (or intersection) of ideals --- e.g. $\mathbb{Z}/n\mathbb{Z}$ with $n=p_1^{a_1}\cdots p_r^{a_r}$, $\F[x]/(f)$ with $f=f_1\cdots f_r$ coprime --- or you must solve simultaneous congruences $r\equiv a_j\pmod{I_j}$.
\begin{enumerate}
\item \textbf{Check comaximality pairwise.} Show $I_i+I_j=R$ for all $i\neq j$, i.e. exhibit $a_{ij}\in I_i,\ b_{ij}\in I_j$ with $a_{ij}+b_{ij}=1$. In $\mathbb{Z}$: $\gcd$ of the moduli is $1$. In $\F[x]$: the polynomials are pairwise coprime (run the Euclidean algorithm / B\'ezout).
\item \textbf{Conclude the splitting.} Comaximality $\Rightarrow$ $I_1\cap\cdots\cap I_k=I_1\cdots I_k$ and $R/(I_1\cdots I_k)\cong\prod_j R/I_j$.
\item \textbf{Build the inverse (to solve systems).} For each $j$ form an ``idempotent'' $e_j$ with $e_j\equiv 1\pmod{I_j}$ and $e_j\equiv 0\pmod{I_i}$ for $i\neq j$, using the B\'ezout coefficients. Then $r=\sum_j a_j e_j$ realizes the target $(a_1,\dots,a_k)$.
\end{enumerate}
\textit{Sanity check.} Reduce your candidate $r$ modulo each $I_j$ and confirm you recover $a_j$; check the cardinalities multiply ($|R/N|=\prod|R/I_j|$) in the finite case.
\end{method}

\begin{pitfall}
\textbf{Comaximality is required for surjectivity, and it is what guarantees $\cap=\,$product --- not merely a convenience.} Without it the kernel of $\varphi$ is $\bigcap I_j$, which can strictly contain $\prod I_j$ (see the $2\mathbb{Z},4\mathbb{Z}$ example), and $\varphi$ need not be onto. The First Isomorphism Theorem \emph{always} gives the \emph{injection} $R/\bigcap I_j\hookrightarrow\prod R/I_j$; surjectivity is the extra content of the CRT.
\end{pitfall}

\begin{pitfall}
\textbf{Pairwise comaximal is genuinely needed for $k\ge 3$; ``jointly $I_1+\cdots+I_k=R$'' is not enough.} For example in $\mathbb{Z}$ take $I_1=2\mathbb{Z},\ I_2=2\mathbb{Z},\ I_3=3\mathbb{Z}$: then $I_1+I_2+I_3=\mathbb{Z}$, yet $I_1,I_2$ are not comaximal ($2\mathbb{Z}+2\mathbb{Z}=2\mathbb{Z}$), and $\mathbb{Z}/(I_1\cap I_2\cap I_3)=\mathbb{Z}/(2\mathbb{Z}\cap 3\mathbb{Z})=\mathbb{Z}/6\mathbb{Z}$ has $6$ elements while $\prod R/I_j$ has $2\cdot 2\cdot 3=12$ --- no isomorphism. Always verify $I_i+I_j=R$ for \emph{every} pair.
\end{pitfall}

\begin{pitfall}
\textbf{$IJ$ is the ideal generated by products, not the set of single products.} Elements of $IJ$ are finite \emph{sums} $\sum a_kb_k$. Writing ``$IJ=\{ab\st a\in I,b\in J\}$'' is wrong in general (that set need not be closed under addition). For principal ideals in a commutative ring it does collapse: $\langle a\rangle\langle b\rangle=\langle ab\rangle$.
\end{pitfall}

\begin{remark}[Idempotents and the product structure]
When $R\cong R_1\times R_2$ the elements $e_1=(1,0)$ and $e_2=(0,1)$ are \emph{orthogonal idempotents}: $e_i^2=e_i$, $e_1 e_2=0$, $e_1+e_2=1$. Conversely such a pair in any commutative ring $R$ splits it as $R\cong Re_1\times Re_2$. In the CRT setting the idempotents are exactly the B\'ezout-built elements $e_j$ of the Method box (e.g. $9$ and $4$ in $\mathbb{Z}/12\mathbb{Z}$; $x+1$ and $x$ in $\F_2[x]/(x^2+x)$). Thus ``solve a congruence system'' and ``find the complementary idempotents'' are the same computation.
\end{remark}

For $V \subseteq U$ define the \emph{restriction maps} $\rho_{UV} : A_U \to A_V$ by $f \mapsto f|_V$, the usual restriction of a function on $U$ to the smaller set $V$ (which is easily seen to be a ring homomorphism). Let $A = \varinjlim A_U$ be the direct limit. In the notation of the preceding exercise, show that the maps $\rho_U : A_U \to A$ are not injective but are all surjective ($A$ is called the ring of \emph{germs of continuous functions at} $p$).

\item We now develop the notion of \emph{inverse limits}; continue to assume $I$ is a partially ordered set (but not necessarily directed), and $A_i$ is a group for all $i \in I$. Suppose for every pair of indices $i, j$ with $i \leq j$ there is a map $\mu_{ji} : A_j \to A_i$ such that the following hold:
\begin{enumerate}
\item[i.] $\mu_{ji} \circ \mu_{kj} = \mu_{ki}$ whenever $i \leq j \leq k$, and
\item[ii.] $\mu_{ii} = 1$ for all $i \in I$.
\end{enumerate}
Let $P$ be the subset of elements $(a_i)_{i \in I}$ in the direct product $\prod_{i \in I} A_i$ such that $\mu_{ji}(a_j) = a_i$ whenever $i \leq j$ (here again $i, j \in I$). The set $P$ is called the \emph{inverse} or \emph{projective limit} of the system $\{A_i\}$, and is denoted $\varprojlim A_i$.
\begin{enumerate}
\item[(a)] Assume all $\mu_{ji}$ are group homomorphisms. Show that $P$ is a subgroup of the direct product group (cf. Exercise 15, Section 5.1).
\item[(b)] Assume the hypotheses in (a), and let $I = \mathbb{Z}^+$ (usual ordering). For each $i \in I$ let $\mu_i : P \to A_i$ be the projection of $P$ onto its $i$th component. Show that if each $\mu_{ji}$ is surjective, then so is $\mu_i$ for all $i$ (so each $A_i$ is a quotient group of $P$).
\item[(c)] Show that if all $A_i$ are commutative rings with 1 and all $\mu_{ji}$ are ring homomorphisms that send 1 to 1, then $P$ may likewise be given the structure of a commutative ring with 1 such that all $\mu_i$ are ring homomorphisms.
\item[(d)] Under the hypotheses in (a) prove that the inverse limit has the following \emph{universal property}: if $D$ is any group and $\pi_i : D \to A_i$ are group homomorphisms such that $\pi_i = \mu_{ji} \circ \pi_j$ whenever $i \leq j$, then there is a unique homomorphism $\pi : D \to P$ such that $\mu_i \circ \pi = \pi_i$ for all $i$.
\end{enumerate}

\item Let $p$ be a prime, let $I = \mathbb{Z}^+$, let $A_i = \mathbb{Z}/p^i\mathbb{Z}$ and let $\mu_{ji}$ be the natural projection maps $\mu_{ji} : a \pmod{p^j} \mapsto a \pmod{p^i}$. The inverse limit $\varprojlim \mathbb{Z}/p^i\mathbb{Z}$ is called the ring of \emph{$p$-adic integers}, and is denoted by $\mathbb{Z}_p$.
\begin{enumerate}
\item[(a)] Show that every element of $\mathbb{Z}_p$ may be written uniquely as an infinite formal sum $b_0 + b_1 p + b_2 p^2 + b_3 p^3 + \cdots$ with each $b_i \in \{0, 1, \ldots, p-1\}$. Describe the rules for adding and multiplying such formal sums corresponding to addition and multiplication in the ring $\mathbb{Z}_p$. [Write a least residue in each $\mathbb{Z}/p^i\mathbb{Z}$ in its base $p$ expansion and then describe the maps $\mu_{ji}$.] (Note in particular that $\mathbb{Z}_p$ is uncountable.)
\item[(b)] Prove that $\mathbb{Z}_p$ is an integral domain that contains a copy of the integers.
\item[(c)] Prove that $b_0 + b_1 p + b_2 p^2 + b_3 p^3 + \cdots$ as in (a) is a unit in $\mathbb{Z}_p$ if and only if $b_0 \neq 0$.
\item[(d)] Prove that $p \mathbb{Z}_p$ is the unique maximal ideal of $\mathbb{Z}_p$ and $\mathbb{Z}_p / p \mathbb{Z}_p \cong \mathbb{Z}/p\mathbb{Z}$ (where $p = 0 + 1p + 0p^2 + 0p^3 + \cdots$). Prove that every nonzero ideal of $\mathbb{Z}_p$ is of the form $p^n \mathbb{Z}_p$ for some integer $n \geq 0$.
\item[(e)] Show that if $a_1 \neq 0 \pmod{p}$ then there is an element $a = (a_i)$ in the inverse limit $\mathbb{Z}_p$ satisfying $a_i^{p-1} \equiv 1 \pmod{p^i}$ and $\mu_{j1}(a_j) = a_1$ for all $j$. Deduce that $\mathbb{Z}_p$ contains $p-1$ distinct $(p-1)^{\text{st}}$ roots of 1.
\end{enumerate}
\end{exers}

\begin{remark}
The remainder need not be unique. In $\mathbb{Z}$ with $\Nm(n)=|n|$ we may write
$5 = 1\cdot 3 + 2$ \emph{or} $5 = 2\cdot 3 + (-1)$; both have $|r|<|3|$. The definition
demands only that \emph{some} valid $(q,r)$ exists, not a canonical one.
\end{remark}

\begin{proof}
Back-substitute the Euclidean Algorithm. From $r_k=r_{k-2}-q_kr_{k-1}$, and recursively
expressing each $r_j$ as an $R$-combination of $a,b$, we obtain $d=r_k=ax+by$ for some
$x,y\in R$. Thus $d\in\langle a,b\rangle$, so $\langle d\rangle\subseteq\langle a,b\rangle$. The reverse inclusion is
$d\mid a$ and $d\mid b$, i.e.\ $a,b\in\langle d\rangle$. Hence $\langle a,b\rangle=\langle d\rangle$.
\end{proof}

\begin{method}{Division / Euclidean / Bezout recipe}
\textit{Trigger.} You are in $\mathbb{Z}$, $\F[x]$, or $\mathbb{Z}[i]$ (anything with a stated norm and
Division Algorithm) and you need to (a) divide with remainder, (b) compute a gcd, or
(c) write the gcd as a linear combination.
\begin{enumerate}
\item \textbf{One division.} To compute $q,r$ in $a=qb+r$:
  \begin{itemize}
  \item $\mathbb{Z}$: $q=\lfloor a/b\rfloor$ (or nearest integer), $r=a-qb$.
  \item $\F[x]$: long division; cancel the leading term repeatedly until $\deg r<\deg b$.
  \item $\mathbb{Z}[i]$: form $a/b=\frac{a\overline b}{\Nm(b)}\in\mathbb{Q}(i)$, round each coordinate to
        the nearest integer to get $q$, set $r=a-qb$.
  \end{itemize}
\item \textbf{gcd.} Iterate: replace $(a,b)\mapsto(b,r)$ until $r=0$. The last nonzero
remainder is the gcd (unique up to a unit multiple).
\item \textbf{Bezout.} Solve each division equation for its remainder and back-substitute
from the bottom up, eliminating intermediate remainders, until only $a,b$ remain.
\item \textit{Check.} Recompute $ax+by$ and confirm it equals $d$; confirm $d\mid a$
and $d\mid b$.
\end{enumerate}
\end{method}

\begin{theorem}[{$\F[x]$ is Euclidean}]\label{thm:fxeuclid@c8}
If $\F$ is a field then $\F[x]$ with $\Nm(f)=\deg f$ is a Euclidean domain: for
$a,b\in\F[x]$ with $b\neq0$ there are unique $q,r$ with $a=qb+r$ and $r=0$ or
$\deg r<\deg b$.
\end{theorem}

\begin{pitfall}
The leading coefficient of $b$ must be a \emph{unit}. Over $\mathbb{Z}$ (not a field) you cannot
divide $x$ by $2x$ inside $\mathbb{Z}[x]$ with a smaller-degree remainder, and indeed $\mathbb{Z}[x]$ is
\emph{not} a Euclidean domain (it is not even a PID, since $\langle 2,x\rangle$ is not principal).
The field hypothesis is what makes $\F[x]$ Euclidean.
\end{pitfall}

\begin{theorem}[{$\mathbb{Z}[i]$ is Euclidean}]\label{thm:zieuclid@c8}
The Gaussian integers $\mathbb{Z}[i]$ with $\Nm(a+bi)=a^2+b^2$ form a Euclidean domain. Concretely,
for $\alpha,\beta\in\mathbb{Z}[i]$ with $\beta\neq0$ there exist $q,r\in\mathbb{Z}[i]$ with
$\alpha=q\beta+r$ and $\Nm(r)\le\tfrac12\Nm(\beta)<\Nm(\beta)$.
\end{theorem}

\begin{remark}
$\Nm$ on $\mathbb{Z}[i]$ is multiplicative: $\Nm(\alpha\beta)=\Nm(\alpha)\Nm(\beta)$ (it is
$|\alpha|^2$). Consequently the units of $\mathbb{Z}[i]$ are exactly the elements of norm $1$,
namely $\units{\mathbb{Z}[i]}=\{\pm1,\pm i\}$, and $\beta\mid\alpha$ forces
$\Nm(\beta)\mid\Nm(\alpha)$ in $\mathbb{Z}$ -- a powerful divisibility test.
\end{remark}

\begin{method}{Dividing in $\mathbb{Z}[i]$ (round to nearest lattice point)}
\textit{Trigger.} You must divide, gcd, or factor in $\mathbb{Z}[i]$.
\begin{enumerate}
\item Multiply numerator and denominator by $\overline\beta$:
$\dfrac{\alpha}{\beta}=\dfrac{\alpha\overline\beta}{\Nm(\beta)}=s+ti$.
\item Round: $m=\operatorname{round}(s)$, $n=\operatorname{round}(t)$; set $q=m+ni$.
\item Remainder $r=\alpha-q\beta$. It automatically satisfies $\Nm(r)<\Nm(\beta)$.
\item For a gcd, iterate $(\alpha,\beta)\mapsto(\beta,r)$. For factoring, use
multiplicativity: if $\Nm(\alpha)=p$ is a prime in $\mathbb{Z}$, then $\alpha$ is irreducible in
$\mathbb{Z}[i]$; factor $\Nm(\alpha)$ in $\mathbb{Z}$ first to know what norms to look for.
\end{enumerate}
\end{method}

\begin{method}{Proving ``not Euclidean'' via side divisors}
\textit{Trigger.} You suspect a domain $R$ (not a field) is not Euclidean and want a proof
that rules out \emph{all} norms.
\begin{enumerate}
\item Identify $\units R$ (often just $\{\pm1\}$), so $\tilde R=\units R\cup\{0\}$ is small.
\item Find \emph{all} candidate universal side divisors by applying the definition to one
well-chosen $x$: a universal side divisor $u$ divides $x-z$ for some $z\in\tilde R$, so it is a
nonunit divisor of one of these finitely many elements (e.g.\ for $x=2$ and $\tilde R=\{0,\pm1\}$:
a divisor of $2$ or $3$). Do not simply take the elements of smallest field norm: the norm in
the Proposition is an unknown Euclidean norm, not the field norm.
\item For each candidate $u$, exhibit an $x$ such that $u\nmid(x-z)$ for \emph{every}
$z\in\tilde R$. This kills $u$.
\item If no universal side divisor exists, the contrapositive of the Proposition shows
$R$ is not Euclidean (for any norm).
\end{enumerate}
\end{method}

\begin{pitfall}
``Not Euclidean'' is a strong claim: it must hold for \emph{every} possible norm, not just
the obvious field norm. That is exactly why the universal side divisor (a norm-free
condition) is the right tool -- ruling out one norm proves nothing, but the absence of a
universal side divisor rules out all norms at once.
\end{pitfall}

\begin{exers}{Exercises (from the text).}
\item For each of the following five pairs of integers $a$ and $b$, determine their greatest common divisor $d$ and write $d$ as a linear combination $ax + by$ of $a$ and $b$.
\begin{enumerate}
\item[(a)] $a = 20$, $b = 13$.
\item[(b)] $a = 69$, $b = 372$.
\item[(c)] $a = 11391$, $b = 5673$.
\item[(d)] $a = 507885$, $b = 60808$.
\item[(e)] $a = 91442056588823$, $b = 779086434385541$ (the Euclidean Algorithm requires only 7 steps for these integers).
\end{enumerate}

\item For each of the following pairs of integers $a$ and $n$, show that $a$ is relatively prime to $n$ and determine the inverse of $a$ mod $n$ (cf.\ D\&F, Section 0.3).
\begin{enumerate}
\item[(a)] $a = 13$, $n = 20$.
\item[(b)] $a = 69$, $n = 89$.
\item[(c)] $a = 1891$, $n = 3797$.
\item[(d)] $a = 6003722857$, $n = 77695236973$ (the Euclidean Algorithm requires only 3 steps for these integers).
\end{enumerate}

\item Let $R$ be a Euclidean Domain. Let $m$ be the minimum integer in the set of norms of nonzero elements of $R$. Prove that every nonzero element of $R$ of norm $m$ is a unit. Deduce that a nonzero element of norm zero (if such an element exists) is a unit.

\item Let $R$ be a Euclidean Domain.
\begin{enumerate}
\item[(a)] Prove that if $(a, b) = 1$ and $a$ divides $bc$, then $a$ divides $c$. More generally, show that if $a$ divides $bc$ with nonzero $a$, $b$ then $\frac{a}{(a,b)}$ divides $c$.
\item[(b)] Consider the Diophantine Equation $ax + by = N$ where $a$, $b$ and $N$ are integers and $a$, $b$ are nonzero. Suppose $x_0$, $y_0$ is a solution: $ax_0 + by_0 = N$. Prove that the full set of solutions to this equation is given by
\[ x = x_0 + \frac{b}{(a,b)} t \qquad y = y_0 - \frac{a}{(a,b)} t \]
as $t$ ranges over the integers. [If $x$, $y$ is a solution to $ax + by = N$, show that $a(x - x_0) = b(y_0 - y)$ and use (a).]
\end{enumerate}

\item Determine all integer solutions of the following equations:
\begin{enumerate}
\item[(a)] $2x + 4y = 5$
\item[(b)] $17x + 29y = 31$
\item[(c)] $85x + 145y = 505$.
\end{enumerate}

\item ({\it The Postage Stamp Problem}) Let $a$ and $b$ be two relatively prime positive integers. Prove that every sufficiently large positive integer $N$ can be written as a linear combination $ax + by$ of $a$ and $b$ where $x$ and $y$ are both nonnegative, i.e., there is an integer $N_0$ such that for all $N \geq N_0$ the equation $ax + by = N$ can be solved with both $x$ and $y$ nonnegative integers. Prove in fact that the integer $ab - a - b$ cannot be written as a nonnegative integer combination of $a$ and $b$ but that every integer greater than $ab - a - b$ is a nonnegative integer combination of $a$ and $b$ (so every ``postage'' greater than $ab - a - b$ can be obtained using only stamps in denominations $a$ and $b$).

\item Find a generator for the ideal $(85, 1 + 13i)$ in $\mathbb{Z}[i]$, i.e., a greatest common divisor for $85$ and $1 + 13i$, by the Euclidean Algorithm. Do the same for the ideal $(47 - 13i, 53 + 56i)$.

\item Let $F = \mathbb{Q}(\sqrt{D})$ be a quadratic field ($D\neq 0,1$ a squarefree integer) with associated quadratic integer ring $\mathcal{O}=\mathbb{Z}[\omega]$, where $\omega=\sqrt{D}$ if $D\equiv 2,3\pmod 4$ and $\omega=\frac{1+\sqrt{D}}{2}$ if $D\equiv 1\pmod 4$, and field norm $N(a+b\sqrt{D})=(a+b\sqrt{D})(a-b\sqrt{D})=a^2-Db^2$ ($a,b\in\mathbb{Q}$), as in D\&F, Section 7.1.
\begin{enumerate}
\item[(a)] Suppose $D$ is $-1$, $-2$, $-3$, $-7$ or $-11$. Prove that $\mathcal{O}$ is a Euclidean Domain with respect to $N$. [Modify the proof for $\mathbb{Z}[i]$ ($D = -1$) in the text. For $D = -3, -7, -11$ prove that every element of $F$ differs from an element in $\mathcal{O}$ by an element whose norm is at most $(1 + |D|)^2/(16|D|)$, which is less than $1$ for these values of $D$. Plotting the points of $\mathcal{O}$ in $\mathbb{C}$ may be helpful.]
\item[(b)] Suppose that $D = -43$, $-67$, or $-163$. Prove that $\mathcal{O}$ is not a Euclidean Domain with respect to any norm. [Apply the same proof as for $D = -19$ in the text.]
\end{enumerate}

\item Prove that the ring of integers $\mathcal{O}=\mathbb{Z}[\sqrt{2}]$ in the quadratic field $\mathbb{Q}(\sqrt{2})$ is a Euclidean Domain with respect to the norm given by the absolute value of the field norm $N(a+b\sqrt{2})=a^2-2b^2$ (cf. the previous exercise).

\item Prove that the quotient ring $\mathbb{Z}[i]/I$ is finite for any nonzero ideal $I$ of $\mathbb{Z}[i]$. [Use the fact that $I = (\alpha)$ for some nonzero $\alpha$ and then use the Division Algorithm in this Euclidean Domain to see that every coset of $I$ is represented by an element of norm less than $N(\alpha)$.]
\end{exers}

\begin{definition}[Principal ideal, principal ideal domain]
Let $R$ be a commutative ring. An ideal $I\subseteq R$ is \emph{principal} if $I=\langle a\rangle=aR$ for some single element $a\in R$. A \emph{principal ideal domain} (PID) is an integral domain in which \emph{every} ideal is principal.
\end{definition}

\begin{theorem}[ED $\Longrightarrow$ PID]
Every Euclidean domain is a principal ideal domain.
\end{theorem}

\begin{proof}
Let $R$ be a Euclidean domain with norm $N$, and let $I\subseteq R$ be an ideal. If $I=\langle 0\rangle$ it is principal, so assume $I\neq\langle 0\rangle$. Among the nonzero elements of $I$, choose $d\in I$ of \emph{minimal} norm $N(d)$ (possible since $N$ takes values in $\mathbb{Z}_{\ge 0}$, a well-ordered set). Clearly $\langle d\rangle\subseteq I$. Conversely take any $a\in I$ and divide: write $a=qd+r$ with $r=0$ or $N(r)<N(d)$. Then $r=a-qd\in I$. If $r\neq 0$ then $N(r)<N(d)$ contradicts the minimality of $N(d)$ among nonzero elements of $I$. Hence $r=0$, so $a=qd\in\langle d\rangle$. Therefore $I=\langle d\rangle$ is principal.
\end{proof}

