\item \textbf{To DISPROVE PID:} produce one ideal that is provably not principal (see the $\mathbb{Z}[x]$ method below).
\end{enumerate}
\end{method}

\begin{wex}{$\F[x]$ is a PID}
Let $\F$ be a field. Show $\F[x]$ is a PID and identify the generator of an arbitrary nonzero ideal.
\wrec ED $\Longrightarrow$ PID: $\F[x]$ carries the degree norm, so it is Euclidean, hence a PID. The generator-of-minimal-norm in the proof becomes the monic polynomial of least degree.
\wsol The map $N(f)=\deg f$ (for $f\neq 0$) makes $\F[x]$ Euclidean: polynomial long division over a field gives $f=qg+r$ with $r=0$ or $\deg r<\deg g$ (the leading coefficient of $g$ is a unit, so division never stalls). Hence $\F[x]$ is a PID by the theorem. Concretely, given an ideal $I\neq\langle 0\rangle$, pick $d\in I$ of least degree; rescaling by the inverse of its leading coefficient we may take $d$ monic, and the ED proof gives $I=\langle d\rangle$ with $d$ the unique monic generator. \textit{Check.} Two monic generators $d_1,d_2$ of $I$ satisfy $d_1\mid d_2$ and $d_2\mid d_1$, so they are associates; the only monic associate of a monic polynomial is itself, so the monic generator is unique.
\end{wex}

\begin{theorem}[gcd as ideal generator]
Let $R$ be a PID and $a,b\in R$ not both zero. Write $\langle a,b\rangle=\langle d\rangle$ (possible since $R$ is a PID). Then:
\begin{enumerate}
\item $d$ is a \emph{greatest common divisor} of $a$ and $b$: $d\mid a$, $d\mid b$, and if $e\mid a$ and $e\mid b$ then $e\mid d$.
\item $d=ax+by$ for some $x,y\in R$ (a linear combination of $a,b$).
\item $d$ is unique up to multiplication by a unit (i.e. up to associates).
\end{enumerate}
\end{theorem}

\begin{proof}
Since $a,b\in\langle a,b\rangle=\langle d\rangle$ we have $d\mid a$ and $d\mid b$. Since $d\in\langle a,b\rangle=aR+bR$, there are $x,y\in R$ with $d=ax+by$, giving (2). If $e\mid a$ and $e\mid b$ then $e$ divides $ax+by=d$, proving $d$ is \emph{greatest} and giving (1). For (3): if $\langle d\rangle=\langle d'\rangle$ then $d\mid d'$ and $d'\mid d$, so $d'=ud$ with $u\in\units{R}$. In a domain such $d,d'$ are associates.
\end{proof}

\begin{remark}
The equality $\langle a,b\rangle=\langle d\rangle$ packages two facts at once: \emph{existence} of a gcd (some rings, like $\mathbb{Z}[\sqrt{-5}]$, have pairs with no gcd) and the \emph{Bezout identity} $d=ax+by$. In a general UFD gcds exist but need \emph{not} be linear combinations; the linear-combination property is special to PIDs (it is equivalent to being a Bezout domain).
\end{remark}

\begin{method}{Finding the generator of a sum of ideals $\langle a\rangle+\langle b\rangle$}
\textit{Trigger.} You see $\langle a,b\rangle$, $\langle a\rangle+\langle b\rangle$, or ``the ideal generated by $a$ and $b$'' in a PID and want a single generator.
\begin{enumerate}
\item Compute $d=\gcd(a,b)$ (Euclidean algorithm if a norm is available).
\item Then $\langle a,b\rangle=\langle d\rangle$. Dually, $\langle a\rangle\cap\langle b\rangle=\langle \operatorname{lcm}(a,b)\rangle$.
\item Normalize: in $\mathbb{Z}$ take $d>0$; in $\F[x]$ take $d$ monic. This pins down the generator exactly.
\item Sanity check by back-substitution: write $d=ax+by$ to confirm $d\in\langle a,b\rangle$, and check $d\mid a,\ d\mid b$ to confirm $\langle a,b\rangle\subseteq\langle d\rangle$.
\end{enumerate}
\end{method}

\begin{theorem}[Nonzero prime ideals are maximal in a PID]
Let $R$ be a principal ideal domain. Then every nonzero prime ideal of $R$ is maximal.
\end{theorem}

