\begin{corollary}
In a PID $R$, a nonzero element $p$ is prime if and only if it is irreducible, and the quotient $R/\langle p\rangle$ is a field for every irreducible $p$.
\end{corollary}

\begin{proof}
$p$ prime $\Longleftrightarrow$ $\langle p\rangle$ nonzero prime $\Longleftrightarrow$ (by the theorem) $\langle p\rangle$ maximal $\Longleftrightarrow$ $R/\langle p\rangle$ a field. In any domain prime $\Longrightarrow$ irreducible. For the reverse, let $p$ be irreducible. Then $\langle p\rangle\neq\langle 0\rangle$ and $\langle p\rangle\neq R$, and $\langle p\rangle$ is contained in some maximal ideal $\langle m\rangle$. From $\langle p\rangle\subseteq\langle m\rangle$ we get $p=mr$; irreducibility forces $m$ or $r$ to be a unit, and $m$ is not a unit (else $\langle m\rangle=R$), so $r\in\units{R}$ and $\langle p\rangle=\langle m\rangle$ is maximal, hence prime.
\end{proof}

\begin{wex}{Prime $=$ maximal applied to $\mathbb{Z}$}
Show that in $\mathbb{Z}$ the nonzero prime ideals are precisely the maximal ideals, and list both.
\wrec $\mathbb{Z}$ is a PID, so the theorem applies: every nonzero prime ideal is maximal.
\wsol The ideals of $\mathbb{Z}$ are $\langle n\rangle$, $n\ge 0$. The ideal $\langle n\rangle$ is prime iff $n=0$ or $n=p$ prime. The \emph{nonzero} primes are exactly $\langle p\rangle$ for $p$ a rational prime, and each is maximal because $\mathbb{Z}/\langle p\rangle=\F_p$ is a field. The ideal $\langle 0\rangle$ is prime (since $\mathbb{Z}$ is a domain) but \emph{not} maximal --- this is the unique nonmaximal prime, and the theorem only claims maximality for \emph{nonzero} primes. \textit{Check.} $\langle 6\rangle$ is not prime ($2\cdot 3\in\langle 6\rangle$ but $2,3\notin\langle 6\rangle$), consistent with $6$ not being a rational prime; $\mathbb{Z}/\langle 6\rangle\cong\mathbb{Z}/2\times\mathbb{Z}/3$ is not a field.
\end{wex}

\begin{wex}{Prime $=$ maximal applied to $\F[x]$}
Show every nonzero prime ideal of $\mathbb{Q}[x]$ is maximal, and decide whether $\langle x^2+1\rangle$ and $\langle x^2-1\rangle$ are maximal.
\wrec $\mathbb{Q}[x]$ is a PID, so nonzero primes are maximal; primality of $\langle f\rangle$ is irreducibility of $f$.
\wsol Nonzero prime ideals of $\mathbb{Q}[x]$ are $\langle p(x)\rangle$ with $p$ irreducible, and each is maximal with $\mathbb{Q}[x]/\langle p\rangle$ a field. Now $x^2+1$ is irreducible over $\mathbb{Q}$ (no rational root, degree $2$), so $\langle x^2+1\rangle$ is maximal and $\mathbb{Q}[x]/\langle x^2+1\rangle\cong\mathbb{Q}(i)$, a field. But $x^2-1=(x-1)(x+1)$ is reducible, so $\langle x^2-1\rangle$ is \emph{not} prime, hence not maximal. \textit{Check.} $\mathbb{Q}[x]/\langle x^2-1\rangle\cong\mathbb{Q}[x]/\langle x-1\rangle\times\mathbb{Q}[x]/\langle x+1\rangle\cong\mathbb{Q}\times\mathbb{Q}$ by CRT --- a product of two fields, not a field, so indeed not maximal.
\end{wex}

\begin{wex}{The zero ideal can be a nonmaximal prime}
In $R=\mathbb{Q}[x]$, is $\langle 0\rangle$ prime? Maximal? Reconcile with the theorem.
\wrec The theorem restricts to \emph{nonzero} prime ideals; $\langle 0\rangle$ is exempt.
\wsol $\langle 0\rangle$ is prime since $R$ is a domain ($fg=0\Longrightarrow f=0$ or $g=0$). It is not maximal: $\langle 0\rangle\subsetneq\langle x\rangle\subsetneq R$. So $\langle 0\rangle$ is a prime that is not maximal, and there is no contradiction --- the theorem only promotes \emph{nonzero} primes to maximal. \textit{Check.} $R/\langle 0\rangle=R=\mathbb{Q}[x]$ is a domain but not a field ($x$ has no inverse), confirming $\langle 0\rangle$ is prime but not maximal.
\end{wex}

\begin{remark}
ACC is exactly the finiteness needed to prove existence of irreducible factorizations: if some element had no factorization into irreducibles, one could build a strictly ascending chain of ideals, contradicting ACC. This is the first half of ``PID $\Longrightarrow$ UFD'' (the second half, uniqueness, uses prime $=$ irreducible). We record the implication chain below.
\end{remark}

\begin{wex}{ACC fails in a non-PID}
Exhibit an ascending chain in $R=\mathbb{Q}[x_1,x_2,x_3,\dots]$ (infinitely many variables) that never stabilizes, illustrating that non-PIDs can fail ACC.
\wrec ACC is a \emph{theorem} for PIDs; a ring that violates ACC therefore cannot be a PID. We build a strictly increasing chain.
\wsol Let $I_k=\langle x_1,x_2,\dots,x_k\rangle$. Then $I_1\subsetneq I_2\subsetneq I_3\subsetneq\cdots$ since $x_{k+1}\in I_{k+1}\setminus I_k$ (no $R$-combination of $x_1,\dots,x_k$ produces $x_{k+1}$: evaluate at $x_1=\cdots=x_k=0$, $x_{k+1}=1$, which kills every element of $I_k$ but sends $x_{k+1}$ to $1$). This chain never stabilizes, so $R$ is not Noetherian and a fortiori not a PID. \textit{Check.} Indeed $I_k=\langle x_1,\dots,x_k\rangle$ needs $k$ generators and is not principal for $k\ge 2$, consistent with $R$ failing to be a PID.
\end{wex}

\begin{proposition}[{$\mathbb{Z}[x]$ is not a PID}]
The ideal $I=\langle 2,x\rangle\subseteq\mathbb{Z}[x]$ is not principal. Hence $\mathbb{Z}[x]$ is an integral domain that is \emph{not} a PID. (More generally, if $R$ is not a field then $R[x]$ is not a PID.)
\end{proposition}

\begin{proof}
First identify $I$ concretely: $\langle 2,x\rangle=\{\,f\in\mathbb{Z}[x] : f(0)\ \text{is even}\,\}$. Indeed every element $2g+xh$ has constant term $2g(0)$, which is even; conversely if $f(0)=2c$ then $f=2c+(f-2c)$ where $f-2c$ has zero constant term, hence is $x\cdot(\text{poly})\in\langle x\rangle$, so $f\in\langle 2,x\rangle$. In particular $I\neq\mathbb{Z}[x]$ because $1\notin I$ ($1(0)=1$ is odd).

Suppose for contradiction $I=\langle p\rangle$ for some $p\in\mathbb{Z}[x]$. Since $2\in I=\langle p\rangle$, we have $p\mid 2$ in $\mathbb{Z}[x]$. The divisors of the constant $2$ in $\mathbb{Z}[x]$ are units $\pm 1$ and $\pm 2$ (a degree argument: $2=pq$ forces $\deg p=\deg q=0$, so $p\in\mathbb{Z}$ and $p\mid 2$ in $\mathbb{Z}$).
\begin{itemize}
\item If $p=\pm 1$ then $\langle p\rangle=\mathbb{Z}[x]\neq I$ (we showed $1\notin I$). Contradiction.
\item If $p=\pm 2$ then $\langle p\rangle=\langle 2\rangle$ consists of polynomials with all coefficients even; but $x\in I$ has an odd coefficient, so $x\notin\langle 2\rangle=\langle p\rangle$, contradicting $x\in I$.
\end{itemize}
No choice of $p$ works, so $I$ is not principal and $\mathbb{Z}[x]$ is not a PID.
\end{proof}

\begin{wex}{Why non-principal $\langle 2,x\rangle$ kills PID}
Spell out the logical step: how does $\langle 2,x\rangle$ not being principal prove $\mathbb{Z}[x]$ is not a PID?
\wrec Definition unpacking: a PID requires \emph{every} ideal principal, so one non-principal ideal is a counterexample.
\wsol A PID is defined as an integral domain in which \emph{every} ideal is principal. $\mathbb{Z}[x]$ is an integral domain (it is a subring of $\mathbb{Q}[x]$, itself a domain; equivalently the product of two nonzero polynomials is nonzero by adding leading degrees). The previous proposition exhibits a single ideal, $\langle 2,x\rangle$, that is \emph{not} principal. The universal quantifier ``every ideal is principal'' is therefore false for $\mathbb{Z}[x]$, so $\mathbb{Z}[x]$ fails the definition of PID. \textit{Check.} No contradiction with $\mathbb{Z}[x]$ being a UFD --- being a UFD does \emph{not} require all ideals principal; indeed $\mathbb{Z}[x]$ is a UFD but not a PID, so the inclusion PID $\subset$ UFD is strict, witnessed precisely by $\mathbb{Z}[x]$.
\end{wex}

\begin{wex}{$\langle 2,x\rangle$ has no gcd-style single generator}
Confirm directly that $2$ and $x$ have gcd $1$ in $\mathbb{Z}[x]$ yet $\langle 2,x\rangle\neq\langle 1\rangle$, so the ``$\gcd$ generates'' theorem really needs the PID hypothesis.
\wrec Contrast with the PID gcd theorem: there $\langle a,b\rangle=\langle \gcd(a,b)\rangle$. Failure here pinpoints why $\mathbb{Z}[x]$ is not a PID.
\wsol In $\mathbb{Z}[x]$ the only common divisors of $2$ and $x$ are units $\pm 1$ (a divisor of $x$ is $\pm 1$ or $\pm x$ up to units; $\pm x\nmid 2$), so $\gcd(2,x)=1$. If $\mathbb{Z}[x]$ were a PID we would get $\langle 2,x\rangle=\langle \gcd(2,x)\rangle=\langle 1\rangle=\mathbb{Z}[x]$, i.e. $1=2f+xg$ for some $f,g\in\mathbb{Z}[x]$. Evaluate at $x=0$: $1=2f(0)$, impossible in $\mathbb{Z}$ (left side odd, right side even). \textit{Check.} So $1\notin\langle 2,x\rangle$, $\langle 2,x\rangle\subsetneq\mathbb{Z}[x]$, and the gcd $1$ fails to generate the ideal --- exactly the PID property that breaks. This is the same obstruction as the non-principality computation, viewed through Bezout.
\end{wex}

\begin{wex}{$\F[x,y]$ is not a PID}
Show $R=\mathbb{Q}[x,y]$ is not a PID using the ideal $\langle x,y\rangle$.
\wrec Same non-principal-ideal strategy; $\langle x,y\rangle$ is the ``functions vanishing at the origin'' ideal and needs two generators.
\wsol $\langle x,y\rangle=\{f\in\mathbb{Q}[x,y] : f(0,0)=0\}$, a maximal ideal with $R/\langle x,y\rangle\cong\mathbb{Q}$. Suppose $\langle x,y\rangle=\langle p\rangle$. Then $p\mid x$ and $p\mid y$. Divisors of $x$ in $\mathbb{Q}[x,y]$ are (up to units) $1$ and $x$; the only common divisor of $x$ and $y$ is a unit, so $p\in\mathbb{Q}^\times$, giving $\langle p\rangle=R$. But $\langle x,y\rangle\neq R$ since $1\notin\langle x,y\rangle$ ($1(0,0)=1\neq 0$). Contradiction, so $R$ is not a PID. \textit{Check.} Consistent with $\mathbb{Q}[x,y]=\mathbb{Q}[x][y]$ being $S[y]$ for $S=\mathbb{Q}[x]$ a non-field, so $\langle x,y\rangle$ behaves just like $\langle 2,x\rangle$ did in $\mathbb{Z}[x]$; and $\mathbb{Q}[x,y]$ is still a UFD.
\end{wex}

\begin{pitfall}
\textbf{Two generators does not mean non-principal.} Writing an ideal as $\langle a,b\rangle$ does not by itself prove it is non-principal --- in a PID \emph{every} $\langle a,b\rangle$ collapses to $\langle d\rangle$. E.g. $\langle 6,9\rangle=\langle 3\rangle$ in $\mathbb{Z}$. To prove non-principality you must show \emph{no} single element generates it, as in $\langle 2,x\rangle$. Conversely, do not conclude $\mathbb{Z}[x]$ is ``not a UFD'' from this; it is a UFD. Only the \emph{PID} property fails.
\end{pitfall}

\begin{pitfall}
\textbf{``Prime ideal is maximal'' needs nonzero AND PID.} The theorem is false without both hypotheses. In $\mathbb{Z}$, $\langle 0\rangle$ is prime but not maximal (the nonzero hypothesis matters). In $\mathbb{Z}[x]$ (not a PID), $\langle x\rangle$ is prime ($\mathbb{Z}[x]/\langle x\rangle\cong\mathbb{Z}$ is a domain) but \emph{not} maximal, since $\langle x\rangle\subsetneq\langle 2,x\rangle\subsetneq\mathbb{Z}[x]$. So $\mathbb{Z}[x]/\langle x\rangle\cong\mathbb{Z}$ is a domain that is not a field --- exactly the failure of ``prime $=$ maximal'' in a non-PID.
\end{pitfall}

\begin{theorem}[{A PID that is not Euclidean}]
Let $\omega=\tfrac{1+\sqrt{-19}}{2}$ and $R=\mathbb{Z}[\omega]$, the ring of integers of $\mathbb{Q}(\sqrt{-19})$, with field norm $\Nm(a+b\omega)=a^2+ab+5b^2$. Then $R$ is a principal ideal domain, but $R$ is \emph{not} a Euclidean domain (for any norm whatsoever). Hence the inclusion $\{\text{ED}\}\subsetneq\{\text{PID}\}$ is strict.
\end{theorem}

\begin{remark}[Summary of what the PID axiom buys]
Every ideal principal $\Longrightarrow$ (i) gcds exist and are Bezout combinations $d=ax+by$; (ii) every nonzero prime ideal is maximal, and prime $=$ irreducible; (iii) ACC holds, so factorizations into irreducibles exist. Together (ii) and (iii) give the next section's theorem PID $\Longrightarrow$ UFD. None of these uses a division algorithm directly --- which is why a non-Euclidean ring like $\mathbb{Z}[\tfrac{1+\sqrt{-19}}{2}]$ can still enjoy all of them.
\end{remark}

\begin{exers}{Exercises (from the text).}
\item Prove that in a Principal Ideal Domain two ideals $(a)$ and $(b)$ are comaximal (cf. Section 7.6) if and only if a greatest common divisor of $a$ and $b$ is $1$ (in which case $a$ and $b$ are said to be \emph{coprime} or \emph{relatively prime}).

\item Prove that any two nonzero elements $a,b$ of a P.I.D. have a least common multiple, i.e., an element $e$ with $a\mid e$ and $b\mid e$ such that $e\mid e'$ whenever $a\mid e'$ and $b\mid e'$ (cf. D\&F, Exercise 11 of Section 8.1).

\item Prove that a quotient of a P.I.D. by a prime ideal is again a P.I.D.

\item Let $R$ be an integral domain. Prove that if the following two conditions hold then $R$ is a Principal Ideal Domain:
\begin{itemize}
\item[(i)] any two nonzero elements $a$ and $b$ in $R$ have a greatest common divisor which can be written in the form $ra + sb$ for some $r, s \in R$, and
\item[(ii)] if $a_1, a_2, a_3, \dots$ are nonzero elements of $R$ such that $a_{i+1} \mid a_i$ for all $i$, then there is a positive integer $N$ such that $a_n$ is a unit times $a_N$ for all $n \geq N$.
\end{itemize}

\item Let $R$ be the quadratic integer ring $\mathbb{Z}[\sqrt{-5}]$. Define the ideals $I_2 = (2, 1 + \sqrt{-5})$, $I_3 = (3, 2 + \sqrt{-5})$, and $I_3' = (3, 2 - \sqrt{-5})$.
\begin{itemize}
\item[(a)] Prove that $I_2$, $I_3$, and $I_3'$ are nonprincipal ideals in $R$. [D\&F prove this for $I_3$ in Section 8.1 (Example 2 following Proposition 1) by comparing norms.]
\item[(b)] Prove that the product of two nonprincipal ideals can be principal by showing that $I_2^2$ is the principal ideal generated by $2$, i.e., $I_2^2 = (2)$.
\item[(c)] Prove similarly that $I_2 I_3 = (1 - \sqrt{-5})$ and $I_2 I_3' = (1 + \sqrt{-5})$ are principal. Conclude that the principal ideal $(6)$ is the product of $4$ ideals: $(6) = I_2^2 I_3 I_3'$.
\end{itemize}

\item Let $R$ be an integral domain and suppose that every prime ideal in $R$ is principal. This exercise proves that every ideal of $R$ is principal, i.e., $R$ is a P.I.D.
\begin{itemize}
\item[(a)] Assume that the set of ideals of $R$ that are not principal is nonempty and prove that this set has a maximal element under inclusion (which, by hypothesis, is not prime). [Use Zorn's Lemma.]
\item[(b)] Let $I$ be an ideal which is maximal with respect to being nonprincipal, and let $a, b \in R$ with $ab \in I$ but $a \notin I$ and $b \notin I$. Let $I_a = (I, a)$ be the ideal generated by $I$ and $a$, let $I_b = (I, b)$ be the ideal generated by $I$ and $b$, and define $J = \{r \in R \mid rI_a \subseteq I\}$. Prove that $I_a = (\alpha)$ and $J = (\beta)$ are principal ideals in $R$ with $I \subseteq I_b \subseteq J$ and $I_a J = (\alpha\beta) \subseteq I$.
\item[(c)] If $x \in I$ show that $x = s\alpha$ for some $s \in J$. Deduce that $I = I_a J$ is principal, a contradiction, and conclude that $R$ is a P.I.D.
\end{itemize}

\item An integral domain $R$ in which every ideal generated by two elements is principal (i.e., for every $a, b \in R$, $(a, b) = (d)$ for some $d \in R$) is called a \emph{Bezout Domain}. [cf. also Exercise 11 in Section 3.]
\begin{itemize}
\item[(a)] Prove that the integral domain $R$ is a Bezout Domain if and only if every pair of elements $a, b$ of $R$ has a g.c.d. $d$ that can be written as an $R$-linear combination of $a$ and $b$, i.e., $d = ra + sb$ for some $r, s \in R$.
\item[(b)] Prove that every finitely generated ideal of a Bezout Domain is principal. [cf. the exercises in Sections 9.2 and 9.3 for Bezout Domains in which not every ideal is principal.]
\item[(c)] Let $F$ be the fraction field of the Bezout Domain $R$. Prove that every element of $F$ can be written in the form $a/b$ with $a$ and $b$ relatively prime elements of $R$ (cf. Exercise 1).
\end{itemize}

\item Prove that if $R$ is a Principal Ideal Domain and $D$ is a multiplicatively closed subset of $R$ with $0\notin D$, then $D^{-1}R$ is also a P.I.D. (cf. Section 7.5).
\end{exers}

\begin{exers}{Additional exercises.}
\item Prove that in a PID every nonzero prime ideal is maximal. Then give an integral domain having a nonzero prime ideal that is \emph{not} maximal, exhibiting where the PID hypothesis is needed. (Hint: in $\mathbb{Z}[x]$, the ideal $\langle x\rangle$ is prime since $\mathbb{Z}[x]/\langle x\rangle\cong\mathbb{Z}$ is a domain, but $\langle x\rangle\subsetneq\langle 2,x\rangle\subsetneq\mathbb{Z}[x]$.)

\item Let $R$ be a PID and $p\in R$ irreducible. Prove that the only ideals of $R$ containing $\langle p^2\rangle$ are $\langle 1\rangle=R$, $\langle p\rangle$, and $\langle p^2\rangle$, and deduce that $R/\langle p^2\rangle$ is a local ring whose unique maximal ideal is $\langle p\rangle/\langle p^2\rangle$. (Hint: an ideal containing $\langle p^2\rangle$ is $\langle d\rangle$ with $d\mid p^2$; the divisors of $p^2$ up to units are $1,p,p^2$.)

\item Let $\omega=\tfrac{1+\sqrt{-19}}{2}$ and $R=\mathbb{Z}[\omega]$, with field norm $\Nm(a+b\omega)=a^2+ab+5b^2$. Prove that $R$ has no universal side divisor, hence is \emph{not} a Euclidean domain for any norm; you may use that $\units{R}=\{\pm1\}$ and that $R$ is a PID (via the Dedekind--Hasse criterion). Conclude that $\{\text{ED}\}\subsetneq\{\text{PID}\}$ is strict. (Hint: taking $x=2$ shows that a universal side divisor divides $2$ or $3$; since $a^2+ab+5b^2$ never equals $2$ or $3$, it must be $\pm2$ or $\pm3$. But $|R/\langle 2\rangle|=\Nm(2)=4$ and $|R/\langle 3\rangle|=\Nm(3)=9$ exceed the three residues $\{0,\pm1\}$.)

\item Let $\F$ be a field. Show that the formal power series ring $\F[[x]]$ is a PID whose only nonzero proper ideals are $\langle x^n\rangle$ for $n\ge1$, and identify $\units{\F[[x]]}$. (Hint: a power series is a unit iff its constant term is nonzero; for a nonzero ideal let $n$ be the minimal order of its elements and show the ideal equals $\langle x^n\rangle$.)
\end{exers}

\begin{definition}[Associates]
Two elements $a, b \in R$ are \emph{associates}, written $a \sim b$, if $a = ub$ for some unit $u \in \units{R}$. Equivalently (in a domain), $a \sim b$ iff $a \mid b$ and $b \mid a$, iff $\langle a\rangle = \langle b\rangle$ as principal ideals.
\end{definition}

\begin{proposition}[Characterizations of associates]
In an integral domain, for $a, b \in R$ the following are equivalent: (i) $a = ub$ for a unit $u$; (ii) $a \mid b$ and $b \mid a$; (iii) $\langle a\rangle = \langle b\rangle$.
\end{proposition}

\begin{proof}
We verify the three characterizations agree. If $a = ub$ with $u$ a unit, then $b \mid a$, and $b = u^{-1} a$ gives $a \mid b$; conversely $\langle a\rangle \subseteq \langle b\rangle$ and $\langle b\rangle \subseteq \langle a\rangle$, so $\langle a\rangle = \langle b\rangle$. If instead $a \mid b$ and $b \mid a$, write $b = xa$ and $a = yb$. Then $a = yxa$, so $a(1 - yx) = 0$. If $a = 0$ then $b = 0$ and they are trivially associates; if $a \neq 0$, since $R$ is a domain $1 = yx$, so $y$ is a unit and $a = yb$. Finally $\langle a\rangle = \langle b\rangle \Longrightarrow a \mid b$ and $b \mid a$ directly. So all three are equivalent.
\end{proof}

\begin{remark}
Associate is an equivalence relation. In $\mathbb{Z}$ the units are $\{\pm 1\}$, so $a \sim b \Longleftrightarrow b = \pm a$; the associate classes of nonzero elements are $\{n, -n\}$. In a field every nonzero element is a unit, so all nonzero elements are associates of $1$. In $\mathbb{Z}[i]$ the units are $\{\pm 1, \pm i\}$, so each nonzero $\alpha$ has four associates $\pm\alpha, \pm i\alpha$.
\end{remark}

\begin{definition}[Irreducible, prime]
Let $r \in R$ be nonzero and not a unit.
\begin{enumerate}
\item[(i)] $r$ is \emph{irreducible} if whenever $r = ab$ with $a, b \in R$, then $a$ or $b$ is a unit. (It cannot be written as a product of two nonunits.)
\item[(ii)] $r$ is \emph{prime} if the ideal $\langle r\rangle$ is a nonzero prime ideal; equivalently, $r \neq 0$, $r$ is not a unit, and $r \mid ab \Longrightarrow r \mid a$ or $r \mid b$.
\end{enumerate}
An element with a nontrivial factorization $r = ab$ (both nonunits) is \emph{reducible}.
\end{definition}

\begin{method}{Deciding irreducible vs.\ reducible, and prime}
\textit{Trigger.} You are handed a specific nonzero nonunit $r$ in a concrete domain and asked whether it is irreducible and/or prime.
\begin{enumerate}
\item \textbf{Irreducible test (norm method).} If a multiplicative norm $\Nm \colon R \to \mathbb{Z}_{\geq 0}$ is available with $\Nm(\alpha\beta) = \Nm(\alpha)\Nm(\beta)$ and $\Nm(\alpha) = 1 \Longleftrightarrow \alpha \in \units{R}$, then in any factorization $r = ab$ we get $\Nm(r) = \Nm(a)\Nm(b)$. If $\Nm(r)$ is prime in $\mathbb{Z}$, one factor has norm $1$ and is a unit, so $r$ is irreducible. (The converse can fail.)
\item \textbf{Reducible.} Exhibit one factorization $r = ab$ with $\Nm(a), \Nm(b) > 1$.
\item \textbf{Prime test.} Find $a, b$ with $r \mid ab$ but $r \nmid a$ and $r \nmid b$ to show \emph{not} prime; or prove $R / \langle r\rangle$ is a domain to show prime.
\item \textit{Shortcut.} Prime always implies irreducible (Proposition below). In a UFD the two notions coincide, so the norm test settles both.
\end{enumerate}
\end{method}

\begin{proposition}[Prime $\Longrightarrow$ irreducible]
In an integral domain, every prime element is irreducible.
\end{proposition}

\begin{proof}
Let $p$ be prime and suppose $p = ab$. Then $p \mid ab$, so by primality $p \mid a$ or $p \mid b$; say $p \mid a$, write $a = px$. Then $p = ab = pxb$, so $p(1 - xb) = 0$; since $p \neq 0$ and $R$ is a domain, $xb = 1$, so $b$ is a unit. Thus in any factorization $p = ab$ one factor is a unit, i.e.\ $p$ is irreducible.
\end{proof}

\begin{pitfall}
The converse fails in general: \emph{irreducible does not imply prime} in an arbitrary domain. The standard counterexample is $\mathbb{Z}[\sqrt{-5}]$ (worked below), where $2$ is irreducible but $2 \mid (1+\sqrt{-5})(1-\sqrt{-5})$ while $2$ divides neither factor. The notions coincide in every UFD; conversely, a domain in which every nonzero nonunit is a product of irreducibles and every irreducible is prime is a UFD (see the additional exercises).
\end{pitfall}

\begin{wex}{Prime implies irreducible, by hand in $\mathbb{Z}$}
\wrec In $\mathbb{Z}$, verify directly that the prime $5$ is irreducible using only the definition, to see the general proof concretely.
\wsol Suppose $5 = ab$ with $a, b \in \mathbb{Z}$. Then $5 \mid ab$; since $5$ is prime in the usual sense, $5 \mid a$ or $5 \mid b$, say $5 \mid a$, so $a = 5x$. Then $5 = 5xb \Longrightarrow xb = 1 \Longrightarrow b \in \{\pm 1\} = \units{\mathbb{Z}}$. So one factor is a unit and $5$ is irreducible. \textit{Check.} The only factorizations of $5$ are $5 = 1 \cdot 5 = (-1)(-5)$, each with a unit factor; consistent.
\end{wex}

\begin{wex}{Irreducibility via prime norm in $\mathbb{Z}[i]$}
\wrec Whenever $\Nm(\alpha)$ is a rational prime, the norm test instantly forces $\alpha$ irreducible.
\wsol In $\mathbb{Z}[i]$, $\Nm(a+bi) = a^2 + b^2$ is multiplicative and $\units{\mathbb{Z}[i]} = \{\pm 1, \pm i\}$ (the norm-$1$ elements). Take $\alpha = 2 + i$: $\Nm(2+i) = 4 + 1 = 5$, a prime. If $2 + i = \beta\gamma$ then $5 = \Nm(\beta)\Nm(\gamma)$, so one of $\Nm(\beta), \Nm(\gamma)$ equals $1$, i.e.\ is a unit. Hence $2 + i$ is irreducible. Likewise $2 - i$ ($\Nm = 5$), $1 + i$ ($\Nm = 2$), and $3$ ($\Nm = 9$, but $a^2 + b^2 = 3$ unsolvable, so $3$ stays irreducible in $\mathbb{Z}[i]$) are all irreducible. \textit{Check.} The splitting $5 = (2+i)(2-i)$ has consistent norms, since $\Nm(2+i)\Nm(2-i) = 5 \cdot 5 = 25 = \Nm(5)$, matching $\Nm(5) = 5^2 = 25$. Consistent.
\end{wex}

