\begin{definition}[UFD]
An integral domain $R$ is a unique factorization domain (UFD) if every nonzero nonunit $r \in R$ satisfies:
\begin{enumerate}
\item[(1)] Existence. $r = p_1 p_2 \cdots p_n$ for some irreducibles $p_i$ (not necessarily distinct);
\item[(2)] Uniqueness. if also $r = q_1 q_2 \cdots q_m$ with each $q_j$ irreducible, then $m = n$ and after reordering $p_i \sim q_i$ for all $i$.
\end{enumerate}
\end{definition}

