\textit{Trigger.} Asked to decide whether a given domain has unique factorization.
\begin{enumerate}
\item \textbf{To prove it fails (norm method).} Exhibit one element with two factorizations into irreducibles whose multisets of associate-classes differ. Use a multiplicative norm to (a) prove the factors are irreducible by ruling out intermediate norms, and (b) show the factors across the two factorizations are non-associate (different norms, or not unit multiples). Example: $6$ in $\mathbb{Z}[\sqrt{-5}]$.
\item \textbf{To prove it holds (structure method).} Show $R$ is a PID (or Euclidean), then invoke ``PID $\Longrightarrow$ UFD.'' Or verify both axioms directly: ACC on principal ideals gives existence, and ``irreducible $\Longrightarrow$ prime'' gives uniqueness.
\item \textbf{Inheriting.} If $R$ is a UFD then so is $R[x]$ (stated below), so $\mathbb{Z}[x]$ and $\F[x_1,\dots,x_n]$ are UFDs.
\end{enumerate}
\end{method}

\begin{theorem}[In a UFD, irreducible $\Longleftrightarrow$ prime]
In a unique factorization domain $R$, an element is prime if and only if it is irreducible.
\end{theorem}

\begin{wex}{Using uniqueness to prove irreducible $\Longrightarrow$ prime}
\wrec In a UFD the only way an irreducible can divide a product is to appear (up to associates) in the factorization of one of the factors.
\wsol Work in $\mathbb{Z}$ (a UFD). Let $p = 7$ (irreducible) and suppose $7 \mid ab$ with $a = 2^2 \cdot 7 = 28$, $b = 15 = 3 \cdot 5$. Then $ab = 2^2 \cdot 3 \cdot 5 \cdot 7$. The irreducible $7$ appears in this unique factorization; tracing it back, $7$ came from $a = 28$, so $7 \mid a$. In general the prime $7$ must show up in the merged factorization of $ab$, and uniqueness pins it to a factor of $a$ or of $b$. \textit{Check.} Indeed $7 \mid 28 = a$, and $7 \nmid 15 = b$; the conclusion ``$7 \mid a$'' is exactly what primality predicts.
\end{wex}

\begin{proof}
$d \mid a$ since $\min(e_i, f_i) \leq e_i$, and likewise $d \mid b$. If $c \mid a$ and $c \mid b$, then in the factorization of $c$ each irreducible (an associate of some $p_i$, since $c$ divides $a$) appears to a power $\leq e_i$ and $\leq f_i$, hence $\leq \min(e_i, f_i)$; so $c \mid d$. Thus $d$ is a gcd. Uniqueness up to associates follows because any two gcds divide each other. The lcm statement is dual.
\end{proof}

\begin{wex}{gcd via factorizations in $\mathbb{Z}$}
\wrec Both numbers factor into the same set of primes; take the minimum exponent prime-by-prime.
\wsol $a = 360 = 2^3 \cdot 3^2 \cdot 5$, $b = 84 = 2^2 \cdot 3 \cdot 7$. Common primes $2, 3$ (and $5, 7$ with exponent $0$ in the other). Minima: $2^{\min(3,2)} = 2^2$, $3^{\min(2,1)} = 3^1$, $5^{\min(1,0)} = 5^0$, $7^{\min(0,1)} = 7^0$. So $\gcd = 2^2 \cdot 3 = 12$. \textit{Check.} $12 \mid 360$ ($360/12 = 30$) and $12 \mid 84$ ($84/12 = 7$), and $\gcd(30, 7) = 1$, so $12$ is greatest. Also $\operatorname{lcm} = 2^3 \cdot 3^2 \cdot 5 \cdot 7 = 2520$, and $12 \cdot 2520 = 30240 = 360 \cdot 84$. Consistent.
\end{wex}

\begin{wex}{gcd via factorizations in $\mathbb{Z}[i]$}
\wrec $\mathbb{Z}[i]$ is a UFD, so the same min-exponent recipe works once we factor into Gaussian irreducibles.
\wsol Compute $\gcd(2+i, 5)$ in $\mathbb{Z}[i]$. Factor: $5 = (2+i)(2-i)$ and $2+i$ is irreducible ($\Nm = 5$). Writing both over the irreducibles $\{2+i, 2-i\}$: $\;2+i = (2+i)^1(2-i)^0$, $\;5 = (2+i)^1(2-i)^1$. Minima: $(2+i)^{\min(1,1)}(2-i)^{\min(0,1)} = (2+i)^1$. So $\gcd(2+i, 5) = 2+i$ (up to a unit). \textit{Check.} $2+i \mid 5$ since $5/(2+i) = 5(2-i)/\Nm(2+i) = 5(2-i)/5 = 2-i \in \mathbb{Z}[i]$, and $2+i \mid 2+i$ trivially; nothing of larger norm divides $2+i$, so $2+i$ is the gcd. Consistent.
\end{wex}

\begin{proof}[Proof sketch]
Two ingredients. \emph{Existence:} a PID is Noetherian, so the ascending chain condition holds on (principal) ideals. If some nonzero nonunit had no factorization into irreducibles, one builds a strictly increasing chain $\langle a_1\rangle \subsetneq \langle a_2\rangle \subsetneq \cdots$ by repeatedly splitting a non-factorable factor, contradicting ACC; hence every element factors into irreducibles. \emph{Uniqueness:} in a PID every irreducible $p$ is prime, because $\langle p\rangle$ is maximal (if $\langle p\rangle \subseteq \langle m\rangle \subseteq R$ then $p = mb$, and irreducibility forces $m$ a unit or $b$ a unit, i.e.\ $\langle m\rangle = R$ or $\langle m\rangle = \langle p\rangle$), and maximal ideals are prime. With ``irreducible $\Longrightarrow$ prime'' available, the standard cancellation argument shows any two irreducible factorizations match up to order and associates. The strictness of the inclusions: $\mathbb{Z}[i]$ is Euclidean; $\mathbb{Z}[\tfrac{1+\sqrt{-19}}{2}]$ is a PID that is not Euclidean (next box); $\mathbb{Z}[x]$ is a UFD that is not a PID (e.g.\ $\langle 2, x\rangle$ is not principal); $\mathbb{Z}[\sqrt{-5}]$ is a domain that is not a UFD.
\end{proof}

\begin{remark}[The PID-not-Euclidean example, stated]
The ring $R = \mathbb{Z}\!\left[\tfrac{1+\sqrt{-19}}{2}\right]$ (the ring of integers of $\mathbb{Q}(\sqrt{-19})$) is a principal ideal domain but admits \emph{no} Euclidean function whatsoever. D\&F prove it is not Euclidean by showing it has no ``universal side divisor'' (the field norm rules out small remainders), yet a careful argument with the Dedekind--Hasse criterion shows every ideal is principal. So the inclusion ED $\subsetneq$ PID is strict.
\end{remark}

\begin{definition}[Content, primitive]
Let $R$ be a UFD with fraction field $\Frac(R)$. For a nonzero $f = \sum a_i x^i \in R[x]$, the \emph{content} $\cont(f)$ is a gcd of the coefficients $a_0, \dots, a_n$ (well-defined up to a unit). Call $f$ \emph{primitive} if $\cont(f)$ is a unit, i.e.\ the coefficients have no common irreducible factor.
\end{definition}

\begin{theorem}[Gauss's Lemma, stated]
Let $R$ be a UFD with fraction field $F = \Frac(R)$.
\begin{enumerate}
\item[(i)] The product of two primitive polynomials in $R[x]$ is primitive; more generally $\cont(fg) \sim \cont(f)\cont(g)$.
\item[(ii)] If $f \in R[x]$ factors as $f = AB$ with $A, B \in F[x]$ nonconstant, then $f = ab$ for some $a, b \in R[x]$ with $\deg a = \deg A$, $\deg b = \deg B$. Hence a nonconstant $f \in R[x]$ is irreducible in $R[x]$ iff it is primitive and irreducible in $F[x]$.
\end{enumerate}
\end{theorem}

\begin{proof}[Sketch]
(i) Suppose $f, g$ primitive but $fg$ not, so some irreducible (hence prime, $R$ a UFD) $p$ divides every coefficient of $fg$. Reduce mod $p$: in the domain $(R/\langle p\rangle)[x]$ we get $\bar f \bar g = 0$, forcing $\bar f = 0$ or $\bar g = 0$, i.e.\ $p \mid \cont(f)$ or $p \mid \cont(g)$, contradicting primitivity. The content formula follows by pulling out contents. (ii) Clear denominators and contents from an $F[x]$-factorization and apply (i) to descend the factorization to $R[x]$.
\end{proof}

\begin{theorem}[{$R$ a UFD $\Longrightarrow R[x]$ a UFD, stated}]
If $R$ is a UFD then the polynomial ring $R[x]$ is a UFD. By induction $R[x_1, \dots, x_n]$ is a UFD; in particular $\mathbb{Z}[x_1,\dots,x_n]$ and $\F[x_1,\dots,x_n]$ are UFDs.
\end{theorem}

\begin{proof}[Sketch]
The irreducibles of $R[x]$ are exactly (a) the irreducibles of $R$ (as constant polynomials) and (b) primitive polynomials that are irreducible in $F[x]$, where $F = \Frac(R)$. Existence of factorizations: split off the content (factored in the UFD $R$) and factor the primitive part using that $F[x]$ is a PID, hence a UFD, then descend via Gauss's Lemma. Uniqueness: Gauss's Lemma transfers the unique factorization in $F[x]$ back to $R[x]$, matched with unique factorization of the content in $R$.
\end{proof}

\begin{wex}{$\mathbb{Z}[x]$ is a UFD but not a PID}
\wrec Inheritance gives the UFD property; a single non-principal ideal blocks the PID property, witnessing strictness of PID $\subsetneq$ UFD.
\wsol Since $\mathbb{Z}$ is a UFD, $\mathbb{Z}[x]$ is a UFD by the theorem above. But $\mathbb{Z}[x]$ is not a PID: the ideal $\langle 2, x\rangle$ (all polynomials with even constant term) is not principal. If $\langle 2, x\rangle = \langle d\rangle$, then $d \mid 2$ forces $d \in \{\pm 1, \pm 2\}$, and $d \mid x$ forces $\deg d = 0$ with $d$ dividing the leading coefficient $1$, so $d \in \{\pm 1\}$; but then $\langle d\rangle = \mathbb{Z}[x] \neq \langle 2, x\rangle$ (the constant $1 \notin \langle 2,x\rangle$). Contradiction. \textit{Check.} $\langle 2,x\rangle$ is a maximal ideal with $\mathbb{Z}[x]/\langle 2,x\rangle \cong \F_2$, yet it needs two generators, confirming $\mathbb{Z}[x]$ is a UFD that is not a PID.
\end{wex}

\begin{wex}{Irreducibility in $\mathbb{Z}[x]$ via Gauss's Lemma}
\wrec Gauss's Lemma reduces irreducibility over $\mathbb{Z}$ to: primitive plus irreducible over $\mathbb{Q}$.
\wsol Let $f(x) = x^2 - 2 \in \mathbb{Z}[x]$. Content: $\gcd(1, 0, -2) = 1$, so $f$ is primitive. Over $\mathbb{Q}$, $f$ has no rational root ($\sqrt 2 \notin \mathbb{Q}$, and a degree-$2$ polynomial with no root in a field is irreducible there), so $f$ is irreducible in $\mathbb{Q}[x]$. By Gauss's Lemma (ii), $f$ is irreducible in $\mathbb{Z}[x]$. \textit{Check.} Any factorization $x^2 - 2 = (ax+b)(cx+d)$ over $\mathbb{Z}$ needs $ac = 1$, $bd = -2$, $ad + bc = 0$; $a = c = 1$ forces $b + d = 0$ and $bd = -2$, so $b, -b$ with $-b^2 = -2$, i.e.\ $b^2 = 2$, impossible in $\mathbb{Z}$. Irreducible, as predicted.
\end{wex}

\begin{pitfall}
``Irreducible over $\mathbb{Z}$'' is not the same as ``irreducible over $\mathbb{Q}$'' for \emph{imprimitive} polynomials. The polynomial $2x + 4 = 2(x+2)$ is reducible in $\mathbb{Z}[x]$ (the constant $2$ is a nonunit irreducible factor) but is a unit times an irreducible in $\mathbb{Q}[x]$, where $2$ is a unit. Gauss's Lemma compares the two worlds only after you strip the content, i.e.\ for primitive polynomials.
\end{pitfall}

\begin{remark}[Summary of the logic]
The whole section threads one chain of implications: a multiplicative norm certifies irreducibles; \emph{prime $\Longrightarrow$ irreducible} always; the reverse \emph{irreducible $\Longrightarrow$ prime} is exactly the property that makes factorizations unique, and it holds in every PID (because irreducibles generate maximal ideals there). Thus ED $\Longrightarrow$ PID $\Longrightarrow$ UFD, while $\mathbb{Z}[\sqrt{-5}]$ shows a domain can fail to be a UFD precisely by having an irreducible that is not prime.
\end{remark}

\begin{exers}{Exercises (from the text).}
\item Let $G = \mathbb{Q}^{\times}$ be the multiplicative group of nonzero rational numbers. If $a = p/q \in G$, where $p$ and $q$ are relatively prime integers, let $\varphi : G \to G$ be the map which interchanges the primes $2$ and $3$ in the prime factorizations of $p$ and $q$ (so, for example, $\varphi(2^4 3^{11} 5^1 13^2) = 3^4 2^{11} 5^1 13^2$, $\varphi(3/16) = \varphi(3/2^4) = 2/3^4 = 2/81$, and $\varphi$ is the identity on all rational numbers with numerators and denominators relatively prime to $2$ and to $3$).
\begin{enumerate}
\item[(a)] Prove that $\varphi$ is a group isomorphism.
\item[(b)] Prove that there are infinitely many isomorphisms of the group $G$ to itself.
\end{enumerate}

\item Let $a$ and $b$ be nonzero elements of the Unique Factorization Domain $R$. Prove that $a$ and $b$ have a least common multiple (cf. Exercise 11 of Section 1) and describe it in terms of the prime factorizations of $a$ and $b$ in the same fashion that Proposition 13 describes their greatest common divisor.

\item Determine all the representations of the integer $2130797 = 17^2 \cdot 73 \cdot 101$ as a sum of two squares.

\item Prove that if an integer is the sum of two rational squares, then it is the sum of two integer squares (for example, $13 = (1/5)^2 + (18/5)^2 = 2^2 + 3^2$).

\item Let $R = \mathbb{Z}[\sqrt{-n}]$ where $n$ is a squarefree integer greater than $3$.
\begin{enumerate}
\item[(a)] Prove that $2$, $\sqrt{-n}$ and $1 + \sqrt{-n}$ are irreducibles in $R$.
\item[(b)] Prove that $R$ is not a U.F.D. Conclude that the quadratic integer ring $\mathcal{O}$ is not a U.F.D. for $D \equiv 2, 3 \bmod 4$, $D < -3$ (so also not Euclidean and not a P.I.D.). [Show that either $\sqrt{-n}$ or $1 + \sqrt{-n}$ is not prime.]
\item[(c)] Give an explicit ideal in $R$ that is not principal. [Using $(b)$ consider a maximal ideal containing the nonprime ideal $(\sqrt{-n})$ or $(1 + \sqrt{-n})$.]
\end{enumerate}

\item \begin{enumerate}
\item[(a)] Prove that the quotient ring $\mathbb{Z}[i]/(1 + i)$ is a field of order $2$.
\item[(b)] Let $q \in \mathbb{Z}$ be a prime with $q \equiv 3 \bmod 4$. Prove that the quotient ring $\mathbb{Z}[i]/(q)$ is a field with $q^2$ elements.
\item[(c)] Let $p \in \mathbb{Z}$ be a prime with $p \equiv 1 \bmod 4$ and write $p = \pi \overline{\pi}$ as in Proposition 18. Show that the hypotheses for the Chinese Remainder Theorem (Theorem 17 in Section 7.6) are satisfied and that $\mathbb{Z}[i]/(p) \cong \mathbb{Z}[i]/(\pi) \times \mathbb{Z}[i]/(\overline{\pi})$ as rings. Show that the quotient ring $\mathbb{Z}[i]/(p)$ has order $p^2$ and conclude that $\mathbb{Z}[i]/(\pi)$ and $\mathbb{Z}[i]/(\overline{\pi})$ are both fields of order $p$.
\end{enumerate}

\item Let $\pi$ be an irreducible element in $\mathbb{Z}[i]$.
\begin{enumerate}
\item[(a)] For any integer $n \geq 0$, prove that $(\pi^{n+1}) = \pi^{n+1}\mathbb{Z}[i]$ is an ideal in $(\pi^n) = \pi^n \mathbb{Z}[i]$ and that multiplication by $\pi^n$ induces an isomorphism $\mathbb{Z}[i]/(\pi) \cong (\pi^n)/(\pi^{n+1})$ as additive abelian groups.
\item[(b)] Prove that $|\mathbb{Z}[i]/(\pi^n)| = |\mathbb{Z}[i]/(\pi)|^n$.
\item[(c)] Prove for any nonzero $\alpha$ in $\mathbb{Z}[i]$ that the quotient ring $\mathbb{Z}[i]/(\alpha)$ has order equal to $N(\alpha)$. [Use $(b)$ together with the Chinese Remainder Theorem and the results of the previous exercise.]
\end{enumerate}

\item Let $R$ be the quadratic integer ring $\mathbb{Z}[\sqrt{-5}]$ and define the ideals $I_2 = (2, 1 + \sqrt{-5})$, $I_3 = (3, 2 + \sqrt{-5})$, and $I_3' = (3, 2 - \sqrt{-5})$.
\begin{enumerate}
\item[(a)] Prove that $2$, $3$, $1 + \sqrt{-5}$ and $1 - \sqrt{-5}$ are irreducibles in $R$, no two of which are associate in $R$, and that $6 = 2 \cdot 3 = (1 + \sqrt{-5}) \cdot (1 - \sqrt{-5})$ are two distinct factorizations of $6$ into irreducibles in $R$.
\item[(b)] Prove that $I_2$, $I_3$, and $I_3'$ are prime ideals in $R$. [One approach: for $I_3$, observe that $R/I_3 \cong (R/(3))/(I_3/(3))$ by the Third Isomorphism Theorem for Rings. Show that $R/(3)$ has $9$ elements, $(I_3/(3))$ has $3$ elements, and $R/I_3 \cong \mathbb{Z}/3\mathbb{Z}$ as an additive abelian group. Conclude that $I_3$ is a maximal (hence prime) ideal and that $R/I_3 \cong \mathbb{Z}/3\mathbb{Z}$ as rings.]
\item[(c)] Show that the factorizations in $(a)$ imply the equality of ideals $(6) = (2)(3)$ and $(6) = (1 + \sqrt{-5})(1 - \sqrt{-5})$. Show that these two ideal factorizations give the same factorization of the ideal $(6)$ as the product of prime ideals (cf. Exercise 5 in Section 2).
\end{enumerate}

\item Suppose that the quadratic integer ring $\mathcal{O}$ is a P.I.D. Prove that the absolute value of the field norm $N$ on $\mathcal{O}$ (here $D\neq 0,1$ is a squarefree integer, $\mathcal{O}=\mathbb{Z}[\omega]$, where $\omega=\sqrt{D}$ if $D\equiv 2,3\pmod 4$ and $\omega=\frac{1+\sqrt{D}}{2}$ if $D\equiv 1\pmod 4$, and $N(a+b\sqrt{D})=(a+b\sqrt{D})(a-b\sqrt{D})=a^2-Db^2$ for $a,b\in\mathbb{Q}$, as in D\&F, Section 7.1) is a Dedekind--Hasse norm on $\mathcal{O}$. Conclude that if the quadratic integer ring $\mathcal{O}$ possesses any Dedekind--Hasse norm, then in fact the absolute value of the field norm on $\mathcal{O}$ already provides a Dedekind--Hasse norm on $\mathcal{O}$. [If $\alpha, \beta \in \mathcal{O}$ then $(\alpha, \beta) = (\gamma)$ for some $\gamma \in \mathcal{O}$. Show that if $\beta$ does not divide $\alpha$ then $0 < |N(\gamma)| < |N(\beta)|$ --- use the fact that the units in $\mathcal{O}$ are precisely the elements whose norm is $\pm 1$.]

\item ($k$-stage Euclidean Domains) Let $R$ be an integral domain and let $N : R \to \mathbb{Z}^+ \cup \{0\}$ be a norm on $R$.

\begin{lemma}[Divisibility by rational integers]
Let $d\in\mathbb{Z}$ and $a+bi\in\mathbb{Z}[i]$.
\begin{enumerate}
\item A Gauss integer that is a real number is an ordinary integer.
\item $d$ divides $a+bi$ in $\mathbb{Z}[i]$ if and only if $d$ divides both $a$ and $b$ in $\mathbb{Z}$.
\end{enumerate}
\end{lemma}

\begin{proof}
(1) If $a+bi\in\mathbb{R}$ then $b=0$, so $a+bi=a\in\mathbb{Z}$. (2) If $a+bi=d(s+ti)$ with $s,t\in\mathbb{Z}$, then $a=ds$ and $b=dt$, so $d\mid a$ and $d\mid b$. Conversely if $a=ds$ and $b=dt$ then $a+bi=d(s+ti)$.
\end{proof}

