Section: Polynomial Rings > Definitions and Basic Properties > Integral domains: $R[x]$ a domain, degree additivity, and units
Type: proposition
Title: D\&F 7.2, Prop.\ 4; 9.1, Prop.\ 1
Content:
\begin{proposition}[D\&F 7.2, Prop.\ 4; 9.1, Prop.\ 1]
Let $R$ be an integral domain and let $f,g\in R[x]$ be nonzero. Then:
\begin{enumerate}
 \item[(1)] $\deg(fg)=\deg f+\deg g$;
 \item[(2)] $\units{R[x]}=\units{R}$ (the units of $R[x]$ are exactly the constant units
 of $R$);
 \item[(3)] $R[x]$ is an integral domain.
\end{enumerate}
\end{proposition}

latex:
\begin{proposition}[D\&F 7.2, Prop.\ 4; 9.1, Prop.\ 1]
Let $R$ be an integral domain and let $f,g\in R[x]$ be nonzero. Then:
\begin{enumerate}
  \item[(1)] $\deg(fg)=\deg f+\deg g$;
  \item[(2)] $\units{R[x]}=\units{R}$ (the units of $R[x]$ are exactly the constant units
  of $R$);
  \item[(3)] $R[x]$ is an integral domain.
\end{enumerate}
\end{proposition}

\begin{remark}
By induction (1)--(3) extend to several variables: if $R$ is an integral domain then so is
$R[x_1,\dots,x_n]$, and $\units{R[x_1,\dots,x_n]}=\units{R}$.
\end{remark}

\begin{method}{Degree arguments}
\textit{Trigger.} You must show a product is nonzero, identify the units of $R[x]$, prove an
element is irreducible by degree count, or rule out a factorization.\\[2pt]
\textit{Recipe.}
\begin{enumerate}
  \item \textbf{Confirm the base ring is a domain.} Only then is $\deg(fg)=\deg f+\deg g$
  and $\LC(fg)=\LC(f)\LC(g)$ valid.
  \item \textbf{Take degrees of the hypothesized identity} (e.g.\ $fg=1$, or $fg=h$).
  \item \textbf{Solve the integer equation} in nonnegative degrees; small/forced solutions
  pin down $\deg f,\deg g$.
  \item \textbf{Translate back} to a statement about constants/leading coefficients in $R$.
\end{enumerate}
\end{method}

\begin{proposition}[D\&F 9.1, Prop.\ 2]
Let $I$ be an ideal of the commutative ring $R$, and let
\[
I[x]:=\{\,f\in R[x]\ \st\ \text{every coefficient of }f\text{ lies in }I\,\}.
\]
Then:
\begin{enumerate}
  \item[(1)] $I[x]$ is an ideal of $R[x]$;
  \item[(2)] $R[x]/I[x]\cong (R/I)[x]$;
  \item[(3)] if $I$ is a prime ideal of $R$, then $I[x]$ is a prime ideal of $R[x]$.
\end{enumerate}
\end{proposition}

\begin{method}{Recognizing and using $I[x]$ / reduction quotients}
\textit{Trigger.} You see a quotient $R[x]/J$ where $J$ is ``coefficients in some ideal,''
or you want to reduce a polynomial problem to a simpler ring.\\[2pt]
\textit{Recipe.}
\begin{enumerate}
  \item \textbf{Spot $I[x]$:} $J$ consists of all polynomials whose coefficients lie in an
  ideal $I\subseteq R$ (e.g.\ $J=(p)$ in $\mathbb{Z}[x]$ means ``all coefficients divisible by
  $p$'').
  \item \textbf{Quotient downstairs first:} replace $R$ by $R/I$ coefficientwise; the
  quotient is $(R/I)[x]$.
  \item \textbf{Test primeness:} $I[x]$ is prime $\iff$ $R/I$ is a domain $\iff$ $I$ is
  prime in $R$.
  \item \textbf{To kill a variable too}, quotient additionally by $(x)$ (or $(x-a)$): use
  evaluation $x\mapsto 0$ (or $x\mapsto a$).
\end{enumerate}
\end{method}

\begin{pitfall}
$I[x]$ \emph{prime} does not make $I[x]$ \emph{maximal}. Even when $I$ is maximal in $R$
(so $R/I$ is a field), $(R/I)[x]$ is only a domain, never a field. Thus $(p)$ is prime but
\emph{not} maximal in $\mathbb{Z}[x]$; to reach a field you must also quotient out a variable, e.g.\
$(p,x)$ giving $\F_p$, or $(p,f(x))$ with $f$ irreducible mod $p$ giving a finite field.
\end{pitfall}

\begin{remark}
The proof uses only that $\LC(g)$ is a unit. Over a general commutative ring $R$ the
algorithm still runs when $g$ is \emph{monic} (or has unit leading coefficient). Over a
field every nonzero leading coefficient is a unit, so division is unrestricted.
\end{remark}

\begin{proof}
The Division Algorithm is exactly the Euclidean condition: for $g \neq 0$ we get
$f = qg + r$ with $r=0$ or $N(r) = \deg r < \deg g = N(g)$. Every Euclidean domain is a
PID, and every PID is a UFD (D\&F 8.1, 8.3).
\end{proof}

\begin{method}{Polynomial long division in $F[x]$}
\textit{Trigger.} You must compute $q,r$ with $f = qg+r$, $\deg r < \deg g$; or you want to
test whether $g \mid f$; or you need a remainder mod $g$ inside $F[x]/(g)$.

\textit{Recipe.}
\begin{enumerate}
  \item Arrange $f,g$ in descending degree. Set $r := f$, $q := 0$.
  \item While $r \neq 0$ and $\deg r \ge \deg g$:
        compute the term $t = \dfrac{\LC(r)}{\LC(g)}\,x^{\deg r - \deg g}$,
        then update $q := q + t$ and $r := r - t\,g$ (this kills $\LT(r)$).
  \item Stop when $r=0$ or $\deg r < \deg g$. Output $(q,r)$.
\end{enumerate}
\textit{Check.} Expand $qg+r$ and confirm it equals $f$; confirm $\deg r < \deg g$.
\end{method}

\begin{pitfall}
Division is only as forgiving as the coefficient ring. In $\mathbb{Z}[x]$ you may divide by $g$
with $\mathbb{Z}$-coefficient quotient only when $\LC(g)$ is a unit (e.g. $g$ monic); for instance
$x$ cannot be divided by $3x-1$ with remainder in $\mathbb{Z}[x]$ ($x=q(3x-1)+r$ with $r\in\mathbb{Z}$ forces $q\in\mathbb{Z}$ with $3q=1$), whereas in $\mathbb{Q}[x]$, $x=\tfrac13(3x-1)+\tfrac13$. Over a field $F$ there is never an obstruction:
every nonzero element is a unit.
\end{pitfall}

\begin{proof}
$I = 0$ is $(0)$. If $I \neq 0$ choose $d \in I \setminus \{0\}$ of minimal degree; scaling
by $\LC(d)^{-1}$ (legal since $F$ is a field) we may take $d$ monic. Clearly
$(d) \subseteq I$. Conversely take any $f \in I$ and divide: $f = qd + r$ with $r=0$ or
$\deg r < \deg d$. Then $r = f - qd \in I$. Minimality of $\deg d$ forces $r = 0$, so
$f \in (d)$. Hence $I = (d)$. Uniqueness of the monic generator: if $(d)=(d')$ with both
monic then $d \mid d'$ and $d' \mid d$, so $d' = ud$ with $u \in F^\times$;
comparing leading coefficients gives $u=1$.
\end{proof}

\begin{proof}
By the previous theorem $(f,g) = (d)$ for a unique monic $d$. Since $f,g \in (d)$ we get
$d \mid f$ and $d \mid g$. Since $d \in (f,g)$ we can write $d = sf + tg$; thus any
common divisor of $f,g$ divides $d$. These two properties are exactly the definition of a
greatest common divisor (up to units, pinned down to monic).
\end{proof}

\begin{method}{Euclidean algorithm + back-substitution in $F[x]$}
\textit{Trigger.} You need $\gcd(f,g)$, a B\'ezout pair $(s,t)$, the generator of $(f,g)$,
or an inverse in $F[x]/(g)$.

\textit{Recipe.}
\begin{enumerate}
  \item Set $r_0 = f$, $r_1 = g$ (the larger degree first). Repeatedly divide:
        $r_{i-1} = q_i r_i + r_{i+1}$ with $\deg r_{i+1} < \deg r_i$.
  \item Stop at the last nonzero remainder $r_k$. Then $\gcd = $ monic scaling of $r_k$:
        $d = \LC(r_k)^{-1} r_k$.
  \item For B\'ezout, keep coefficient pairs $(s_i,t_i)$ with $r_i = s_i f + t_i g$ via
        $s_{i+1} = s_{i-1} - q_i s_i$, $t_{i+1} = t_{i-1} - q_i t_i$, starting from
        $(s_0,t_0)=(1,0)$, $(s_1,t_1)=(0,1)$. Scale the final pair by $\LC(r_k)^{-1}$.
\end{enumerate}
\textit{Check.} Verify $d \mid f$ and $d \mid g$ by division, and recompute
$sf+tg = d$.
\end{method}

\begin{proof}
Divide $f$ by the monic polynomial $x-a$ (legal over any commutative ring since $x-a$ is
monic): $f = (x-a)q + r$ with $r$ a constant (degree $<1$). Evaluate at $x=a$:
$f(a) = 0\cdot q(a) + r = r$. So $r = f(a)$, giving $f = (x-a)q + f(a)$. Then $(x-a)
\mid f$ iff $r = f(a) = 0$.
\end{proof}

\begin{pitfall}
The integral-domain hypothesis matters (the proof uses nothing more, so the bound holds over any integral domain, e.g.\ $\mathbb{Z}$). Over $\mathbb{Z}/(8)\mathbb{Z}$ the polynomial
$x^2 - 1$ of degree $2$ has \emph{four} roots: $x \in \{1,3,5,7\}$, because $\mathbb{Z}/(8)\mathbb{Z}$ has
zero divisors. The step ``$(b-a)q(b)=0 \Longrightarrow q(b)=0$'' fails when $b-a$ is a zero divisor.
Over a field this never happens.
\end{pitfall}

\begin{method}{Root--factor recipe}
\textit{Trigger.} You want to factor out known roots, count roots, or test irreducibility
of a low-degree polynomial.
\begin{enumerate}
  \item To remove a root $a$: confirm $f(a)=0$, then synthetic-divide by $(x-a)$ to get
        $q$ with $\deg q = \deg f - 1$; repeat on $q$.
  \item A degree-$2$ or $3$ polynomial over $F$ is irreducible iff it has \emph{no} root
        in $F$ (a nontrivial factorization must include a linear factor).
  \item Rational Root Test in $\mathbb{Q}[x]$: any root $p/q$ (lowest terms) of an integer
        polynomial has $p \mid a_0$, $q \mid a_n$.
\end{enumerate}
\textit{Check.} Multiply factors back; verify each claimed root by direct evaluation.
\end{method}

\begin{pitfall}
$F[x]/(f)$ is a field \emph{only} when $f$ is irreducible. For $f = x^2 - 1 = (x-1)(x+1)$
over $\mathbb{Q}$, the quotient $\mathbb{Q}[x]/(x^2-1)$ has zero divisors $(\bar x - 1)(\bar x + 1) = 0$
with both factors nonzero; by CRT it is $\mathbb{Q} \times \mathbb{Q}$, a ring but not a field. Always
check irreducibility before claiming a field.
\end{pitfall}

Prove that every left ideal of $R$ is principal (so $R$ is a ``left Principal Ideal Domain'').
\\(d) Let $f = cx$ for some $c \in F$ that is not a $p^{\text{th}}$ power in $F$, and let $g = x$. Prove that there are no $q, r \in R$ with $f = gq + r$ and $r = 0$ or $\deg(r) < \deg(g)$, so $R$ is not ``left Euclidean'' with respect to $N$. Prove that the right ideal of $R$ generated by $x$ and $cx$ is not principal. Conclude that $R$ is not ``left Euclidean'' with respect to any norm.
\end{exers}

\begin{method}{Computing $\cont(f)$ and the primitive part}
\textit{Trigger.} You are handed $f\in R[x]$ and want to strip off the ``$R$-part,'' or you
need a primitive polynomial to feed into Gauss's Lemma.
\begin{enumerate}
\item List all coefficients $a_0,\dots,a_n$ (include the constant term, even if $0$ is
present in the middle).
\item Compute $c=\gcd(a_0,\dots,a_n)$ in $R$ (in $\mathbb{Z}$: factor each $|a_i|$, take the min
power of each prime; or run the Euclidean algorithm pairwise).
\item Divide: $f_1=f/c$. Then $f=c\,f_1$ with $f_1$ \emph{primitive}.
\item \textit{Check.} Verify $\gcd$ of the coefficients of $f_1$ is $1$ (every prime fails
to divide \emph{some} coefficient, i.e.\ no prime divides all of them).
\end{enumerate}
\end{method}

\begin{remark}
The heart of the proof is: \emph{$\pi$ prime $\Rightarrow$ $(R/(\pi))[x]$ a domain}. This
is exactly where ``$R$ a UFD'' is used. Part (c) is the practically useful form: it says a
factorization over the field $F$ can always be ``cleared'' to a factorization over $R$
with the same degree pattern.
\end{remark}

\begin{method}{Reduce $\mathbb{Z}[x]$-factoring to $\mathbb{Q}[x]$-factoring (Gauss)}
\textit{Trigger.} You must decide whether a primitive $f\in\mathbb{Z}[x]$ is irreducible, or factor
it over $\mathbb{Z}$, and factoring over a field is easier.
\begin{enumerate}
\item Make $f$ primitive (divide out $\cont(f)$); the constant content factors separately.
\item Try to factor the primitive $f$ over $\mathbb{Q}$ (rational root test for linear factors;
quadratic formula; known irreducibility criteria).
\item If $f$ is irreducible over $\mathbb{Q}$, then (being primitive) it is irreducible in $\mathbb{Z}[x]$
(a nonunit constant cannot divide the primitive $f$, so a factorization into nonunits of $\mathbb{Z}[x]$ has two nonconstant factors and is already one over $\mathbb{Q}$). If $f=AB$ over $\mathbb{Q}$, use Gauss (c): clear denominators and rescale to get $f=A'B'$ over
$\mathbb{Z}$ with $\deg A'=\deg A$, $\deg B'=\deg B$.
\item \textit{Check.} Multiply the $\mathbb{Z}$-factors back out and confirm you recover $f$.
\end{enumerate}
\end{method}

\begin{corollary}[{Irreducibles of $R[x]$}]
Let $R$ be a UFD with fraction field $F$. The irreducible elements of $R[x]$ are exactly:
\begin{enumerate}
\item the irreducible elements of $R$ (the \emph{constant} irreducibles), and
\item the \emph{primitive} polynomials $p(x)\in R[x]$ of degree $\ge1$ that are
irreducible in $F[x]$.
\end{enumerate}
A nonconstant $f\in R[x]$ is irreducible iff $f$ is primitive and irreducible over $F$.
\end{corollary}

\begin{method}{Classify an irreducible of $R[x]$}
\textit{Trigger.} ``Is $f\in R[x]$ irreducible?''
\begin{enumerate}
\item If $\deg f=0$: $f$ is irreducible iff it is an irreducible of $R$ (e.g.\ a prime in
$\mathbb{Z}$).
\item If $\deg f\ge1$: first check $f$ is \emph{primitive} (else $\cont(f)$ splits off a
nonunit factor $\Rightarrow$ reducible).
\item Then check irreducibility over $F$ (rational roots, Eisenstein, mod-$p$ reduction,
degree arguments).
\item \textit{Check.} Primitive $+$ irreducible over $F$ is equivalent to irreducible in
$R[x]$.
\end{enumerate}
\end{method}

