\begin{exers}{Exercises (from the text).}
\item Let $R$ be an integral domain with quotient field $F$ and let $p(x)$ be a monic polynomial in $R[x]$. Assume that $p(x) = a(x)b(x)$ where $a(x)$ and $b(x)$ are monic polynomials in $F[x]$ of smaller degree than $p(x)$. Prove that if $a(x) \notin R[x]$ then $R$ is not a Unique Factorization Domain. Deduce that $\mathbb{Z}[2\sqrt{2}]$ is not a U.F.D.

\item Prove that if $f(x)$ and $g(x)$ are polynomials with rational coefficients whose product $f(x)g(x)$ has integer coefficients, then the product of any coefficient of $g(x)$ with any coefficient of $f(x)$ is an integer.

\item Let $F$ be a field. Prove that the set $R$ of polynomials in $F[x]$ whose coefficient of $x$ is equal to $0$ is a subring of $F[x]$ and that $R$ is not a U.F.D. [Show that $x^6 = (x^2)^3 = (x^3)^2$ gives two distinct factorizations of $x^6$ into irreducibles.]

\item Let $R = \mathbb{Z} + x\mathbb{Q}[x] \subset \mathbb{Q}[x]$ be the set of polynomials in $x$ with rational coefficients whose constant term is an integer.
\begin{itemize}
\item[(a)] Prove that $R$ is an integral domain and its units are $\pm 1$.
\item[(b)] Show that the irreducibles in $R$ are $\pm p$ where $p$ is a prime in $\mathbb{Z}$ and the polynomials $f(x)$ that are irreducible in $\mathbb{Q}[x]$ and have constant term $\pm 1$. Prove that these irreducibles are prime in $R$.
\item[(c)] Show that $x$ cannot be written as the product of irreducibles in $R$ (in particular, $x$ is not irreducible) and conclude that $R$ is not a U.F.D.
\item[(d)] Show that $x$ is not a prime in $R$ and describe the quotient ring $R/(x)$.
\end{itemize}

\item Let $R = \mathbb{Z} + x\mathbb{Q}[x] \subset \mathbb{Q}[x]$ be the ring considered in the previous exercise.
\begin{itemize}
\item[(a)] Suppose that $f(x), g(x) \in \mathbb{Q}[x]$ are two nonzero polynomials with rational coefficients and that $x^r$ is the largest power of $x$ dividing both $f(x)$ and $g(x)$ in $\mathbb{Q}[x]$, i.e., $r$ is the degree of the lowest order term appearing in either $f(x)$ or $g(x)$. Let $f_r$ and $g_r$ be the coefficients of $x^r$ in $f(x)$ and $g(x)$, respectively (one of which is nonzero by definition of $r$). Then $\mathbb{Z} f_r + \mathbb{Z} g_r = \mathbb{Z} d_r$ for some nonzero $d_r \in \mathbb{Q}$ (cf. Exercise 14 in Section 2.4). Prove that there is a polynomial $d(x) \in \mathbb{Q}[x]$ that is a g.c.d. of $f(x)$ and $g(x)$ in $\mathbb{Q}[x]$ and whose term of minimal degree is $d_r x^r$.
\item[(b)] Prove that $f(x) = d(x)q_1(x)$ and $g(x) = d(x)q_2(x)$ where $q_1(x)$ and $q_2(x)$ are elements of the subring $R$ of $\mathbb{Q}[x]$.
\item[(c)] Prove that $d(x) = a(x)f(x) + b(x)g(x)$ for polynomials $a(x), b(x)$ in $R$. [The existence of $a(x), b(x)$ in the Euclidean Domain $\mathbb{Q}[x]$ is immediate. Use Exercise 11 in Section 2 to show that $a(x)$ and $b(x)$ can be chosen to lie in $R$.]
\item[(d)] Conclude from (b) and (c) that $Rf(x) + Rg(x) = Rd(x)$ in $\mathbb{Q}[x]$ and use this to prove that $R$ is a Bezout Domain (cf. Exercise 7 in Section 8.2).
\item[(e)] Show that (d), the results of the previous exercise, and Exercise 11 of Section 8.3 imply that $R$ must contain ideals that are not principal (hence not finitely generated). Prove that in fact $I = x\mathbb{Q}[x]$ is an ideal of $R$ that is not finitely generated.
\end{itemize}
\end{exers}

\begin{method}{Hunting rational roots (and using them)}
\textit{Trigger.} You want a root, or you want to test irreducibility of a degree-$2$ or
degree-$3$ polynomial in $\mathbb{Q}[x]$ (Proposition below).
\begin{enumerate}
\item Clear denominators so $f\in\mathbb{Z}[x]$; record $a_0$ (constant) and $a_n$ (leading).
\item List candidate roots $\pm p/q$ with $p\mid a_0$, $q\mid a_n$, in lowest terms.
\item Evaluate $f$ at each candidate (Horner's scheme is fastest); a candidate $\alpha$ is a
root iff $f(\alpha)=0$, equivalently $(x-\alpha)\mid f$.
\item If $f$ is monic, only integer divisors of $a_0$ need testing.
\end{enumerate}
\textbf{Caveat:} once $\deg f\ge 4$, the \emph{absence} of a rational root proves nothing
about irreducibility (a quartic can split into two irreducible quadratics with no roots).
\end{method}

\begin{wex}{No rational root despite small coefficients}
Does $f(x)=x^4+x+1$ have a rational root?
\wrec Monic; candidates are integer divisors of $a_0=1$, i.e.\ $\pm1$.
\wsol $f(1)=1+1+1=3\neq0$ and $f(-1)=1-1+1=1\neq0$. No rational root.
\textit{Check / warning.} This does \emph{not} prove $x^4+x+1$ irreducible over $\mathbb{Q}$; a
quartic can be a product of two quadratics with no roots. (In fact $x^4+x+1$ \emph{is}
irreducible over $\mathbb{Q}$ --- proven by reduction mod $2$ below --- but the
rational-root test alone is silent here.)
\end{wex}

\begin{pitfall}
A successful grouping/factoring \emph{must} be confirmed by expansion. If $f$ has no rational
root but you ``find'' a linear factor, you made an arithmetic slip. Conversely, for
$\deg f\ge 4$, absence of rational roots is \emph{not} irreducibility.
\end{pitfall}

\begin{remark}
The hypothesis $\deg f\le 3$ is essential: a degree-$2$ or degree-$3$ reducible polynomial
\emph{must} shed a linear factor, but a degree-$4$ polynomial can factor as (irreducible
quadratic)$\times$(irreducible quadratic) with no root at all (e.g.\ $x^4+1=(x^2+x+2)(x^2+2x+2)$ over $\F_3$,
which has no root in $\F_3$ --- see below).
\end{remark}

\begin{method}{Degree 2 or 3 irreducibility over $F$}
\textit{Trigger.} $\deg f\in\{2,3\}$ over a field $F$ (e.g.\ $\mathbb{Q}$, $\F_p$).
\begin{enumerate}
\item Search for a root in $F$. Over $\mathbb{Q}$ use the Rational Root Theorem; over $\F_p$ just
test all $p$ elements.
\item If a root exists, $f$ is reducible; otherwise $f$ is irreducible.
\end{enumerate}
This is the only test where ``no root'' immediately gives irreducibility.
\end{method}

\begin{wex}{A quadratic that stays irreducible over $\F_7$}
Is $x^2+1\in\F_7[x]$ irreducible?
\wrec Degree $2$ over $\F_7$: reducible iff $-1$ is a square mod $7$.
\wsol Squares mod $7$: $1,4,2,2,4,1$ for $x=1,\dots,6$, i.e.\ $\{1,2,4\}$. We need $x^2=-1=6$;
$6\notin\{1,2,4\}$, so \emph{no} root and $x^2+1$ is irreducible over $\F_7$.
\textit{Check.} Since $7\equiv 3\pmod 4$, $-1$ is a nonsquare mod $7$, matching. (Contrast
$\F_5$: $2^2=4\equiv-1$, so $x^2+1=(x-2)(x+2)$ splits there.)
\end{wex}

\begin{pitfall}
Reduction mod a \emph{single} prime can give a factorization that does not lift: $x^4+1$ is
irreducible over $\mathbb{Q}$ yet factors mod every prime. Reduction proves irreducibility only when
$\bar f$ is irreducible; a factorization of $\bar f$ does not show that $f$ factors (it only limits the degrees of possible factors of $f$).
\end{pitfall}

\begin{proof}
Suppose, for contradiction, $f=gh$ in $\mathbb{Z}[x]$ with $\deg g,\deg h\ge 1$. Since $f$ is monic
we may take $g,h$ monic (the leading coefficients of $g,h$ multiply to $1$, so are $\pm1$;
absorb signs). Apply the ring homomorphism $\bmod p:\mathbb{Z}[x]\to\F_p[x]$, which is
multiplicative: $\bar f=\bar g\,\bar h$. Because $g,h$ are monic, $\deg\bar g=\deg g$ and
$\deg\bar h=\deg h$, so both factors are nonconstant. This contradicts the irreducibility of
$\bar f$ in $\F_p[x]$. Hence $f$ is irreducible in $\mathbb{Z}[x]$; as a monic (so primitive)
polynomial it is then irreducible in $\mathbb{Q}[x]$ by Gauss's Lemma.
\end{proof}

\begin{method}{Reduction mod $p$}
\textit{Trigger.} $f\in\mathbb{Z}[x]$ (or $\mathbb{Q}[x]$, cleared to $\mathbb{Z}[x]$), no obvious roots, degree
$\ge 2$, and Eisenstein does not apply.
\begin{enumerate}
\item Make $f$ monic if possible; otherwise choose a prime $p$ with $p\nmid a_n$.
\item Reduce: form $\bar f\in\F_p[x]$. Try small primes $p=2,3,5$.
\item Test $\bar f$ for irreducibility over $\F_p$ (root test if $\deg\le3$; otherwise
trial-divide by all irreducibles of degree $\le\lfloor\deg f/2\rfloor$).
\item If $\bar f$ is irreducible of full degree for \emph{some} prime, conclude $f$ is
irreducible over $\mathbb{Q}$. If $\bar f$ factors, the test is inconclusive --- try another $p$.
\end{enumerate}
\end{method}

\begin{method}{Eisenstein's criterion}
\textit{Trigger.} Integer coefficients with a prime $p$ dividing every coefficient except the
leading one, $p^2$ \emph{not} dividing the constant term. Watch for ``shift'' variants.
\begin{enumerate}
\item Identify a candidate prime $p$ (often a prime dividing $a_0$).
\item Verify the three conditions: $p\mid a_i$ ($i<n$), $p\nmid a_n$,
$p^2\nmid a_0$.
\item If they hold, $f$ is irreducible over $\mathbb{Q}$. If not, try a substitution $x\mapsto x+c$
(irreducibility is preserved by $x\mapsto x+c$, an automorphism of $\mathbb{Q}[x]$) and re-test.
\end{enumerate}
\end{method}

