\begin{proposition}[{$F[x]/(p)$ as an extension of $F$ of degree $\deg p$}]
Let $p(x) \in F[x]$ be irreducible of degree $n = \deg p \geq 1$, and write $K = F[x]/(p)$. Let $\bar x = x + (p)$ denote the image of $x$. Then:
\begin{enumerate}
\item[(a)] $K$ is a field, and the map $F \to K$, $c \mapsto c + (p)$, is an injective ring homomorphism; identifying $F$ with its image, $F \subseteq K$.
\item[(b)] $\bar x$ is a root of $p$ in $K$, i.e.\ $p(\bar x) = 0$ in $K$.
\item[(c)] As an $F$-vector space, $K$ has basis $\{1, \bar x, \bar x^2, \dots, \bar x^{\,n-1}\}$; in particular $\dim_F K = n$, so every element of $K$ is uniquely $c_0 + c_1 \bar x + \dots + c_{n-1}\bar x^{\,n-1}$ with $c_i \in F$.
\end{enumerate}
\end{proposition}

\begin{proof}
(a) $K$ is a field by the Maximal Ideals theorem. A ring homomorphism from a field $F$ is either zero or injective; since $1 \mapsto 1 \neq 0$ in $K$, it is injective.

(b) Writing $p(x) = \sum a_i x^i$, in $K$ we have $p(\bar x) = \sum a_i \bar x^{\,i} = \overline{p(x)} = p(x) + (p) = 0$.

(c) By the Division Algorithm in $F[x]$, every $a(x)$ equals $q(x)p(x) + r(x)$ with $r = 0$ or $\deg r < n$. Thus every coset $a + (p)$ has a unique representative $r$ of degree $< n$ (uniqueness: if $r_1 - r_2 \in (p)$ has degree $< n$ then it is $0$). The representatives of degree $< n$ are exactly the $F$-linear combinations $c_0 + c_1 x + \dots + c_{n-1}x^{n-1}$, so $\{1, \bar x, \dots, \bar x^{\,n-1}\}$ spans $K$ over $F$ and is linearly independent, hence a basis. Therefore $\dim_F K = n$.
\end{proof}

\begin{method}{Building a field extension as $F[x]/(p)$}
\textbf{Goal:} produce a field $K \supseteq F$ in which a given irreducible $p$ acquires a root, or recognize a known field as such a quotient.
\begin{enumerate}
\item \textbf{Check $p$ is irreducible over $F$.} For $\deg p \in \{2,3\}$ it suffices that $p$ has \emph{no root in $F$} (rational root test, or check all elements when $F$ is finite). For higher degree use D\&F 9.4 tools (Gauss, Eisenstein, reduction mod $p$).
\item \textbf{Form $K = F[x]/(p)$.} By the theorem $K$ is a field, $[K:F] = \deg p$, with $F$-basis $1, \bar x, \dots, \bar x^{\,n-1}$.
\item \textbf{Set the multiplication rule.} The single relation $p(\bar x) = 0$ lets you rewrite $\bar x^{\,n}$ (and higher powers) in terms of lower ones. Multiply representatives in $F[x]$, then \emph{reduce mod $p$} (Division Algorithm) to land back in degree $< n$.
\item \textbf{Find inverses} via the Extended Euclidean Algorithm: for $a(x)$ with $\gcd(a,p)=1$ solve $a u + p v = 1$; then $a^{-1} = \bar u$ in $K$.
\item \textbf{Identify $K$ with a familiar field} by sending $\bar x$ to an actual root (e.g.\ $\sqrt2$, $i$) and checking the relation holds; the resulting map is an isomorphism by the First Isomorphism Theorem.
\end{enumerate}
\end{method}

\begin{theorem}[{Cyclicity of finite subgroups of $F^\times$}]
Let $F$ be a field and let $G$ be a finite subgroup of the multiplicative group $\units{F} = F \setminus \{0\}$. Then $G$ is cyclic. In particular, for a finite field $\F_q$ (with $q$ elements), the group $\units{\F_q} = \F_q^{\times}$ is cyclic of order $q - 1$.
\end{theorem}

\begin{proof}
Let $|G| = n$ and let $m$ be the exponent of $G$ (the least common multiple of the orders of all elements; equivalently the largest order of an element, since $G$ is abelian). Every $g \in G$ satisfies $g^m = 1$, so every element of $G$ is a root of the polynomial $x^m - 1 \in F[x]$. Over a field, $x^m - 1$ has at most $m$ roots (D\&F 9.5: a nonzero polynomial of degree $d$ over a field has at most $d$ roots, because each root $a$ contributes a factor $(x-a)$ and these are coprime). Hence $n = |G| \leq m$.

On the other hand, in a finite abelian group the exponent divides the order: $m \mid n$, so $m \leq n$. Therefore $m = n$. Since the exponent of a finite abelian group equals the maximal element order, there is an element $g \in G$ of order $m = n = |G|$, so $G = \langle g\rangle$ is cyclic.
\end{proof}

\begin{remark}
The two inputs are essential and field-specific. (1) ``At most $\deg$ roots'' \emph{fails} over a non-domain: in $\mathbb{Z}/8\mathbb{Z}$ the polynomial $x^2 - 1$ has the four roots $1,3,5,7$. (2) The result genuinely uses that $F$ is a field; $\units{(\mathbb{Z}/8\mathbb{Z})} \cong (\mathbb{Z}/2)^2$ is \emph{not} cyclic --- but $\mathbb{Z}/8\mathbb{Z}$ is not a field. A generator of $\units{\F_q}$ is called a \emph{primitive root} (mod $p$ when $q = p$).
\end{remark}

\begin{method}{Finding a generator of $\units{\F_q}$ (a primitive root)}
\textit{Trigger.} You need a cyclic generator $g$ of $\units{\F_q}$, i.e.\ an element of order $q-1$.
\begin{enumerate}
\item Factor $q - 1 = \prod_i \ell_i^{e_i}$.
\item Pick a candidate $g \in \units{\F_q}$ (start with small ones: $2, 3, \dots$).
\item For each prime $\ell_i$ dividing $q-1$, compute $g^{(q-1)/\ell_i}$. If \emph{all} of these are $\neq 1$, then $\operatorname{ord}(g) = q-1$ and $g$ is a generator. If some equals $1$, discard $g$ and try the next candidate.
\item (Why it works: $\operatorname{ord}(g) \mid q-1$; it is a proper divisor iff $\operatorname{ord}(g) \mid (q-1)/\ell_i$ for some $i$, equivalently $g^{(q-1)/\ell_i} = 1$.)
\end{enumerate}
\end{method}

\begin{wex}{Primitive root mod $11$}
Find a generator of $\units{\F_{11}}$ (order $10$).
\wrec $\F_{11}$ is a field, $\units{\F_{11}}$ cyclic of order $10 = 2\cdot 5$. Test exponents $10/2 = 5$ and $10/5 = 2$: $g$ generates iff $g^5 \neq 1$ and $g^2 \neq 1$.
\wsol Try $g = 2$: $2^2 = 4 \neq 1$. $2^5 = 32 = 10 \neq 1 \pmod{11}$. Both nontrivial, so $\operatorname{ord}(2) = 10$: $2$ is a generator.

\textit{Check.} Powers of $2$ mod $11$: $2,4,8,5,10,9,7,3,6,1$ --- all ten nonzero residues, exactly once each. So $\units{\F_{11}} = \langle 2\rangle$. (By contrast $\operatorname{ord}(10) = 2$ since $10 \equiv -1$, and $10^5 = (-1)^5 = -1 = 10 \neq 1$ but $10^2 = 1$, so $10$ fails the $g^2 \neq 1$ test --- not a generator, as expected.)
\end{wex}

\begin{pitfall}
\textbf{``No root $\Rightarrow$ irreducible'' is valid ONLY in degree $2$ and $3$.} For degree $\geq 4$ a polynomial can lack roots yet factor. Over $\mathbb{Q}$, $x^4 + 4 = (x^2 - 2x + 2)(x^2 + 2x + 2)$ has no rational (indeed no real) root but is reducible, so $\mathbb{Q}[x]/(x^4+4)$ is \emph{not} a field. Always factor into lower-degree pieces for $\deg \geq 4$.
\end{pitfall}

\begin{pitfall}
\textbf{$(p)$ prime does not imply $(p)$ maximal in a general $R[x]$.} The clean equivalence ``prime $\Longleftrightarrow$ maximal $\Longleftrightarrow$ irreducible'' for nonzero ideals holds in $F[x]$ \emph{because $F$ is a field} (making $F[x]$ a PID). In $\mathbb{Z}[x]$, $(x)$ is prime ($\mathbb{Z}[x]/(x) \cong \mathbb{Z}$, a domain) but not maximal ($\mathbb{Z}$ is not a field); $(2,x)$ is a maximal ideal above it (as is $(p,x)$ for every prime $p$). Do not transport the $F[x]$ equivalence to $\mathbb{Z}[x]$ or $F[x,y]$.
\end{pitfall}

\begin{pitfall}
\textbf{Finite multiplicative groups need not be cyclic outside a field.} The proof needs ``a degree-$d$ polynomial has at most $d$ roots,'' which requires an integral domain. $\units{(\mathbb{Z}/8\mathbb{Z})} \cong (\mathbb{Z}/2)\times(\mathbb{Z}/2)$ is not cyclic; $\mathbb{Z}/8\mathbb{Z}$ is not a field. Likewise $\units{(\mathbb{Z}/n\mathbb{Z})}$ is cyclic only for $n = 1, 2, 4, p^k, 2p^k$ ($p$ an odd prime): e.g.\ $\units{(\mathbb{Z}/15\mathbb{Z})} \cong \mathbb{Z}/2\times\mathbb{Z}/4$ is not cyclic, while $\units{(\mathbb{Z}/9\mathbb{Z})}$ is cyclic of order $6$ although $\mathbb{Z}/9\mathbb{Z}$ is not a field.
\end{pitfall}

\begin{theorem}[{Hilbert's Basis Theorem}]
If $R$ is a commutative Noetherian ring, then the polynomial ring $R[x]$ is Noetherian. Consequently, for any field $F$ (or any Noetherian ring $F$), $F[x_1,\dots,x_n]$ is Noetherian: every ideal $I\subseteq F[x_1,\dots,x_n]$ is finitely generated.
\end{theorem}

\begin{remark}
Hilbert's Basis Theorem guarantees that the ideals we study are finitely generated, but it gives no \emph{algorithm} and no \emph{useful} generating set. Grobner bases supply a particular, computable generating set from which membership, equality of ideals, and elimination can all be decided.
\end{remark}

