\begin{definition}
Fix a monomial ordering $>$. For nonzero $f=\sum_\alpha c_\alpha x^\alpha \in F[x_1,\dots,x_n]$:
\begin{itemize}
\item the multidegree $\multideg(f) = \max_{>}\{\alpha : c_\alpha\ne 0\}$;
\item the leading coefficient $\LC(f) = c_{\multideg(f)}\in F\setminus\{0\}$;
\item the leading monomial $\LM(f) = x^{\multideg(f)}$;
\item the leading term $\LT(f) = \LC(f)\,\LM(f)$.
\end{itemize}
\end{definition}

