\begin{definition}[Left $R$-module]
Let $R$ be a ring with $1$. A \emph{left $R$-module} (or \emph{left module over $R$}) is an abelian group $(M,+)$ together with an action
\[
R\times M\longrightarrow M,\qquad (r,m)\longmapsto rm,
\]
called \emph{(left) scalar multiplication}, such that for all $r,s\in R$ and all $m,n\in M$:
\begin{enumerate}
\item[(M1)] $(r+s)m = rm + sm$ \hfill (distributivity over ring addition);
\item[(M2)] $(rs)m = r(sm)$ \hfill (associativity of the action);
\item[(M3)] $r(m+n) = rm + rn$ \hfill (distributivity over module addition);
\item[(M4)] $1m = m$ \hfill (the identity acts as identity).
\end{enumerate}
A module satisfying (M4) is called \emph{unital}; we assume (M4) always. A \emph{right $R$-module} is defined symmetrically with the action written $m\mapsto mr$ and (M2) reading $m(rs)=(mr)s$.
\end{definition}

\begin{remark}[Why ``left,'' and the role of commutativity]
When $R$ is commutative, (M2) reads $(rs)m=r(sm)$ and we may also write $mr:=rm$; then there is no distinction between left and right modules and we simply say ``$R$-module.'' When $R$ is noncommutative the left/right distinction is real: with $mr:=rm$, the right-module axiom $m(rs)=(mr)s$ would force $(rs)m=r(sm)=s(rm)$ in general, which fails. We work with \emph{left} modules by default.
\end{remark}

\begin{method}{Checking ``$M$ is a left $R$-module''}
Recognition trigger: you are handed an abelian group $M$, a ring $R$, and a proposed rule $(r,m)\mapsto rm$.
\begin{enumerate}
\item Confirm $(M,+)$ is an abelian group (identity, inverses, commutativity, associativity).
\item Confirm the action lands in $M$ and is well defined (especially if $m$ is an equivalence class).
\item Verify (M1), (M2), (M3), (M4) by direct computation. Do not skip (M4): it is the one most often false.
\item If $R$ is noncommutative, decide left vs.\ right and keep the order of scalars straight.
\end{enumerate}
\end{method}

\begin{wex}{Vector spaces are exactly modules over a field}
Let $F$ be a field. Show that an $F$-module is precisely an $F$-vector space.
\wrec Compare the module axioms (M1)--(M4) with the vector-space axioms. The \emph{rule \& why}: the four module axioms over a ring $R$ are word-for-word the vector-space axioms; ``$F$ a field'' adds nothing to the list of axioms, it only restricts the scalar ring.
\wsol The axioms for an $F$-vector space $V$ are: $V$ is an abelian group, and for $a,b\in F$, $v,w\in V$: $(a+b)v=av+bv$, $(ab)v=a(bv)$, $a(v+w)=av+aw$, $1v=v$. These are literally (M1)--(M4) with $R=F$. Conversely an $F$-module satisfies exactly these. So the notion of $F$-module \emph{is} the notion of $F$-vector space. \textit{Check.} $\mathbb{R}^n$ over $\mathbb{R}$, $\mathbb{C}$ over $\mathbb{Q}$, $F[x]$ over $F$ are all both vector spaces and $F$-modules, with the same scalar action --- consistent.
\end{wex}

\begin{wex}{$R$ as a module over itself, and $R^n$}
Let $R$ be any ring with $1$. Verify that $R$ is a left $R$-module via $r\cdot a:=ra$ (ring multiplication), and that $R^n=\{(a_1,\dots,a_n):a_i\in R\}$ is a left $R$-module via $r(a_1,\dots,a_n)=(ra_1,\dots,ra_n)$.
\wrec The action ``is'' the ring's own multiplication. The \emph{rule \& why}: the module axioms (M1)--(M4) for this action are exactly the ring axioms (both distributive laws, associativity of multiplication, and $1a=a$).
\wsol For $R$ on itself: (M1) $(r+s)a=ra+sa$ is right distributivity in $R$; (M2) $(rs)a=r(sa)$ is associativity of multiplication; (M3) $r(a+b)=ra+rb$ is left distributivity; (M4) $1a=a$ is the identity axiom. So $R$ is a left $R$-module, called the \emph{left regular module} $\,_RR$. For $R^n$, all axioms hold coordinatewise from the case $n=1$. \textit{Check.} Take $R=M_2(\mathbb{R})$ (noncommutative). With $r=\begin{psmallmatrix}1&0\\0&0\end{psmallmatrix}$, $a=\begin{psmallmatrix}0&1\\0&0\end{psmallmatrix}$ we get $ra=\begin{psmallmatrix}0&1\\0&0\end{psmallmatrix}$ but $ar=\begin{psmallmatrix}0&0\\0&0\end{psmallmatrix}$; the \emph{left} action $r\cdot a=ra$ is the right one to use, and $1\cdot a=I_2 a=a$ confirms (M4).
\end{wex}

\begin{wex}{Quotient $R/I$ and $R/I$-modules}
Let $I$ be a (two-sided) ideal of $R$. Show $R/I$ is a left $R$-module via $r\cdot(a+I):=ra+I$, and that any $R/I$-module is automatically an $R$-module.
\wrec There is a quotient and a coset action --- the danger is well-definedness. The \emph{rule \& why}: scalar multiplication on a quotient must be checked independent of coset representative, and that is exactly where the ideal condition $rI\subseteq I$ is used.
\wsol \emph{Well defined:} if $a+I=a'+I$ then $a-a'\in I$, so $r(a-a')=ra-ra'\in I$ (since $I$ is a left ideal), giving $ra+I=ra'+I$. \emph{Axioms} are inherited from $R$: e.g.\ $(rs)(a+I)=(rs)a+I=r(sa)+I=r\cdot(s\cdot(a+I))$, and $1\cdot(a+I)=a+I$. So $R/I$ is a left $R$-module. \emph{$R/I$-module $\Rightarrow$ $R$-module:} if $M$ is a module over the ring $R/I$, define $r\cdot m:=(r+I)m$; the projection $R\to R/I$ is a ring homomorphism, so (M1)--(M4) transfer. \textit{Check.} $R=\mathbb{Z}$, $I=6\mathbb{Z}$; then $\mathbb{Z}/6\mathbb{Z}=\mathbb{Z}/(6)\mathbb{Z}$ as a $\mathbb{Z}$-module via $n\cdot\bar a=\overline{na}$, e.g.\ $4\cdot\bar5=\bar2$, matching the $\mathbb{Z}$-module structure of the abelian group $\mathbb{Z}/(6)\mathbb{Z}$. Consistent.
\end{wex}

\begin{pitfall}
\textbf{Scalars genuinely act; $1m=m$ is not optional.} On any abelian group $M$ over any ring $R$ the ``zero action'' $r\cdot m:=0$ for all $r,m$ satisfies (M1),(M2),(M3) but \emph{fails} (M4) unless $M=0$. Likewise, dropping (M4) lets pathological actions sneak in. Always verify $1m=m$. A second pitfall in the noncommutative case: $(rs)m=r(sm)$ requires the scalars to act \emph{in the same order} they multiply --- writing the action on the right ($mr$) and still demanding $(rs)m$-style laws is inconsistent.
\end{pitfall}

\begin{proof}
\emph{$(V,T)\Rightarrow$ module.} $V$ is already an abelian group. Check (M1)--(M4) for $p(x)\cdot v:=p(T)v$. Since $p\mapsto p(T)$ is the evaluation ring homomorphism $F[x]\to\End_F(V)$ (it exists and is a homomorphism because $\End_F(V)$ is an $F$-algebra and $x\mapsto T$ extends uniquely by the universal property of the polynomial ring), we have $(p+q)(T)=p(T)+q(T)$ giving (M1); $(pq)(T)=p(T)q(T)$ giving (M2) since $(pq)\cdot v=p(T)q(T)v=p\cdot(q\cdot v)$; $p(T)(v+w)=p(T)v+p(T)w$ since $p(T)$ is linear, giving (M3); and $1(x)=1$ acts as $\id_V$, giving (M4).

\emph{Module $\Rightarrow (V,T)$.} If $V$ is an $F[x]$-module, restrict the action to constants $a\in F\subseteq F[x]$: axioms (M1)--(M4) for these scalars make $V$ an $F$-vector space. Define $T:V\to V$ by $Tv:=x\cdot v$. Then $T$ is additive by (M3) and $F$-linear because for $a\in F$, $T(av)=x\cdot(a\cdot v)=(xa)\cdot v=(ax)\cdot v=a\cdot(x\cdot v)=aTv$ (using commutativity of $F[x]$). 

\emph{Inverse.} Starting from $(V,T)$, the recovered operator is $v\mapsto x\cdot v=p(T)v$ with $p=x$, i.e.\ $T$ itself. Starting from a module, defining $p\cdot v:=p(T)v$ recovers the original action because both are determined by the action of $x$ (the algebra is generated by $x$ over $F$) and they agree on $x$ and on $F$. Hence the correspondence is a bijection.
\end{proof}

