\begin{method}{Recognizing a direct sum}
\textit{Trigger.} You must decide whether $M$ splits as $N_1\oplus\cdots\oplus N_k$, or build a module out of pieces.
\begin{enumerate}
\item \textbf{External:} just form tuples with componentwise structure; this always exists.
\item \textbf{Internal (two summands):} check $M=N_1+N_2$ \emph{and} $N_1\cap N_2=0$.
\item \textbf{Internal ($k\ge 3$):} check $M=\sum N_i$ \emph{and} $N_i\cap\sum_{j\neq i}N_j=0$ for every $i$ (NOT just pairwise).
\item Equivalent shortcut: show \emph{unique} representation $m=\sum a_i$. Existence $\Rightarrow$ spanning; uniqueness $\Rightarrow$ the intersection condition.
\end{enumerate}
\end{method}

\begin{wex}{$\mathbb{Z}/(6)\mathbb{Z}\cong\mathbb{Z}/(2)\mathbb{Z}\oplus\mathbb{Z}/(3)\mathbb{Z}$ as $\mathbb{Z}$-modules (CRT)}
Show $\mathbb{Z}/(6)\mathbb{Z}\cong\mathbb{Z}/(2)\mathbb{Z}\oplus\mathbb{Z}/(3)\mathbb{Z}$ as $\mathbb{Z}$-modules, both externally (via a map) and internally (via submodules).
\wrec Internal direct sum criterion plus the cyclic isomorphism $Rm\cong R/\ann(m)$; $\mathbb{Z}$-module $=$ abelian group.
\wsol \textbf{External map.} Define $\varphi:\mathbb{Z}\to\mathbb{Z}/(2)\mathbb{Z}\oplus\mathbb{Z}/(3)\mathbb{Z}$ by $\varphi(k)=(k\bmod 2,\ k\bmod 3)$, a $\mathbb{Z}$-module homomorphism. $\ker\varphi=\{k:2\mid k\text{ and }3\mid k\}=6\mathbb{Z}$ (since $\gcd(2,3)=1$). It is surjective: $|\mathbb{Z}/(2)\mathbb{Z}\oplus\mathbb{Z}/(3)\mathbb{Z}|=6=[\mathbb{Z}:6\mathbb{Z}]$ and injectivity on the quotient forces a bijection. So $\mathbb{Z}/6\mathbb{Z}\cong\mathbb{Z}/(2)\mathbb{Z}\oplus\mathbb{Z}/(3)\mathbb{Z}$, i.e.\ $\mathbb{Z}/(6)\mathbb{Z}\cong\mathbb{Z}/(2)\mathbb{Z}\oplus\mathbb{Z}/(3)\mathbb{Z}$.

\textbf{Internal.} In $M=\mathbb{Z}/(6)\mathbb{Z}$ set $N_1=\mathbb{Z}\overline3=\{\overline0,\overline3\}$ and $N_2=\mathbb{Z}\overline2=\{\overline0,\overline2,\overline4\}$. Then $\ann(\overline3)=2\mathbb{Z}$ so $N_1\cong\mathbb{Z}/(2)\mathbb{Z}$; $\ann(\overline2)=3\mathbb{Z}$ so $N_2\cong\mathbb{Z}/(3)\mathbb{Z}$. Also $N_1\cap N_2=\{\overline0\}$ (orders $2$ and $3$ are coprime) and $N_1+N_2\ni\overline3+\overline2=\overline5$ and $\overline3+\overline4=\overline1$, so $N_1+N_2=M$. By the two-summand criterion $M=N_1\oplus N_2\cong\mathbb{Z}/(2)\mathbb{Z}\oplus\mathbb{Z}/(3)\mathbb{Z}$. \textit{Check.} $\overline1=\overline3+\overline4=\overline3+2\cdot\overline2$ uniquely splits as $(\overline3,\ \overline4)\in N_1\times N_2$; orders multiply $2\cdot3=6$. Consistent.
\end{wex}

\begin{wex}{When CRT fails: $\mathbb{Z}/(4)\mathbb{Z}\not\cong\mathbb{Z}/(2)\mathbb{Z}\oplus\mathbb{Z}/(2)\mathbb{Z}$}
Decide whether $\mathbb{Z}/(4)\mathbb{Z}\cong\mathbb{Z}/(2)\mathbb{Z}\oplus\mathbb{Z}/(2)\mathbb{Z}$ as $\mathbb{Z}$-modules.
\wrec Direct sum / structure: compare element orders (a $\mathbb{Z}$-module invariant).
\wsol $\mathbb{Z}/(4)\mathbb{Z}$ has an element of additive order $4$ (namely $\overline1$). In $\mathbb{Z}/(2)\mathbb{Z}\oplus\mathbb{Z}/(2)\mathbb{Z}$ every nonzero element $(a,b)$ satisfies $2(a,b)=(0,0)$, so the maximal order is $2$. An isomorphism preserves orders, so no isomorphism exists: $\mathbb{Z}/(4)\mathbb{Z}\not\cong\mathbb{Z}/(2)\mathbb{Z}\oplus\mathbb{Z}/(2)\mathbb{Z}$. \textit{Check.} CRT needs coprime moduli; $4=2\cdot 2$ is not a product of coprimes, so the splitting must fail, consistent with the order obstruction.
\end{wex}

\begin{wex}{Internal sum of three lines failing directness}
In $M=\F^2$ ($\F$ a field), let $N_1=\F e_1$, $N_2=\F e_2$, $N_3=\F(e_1+e_2)$. Is $M=N_1\oplus N_2\oplus N_3$?
\wrec Internal criterion for $k=3$: need $N_i\cap\sum_{j\neq i}N_j=0$, not just pairwise.
\wsol Spanning holds: already $N_1+N_2=M$. Pairwise intersections are $0$ (distinct lines). But $N_3\subseteq N_1+N_2$, so $N_3\cap(N_1+N_2)=N_3\neq 0$, violating the $i=3$ condition. Hence the sum is \emph{not} direct. \textit{Check.} The relation $1\cdot e_1+1\cdot e_2+(-1)(e_1+e_2)=0$ is a nontrivial way to write $0$, exactly the obstruction the criterion detects.
\end{wex}

\begin{wex}{Splitting a $\mathbb{Z}$-module: $\mathbb{Z}/(30)\mathbb{Z}\cong\mathbb{Z}/(2)\mathbb{Z}\oplus\mathbb{Z}/(3)\mathbb{Z}\oplus\mathbb{Z}/(5)\mathbb{Z}$}
Decompose $\mathbb{Z}/(30)\mathbb{Z}$ as an internal direct sum of cyclic $\mathbb{Z}$-modules.
\wrec Iterated CRT via the internal criterion for three submodules.
\wsol Let $N_1=\mathbb{Z}\overline{15}\cong\mathbb{Z}/(2)\mathbb{Z}$, $N_2=\mathbb{Z}\overline{10}\cong\mathbb{Z}/(3)\mathbb{Z}$, $N_3=\mathbb{Z}\overline6\cong\mathbb{Z}/(5)\mathbb{Z}$ (annihilators $2\mathbb{Z},3\mathbb{Z},5\mathbb{Z}$ respectively). Their orders $2,3,5$ are pairwise coprime, so $N_i\cap\sum_{j\neq i}N_j$ has order dividing both $|N_i|$ and $|\sum_{j\neq i}N_j|$ (orders dividing $15,10,6$ respectively, since $N_j+N_k$ is the image of $N_j\oplus N_k$), and $\gcd$ forces $0$ in each case. Sum: $\overline{15}+\overline{10}+\overline6=\overline{31}=\overline1$ generates, so $\sum N_i=M$. Hence $\mathbb{Z}/(30)\mathbb{Z}=N_1\oplus N_2\oplus N_3\cong\mathbb{Z}/(2)\mathbb{Z}\oplus\mathbb{Z}/(3)\mathbb{Z}\oplus\mathbb{Z}/(5)\mathbb{Z}$. \textit{Check.} $2\cdot3\cdot5=30=|M|$. Consistent.
\end{wex}

\begin{proof}
\emph{Existence.} Define $\Phi(\sum_a r_a a)=\sum_a r_a f(a)$ (a finite sum). This is well defined because each element of $R^{(A)}$ has a unique finitely-supported expression $\sum r_a a$. It is additive and $R$-linear because the operations on $R^{(A)}$ are componentwise, and $\Phi(\iota(a))=\Phi(1\cdot a)=f(a)$. \emph{Uniqueness.} Any $R$-map $\Psi$ with $\Psi\iota=f$ must satisfy $\Psi(\sum_a r_a a)=\sum_a r_a\Psi(a)=\sum_a r_a f(a)=\Phi(\sum r_a a)$, since $\{a\}$ generates $R^{(A)}$ and $\Psi$ respects $R$-linear combinations. So $\Psi=\Phi$.
\end{proof}

\begin{proof}
Take $A$ a generating set and $f:A\hookrightarrow M$ the inclusion. The induced $\Phi$ has image $\Phi(R^{(A)})=R\cdot A=M$, so $\Phi$ is onto. By the First Isomorphism Theorem $M\cong R^{(A)}/\ker\Phi$. If $M$ is finitely generated, choose $A$ finite of size $n$; then $R^{(A)}=R^n$ surjects onto $M$. Conversely a quotient of $R^n$ is generated by the $n$ images of the standard basis.
\end{proof}

\begin{theorem}[Rank of a free module is well defined over a commutative ring]
Let $R$ be a nonzero \emph{commutative} ring. If $R^m\cong R^n$ as $R$-modules, then $m=n$. Thus the \emph{rank} of a free module $R^n$ is a well-defined invariant.
\end{theorem}

\begin{proof}
Let $\mathfrak{m}$ be a maximal ideal of $R$ (exists since $R\neq 0$), and let $k=R/\mathfrak{m}$, a field. Tensoring with $k$, $k\otimes_R R^n\cong k^n$ as $k$-vector spaces (tensor commutes with finite direct sums and $k\otimes_R R\cong k$). An isomorphism $R^m\cong R^n$ of $R$-modules induces an isomorphism $k^m\cong k^n$ of $k$-vector spaces, so $m=\dim_k k^m=\dim_k k^n=n$ by uniqueness of dimension over a field.
\end{proof}

\begin{method}{Using the universal property to define a map out of $R^{(A)}$}
\textit{Trigger.} You must \emph{construct} an $R$-homomorphism whose domain is free (or $R^n$), or prove two maps out of a free module agree.
\begin{enumerate}
\item Specify the map \emph{only on the basis}: choose any $f(a)\in M$ for each basis element $a$. No relations to check --- a free module has none.
\item Extend $R$-linearly: $\Phi(\sum r_a a)=\sum r_a f(a)$. The theorem guarantees this is a well-defined homomorphism and is the \emph{unique} extension.
\item To prove $\Phi=\Psi$ on $R^{(A)}$, check only $\Phi(a)=\Psi(a)$ on basis elements.
\item To present a module: pick generators $A$, get $\Phi:R^{(A)}\twoheadrightarrow M$, then $M\cong R^{(A)}/\ker\Phi$ and $\ker\Phi$ records the relations.
\end{enumerate}
\end{method}

\begin{wex}{Build a map out of a free module via the universal property}
Construct the $\mathbb{Z}$-module homomorphism $\Phi:\mathbb{Z}^2\to\mathbb{Z}/(6)\mathbb{Z}$ with $\Phi(e_1)=\overline2$, $\Phi(e_2)=\overline3$, and identify $\im\Phi$ and $\ker\Phi$.
\wrec Universal property of $R^{(A)}=\mathbb{Z}^2$: a map is determined by its values on the basis $\{e_1,e_2\}$.
\wsol By the universal property $\Phi(a,b)=a\,\overline2+b\,\overline3=\overline{2a+3b}$. Image: $2a+3b$ realizes $\overline1=\overline3-\overline2$ (take $a=-1,b=1$), so $\im\Phi=\mathbb{Z}/(6)\mathbb{Z}$ (surjective). Kernel: $(a,b)\in\ker\Phi$ iff $2a+3b\equiv0\pmod6$. Reduce: mod $2$, $3b\equiv b\equiv0$, so $b$ is even; mod $3$, $2a\equiv -a\equiv0$, so $a$ is divisible by $3$. These two congruences are independent and together necessary and sufficient, so $\ker\Phi=3\mathbb{Z}\oplus2\mathbb{Z}=\mathbb{Z}(3,0)+\mathbb{Z}(0,2)$. \textit{Check.} $\Phi(3,0)=\overline6=\overline0$, $\Phi(0,2)=\overline6=\overline0$. Index: $[\mathbb{Z}^2:\ker\Phi]=\det\begin{psmallmatrix}3&0\\0&2\end{psmallmatrix}=6=|\im\Phi|$, confirming $\mathbb{Z}^2/\ker\Phi\cong\mathbb{Z}/(6)\mathbb{Z}$.
\end{wex}

\begin{wex}{Free of rank $2$: a basis and coordinates}
In $M=\mathbb{Z}^2$, let $v_1=(2,1)$ and $v_2=(1,1)$. Decide whether $\{v_1,v_2\}$ is a basis of $\mathbb{Z}^2$, and if so give the coordinates of $(3,2)$.
\wrec A free module of rank $2$: $\{v_1,v_2\}$ is a basis iff the change-of-basis matrix is invertible over $R=\mathbb{Z}$ (determinant a unit).
\wsol Form $B=\begin{psmallmatrix}2&1\\1&1\end{psmallmatrix}$ with columns $v_1,v_2$. $\det B=2\cdot1-1\cdot1=1\in\units{\mathbb{Z}}=\{\pm1\}$, so $B$ is invertible over $\mathbb{Z}$ with $B^{-1}=\begin{psmallmatrix}1&-1\\-1&2\end{psmallmatrix}$. Hence $\{v_1,v_2\}$ is a $\mathbb{Z}$-basis. Coordinates of $w=(3,2)$: solve $Bc=w$, $c=B^{-1}w=\begin{psmallmatrix}1&-1\\-1&2\end{psmallmatrix}\begin{psmallmatrix}3\\2\end{psmallmatrix}=\begin{psmallmatrix}1\\1\end{psmallmatrix}$, so $(3,2)=1\cdot v_1+1\cdot v_2$. \textit{Check.} $1\cdot(2,1)+1\cdot(1,1)=(3,2)$. Correct, and integer coordinates confirm $w\in\mathbb{Z}^2$ exactly.
\end{wex}

\begin{wex}{A determinant that is not a unit: NOT a basis}
In $M=\mathbb{Z}^2$, is $\{(2,0),(0,3)\}$ a basis?
\wrec Same criterion: over $\mathbb{Z}$ a generating square matrix must have determinant $\pm1$.
