\begin{method}{Computing $M\otimes_R N$ via the universal property}
\textit{Trigger.} You must identify a tensor product, or define / evaluate a homomorphism \emph{out of} one.
\begin{enumerate}
\item \textbf{To define a map out of $M\otimes_R N$:} never define it on simple tensors directly. Define a balanced map $\varphi\colon M\times N\to L$, \emph{check all three balanced axioms}, then the UP hands you $\Phi$ with $\Phi(m\otimes n)=\varphi(m,n)$.
\item \textbf{To identify the group:} guess the answer $T$, build maps both ways. Forward: a balanced $M\times N\to T$ gives $M\otimes_R N\to T$. Back: a map $T\to M\otimes_R N$ on generators. Check they are mutually inverse on simple tensors / generators.
\item \textbf{To kill an element:} exhibit it as $0$ using $0\otimes n=0$, $mr\otimes n=m\otimes rn$, and biadditivity --- relations only flow \emph{in} this way.
\end{enumerate}
\end{method}

\begin{wex}{$R\otimes_R N\cong N$ (unit object)}
For a left $R$-module $N$ (with $R$ a right module over itself), prove $R\otimes_R N\cong N$ as abelian groups, naturally.
\wrec $R$ is the multiplicative ``unit'' for $\otimes$; expect $r\otimes n\mapsto rn$, with inverse $n\mapsto 1\otimes n$.
\wsol \emph{Forward.} Define $\varphi\colon R\times N\to N$ by $\varphi(r,n)=rn$. Biadditive in each slot, and balanced: $\varphi(rs,n)=(rs)n=r(sn)=\varphi(r,sn)$. By the UP, get $\Phi\colon R\otimes_R N\to N$, $\Phi(r\otimes n)=rn$. \emph{Backward.} Define $\Psi\colon N\to R\otimes_R N$ by $\Psi(n)=1\otimes n$; it is a group hom. \emph{Inverse check.} $\Phi\Psi(n)=\Phi(1\otimes n)=1\cdot n=n$. And on a simple tensor, $\Psi\Phi(r\otimes n)=\Psi(rn)=1\otimes rn=1\cdot r\otimes n=r\otimes n$ (slide $1r\otimes n=1\otimes rn$ read backwards). Since simple tensors generate, $\Psi\Phi=\id$. Hence $R\otimes_R N\cong N$. \textit{Check.} With $R=\mathbb{Z}$, $\mathbb{Z}\otimes_\mathbb{Z}\mathbb{Z}/(n)\mathbb{Z}\cong\mathbb{Z}/(n)\mathbb{Z}$, consistent with the $\gcd$ formula at $m=0$ read as $\gcd(0,n)=n$. Correct.
\end{wex}

\begin{wex}{A bilinear map factoring through $\otimes$}
Let $V=W=\mathbb{R}^2$ over $R=\mathbb{R}$. The determinant-style map $\beta\colon \mathbb{R}^2\times\mathbb{R}^2\to\mathbb{R}$, $\beta\big((a,b),(c,d)\big)=ad-bc$, is $\mathbb{R}$-bilinear. Realize it as a homomorphism out of $\mathbb{R}^2\otimes_\mathbb{R}\mathbb{R}^2$.
\wrec ``$\mathbb{R}$-bilinear map into a group'' is exactly the UP trigger: it must factor uniquely through $\otimes$.
\wsol Check $\beta$ is balanced over $\mathbb{R}$: additive in each argument (determinant expansion is linear in each row), and for $\lambda\in\mathbb{R}$, $\beta(\lambda u,v)=\lambda\beta(u,v)=\beta(u,\lambda v)$. (Over the commutative ring $\mathbb{R}$, an $\mathbb{R}$-bilinear map is in particular balanced, and $\lambda$ slides freely.) By the UP there is a unique $\mathbb{R}$-linear $B\colon\mathbb{R}^2\otimes_\mathbb{R}\mathbb{R}^2\to\mathbb{R}$ with $B(u\otimes v)=ad-bc$. On the basis $\{e_1\otimes e_1,e_1\otimes e_2,e_2\otimes e_1,e_2\otimes e_2\}$ of $\mathbb{R}^2\otimes_\mathbb{R}\mathbb{R}^2\cong\mathbb{R}^4$, $B$ takes values $0,1,-1,0$. \textit{Check.} $B(e_1\otimes e_2-e_2\otimes e_1)=1-(-1)=2$; directly $\beta(e_1,e_2)-\beta(e_2,e_1)=1-(-1)=2$. Note $e_1\otimes e_2-e_2\otimes e_1\neq0$ is \emph{not} a simple tensor (it is the alternating combination $\det$ detects). Correct.
\end{wex}

