\end{itemize}
\end{pitfall}

\begin{exers}{Quick checks.}
\item Compute $\mathbb{Z}/(12)\mathbb{Z}\otimes_\mathbb{Z}\mathbb{Z}/(18)\mathbb{Z}$ as an abelian group, and find the order of the simple tensor $\bar4\otimes\bar3$ in it.
\item Show that the simple tensor $\bar2\otimes\bar3$ is $0$ in $\mathbb{Z}/(4)\mathbb{Z}\otimes_\mathbb{Z}\mathbb{Z}/(9)\mathbb{Z}$, yet $\bar2\neq\bar0$ and $\bar3\neq\bar0$.
\item Let $A$ be an abelian group with $nA=A$ for some fixed $n\ge2$ (i.e.\ multiplication by $n$ is surjective). Prove $A\otimes_\mathbb{Z}\mathbb{Z}/(n)\mathbb{Z}=0$.
\item Using only the universal property, prove that the canonical map $M\times N\to M\otimes_R N$ has image generating the whole group, and deduce that if $M$ and $N$ are each generated by one element over a commutative $R$ then $M\otimes_R N$ is cyclic as an $R$-module.
\end{exers}

\begin{proof}[Sketch]
For fixed $s'\in S$ the map $(s,n)\mapsto (s's)\otimes n$ is $R$-balanced, so it induces an additive endomorphism of $S\otimes_R N$; one checks these define a unital, associative left $S$-action. For the universal property: given $f$, the map $(s,n)\mapsto s\,f(n)$ is $R$-balanced into $L$ ($s r\otimes n\mapsto (sr)f(n)=s\,f(rn)$ using that $f$ is $R$-linear), so it induces an additive $F$; $F$ is $S$-linear by the displayed action, and $F(1\otimes n)=f(n)$. Uniqueness holds because the $s\otimes n$ generate $S\otimes_R N$ as a group and $F(s\otimes n)=sF(1\otimes n)=s\,f(n)$ is forced.
\end{proof}

