\begin{method}{Recognizing / using extension of scalars}
\textit{Trigger.} You have an $R$-module $N$ but need an $S$-module ($R\subseteq S$), e.g. complexify a real space ($R=\mathbb{R}\subseteq S=\mathbb{C}$), pass from $\mathbb{Z}$ to $\mathbb{Q}$, or induce from a subring/subgroup.
\begin{enumerate}
\item Form $S\otimes_R N$; its $S$-action is $s'(s\otimes n)=(s's)\otimes n$.
\item If $N$ is free/has a basis $\{n_i\}$ over $R$, then $\{1\otimes n_i\}$ is an $S$-basis: $S\otimes_R R^k\cong S^k$.
\item To extend an $R$-map $f\colon N\to L$ ($L$ an $S$-module) to an $S$-map, use $F(s\otimes n)=s\,f(n)$.
\end{enumerate}
\end{method}

\begin{wex}{Complexification $\mathbb{C}\otimes_\mathbb{R}\mathbb{R}^n\cong\mathbb{C}^n$}
With $R=\mathbb{R}\subseteq S=\mathbb{C}$, compute $\mathbb{C}\otimes_\mathbb{R}\mathbb{R}^n$ as a $\mathbb{C}$-vector space.
\wrec Free module of rank $n$; extension of scalars sends $\mathbb{R}^n\mapsto$ rank-$n$ free $\mathbb{C}$-module.
\wsol $\mathbb{R}^n$ has $\mathbb{R}$-basis $e_1,\dots,e_n$. By the method, $\{1\otimes e_i\}_{i=1}^n$ is a $\mathbb{C}$-basis of $\mathbb{C}\otimes_\mathbb{R}\mathbb{R}^n$, so $\mathbb{C}\otimes_\mathbb{R}\mathbb{R}^n\cong\mathbb{C}^n$ as $\mathbb{C}$-modules, with $z\otimes(a_1,\dots,a_n)\mapsto(za_1,\dots,za_n)$. \textit{Check.} $\dim_\mathbb{C}(\mathbb{C}\otimes_\mathbb{R}\mathbb{R}^n)=n$ while $\dim_\mathbb{R}(\mathbb{C}\otimes_\mathbb{R}\mathbb{R}^n)=2n$, matching $\dim_\mathbb{R}\mathbb{C}^n=2n$. For $n=1$: $\mathbb{C}\otimes_\mathbb{R}\mathbb{R}\cong\mathbb{C}$ (a special case of $R\otimes_R N\cong N$, with $R=\mathbb{R}$, $N=\mathbb{C}$ and the two factors interchanged). Correct.
\end{wex}

\begin{wex}{Reduction mod $p$: $\mathbb{Z}/(p)\mathbb{Z}\otimes_\mathbb{Z} M\cong M/pM$}
For $R=\mathbb{Z}$, $S=\mathbb{Z}/(p)\mathbb{Z}$ is a \emph{quotient} ring; show $\mathbb{Z}/(p)\mathbb{Z}\otimes_\mathbb{Z} M\cong M/pM$ for any abelian group $M$.
\wrec Tensoring with a cyclic quotient ring $\mathbb{Z}/p\mathbb{Z}=\mathbb{Z}/(p)$; expect to mod out by $p$.
\wsol Define $\varphi\colon\mathbb{Z}/(p)\mathbb{Z}\times M\to M/pM$ by $\varphi(\bar a,m)=\overline{am}$. Well defined: if $a\equiv a'\pmod p$ then $am-a'm=(a-a')m\in pM$. It is $\mathbb{Z}$-balanced (biadditive; $\varphi(\bar a r,m)=\overline{arm}=\varphi(\bar a,rm)$ for $r\in\mathbb{Z}$). The UP gives $\Phi\colon\mathbb{Z}/(p)\mathbb{Z}\otimes_\mathbb{Z} M\to M/pM$, $\bar a\otimes m\mapsto\overline{am}$. Inverse: $\Psi\colon M/pM\to\mathbb{Z}/(p)\mathbb{Z}\otimes_\mathbb{Z} M$, $\Psi(\bar m)=\bar1\otimes m$, well defined since $\bar1\otimes pm=\bar p\otimes m=\bar0\otimes m=0$. They invert each other on generators. \textit{Check.} $\mathbb{Z}/(p)\mathbb{Z}\otimes_\mathbb{Z}\mathbb{Z}\cong\mathbb{Z}/p\mathbb{Z}$ ($M=\mathbb{Z}$), and $\mathbb{Z}/(p)\mathbb{Z}\otimes_\mathbb{Z}\mathbb{Z}/(n)\mathbb{Z}\cong\mathbb{Z}/(n)\mathbb{Z}/p\mathbb{Z}/(n)\mathbb{Z}\cong\mathbb{Z}/(\gcd(p,n))\mathbb{Z}$, agreeing with the $\gcd$ formula. Correct.
\end{wex}

\begin{exers}{Quick checks.}
\item Compute $\mathbb{C}\otimes_\mathbb{R}\mathbb{C}$ as a $\mathbb{C}$-vector space and as an $\mathbb{R}$-algebra; in particular find its $\mathbb{C}$-dimension and exhibit a $\mathbb{C}$-basis. (Note: the left and right $\mathbb{C}$-actions differ.)
\item For an abelian group $M$, prove $\mathbb{Q}\otimes_\mathbb{Z} M=0$ if and only if every element of $M$ is torsion, by writing a general element of $\mathbb{Q}\otimes_\mathbb{Z} M$ as a single simple tensor $q\otimes x$ over a common denominator.
\item Let $R=\mathbb{Z}$ and $S=\mathbb{Z}[i]$. Compute $S\otimes_\mathbb{Z}\mathbb{Z}/(3)\mathbb{Z}$ and $S\otimes_\mathbb{Z}\mathbb{Z}^2$ as $S$-modules, identifying each with a standard form.
\item Show that $\mathbb{Z}/(6)\mathbb{Z}\otimes_\mathbb{Z} M\cong M/6M$ directly from the reduction-mod-$p$ idea applied to a composite modulus, and verify it agrees with $\mathbb{Z}/(6)\mathbb{Z}\otimes_\mathbb{Z}\mathbb{Z}/(4)\mathbb{Z}$.
\end{exers}

\begin{proof}[Sketch]
For fixed $r$, $(m,n)\mapsto (rm)\otimes n$ is $R$-balanced (using commutativity: $(mr')\mapsto r(mr')\otimes n=(mr')\otimes rn$ etc.), so $r\cdot(-)$ is a well-defined endomorphism; commutativity gives $(rm)\otimes n=m\otimes(rn)$. Unitality and associativity of the action are routine. The middle-linear relation $mr\otimes n=m\otimes rn$ now coincides with $R$-bilinearity, so the abelian-group UP upgrades to an $R$-module UP.
\end{proof}

\begin{remark}
Over commutative $R$, every $R$-bilinear map is $R$-balanced (not conversely: $(u,v)\mapsto\overline{uv}$, the complex conjugate of $uv$, is a $\mathbb{C}$-balanced map $\mathbb{C}\times\mathbb{C}\to\mathbb{C}$ that is not $\mathbb{C}$-bilinear), and one writes $r(m\otimes n)$ unambiguously. The earlier examples $\mathbb{Z}/(m)\mathbb{Z}\otimes_\mathbb{Z}\mathbb{Z}/(n)\mathbb{Z}\cong\mathbb{Z}/(\gcd(m,n))\mathbb{Z}$, $\mathbb{R}^2\otimes_\mathbb{R}\mathbb{R}^2\cong\mathbb{R}^4$, $\mathbb{C}\otimes_\mathbb{R}\mathbb{R}^n\cong\mathbb{C}^n$ are all instances. Tensor distributes over direct sums: $M\otimes_R\big(\bigoplus_i N_i\big)\cong\bigoplus_i(M\otimes_R N_i)$, which together with $R\otimes_R N\cong N$ and $R/(a)\otimes_R R/(b)\cong R/(a,b)$ computes all tensor products of finitely generated modules over a PID.
\end{remark}

