\end{enumerate}
\end{method}

\begin{wex}{Direct sums: a $2\times2$ block computation}
Over $R=\mathbb{Z}$, compute $(\mathbb{Z}/(4)\mathbb{Z}\oplus\mathbb{Z}/(6)\mathbb{Z})\otimes_\mathbb{Z}\mathbb{Z}/(9)\mathbb{Z}$.
\wrec Distribute $\otimes$ over $\oplus$, then apply the $\gcd$ rule to each block.
\wsol
\[
\begin{aligned}
(\mathbb{Z}/(4)\mathbb{Z}\oplus\mathbb{Z}/(6)\mathbb{Z})\otimes_\mathbb{Z}\mathbb{Z}/(9)\mathbb{Z}
&\cong(\mathbb{Z}/(4)\mathbb{Z}\otimes_\mathbb{Z}\mathbb{Z}/(9)\mathbb{Z})\oplus(\mathbb{Z}/(6)\mathbb{Z}\otimes_\mathbb{Z}\mathbb{Z}/(9)\mathbb{Z})\\
&\cong\mathbb{Z}/(\gcd(4,9))\mathbb{Z}\oplus\mathbb{Z}/(\gcd(6,9))\mathbb{Z}=\mathbb{Z}/(1)\mathbb{Z}\oplus\mathbb{Z}/(3)\mathbb{Z}\cong\mathbb{Z}/(3)\mathbb{Z}.
\end{aligned}
\]
\textit{Check.} $\gcd(4,9)=1\Rightarrow$ first block $0$; $\gcd(6,9)=3\Rightarrow$ second block $\mathbb{Z}/(3)\mathbb{Z}$. The generator $(\bar0,\bar1)\otimes\bar1$ has order $3$ (it corresponds to the generator $\bar1\otimes\bar1\neq0$ of the block $\mathbb{Z}/(6)\mathbb{Z}\otimes_\mathbb{Z}\mathbb{Z}/(9)\mathbb{Z}\cong\mathbb{Z}/(3)\mathbb{Z}$, and $3\cdot\big((\bar0,\bar1)\otimes\bar1\big)=(\bar0,\bar3)\otimes\bar1$ corresponds to $\bar3\otimes\bar1=3(\bar1\otimes\bar1)=0$). Correct.
\end{wex}

\begin{wex}{Scalars commute past $\otimes$}
Over commutative $R=\mathbb{Z}$, verify directly in $\mathbb{Z}/(6)\mathbb{Z}\otimes_\mathbb{Z}\mathbb{Z}/(10)\mathbb{Z}$ that $3\cdot(\bar1\otimes\bar1)$ can be computed on either factor.
\wrec Proposition: $r(m\otimes n)=(rm)\otimes n=m\otimes(rn)$ over commutative $R$.
\wsol Compute three ways: $3\cdot(\bar1\otimes\bar1)=\bar3\otimes\bar1$ (act on the left factor) $=\bar1\otimes\bar3$ (act on the right factor) $=3(\bar1\otimes\bar1)$ again. In $\mathbb{Z}/(6)\mathbb{Z}\otimes_\mathbb{Z}\mathbb{Z}/(10)\mathbb{Z}\cong\mathbb{Z}/(2)\mathbb{Z}$ (from $\gcd(6,10)=2$), the generator $\bar1\otimes\bar1$ has order $2$, so $3(\bar1\otimes\bar1)=1\cdot(\bar1\otimes\bar1)=\bar1\otimes\bar1$. \textit{Check.} $\bar3\otimes\bar1\mapsto\overline{3}=\bar1\in\mathbb{Z}/(2)\mathbb{Z}$ and $\bar1\otimes\bar3\mapsto\overline{3}=\bar1\in\mathbb{Z}/(2)\mathbb{Z}$ under the iso $\bar a\otimes\bar b\mapsto\overline{ab}$; both equal $\bar1\otimes\bar1$. The action is consistent on both factors, as the Proposition guarantees. Correct.
\end{wex}

\begin{exers}{Quick checks.}
\item Over $R=\mathbb{Z}$, compute $(\mathbb{Z}/(2)\mathbb{Z}\oplus\mathbb{Z}/(12)\mathbb{Z})\otimes_\mathbb{Z}(\mathbb{Z}/(8)\mathbb{Z}\oplus\mathbb{Z}/(18)\mathbb{Z})$ by expanding into a $2\times2$ block table and applying the $\gcd$ rule to each block.
\item Let $R=F[x]$. Compute $\big(F[x]/(x^2)\big)\otimes_{F[x]}\big(F[x]/(x^3)\big)$ and give its dimension as an $F$-vector space.
\item Over a commutative ring $R$, prove the symmetry isomorphism $M\otimes_R N\cong N\otimes_R M$ via the universal property (construct maps both ways and check they are mutually inverse on simple tensors).
\item Over commutative $R$, suppose $M$ is generated by $m$ elements and $N$ by $n$ elements. Prove $M\otimes_R N$ is generated by at most $mn$ elements, and show by example over $R=\mathbb{Z}$ that the bound need not be attained.
\end{exers}

Two boundary cases pin down the language. With $0$ the zero module:
\begin{itemize}
\item $0\xrightarrow{\ }A\xrightarrow{\ \psi\ }B$ is exact at $A$ $\iff$ $\ker\psi=0$ $\iff$ $\psi$ is \emph{injective}.
\item $B\xrightarrow{\ \varphi\ }C\xrightarrow{\ }0$ is exact at $C$ $\iff$ $\im\varphi=C$ $\iff$ $\varphi$ is \emph{surjective}.
\end{itemize}

\begin{method}{Testing exactness of a (short) sequence}
\textit{Trigger.} You are handed a chain of maps and asked whether it is exact, or whether
the two end zeros are legitimate. \textit{Recipe.}
\begin{enumerate}
\item At each interior node $Y$ with incoming $\alpha$ and outgoing $\beta$, first check
$\beta\circ\alpha=0$ (this gives $\im\alpha\subseteq\ker\beta$ for free).
\item Then check the reverse $\ker\beta\subseteq\im\alpha$: take $y\in\ker\beta$ and exhibit a preimage under $\alpha$.
\item Leftmost zero $\Rightarrow$ check the first nonzero map is injective; rightmost zero $\Rightarrow$ check the last nonzero map is surjective.
\item For a SES, equivalently verify: $\psi$ injective, $\varphi$ surjective, $\im\psi=\ker\varphi$; often it is fastest to use the dimension/order count $|B|=|A|\cdot|C|$ (finite case) or $\rank$ count as a sanity check.
\end{enumerate}
\end{method}

\begin{remark}
For abelian groups (i.e. $\mathbb{Z}$-modules) and more generally for modules over any commutative
domain, exactness of a SES forces the order count $|B|=|A|\cdot|C|$ when all
are finite. This single equality is a fast necessary check, though not sufficient on its
own.
\end{remark}

