\begin{enumerate}
\item there is a splitting $s\colon C\to B$ with $\varphi s=\id_C$;
\item there is a retraction $t\colon B\to A$ with $t\psi=\id_A$;
\item $B=\im\psi\oplus K$ for some submodule $K$ with $\varphi|_K\colon K\xrightarrow{\cong}C$; and in all cases $B\cong A\oplus C$ via an isomorphism compatible with $\psi,\varphi$.
\end{enumerate}
\end{proposition}

\begin{method}{Deciding whether a SES splits}
\textit{Trigger.} You have a SES and want to know if $B\cong A\oplus C$, or you must build
a splitting. \textit{Recipe.}
\begin{enumerate}
\item Try to define a section $s\colon C\to B$ by sending generators of $C$ to chosen
preimages \emph{that respect all relations}; if the relations can be honored, $s$ exists
and the sequence splits.
\item Equivalently hunt for a retraction $t\colon B\to A$ fixing the copy of $A$.
\item To prove \emph{non}-splitting, show $B\not\cong A\oplus C$ as $R$-modules (compare
torsion, order of elements, number of elements of a given order, etc.).
\item Special automatic case: if $C$ is \emph{projective} (e.g. free), the sequence always splits.
\end{enumerate}
\end{method}

\begin{pitfall}
``$|B|=|A|\cdot|C|$, so $B\cong A\oplus C$'' is false. The order/dimension count is a
\emph{necessary} consequence of a SES but says nothing about splitting:
$0\to\mathbb{Z}\xrightarrow{2}\mathbb{Z}\to\mathbb{Z}/(2)\mathbb{Z}\to0$ passes the count yet does not split, and
$0\to\mathbb{Z}/(2)\mathbb{Z}\to\mathbb{Z}/(4)\mathbb{Z}\to\mathbb{Z}/(2)\mathbb{Z}\to0$ has $|B|=4=2\cdot2$ but $\mathbb{Z}/(4)\mathbb{Z}\not\cong\mathbb{Z}/(2)\mathbb{Z}\oplus\mathbb{Z}/(2)\mathbb{Z}$.
\end{pitfall}

