\item every SES $0\to A\to B\to P\to0$ splits;
\item $P$ is a direct summand of a free module: $F\cong P\oplus Q$ for some free $F$;
\item the functor $\Hom_R(P,-)$ is exact (equivalently, it takes surjections to surjections; it is always left exact).
\end{enumerate}
In particular every free module is projective.
\end{theorem}

\begin{method}{Recognizing / using projectivity}
\textit{Trigger.} You must lift a map through a surjection, split a SES whose quotient is
$P$, or certify a module is projective. \textit{Recipe.}
\begin{enumerate}
\item If $P$ is free, it is projective -- lift by sending a basis to chosen preimages.
\item To show $P$ projective, exhibit a free $F$ with $F\cong P\oplus Q$ (find a complementary summand).
\item Over $\mathbb{Z}/(n)\mathbb{Z}$ with $n=ab$, $\gcd(a,b)=1$: $\mathbb{Z}/(n)\mathbb{Z}\cong\mathbb{Z}/(a)\mathbb{Z}\oplus\mathbb{Z}/(b)\mathbb{Z}$, so each factor is a projective $\mathbb{Z}/(n)\mathbb{Z}$-module.
\item To \emph{use} projectivity, invoke the lift $\tilde f$ or the automatic splitting of $0\to A\to B\to P\to0$.
\end{enumerate}
\end{method}

