\begin{theorem}[Characterizations of injectives]\label{thm:inj@c10}
For an $R$-module $Q$ the following are equivalent:
\begin{enumerate}
\item $Q$ is injective (the extension property above);
\item every SES $0\to Q\to B\to C\to0$ splits;
\item the functor $\Hom_R(-,Q)$ is exact (it is always left exact; injectivity is the extra statement that it sends injections to surjections of $\Hom$).
\end{enumerate}
\end{theorem}

\begin{theorem}[Baer's Criterion]\label{thm:baer@c10}
An $R$-module $Q$ is injective if and only if for every left ideal $I\subseteq R$, every
$R$-homomorphism $g\colon I\to Q$ extends to an $R$-homomorphism $\tilde g\colon R\to Q$.
\end{theorem}

\begin{corollary}\label{cor:divisible@c10}
A $\mathbb{Z}$-module is injective if and only if it is divisible. In particular $\mathbb{Q}$, $\mathbb{Q}/\mathbb{Z}$, and
$\mathbb{R}/\mathbb{Z}$ are injective $\mathbb{Z}$-modules, while $\mathbb{Z}$ and $\mathbb{Z}/(n)\mathbb{Z}$ ($n\geq2$) are not.
\end{corollary}

\begin{proof}
By Baer's Criterion over $R=\mathbb{Z}$ it suffices to extend maps from ideals $I=n\mathbb{Z}$ to $\mathbb{Z}$. A
map $g\colon n\mathbb{Z}\to D$ is determined by $g(n)=d\in D$; an extension $\tilde g\colon\mathbb{Z}\to D$
exists iff there is $d'=\tilde g(1)$ with $nd'=g(n)=d$, i.e. iff $D$ is divisible.
\end{proof}

\begin{method}{Showing a module is (not) injective}
\textit{Trigger.} Certify injectivity, or extend a map past an inclusion.
\textit{Recipe.}
\begin{enumerate}
\item Over $\mathbb{Z}$: injective $\iff$ divisible -- check $nd'=d$ solvable for all $n\neq0$, $d$.
\item General ring: use \textbf{Baer} -- only need to extend maps $I\to Q$ from ideals $I$ to $R$.
\item To extend a concrete $f\colon A\to Q$, push along $A\hookrightarrow B$ by choosing images of new generators consistently (divisibility supplies the needed solutions).
\item To prove \emph{not} injective, exhibit an inclusion $A\hookrightarrow B$ and $f\colon A\to Q$ admitting no extension (often a torsion/divisibility obstruction).
\end{enumerate}
\end{method}

\begin{wex}{$\mathbb{Z}$ is NOT injective}
Problem. Show $\mathbb{Z}$ is not an injective $\mathbb{Z}$-module.
\wrec Injective over $\mathbb{Z}$ means divisible; $\mathbb{Z}$ is not divisible.
\wsol $\mathbb{Z}$ is not divisible: $1\in\mathbb{Z}$ is not divisible by $2$ (no integer $m$ with
$2m=1$). Concretely take $\id\colon\mathbb{Z}\to\mathbb{Z}$ and the inclusion
$\mathbb{Z}\xrightarrow{\times2}\mathbb{Z}$; an extension $\tilde f\colon\mathbb{Z}\to\mathbb{Z}$ of $\id$ along $\times2$
would need $\tilde f(\times2\cdot1)=\tilde f(2)$ to equal $\id(1)=1$, i.e. $2\tilde
f(1)=1$, impossible in $\mathbb{Z}$. So no extension; $\mathbb{Z}$ is not injective. \textit{Check.}
Consistent with Cor.~\ref{cor:divisible@c10}, since $\mathbb{Z}$ is non-divisible. Correct.
\end{wex}

\begin{pitfall}
Injectivity is \emph{not} the same as ``$f$ is injective.'' An injective module is a target
$Q$ with the extension property; it has nothing to do with any one map being one-to-one.
Likewise ``divisible $\Rightarrow$ injective'' is a theorem \emph{only over special rings} ($\mathbb{Z}$, PIDs, and more
generally Dedekind domains); over a general ring use Baer's Criterion.
\end{pitfall}

\begin{definition}[Flat module]
A right $R$-module $M$ is \emph{flat} if the functor $M\otimes_R-$ preserves injections:
for every injection $\iota\colon A\hookrightarrow B$ of left $R$-modules,
$1\otimes\iota\colon M\otimes_R A\to M\otimes_R B$ is injective. Equivalently (with right
exactness), $M\otimes_R-$ is exact.
\end{definition}

\begin{proposition}\label{prop:flat@c10}
Free modules are flat; more generally projective modules are flat; and a direct sum
$\bigoplus_i M_i$ is flat iff each $M_i$ is flat. Over $\mathbb{Z}$, a module is flat iff it is
torsion-free.
\end{proposition}

\begin{method}{Detecting flatness / failure of left-exactness}
\textit{Trigger.} You tensor an injection and ask if it stays injective, or must certify a
module flat. \textit{Recipe.}
\begin{enumerate}
\item Free or projective $\Rightarrow$ flat (safe default).
\item Over $\mathbb{Z}$ (or a PID): flat $\iff$ torsion-free. So $\mathbb{Q},\mathbb{Z},\mathbb{Z}^n$ are flat;
$\mathbb{Z}/(n)\mathbb{Z}$ ($n\geq2$) is not.
\item To show non-flatness, tensor the injection $\mathbb{Z}\xrightarrow{\times n}\mathbb{Z}$ with the
module and find a nonzero kernel.
\item Right-exactness always holds: only the left end ($1\otimes\psi$ injective) is at stake.
\end{enumerate}
\end{method}

\begin{wex}{$\mathbb{Z}^n$ is flat}
Problem. Show $\mathbb{Z}^3$ is a flat $\mathbb{Z}$-module.
\wrec Free $\Rightarrow$ flat; tensoring with a free module is taking direct sums of copies.
\wsol For any injection $\iota\colon A\hookrightarrow B$, $\mathbb{Z}^3\otimes_\mathbb{Z} A\cong A^3$ and
$\mathbb{Z}^3\otimes_\mathbb{Z} B\cong B^3$, with $1\otimes\iota$ becoming $\iota^3=(\iota,\iota,\iota)$,
which is injective since each coordinate $\iota$ is. So $\mathbb{Z}^3$ is flat. \textit{Check.}
$\mathbb{Z}^3$ is torsion-free, matching the PID criterion. Correct.
\end{wex}

