\begin{method}{Computing a dual basis}
\textit{Trigger.} A basis $\{v_i\}$ is given and you need the functionals $v_i^{*}$ explicitly, or the coordinates of a given $f$.
\begin{enumerate}
\item Form the matrix $P=[\,v_1\ \cdots\ v_n\,]$ whose columns are the $v_i$ in standard coordinates.
\item The rows of $P^{-1}$ are the dual basis functionals: $v_i^{*}(x)=(\text{$i$th row of }P^{-1})\,x$. (Reason: $v_i^{*}(v_j)=(P^{-1}P)_{ij}=\delta_{ij}$.)
\item To get the coordinates of a functional $f$ in $\{v_i^{*}\}$, just evaluate: $f=\sum_i f(v_i)\,v_i^{*}$.
\end{enumerate}
\end{method}

\begin{wex}{Dual basis on $\mathbb{Q}^2$ for a skew basis}
Find the dual basis to $v_1=(1,1)$, $v_2=(1,2)$ in $\mathbb{Q}^2$, and expand $f(x,y)=3x-y$ in it.
\wrec Theorem~\ref{thm:dualbasis@c11} plus the Method: invert the matrix of basis columns; read off rows.
\wsol Here $P=\begin{pmatrix}1&1\\1&2\end{pmatrix}$, $\det P=1$, $P^{-1}=\begin{pmatrix}2&-1\\-1&1\end{pmatrix}$. So $v_1^{*}(x,y)=2x-y$ and $v_2^{*}(x,y)=-x+y$. Check $\delta$: $v_1^{*}(v_1)=2-1=1$, $v_1^{*}(v_2)=2-2=0$. Now $f(v_1)=3-1=2$, $f(v_2)=3-2=1$, so $f=2\,v_1^{*}+1\,v_2^{*}$. \textit{Check.} $2(2x-y)+(-x+y)=3x-y=f$. Correct.
\end{wex}

\begin{wex}{Dual basis over $\F_2$}
In $V=\F_2^2$ take the basis $v_1=(1,1)$, $v_2=(0,1)$. Compute the dual basis.
\wrec Same inversion recipe; arithmetic is mod $2$, where $-1=1$.
\wsol $P=\begin{pmatrix}1&0\\1&1\end{pmatrix}$, and over $\F_2$, $P^{-1}=\begin{pmatrix}1&0\\1&1\end{pmatrix}$ (since $P^2=I$). Thus $v_1^{*}(x,y)=x$, $v_2^{*}(x,y)=x+y$. \textit{Check.} $v_1^{*}(v_1)=1$, $v_1^{*}(v_2)=0$; $v_2^{*}(v_2)=0+1=1$, $v_2^{*}(v_1)=1+1=0$. The $\delta$-relations hold, so this is the dual basis.
\end{wex}

\begin{wex}{Monomial dual basis and Taylor coordinates}
On $V=\{p\in\mathbb{Q}[x]:\deg p\le 2\}$ with basis $1,x,x^2$, identify the dual basis and recognize it.
\wrec The dual basis extracts coordinates; here coordinates are the Taylor coefficients at $0$.
\wsol Write $p=c_0+c_1x+c_2x^2$. The dual basis $\{1^{*},x^{*},(x^2)^{*}\}$ satisfies $1^{*}(p)=c_0=p(0)$, $x^{*}(p)=c_1=p'(0)$, $(x^2)^{*}(p)=c_2=\tfrac12 p''(0)$. \textit{Check.} $1^{*}(x)=0$, $x^{*}(x)=1$, $(x^2)^{*}(x)=0$, matching $\delta_{ij}$ on the basis. So the dual basis is precisely ``read off the Taylor coefficients,'' i.e.\ $p\mapsto \tfrac{1}{k!}p^{(k)}(0)$.
\end{wex}

\begin{definition}[Double dual]
The \textbf{double dual} of $V$ is $\dual{(\dual{V})}$, written $V^{**}$. Its elements are linear functionals on $\dual{V}$.
\end{definition}

\begin{proof}
\emph{$\mathrm{ev}_v$ is linear in $f$:} $\mathrm{ev}_v(f+g)=(f+g)(v)=f(v)+g(v)$ and $\mathrm{ev}_v(cf)=c f(v)$, so $\mathrm{ev}_v\in V^{**}$. \emph{$\Phi$ is linear in $v$:} $\mathrm{ev}_{v+w}(f)=f(v+w)=f(v)+f(w)=(\mathrm{ev}_v+\mathrm{ev}_w)(f)$, similarly for scalars. \emph{Injective:} if $\Phi(v)=0$ then $f(v)=0$ for all $f\in\dual{V}$; extending $v\ne0$ to a basis and using its dual basis gives a functional with $f(v)=1$, a contradiction, so $v=0$. \emph{Finite-dimensional case:} $\dim V^{**}=\dim\dual{V}=\dim V$ by Theorem~\ref{thm:dualbasis@c11} applied twice, so an injective linear map between equal finite dimensions is an isomorphism.
\end{proof}

\begin{remark}
``Natural'' has a precise meaning: $\Phi$ commutes with all linear maps, so no choices are involved. By contrast the isomorphism $V\cong\dual{V}$ (matching $v_i\mapsto v_i^{*}$) \emph{depends on the chosen basis} and is not natural. The double dual restores naturality. The square below records this naturality: for any linear $T\colon V\to W$, the double-transpose $T^{**}$ makes the evaluation maps commute.
\end{remark}

\begin{wex}{An explicit double-dual element}
On $V=\mathbb{Q}^2$ with standard dual basis $e_1^{*},e_2^{*}$ of $\dual{V}$, write the element $\Phi(v)$ of $V^{**}$ for $v=(3,5)$ in the basis $\{e_1^{**},e_2^{**}\}$ dual to $\{e_1^{*},e_2^{*}\}$.
\wrec $\Phi(v)$ evaluates functionals at $v$; its coordinates in $\{e_i^{**}\}$ are its values on $e_1^{*},e_2^{*}$.
\wsol By Theorem~\ref{thm:dualbasis@c11}, $\Phi(v)=\sum_i \Phi(v)(e_i^{*})\,e_i^{**}=\sum_i e_i^{*}(v)\,e_i^{**}$. Here $e_1^{*}(v)=3$, $e_2^{*}(v)=5$, so $\Phi(v)=3\,e_1^{**}+5\,e_2^{**}$. \textit{Check.} The coordinate vector of $\Phi(v)$ in the double-dual basis is $(3,5)$, identical to $v$ --- the natural iso is the identity in matching bases, as it must be.
\end{wex}

\begin{wex}{$\Phi$ is independent of basis}
Verify on $V=\mathbb{Q}^2$ that $\Phi(v)(f)=f(v)$ gives the same element of $V^{**}$ whether $f$ is expressed in the standard or the skew dual basis of the earlier example.
\wrec Naturality says $\Phi$ uses no basis; the test is that $\mathrm{ev}_v(f)=f(v)$ is computed intrinsically.
\wsol Take $v=(1,1)$ and $f=3x-y$. Directly, $\Phi(v)(f)=f(1,1)=3-1=2$. Using the skew basis $f=2v_1^{*}+v_2^{*}$ (computed earlier) with $v=v_1$, and $v_1^{*}(v_1)=1$, $v_2^{*}(v_1)=v_2^{*}(1,1)=-1+1=0$: $\Phi(v_1)(f)=2\cdot1+1\cdot0=2$. \textit{Check.} Both routes give $2$. The value $f(v)$ does not see the basis, confirming $\Phi$ is natural.
\end{wex}

\begin{wex}{Failure of surjectivity in infinite dimensions}
Let $V$ have countable basis $v_1,v_2,\dots$ over $F$. Exhibit an element of $V^{**}$ not of the form $\Phi(v)$.
\wrec $\Phi$ is always injective but only surjective when $\dim V<\infty$; the obstruction is a functional summing infinitely many dual-basis coordinates.
\wsol Consider $\Theta\in V^{**}$ defined on the (linearly independent) functionals $v_i^{*}$ by $\Theta(v_i^{*})=1$ for all $i$, extended linearly to all of $\dual{V}$. If $\Theta=\Phi(v)$ for some $v=\sum_{i}a_i v_i$ (finite sum), then $\Theta(v_i^{*})=v_i^{*}(v)=a_i$, forcing $a_i=1$ for \emph{all} $i$ --- impossible for a finite combination. \textit{Check.} So $\Theta\notin\im\Phi$, hence $\Phi$ is not surjective. This matches the Remark that $\dim\dual{V}>\dim V$ for infinite-dimensional $V$.
\end{wex}

\begin{wex}{Double transpose recovers $T$}
For $T\colon\mathbb{Q}^2\to\mathbb{Q}^2$, $T(x,y)=(x+2y,\,3x)$, verify the naturality square: $\Phi_W\circ T=T^{**}\circ\Phi_V$ on the vector $v=(1,0)$.
\wrec The square in the Remark must commute; check it on a vector by chasing both paths.
\wsol Top-right path: $T(1,0)=(1,3)$, then $\Phi_W(1,3)=\mathrm{ev}_{(1,3)}$. Down-bottom path: $\Phi_V(1,0)=\mathrm{ev}_{(1,0)}$, then $T^{**}$ precomposes with $T^{*}$, giving $\mathrm{ev}_{(1,0)}\circ T^{*}$. For any $f\in\dual{W}$, $(\mathrm{ev}_{(1,0)}\circ T^{*})(f)=T^{*}(f)(1,0)=f(T(1,0))=f(1,3)=\mathrm{ev}_{(1,3)}(f)$. \textit{Check.} Both paths equal $\mathrm{ev}_{(1,3)}$, so the square commutes at $v$. Correct.
\end{wex}

\begin{proof}
Let $\dim W=k$, $\dim V=n$. Choose a basis $v_1,\dots,v_k$ of $W$ and extend to a basis $v_1,\dots,v_n$ of $V$, with dual basis $v_1^{*},\dots,v_n^{*}$. A functional $f=\sum_i c_i v_i^{*}$ annihilates $W$ iff $f(v_j)=c_j=0$ for $j=1,\dots,k$. Thus $\operatorname{ann}(W)=\Span\{v_{k+1}^{*},\dots,v_n^{*}\}$, which has dimension $n-k$. The restriction map $\dual{V}\to\dual{W}$, $f\mapsto f|_W$, is surjective with kernel exactly $\operatorname{ann}(W)$, giving the short exact sequence below; rank--nullity reproduces the count. The equality $\operatorname{ann}(\operatorname{ann}(W))=W$ follows by applying the dimension formula twice ($\dim\operatorname{ann}(\operatorname{ann}(W))=n-(n-k)=k$) together with the evident inclusion $W\subseteq\operatorname{ann}(\operatorname{ann}(W))$.
\end{proof}

