For finite-dimensional $V$ over $F$ the constructions of this section assemble into one coherent dictionary, all anchored by the natural isomorphism $V\cong V^{**}$:
\begin{itemize}
\item $\dim\dual{V}=\dim V$, with dual basis $v_i^{*}(v_j)=\delta_{ij}$ (Theorem~\ref{thm:dualbasis@c11});
\item $V\xrightarrow{\ \Phi\ }V^{**}$, $\Phi(v)(f)=f(v)$, a basis-free isomorphism (Theorem~\ref{thm:doubledual@c11});
\item $\dim\operatorname{ann}(W)=\dim V-\dim W$ and $\operatorname{ann}(\operatorname{ann}(W))=W$ (Proposition~\ref{prop:ann@c11});
\item $\dual{T}(f)=f\circ T$ has matrix $A\trans$, with $\ker\dual{T}=\operatorname{ann}(\im T)$ and $\rank\dual{T}=\rank T$ (Theorem~\ref{thm:transpose@c11}).
\end{itemize}
The contravariant functor $\Hom_F(-,F)$ ties these together: it sends $V\rightsquigarrow\dual{V}$, $T\rightsquigarrow\dual{T}$, subspaces to their annihilators, and --- applied twice --- returns $V$ to itself.

\begin{exers}{Commutative-diagram exercises.}
\item (Naturality of evaluation.) Let $T \colon V \to W$ be a linear map of finite-dimensional spaces, and let $\mathrm{ev}_V, \mathrm{ev}_W$ be the natural isomorphisms into the double duals. Prove that the diagram
\[
\begin{tikzcd}
V \arrow[r, "T"] \arrow[d, "\mathrm{ev}_V"'] & W \arrow[d, "\mathrm{ev}_W"] \\
\dual{(\dual{V})} \arrow[r, "(T\trans)\trans"'] & \dual{(\dual{W})}
\end{tikzcd}
\]
commutes, i.e. $\mathrm{ev}_W \circ T = (T\trans)\trans \circ \mathrm{ev}_V$. This says the double transpose $(T\trans)\trans$ is identified with $T$ itself under the natural isomorphisms.

\item (Functoriality of the dual on a short exact sequence.) Let
\[
\begin{tikzcd}
0 \arrow[r] & U \arrow[r, hook, "i"] & V \arrow[r, two heads, "p"] & W \arrow[r] & 0
\end{tikzcd}
\]
be a short exact sequence of finite-dimensional $\F$-vector spaces. Prove that applying $\dual{(\,\cdot\,)}$ yields the short exact sequence
\[
\begin{tikzcd}
0 \arrow[r] & \dual{W} \arrow[r, "p\trans"] & \dual{V} \arrow[r, "i\trans"] & \dual{U} \arrow[r] & 0,
\end{tikzcd}
\]
identifying $\im(p\trans) = \ker(i\trans)$ with $\operatorname{Ann}(\ker p) = \operatorname{Ann}(\im i)$.

\item (Universal property of the dual basis pairing.) Let $V$ be finite dimensional with the natural pairing $\langle\,\cdot\,,\,\cdot\,\rangle \colon \dual{V} \times V \to \F$ given by $\langle \varphi, v\rangle = \varphi(v)$. Show that for any linear map $T \colon V \to W$ between finite-dimensional spaces, $T\trans$ is the unique linear map making
\[
\begin{tikzcd}[column sep=large]
\dual{W} \times V \arrow[r, "\id \times T"] \arrow[d, "T\trans \times \id"'] & \dual{W} \times W \arrow[d, "{\langle\,\cdot\,,\,\cdot\,\rangle_W}"] \\
\dual{V} \times V \arrow[r, "{\langle\,\cdot\,,\,\cdot\,\rangle_V}"'] & \F
\end{tikzcd}
\]
commute, i.e. the defining adjunction $\langle T\trans\psi,\, v\rangle_V = \langle \psi,\, Tv\rangle_W$ for all $\psi \in \dual{W}$, $v \in V$.

\item (Annihilator and the quotient.) Let $W \subseteq V$ be a subspace of a finite-dimensional space, with inclusion $i \colon W \hookrightarrow V$ and quotient map $q \colon V \to V/W$. Prove that the natural isomorphism $\operatorname{Ann}(W) \cong \dual{(V/W)}$ fits into the commutative diagram
\[
\begin{tikzcd}
\dual{(V/W)} \arrow[r, "q\trans"] \arrow[d, "\cong"'] & \dual{V} \arrow[d, equal] \\
\operatorname{Ann}(W) \arrow[r, hook] & \dual{V}
\end{tikzcd}
\]
where the bottom arrow is inclusion; deduce $\dim \operatorname{Ann}(W) = \dim V - \dim W$ from $\dim \dual{(V/W)} = \dim(V/W)$.
\end{exers}

\begin{wex}{Leibniz formula over $\F_2$}
In $\Mat_3(\F_2)$ compute $\det A$ for
$A = \begin{psmallmatrix} 1 & 1 & 0 \\ 0 & 1 & 1 \\ 1 & 0 & 1 \end{psmallmatrix}$.
\wrec Theorem~\ref{thm:det-exists@c11}; over $\F_2$ signs are irrelevant since
$-1 = 1$, so $\det A = \sum_\sigma \prod_j a_{\sigma(j)\,j} \pmod 2$.
\wsol The nonzero products: $\sigma=\id$ gives $a_{11}a_{22}a_{33}=1$;
$\sigma=(1\,2\,3)$ gives $a_{21}a_{32}a_{13}$, which is $0\cdot 0 \cdot 0 = 0$;
$\sigma=(1\,3\,2)$ gives $a_{31}a_{12}a_{23}=1\cdot 1\cdot 1 = 1$. The remaining
three permutations all hit a zero entry. Sum $= 1 + 1 = 0$ in $\F_2$.
So $\det A = 0$, i.e. $A$ is singular over $\F_2$. \textit{Sanity check.}
$A_1 + A_2 + A_3 = (1{+}1{+}0,\ 0{+}1{+}1,\ 1{+}0{+}1)^{\trans}
= (0,0,0)^{\trans}$, so the columns are dependent, confirming $\det A = 0$.
\end{wex}

\begin{wex}{Upper triangular: product of the diagonal, over $\mathbb{Q}$}
Compute $\det\begin{psmallmatrix} 2 & 9 & -1 \\ 0 & 3 & 7 \\ 0 & 0 & 5
\end{psmallmatrix}$.
\wrec Leibniz: for an upper-triangular matrix the only permutation giving a
nonzero product is the identity.
\wsol If $a_{ij}=0$ for $i>j$, a term $\prod_j a_{\sigma(j)\,j}\neq 0$ needs
$\sigma(j) \leq j$ for all $j$, forcing $\sigma=\id$. Thus $\det = a_{11}a_{22}a_{33}
= 2\cdot 3\cdot 5 = 30$. \textit{Sanity check.} The matrix is invertible (no zero on
the diagonal), consistent with $\det \neq 0$ (Theorem~\ref{thm:det-invertible@c11}).
\end{wex}

\begin{theorem}[Multiplicativity]
\label{thm:det-mult@c11}
For all $A, B \in \Mat_n(F)$, $\det(AB) = \det(A)\det(B)$. Consequently
$\det(A^k) = (\det A)^k$ and, if $A$ is invertible, $\det(A^{-1}) = (\det A)^{-1}$.
\end{theorem}

\begin{theorem}[Invertibility criterion]
\label{thm:det-invertible@c11}
$A \in \Mat_n(F)$ is invertible if and only if $\det A \neq 0$. Equivalently,
the columns of $A$ are linearly independent iff $\det A \neq 0$. Moreover
$\det(A^{\trans}) = \det A$, so the same holds for rows.
\end{theorem}

\begin{theorem}[Laplace expansion and Cramer's rule]
\label{thm:laplace@c11}
For each fixed column $j$ (resp.\ row $i$),
\[
  \det A = \sum_{i=1}^n (-1)^{i+j} a_{ij}\,\det A_{ij}
         = \sum_{i=1}^n a_{ij}\,c_{ij}
  \qquad\Big(\text{resp. } \det A = \sum_{j=1}^n a_{ij}\,c_{ij}\Big).
\]
Furthermore $A\,(\operatorname{adj} A) = (\operatorname{adj} A)\,A = (\det A)\,I$,
so when $\det A \neq 0$, $A^{-1} = (\det A)^{-1}\operatorname{adj} A$. If
$Ax = b$ with $\det A \neq 0$, then $x_j = \det(A^{(j)})/\det A$, where $A^{(j)}$
replaces column $j$ of $A$ by $b$ (\emph{Cramer's rule}).
\end{theorem}

