Find $A^{-1}$ for $A = \begin{psmallmatrix} 1 & 2 \\ 3 & 4 \end{psmallmatrix}$.
\wrec Theorem~\ref{thm:laplace@c11}: $A^{-1} = (\det A)^{-1}\operatorname{adj} A$.
\wsol $\det A = -2$. Cofactors: $c_{11}=4,\ c_{12}=-3,\ c_{21}=-2,\ c_{22}=1$, so
$\operatorname{adj} A = \begin{psmallmatrix} c_{11} & c_{21} \\ c_{12} & c_{22}
\end{psmallmatrix} = \begin{psmallmatrix} 4 & -2 \\ -3 & 1 \end{psmallmatrix}$.
Hence $A^{-1} = -\tfrac12\begin{psmallmatrix} 4 & -2 \\ -3 & 1 \end{psmallmatrix}
= \begin{psmallmatrix} -2 & 1 \\ 3/2 & -1/2 \end{psmallmatrix}$.
\textit{Sanity check.} $A A^{-1} = \begin{psmallmatrix} 1 & 2 \\ 3 & 4 \end{psmallmatrix}
\begin{psmallmatrix} -2 & 1 \\ 3/2 & -1/2 \end{psmallmatrix}
= \begin{psmallmatrix} 1 & 0 \\ 0 & 1 \end{psmallmatrix}$. \checkmark
\end{wex}

\begin{wex}{Cramer's rule over $\mathbb{Q}$}
Solve $\begin{cases} 2x + y = 5 \\ x + 3y = 6 \end{cases}$ by Cramer's rule.
\wrec Theorem~\ref{thm:laplace@c11} (Cramer's rule).
\wsol $A = \begin{psmallmatrix} 2 & 1 \\ 1 & 3 \end{psmallmatrix}$, $\det A = 5$;
$b = (5,6)^{\trans}$. Then $x = \det\begin{psmallmatrix} 5 & 1 \\ 6 & 3
\end{psmallmatrix}/5 = (15-6)/5 = 9/5$ and
$y = \det\begin{psmallmatrix} 2 & 5 \\ 1 & 6 \end{psmallmatrix}/5 = (12-5)/5 = 7/5$.
\textit{Sanity check.} $2(9/5) + 7/5 = 25/5 = 5$ and $9/5 + 3(7/5) = 30/5 = 6$.
\checkmark
\end{wex}

\begin{wex}{Adjugate identity over $\F_2$}
For $A = \begin{psmallmatrix} 1 & 1 \\ 1 & 0 \end{psmallmatrix}$ over $\F_2$,
verify $A\,\operatorname{adj}A = (\det A) I$ and find $A^{-1}$.
\wrec Theorem~\ref{thm:laplace@c11}; recall $-1 = 1$ in $\F_2$.
\wsol $\det A = 1\cdot 0 - 1\cdot 1 = -1 = 1$. Cofactors:
$c_{11}=0,\ c_{12}=-1=1,\ c_{21}=-1=1,\ c_{22}=1$, so
$\operatorname{adj}A = \begin{psmallmatrix} 0 & 1 \\ 1 & 1 \end{psmallmatrix}$.
Then $A\,\operatorname{adj}A = \begin{psmallmatrix} 1 & 1 \\ 1 & 0 \end{psmallmatrix}
\begin{psmallmatrix} 0 & 1 \\ 1 & 1 \end{psmallmatrix}
= \begin{psmallmatrix} 1 & 0 \\ 0 & 1 \end{psmallmatrix} = (\det A)I$.
Since $\det A = 1$, $A^{-1} = \operatorname{adj}A
= \begin{psmallmatrix} 0 & 1 \\ 1 & 1 \end{psmallmatrix}$.
\textit{Sanity check.} $A^{-1} = A^{-1}$ should satisfy $A^{-1}A = I$:
$\begin{psmallmatrix} 0 & 1 \\ 1 & 1 \end{psmallmatrix}
\begin{psmallmatrix} 1 & 1 \\ 1 & 0 \end{psmallmatrix}
= \begin{psmallmatrix} 1 & 0 \\ 0 & 1 \end{psmallmatrix}$. \checkmark
\end{wex}

\begin{proof}
By Theorem~\ref{thm:det-mult@c11},
$\det(P^{-1}AP) = \det(P^{-1})\det(A)\det(P) = \det(A)$ since
