\begin{pitfall}
The last-column pivot test decides \emph{consistency}, not uniqueness. A system can be consistent yet have infinitely many solutions (free columns of $A'$, as in the underdetermined example), and can be inconsistent regardless of how many free columns $A'$ has. Keep the two columns of bookkeeping separate: a pivot in $B'$ kills all solutions; a free column in $A'$ multiplies the solutions. Also: over a ring that is not a field do not ``divide'' carelessly --- type (iii) scaling requires the pivot entry to be a \emph{unit}, which is automatic in a field but fails for matrices over a mere ring.
\end{pitfall}

\begin{remark}[Bridge to the abstract chapter]
Theorem~\ref{art:matrices:invtfae@c11} is the matrix incarnation of the isomorphism criterion: $A$ invertible $\iff$ the map $T=L_A$ is bijective $\iff$ $\ker T=0$ $\iff$ $\im T=F^n$, the $\dim V=n$ case of rank--nullity. The factorization $A=E_1^{-1}\cdots E_k^{-1}$ says $\GL_n(F)$ is \emph{generated by elementary matrices}, the computational shadow of the structure of $\GL_n$ studied later. Thus the algorithm of this section and the structure theory of \S11.1--11.2 are two views of one object.
\end{remark}

\begin{definition}[Cycle notation]
A \textbf{cycle} $(c_1\,c_2\,\cdots\,c_r)$ denotes the permutation that sends $c_1\mapsto c_2$, $c_2\mapsto c_3$, \dots, $c_{r-1}\mapsto c_r$, and $c_r\mapsto c_1$, fixing all unlisted indices. A $2$-cycle is a \textbf{transposition}. Every permutation is a product of disjoint cycles; one omits $1$-cycles (fixed points), and writes the identity as $1$.
\end{definition}

\begin{remark}
Because $qp=q\circ p$ is read right-to-left, composing cycles takes practice. With $q=(1\,4\,5\,2)$ and $p=(1\,3\,4)(2\,5)$ one follows each index through $p$ first, then $q$: $3\xmapsto{p}4\xmapsto{q}5$, so $qp$ sends $3\mapsto 5$; tracking all indices gives $qp=(1\,3\,5)$, while $pq=(2\,3\,4)$. Composition is \emph{not} commutative.
\end{remark}

\begin{wex}{Multiplying permutations in cycle notation}
With $p=(1\,3\,4)(2\,5)$ and $q=(1\,4\,5\,2)$ in $\Sym_5$, compute $qp$ and confirm $pq\ne qp$.
\wrec Product means compose right-to-left ($qp=q\circ p$); chase each index through $p$ then through $q$.
\wsol Apply $p$ then $q$ to each index: $1\xmapsto{p}3\xmapsto{q}3$; $3\xmapsto{p}4\xmapsto{q}5$; $5\xmapsto{p}2\xmapsto{q}1$; and $2\xmapsto{p}5\xmapsto{q}2$, $4\xmapsto{p}1\xmapsto{q}4$ are fixed. So $qp=(1\,3\,5)$. Reversing the order, $pq$: $1\xmapsto{q}4\xmapsto{p}1$ fixed; $2\xmapsto{q}1\xmapsto{p}3$; $3\xmapsto{q}3\xmapsto{p}4$; $4\xmapsto{q}5\xmapsto{p}2$; so $pq=(2\,3\,4)$. \textit{Check.} $qp=(1\,3\,5)$ moves $1$, but $pq=(2\,3\,4)$ fixes $1$; the two products differ, so $\Sym_5$ is non-abelian.
\end{wex}

\begin{proposition}[Permutation matrices, Artin 1.5.10]\label{art:perm_det:permmat@c11}
Let $p,q\in\Sym_n$ with matrices $P,Q$.
\begin{enumerate}
\item[(a)] A matrix is a permutation matrix iff it has exactly one $1$ in each row and column and $0$ elsewhere.
\item[(b)] $\det P=\pm1$.
\item[(c)] $P_{pq}=P_p P_q$, so $p\mapsto P_p$ is a group homomorphism $\Sym_n\to\GL_n$.
\end{enumerate}
\end{proposition}

\begin{definition}[Sign]
The \textbf{sign} of $p$ is $\operatorname{sgn}(p)=\det P_p\in\{+1,-1\}$. A permutation is \textbf{even} if $\operatorname{sgn}(p)=+1$ and \textbf{odd} if $\operatorname{sgn}(p)=-1$.
\end{definition}

\begin{wex}{Sign by three routes}
Compute $\operatorname{sgn}(p)$ for $p=(1\,3\,4)(2\,5)\in\Sym_5$ using transpositions, cycle lengths, and inversions.
\wrec $\operatorname{sgn}$ is multiplicative; an $r$-cycle has sign $(-1)^{r-1}$; or count inversions of the one-line image.
\wsol \emph{Transpositions:} $(1\,3\,4)=(1\,4)(1\,3)$ (two transpositions, even) and $(2\,5)$ is one transposition (odd), so $\operatorname{sgn}(p)=(+1)(-1)=-1$. \emph{Cycle lengths:} a $3$-cycle has sign $(-1)^{2}=+1$, a $2$-cycle has sign $(-1)^{1}=-1$; product $=-1$. \emph{Inversions:} the one-line image is $(p(1),\dots,p(5))=(3,5,4,1,2)$; counting pairs $i<j$ with $p(i)>p(j)$ gives $7$ inversions, namely $(1,4),(1,5),(2,3),(2,4),(2,5),(3,4),(3,5)$, and $(-1)^7=-1$. \textit{Check.} All three routes give $\operatorname{sgn}(p)=-1$, so $p$ is odd.
\end{wex}

