\begin{theorem}[Complete expansion, Artin 1.6.4]\label{art:perm_det:leibniz@c11}
For an $n\times n$ matrix $A=(a_{ij})$,
\[
\det A=\sum_{p\in\Sym_n}\operatorname{sgn}(p)\,a_{1,p(1)}\,a_{2,p(2)}\cdots a_{n,p(n)}.
\]
\end{theorem}

\begin{pitfall}
The diagonal (``Sarrus'') mnemonic from the block $[\,A\mid A\,]$ works \emph{only} for $3\times3$. For $4\times4$ and larger it is wrong --- the complete expansion has $n!$ terms, not $2n$, and they do not line up along diagonals.
\end{pitfall}

\begin{proof}[Proof sketch]
Group the $n!$ terms of Theorem~\ref{art:perm_det:leibniz@c11} by the value $v=p(i)$ in the chosen row $i$. Factoring out $a_{iv}$ from each group, what remains is a signed sum over permutations of the remaining indices --- precisely $(-1)^{i+v}\det A_{iv}$, the cofactor. (The sign $(-1)^{i+v}$ records the transpositions needed to move entry $(i,v)$ into the corner before deleting its row and column.) Summing over $v$ recovers $\det A$. Applying the result to $A^{\trans}$, whose determinant equals $\det A$, gives the column version.
\end{proof}

\begin{remark}
The $i,j$ entry of the \textbf{cofactor matrix} is $\operatorname{cof}(A)_{ij}=(-1)^{i+j}\det A_{ji}$ (note the transposed indices: it is the $(j,i)$ cofactor $(-1)^{j+i}\det A_{ji}$ in the sense of the proof above). Artin uses the cofactor matrix to write the inverse: $A^{-1}=\det(A)^{-1}\operatorname{cof}(A)$ when $\det A\ne0$. For hand computation, expand along whichever row or column has the most zeros.
\end{remark}

\begin{wex}{Sign from the complete expansion of a single term}
In a $4\times4$ matrix, the complete expansion contains the term $a_{1,2}a_{2,4}a_{3,1}a_{4,3}$. Determine its sign.
\wrec By Theorem~\ref{art:perm_det:leibniz@c11} the coefficient is $\operatorname{sgn}(p)$ where $p$ is the permutation with $p(i)$ equal to the second index of $a_{i,\cdot}$.
\wsol The column indices give $p(1)=2,\,p(2)=4,\,p(3)=1,\,p(4)=3$, i.e.\ $p=(1\,2\,4\,3)$, a single $4$-cycle. A $4$-cycle is a product of $3$ transpositions, so $\operatorname{sgn}(p)=(-1)^{3}=-1$. (Inversion check on $(2,4,1,3)$: pairs $(2,1),(4,1),(4,3)$ are inverted, $3$ inversions, $(-1)^3=-1$.) \textit{Check.} Both the cycle-length rule and the inversion count give $\operatorname{sgn}(p)=-1$, so this term appears with a minus sign in $\det A$.
\end{wex}

\begin{remark}
The complete expansion is mostly of theoretical value: with $n!$ terms it is impractical for large $n$, but it exhibits $\det A$ as a \emph{polynomial} in the $n^2$ entries with coefficients $\pm1$. Hence if each $a_{ij}(t)$ is a differentiable (or polynomial, or continuous) function of a parameter $t$, so is $\det A(t)$ --- a fact used repeatedly when $A$ varies, e.g.\ in computing characteristic polynomials.
\end{remark}

\begin{proposition}[Similar matrices share eigenvalues]\label{art:eigen:similar@c11}
If $A'=P^{-1} A P$ for an invertible $P$, then $A$ and $A'$ have the same eigenvalues.
\end{proposition}

\begin{proof}
Similar matrices represent the same operator $T$ in different bases, and the eigenvalues are an intrinsic feature of $T$: if $A X=\lambda X$ then $A'(P^{-1} X)=P^{-1} A P P^{-1} X=P^{-1}(AX)=\lambda(P^{-1} X)$, and $P^{-1} X\neq 0$. So every eigenvalue of $A$ is one of $A'$, and symmetrically.
\end{proof}

\begin{proposition}[Diagonal matrix $=$ basis of eigenvectors]\label{art:eigen:diagbasis@c11}
The matrix of $T$ in a basis $B=(v_1,\dots,v_n)$ is diagonal if and only if each $v_j$ is an eigenvector. Equivalently, $A\in\Mat_n(F)$ is similar to a diagonal matrix iff $F^n$ has a basis of eigenvectors of $A$.
\end{proposition}

\begin{proof}
If $T(v_j)=\lambda_j v_j$ for all $j$, the $j$th column of $[T]_B$ is $\lambda_j$ in row $j$ and $0$ elsewhere, so $[T]_B=\operatorname{diag}(\lambda_1,\dots,\lambda_n)$. Conversely, if $[T]_B$ is diagonal with entries $\lambda_j$, then reading off column $j$ gives $T(v_j)=\lambda_j v_j$, so each $v_j$ is an eigenvector. The matrix statement is the same fact applied to $T=$ left multiplication by $A$, with $P=[B]$ the change-of-basis matrix.
\end{proof}

\begin{proposition}[Basic facts]\label{art:eigen:charpoly@c11}
Let $p(t)=\det(tI-A)$ for an $n\times n$ matrix $A$.
\begin{enumerate}
\item[(a)] $p(t)$ is a monic polynomial of degree $n$, and the eigenvalues of $T$ are exactly the roots of $p(t)$ in $F$.
\item[(b)] $p(t)$ does not depend on the choice of basis; it is an invariant of $T$.
\item[(c)] $p(t)=t^n-(\tr A)\,t^{n-1}+\cdots+(-1)^n\det A$, where $\tr A$ is the sum of the diagonal entries.
\item[(d)] If $A$ is upper or lower triangular with diagonal entries $a_{11},\dots,a_{nn}$, then $p(t)=(t-a_{11})\cdots(t-a_{nn})$; the diagonal entries are the eigenvalues.
\end{enumerate}
\end{proposition}

\begin{corollary}[Existence over $\mathbb{C}$; trace and determinant]\label{art:eigen:exist@c11}
Let $T$ act on a finite-dimensional space $V\neq\{0\}$.
\begin{enumerate}
\item[(a)] $T$ has at most $n=\dim V$ eigenvalues.
\item[(b)] If $F=\mathbb{C}$, then $T$ has at least one eigenvalue, hence at least one eigenvector.
\item[(c)] If $\lambda_1,\dots,\lambda_n$ are the eigenvalues of a complex $n\times n$ matrix $A$ (with multiplicity), then $\det A=\lambda_1\cdots\lambda_n$ and $\tr A=\lambda_1+\cdots+\lambda_n$.
\end{enumerate}
\end{corollary}

\begin{proof}
(a) Eigenvalues are roots of $p(t)$, which has degree $n$, hence at most $n$ roots. (b) By the Fundamental Theorem of Algebra every complex polynomial of positive degree has a root, so $p(t)$ has a root $\lambda\in\mathbb{C}$, and $\lambda I-A$ is then singular. (c) Over $\mathbb{C}$, $p(t)=(t-\lambda_1)\cdots(t-\lambda_n)$; comparing with the form in Proposition~\ref{art:eigen:charpoly@c11}(c), the coefficient of $t^{n-1}$ gives $\tr A=\sum\lambda_i$ and the constant term gives $(-1)^n\det A=(-1)^n\prod\lambda_i$.
\end{proof}

\begin{wex}{A diagonalizable $2\times 2$ matrix}
Diagonalize $A=\begin{psmallmatrix}3&2\\1&4\end{psmallmatrix}$ over $\mathbb{R}$.
\wrec Two distinct eigenvalues will force a basis of eigenvectors (Proposition~\ref{art:eigen:diagbasis@c11}); compute $p(t)$, then solve $(\lambda I-A)X=0$.
\wsol $p(t)=t^2-(\tr A)t+\det A=t^2-7t+10=(t-5)(t-2)$, so the eigenvalues are $5$ and $2$. For $\lambda=5$: $(5I-A)=\begin{psmallmatrix}2&-2\\-1&1\end{psmallmatrix}$ kills $v_1=(1,1)^{\trans}$. For $\lambda=2$: $(2I-A)=\begin{psmallmatrix}-1&-2\\-1&-2\end{psmallmatrix}$ kills $v_2=(2,-1)^{\trans}$. With $P=[\,v_1\ v_2\,]=\begin{psmallmatrix}1&2\\1&-1\end{psmallmatrix}$ we get $P^{-1} A P=\begin{psmallmatrix}5&0\\0&2\end{psmallmatrix}$. \textit{Check.} $A v_1=(5,5)^{\trans}=5v_1$ and $A v_2=(4,-2)^{\trans}=2v_2$; also $\tr A=7=5+2$ and $\det A=10=5\cdot 2$, matching Corollary~\ref{art:eigen:exist@c11}(c).
\end{wex}

\begin{wex}{A non-diagonalizable $2\times 2$ matrix}
Show the shear $A=\begin{psmallmatrix}1&1\\0&1\end{psmallmatrix}$ is not diagonalizable over any field.
\wrec $A$ is triangular, so its eigenvalues are read off the diagonal (Proposition~\ref{art:eigen:charpoly@c11}(d)); diagonalizability needs a full basis of eigenvectors (Proposition~\ref{art:eigen:diagbasis@c11}).
\wsol Here $p(t)=(t-1)^2$, so the only eigenvalue is $\lambda=1$ (a double root). The eigenvectors solve $(I-A)X=0$, i.e.\ $\begin{psmallmatrix}0&-1\\0&0\end{psmallmatrix}X=0$, forcing the second coordinate to vanish: the eigenspace is the single line $F\cdot(1,0)^{\trans}$, dimension $1$. There is no basis of eigenvectors, so $A$ is not similar to a diagonal matrix. \textit{Check.} If $A=P\operatorname{diag}(1,1)P^{-1}$ held, then $A=I$, which is false. So a repeated eigenvalue with a deficient eigenspace genuinely blocks diagonalization.
\end{wex}

\begin{wex}{Eigenvalues of a triangular $3\times 3$ matrix}
Read off the eigenvalues and find an eigenvector of $A=\begin{psmallmatrix}2&5&-1\\0&3&4\\0&0&2\end{psmallmatrix}$.
\wrec For a triangular matrix the diagonal entries are the eigenvalues, with no determinant expansion needed (Proposition~\ref{art:eigen:charpoly@c11}(d)).
\wsol The diagonal gives $p(t)=(t-2)^2(t-3)$, so the eigenvalues are $2$ (multiplicity $2$) and $3$. For $\lambda=2$, solve $(2I-A)X=0$: the first standard basis vector $e_1=(1,0,0)^{\trans}$ works since the first column of $A$ is $(2,0,0)^{\trans}=2e_1$. \textit{Check.} $A e_1=(2,0,0)^{\trans}=2e_1$, and $\tr A=2+3+2=7=2+2+3$ matches the eigenvalue sum.
\end{wex}

\begin{theorem}[Triangularization over $\mathbb{C}$]\label{art:eigen:triangular@c11}
Let $T$ be a linear operator on a finite-dimensional complex vector space $V$. Then there is a basis of $V$ in which the matrix of $T$ is upper triangular. Equivalently, every complex $n\times n$ matrix $A$ is similar to an upper triangular matrix: there is $P\in\GL_n(\mathbb{C})$ with $P^{-1} A P$ upper triangular.
\end{theorem}

\begin{remark}
The only feature of $\mathbb{C}$ used is that the characteristic polynomial \emph{splits} into linear factors. Hence the same induction proves: over any field $F$, if the characteristic polynomial of $A$ is a product of linear factors in $F$, then $A$ is similar over $F$ to an upper (or lower) triangular matrix. In the induction step one checks that the characteristic polynomial of the block $D$ is $p(t)/(t-\lambda)$, so the splitting hypothesis passes from $A$ to $D$.
\end{remark}

\begin{proposition}[Distinct eigenvalues give independence]\label{art:eigen:indep@c11}
Eigenvectors $v_1,\dots,v_r$ of $T$ belonging to distinct eigenvalues $\lambda_1,\dots,\lambda_r$ are linearly independent.
\end{proposition}

\begin{theorem}[Diagonalizability criterion]\label{art:eigen:diag@c11}
Let $T$ act on an $n$-dimensional space $V$ over $F$.
\begin{enumerate}
\item[(a)] $T$ is diagonalizable iff $V$ has a basis of eigenvectors of $T$.
\item[(b)] If the characteristic polynomial of $T$ has $n$ distinct roots in $F$, then $T$ is diagonalizable.
\end{enumerate}
\end{theorem}

\begin{proof}
(a) is Proposition~\ref{art:eigen:diagbasis@c11}. For (b): the $n$ distinct roots give $n$ eigenvectors, one per eigenvalue, which are independent by Proposition~\ref{art:eigen:indep@c11}; $n$ independent vectors in an $n$-dimensional space form a basis, so (a) applies.
\end{proof}

\begin{pitfall}
Distinct eigenvalues are \emph{sufficient} but not \emph{necessary} for diagonalizability: the identity $I_n$ has the single eigenvalue $1$ yet is already diagonal. The sharp statement (over a field where the characteristic polynomial splits) is that $T$ is diagonalizable iff its \textbf{minimal polynomial} is a product of \emph{distinct} linear factors. Conversely, the shear $\begin{psmallmatrix}1&1\\0&1\end{psmallmatrix}$ has minimal polynomial $(t-1)^2$, with a repeated factor, and is not diagonalizable.
\end{pitfall}

\begin{theorem}[Cayley--Hamilton]\label{art:eigen:ch@c11}
Every square matrix satisfies its own characteristic polynomial: if $p(t)=\det(tI-A)$, then $p(A)=0$.
\end{theorem}

\begin{remark}[The continuity / diagonalizable-dense argument]
Here is a second proof over $\mathbb{C}$. Matrices with $n$ distinct eigenvalues are \emph{dense} in $\Mat_n(\mathbb{C})$: the discriminant of the characteristic polynomial is a polynomial in the entries that is not identically zero, so its non-vanishing locus is dense. For such a diagonalizable $A$, Cayley--Hamilton is immediate --- in an eigenbasis $A$ is $\operatorname{diag}(\lambda_1,\dots,\lambda_n)$ and $p(A)=\operatorname{diag}(p(\lambda_1),\dots,p(\lambda_n))=0$ since each $\lambda_i$ is a root of $p$. The map $A\mapsto p_A(A)$ is a polynomial (hence continuous) function of the entries of $A$, and it vanishes on the dense diagonalizable set, so it vanishes everywhere.
\end{remark}

\begin{wex}{Cayley--Hamilton on a $2\times 2$ matrix}
Verify $p(A)=0$ for $A=\begin{psmallmatrix}3&2\\1&4\end{psmallmatrix}$, and use it to express $A^{-1}$.
\wrec By Theorem~\ref{art:eigen:ch@c11}, $A$ kills $p(t)=t^2-7t+10$; the constant term lets us solve for $A^{-1}$.
\wsol $A^2=\begin{psmallmatrix}11&14\\7&18\end{psmallmatrix}$, so $A^2-7A+10I=\begin{psmallmatrix}11&14\\7&18\end{psmallmatrix}-\begin{psmallmatrix}21&14\\7&28\end{psmallmatrix}+\begin{psmallmatrix}10&0\\0&10\end{psmallmatrix}=\begin{psmallmatrix}0&0\\0&0\end{psmallmatrix}$. From $A^2-7A+10I=0$ we get $A(7I-A)=10I$, hence $A^{-1}=\tfrac{1}{10}(7I-A)=\tfrac{1}{10}\begin{psmallmatrix}4&-2\\-1&3\end{psmallmatrix}$. \textit{Check.} $A\cdot\tfrac{1}{10}\begin{psmallmatrix}4&-2\\-1&3\end{psmallmatrix}=\tfrac{1}{10}\begin{psmallmatrix}10&0\\0&10\end{psmallmatrix}=I$. Correct.
\end{wex}

