\begin{definition}[Orthogonal matrix]
A real $n\times n$ matrix $A$ is \emph{orthogonal} if $A\trans A=I$; equivalently $A$ is invertible with $A^{-1}=A\trans$. The orthogonal matrices form a subgroup $\mathrm{O}(n)\sgr\GL_n(\mathbb{R})$, the \emph{orthogonal group}; those with $\det=1$ form the \emph{special orthogonal group} $\mathrm{SO}(n)\nor\mathrm{O}(n)$, of index $2$.
\end{definition}

\begin{lemma}[Columns are orthonormal]
A matrix $A$ is orthogonal if and only if its columns $A_1,\dots,A_n$ form an orthonormal basis of $\mathbb{R}^n$, i.e.\ $(A_i\cdot A_j)=\delta_{ij}$.
\end{lemma}

\begin{proof}
The $(i,j)$ entry of $A\trans A$ is $A_i\trans A_j=(A_i\cdot A_j)$. Thus $A\trans A=I$ if and only if $(A_i\cdot A_j)=\delta_{ij}$ for all $i,j$, which says exactly that the columns are mutually orthogonal unit vectors.
\end{proof}

\begin{theorem}[Classification of $2\times2$ orthogonal matrices]
Let $A\in\mathrm{O}(2)$.
\begin{enumerate}
\item If $\det A=1$, then $A=R_\theta=\begin{pmatrix}c&-s\\ s&c\end{pmatrix}$ with $c=\cos\theta$, $s=\sin\theta$, for some angle $\theta$. This is counterclockwise rotation through $\theta$; these matrices are $\mathrm{SO}(2)$.
\item If $\det A=-1$, then $A=\begin{pmatrix}c&s\\ s&-c\end{pmatrix}$. Such an $A$ is the reflection of the plane across the line through the origin making angle $\theta/2$ with the $x$-axis.
\end{enumerate}
\end{theorem}

\begin{proof}
The first column of $A$ is a unit vector, so it equals $(c,s)\trans=(\cos\theta,\sin\theta)\trans$ for some $\theta$. The second column is a unit vector orthogonal to the first, and in $\mathbb{R}^2$ there are exactly two such: $(-s,c)\trans$ and $(s,-c)\trans$. The first choice gives $R_\theta$, with $\det R_\theta=c^2+s^2=1$; the second gives $\begin{pmatrix}c&s\\ s&-c\end{pmatrix}$, with determinant $-c^2-s^2=-1$. This exhausts $\mathrm{O}(2)$ and separates the two cases by the sign of the determinant.

For the rotation, $R_\theta(1,0)\trans=(c,s)\trans$ and $R_\theta(0,1)\trans=(-s,c)\trans$ are the standard basis turned counterclockwise by $\theta$. For the reflection $S=\begin{pmatrix}c&s\\ s&-c\end{pmatrix}$ the characteristic polynomial is $t^2-1$, so the eigenvalues are $+1$ and $-1$ with orthogonal eigenvectors; writing a unit vector as $(\cos\alpha,\sin\alpha)\trans$ one finds $S(\cos\alpha,\sin\alpha)\trans=(\cos(\theta-\alpha),\sin(\theta-\alpha))\trans$, which is fixed exactly when $\alpha=\theta/2$. So $S$ fixes the line at angle $\theta/2$ and negates its perpendicular: a reflection across that line.
\end{proof}

\begin{remark}
The map $\theta\mapsto R_\theta$ is a homomorphism $\mathbb{R}\to\mathrm{SO}(2)$ with $R_\theta R_\phi=R_{\theta+\phi}$ and kernel $2\pi\mathbb{Z}$, so $\mathrm{SO}(2)\cong\mathbb{R}/2\pi\mathbb{Z}$ is the circle group: rotations add their angles. A product of two reflections has determinant $(-1)(-1)=1$, hence is a rotation; this is the algebra behind ``two mirrors make a turn.''
\end{remark}

