\begin{wex}{Axis and angle of a $3\times3$ rotation}
Let $M=\begin{pmatrix}0&0&1\\ 1&0&0\\ 0&1&0\end{pmatrix}$. Confirm $M\in\mathrm{SO}(3)$, then find its axis and angle.
\wrec Verify $M\trans M=I$ and $\det M=1$; the axis is the $+1$-eigenvector, and $\theta$ comes from $\tr M=1+2\cos\theta$.
\wsol The columns are $e_2,e_3,e_1$, an orthonormal basis, so $M\trans M=I$; this is an even permutation (a $3$-cycle), so $\det M=1$ and $M\in\mathrm{SO}(3)$. For the axis solve $Mu=u$: the system makes all coordinates equal, so $u=\tfrac{1}{\sqrt3}(1,1,1)\trans$. For the angle, $\tr M=0=1+2\cos\theta$, so $\cos\theta=-\tfrac12$ and $\theta=120^\circ$. Check: $M$ cyclically permutes $e_1\to e_2\to e_3\to e_1$, and $M^3=I$, consistent with a $120^\circ$ turn about the main diagonal $(1,1,1)$.
\end{wex}

\begin{wex}{Recovering the angle but not the axis sign}
A matrix $M\in\mathrm{SO}(3)$ has $\tr M=2$. What is its rotation angle, and why is the axis not pinned down by the trace alone?
\wrec Use $\tr M=1+2\cos\theta$ to solve for $\cos\theta$; remember the spin $(u,\theta)$ equals $(-u,-\theta)$.
\wsol $2=1+2\cos\theta$ gives $\cos\theta=\tfrac12$, so $\theta=\pm60^\circ$. The trace is a similarity invariant and depends only on $\cos\theta$, so it cannot distinguish $\theta$ from $-\theta$ nor select between the two poles $\pm u$; the unsigned angle $60^\circ$ is all the trace sees. Check: rotations by $+60^\circ$ about $u$ and by $-60^\circ$ about $u$ (equivalently $+60^\circ$ about $-u$) both have trace $2$ but are inverse to each other, confirming the trace alone is blind to orientation. To fix the axis one solves $Mu=u$.
\end{wex}

\begin{pitfall}
The trace gives only $\cos\theta$, hence the angle up to sign. Orthogonality alone is weaker still: $\det=-1$ orthogonal matrices (improper rotations, reflections, rotary reflections) are \emph{not} rotations. Always check $\det=+1$ before invoking Euler's theorem, and find the axis by solving $(M-I)u=0$ rather than guessing from the trace.
\end{pitfall}

\begin{theorem}[Convergence and derivative; Artin 5.4.4]\label{art:matexp:main@c11}
Let $A\in\Mat_n(\mathbb{C})$.
\begin{enumerate}
\item[(a)] The series for $e^{tA}$ converges absolutely, and uniformly on every bounded set of $t$.
\item[(b)] $e^{tA}$ is a differentiable function of $t$, with $\frac{d}{dt}e^{tA}=Ae^{tA}=e^{tA}A$.
\item[(c)] If $A,B\in\Mat_n(\mathbb{C})$ commute, $AB=BA$, then $e^{A+B}=e^{A}e^{B}$.
\end{enumerate}
\end{theorem}

\begin{corollary}[Artin 5.4.5]
For every $A\in\Mat_n(\mathbb{C})$ the matrix $e^{A}$ is invertible, with inverse $e^{-A}$.
\end{corollary}

\begin{proof}
$A$ and $-A$ commute, so part (c) gives $e^{A}e^{-A}=e^{A+(-A)}=e^{0}=\id$, and likewise $e^{-A}e^{A}=\id$.
\end{proof}

\begin{pitfall}
The law $e^{A+B}=e^{A}e^{B}$ \emph{requires} $AB=BA$. For $A=\begin{psmallmatrix}0&1\\0&0\end{psmallmatrix}$ and $B=\begin{psmallmatrix}0&0\\1&0\end{psmallmatrix}$ one has $AB\ne BA$, and indeed $e^{A}e^{B}=\begin{psmallmatrix}1&1\\0&1\end{psmallmatrix}\begin{psmallmatrix}1&0\\1&1\end{psmallmatrix}=\begin{psmallmatrix}2&1\\1&1\end{psmallmatrix}$, whereas $e^{B}e^{A}=\begin{psmallmatrix}1&1\\1&2\end{psmallmatrix}$, so the two products even disagree with each other --- neither can equal the symmetric quantity $e^{A+B}$.
\end{pitfall}

\begin{theorem}[Fundamental matrix; Artin 5.4.9]\label{art:matexp:basis@c11}
Let $A\in\Mat_n(\mathbb{C})$. The columns of $e^{tA}$ form a basis of the solution space of $\frac{dX}{dt}=AX$. Equivalently, every solution is $X(t)=e^{tA}C$ for a unique constant vector $C\in\mathbb{C}^n$; the initial condition $X(0)=X_0$ forces $C=X_0$.
\end{theorem}

\begin{method}{Computing $e^{tA}$.}
The series is rarely summed directly. Instead:
\begin{itemize}
\item \textbf{Diagonal:} if $A=\operatorname{diag}(\lambda_1,\dots,\lambda_n)$ then $e^{tA}=\operatorname{diag}(e^{\lambda_1 t},\dots,e^{\lambda_n t})$, read straight off the series.
\item \textbf{Diagonalizable:} if $P^{-1}AP=D$ is diagonal, then $A^k=PD^kP^{-1}$, so $e^{tA}=Pe^{tD}P^{-1}$. (Conjugation commutes with the whole series.)
\item \textbf{Jordan block:} if $A=\lambda\id+N$ with $N$ nilpotent ($N^k=0$), then since $\lambda\id$ and $N$ commute, $e^{tA}=e^{\lambda t}e^{tN}$ and $e^{tN}=\id+tN+\cdots+\frac{t^{k-1}}{(k-1)!}N^{k-1}$ is a \emph{finite} sum.
\item \textbf{Complex eigenvalues:} a pair $\lambda=r\pm si$ contributes real solutions through $e^{(r+si)t}=e^{rt}(\cos st+i\sin st)$; take real and imaginary parts.
\end{itemize}
\end{method}

