\begin{theorem}[Hermitian eigenvalues are real, Artin 8.3.11]
The eigenvalues, trace, and determinant of a Hermitian matrix $A$ are real. In particular the eigenvalues of a real symmetric matrix are real.
\end{theorem}

\begin{remark}[Unitary change preserves the standard form]
A complex matrix $P$ with $P^{*}P=I$ is \emph{unitary}; equivalently its columns are orthonormal for the standard Hermitian form. Under $\mathcal{B}'=\mathcal{B}P$ the standard form $X^{*}Y$ becomes $X'^{*}(P^{*}P)Y'$, which equals $X'^{*}Y'$ exactly when $P$ is unitary. Thus a change of basis of $\mathbb{C}^n$ preserves the standard Hermitian form iff the change-of-basis matrix is unitary --- the complex analogue of orthogonal matrices preserving dot product on $\mathbb{R}^n$. The unitary matrices form a group $\mathrm{U}(n)\sgr\mathrm{GL}_n(\mathbb{C})$.
\end{remark}

\begin{remark}
When the form is indefinite a \emph{nonzero} vector can be self-orthogonal: $\langle v,v\rangle=0$ with $v\ne 0$ (a \textbf{null vector} of the form is one orthogonal to \emph{all} of $V$). For the Lorentz form on $\mathbb{R}^4$, $(1,0,0,1)$ is self-orthogonal (but it is not a null vector: the Lorentz form is nondegenerate). So one should resist reading $\perp$ as a metric angle in general and work algebraically with the bare condition $\langle v,w\rangle=0$.
\end{remark}

\begin{definition}[Nullspace and nondegeneracy]
The \textbf{nullspace} of the form is $N=V^{\perp}=\{v\in V:\langle v,V\rangle=0\}$, the set of null vectors. The form is \textbf{nondegenerate} if $N=\{0\}$, i.e.\ for every $v\ne 0$ there is some $v'$ with $\langle v,v'\rangle\ne 0$; otherwise it is \textbf{degenerate}. The form is nondegenerate \emph{on a subspace} $W$ if its restriction to $W$ is nondegenerate.
\end{definition}

\begin{proposition}[Matrix criterion for nondegeneracy]\label{art:orthogonality:nondeg@c11}
With $A$ the matrix of the form in a basis: \emph{(a)} $v$ is a null vector iff its coordinate vector $Y$ solves $AY=0$; \emph{(b)} the form is nondegenerate iff $A$ is invertible.
\end{proposition}

\begin{proof}
If $AY=0$ then $X^{*}AY=0$ for all $X$, so $v$ is orthogonal to every vector, hence null. Conversely if $AY\ne 0$ then some coordinate $e_i^{*}AY=(AY)_i$ is nonzero, so $v$ is not orthogonal to that basis vector and is not null. This is (a). Since $A$ is invertible iff $AY=0$ has only the trivial solution, (b) follows from (a).
\end{proof}

\begin{proposition}[Testing equality through the form]\label{art:orthogonality:cancel@c11}
If the form is nondegenerate and $\langle v,w\rangle=\langle v',w\rangle$ for \emph{all} $w\in V$, then $v=v'$.
\end{proposition}

\begin{proof}
The hypothesis says $\langle v-v',w\rangle=0$ for all $w$, so $v-v'$ is a null vector. Nondegeneracy forces $v-v'=0$.
\end{proof}

\begin{wex}{Reading off the nullspace from the matrix}
Let $V=\mathbb{R}^3$ with the form whose matrix in the standard basis is $A=\begin{pmatrix}1&0&1\\0&1&0\\1&0&1\end{pmatrix}$. Find the nullspace and decide whether the form is nondegenerate.
\wrec By Proposition~\ref{art:orthogonality:nondeg@c11}, the nullspace is $\ker A$ and the form is nondegenerate iff $\det A\ne 0$.
\wsol Row reduction gives $\det A=1\cdot(1-0)-0+1\cdot(0-1)=0$, so $A$ is singular and the form is \emph{degenerate}. Solving $AY=0$: rows $1$ and $3$ both say $y_1+y_3=0$, and row $2$ says $y_2=0$. Thus $N=\Span\{(1,0,-1)\}$, a line of null vectors. \textit{Check.} $\langle(1,0,-1),(x_1,x_2,x_3)\rangle$ is the first-minus-third entry of $A(x_1,x_2,x_3)\trans$ paired suitably; directly $A(1,0,-1)\trans=(0,0,0)\trans$, confirming $(1,0,-1)\in N$. Correct.
\end{wex}

\begin{lemma}[Nondegeneracy on $W$ as a trivial intersection]\label{art:orthogonality:lemma@c11}
The form is nondegenerate on $W$ if and only if $W\cap W^{\perp}=\{0\}$.
\end{lemma}

\begin{proof}
A vector $w\in W$ lies in $W^{\perp}$ iff $\langle w,w'\rangle=0$ for all $w'\in W$, i.e.\ iff $w$ is a null vector of the restricted form. So $W\cap W^{\perp}$ is the nullspace of the restriction, which is $\{0\}$ exactly when the restriction is nondegenerate.
\end{proof}

\begin{theorem}[Orthogonal direct sum]\label{art:orthogonality:split@c11}
Let $W\sgr V$.
\begin{enumerate}
\item The form is nondegenerate on $W$ if and only if $V=W\oplus W^{\perp}$.
\item If the form is nondegenerate on $V$ and on $W$, then it is nondegenerate on $W^{\perp}$.
\end{enumerate}
When $V=W\oplus W^{\perp}$ with $W\perp W^{\perp}$ we call it the \textbf{orthogonal sum} of the two pieces.
\end{theorem}

\begin{proof}
\emph{(1)} A direct sum requires $W\cap W^{\perp}=\{0\}$ and $V=W+W^{\perp}$. The first is precisely nondegeneracy on $W$ by Lemma~\ref{art:orthogonality:lemma@c11}, so it remains to produce, assuming nondegeneracy on $W$, a decomposition $v=w+u$ with $w\in W$, $u\in W^{\perp}$ for every $v$. Extend a basis $w_1,\dots,w_k$ of $W$ to a basis of $V$ and write the matrix of the form in block form $M=\begin{psmallmatrix}A&B\\ B^{*}&D\end{psmallmatrix}$, where $A$ is the $k\times k$ matrix of the form on $W$. Nondegeneracy on $W$ makes $A$ invertible. Change the appended basis vectors by $P=\begin{psmallmatrix}I&Q\\0&I\end{psmallmatrix}$; the new matrix is $P^{*}MP$, whose upper-right block becomes $0$ exactly when $Q=-A^{-1}B$. The new appended vectors are then orthogonal to all of $W$, hence lie in $W^{\perp}$, and together with $W$ they span $V$. So $V=W+W^{\perp}$.

\emph{(2)} By (1), $V=W\oplus W^{\perp}$, and in a basis adapted to this splitting the matrix of the form is block-diagonal $\operatorname{diag}(A,A')$ with $A$ the matrix on $W$ and $A'$ the matrix on $W^{\perp}$. Since the form is nondegenerate on $V$, this block-diagonal matrix is invertible, so each block is invertible; in particular $A'$ is, and the form is nondegenerate on $W^{\perp}$.
\end{proof}

\begin{theorem}[Existence of an orthogonal basis]\label{art:orthogonality:orthobasis@c11}
Every symmetric form on a real space, or Hermitian form on a complex space, admits an orthogonal basis.
\end{theorem}

\begin{proof}
If the form is identically zero every basis is orthogonal. Otherwise there is a vector with $\langle v_1,v_1\rangle\ne 0$: indeed if $\langle x,y\rangle\ne 0$ then expanding $\langle x+y,x+y\rangle=\langle x,x\rangle+2\operatorname{Re}\langle x,y\rangle+\langle y,y\rangle$ (after scaling $y$ to make $\langle x,y\rangle$ real and nonzero) shows one of the diagonal terms is nonzero. Let $W=\Span\{v_1\}$; the $1\times 1$ matrix $(\langle v_1,v_1\rangle)$ is invertible, so the form is nondegenerate on $W$, and by Theorem~\ref{art:orthogonality:split@c11}, $V=W\oplus W^{\perp}$. By induction $W^{\perp}$ has an orthogonal basis $v_2,\dots,v_n$, and $v_1,\dots,v_n$ is then an orthogonal basis of $V$.
\end{proof}

\begin{definition}[Orthogonal projection]
The \textbf{orthogonal projection} onto $W$ is the linear map $\pi\colon V\to W$, $\pi(v)=w$, where $v=w+u$ is the decomposition above. Equivalently $\pi$ is the unique linear map with $\pi(w)=w$ for $w\in W$ and $\pi(u)=0$ for $u\in W^{\perp}$.
\end{definition}

\begin{pitfall}
If the form is \emph{degenerate} on $W$ the projection does not exist: by Lemma~\ref{art:orthogonality:lemma@c11} there is a nonzero $x\in W\cap W^{\perp}$, and we would need both $\pi(x)=x$ (as $x\in W$) and $\pi(x)=0$ (as $x\in W^{\perp}$). Always check nondegeneracy on $W$ before projecting.
\end{pitfall}

\begin{theorem}[Projection formula]\label{art:orthogonality:projform@c11}
Let the form be nondegenerate on $W$ and let $w_1,\dots,w_k$ be an \emph{orthogonal} basis of $W$. Then the orthogonal projection of $v$ onto $W$ is
\[
\pi(v)\;=\;\sum_{i=1}^{k} c_i\,w_i,\qquad c_i=\frac{\langle w_i,v\rangle}{\langle w_i,w_i\rangle}.
\]
\end{theorem}

\begin{pitfall}
The projection formula is \emph{false} if the spanning vectors of $W$ are not mutually orthogonal --- the cross terms $\langle w_i,w_j\rangle$ no longer drop out. Orthogonalize first (next subsection).
\end{pitfall}

\begin{wex}{Projection onto a line in $\mathbb{R}^3$}
With the dot product on $V=\mathbb{R}^3$, let $W=\Span\{w_1\}$, $w_1=(1,1,1)\trans$. Project $v=(x_1,x_2,x_3)\trans$ onto $W$.
\wrec One orthogonal basis vector; apply Theorem~\ref{art:orthogonality:projform@c11} with a single term.
\wsol $\langle w_1,v\rangle=x_1+x_2+x_3$ and $\langle w_1,w_1\rangle=3$, so $\pi(v)=c\,w_1$ with $c=\tfrac{x_1+x_2+x_3}{3}$. Concretely $\pi(v)=\tfrac{x_1+x_2+x_3}{3}(1,1,1)\trans$. \textit{Check.} $v-\pi(v)$ should lie in $W^{\perp}$: $\langle w_1,v-\pi(v)\rangle=(x_1+x_2+x_3)-3c=0$. Correct.
\end{wex}

