\begin{method}{Gram--Schmidt: turn any basis into an orthonormal one}
\textit{Trigger.} A positive-definite form and a basis $v_1,\dots,v_n$; you want an orthonormal basis spanning the same flags $V_k=\Span\{v_1,\dots,v_k\}$.
\begin{enumerate}
\item Set $u_1=v_1$, then $w_1=u_1/\abs{u_1}$.
\item Having orthonormal $w_1,\dots,w_{k-1}$ for $V_{k-1}$, subtract the projection: $u_k=v_k-\sum_{i=1}^{k-1}\langle w_i,v_k\rangle\,w_i$ (denominators are $1$ since the $w_i$ are normalized). Then $u_k\perp V_{k-1}$.
\item Normalize: $w_k=u_k/\abs{u_k}$. After $n$ steps $w_1,\dots,w_n$ is orthonormal and $\Span\{w_1,\dots,w_k\}=V_k$ for each $k$.
\end{enumerate}
\end{method}

\begin{corollary}[Gram--Schmidt procedure]\label{art:orthogonality:gs@c11}
Every Euclidean or Hermitian space has an orthonormal basis; the Method above produces one from any starting basis, with $w_k=u_k/\abs{u_k}$ and $u_k=v_k-\pi_{V_{k-1}}(v_k)$.
\end{corollary}

\begin{proof}
By the projection formula (Theorem~\ref{art:orthogonality:projform@c11}) with the orthonormal basis $w_1,\dots,w_{k-1}$ of $V_{k-1}$, the vector $\pi_{V_{k-1}}(v_k)=\sum_{i<k}\langle w_i,v_k\rangle w_i$, so $u_k=v_k-\pi_{V_{k-1}}(v_k)$ lies in $V_{k-1}^{\perp}$ and is nonzero because $v_k\notin V_{k-1}$. Positive definiteness gives $\abs{u_k}>0$, so $w_k$ is defined and is a unit vector orthogonal to $w_1,\dots,w_{k-1}$. By induction the whole set is orthonormal and spans the same flag.
\end{proof}

\begin{wex}{Length and angle from the form}
In a Euclidean space, $\langle v,w\rangle=\abs{v}\,\abs{w}\cos\theta$ defines the angle $\theta$. Find the angle between $v=(1,1,0)\trans$ and $w=(1,0,1)\trans$ in $\mathbb{R}^3$.
\wrec Restricting the form to $\Span\{v,w\}$ makes it a $2$-dimensional Euclidean space, where the form reads as the dot product and the law of cosines $\langle v,w\rangle=\abs v\abs w\cos\theta$ holds.
\wsol $\langle v,w\rangle=1$, $\abs v=\abs w=\sqrt2$, so $\cos\theta=\tfrac{1}{\sqrt2\cdot\sqrt2}=\tfrac12$, giving $\theta=60^{\circ}$. \textit{Check.} $\cos\theta=\tfrac12\in[-1,1]$, consistent with the Cauchy--Schwarz bound $\abs{\langle v,w\rangle}\le\abs v\abs w$ that positive definiteness guarantees; here $1\le 2$. Correct.
\end{wex}

\begin{remark}
One often keeps the \emph{orthogonal} (unnormalized) basis $u_1,\dots,u_n$ rather than the orthonormal one: normalizing requires extracting square roots like $\sqrt2,\sqrt6$, which leaves the field $\mathbb{Q}$, whereas the projection formula already works over any nondegenerate form using the denominators $\langle u_i,u_i\rangle$. The orthonormal basis is the right object only when one genuinely wants lengths and the standard form $\langle v,w\rangle=X^{*}Y$.
\end{remark}

\begin{proposition}[Orthogonal complements of invariant subspaces]\label{art:spectral:invcomp@c11}
Let $W$ be a subspace of $V$. If $W$ is $T$-invariant ($TW\subseteq W$), then
$W^{\perp}$ is $\dual{T}$-invariant. If $W$ is $\dual{T}$-invariant, then
$W^{\perp}$ is $T$-invariant.
\end{proposition}

\begin{theorem}[Shared eigenvectors]\label{art:spectral:shared@c11}
Let $T$ be normal on a Hermitian space $V$, and let $v$ be an eigenvector of $T$
with eigenvalue $\lambda$. Then $v$ is an eigenvector of $\dual{T}$ with
eigenvalue $\overline{\lambda}$.
\end{theorem}

\begin{theorem}[Spectral Theorem for normal operators]\label{art:spectral:main@c11}
Let $T$ be a normal operator on a Hermitian space $V$.
\begin{enumerate}
\item[(a)] There is an orthonormal basis of $V$ consisting of eigenvectors of $T$.
\item[(b)] (Matrix form) If $A$ is a normal matrix, there is a unitary matrix $P$
  such that $\dual{P}AP$ is diagonal.
\end{enumerate}
\end{theorem}

\begin{corollary}[Hermitian operators have real eigenvalues]\label{art:spectral:herm@c11}
Let $T$ be Hermitian ($\dual{T}=T$). Then $V$ has an orthonormal basis of
eigenvectors, and every eigenvalue of $T$ is real. In matrix form: a Hermitian
matrix $A$ admits a unitary $P$ with $\dual{P}AP$ a \emph{real} diagonal matrix.
\end{corollary}

\begin{corollary}[Unitary operators: eigenvalues on the unit circle]\label{art:spectral:unit@c11}
Let $T$ be unitary ($\dual{T}T=\id$). Then $V$ has an orthonormal basis of
eigenvectors, and every eigenvalue satisfies $|\lambda|=1$. In matrix form: a
unitary matrix $A$ admits a unitary $P$ with $\dual{P}AP$ diagonal, each diagonal
entry of absolute value $1$.
\end{corollary}

\begin{proof}
A unitary operator is normal, so we have the eigenbasis. If $Tv=\lambda v$ with
$\|v\|=1$, then by part (d) the form is preserved:
$1=\langle v,v\rangle=\langle Tv,Tv\rangle=\langle\lambda v,\lambda v\rangle
=\lambda\overline{\lambda}\,\langle v,v\rangle=|\lambda|^{2}$, so $|\lambda|=1$.
\end{proof}

