\begin{definition}[The real classical groups]
Inside $\GL_n=\GL_n(R)$ or $\GL_n(C)$ one singles out:
\begin{enumerate}
\item[(SL)] the special linear group $\SL_n=\{P\in\GL_n(R) : \det P=1\}$;
\item[(O)] the orthogonal group $O_n=\{P\in\GL_n(R) : P\trans P=I\}$;
\item[(U)] the unitary group $U_n=\{P\in\GL_n(C) : \dual{P}P=I\}$;
\item[(Sp)] the symplectic group $Sp_{2n}=\{P\in\GL_{2n}(R) : P\trans S\,P=S\}$, where $S=\begin{psmallmatrix}0&I_n\\-I_n&0\end{psmallmatrix}$ is the standard skew-symmetric form on $R^{2n}$.
\end{enumerate}
Adding the word special imposes $\det P=1$ in addition: the special orthogonal group $SO_n=O_n\cap\SL_n$ and the special unitary group $SU_n=U_n\cap\{\det P=1\}$.
\end{definition}

