\begin{pitfall}
Do not confuse the orthogonal relation $P\trans P=I$ (real) with the unitary relation $\dual{P}P=I$ (complex): forgetting to conjugate when computing $\dual{P}$ is the most common error in a unitary membership check. Likewise, ``$\det P=\pm1$'' for orthogonal matrices does \emph{not} say $P\in\mathrm{SO}_n$; the reflection $\begin{psmallmatrix}1&0\\0&-1\end{psmallmatrix}$ is orthogonal with $\det=-1$, so it lies in $\mathrm{O}_2\setminus\mathrm{SO}_2$.
\end{pitfall}

\begin{definition}[The special unitary group $\mathrm{SU}(2)$]
$\mathrm{SU}(2)$ consists of the complex $2\times 2$ matrices $P$ satisfying $P^{*}P=I$ and $\det P=1$, where $P^{*}=\overline{P}\trans$ is the conjugate transpose.
\end{definition}

\begin{proof}
Write $P=\begin{psmallmatrix} a & b\\ u & v\end{psmallmatrix}$ with $a,b,u,v\in\mathbb{C}$. When $\det P=1$ the relation $P^{*}=P^{-1}$ reads
\[
\begin{pmatrix}\overline{a}&\overline{u}\\ \overline{b}&\overline{v}\end{pmatrix}
=\begin{pmatrix}\phantom{-}v & -b\\ -u & \phantom{-}a\end{pmatrix},
\]
since for a $2\times 2$ matrix of determinant $1$ the inverse is $\begin{psmallmatrix} v & -b\\ -u & a\end{psmallmatrix}$. Comparing entries gives $v=\overline{a}$ and $u=-\overline{b}$, and then $\det P=av-bu=a\overline{a}+b\overline{b}=1$. The converse is the same computation read backwards.
\end{proof}

\begin{remark}
That $S^3$ carries a continuous group law is special: there is no way to make $S^2$ a topological group, and a theorem of topology says the only spheres of positive dimension admitting continuous group laws are $S^1$ and $S^3$ (the $0$-sphere $S^0=\{\pm1\}$ is the group of order $2$). The norm $\abs{a}^2+\abs{b}^2=\det P$ is multiplicative, which is why unit quaternions are closed under multiplication.
\end{remark}

\begin{lemma}[Eigenvalues]\label{art:su2so3:eig@c11}
For $P\in\mathrm{SU}(2)$ with $P\ne\pm I$, the eigenvalues are complex conjugates of absolute value $1$. The characteristic polynomial is $t^2-(\tr P)\,t+1=t^2-2x_0 t+1$.
\end{lemma}

\begin{proof}
$\det P=1$ gives the constant term $1$, and $\tr P=2x_0$ the linear term. The discriminant is $4x_0^2-4\le 0$ since $-1\le x_0\le 1$ on the sphere, so the roots are conjugate; their product is $\det P=1$, so each has absolute value $1$.
\end{proof}

\begin{proposition}[Latitudes are conjugacy classes]\label{art:su2so3:lat@c11}
For $-1<c<1$ the latitude $\{x_0=c\}=\{P\in\mathrm{SU}(2)\st \tr P=2c\}$ is a single conjugacy class. The remaining classes are the singletons $\{I\}$ and $\{-I\}$, which together form the center $Z=\{\pm I\}$.
\end{proposition}

\begin{proof}
Trace is a conjugacy invariant, so each class lies in one latitude. Conversely, let $P$ have eigenvalues $\lambda,\overline{\lambda}$. Choose a unit eigenvector and complete it to an orthonormal eigenbasis; the change-of-basis matrix $Q$ can be normalized to lie in $\mathrm{SU}(2)$, and then $Q^{*}PQ=\operatorname{diag}(\lambda,\overline{\lambda})$. Two elements with the same trace have the same eigenvalue pair, hence are both conjugate to the same diagonal matrix, hence to each other. The extreme traces $\tr P=\pm 2$ force $P=\pm I$, which are central.
\end{proof}

\begin{proposition}[The equator squares to $-I$]\label{art:su2so3:eqsq@c11}
For $A\in\mathrm{SU}(2)$ the following are equivalent: (i) $A\in E$, i.e.\ $\tr A=0$; (ii) the eigenvalues of $A$ are $i$ and $-i$; (iii) $A^2=-I$.
\end{proposition}

\begin{proof}
(i)$\Leftrightarrow$(ii): the characteristic polynomial $t^2-(\tr A)t+1$ has roots $\pm i$ iff $\tr A=0$. (ii)$\Rightarrow$(iii): if $\lambda$ is an eigenvalue of $A$ then $\lambda^2$ is one of $A^2$; here $\lambda=\pm i$ gives $\lambda^2=-1$, and the only $\mathrm{SU}(2)$ matrix with eigenvalue $-1$ is $-I$, so $A^2=-I$. (iii)$\Rightarrow$(ii): $A^2=-I$ forces each eigenvalue to satisfy $\lambda^2=-1$, so $\lambda=\pm i$, and $\det A=1$ pairs them as $i,-i$.
\end{proof}

\begin{remark}
Two longitudes are familiar groups. The longitude $L_{\mathbf{i}}=\{cI+s\mathbf{i}\}$ is the group $T$ of diagonal matrices $\operatorname{diag}(e^{i\theta},e^{-i\theta})$. The longitude $L_{\mathbf{j}}=\{cI+s\mathbf{j}\}$ is the group of \emph{real} matrices in $\mathrm{SU}(2)$, namely $\mathrm{SO}(2)$ itself, with $cI+s\mathbf{j}$ representing rotation through $-\theta$.
\end{remark}

\begin{wex}{A longitude is a one-parameter circle subgroup}
Verify directly that $T=\{\operatorname{diag}(e^{i\theta},e^{-i\theta})\st\theta\in\mathbb{R}\}$ is the longitude $L_{\mathbf{i}}$ and is closed under multiplication.
\wrec By Proposition~\ref{art:su2so3:long@c11} a longitude is $cI+sA$ with $A\in E$; for $A=\mathbf{i}$ we recognize the diagonal torus.
\wsol Compute $(\cos\theta)I+(\sin\theta)\mathbf{i}=\begin{psmallmatrix}\cos\theta+i\sin\theta & 0\\ 0 & \cos\theta-i\sin\theta\end{psmallmatrix}=\operatorname{diag}(e^{i\theta},e^{-i\theta})$, so $L_{\mathbf{i}}=T$. Multiplying, $\operatorname{diag}(e^{i\theta},e^{-i\theta})\operatorname{diag}(e^{i\phi},e^{-i\phi})=\operatorname{diag}(e^{i(\theta+\phi)},e^{-i(\theta+\phi)})$. \textit{Check.} The product sits at angle $\theta+\phi$, matching the addition law $\theta\mapsto\theta+\phi$ of Proposition~\ref{art:su2so3:long@c11}; and $\mathbf{i}^2=\operatorname{diag}(i,-i)^2=\operatorname{diag}(-1,-1)=-I$ as required.
\end{wex}

\begin{lemma}[Trace recovers the dot product]\label{art:su2so3:trace@c11}
For $U,V\in V$ with coordinates in the basis $(\mathbf{i},\mathbf{j},\mathbf{k})$, the Euclidean inner product is
\[
\langle U,V\rangle=-\tfrac12\tr(UV).
\]
\end{lemma}

\begin{lemma}[$\gamma_P$ is a rotation]\label{art:su2so3:rot@c11}
For every $P\in\mathrm{SU}(2)$, $\gamma_P$ is an orthogonal operator on $V$ with $\det\gamma_P=1$, hence a rotation.
\end{lemma}

\begin{proof}
\emph{Homomorphism:} $\gamma_P(\gamma_Q U)=P(QUQ^{*})P^{*}=(PQ)U(PQ)^{*}=\gamma_{PQ}(U)$, so $\gamma_P\gamma_Q=\gamma_{PQ}$. By Lemma~\ref{art:su2so3:rot@c11} the image lies in $\mathrm{SO}(3)$.

\emph{Kernel:} if $\gamma_P=\mathrm{id}$ then $PUP^{*}=U$, i.e.\ $P$ commutes with every $U\in E$. Every element of $\mathrm{SU}(2)$ has the form $cI+sB$ with $B\in E$, so $P$ commutes with all of $\mathrm{SU}(2)$, forcing $P\in Z=\{\pm I\}$. Conversely $\pm I$ are central, so $\gamma_{\pm I}=\mathrm{id}$. Thus $\ker\gamma=\{\pm I\}$ and $\gamma_P=\gamma_{-P}$.

\emph{Angle, surjectivity:} a rotation's angle is a conjugacy invariant of $\mathrm{SO}(3)$ and $\theta$ is a conjugacy invariant of $\mathrm{SU}(2)$ (Proposition~\ref{art:su2so3:lat@c11}), so it suffices to compute one representative per class. Take $P=(\cos\theta)I+(\sin\theta)\mathbf{i}=\operatorname{diag}(e^{i\theta},e^{-i\theta})$. Then $\gamma_P\mathbf{i}=P\mathbf{i}P^{*}=\mathbf{i}$, so $\mathbf{i}$ is the pole, and
\[
\gamma_P\mathbf{j}=P\mathbf{j}P^{*}
=\begin{pmatrix}e^{i\theta}&0\\0&e^{-i\theta}\end{pmatrix}\!\begin{pmatrix}0&1\\-1&0\end{pmatrix}\!\begin{pmatrix}e^{-i\theta}&0\\0&e^{i\theta}\end{pmatrix}
=\begin{pmatrix}0&e^{2i\theta}\\-e^{-2i\theta}&0\end{pmatrix}
=(\cos 2\theta)\mathbf{j}+(\sin 2\theta)\mathbf{k}.
\]
In the orthonormal plane $\Span\{\mathbf{j},\mathbf{k}\}$ orthogonal to the pole $\mathbf{i}$, this is rotation through $2\theta$. As $\theta$ ranges over $[0,\pi]$ the angle $2\theta$ covers every value in $[0,2\pi)$, so every rotation is hit: $\gamma$ is surjective. By the first isomorphism theorem $\mathrm{SO}(3)\cong\mathrm{SU}(2)/\{\pm I\}$. Identifying the antipodal pair $\{\pm P\}$ with a point of $S^3$ identifies $\mathrm{SO}(3)$ with $S^3/\{\pm1\}=\mathbb{RP}^3$.
\end{proof}

\begin{remark}
The factor of $2$ in ``angle $2\theta$'' is why $\mathrm{SU}(2)$ is the \emph{spin} group: a full $2\pi$ rotation in $\mathrm{SO}(3)$ comes from a half-loop $\theta\colon 0\to\pi$ in $\mathrm{SU}(2)$, while the loop $\theta\colon 0\to2\pi$ traverses $\mathrm{SU}(2)$ once but $\mathrm{SO}(3)$ twice. The one-dimensional shadow is the double cover $\mathrm{SO}(2)\to\mathrm{SO}(2)$, $\rho_\theta\mapsto\rho_{2\theta}$, whose every fiber is the antipodal pair $\{\rho_\theta,\rho_{\theta+\pi}\}$.
\end{remark}

