\begin{wex}{The kernel is exactly $\{\pm I\}$}
Show that $-I$ acts trivially on $V$, and that no element of a non-polar latitude can.
\wrec $\ker\gamma=\{\pm I\}$ by Theorem~\ref{art:su2so3:spin@c11}; the kernel is detected by which $P$ commute with all of $E$.
\wsol For $P=-I$: $\gamma_{-I}(U)=(-I)U(-I)^{*}=U$, so $-I\in\ker\gamma$, confirming $\gamma_P=\gamma_{-P}$. Now take any $P$ with $\tr P=2c$, $-1<c<1$, so $P=cI+sB$ with $B\in E$, $s\ne0$. If $P$ centralized all of $E$ it would centralize $\mathbf{i},\mathbf{j},\mathbf{k}$; but $B=x_1\mathbf{i}+x_2\mathbf{j}+x_3\mathbf{k}$ has $\mathbf{i}B-B\mathbf{i}=2x_2\mathbf{k}-2x_3\mathbf{j}$, so $B$ commutes with $\mathbf{i}$ only when $B=\pm\mathbf{i}$, and $\pm\mathbf{i}$ does not commute with $\mathbf{j}$ ($\mathbf{j}\mathbf{i}=-\mathbf{k}\ne\mathbf{k}=\mathbf{i}\mathbf{j}$). Since $s\ne0$, $P=cI+sB$ commutes with exactly the matrices that $B$ commutes with, so $P$ cannot commute with all of $E$. \textit{Check.} Only $c=\pm1$ (forcing $s=0$, $P=\pm I$) survives, so $\ker\gamma=\{\pm I\}$, a group of order $2$, and $\gamma$ is two-to-one as claimed.
\end{wex}

\begin{wex}{Composition of induced rotations}
Let $P=\operatorname{diag}(e^{i\theta},e^{-i\theta})$ and $P'=\operatorname{diag}(e^{i\phi},e^{-i\phi})$. Verify $\gamma_{PP'}=\gamma_P\gamma_{P'}$ and read off the resulting rotation.
\wrec $\gamma$ is a homomorphism (Theorem~\ref{art:su2so3:spin@c11}); both $P,P'$ lie on the longitude $L_{\mathbf{i}}$, which $\gamma$ sends to rotations about the common axis $\mathbf{i}$.
\wsol Since $PP'=\operatorname{diag}(e^{i(\theta+\phi)},e^{-i(\theta+\phi)})$, Theorem~\ref{art:su2so3:spin@c11} gives $\gamma_{PP'}=$ rotation about $\mathbf{i}$ through $2(\theta+\phi)$. Separately $\gamma_P$ rotates by $2\theta$ and $\gamma_{P'}$ by $2\phi$ about the same axis $\mathbf{i}$; rotations about a fixed axis add their angles, giving $2\theta+2\phi$. \textit{Check.} Both routes yield rotation about $\mathbf{i}$ by $2\theta+2\phi$, so $\gamma_{PP'}=\gamma_P\gamma_{P'}$. The longitude $L_{\mathbf{i}}\cong\mathrm{SO}(2)$ maps onto the circle of rotations about $\mathbf{i}$ by angle-doubling --- the $1$-dimensional double cover.
\end{wex}

\begin{pitfall}
A unit quaternion and the rotation it induces are \emph{not} in bijection: $P$ and $-P$ give the same rotation $\gamma_P=\gamma_{-P}$. So a rotation by angle $\alpha$ about axis $A$ has two ``spins'' $(A,\alpha)$ and $(-A,-\alpha)$, the antipodal pair $\{\pm P\}$. Tracking the sign is exactly the extra data $\mathrm{SU}(2)$ carries over $\mathrm{SO}(3)$.
\end{pitfall}

\begin{theorem}[Artin 9.5.2]\label{art:lie:expthm@c11}
Let $A$ be a real or complex $n\times n$ matrix.
\begin{enumerate}
\item[(a)] The map $\varphi\colon\mathbb{R}^{+}\to\mathrm{GL}_n$, $\varphi(t)=e^{tA}$, is a
group homomorphism.
\item[(b)] Conversely, if $\varphi\colon\mathbb{R}^{+}\to\mathrm{GL}_n$ is a differentiable
map that is a homomorphism, and $A=\varphi'(0)$ is its derivative at the origin,
then $\varphi(t)=e^{tA}$ for all $t$.
\end{enumerate}
\end{theorem}

\begin{remark}
The theorem is a bijection $\{\text{one-parameter groups in }\mathrm{GL}_n\}
\leftrightarrow\{n\times n\text{ matrices }A\}$, the correspondence being
$\varphi\leftrightarrow\varphi'(0)$. So to find the one-parameter groups lying in a
subgroup $H\sgr\mathrm{GL}_n$ we ask only: for which $A$ is $e^{tA}\in H$ for all
$t$? This single question produces the Lie algebra of $H$.
\end{remark}

\begin{proposition}[Artin 9.5.8, 9.5.10]\label{art:lie:classify@c11}
\begin{enumerate}
\item[(a)] If $A$ is real skew-symmetric ($A^{\trans}=-A$), then $e^{A}$ is
orthogonal; if $A$ is complex skew-Hermitian ($A^{*}=-A$), then $e^{A}$ is unitary.
\item[(b)] The one-parameter groups in $\mathrm{O}(n)$ are exactly the $t\mapsto e^{tA}$
with $A$ real skew-symmetric; those in $\mathrm{U}(n)$ are the $t\mapsto e^{tA}$ with
$A$ skew-Hermitian.
\item[(c)] The one-parameter groups in $\mathrm{SL}_n$ are the $t\mapsto e^{tA}$ with
$\tr A=0$.
\end{enumerate}
\end{proposition}

\begin{lemma}[Artin 9.5.9]\label{art:lie:detexp@c11}
For any square matrix $A$, $\;\det e^{A}=e^{\tr A}$.
\end{lemma}

\begin{proposition}[Artin 9.6.1]\label{art:lie:son@c11}
$\mathrm{Lie}(\mathrm{O}(n))=\mathrm{Lie}(\mathrm{SO}(n))$ is the space of real
skew-symmetric matrices.
\end{proposition}

\begin{proposition}[Artin 9.6.4]\label{art:lie:sln@c11}
$\mathrm{Lie}(\mathrm{SL}_n)$ is the space of real trace-zero matrices.
\end{proposition}

\begin{remark}
The pattern across the classical groups: the defining condition on the group becomes
a \emph{linear} condition on the tangent matrices (the derivative of the constraint
at $I$). Skew-Hermitian gives $\mathrm{Lie}(\mathrm{U}(n))=\mathfrak{u}(n)$, and
imposing also trace zero gives $\mathrm{Lie}(\mathrm{SU}(n))=\mathfrak{su}(n)$. In
each case $\mathrm{Lie}(G)$ is a real vector space.
\[
\renewcommand{\arraystretch}{1.25}
\begin{array}{lll}
  \text{Group} & \text{Condition on }M\in G & \text{Lie algebra } \mathrm{Lie}(G)\\\hline
  \mathrm{O}(n),\,\mathrm{SO}(n) & M^{\trans}M=I & A^{\trans}=-A\ \ (\text{skew-symmetric})\\
  \mathrm{U}(n) & M^{*}M=I & A^{*}=-A\ \ (\text{skew-Hermitian})\\
  \mathrm{SL}_n & \det M=1 & \tr A=0\ \ (\text{trace zero})
\end{array}
\]
\end{remark}

