\begin{proposition}\label{art:lie:bracketaxioms@c11}
The bracket is bilinear and alternating ($[A,A]=0$, equivalently $[A,B]=-[B,A]$), and
satisfies the \emph{Jacobi identity}
\[
  [A,[B,C]]+[B,[C,A]]+[C,[A,B]]=0.
\]
Moreover, on each classical Lie algebra it restricts to that subspace: if $A,B$ are
both trace zero, or both skew-symmetric, then so is $[A,B]$.
\end{proposition}

\begin{proof}
Bilinearity and $[A,A]=AA-AA=0$ are immediate; expanding $[A+B,A+B]=0$ then gives
$[A,B]=-[B,A]$. For Jacobi, expand each double bracket into the six products
$ABC,ACB,\dots$; for example $[A,[B,C]]=ABC-ACB-BCA+CBA$. Summing the three cyclic
terms, every one of the six monomials $ABC,\,ACB,\dots$ appears once with a $+$
sign and once with a $-$ sign, so the total is $0$. Closure on the classical algebras:
$\tr[A,B]=\tr(AB)-\tr(BA)=0$ since $\tr(AB)=\tr(BA)$; and if $A^{\trans}=-A$,
$B^{\trans}=-B$ then $[A,B]^{\trans}=(AB-BA)^{\trans}=B^{\trans}A^{\trans}-A^{\trans}B^{\trans}
=BA-AB=-[A,B]$.
\end{proof}

\begin{method}{Compute the Lie algebra of a matrix group}
Differentiate the defining equation of $G$ at $I$. Write a path $\varphi(t)=I+tA+\cdots$,
substitute into the constraint (e.g.\ $\varphi^{\trans}\varphi=I$ or $\det\varphi=1$),
and keep the first-order term: it is a \emph{linear} equation in $A$ cutting out
$\mathrm{Lie}(G)$. Then equip $\mathrm{Lie}(G)$ with $[A,B]=AB-BA$.
\end{method}

\begin{definition}
An $R$-module $F$ is \emph{free} on a subset $A \subseteq F$ if for every nonzero $x \in F$ there are unique nonzero $r_1,\dots,r_n \in R$ and distinct $a_1,\dots,a_n \in A$ with $x = r_1 a_1 + \cdots + r_n a_n$. We call $A$ a \emph{basis}. If $A$ is finite of size $n$ then $F \cong R^n$, and $n$ is the \emph{rank} of $F$.
\end{definition}

\begin{remark}
Over a commutative ring with $1\neq 0$ the rank is well defined: $R^n \cong R^m$ forces $n=m$. (Quotient by a maximal ideal $\mathfrak{m}$ to get $(R/\mathfrak{m})^n \cong (R/\mathfrak{m})^m$ as vector spaces over the field $R/\mathfrak{m}$, then compare dimensions.) For a PID this is part of the larger structure below.
\end{remark}

\begin{wex}{Free vs.\ non-free modules}
Decide which of the following are free $R$-modules: (a) $\mathbb{Z}^3$ over $\mathbb{Z}$; (b) $\mathbb{Z}/6\mathbb{Z}$ over $\mathbb{Z}$; (c) $\mathbb{Q}$ over $\mathbb{Z}$; (d) $\F[x]^2$ over $\F[x]$; (e) the ideal $(2)\subseteq\mathbb{Z}$ over $\mathbb{Z}$.
\wrec Apply the definition directly: a free module is a direct sum of copies of $R$, equivalently it has a basis. Torsion or "divisibility" obstructions kill freeness.
\wsol (a) Free of rank $3$, basis $e_1,e_2,e_3$. (b) NOT free: every element is killed by $6$, but a basis element $a$ must satisfy $ra=0\Rightarrow r=0$ (uniqueness with $r=0$). (c) NOT free: any two elements $\tfrac{a}{b},\tfrac{c}{d}\in\mathbb{Q}$ satisfy the relation $(cb)\tfrac{a}{b}-(ad)\tfrac{c}{d}=0$, so no two elements are independent; a single element cannot generate $\mathbb{Q}$ (e.g.\ $\tfrac{1}{2}$ generates only $\tfrac{1}{2}\mathbb{Z}$). (d) Free of rank $2$. (e) Free of rank $1$ with basis $\{2\}$: every element is $2k = k\cdot 2$ uniquely, and $r\cdot 2=0\Rightarrow r=0$ since $\mathbb{Z}$ is a domain. Sanity check: $(2)\cong\mathbb{Z}$ as $\mathbb{Z}$-modules via $2k\mapsto k$, confirming rank $1$.
\end{wex}

\begin{theorem}\label{thm:subfree@c12}
Let $R$ be a PID, let $F$ be a free $R$-module of finite rank $n$, and let $N \subseteq F$ be a submodule. Then $N$ is free of rank $m \le n$, and there is a basis $y_1,\dots,y_n$ of $F$ together with nonzero elements $a_1,\dots,a_m \in R$ such that $a_1 y_1,\dots,a_m y_m$ is a basis of $N$ and $a_1 \mid a_2 \mid \cdots \mid a_m$.
\end{theorem}

\begin{wex}{An aligned basis in $\mathbb{Z}^2$}
Let $F=\mathbb{Z}^2$ and $N$ the subgroup generated by $u=(4,2)$ and $v=(2,2)$. Find a basis $y_1,y_2$ of $F$ and $a_1\mid a_2$ with $a_1y_1,a_2y_2$ a basis of $N$.
\wrec Theorem~\ref{thm:subfree@c12}: pick generators, run integer row/column operations (change of basis in $F$ and in $N$) to diagonalize.
\wsol Stack as rows of $A=\begin{pmatrix}4&2\\2&2\end{pmatrix}$. Swap rows: $\begin{pmatrix}2&2\\4&2\end{pmatrix}$; $R_2\!-\!2R_1$: $\begin{pmatrix}2&2\\0&-2\end{pmatrix}$; $C_2\!-\!C_1$: $\begin{pmatrix}2&0\\0&-2\end{pmatrix}$; sign-fix to $\diag(2,2)$. So $a_1=2,a_2=2$ with $2\mid2$, and $y_1,y_2$ is the basis of $F$ recorded by the column operations. Sanity check: $\det A=8-4=4=a_1a_2$ and $[F:N]=4$, matching $\abs{\det}$.
\end{wex}

If $M$ is finitely generated by $x_1,\dots,x_m$, map $R^m \twoheadrightarrow M$ by $e_i \mapsto x_i$; the kernel $N$ of relations is free of rank $\le m$ (Theorem~\ref{thm:subfree@c12}), say with generators giving a map $R^n \to R^m$ whose matrix is the \emph{relations/presentation matrix} $A \in \Mat_{m\times n}(R)$. We get an exact sequence, a \emph{free presentation} of $M$:

\begin{center}
\begin{tikzcd}
R^n \arrow[r, "A"] & R^m \arrow[r, two heads, "\pi"] & M \arrow[r] & 0
\end{tikzcd}
\end{center}

\begin{dgx}
\dgi{Objects:} Three $R$-modules in sequence: $R^n$ is the free module of relations (rank $n$, one basis vector per relation generator), $R^m$ is the free module of generators (rank $m$, one basis vector per generator $x_i$ of $M$), and $M$ is the finitely generated $R$-module being presented.
\dgi{Arrows:} $A\colon R^n \to R^m$ is the relations map, sending the $j$-th basis vector $e_j$ of $R^n$ to the $j$-th relation written as a linear combination of generators; its matrix is the presentation matrix. $\pi\colon R^m \to M$ is the surjective quotient map sending $e_i\mapsto x_i$. The terminal $0$ records surjectivity of $\pi$.
\dgi{What commutes:} Exactness at $R^m$: $\operatorname{im}(A) = \ker(\pi)$. In other words, a combination $\sum r_i e_i$ maps to $0$ in $M$ if and only if it is a relation, i.e., lies in the column space of $A$.
\dgi{Why it commutes:} $\pi \circ A$ sends $e_j \mapsto$ the $j$-th relation expressed in $M$, which is $0$ by construction (the $x_i$ satisfy those relations). Conversely, any $v \in \ker(\pi)$ is an element of $R^m$ whose image in $M$ is $0$, meaning it is expressible as a relation, so $v \in \im(A)$.
\dgi{Why this matters here:} This diagram encodes the entire data of $M$: generators live in $R^m$ and the relations kernel $N = \im(A)$ is free of rank $\le m$ by Theorem~\ref{thm:subfree@c12}. It is the raw input for Smith Normal Form -- diagonalizing $A$ immediately yields the invariant factor decomposition.
\dgi{Concrete example:} $M = \mathbb{Z}/2\mathbb{Z} \oplus \mathbb{Z}/3\mathbb{Z}$, generators $x_1, x_2$ with relations $2x_1 = 0$, $3x_2 = 0$. Then $A = \diag(2,3)$, $n = m = 2$, and $M \cong \mathbb{Z}^2 / \im(A) = \mathbb{Z}/2 \oplus \mathbb{Z}/3$.
\dgi{Common pitfall:} Students often confuse $A$ as the matrix of a map $R^n \to R^m$ (acting on column vectors of coefficients) with $A$ as the transpose presentation. Be careful: columns of $A$ are the relation vectors in $R^m$, not rows.
\dgi{Takeaway:} The point of this diagram is that every finitely generated $R$-module is a cokernel of a matrix $A$ over $R$, so classifying modules reduces to understanding $\coker(A)$ via Smith Normal Form.
\end{dgx}

so that $M \cong R^m / \im(A) = \coker(A)$.

\begin{wex}{A cokernel with free part}
Compute $\coker(A)$ for $A=\begin{pmatrix}6&4\\ 9&6\end{pmatrix}\in\Mat_2(\mathbb{Z})$ viewed as relations on $\mathbb{Z}^2$.
\wrec $\det A=0$ flags a free summand; Smith Normal Form has a trailing $0$.
\wsol $\det A=36-36=0$. Entry gcd $d_1=\gcd(6,4,9,6)=1$, so $a_1=1$. Since $\det=0$, $d_2=0$, giving $D=\diag(1,0)$. Thus $\coker(A)\cong \mathbb{Z}/1\mathbb{Z}\oplus\mathbb{Z}/0\mathbb{Z}\cong 0\oplus\mathbb{Z}\cong\mathbb{Z}$. Sanity check: rows $(6,4),(9,6)$ are parallel ($\tfrac32$ ratio), so $\im(A)$ has rank $1$ inside $\mathbb{Z}^2$ and the quotient has free rank $2-1=1$; the $\mathbb{Z}/1\mathbb{Z}=0$ factor reflects that $\im(A)$ is "primitive enough" ($\gcd$ of entries $1$) to contribute no torsion.
\end{wex}

\begin{wex}{Smith Normal Form over $\F[x]$}
Over $R=\mathbb{Q}[x]$ put $A=\begin{pmatrix}x-1 & 0\\ 0 & (x-1)(x+2)\end{pmatrix}$ into Smith Normal Form.
\wrec The PID $\mathbb{Q}[x]$ admits the same algorithm; invariant factors must satisfy $a_1\mid a_2$ after sorting.
\wsol Here it is already diagonal with $a_1=x-1$, $a_2=(x-1)(x+2)$ and $x-1\mid(x-1)(x+2)$, so this IS the Smith Normal Form. Thus $\coker(A)\cong \mathbb{Q}[x]/(x-1)\oplus \mathbb{Q}[x]/\big((x-1)(x+2)\big)$. Sanity check: had we instead been handed $\diag\big((x-1)(x+2),\,x-1\big)$, divisibility fails ($(x-1)(x+2)\nmid x-1$); column/row ops would re-sort to recover $a_1=x-1,\ a_2=(x-1)(x+2)$, the unique invariant-factor order.
\end{wex}

\begin{definition}
The \emph{torsion submodule} is $\mathrm{Tor}(M) = \{x \in M : rx = 0 \text{ for some } r \neq 0\}$. A module is \emph{torsion} if $\mathrm{Tor}(M)=M$ and \emph{torsion-free} if $\mathrm{Tor}(M)=0$.
\end{definition}

\begin{corollary}
A finitely generated torsion-free module over a PID is free.
\end{corollary}

\begin{center}
\begin{tikzcd}
0 \arrow[r] & \mathrm{Tor}(M) \arrow[r, hook] & M \arrow[r, two heads] & M/\mathrm{Tor}(M) \arrow[r] & 0 \\
& R/(a_1)\oplus\cdots\oplus R/(a_m) \arrow[u, "\cong"] & & R^r \arrow[u, "\cong"'] &
\end{tikzcd}
\end{center}

\begin{dgx}
\dgi{Objects:} Top row: five terms of a short exact sequence of $R$-modules: $0$, $\Tor(M)$ (the torsion submodule of $M$, consisting of all elements killed by some nonzero $r \in R$), $M$ itself, the quotient $M/\Tor(M)$ (torsion-free part), and $0$. Bottom row: $R/(a_1) \oplus \cdots \oplus R/(a_m)$ is the direct sum of cyclic torsion factors from the structure theorem, and $R^r$ is the free summand of rank $r$.
\dgi{Arrows:} Top row left: inclusion $\Tor(M) \hookrightarrow M$ (the natural inclusion of the torsion submodule). Top row right: canonical surjection $M \twoheadrightarrow M/\Tor(M)$. Left vertical: the isomorphism $R/(a_1) \oplus \cdots \oplus R/(a_m) \xrightarrow{\,\cong\,} \Tor(M)$ given by the structure theorem. Right vertical: the isomorphism $R^r \xrightarrow{\,\cong\,} M/\Tor(M)$ identifying the free part.
\dgi{What commutes:} Exactness at $\Tor(M)$: $\ker(\Tor(M) \to M) = 0$ (injection). Exactness at $M$: $\operatorname{im}(\Tor(M) \hookrightarrow M) = \ker(M \to M/\Tor(M))$, i.e., $\Tor(M)$ is exactly the kernel of the quotient map. Exactness at $M/\Tor(M)$: $\ker(M/\Tor(M) \to 0) = M/\Tor(M) = \operatorname{im}(M \to M/\Tor(M))$ (surjection). The vertical isom arrows are compatible with the horizontal sequence.
\dgi{Why it commutes:} By definition, $\Tor(M)$ is a submodule of $M$, so inclusion is injective; the quotient map kills exactly $\Tor(M)$. The structure theorem (Theorem~\ref{thm:invfac@c12}) supplies the explicit isomorphisms vertically, identifying torsion with the cyclic factors and the free part with $R^r$.
\dgi{Why this matters here:} This diagram cleanly separates the two parts of the structure theorem and shows the sequence SPLITS -- since $M/\Tor(M) \cong R^r$ is free (hence projective), the surjection $M \twoheadrightarrow R^r$ has a section, giving $M \cong \Tor(M) \oplus R^r \cong R/(a_1) \oplus \cdots \oplus R/(a_m) \oplus R^r$.
\dgi{Concrete example:} $M = \mathbb{Z} \oplus \mathbb{Z}/2 \oplus \mathbb{Z}/6$. Then $\Tor(M) = \mathbb{Z}/2 \oplus \mathbb{Z}/6$, $M/\Tor(M) = \mathbb{Z}$, and the sequence $0 \to \mathbb{Z}/2 \oplus \mathbb{Z}/6 \to M \to \mathbb{Z} \to 0$ splits via the section $1 \mapsto (1,0,0)$.
\dgi{Common pitfall:} Students sometimes confuse $\Tor(M)$ (torsion submodule, a specific subobject of $M$) with the derived functor $\operatorname{Tor}^1_R(-,-)$ from homological algebra. Here $\Tor(M)$ is simply the set of torsion elements, not a bifunctor.
\dgi{Takeaway:} The point of this diagram is that the structure theorem naturally splits $M$ into a torsion piece (the cyclic $R/(a_i)$ factors) and a free piece ($R^r$), and the short exact sequence splits because free modules are projective.
\end{dgx}

The bottom row identifies the two halves of the structure theorem; the sequence splits because $R^r$ is free (hence projective).

\begin{wex}{Number of abelian groups of order 600}
How many abelian groups of order $600$ are there up to isomorphism, and list their invariant factors.
\wrec $R=\mathbb{Z}$ case of Theorem~\ref{thm:invfac@c12}: count via partitions of each prime exponent; assemble invariant-factor chains.
\wsol $600=2^3\cdot3\cdot5^2$. Partitions: of $3$ (for $2$): $3,\;2{+}1,\;1{+}1{+}1$ ($p(3)=3$); of $1$ (for $3$): only $1$ ($p(1)=1$); of $2$ (for $5$): $2,\;1{+}1$ ($p(2)=2$). Total $3\cdot1\cdot2=6$ groups. As invariant factors (align partitions right, multiply column-wise): e.g.\ for $2$-part $2{+}1$, $5$-part $1{+}1$, $3$-part $1$: columns give $a_1=2\cdot5=10$, $a_2=4\cdot5\cdot3=60$, so $\mathbb{Z}/10\oplus\mathbb{Z}/60$. Listing all six in invariant-factor form (each chain $a_1\mid a_2\mid\cdots$): $\mathbb{Z}/600$; $\mathbb{Z}/2\oplus\mathbb{Z}/300$; $\mathbb{Z}/2\oplus\mathbb{Z}/2\oplus\mathbb{Z}/150$; $\mathbb{Z}/5\oplus\mathbb{Z}/120$; $\mathbb{Z}/10\oplus\mathbb{Z}/60$; $\mathbb{Z}/2\oplus\mathbb{Z}/10\oplus\mathbb{Z}/30$. Sanity check: each has product $600$, and within each the invariant factors form a divisibility chain ($5\mid120$, $10\mid60$, $2\mid10\mid30$).
\end{wex}

\begin{remark}[Converting between the two lists]
\emph{Invariant factors $\to$ elementary divisors:} factor each $a_i$ into prime powers and list them. \emph{Elementary divisors $\to$ invariant factors:} for each prime $p$ sort its exponents in nondecreasing order and pad with $0$'s on the LEFT so all primes have the same length; the $k$-th invariant factor is the product over all primes $p$ of $p$ raised to its $k$-th exponent. The largest invariant factor $a_m$ is the lcm of all elementary divisors and generates $\mathrm{Ann}(\mathrm{Tor}(M))$ (for $R=\mathbb{Z}$: $a_m$ is the exponent of $\mathrm{Tor}(M)$, not its order).
\end{remark}

\begin{proposition}[Counting via $\dim_k$]
For a finitely generated torsion module $M$ over the PID $R$, the number of elementary divisors that are powers of $p$ is $\dim_k\!\big(M/pM\big)$, and more refined counts come from $\dim_k\!\big(p^{j}M/p^{j+1}M\big)$. These dimensions are isomorphism invariants, which forces uniqueness of the elementary divisor list.
\end{proposition}

\begin{wex}{Distinguishing two groups by $\dim_{\F_p}$}
Show $G=\mathbb{Z}/4\mathbb{Z}\oplus\mathbb{Z}/4\mathbb{Z}$ and $H=\mathbb{Z}/2\mathbb{Z}\oplus\mathbb{Z}/8\mathbb{Z}$ are non-isomorphic even though $\abs{G}=\abs{H}=16$.
\wrec Use the invariant $\dim_{\F_2}(M/2M)$ = number of $2$-power elementary divisors (rank of the $2$-torsion).
\wsol $G/2G$: each $\mathbb{Z}/4$ gives $\mathbb{Z}/4 \big/ 2(\mathbb{Z}/4)\cong\mathbb{Z}/2$, so $\dim_{\F_2}(G/2G)=2$. $H/2H$: $\mathbb{Z}/2\big/2(\mathbb{Z}/2)=\mathbb{Z}/2$ and $\mathbb{Z}/8\big/2(\mathbb{Z}/8)=\mathbb{Z}/2$, so $\dim_{\F_2}(H/2H)=2$ also. Tie --- go one level deeper with $\dim_{\F_2}(2M/4M)$. For $G$: $2G=2\mathbb{Z}/4\oplus2\mathbb{Z}/4\cong\mathbb{Z}/2\oplus\mathbb{Z}/2$ and $4G=0$, so $\dim(2G/4G)=2$. For $H$: $2H=0\oplus2\mathbb{Z}/8\cong\mathbb{Z}/4$, $4H=0\oplus4\mathbb{Z}/8\cong\mathbb{Z}/2$, so $\dim(2H/4H)=\dim(\mathbb{Z}/4\big/\mathbb{Z}/2)=1$. Since $2\neq1$, $G\not\cong H$. Sanity check: elementary divisors are $\{4,4\}$ vs.\ $\{2,8\}$ --- genuinely different lists, as the invariants detect.
\end{wex}

\begin{wex}{Uniqueness forces the divisibility order}
Explain why $\mathbb{Z}/2\mathbb{Z}\oplus\mathbb{Z}/4\mathbb{Z}$ cannot also be written with invariant factors $4,2$ (i.e.\ why the chain must be $2\mid4$, not $4\mid2$).
\wrec Theorem~\ref{thm:invfac@c12} fixes invariant factors uniquely AND requires $a_1\mid a_2$; this is a normalization, not a choice.
\wsol The module $\mathbb{Z}/2\oplus\mathbb{Z}/4$ has order $8$ and exponent (largest order of an element) $=4$. The largest invariant factor always equals the exponent, so $a_{\max}=4$; the remaining factor is $8/4=2$, and $2\mid4$. Writing "$4,2$" would violate $a_1\mid a_2$ ($4\nmid2$) and is simply not the normal form. Sanity check: as elementary divisors this is $\{2,4\}$ at $p=2$; pad-left gives $a_1=2,a_2=4$ --- the unique answer.
\end{wex}

\begin{wex}{From order data to the group}
A finite abelian group $G$ has order $72$, contains an element of order $12$, and satisfies $\dim_{\F_2}(G/2G)=2$, $\dim_{\F_3}(G/3G)=1$. Determine $G$.
\wrec Combine the order/exponent constraint (largest invariant factor) with the $\dim_k(G/pG)$ counts of elementary divisors (uniqueness proposition).
\wsol $72=2^3\cdot3^2$. $\dim_{\F_3}(G/3G)=1$ means ONE $3$-power elementary divisor, so the $3$-part is a single $\mathbb{Z}/9$ (since $3^2$ must appear). $\dim_{\F_2}(G/2G)=2$ means TWO $2$-power elementary divisors with exponents summing to $3$: that is $\{2,4\}$ (i.e.\ $2^1,2^2$). So elementary divisors $=\{4,2,9\}$. Build invariant factors: $a_1=2$ (smaller $2$-power, no $3$-part), $a_2=4\cdot9=36$. So $G\cong\mathbb{Z}/2\oplus\mathbb{Z}/36$. Check the order-$12$ requirement: exponent $=a_2=36$, and $12\mid36$, so an element of order $12$ exists. Sanity check: $2\cdot36=72$; $2\mid36$. Consistent and unique.
\end{wex}

\begin{wex}{Executing the bootstrap by hand}
Let $M=\mathbb{Z}^2/N$ where $N=\Span_\mathbb{Z}\{(6,0),(0,9),(3,3)\}$. Classify $M$ by aligning a basis.
\wrec The diagram above: diagonalize the $2\times3$ relations matrix to Smith Normal Form, then quotient coordinatewise.
\wsol Relations as columns: $A=\begin{pmatrix}6&0&3\\0&9&3\end{pmatrix}$ ($2$ generators, $3$ relations). $d_1=\gcd(6,0,3,0,9,3)=3$, so $a_1=3$. $d_2=\gcd$ of $2\times2$ minors: $\det\begin{pmatrix}6&0\\0&9\end{pmatrix}=54$, $\det\begin{pmatrix}6&3\\0&3\end{pmatrix}=18$, $\det\begin{pmatrix}0&3\\9&3\end{pmatrix}=-27$; $\gcd(54,18,27)=9$, so $d_2=9$ and $a_2=d_2/d_1=9/3=3$. Smith Normal Form $\diag(3,3)$ (the extra relation column is dependent). Hence $M\cong\mathbb{Z}/3\mathbb{Z}\oplus\mathbb{Z}/3\mathbb{Z}$ with invariant factors $3,3$ ($3\mid3$).
Sanity check: $\abs{M}=[\mathbb{Z}^2:N]$. Lattice $N$ contains $(6,0),(0,9),(3,3)$; index $=\abs{\det}$ of a basis of $N$. From $(3,3)$ and $(6,0)=2(3,3)-(0,6)$ get $(0,6)$, and $\gcd(6,9)=3$ gives $(0,3)$; so $N$ has basis $(3,3),(0,3)$, $\det=9$, index $9=3\cdot3$. Matches.
\end{wex}

\begin{exers}{Commutative-diagram exercises.}

\item Let $R$ be a PID and let $M$ be finitely generated with a presentation
\[
\begin{tikzcd}
R^m \arrow[r,"A"] & R^n \arrow[r,two heads,"\pi"] & M \arrow[r] & 0
\end{tikzcd}
\]
exact, where $A$ is an $n\times m$ matrix. Suppose $U\in\operatorname{GL}_n(R)$ and $V\in\operatorname{GL}_m(R)$ put $A$ into Smith normal form $D=UAV=\diag(a_1,\dots,a_k,0,\dots)$. Draw the commutative diagram relating the two presentations $R^m\xrightarrow{A}R^n$ and $R^m\xrightarrow{D}R^n$ using the vertical isomorphisms induced by $U$ and $V$, and explain why it shows $M\cong\operatorname{coker}(A)\cong\operatorname{coker}(D)=R^{n-k}\oplus\bigoplus_i R/(a_i)$.

\item Let $R$ be a PID and let
\[
\begin{tikzcd}
0 \arrow[r] & T \arrow[r,hook,"\iota"] & M \arrow[r,two heads,"q"] & M/T \arrow[r] & 0
\end{tikzcd}
\]
be the short exact sequence where $T$ is the torsion submodule of the finitely generated module $M$. Show this sequence splits by constructing a section $s\colon M/T\to M$ with $q\circ s=\id_{M/T}$, and draw the diagram exhibiting the resulting isomorphism $M\cong T\oplus(M/T)$ (with $M/T$ free).

\item Let $R$ be a PID and let $a\mid b$ in $R$. Consider the diagram
\[
\begin{tikzcd}
R/(a) \arrow[r,"f"] & R/(b)
\end{tikzcd}
\]
where $f$ is the $R$-module map sending $1+(a)$ to $c+(b)$. Determine exactly which $c\in R$ make $f$ well defined, and for such $c$ build the commutative diagram with the quotient maps from $R$ showing $f$ is induced by multiplication by $c$ on $R$. Use this to describe $\Hom_R(R/(a),R/(b))$ as a cyclic $R$-module.

\item Let $R=\mathbb{Z}$ and consider the map $\varphi\colon\mathbb{Z}^2\to\mathbb{Z}^2$ given by the matrix $A=\begin{pmatrix} 6 & 0\\ 0 & 10 \end{pmatrix}$, fitting into
\[
\begin{tikzcd}
\mathbb{Z}^2 \arrow[r,"A"] & \mathbb{Z}^2 \arrow[r,two heads,"\pi"] & M \arrow[r] & 0.
\end{tikzcd}
\]
Find $U,V\in\operatorname{GL}_2(\mathbb{Z})$ with $UAV$ in Smith normal form, and draw the commutative square with vertical maps $V$ and $U$ relating $A$ to its Smith normal form. Read off $M$ in invariant factor form from the diagram.

\item Let $R$ be a PID, $p$ a prime, and let $M$ be a finitely generated torsion $R$-module. Consider multiplication by $p$, fitting into the exact sequence
\[
\begin{tikzcd}
0 \arrow[r] & M[p] \arrow[r] & M \arrow[r,"{p\cdot}"] & M \arrow[r] & M/pM \arrow[r] & 0.
\end{tikzcd}
\]
Draw this diagram and prove that $\dim_{R/(p)} M[p]=\dim_{R/(p)} M/pM$ equals the number of elementary divisors of $M$ that are powers of $p$. (Argue exactness at each spot and count $R/(p)$-dimensions.)

\end{exers}

\begin{corollary}
$\deg c_T = \dim_F V$, $\ m_T \mid c_T$, and $c_T \mid (m_T)^m$ where $m$ is the
number of invariant factors. Consequently $c_T$ and $m_T$ have the same irreducible
factors (the distinct prime divisors of $a_m$). The operator $T$ is cyclic (i.e.\
$V_T$ is a cyclic $F[x]$-module, $m = 1$) iff $m_T = c_T$.
\end{corollary}

