\begin{theorem}[similarity $\iff$ same invariant factors]
Let $A, B \in \Mat_n(F)$. The following are equivalent:
\begin{enumerate}
 \item $A$ and $B$ are similar over $F$ (i.e.\ $B = P^{-1} A P$ for some invertible
 $P \in \Mat_n(F)$);
 \item $V_A \cong V_B$ as $F[x]$-modules;
 \item $A$ and $B$ have the same invariant factors;
 \item $A$ and $B$ have the same rational canonical form;
 \item $xI - A$ and $xI - B$ have the same Smith normal form over $F[x]$.
\end{enumerate}
\end{theorem}

