\begin{theorem}[13.17]
The extension $K/F$ is finite if and only if $K$ is generated over $F$ by finitely many algebraic elements; that is, $K=F(\alpha_1,\dots,\alpha_n)$ with each $\alpha_i$ algebraic over $F$. Consequently every finite extension is algebraic.
\end{theorem}

\begin{wex}{Every element of a finite extension is algebraic}
Let $K=\mathbb{Q}(\sqrt2,\sqrt3)$, $[K:\mathbb{Q}]=4$. Show $\gamma=1+\sqrt2+\sqrt6$ is algebraic over $\mathbb{Q}$ and bound its degree.
\wrec Theorem 13.17: $K/\mathbb{Q}$ finite $\Rightarrow$ algebraic; the degree of any $\gamma\in K$ divides $[K:\mathbb{Q}]$.
\wsol Since $[K:\mathbb{Q}]=4<\infty$, $K/\mathbb{Q}$ is algebraic, so $\gamma$ is algebraic. Moreover $\mathbb{Q}(\gamma)\subseteq K$, so $[\mathbb{Q}(\gamma):\mathbb{Q}]\mid4$, i.e.\ $\deg\gamma\in\{1,2,4\}$. As $\gamma\notin\mathbb{Q}$ (it involves $\sqrt2$) the degree is $2$ or $4$. The powers $1,\gamma,\gamma^2,\gamma^3,\gamma^4$ live in the $4$-dimensional space $K$, so are $\mathbb{Q}$-dependent; that dependence is a degree-$\le4$ polynomial relation, explicitly producing $m_{\gamma,\mathbb{Q}}$. Sanity check: any concrete element of a $4$-dimensional extension has at most $4$ linearly independent powers, guaranteeing a vanishing polynomial of degree $\le4$.
\end{wex}

\begin{wex}{A finitely generated tower built step by step}
Compute $[\mathbb{Q}(\sqrt2,\sqrt[3]2):\mathbb{Q}]$ via the chain $\mathbb{Q}\subseteq\mathbb{Q}(\sqrt2)\subseteq\mathbb{Q}(\sqrt2,\sqrt[3]2)$.
\wrec Iterate the tower law: each adjunction of an algebraic element multiplies the degree by the degree of its minimal polynomial \emph{over the current field}.
\wsol $[\mathbb{Q}(\sqrt2):\mathbb{Q}]=2$. Over $E=\mathbb{Q}(\sqrt2)$, $\sqrt[3]2$ satisfies $x^3-2$; this is irreducible over $E$ since $3\nmid[E:\mathbb{Q}]=2$ rules out a root or factor (a proper factor would give $\sqrt[3]2$ degree $1$ or $2$ over $E$, hence $[E(\sqrt[3]2):\mathbb{Q}]\in\{2,4\}$, which is not divisible by $3=[\mathbb{Q}(\sqrt[3]2):\mathbb{Q}]$ although $\mathbb{Q}(\sqrt[3]2)\subseteq E(\sqrt[3]2)$). So $[\mathbb{Q}(\sqrt2,\sqrt[3]2):E]=3$ and $[\mathbb{Q}(\sqrt2,\sqrt[3]2):\mathbb{Q}]=3\cdot2=6$. Sanity check: $6$ is divisible by both $2=[\mathbb{Q}(\sqrt2):\mathbb{Q}]$ and $3=[\mathbb{Q}(\sqrt[3]2):\mathbb{Q}]$, as the tower law requires; note $\mathbb{Q}(\sqrt2,\sqrt[3]2)=\mathbb{Q}(\sqrt[6]2)$ since $\sqrt[6]2=\sqrt2/\sqrt[3]2$ lies in the field, while conversely $\sqrt2=(\sqrt[6]2)^3$ and $\sqrt[3]2=(\sqrt[6]2)^2$, so $\sqrt[6]2$ generates both.
\end{wex}

\begin{wex}{Composite degree bound for $F(\alpha,\beta)$}
If $[F(\alpha):F]=m$ and $[F(\beta):F]=n$ with $\gcd(m,n)=1$, show $[F(\alpha,\beta):F]=mn$. Apply to $\sqrt2$ ($m=2$) and $\sqrt[3]2$ ($n=3$).
\wrec Tower law twice: $m,n$ each divide $[F(\alpha,\beta):F]$, while $[F(\alpha,\beta):F]\le mn$; coprimality pins the value.
\wsol Both $F(\alpha)$ and $F(\beta)$ sit inside $L=F(\alpha,\beta)$, so $m\mid[L:F]$ and $n\mid[L:F]$; since $\gcd(m,n)=1$, $mn\mid[L:F]$. Conversely $[L:F]=[L:F(\alpha)][F(\alpha):F]\le n\cdot m$ because $\beta$ has degree $\le n$ over the larger field $F(\alpha)$. Hence $[L:F]=mn$. For $\sqrt2,\sqrt[3]2$ over $\mathbb{Q}$: $m=2,n=3$, $\gcd=1$, so $[\mathbb{Q}(\sqrt2,\sqrt[3]2):\mathbb{Q}]=6$, agreeing with the previous example. Sanity check: the displayed lattice has $[L:F(\alpha)]=mn/m=n$ and $[L:F(\beta)]=mn/n=m$, both consistent.
\end{wex}

\begin{remark}
The point: if $\alpha,\beta$ are algebraic over $F$, then $F(\alpha,\beta)/F$ is finite (Theorem 13.17), hence algebraic, so $\alpha\pm\beta$, $\alpha\beta$, and $\alpha/\beta$ (for $\beta\neq0$) --- all elements of $F(\alpha,\beta)$ --- are again algebraic over $F$. Closure under the field operations follows with no need to exhibit minimal polynomials.
\end{remark}

\begin{wex}{Sum and product of algebraic numbers are algebraic}
Show directly that $\sqrt2+\sqrt[3]2$ and $\sqrt2\cdot\sqrt[3]2$ are algebraic over $\mathbb{Q}$, and bound their degrees.
\wrec Theorem 13.19 / the remark: both lie in $\mathbb{Q}(\sqrt2,\sqrt[3]2)$, a finite (hence algebraic) extension; degrees divide $[\mathbb{Q}(\sqrt2,\sqrt[3]2):\mathbb{Q}]=6$.
\wsol $\mathbb{Q}(\sqrt2,\sqrt[3]2)$ has degree $6$ over $\mathbb{Q}$ and is algebraic, so $\sqrt2+\sqrt[3]2$ and $\sqrt2\sqrt[3]2=2^{1/2+1/3}=2^{5/6}=\sqrt[6]{32}$ are algebraic with degree dividing $6$. In fact $2^{5/6}$ has minimal polynomial $x^6-32$, so degree exactly $6$: Eisenstein at $2$ does not apply ($2^2\mid32$), but $(2^{5/6})^5=16\sqrt[6]2$ puts $\sqrt[6]2$, of degree $6$ by Eisenstein on $x^6-2$, inside $\mathbb{Q}(2^{5/6})$. Sanity check: $\deg(2^{5/6})=6=[\mathbb{Q}(\sqrt2,\sqrt[3]2):\mathbb{Q}]$, so $\mathbb{Q}(2^{5/6})=\mathbb{Q}(\sqrt2,\sqrt[3]2)$, consistent with $2^{5/6}$ generating the whole field.
\end{wex}

\begin{wex}{The field of algebraic numbers}
Let $\overline{\mathbb{Q}}\subseteq\mathbb{C}$ be the set of complex numbers algebraic over $\mathbb{Q}$. Show $\overline{\mathbb{Q}}$ is a field, and that $[\overline{\mathbb{Q}}:\mathbb{Q}]=\infty$ even though $\overline{\mathbb{Q}}/\mathbb{Q}$ is algebraic.
\wrec Theorem 13.19 gives the subfield structure. For the degree, exhibit elements of unbounded degree, so no finite bound on $\dim_\mathbb{Q}$ can hold.
\wsol By Theorem 13.19 (with $K=\mathbb{C}$, $F=\mathbb{Q}$), $\overline{\mathbb{Q}}$ is a subfield of $\mathbb{C}$. It is algebraic over $\mathbb{Q}$ by definition. But $\sqrt[n]2\in\overline{\mathbb{Q}}$ has degree $n$ over $\mathbb{Q}$ for every $n$ (Eisenstein at $2$ on $x^n-2$), so $\overline{\mathbb{Q}}$ contains subfields of every finite degree; thus $[\overline{\mathbb{Q}}:\mathbb{Q}]=\infty$. Sanity check: ``algebraic'' does not imply ``finite'' --- an infinite algebraic extension is exactly one that is algebraic yet of infinite degree, and $\overline{\mathbb{Q}}$ is the prototype.
\end{wex}

\begin{wex}{Algebraic closure inside $\mathbb{R}$}
Describe $\overline{\mathbb{Q}}^{\,\mathbb{R}}$, the elements of $\mathbb{R}$ algebraic over $\mathbb{Q}$ (the real algebraic numbers), and verify it is a field strictly between $\mathbb{Q}$ and $\mathbb{R}$.
\wrec Theorem 13.19 with $K=\mathbb{R}$. Strictness on both ends needs one algebraic irrational and one transcendental real.
\wsol The set of real algebraic numbers is a subfield of $\mathbb{R}$ by Theorem 13.19. It strictly contains $\mathbb{Q}$ (e.g.\ $\sqrt2$) and is strictly contained in $\mathbb{R}$ (e.g.\ $\pi$ is transcendental, so $\pi\notin\overline{\mathbb{Q}}^{\,\mathbb{R}}$). Sanity check: $\overline{\mathbb{Q}}^{\,\mathbb{R}}=\overline{\mathbb{Q}}\cap\mathbb{R}$, the real part of the algebraic numbers; it is countable while $\mathbb{R}$ is uncountable, re-confirming proper containment.
\end{wex}

\begin{theorem}[13.20]
If $K/E$ is algebraic and $E/F$ is algebraic, then $K/F$ is algebraic. (Algebraicity is transitive.)
\end{theorem}

\begin{wex}{A two-step algebraic tower is algebraic}
Let $E=\mathbb{Q}(\sqrt2)$ and $K=E(\sqrt{1+\sqrt2})$. Show $K/\mathbb{Q}$ is algebraic and compute $[K:\mathbb{Q}]$.
\wrec Theorem 13.20: $\sqrt{1+\sqrt2}$ is algebraic over $E$ and $E$ is algebraic over $\mathbb{Q}$, so $K/\mathbb{Q}$ is algebraic; the tower law gives the degree.
\wsol $\sqrt2$ is algebraic over $\mathbb{Q}$ ($x^2-2$), so $E/\mathbb{Q}$ is algebraic with $[E:\mathbb{Q}]=2$. Next $\beta=\sqrt{1+\sqrt2}$ satisfies $x^2-(1+\sqrt2)$ over $E$, irreducible since $1+\sqrt2$ is not a square in $E$ (a square $a+b\sqrt2$ would need $\sqrt{1+\sqrt2}\in E\subseteq\mathbb{R}$ with $E$ of degree $2$; checking $E=\mathbb{Q}(\sqrt2)$ shows no solution). So $[K:E]=2$ and, by transitivity/tower law, $K/\mathbb{Q}$ is algebraic with $[K:\mathbb{Q}]=2\cdot2=4$. Sanity check: $\beta^2=1+\sqrt2\Rightarrow(\beta^2-1)^2=2\Rightarrow\beta^4-2\beta^2-1=0$, so $\beta$ satisfies $x^4-2x^2-1\in\mathbb{Q}[x]$ (Eisenstein-free but irreducible over $\mathbb{Q}$), confirming $\deg_\mathbb{Q}\beta=4=[K:\mathbb{Q}]$.
\end{wex}

\begin{wex}{Composite of two algebraic extensions is algebraic}
Inside $\mathbb{C}$, let $E_1=\mathbb{Q}(\sqrt[3]2)$ and $E_2=\mathbb{Q}(\zeta_3)$. Show the composite $E_1E_2=\mathbb{Q}(\sqrt[3]2,\zeta_3)$ is algebraic over $\mathbb{Q}$ and finite, with degree $6$.
\wrec The composite is generated by finitely many algebraic elements, so Theorem 13.17 makes it finite (hence algebraic); the tower law and coprime degrees fix the value.
\wsol $E_1E_2=\mathbb{Q}(\sqrt[3]2,\zeta_3)$ is generated by the algebraic elements $\sqrt[3]2$ (degree $3$) and $\zeta_3$ (degree $2$). By Theorem 13.17 it is finite over $\mathbb{Q}$, hence algebraic. Degrees $3$ and $2$ are coprime, so as in an earlier example $[E_1E_2:\mathbb{Q}]=3\cdot2=6$. Sanity check: this composite is precisely the splitting field of $x^3-2$ over $\mathbb{Q}$, whose degree we computed independently as $6$ --- the two computations agree.
\end{wex}

\begin{wex}{Doubling the cube is impossible}
Explain why $\sqrt[3]2$ is not constructible.
\wrec Constructible $\Rightarrow$ $[\mathbb{Q}(\alpha):\mathbb{Q}]$ is a power of $2$ (tower of quadratic extensions). A degree not of that form is an obstruction.
\wsol $[\mathbb{Q}(\sqrt[3]2):\mathbb{Q}]=3$, which is not a power of $2$. By the principle above, $\sqrt[3]2$ is not constructible, so the cube cannot be doubled with straightedge and compass. Sanity check: $3=\deg(x^3-2)$ and $3\nmid2^k$ for any $k$, exactly the divisibility failure.
\end{wex}

\begin{wex}{Trisecting a $60^\circ$ angle is impossible}
Show $\cos20^\circ$ is not constructible, so a general angle cannot be trisected.
\wrec Reduce trisection to a degree-$3$ algebraic obstruction via the triple-angle identity, then apply the power-of-$2$ criterion.
\wsol The identity $\cos3\theta=4\cos^3\theta-3\cos\theta$ at $\theta=20^\circ$ (so $3\theta=60^\circ$, $\cos60^\circ=\tfrac12$) gives $4\cos^3 20^\circ-3\cos20^\circ=\tfrac12$, i.e.\ with $\alpha=\cos20^\circ$, $8\alpha^3-6\alpha-1=0$. The polynomial $8x^3-6x-1$ has no rational root (rational root test: $\pm1,\pm\tfrac12,\pm\tfrac14,\pm\tfrac18$ all fail), so it is irreducible over $\mathbb{Q}$ and $[\mathbb{Q}(\alpha):\mathbb{Q}]=3$. Since $3$ is not a power of $2$, $\cos20^\circ$ is not constructible; hence the $60^\circ$ angle cannot be trisected. Sanity check: $60^\circ$ is itself constructible ($\cos60^\circ=\tfrac12\in\mathbb{Q}$), so the obstruction is exactly the degree-$3$ jump introduced by trisection.
\end{wex}

\begin{wex}{Squaring the circle is impossible}
Explain why a square of area equal to a given disk cannot be constructed.
\wrec Constructible numbers are algebraic (each $F_i/\mathbb{Q}$ is finite, hence algebraic). A transcendental target is therefore unreachable.
\wsol Squaring the circle of radius $1$ requires constructing a length $\sqrt\pi$, hence $\pi$. But every constructible number is algebraic over $\mathbb{Q}$ (it lies in a finite tower over $\mathbb{Q}$), while $\pi$ is transcendental (Lindemann). So $\sqrt\pi$ is not constructible and the circle cannot be squared. Sanity check: here the obstruction is not a wrong \emph{degree} but the failure of algebraicity altogether --- transcendence is the strongest possible barrier.
\end{wex}

\begin{theorem}\label{thm:field@c13}
The set of constructible real numbers is a subfield of $\mathbb{R}$ containing $\mathbb{Q}$.
Moreover it is closed under the operation $\alpha \mapsto \sqrt{\alpha}$ for
$\alpha > 0$.
\end{theorem}

\begin{theorem}\label{thm:tower@c13}
If $\alpha$ is a constructible real number, then there is a finite tower of
fields
\[
\mathbb{Q} = F_0 \subseteq F_1 \subseteq F_2 \subseteq \cdots \subseteq F_m \subseteq \mathbb{R}
\]
with $\alpha \in F_m$ and $[F_{i}:F_{i-1}] = 2$ for every $i$. In
particular $[F_m:\mathbb{Q}] = 2^m$ is a power of $2$.
\end{theorem}

\begin{corollary}\label{cor:power-of-two@c13}
If $\alpha$ is a constructible real number, then $\alpha$ is algebraic over
$\mathbb{Q}$ and $[\mathbb{Q}(\alpha):\mathbb{Q}] = \deg m_{\alpha,\mathbb{Q}}(x)$ is a power of $2$.
\end{corollary}

\begin{proof}
By Theorem~\ref{thm:tower@c13}, $\alpha \in F_m$ with $[F_m:\mathbb{Q}]=2^m$. Since
$\mathbb{Q} \subseteq \mathbb{Q}(\alpha) \subseteq F_m$, the tower law gives
$[F_m:\mathbb{Q}] = [F_m:\mathbb{Q}(\alpha)]\,[\mathbb{Q}(\alpha):\mathbb{Q}]$, so
$[\mathbb{Q}(\alpha):\mathbb{Q}]$ divides $2^m$ and is therefore a power of $2$.
\end{proof}

\begin{theorem}[Doubling the cube is impossible]\label{thm:double@c13}
There is no straightedge-and-compass construction producing, from an edge of a
cube, the edge of a cube with twice the volume.
\end{theorem}

\begin{proof}
Taking the given edge as the unit, the new edge has length $\beta$ with
$\beta^3 = 2$, i.e. $\beta = 2^{1/3}$. Its minimal polynomial over $\mathbb{Q}$ is
$x^3-2$ (Eisenstein), so $[\mathbb{Q}(\beta):\mathbb{Q}]=3$, not a power of $2$. By
Corollary~\ref{cor:power-of-two@c13}, $\beta$ is not constructible.
\end{proof}

\begin{theorem}[Trisecting a general angle is impossible]\label{thm:trisect@c13}
There is no construction that trisects an arbitrary constructible angle. In
particular the angle $60^\circ$ cannot be trisected.
\end{theorem}

\begin{theorem}[Squaring the circle is impossible]\label{thm:square@c13}
There is no construction producing a square whose area equals that of a given
circle.
\end{theorem}

\begin{remark}
Doubling the cube and trisecting $60^\circ$ are pure degree obstructions: the
target has degree $3$. Squaring the circle is deeper -- it fails not on a degree
count but because $\pi$ is not even algebraic, so it lies outside \emph{every}
finite tower over $\mathbb{Q}$. The transcendence of $\pi$ (Lindemann, 1882) is the only
non-algebraic input to this entire section.
\end{remark}

\begin{proposition}\label{prop:zeta@c13}
The regular $n$-gon is constructible if and only if $\zeta_n$ is constructible.
A \emph{necessary} condition is that $[\mathbb{Q}(\zeta_n):\mathbb{Q}] = \varphi(n)$ be a
power of $2$.
\end{proposition}

\begin{theorem}[{Gauss--Wantzel}]\label{thm:gauss@c13}
The regular $n$-gon is constructible if and only if $n = 2^{a} p_1 p_2 \cdots p_r$
with $a\ge 0$ and $p_1,\dots,p_r$ distinct Fermat primes, i.e. primes of the form
$2^{2^{k}}+1$.
\end{theorem}

\begin{proof}
Apply the theorem with $F'=F$ and $\varphi=\id_F$. Then $f'=f$, and any two
splitting fields $K,K'$ satisfy $\sigma:K\to K'$ with $\sigma|_F=\id_F$.
\end{proof}

\begin{remark}
Equivalently, $\overline F$ is a splitting field over $F$ of the set of
\emph{all} polynomials in $F[x]$. The condition that $\overline F$ be
algebraic over $F$ keeps it minimal: $\overline F$ adds only roots of
$F$-polynomials, nothing transcendental.
\end{remark}

\begin{lemma}
If $\overline F$ is algebraic over $F$ and every polynomial in $F[x]$
splits in $\overline F$, then $\overline F$ is algebraically closed (hence
an algebraic closure of $F$).
\end{lemma}

\begin{exers}{Exercises (from the text).}
\item Determine the splitting field and its degree over $\mathbb{Q}$ for $x^4 - 2$.
\item Determine the splitting field and its degree over $\mathbb{Q}$ for $x^4 + 2$.
\item Determine the splitting field and its degree over $\mathbb{Q}$ for $x^4 + x^2 + 1$.
\item Determine the splitting field and its degree over $\mathbb{Q}$ for $x^6 - 4$.
\item Let $K$ be a finite extension of $F$. Prove that $K$ is a splitting field over $F$ if and only if every irreducible polynomial in $F[x]$ that has a root in $K$ splits completely in $K[x]$. [Use Theorems 8 and 27.]
\item Let $K_1$ and $K_2$ be finite extensions of $F$ contained in the field $K$, and assume both are splitting fields over $F$.
\begin{enumerate}
\item[(a)] Prove that their composite $K_1 K_2$ is a splitting field over $F$.
\item[(b)] Prove that $K_1 \cap K_2$ is a splitting field over $F$. [Use the preceding exercise.]
\end{enumerate}
\end{exers}

\begin{definition}
A nonzero polynomial $f(x)\in F[x]$ has a \emph{repeated root} $\alpha$ (in a
splitting field) if $(x-\alpha)^2\mid f(x)$, i.e.\ the multiplicity of $\alpha$
is at least $2$. We call $f$ \emph{separable} if it has no repeated roots in a
splitting field, and \emph{inseparable} otherwise.
\end{definition}

\begin{proposition}
A polynomial $f$ has a repeated root $\alpha$ if and only if $\alpha$ is also a
root of $D_x f$; equivalently, $f$ has a repeated root if and only if
$\gcd\!\big(f,\,D_x f\big)$ has positive degree. In particular $f$ is separable
if and only if $\gcd\!\big(f,\,D_x f\big)=1$.
\end{proposition}

\begin{remark}
The point is that $\gcd(f,D_x f)$ may be computed in $F[x]$ itself, and the gcd
is unchanged under field extension. So separability is detected without
factoring $f$ and without naming a single root.
\end{remark}

\begin{proof}
If $p$ is irreducible then $\gcd(p,D_x p)$ is either $1$ or $p$ (up to units),
since the only monic divisors of $p$ are $1$ and $p$. Now $\deg D_x p<\deg p$,
so $\gcd(p,D_x p)=p$ forces $D_x p=0$. Thus $p$ is inseparable iff $D_x p=0$. If
$\charac F=0$ and $p$ is nonconstant, the leading term $n a_n x^{n-1}$ of $D_x p$
has $n a_n\neq0$, so $D_x p\neq0$ and $p$ is separable. If $\charac F=p$, then
$D_x p=\sum k a_k x^{k-1}=0$ forces $k a_k=0$, i.e.\ $a_k=0$ whenever $p\nmid k$;
the surviving exponents are multiples of $p$, so $p(x)=g(x^p)$.
\end{proof}

\begin{definition}
A field $F$ is \emph{perfect} if either $\charac F=0$, or $\charac F=p>0$ and the
Frobenius map $F\to F$, $a\mapsto a^p$, is surjective (equivalently
$F=F^p$). For $\charac p$ fields, perfection says every element has a $p$-th
root in $F$.
\end{definition}

\begin{proposition}
Every irreducible polynomial over a perfect field $F$ is separable; hence a polynomial
in $F[x]$ is separable if and only if it is a product of distinct (pairwise
non-associate) irreducible polynomials. Every field of
characteristic $0$ and every finite field is perfect.
\end{proposition}

\begin{theorem}
The multiplicative group $\F_{p^n}^{\,\times}$ is cyclic of order $p^n-1$.
\end{theorem}

\begin{definition}
Let $\charac F=p$. An element $\alpha$ algebraic over $F$ is \emph{purely
inseparable} over $F$ if $m_{\alpha,F}(x)=x^{p^k}-a$ for some $a\in F$ and
$k\ge0$, equivalently $\alpha^{p^k}\in F$. An extension $K/F$ is \emph{purely
inseparable} if every element of $K$ is purely inseparable over $F$.
\end{definition}

\begin{corollary}
Over a perfect field every algebraic extension is separable, and the only purely
inseparable extension is the trivial one $F/F$. In particular, finite fields and
$\charac0$ fields have no nontrivial purely inseparable extensions.
\end{corollary}

