\begin{exers}{Practice problems.}
\item For each polynomial, compute the formal derivative $f'(x)$, then use $\gcd(f,f')$ to decide whether $f$ has a repeated root in $\overline{F}$.
 \begin{enumerate}
 \item $f(x) = x^4 - 2x^2 + 1$ over $Q$.
 \item $f(x) = x^3 - 3x + 2$ over $Q$.
 \item $f(x) = x^5 + x^4 + x^3 + x^2 + x + 1$ over $Q$.
 \end{enumerate}

\item Work over $\F = Z/(3)Z$. Let $f(x) = x^6 + x^3 + 1$.
 \begin{enumerate}
 \item Compute $f'(x)$ and observe that it is the zero polynomial in $\F[x]$. Explain, without factoring $f$, why $f'=0$ means $f$ is a polynomial in $x^3$, and why this forces every root of $f$ in $\overline{\F}$ to be repeated.
 \item Show that $f(x) = (x-1)^6$ in $\F[x]$, and reconcile this with your derivative computation. (Hint: $x^6+x^3+1 = (x^3-1)^2$, and $x^3 - 1 = (x-1)^3$ over $\F$.)
 \end{enumerate}

\item Let $p$ be a prime and consider $g(x) = x^p - a \in \F_p(t)[x]$ where $\F_p(t)$ is the rational function field and $a = t$.
 \begin{enumerate}
 \item Compute $g'(x)$ and conclude $\gcd(g,g') = g$.
 \item Show $g(x) = (x - t^{1/p})^p$ over a splitting field, and explain why every root of $g$ is repeated. This is the standard example of an inseparable irreducible polynomial.
 \end{enumerate}

\item Determine the number of distinct roots of $x^{16} - x$ over $\F_2$, and prove that this polynomial equals the product of all monic irreducible polynomials in $\F_2[x]$ whose degree divides $4$. List the possible degrees of those irreducible factors.

\item Inside a fixed algebraic closure $\overline{\F_2}$, decide which of $\F_4$, $\F_8$, $\F_{16}$ contain $\F_4$ as a subfield. State the general containment rule for $\F_{p^m} \subseteq \F_{p^n}$ and prove the direction $m \mid n \implies \F_{p^m} \subseteq \F_{p^n}$ using that $\F_{p^n}$ is the splitting field of $x^{p^n} - x$.

\item Let $\alpha$ be a generator of the cyclic group $\F_{16}^\times$.
 \begin{enumerate}
 \item Compute $\ord{\alpha}$ and $\abs{\F_{16}^\times}$.
 \item Determine $[\F_2(\alpha):\F_2]$ and deduce $m_{\alpha,\F_2}(x)$ has degree $4$.
 \item How many distinct generators does $\F_{16}^\times$ have? Express your answer using $\varphi$.
 \end{enumerate}

\item Let $\sigma : \F_{p^n} \to \F_{p^n}$ be the Frobenius endomorphism $x \mapsto x^p$.
 \begin{enumerate}
 \item Prove $\sigma$ is a field homomorphism, i.e. verify $\sigma(x+y) = \sigma(x) + \sigma(y)$ and $\sigma(xy) = \sigma(x)\sigma(y)$, citing the binomial coefficients $\binom{p}{k} \equiv 0 \pmod p$ for $0 < k < p$.
 \item Show $\sigma$ is injective, hence bijective on the finite field $\F_{p^n}$.
 \item Identify the fixed field $\{x \in \F_{p^n} : \sigma(x) = x\}$ and compute its size.
 \item Show $\sigma$ has order $n$ as an element of $\Aut(\F_{p^n})$, i.e. $\sigma^n = \id$ but $\sigma^d \neq \id$ for $0 < d < n$.
 \end{enumerate}

\item Let $K = \F_p(t^{1/p}, u^{1/p})$ where $t,u$ are independent transcendentals over $\F_p$ and $F = \F_p(t,u)$.
 \begin{enumerate}
 \item Show each of $t^{1/p}, u^{1/p}$ is purely inseparable over $F$ and compute $[F(t^{1/p}):F]$.
 \item Compute $[K:F]$.
 \item Show $x^p - t \in F[x]$ is irreducible, and conclude $F$ is not a perfect field.
 \end{enumerate}

\item Decide whether each irreducible polynomial is separable. Justify each answer by either citing perfectness of the ground field or computing $\gcd(f,f')$.
 \begin{enumerate}
 \item $x^3 - 2$ over $Q$.
 \item $x^4 + x + 1$ over $\F_2$.
 \item $x^p - t$ over $\F_p(t)$.
 \item $\Phi_7(x)$ over $Q$, where $\Phi_7$ is the $7$th cyclotomic polynomial.
 \end{enumerate}
\end{exers}

