\begin{exers}{Additional exercises.}
\item (Perfect fields.) A field $F$ of characteristic $p$ is \emph{perfect} iff the Frobenius map $x \mapsto x^p$ is surjective on $F$, i.e. $F = F^p$. Prove that every finite field is perfect, and prove that every field of characteristic $0$ is perfect (vacuously, by showing every irreducible polynomial there is separable). Then exhibit one imperfect field with proof.

\item (Counting irreducibles.) Let $N_d$ be the number of monic irreducible polynomials of degree $d$ in $\F_p[x]$. Using $x^{p^n} - x = \prod_{d \mid n} \big(\text{product of monic irreducibles of degree } d\big)$, derive the degree identity $p^n = \sum_{d \mid n} d\, N_d$. Use it to compute $N_1, N_2, N_3, N_4$ for $p = 2$ explicitly.

\item (Separable degree of a tower.) Let $F = \F_3(t)$, and let $\alpha$ be a root of $x^9 - t \in F[x]$ and $\beta = \alpha^3$, so $\beta^3 = t$.
  \begin{enumerate}
    \item Show $m_{\beta,F}(x) = x^3 - t$ and $m_{\alpha,F(\beta)}(x) = x^3 - \beta$, each purely inseparable.
    \item Compute $[F(\alpha):F]$ and explain why no element of $F(\alpha) \setminus F$ is separable over $F$.
  \end{enumerate}

\item (Multiplicity of a root.) Let $f(x) \in F[x]$ and $\alpha \in \overline{F}$. Prove that $\alpha$ is a root of $f$ of multiplicity $\geq 2$ iff $f(\alpha) = f'(\alpha) = 0$. Then determine, over $\F_5$, the multiplicity of $x = 2$ as a root of $f(x) = x^4 - 3x^3 + x^2 + 4$.

\item (Splitting field as fixed locus.) Prove that $\F_{p^n}$ is precisely the set of roots of $x^{p^n} - x$ in $\overline{\F_p}$, and that these $p^n$ roots are all distinct. Deduce both the existence and the uniqueness (inside a fixed $\overline{\F_p}$) of the field with $p^n$ elements. Where in the argument is separability of $x^{p^n} - x$ used?
\end{exers}

\begin{exers}{Commutative-diagram exercises.}
\item Let $\sigma : \F_{p^n} \to \F_{p^n}$ be the Frobenius $x \mapsto x^p$ and let $\iota : \F_p \hookrightarrow \F_{p^n}$ be the inclusion. Draw the square
\[
\begin{tikzcd}
\F_p \arrow[r, hook, "\iota"] \arrow[d, "\id"'] & \F_{p^n} \arrow[d, "\sigma"] \\
\F_p \arrow[r, hook, "\iota"'] & \F_{p^n}
\end{tikzcd}
\]
and prove it commutes (i.e. $\sigma$ restricts to the identity on the prime field). Explain why this exhibits $\sigma$ as an $\F_p$-algebra automorphism.

\item For $m \mid n$, let $\sigma$ be the Frobenius on $\F_{p^n}$. Consider
\[
\begin{tikzcd}[column sep=large]
\F_{p^n} \arrow[r, "\sigma^m"] \arrow[d, hook, "\subseteq"'] & \F_{p^n} \arrow[d, hook', "\subseteq"] \\
\overline{\F_p} \arrow[r, "{x \mapsto x^{p^m}}"'] & \overline{\F_p}
\end{tikzcd}
\]
Show the diagram commutes, and prove that the fixed field of $\sigma^m$ on $\F_{p^n}$ equals $\F_{p^m}$. Conclude $\F_{p^m}$ is the unique subfield of $\F_{p^n}$ of degree $m$ over $\F_p$.

\item Let $F$ have characteristic $p$ and let $\alpha \in \overline{F}$, $\alpha \notin F$, be purely inseparable over $F$ with $\alpha^{p} = a \in F$. Let $K = F(\alpha)$ and consider the Frobenius maps making the square
\[
\begin{tikzcd}
F \arrow[r, hook, "\subseteq"] \arrow[d, "{x \mapsto x^p}"'] & K \arrow[d, "{x \mapsto x^p}"] \\
F \arrow[r, hook, "\subseteq"'] & K
\end{tikzcd}
\]
Show this commutes, and use it to prove $K^p \subseteq F$, hence $[K:F] = p$. Why does this force $m_{\alpha,F}(x) = x^p - a$?

\item Let $E$ be the splitting field of $x^{p^n} - x$ over $\F_p$ and let $\varphi : E \to E$ be the Frobenius. Given a tower $\F_p \subseteq \F_{p^d} \subseteq E$ with $d \mid n$, fill in and prove commutativity of
\[
\begin{tikzcd}
\F_{p^d} \arrow[r, hook, "\subseteq"] \arrow[d, "\varphi^d"'] & E \arrow[d, "\varphi^d"] \\
\F_{p^d} \arrow[r, hook, "\subseteq"'] & E
\end{tikzcd}
\]
where the left arrow is the identity on $\F_{p^d}$. Explain how this realizes $\Aut(E/\F_p)$ as the cyclic group $\langle \varphi\rangle$ of order $n$, with $\Aut(E/\F_{p^d}) = \langle \varphi^d\rangle$.

\item Let $F = \F_p(t)$ and $K = F(t^{1/p})$, a purely inseparable extension. Writing $\beta = t^{1/p}$, show there is exactly one $F$-algebra homomorphism $K \to \overline{F}$ by completing
\[
\begin{tikzcd}
F \arrow[r, hook, "\subseteq"] \arrow[rd, hook', "\subseteq"'] & K \arrow[d, dashed, "\exists !\,\psi"] \\
 & \overline{F}
\end{tikzcd}
\]
Prove $\psi$ must send $\beta \mapsto \beta$ because $x^p - t = (x - \beta)^p$ has $\beta$ as its only root. Contrast this with the separable case, where the number of such extensions equals the number of distinct roots of $m_{\beta,F}(x)$.
\end{exers}

\begin{remark}
$\mu_n$ is a finite subgroup of the multiplicative group of a field; every finite subgroup of $F^{\times}$ is cyclic, which re-proves cyclicity without reference to $\mathbb{C}$. Thus $\mu_n\cong\mathbb{Z}/(n)\mathbb{Z}$ as abelian groups.
\end{remark}

\begin{definition}
A generator of the cyclic group $\mu_n$ is a \emph{primitive $n$-th root of unity}; we write a fixed choice as $\zeta_n$. In $\mathbb{C}$ we take $\zeta_n=e^{2\pi i/n}$. An element $\zeta_n^{\,a}$ is primitive (i.e.\ has order exactly $n$) if and only if $\gcd(a,n)=1$, so the number of primitive $n$-th roots of unity is $\varphi(n)$.
\end{definition}

\begin{wex}{Listing $\mu_n$ and its generators for small $n$}
For $n=1,2,3,4,6$ list $\mu_n\subset\mathbb{C}$ and identify the primitive roots.
\wrec Use $\mu_n=\{e^{2\pi ik/n}\}$; primitive roots are the $\zeta_n^{\,a}$ with $\gcd(a,n)=1$, and there are $\varphi(n)$ of them.
\wsol $\mu_1=\{1\}$ (primitive: $1$). $\mu_2=\{1,-1\}$ (primitive: $-1$; $\varphi(2)=1$). $\mu_3=\{1,\omega,\omega^2\}$ with $\omega=e^{2\pi i/3}=\tfrac{-1+\sqrt{-3}}{2}$ (primitive: $\omega,\omega^2$; $\varphi(3)=2$). $\mu_4=\{1,i,-1,-i\}$ (primitive: $i,-i$; $\varphi(4)=2$). $\mu_6=\{\pm1,\pm\omega,\pm\omega^2\}$ with primitive roots $e^{\pm\pi i/3}=\tfrac{1\pm\sqrt{-3}}{2}$ (so $\varphi(6)=2$). Sanity check: in each case $\#\{\text{primitive}\}=\varphi(n)$, and $1+\varphi(2)+\varphi(3)+\varphi(4)+\varphi(6)$ correctly counts $1,1,2,2,2$.
\end{wex}

\begin{wex}{Which powers of $\zeta_{12}$ are primitive}
Inside $\mu_{12}=\langle \zeta_{12}\rangle$, determine which $\zeta_{12}^{\,a}$ are primitive $12$-th roots of unity, and identify the order of $\zeta_{12}^{\,8}$.
\wrec $\zeta_{12}^{\,a}$ has order $12/\gcd(a,12)$; it is primitive of order $12$ iff $\gcd(a,12)=1$.
\wsol The units mod $12$ are $a\in\{1,5,7,11\}$, so the primitive $12$-th roots are $\zeta_{12},\zeta_{12}^{5},\zeta_{12}^{7},\zeta_{12}^{11}$, and $\varphi(12)=4$. For $a=8$: $\gcd(8,12)=4$, so $\zeta_{12}^{\,8}$ has order $12/4=3$, i.e.\ it is a primitive cube root of unity. Sanity check: $(\zeta_{12}^{8})^3=\zeta_{12}^{24}=1$ and $(\zeta_{12}^{8})^1=\zeta_{12}^{8}\neq1$, confirming order $3$.
\end{wex}

\begin{theorem}[{integer coefficients}]
For every $n\ge1$, $\Phi_n(x)\in\mathbb{Z}[x]$; it is a monic polynomial of degree $\varphi(n)$ with integer coefficients.
\end{theorem}

\begin{proof}[Sketch]
Induct on $n$ using the recursion. For $n=1$, $\Phi_1(x)=x-1\in\mathbb{Z}[x]$. For the inductive step, $g(x)=\prod_{d\mid n,\,d<n}\Phi_d(x)$ is monic in $\mathbb{Z}[x]$, and it divides $x^n-1$ in $\mathbb{C}[x]$; division of one monic integer polynomial by another monic integer polynomial yields a quotient in $\mathbb{Z}[x]$ (the division algorithm stays inside $\mathbb{Z}[x]$ when the divisor is monic). Hence $\Phi_n(x)=(x^n-1)/g(x)\in\mathbb{Z}[x]$.
\end{proof}

\begin{wex}{Building $\Phi_n$ by the divisor recursion, $n\le 6$}
Compute $\Phi_1,\dots,\Phi_6$ from $x^n-1=\prod_{d\mid n}\Phi_d(x)$.
\wrec Apply $\Phi_n=(x^n-1)/\prod_{d\mid n,\,d<n}\Phi_d$ in increasing $n$.
\wsol $\Phi_1=x-1$. From $x^2-1=\Phi_1\Phi_2$: $\Phi_2=\tfrac{x^2-1}{x-1}=x+1$. From $x^3-1=\Phi_1\Phi_3$: $\Phi_3=\tfrac{x^3-1}{x-1}=x^2+x+1$. From $x^4-1=\Phi_1\Phi_2\Phi_4$: $\Phi_4=\tfrac{x^4-1}{(x-1)(x+1)}=\tfrac{x^4-1}{x^2-1}=x^2+1$. From $x^5-1=\Phi_1\Phi_5$: $\Phi_5=x^4+x^3+x^2+x+1$. From $x^6-1=\Phi_1\Phi_2\Phi_3\Phi_6$: $\Phi_6=\dfrac{x^6-1}{(x-1)(x+1)(x^2+x+1)}=\dfrac{x^6-1}{(x^2-1)(x^2+x+1)}=x^2-x+1$. Sanity check on degrees: $\varphi(1,2,3,4,5,6)=1,1,2,2,4,2$, matching the degrees obtained; and $\sum_{d\mid 6}\varphi(d)=\varphi(1)+\varphi(2)+\varphi(3)+\varphi(6)=1+1+2+2=6$.
\end{wex}

\begin{theorem}[{irreducibility of $\Phi_n$}]
For every $n\ge1$ the cyclotomic polynomial $\Phi_n(x)$ is irreducible over $\mathbb{Q}$. Equivalently, $\Phi_n(x)$ is the minimal polynomial over $\mathbb{Q}$ of any primitive $n$-th root of unity: $m_{\zeta_n,\mathbb{Q}}(x)=\Phi_n(x)$.
\end{theorem}

\begin{proof}[Idea]
By Gauss's Lemma it suffices to show $\Phi_n$ is irreducible in $\mathbb{Z}[x]$. Suppose $\Phi_n=f g$ with $f$ the (monic, integral) minimal polynomial of a fixed primitive root $\zeta$. One shows that for every prime $p\nmid n$, if $\zeta$ is a root of $f$ then $\zeta^{p}$ is again a root of $f$ (using that $f(x^p)\equiv f(x)^p\pmod p$, the $p$-th power map being a ring homomorphism in characteristic $p$ that fixes $\F_p$, so $f(\zeta^p)\equiv f(\zeta)^p\equiv0$ forces a repeated root unless $\zeta^p$ is a root of $f$). Iterating, every $\zeta^{a}$ with $\gcd(a,n)=1$ is a root of $f$, so $f$ has all $\varphi(n)$ primitive roots; thus $f=\Phi_n$ and $g$ is a unit.
\end{proof}

\begin{definition}
The field $\mathbb{Q}(\zeta_n)$ obtained by adjoining a primitive $n$-th root of unity to $\mathbb{Q}$ is the \emph{cyclotomic field} of $n$-th roots of unity.
\end{definition}

\begin{wex}{Degree of $\mathbb{Q}(\zeta_5)$ and a basis}
Find $[\mathbb{Q}(\zeta_5):\mathbb{Q}]$, the minimal polynomial of $\zeta_5$, and express $\zeta_5^{4}$ in the standard basis.
\wrec Corollary: $[\mathbb{Q}(\zeta_5):\mathbb{Q}]=\varphi(5)$ and $m_{\zeta_5,\mathbb{Q}}=\Phi_5$; reduce higher powers via $\Phi_5(\zeta_5)=0$.
\wsol $\varphi(5)=4$, so $[\mathbb{Q}(\zeta_5):\mathbb{Q}]=4$ with $m_{\zeta_5,\mathbb{Q}}(x)=\Phi_5(x)=x^4+x^3+x^2+x+1$ and basis $\{1,\zeta_5,\zeta_5^2,\zeta_5^3\}$. Although $\zeta_5^4$ would naively be the fourth basis vector, the relation $\Phi_5(\zeta_5)=0$ gives $\zeta_5^4=-1-\zeta_5-\zeta_5^2-\zeta_5^3$, already in the $4$-dimensional standard basis. Sanity check: multiplying that relation by $\zeta_5$ and using $\zeta_5^5=1$ returns $1=-\zeta_5-\zeta_5^2-\zeta_5^3-\zeta_5^4$, the same relation, confirming consistency.
\end{wex}

\begin{wex}{$\mathbb{Q}(\zeta_3)$ as a quadratic field}
Identify $\mathbb{Q}(\zeta_3)$ explicitly and compute its degree.
\wrec $\zeta_3=\omega$ has minimal polynomial $\Phi_3(x)=x^2+x+1$, degree $\varphi(3)=2$.
\wsol Since $\omega=\tfrac{-1+\sqrt{-3}}{2}$, we get $\mathbb{Q}(\zeta_3)=\mathbb{Q}(\sqrt{-3})$, an imaginary quadratic field, and $[\mathbb{Q}(\zeta_3):\mathbb{Q}]=2=\varphi(3)$. Sanity check: $\omega$ satisfies $x^2+x+1=0$, i.e.\ $2\omega+1=\sqrt{-3}$, so $\sqrt{-3}\in\mathbb{Q}(\zeta_3)$ and conversely $\omega=\tfrac{-1+\sqrt{-3}}{2}\in\mathbb{Q}(\sqrt{-3})$; the two fields coincide. Likewise $\mathbb{Q}(\zeta_4)=\mathbb{Q}(i)$ with $[\mathbb{Q}(i):\mathbb{Q}]=2=\varphi(4)$.
\end{wex}

\begin{wex}{Compositum of cyclotomic fields}
Compute $[\mathbb{Q}(\zeta_3,\zeta_4):\mathbb{Q}]$ and identify $\mathbb{Q}(\zeta_3,\zeta_4)$ as a single cyclotomic field.
\wrec Use $\mathbb{Q}(\zeta_m,\zeta_n)=\mathbb{Q}(\zeta_{\lcm(m,n)})$ and, when $\gcd(m,n)=1$, multiplicativity $\varphi(mn)=\varphi(m)\varphi(n)$.
\wsol Since $\gcd(3,4)=1$, $\lcm(3,4)=12$ and $\zeta_3\zeta_4$ is a primitive $12$-th root, so $\mathbb{Q}(\zeta_3,\zeta_4)=\mathbb{Q}(\zeta_{12})$. Then $[\mathbb{Q}(\zeta_{12}):\mathbb{Q}]=\varphi(12)=\varphi(3)\varphi(4)=2\cdot2=4$. Sanity check: $\mathbb{Q}(\zeta_3)=\mathbb{Q}(\sqrt{-3})$ and $\mathbb{Q}(\zeta_4)=\mathbb{Q}(i)$ are distinct quadratic fields, so their compositum has degree $2\cdot2=4$ over $\mathbb{Q}$ (the two square roots $\sqrt{-3},i$ are independent), matching $\varphi(12)=4$; note $\sqrt3=\sqrt{-3}/i\in\mathbb{Q}(\zeta_{12})$ as well.
\end{wex}

\begin{wex}{When $\zeta_n$ generates the same field for different $n$}
Explain why $\mathbb{Q}(\zeta_n)=\mathbb{Q}(\zeta_{2n})$ when $n$ is odd, illustrated by $n=3$.
\wrec For $n$ odd, $\varphi(2n)=\varphi(2)\varphi(n)=\varphi(n)$, and $-\zeta_n$ is a primitive $2n$-th root of unity.
\wsol If $n$ is odd then $\gcd(2,n)=1$, so $\varphi(2n)=\varphi(n)$, hence $[\mathbb{Q}(\zeta_{2n}):\mathbb{Q}]=[\mathbb{Q}(\zeta_n):\mathbb{Q}]$. Moreover $-\zeta_n$ has order $\lcm(2,n)=2n$, so $\zeta_{2n}\in\langle -\zeta_n\rangle\subseteq\mathbb{Q}(\zeta_n)$ and the fields coincide. For $n=3$: $\mathbb{Q}(\zeta_6)=\mathbb{Q}(\zeta_3)=\mathbb{Q}(\sqrt{-3})$, both of degree $2$. Sanity check: $\Phi_6(x)=x^2-x+1$ and $\Phi_3(x)=x^2+x+1$ satisfy $\Phi_6(x)=\Phi_3(-x)$, confirming $\zeta_6=-\zeta_3^{\,k}$ and equality of fields.
\end{wex}

