\begin{exers}{Commutative-diagram exercises.}
\item Let $\zeta = \zeta_n$. There is a canonical isomorphism $\Aut(\mathbb{Q}(\zeta_n)/\mathbb{Q}) \cong (\mathbb{Z}/(n)\mathbb{Z})^{\times}$ sending an automorphism $\sigma$ to the unit $a$ with $\sigma(\zeta) = \zeta^a$. Verify that this map is a group homomorphism by checking that the square below commutes, where the vertical maps send $\sigma$ to its unit $a$ (componentwise on the left), the bottom map is multiplication of the corresponding units and the top map is composition $\sigma, \tau \mapsto \sigma \circ \tau$.
\[
\begin{tikzcd}
\Aut(\mathbb{Q}(\zeta_n)/\mathbb{Q}) \times \Aut(\mathbb{Q}(\zeta_n)/\mathbb{Q}) \arrow[r, "{\circ}"] \arrow[d] & \Aut(\mathbb{Q}(\zeta_n)/\mathbb{Q}) \arrow[d] \\
(\mathbb{Z}/(n)\mathbb{Z})^{\times} \times (\mathbb{Z}/(n)\mathbb{Z})^{\times} \arrow[r, "{(a,b)\,\mapsto\,ab}"] & (\mathbb{Z}/(n)\mathbb{Z})^{\times}
\end{tikzcd}
\]
Then specialize to $n = 5$ and exhibit the resulting isomorphism with the cyclic group $(\mathbb{Z}/(5)\mathbb{Z})^{\times} \cong \mathbb{Z}/(4)\mathbb{Z}$ explicitly.

\item For $d \mid n$, inclusion of roots of unity gives $\mu_d \subseteq \mu_n$ and a corresponding field inclusion $\mathbb{Q}(\zeta_d) \subseteq \mathbb{Q}(\zeta_n)$ (take $\zeta_d = \zeta_n^{n/d}$). Show that every $\sigma \in \Aut(\mathbb{Q}(\zeta_n)/\mathbb{Q})$ maps $\mathbb{Q}(\zeta_d)$ onto itself, so that restriction $\sigma \mapsto \sigma|_{\mathbb{Q}(\zeta_d)}$ is a homomorphism $\Aut(\mathbb{Q}(\zeta_n)/\mathbb{Q}) \to \Aut(\mathbb{Q}(\zeta_d)/\mathbb{Q})$, and that the diagram below commutes, where the vertical maps are the isomorphisms of the previous exercise and the bottom map is reduction mod $d$, the surjection $(\mathbb{Z}/(n)\mathbb{Z})^{\times} \to (\mathbb{Z}/(d)\mathbb{Z})^{\times}$.
\[
\begin{tikzcd}[column sep=huge]
\Aut(\mathbb{Q}(\zeta_n)/\mathbb{Q}) \arrow[r, "{\sigma\,\mapsto\,\sigma|_{\mathbb{Q}(\zeta_d)}}"] \arrow[d, "{\cong}"'] & \Aut(\mathbb{Q}(\zeta_d)/\mathbb{Q}) \arrow[d, "{\cong}"] \\
(\mathbb{Z}/(n)\mathbb{Z})^{\times} \arrow[r, "{\bmod\ d}"'] & (\mathbb{Z}/(d)\mathbb{Z})^{\times}
\end{tikzcd}
\]
Illustrate with $d = 3$, $n = 12$, computing both unit groups and the reduction map.

\item Let $p$ be a prime not dividing $n$ and consider reduction of coefficients modulo $p$, the ring map $\mathbb{Z}[x] \to \F_p[x]$. Since $\Phi_n(x) \in \mathbb{Z}[x]$, it has a well-defined image $\overline{\Phi_n}(x) \in \F_p[x]$. Show that the square commutes, where the top map is the divisor-product factorization over $\mathbb{Z}$ and the bottom is the same factorization over $\F_p$, and the vertical maps are coefficient reduction:
\[
\begin{tikzcd}[column sep=7em]
{\mathbb{Z}[x]} \arrow[r, "{x^n - 1\, \mapsto\, \prod_{d \mid n}\Phi_d}"] \arrow[d, "{\bmod\ p}"'] & {\mathbb{Z}[x]} \arrow[d, "{\bmod\ p}"] \\
{\F_p[x]} \arrow[r, "{x^n - 1\, \mapsto\, \prod_{d \mid n}\overline{\Phi_d}}"'] & {\F_p[x]}
\end{tikzcd}
\]
Use commutativity to explain why $x^n - 1$ remains separable over $\F_p$ exactly when $p \nmid n$.

\item Let $K = \mathbb{Q}(\zeta_8)$ with the three quadratic subfields $\mathbb{Q}(i)$, $\mathbb{Q}(\sqrt{2})$, $\mathbb{Q}(\sqrt{-2})$ corresponding to the three index-$2$ subgroups of $(\mathbb{Z}/(8)\mathbb{Z})^{\times} \cong \mathbb{Z}/(2)\mathbb{Z} \times \mathbb{Z}/(2)\mathbb{Z}$. Draw the lattice of intermediate fields as a commutative diagram of inclusions:
\[
\begin{tikzcd}
& \mathbb{Q}(\zeta_8) & \\
\mathbb{Q}(i) \arrow[ur, hook] & \mathbb{Q}(\sqrt{2}) \arrow[u, hook] & \mathbb{Q}(\sqrt{-2}) \arrow[ul, hook] \\
& \mathbb{Q} \arrow[ul, hook] \arrow[u, hook] \arrow[ur, hook] &
\end{tikzcd}
\]
Label each edge with its relative degree, confirm the top-to-bottom degree is $\varphi(8) = 4$, and match each intermediate field to its corresponding subgroup of $(\mathbb{Z}/(8)\mathbb{Z})^{\times}$.
\end{exers}

\begin{remark}
The two methods are dual faces of the same vector-space fact. Method 1 reads off a
dependence among powers and trusts a \emph{monomial basis} to certify its degree;
Method 2 names the conjugates and lets the field automorphisms do the cancellation.
When you can guess the conjugates, Method 2 is faster and self-certifying (a product
of $[F(\alpha):F]$ distinct conjugates is automatically the minimal polynomial).
When you cannot, Method 1 always terminates -- provided you take the \emph{first}
dependence among $1,\alpha,\alpha^2,\dots$ (a basis of $K$ lets you detect it), so that the
reducible-relation pitfall cannot pass off a proper multiple of the minimal polynomial
as the minimal polynomial.
\end{remark}

\begin{definition}
A real number $a$ is \emph{constructible} if the point $(a,0)$ is constructible.
Since perpendiculars and lengths can be marked off, $a$ is constructible iff it
is a coordinate of some constructible point, iff some pair of constructible
points lies at distance $\abs{a}$.
\end{definition}

\begin{corollary}[Degree obstruction]
\label{art:constructible_ngons:degree@c13}
If $a\in\mathbb{R}$ is constructible, then $a$ is algebraic over $\mathbb{Q}$ and $[\mathbb{Q}(a):\mathbb{Q}]$
is a power of $2$.
\end{corollary}

\begin{proof}
By Theorem~\ref{art:constructible_ngons:tower@c13}, $a\in K$ with $[K:\mathbb{Q}]=2^n$.
Since $\mathbb{Q}(a)\subseteq K$, the tower law gives
$[\mathbb{Q}(a):\mathbb{Q}]\mid[K:\mathbb{Q}]=2^n$, so $[\mathbb{Q}(a):\mathbb{Q}]$ is itself a power of $2$.
\end{proof}

\begin{corollary}[Prime polygons force Fermat primes]
\label{art:constructible_ngons:fermat@c13}
Let $p$ be an odd prime. If the regular $p$-gon is constructible, then
$p=2^{2^k}+1$ for some $k\ge0$, i.e.\ $p$ is a \emph{Fermat prime}.
\end{corollary}

\begin{theorem}[Riemann Existence Theorem]\label{art:function_fields:rem@c13}
There is a bijective correspondence
\[
  \left\{\,\parbox{2.7cm}{\centering isomorphism classes of degree-$n$
  function fields over $F$}\,\right\}
  \;\longleftrightarrow\;
  \left\{\,\parbox{3.2cm}{\centering isomorphism classes of connected,
  $n$-sheeted branched coverings of $T$}\,\right\},
\]
under which the class of the extension $K=F[x]/(f)$ defined by an irreducible
$f(t,x)$ corresponds to the class of its Riemann surface $X=\{f=0\}$.
\end{theorem}

