\begin{corollary}
$\mathbb{C}$ is algebraically closed: every $f\in\mathbb{C}[x]$ of degree $n\ge1$ factors as
$f(x)=c\prod_{j=1}^{n}(x-\alpha_{j})$ with $c,\alpha_{j}\in\mathbb{C}$.
\end{corollary}

\begin{proof}
The theorem gives one root $\alpha_{1}$; divide by $x-\alpha_{1}$ and induct on
degree. The quotient is a complex polynomial of degree $n-1$, which again has a
root, and so on until the degree is $0$.
\end{proof}

\begin{lemma}[{an $F$-automorphism is determined by its values on generators}]
If $K=F(\alpha_1,\dots,\alpha_n)$ and $\sigma,\tau\in\Aut(K/F)$ satisfy $\sigma(\alpha_i)=\tau(\alpha_i)$ for all $i$, then $\sigma=\tau$. In particular $\sigma=\id$ iff $\sigma$ fixes a generating set.
\end{lemma}

\begin{proof}[Idea]
Every element of $K=F(\alpha_1,\dots,\alpha_n)$ is built from the $\alpha_i$ and elements of $F$ by the four field operations. Since $\sigma$ fixes $F$ and commutes with all four operations, its value on such an expression is forced once the values $\sigma(\alpha_i)$ are fixed. Thus agreeing on the $\alpha_i$ (and on $F$) forces agreement everywhere.
\end{proof}

\begin{wex}{Reading an automorphism off a single generator}
Show that any $\sigma\in\Aut(\mathbb{Q}(\sqrt2)/\mathbb{Q})$ is determined by the single value $\sigma(\sqrt2)$, and list the only possible values.
\wrec By the lemma, $\sigma$ is determined by its action on the generator $\sqrt2$ of $\mathbb{Q}(\sqrt2)$ over $\mathbb{Q}$; the value must itself be a root of the minimal polynomial of $\sqrt2$ (next subsection).
\wsol A general element is $a+b\sqrt2$ with $a,b\in\mathbb{Q}$, and $\sigma(a+b\sqrt2)=a+b\,\sigma(\sqrt2)$ because $\sigma$ fixes $\mathbb{Q}$. So $\sigma$ is pinned down by $\sigma(\sqrt2)$. Applying $\sigma$ to $(\sqrt2)^2=2$ gives $\sigma(\sqrt2)^2=\sigma(2)=2$, so $\sigma(\sqrt2)=\pm\sqrt2$. Thus there are at most two automorphisms. Sanity check: both candidates are realizable -- $\sigma(\sqrt2)=\sqrt2$ gives the identity, and $\sigma(\sqrt2)=-\sqrt2$ gives a well-defined ring map since $\mathbb{Q}(\sqrt2)\cong\mathbb{Q}[x]/(x^2-2)$ and $-\sqrt2$ is also a root of $x^2-2$.
\end{wex}

\begin{wex}{Complex conjugation as an automorphism}
Verify that $\tau:\mathbb{C}\to\mathbb{C}$, $\tau(a+bi)=a-bi$, is an element of $\Aut(\mathbb{C}/\mathbb{R})$, and find its order.
\wrec An $\mathbb{R}$-automorphism is a bijective ring map fixing $\mathbb{R}$; conjugation visibly fixes $\mathbb{R}$ ($b=0$) and is its own inverse.
\wsol For $z=a+bi,\ w=c+di$: $\tau(z+w)=(a+c)-(b+d)i=\tau(z)+\tau(w)$, and $\tau(zw)=\tau((ac-bd)+(ad+bc)i)=(ac-bd)-(ad+bc)i=(a-bi)(c-di)=\tau(z)\tau(w)$. Also $\tau(1)=1$ and $\tau$ fixes every real number, so $\tau\in\Aut(\mathbb{C}/\mathbb{R})$. Finally $\tau^2(a+bi)=\tau(a-bi)=a+bi$, so $\tau^2=\id$ and $\tau\neq\id$, giving $\ord{\tau}=2$. Sanity check: $[\mathbb{C}:\mathbb{R}]=2$, and $\Aut(\mathbb{C}/\mathbb{R})=\{\id,\tau\}\cong\mathbb{Z}/(2)\mathbb{Z}$ has order equal to the degree -- exactly what the bound below predicts for this (Galois) extension.
\end{wex}

\begin{proposition}[{$\sigma$ permutes the roots of an $F$-polynomial}]
Let $\sigma\in\Aut(K/F)$ and let $p(x)\in F[x]$. If $\alpha\in K$ is a root of $p$, then $\sigma(\alpha)$ is also a root of $p$. Consequently $\sigma$ permutes the set of roots of $p$ lying in $K$, and if $p$ is irreducible over $F$ then $\sigma$ sends each root of $p$ to another root of $p$.
\end{proposition}

\begin{proof}[Idea]
Write $p(x)=\sum_i c_i x^i$ with $c_i\in F$. Applying $\sigma$ to the equation $\sum_i c_i\alpha^i=0$ and using $\sigma(c_i)=c_i$ (since $c_i\in F$) and the multiplicativity/additivity of $\sigma$ gives $\sum_i c_i\,\sigma(\alpha)^i=0$, i.e.\ $p(\sigma(\alpha))=0$. So $\sigma$ maps roots to roots; being injective on the finite root set of $p$ in $K$, it permutes them.
\end{proof}

\begin{remark}
The proposition explains the asymmetry between abstract and embedded roots. An automorphism may only send $\alpha$ to a conjugate that \emph{actually lies in $K$}. If $K$ contains some but not all roots of the minimal polynomial of $\alpha$, the missing roots are simply unavailable as targets, and $\Aut(K/F)$ is smaller than the degree. This is precisely the failure of normality, seen below for $\mathbb{Q}(\sqrt[3]2)$.
\end{remark}

\begin{wex}{The only roots available may be the obvious ones}
For $K=\mathbb{Q}(\sqrt[4]2)$, show that an automorphism over $\mathbb{Q}$ can send $\sqrt[4]2$ only to $\pm\sqrt[4]2$, not to the complex roots $\pm i\sqrt[4]2$.
\wrec $\sqrt[4]2$ has minimal polynomial $x^4-2$ over $\mathbb{Q}$ (Eisenstein at $2$); by the proposition $\sigma(\sqrt[4]2)$ is a root of $x^4-2$ \emph{lying in $K$}.
\wsol The four roots of $x^4-2$ are $\pm\sqrt[4]2,\ \pm i\sqrt[4]2$. But $K=\mathbb{Q}(\sqrt[4]2)\subset\mathbb{R}$, so the non-real roots $\pm i\sqrt[4]2$ do not lie in $K$. Hence $\sigma(\sqrt[4]2)\in\{\sqrt[4]2,-\sqrt[4]2\}$, giving at most two automorphisms. Both occur: $\sqrt[4]2\mapsto-\sqrt[4]2$ extends $\sqrt2\mapsto\sqrt2$ (since $(-\sqrt[4]2)^2=\sqrt2$), so $\Aut(\mathbb{Q}(\sqrt[4]2)/\mathbb{Q})\cong\mathbb{Z}/(2)\mathbb{Z}$. Sanity check: $[\mathbb{Q}(\sqrt[4]2):\mathbb{Q}]=4$ but only $2$ automorphisms appear, so this real extension is \emph{not} Galois -- two of the four conjugates escaped the field.
\end{wex}

\begin{wex}{Automorphisms of $\mathbb{Q}(\sqrt[4]2)/\mathbb{Q}(\sqrt2)$}
Determine $\Aut(\mathbb{Q}(\sqrt[4]2)/\mathbb{Q}(\sqrt2))$ explicitly.
\wrec Now $\sqrt2$ is fixed, so $\sigma(\sqrt[4]2)$ must be a root of the minimal polynomial of $\sqrt[4]2$ over the larger base $\mathbb{Q}(\sqrt2)$, namely $x^2-\sqrt2$.
\wsol Over $\mathbb{Q}(\sqrt2)$ the element $\beta=\sqrt[4]2$ satisfies $\beta^2=\sqrt2$, and $x^2-\sqrt2$ is its minimal polynomial (degree $2=[\mathbb{Q}(\sqrt[4]2):\mathbb{Q}(\sqrt2)]$). Its roots are $\pm\sqrt[4]2$, both in $K$. So $\sigma(\sqrt[4]2)=\pm\sqrt[4]2$, giving $\Aut(\mathbb{Q}(\sqrt[4]2)/\mathbb{Q}(\sqrt2))=\{\id,\ \sqrt[4]2\mapsto-\sqrt[4]2\}\cong\mathbb{Z}/(2)\mathbb{Z}$. Sanity check: $[\mathbb{Q}(\sqrt[4]2):\mathbb{Q}(\sqrt2)]=2$ and we found $2$ automorphisms, so this degree-$2$ step \emph{is} Galois (both roots of the quadratic live in $K$).
\end{wex}

\begin{proof}[Idea]
Dedekind's lemma: a minimal-length nontrivial $K$-linear relation $\sum_i a_i\sigma_i(x)=0$ (all $x$) is impossible -- pick $y$ with $\sigma_1(y)\neq\sigma_2(y)$, substitute $xy$, and subtract $\sigma_1(y)$ times the original to get a shorter relation, a contradiction. For the bound: if $[K:F]=n$, with $F$-basis $\omega_1,\dots,\omega_n$, and there were $n+1$ distinct $F$-automorphisms $\sigma_1,\dots,\sigma_{n+1}$, the homogeneous $K$-linear system $\sum_j\sigma_j(\omega_i)x_j=0$ ($i=1,\dots,n$) of $n$ equations in $n+1$ unknowns would have a nonzero solution $x\in K^{n+1}$; by $F$-linearity $\sum_j x_j\sigma_j$ then vanishes on all of $K$, a nontrivial $K$-dependence among the $\sigma_j$, contradicting independence. The equality $[K:\Fix(G)]=\abs G$ is the quantitative converse, proved by the same independence input (Artin's theorem).
\end{proof}

\begin{proof}[Idea]
Build automorphisms by the isomorphism-extension theorem. An $F$-isomorphism of subfields $F(\alpha)\to F(\alpha')$ sending a root $\alpha$ of an irreducible factor to another root $\alpha'$ extends, over a splitting field, to an automorphism; separability guarantees each irreducible factor encountered has \emph{distinct} roots, so the number of extensions at each stage is exactly the degree of that factor. Multiplying these local counts up the tower of root adjunctions yields exactly $[K:F]$ automorphisms, meeting the bound.
\end{proof}

\begin{wex}{Counting embeddings to realize all $[K:F]$ automorphisms}
For the splitting field $K$ of $f(x)=(x^2-2)(x^2-3)$ over $\mathbb{Q}$, count $\Aut(K/\mathbb{Q})$ by extending one root choice at a time.
\wrec $f$ is separable (four distinct roots $\pm\sqrt2,\pm\sqrt3$), so by the corollary $\abs{\Aut(K/\mathbb{Q})}=[K:\mathbb{Q}]$; count by isomorphism-extension across the tower $\mathbb{Q}\subset\mathbb{Q}(\sqrt2)\subset\mathbb{Q}(\sqrt2,\sqrt3)$.
\wsol Adjoin $\sqrt2$: the irreducible $x^2-2$ has $2$ roots in $K$, so an embedding of $\mathbb{Q}(\sqrt2)$ extends in $2$ ways ($\sqrt2\mapsto\pm\sqrt2$). Over $\mathbb{Q}(\sqrt2)$, $\sqrt3$ still has minimal polynomial $x^2-3$ (degree $2$, $\sqrt3\notin\mathbb{Q}(\sqrt2)$), with $2$ roots $\pm\sqrt3$ in $K$, doubling each choice. Total $2\cdot2=4$ automorphisms, and $[K:\mathbb{Q}]=2\cdot2=4$. Sanity check: the four maps are the independent sign choices $(\sqrt2,\sqrt3)\mapsto(\pm\sqrt2,\pm\sqrt3)$; they meet the degree bound exactly, confirming separability gives equality.
\end{wex}

\begin{wex}{When the bound is strict: a tell-tale gap}
Without listing automorphisms, predict whether $\abs{\Aut(\mathbb{Q}(\sqrt[3]2)/\mathbb{Q})}$ equals $[\mathbb{Q}(\sqrt[3]2):\mathbb{Q}]=3$.
\wrec Equality requires $K$ to contain \emph{all} roots of the minimal polynomials of its generators (normality) and those polynomials to be separable; check whether all roots of $x^3-2$ lie in $\mathbb{Q}(\sqrt[3]2)$.
\wsol The roots of $x^3-2$ are $\sqrt[3]2,\ \zeta_3\sqrt[3]2,\ \zeta_3^2\sqrt[3]2$ with $\zeta_3=e^{2\pi i/3}$ non-real. But $\mathbb{Q}(\sqrt[3]2)\subset\mathbb{R}$, so two of the three roots are absent. Any $\sigma$ must send $\sqrt[3]2$ to a root \emph{in $K$}, leaving only $\sigma(\sqrt[3]2)=\sqrt[3]2$, the identity. So $\abs{\Aut(\mathbb{Q}(\sqrt[3]2)/\mathbb{Q})}=1<3$: the bound is strict. Sanity check: this matches the degree bound (a number $\le3$) and confirms a strict gap exactly where roots escape, anticipating the detailed count in the next subsection.
\end{wex}

\begin{pitfall}
Degree $[K:F]$ many automorphisms require BOTH normality (all conjugates of each generator lie in $K$) and separability (those conjugates are distinct). Degree alone is no guarantee: $\mathbb{Q}(\sqrt[3]2)/\mathbb{Q}$ has degree $3$ but only the identity automorphism, since the field is real while two of the three cube roots of $2$ are complex. It fails \emph{normality}: $x^3-2$ does not split in $\mathbb{Q}(\sqrt[3]2)$. (In characteristic $p$ one can instead fail \emph{separability}, e.g.\ $\F_p(t^{1/p})/\F_p(t)$, where $x^p-t=(x-t^{1/p})^p$ has a single repeated root.)
\end{pitfall}

\begin{wex}{$\Aut(\mathbb{Q}(\sqrt2)/\mathbb{Q})\cong\mathbb{Z}/(2)\mathbb{Z}$ is Galois}
Show $\mathbb{Q}(\sqrt2)/\mathbb{Q}$ is Galois with group $\mathbb{Z}/(2)\mathbb{Z}$, and verify the fixed field is $\mathbb{Q}$.
\wrec $\mathbb{Q}(\sqrt2)$ is the splitting field of the separable $x^2-2$ over $\mathbb{Q}$, so by the corollary it is Galois of degree $2$.
\wsol The two automorphisms are $\id$ and $\sigma:\sqrt2\mapsto-\sqrt2$ (from the first worked example), and $\ord\sigma=2$, so $\Gal(\mathbb{Q}(\sqrt2)/\mathbb{Q})=\{\id,\sigma\}\cong\mathbb{Z}/(2)\mathbb{Z}$, matching $[\mathbb{Q}(\sqrt2):\mathbb{Q}]=2$. The fixed field: $\sigma(a+b\sqrt2)=a-b\sqrt2$ equals $a+b\sqrt2$ iff $b=0$, so $\Fix(\gen\sigma)=\mathbb{Q}$. Sanity check: $\abs{\Gal}=2=[K:F]$ and $\Fix(\Gal)=\mathbb{Q}=F$, the two equivalent Galois criteria both hold.
\end{wex}

\begin{wex}{$\mathbb{Q}(\sqrt[3]2)/\mathbb{Q}$ is NOT Galois}
Confirm explicitly that $\Aut(\mathbb{Q}(\sqrt[3]2)/\mathbb{Q})=\{\id\}$ and identify the fixed field, so the extension is not Galois despite having prime degree $3$.
\wrec By the root-permutation proposition, $\sigma(\sqrt[3]2)$ is a root of $x^3-2$ in $K=\mathbb{Q}(\sqrt[3]2)\subset\mathbb{R}$; the other two roots are non-real.
\wsol The roots of $x^3-2$ are $\sqrt[3]2,\ \zeta_3\sqrt[3]2,\ \zeta_3^2\sqrt[3]2$; only $\sqrt[3]2$ is real, hence the only root in $K$. So $\sigma(\sqrt[3]2)=\sqrt[3]2$, forcing $\sigma=\id$ by the generator lemma. Thus $\Aut(\mathbb{Q}(\sqrt[3]2)/\mathbb{Q})=\{\id\}$, $\abs{\Aut}=1<3=[K:\mathbb{Q}]$, and $\Fix(\{\id\})=K=\mathbb{Q}(\sqrt[3]2)\supsetneq\mathbb{Q}$. Sanity check: both Galois criteria fail in agreement -- the order is $1\neq3$, and the fixed field is all of $K$ rather than $\mathbb{Q}$. The extension is separable (char $0$) but not normal.
\end{wex}

\begin{wex}{The splitting field $\mathbb{Q}(\sqrt[3]2,\zeta_3)/\mathbb{Q}$ is Galois with group $S_3$}
Show the splitting field of $x^3-2$ over $\mathbb{Q}$ is Galois of degree $6$ with $\Gal\cong S_3$.
\wrec $K=\mathbb{Q}(\sqrt[3]2,\zeta_3)$ is the splitting field of the separable $x^3-2$, hence Galois with $\abs{\Gal}=[K:\mathbb{Q}]$; the group acts faithfully by permuting the $3$ roots, so embeds in $S_3$.
\wsol Degree: $[\mathbb{Q}(\sqrt[3]2):\mathbb{Q}]=3$ and $[\mathbb{Q}(\sqrt[3]2,\zeta_3):\mathbb{Q}(\sqrt[3]2)]=2$ (since $\zeta_3$ satisfies $x^2+x+1$, irreducible over the real field $\mathbb{Q}(\sqrt[3]2)$), so $[K:\mathbb{Q}]=6$. Thus $\abs{\Gal(K/\mathbb{Q})}=6$. Every automorphism permutes the three roots $\sqrt[3]2,\zeta_3\sqrt[3]2,\zeta_3^2\sqrt[3]2$, giving an injection $\Gal(K/\mathbb{Q})\hookrightarrow S_3$; as both have order $6$ it is an isomorphism, $\Gal(K/\mathbb{Q})\cong S_3$. Sanity check: $\abs{S_3}=6=[K:\mathbb{Q}]$, and the extension is normal (all roots of $x^3-2$ are now present) and separable, so it is genuinely Galois -- contrast the non-Galois subextension $\mathbb{Q}(\sqrt[3]2)$. Concretely $\sigma:\sqrt[3]2\mapsto\zeta_3\sqrt[3]2,\ \zeta_3\mapsto\zeta_3$ has order $3$ and $\tau:\zeta_3\mapsto\zeta_3^2$ (complex conjugation) has order $2$, with $\tau\sigma\tau^{-1}=\sigma^{-1}$, the defining $S_3$ relation.
\end{wex}

\begin{wex}{The cyclotomic extension $\mathbb{Q}(\zeta_5)/\mathbb{Q}$}
Identify $\Gal(\mathbb{Q}(\zeta_5)/\mathbb{Q})$ where $\zeta_5=e^{2\pi i/5}$.
\wrec $\mathbb{Q}(\zeta_5)$ is the splitting field of the separable $x^5-1$ (roots the distinct $5$th roots of unity), hence Galois; $\zeta_5$ has minimal polynomial the cyclotomic $\Phi_5(x)=x^4+x^3+x^2+x+1$.
\wsol $\Phi_5$ is irreducible over $\mathbb{Q}$ (Eisenstein at $5$ after $x\mapsto x+1$), so $[\mathbb{Q}(\zeta_5):\mathbb{Q}]=4$ and $\abs{\Gal}=4$. An automorphism $\sigma$ sends $\zeta_5$ to another \emph{primitive} $5$th root, $\zeta_5^a$ with $a\in\{1,2,3,4\}$; the rule $\sigma_a:\zeta_5\mapsto\zeta_5^a$ gives $\sigma_a\sigma_b=\sigma_{ab\bmod5}$, so $\Gal(\mathbb{Q}(\zeta_5)/\mathbb{Q})\cong(\mathbb{Z}/(5)\mathbb{Z})^{\times}=(\mathbb{Z}/5\mathbb{Z})^{\times}$, cyclic of order $4$. Sanity check: $(\mathbb{Z}/(5)\mathbb{Z})^{\times}=\langle 2\rangle$ since $2^1,2^2,2^3,2^4=2,4,3,1\pmod5$ runs through all units, so the group is $\mathbb{Z}/(4)\mathbb{Z}$, and $\abs{(\mathbb{Z}/(5)\mathbb{Z})^{\times}}=\varphi(5)=4=[\mathbb{Q}(\zeta_5):\mathbb{Q}]$, meeting the bound.
\end{wex}

\begin{wex}{The fixed field of complex conjugation on $\mathbb{C}$}
Determine $\Fix(\gen\tau)$ for $\tau$ complex conjugation, and relate it to $\Aut(\mathbb{C}/\mathbb{R})$.
\wrec $\Fix(H)$ collects the elements moved by no element of $H$; for $\tau:a+bi\mapsto a-bi$ this is the equation $a+bi=a-bi$.
\wsol $\tau(a+bi)=a+bi$ iff $-bi=bi$ iff $b=0$ iff $a+bi\in\mathbb{R}$. So $\Fix(\gen\tau)=\mathbb{R}$. Since $\gen\tau=\{\id,\tau\}$ has order $2=[\mathbb{C}:\mathbb{R}]$ and fixes exactly $\mathbb{R}$, the extension $\mathbb{C}/\mathbb{R}$ is Galois with $\Gal(\mathbb{C}/\mathbb{R})=\{\id,\tau\}\cong\mathbb{Z}/(2)\mathbb{Z}$. Sanity check: $[\mathbb{C}:\mathbb{R}]=2$ equals $\abs{\gen\tau}$, and the fixed field equals the base field $\mathbb{R}$ -- both Galois criteria confirmed.
\end{wex}

\begin{wex}{Distinguishing $\mathbb{Q}(\sqrt2)$ from $\mathbb{Q}(\sqrt3)$ via automorphisms}
Show $\mathbb{Q}(\sqrt2)$ and $\mathbb{Q}(\sqrt3)$ are not isomorphic as fields.
\wrec An isomorphism of fields preserves which elements are squares; the existence of $\sqrt2$ as a square is an isomorphism invariant.
\wsol Any field isomorphism $\varphi:\mathbb{Q}(\sqrt2)\to\mathbb{Q}(\sqrt3)$ fixes $\mathbb{Q}$ (it fixes $1$, hence $\mathbb{Z}$, hence $\mathbb{Q}$). Then $\varphi(\sqrt2)^2=\varphi(2)=2$, so $\mathbb{Q}(\sqrt3)$ would contain an element squaring to $2$. But elements of $\mathbb{Q}(\sqrt3)$ are $a+b\sqrt3$ with $(a+b\sqrt3)^2=a^2+3b^2+2ab\sqrt3=2$ forcing $ab=0$ and $a^2+3b^2=2$, which has no rational solution ($a^2=2$ or $3b^2=2$, neither solvable in $\mathbb{Q}$). So no such $\varphi$ exists. Sanity check: equivalently $2$ is a square in $\mathbb{Q}(\sqrt2)$ but not in $\mathbb{Q}(\sqrt3)$, an isomorphism-invariant property, so the fields differ -- consistent with their distinct (though both order-$2$) automorphism groups acting on different generators.
\end{wex}

\begin{theorem}[{isomorphism-extension counts embeddings}]
Let $\varphi:F\to F'$ be a field isomorphism, $K/F$ finite, and $L$ a field containing $\varphi(F)=F'$. The number of embeddings $\sigma:K\hookrightarrow L$ extending $\varphi$ is at most $[K:F]$, with equality when $L$ contains a splitting field over $F'$ of the (image under $\varphi$ of the) minimal polynomials of a generating set and every such minimal polynomial is separable. Taking $F'=F$, $\varphi=\id$, and $L=K$ a splitting field recovers $\abs{\Aut(K/F)}\le[K:F]$ with equality in the separable normal case.
\end{theorem}

\begin{proof}[Idea]
Induct on $[K:F]$. Write $K=F(\alpha)(\dots)$ and let $m_\alpha$ be the minimal polynomial of $\alpha$, of degree $d=[F(\alpha):F]$. An extension of $\varphi$ to $F(\alpha)$ is determined by sending $\alpha$ to a root in $L$ of $\varphi(m_\alpha)$; there are at most $d$ such roots, exactly $d$ distinct ones when $\varphi(m_\alpha)$ is separable and splits in $L$. Each choice fixes a new base isomorphism $F(\alpha)\to F(\alpha')$, and the inductive hypothesis multiplies in the remaining $[K:F(\alpha)]$ extensions. Multiplying degree by degree up the tower gives the bound and the equality criterion.
\end{proof}

\begin{wex}{Embedding count up a tower for $\mathbb{Q}(\sqrt[3]2,\zeta_3)$}
Recount $\abs{\Aut(\mathbb{Q}(\sqrt[3]2,\zeta_3)/\mathbb{Q})}$ purely as a product of per-step embedding counts.
\wrec Embeddings multiply along a tower: (number of roots of each minimal polynomial available in $K$) at each adjunction; separability and normality make every factor maximal.
\wsol Step $1$, adjoin $\sqrt[3]2$ with minimal polynomial $x^3-2$: in $K=\mathbb{Q}(\sqrt[3]2,\zeta_3)$ all $3$ roots $\sqrt[3]2,\zeta_3\sqrt[3]2,\zeta_3^2\sqrt[3]2$ are present, so $3$ extensions. Step $2$, adjoin $\zeta_3$ with minimal polynomial $x^2+x+1$ over $\mathbb{Q}(\sqrt[3]2)$: both roots $\zeta_3,\zeta_3^2$ lie in $K$, so $2$ extensions each. Total $3\cdot2=6=[K:\mathbb{Q}]$. Sanity check: this product equals the group order $\abs{S_3}=6$ found earlier; had a root been missing (as in $\mathbb{Q}(\sqrt[3]2)$ alone) a factor would have dropped below the degree and the bound would be strict.
\end{wex}

\begin{wex}{Finite-field cross-reference: Frobenius realizes the bound}
For $K=\F_{p^n}$ over $F=\F_p$, identify the automorphism that achieves $\abs{\Aut(K/F)}=[K:F]=n$, and point to where the lattice is worked out.
\wrec $\F_{p^n}/\F_p$ is the splitting field of the separable $x^{p^n}-x$, so by the corollary it is Galois of degree $n$; the group is generated by Frobenius (Section 14.3).
\wsol The map $\Frob_p:\alpha\mapsto\alpha^p$ is an $\F_p$-automorphism (it fixes $\F_p$ by Fermat: $a^p=a$), and $\langle \Frob_p\rangle=\Gal(\F_{p^n}/\F_p)\cong\mathbb{Z}/(n)\mathbb{Z}$ has order $n=[\F_{p^n}:\F_p]$, meeting the bound. The full subfield/subgroup correspondence -- subfields $\F_{p^d}$ for $d\mid n$ matched with $\langle \Frob_p^{d}\rangle$ -- is developed in Section 14.3. Sanity check: $\Frob_p^n(\alpha)=\alpha^{p^n}=\alpha$ for all $\alpha\in\F_{p^n}$, while for $0<k<n$ the polynomial $x^{p^k}-x$ has at most $p^k<p^n$ roots, so $\Frob_p^k\neq\id$; hence $\ord{\Frob_p}=n$, and the extension is normal (a splitting field) and separable, hence genuinely Galois, exactly the equality case of the bound.
\end{wex}

\begin{wex}{Strictness from inseparability in characteristic $p$}
Show $K=\F_p(t^{1/p})$ over $F=\F_p(t)$ has degree $p$ but only the trivial automorphism group, so equality fails for the separability reason.
\wrec Here normality holds but separability fails: the minimal polynomial of $t^{1/p}$ is $x^p-t=(x-t^{1/p})^p$, a single root of multiplicity $p$.
\wsol $x^p-t$ is irreducible over $F=\F_p(t)$ (Eisenstein at the prime $t$ in $\F_p[t]$), so $[K:F]=p$. Over $K$ it factors as $(x-t^{1/p})^p$, so $t^{1/p}$ is the \emph{only} root. Any $\sigma\in\Aut(K/F)$ must fix $t$ and send $t^{1/p}$ to a root of $x^p-t$ in $K$, i.e.\ to $t^{1/p}$ itself; hence $\sigma=\id$ and $\abs{\Aut(K/F)}=1<p$. Sanity check: the bound $\abs{\Aut}\le[K:F]=p$ holds, but is strict; the failure here is inseparability ($x^p-t$ has a repeated root), complementing the normality failure of $\mathbb{Q}(\sqrt[3]2)/\mathbb{Q}$. Both reasons must be excluded for an extension to be Galois.
\end{wex}

\begin{exers}{Exercises (from the text).}
  \item
    \begin{enumerate}
      \item[(a)] Show that if the field $K$ is generated over $F$ by the elements $\alpha_1, \ldots, \alpha_n$ then an automorphism $\sigma$ of $K$ fixing $F$ is uniquely determined by $\sigma(\alpha_1), \ldots, \sigma(\alpha_n)$. In particular show that an automorphism fixes $K$ if and only if it fixes a set of generators for $K$.
      \item[(b)] Let $G \le \Gal(K/F)$ be a subgroup of the Galois group of the extension $K/F$ and suppose $\sigma_1, \ldots, \sigma_k$ are generators for $G$. Show that the subfield $E/F$ is fixed by $G$ if and only if it is fixed by the generators $\sigma_1, \ldots, \sigma_k$.
    \end{enumerate}

  \item Let $\tau$ be the map $\tau : \mathbb{C} \to \mathbb{C}$ defined by $\tau(a+bi) = a - bi$ (\emph{complex conjugation}). Prove that $\tau$ is an automorphism of $\mathbb{C}$.

  \item Determine the fixed field of complex conjugation on $\mathbb{C}$.

  \item Prove that $\mathbb{Q}(\sqrt{2})$ and $\mathbb{Q}(\sqrt{3})$ are not isomorphic.

  \item Determine the automorphisms of the extension $\mathbb{Q}(\sqrt[4]{2})/\mathbb{Q}(\sqrt{2})$ explicitly.

  \item Let $k$ be a field.
    \begin{enumerate}
      \item[(a)] Show that the mapping $\varphi : k[t] \to k[t]$ defined by $\varphi(f(t)) = f(at+b)$ for fixed $a, b \in k$, $a \ne 0$ is an automorphism of $k[t]$ which is the identity on $k$.
      \item[(b)] Conversely, let $\varphi$ be an automorphism of $k[t]$ which is the identity on $k$. Prove that there exist $a, b \in k$ with $a \ne 0$ such that $\varphi(f(t)) = f(at+b)$ as in (a).
    \end{enumerate}

  \item This exercise determines $\mathrm{Aut}(\mathbb{R}/\mathbb{Q})$.
    \begin{enumerate}
      \item[(a)] Prove that any $\sigma \in \mathrm{Aut}(\mathbb{R}/\mathbb{Q})$ takes squares to squares and takes positive reals to positive reals. Conclude that $a < b$ implies $\sigma a < \sigma b$ for every $a, b \in \mathbb{R}$.
      \item[(b)] Prove that $-\dfrac{1}{m} < a - b < \dfrac{1}{m}$ implies $-\dfrac{1}{m} < \sigma a - \sigma b < \dfrac{1}{m}$ for every positive integer $m$. Conclude that $\sigma$ is a continuous map on $\mathbb{R}$.
      \item[(c)] Prove that any continuous map on $\mathbb{R}$ which is the identity on $\mathbb{Q}$ is the identity map, hence $\mathrm{Aut}(\mathbb{R}/\mathbb{Q}) = 1$.
    \end{enumerate}

  \item Prove that the automorphisms of the rational function field $k(t)$ which fix $k$ are precisely the \emph{fractional linear transformations} determined by $t \mapsto \dfrac{at+b}{ct+d}$ for $a, b, c, d \in k$, $ad - bc \ne 0$ (so $f(t) \in k(t)$ maps to $f\!\left(\dfrac{at+b}{ct+d}\right)$) (cf. Exercise 18 of Section 13.2).

  \item Determine the fixed field of the automorphism $t \mapsto t+1$ of $k(t)$.

  \item Let $K$ be an extension of the field $F$. Let $\varphi : K \to K'$ be an isomorphism of $K$ with a field $K'$ which maps $F$ to the subfield $F'$ of $K'$. Prove that the map $\sigma \mapsto \varphi \sigma \varphi^{-1}$ defines a group isomorphism $\mathrm{Aut}(K/F) \stackrel{\sim}{\to} \mathrm{Aut}(K'/F')$.
\end{exers}

\begin{definition}
A \emph{character} of a group $G$ with values in a field $L$ is a group homomorphism $\chi\colon G\to L^{\times}$. Characters $\chi_1,\dots,\chi_n$ are \emph{linearly independent over $L$} if no relation $a_1\chi_1+\cdots+a_n\chi_n=0$ holds with $a_i\in L$ not all zero, where equality means $\sum_i a_i\chi_i(g)=0$ for every $g\in G$.
\end{definition}

\begin{theorem}[{linear independence of characters (Dedekind--Artin)}]
If $\chi_1,\dots,\chi_n$ are distinct characters of a group $G$ with values in a field $L$, then they are linearly independent over $L$. In particular, distinct field embeddings $\sigma_1,\dots,\sigma_n\colon K\to L$ are linearly independent as $L$-valued functions on $K^{\times}$.
\end{theorem}

\begin{corollary}[{nonzero trace}]
If $K/F$ is a finite Galois extension with $G=\Gal(K/F)$, then the trace map $\Tr_{K/F}(\alpha)=\sum_{\sigma\in G}\sigma(\alpha)$ is not identically zero; some $\alpha\in K$ has $\Tr_{K/F}(\alpha)\neq0$.
\end{corollary}

\begin{proof}[Idea]
$\Tr_{K/F}=\sum_{\sigma\in G}\sigma$ is exactly an $F$-linear combination (all coefficients $1$) of the distinct embeddings $\sigma$. If it were the zero function, that would be a nontrivial linear dependence among distinct characters $K^{\times}\to K^{\times}$, contradicting the theorem.
\end{proof}

\begin{wex}{Three embeddings of a number field are independent}
Let $K=\mathbb{Q}(\theta)$ with $\theta=2^{1/3}$ embedded in $\mathbb{C}$, and let $\sigma_1,\sigma_2,\sigma_3\colon K\to\mathbb{C}$ send $\theta$ to $\theta,\ \omega\theta,\ \omega^2\theta$ ($\omega=e^{2\pi i/3}$). Show no $a_i\in\mathbb{C}$ with $\sum a_i\sigma_i=0$ exist unless all $a_i=0$.
\wrec These are three distinct embeddings of a field into $\mathbb{C}$, so the theorem on independence of characters applies directly.
\wsol Evaluate $\sum_i a_i\sigma_i$ at $1,\theta,\theta^2$. Since each $\sigma_j$ fixes $\mathbb{Q}$, at $1$ we get $a_1+a_2+a_3=0$. At $\theta$ we get $a_1\theta+a_2\omega\theta+a_3\omega^2\theta=0$, i.e.\ $a_1+a_2\omega+a_3\omega^2=0$. At $\theta^2$ we get $a_1+a_2\omega^2+a_3\omega^4=a_1+a_2\omega^2+a_3\omega=0$. The coefficient matrix is the Vandermonde matrix on $1,\omega,\omega^2$, which is invertible (distinct entries), forcing $a_1=a_2=a_3=0$. Sanity check: the Vandermonde determinant is $\prod_{i<j}(\omega^{j}-\omega^{i})\neq0$ precisely because $1,\omega,\omega^2$ are distinct, which is the same nonvanishing that drives the general proof.
\end{wex}

\begin{proof}[Idea]
Write $G=\{\sigma_1=\id,\dots,\sigma_n\}$, $n=\abs{G}$. First $[K:F]\le n$: if $\alpha_1,\dots,\alpha_{n+1}\in K$ were $F$-linearly independent, the $n\times(n+1)$ system $\sum_j x_j\sigma_i(\alpha_j)=0$ has a nonzero solution $x\in K^{n+1}$; choosing one with fewest nonzero entries and averaging over $G$ produces (via independence of characters) a nontrivial $F$-relation among the $\alpha_j$, a contradiction. Conversely $[K:F]\ge n$: the $n$ distinct automorphisms $\sigma_i$ are $F$-linear maps $K\to K$, and by independence of characters they are linearly independent in the $F$-vector space $\Hom_F(K,K)$, which has dimension $[K:F]^2$ over $F$, but more sharply they restrict to distinct embeddings, forcing $[K:F]\ge n$. Hence $[K:F]=n$. Since $G\subseteq\Aut(K/F)$ and $\abs{\Aut(K/F)}\le[K:F]=n=\abs{G}$ always, we get $\Aut(K/F)=G$ of order $[K:F]$, which makes $K/F$ Galois with $\Gal(K/F)=G$.
\end{proof}

