\begin{theorem}[{four characterizations of a finite Galois extension}]
For a finite extension $K/F$ the following are equivalent:
\begin{enumerate}[label=\textup{(\arabic*)},leftmargin=*]
\item $K/F$ is normal and separable;
\item $K$ is the splitting field over $F$ of some separable polynomial in $F[x]$;
\item $\abs{\Aut(K/F)}=[K:F]$;
\item $F=\Fix(\Aut(K/F))$, i.e.\ $F$ is exactly the fixed field of the full automorphism group.
\end{enumerate}
When these hold we call $K/F$ \emph{Galois} and write $\Gal(K/F)=\Aut(K/F)$.
\end{theorem}

\begin{proof}[Idea]
$(1)\Rightarrow(2)$: a normal separable extension is the splitting field of the product of the (separable) minimal polynomials of a set of generators. $(2)\Rightarrow(3)$: counting embeddings of a splitting field, separability makes every root simple so all $[K:F]$ extensions of the identity exist as automorphisms. $(3)\Rightarrow(4)$: if $F_0=\Fix(\Aut(K/F))\supseteq F$, then by Artin $[K:F_0]=\abs{\Aut(K/F)}=[K:F]$, forcing $F_0=F$. $(4)\Rightarrow(1)$: by Artin $K/F$ is Galois with $\Gal=\Aut(K/F)$, and a Galois extension is normal (the orbit of any root under the group gives all conjugates inside $K$) and separable (distinct conjugates, no repeated roots).
\end{proof}

\begin{pitfall}
Normality and separability are independent conditions and \emph{both} are needed. $\mathbb{Q}(2^{1/3})/\mathbb{Q}$ is separable (characteristic $0$) but not normal -- it omits the complex roots $\omega2^{1/3},\omega^22^{1/3}$ -- so $\abs{\Aut(\mathbb{Q}(2^{1/3})/\mathbb{Q})}=1<3=[\mathbb{Q}(2^{1/3}):\mathbb{Q}]$ and the extension is not Galois. Over $\F_p(t)$ the extension $\F_p(t^{1/p})/\F_p(t)$ is normal (it is the splitting field of $x^p-t=(x-t^{1/p})^p$) but inseparable, again failing $(3)$.
\end{pitfall}

\begin{wex}{$\mathbb{Q}(2^{1/3})/\mathbb{Q}$ is not Galois}
Show $\abs{\Aut(\mathbb{Q}(2^{1/3})/\mathbb{Q})}=1$ and conclude the extension is not Galois.
\wrec Use characterization (3): an automorphism must send $2^{1/3}$ to another root of its minimal polynomial $x^3-2$ \emph{lying in the field}.
\wsol The minimal polynomial of $\theta=2^{1/3}$ over $\mathbb{Q}$ is $x^3-2$, with roots $\theta,\omega\theta,\omega^2\theta$. But $\mathbb{Q}(\theta)\subset\mathbb{R}$, while $\omega\theta,\omega^2\theta\notin\mathbb{R}$, so the only root inside $\mathbb{Q}(\theta)$ is $\theta$ itself. Any $\sigma\in\Aut(\mathbb{Q}(\theta)/\mathbb{Q})$ is determined by $\sigma(\theta)$, which must be a root of $x^3-2$ in $\mathbb{Q}(\theta)$, hence $\sigma(\theta)=\theta$ and $\sigma=\id$. So $\abs{\Aut}=1\neq3=[\mathbb{Q}(\theta):\mathbb{Q}]$. Sanity check: characterization (4) agrees -- $\Fix(\Aut)=\Fix(\{\id\})=\mathbb{Q}(\theta)\neq\mathbb{Q}$, so $K/F$ fails the fixed-field test as well.
\end{wex}

\begin{wex}{$\mathbb{Q}(\sqrt2,\sqrt3)/\mathbb{Q}$ is Galois by all four tests}
Verify the four characterizations for $K=\mathbb{Q}(\sqrt2,\sqrt3)$ over $\mathbb{Q}$.
\wrec $K$ is the splitting field of $(x^2-2)(x^2-3)$, a separable polynomial in characteristic $0$; this is characterization (2).
\wsol The polynomial $(x^2-2)(x^2-3)$ has roots $\pm\sqrt2,\pm\sqrt3$, all distinct, and $K=\mathbb{Q}(\sqrt2,\sqrt3)$ contains all of them, so $K$ is its splitting field: (2) holds, hence (1) normal+separable. The four automorphisms send $\sqrt2\mapsto\pm\sqrt2$ and $\sqrt3\mapsto\pm\sqrt3$ independently, so $\abs{\Aut(K/\mathbb{Q})}=4=[K:\mathbb{Q}]$: (3) holds. Finally any element fixed by all four sign-changes lies in $\mathbb{Q}$, giving $\Fix(\Aut)=\mathbb{Q}$: (4) holds. Sanity check: $[K:\mathbb{Q}]=[K:\mathbb{Q}(\sqrt2)]\cdot[\mathbb{Q}(\sqrt2):\mathbb{Q}]=2\cdot2=4$, matching $\abs{\Aut(K/\mathbb{Q})}=4$.
\end{wex}

\begin{wex}{Recovering the base field as a fixed field}
With $K=\mathbb{Q}(\sqrt2,\sqrt3)$ and $\sigma\colon\sqrt2\mapsto-\sqrt2,\sqrt3\mapsto\sqrt3$, identify $\Fix(\langle \sigma\rangle)$.
\wrec By Artin, $[K:\Fix(\langle \sigma\rangle)]=\abs{\langle \sigma\rangle}=2$, so $\Fix(\langle \sigma\rangle)$ is a degree-$2$ subfield -- one of the quadratic subfields.
\wsol $\sigma$ fixes $\sqrt3$ and negates $\sqrt2$, so it fixes $\mathbb{Q}(\sqrt3)$ pointwise; since $[K:\mathbb{Q}(\sqrt3)]=2=\abs{\langle \sigma\rangle}$, Artin forces $\Fix(\langle \sigma\rangle)=\mathbb{Q}(\sqrt3)$. Sanity check: $\sigma(\sqrt6)=\sigma(\sqrt2)\sigma(\sqrt3)=-\sqrt2\cdot\sqrt3=-\sqrt6$, so $\sqrt6\notin\Fix(\langle \sigma\rangle)$, consistent with $\Fix(\langle \sigma\rangle)=\mathbb{Q}(\sqrt3)$ not containing $\sqrt6$.
\end{wex}

\begin{proof}[Idea]
That the maps are inverse bijections is Artin run in both directions: for any subgroup $H$, $K/\Fix(H)$ is Galois with group exactly $H$ (so $\Gal(K/\Fix(H))=H$), and for any intermediate $E$, $K/E$ is Galois (it is a splitting field of the same separable polynomial), so $\Fix(\Gal(K/E))=E$. Inclusion reversal is immediate: a bigger group fixes fewer elements. (1) is the degree formula $[K:F]=[K:E][E:F]$ combined with $\abs{G}=[K:F]$, $\abs{H}=[K:E]$. For (2), $\tau\in\sigma H\sigma^{-1}$ fixes $\sigma(\alpha)$ iff $\sigma^{-1}\tau\sigma\in H$ fixes $\alpha$, giving $\Fix(\sigma H\sigma^{-1})=\sigma\Fix(H)$. For (3), $E=\Fix(H)$ is stable under all of $G$ (i.e.\ $\sigma(E)=E$ for all $\sigma$, equivalently $E/F$ normal) iff $\sigma H\sigma^{-1}=H$ for all $\sigma$ by (2), i.e.\ $H\nor G$; the restriction map $G\to\Gal(E/F)$ is then onto with kernel exactly $H$, so $\Gal(E/F)\cong G/H$.
\end{proof}

\begin{wex}{Degrees from the index, both directions}
In a Galois extension with $G=D_8$ (order $8$), what are $[K:E]$ and $[E:F]$ for $E=\Fix(H)$ with $\abs{H}=2$?
\wrec Apply part (1): $[K:E]=\abs{H}$ and $[E:F]=[G:H]=\abs{G}/\abs{H}$.
\wsol $[K:E]=\abs{H}=2$ and $[E:F]=8/2=4$. Sanity check: $[K:E]\cdot[E:F]=2\cdot4=8=\abs{G}=[K:F]$, the tower law holds.
\end{wex}

\begin{proof}[Idea]
$\sigma^2=\tau^2=\id$ and $\sigma\tau=\tau\sigma$, so $G\cong V_4$. The element $\sigma\tau$ negates both $\sqrt2$ and $\sqrt3$, hence fixes their product $\sqrt6$; thus $\Fix(\langle \sigma\tau\rangle)\supseteq\mathbb{Q}(\sqrt6)$, and by Artin equality holds (degree $2$ each). Similarly $\langle \tau\rangle$ fixes $\sqrt2$ and $\langle \sigma\rangle$ fixes $\sqrt3$. Since $G$ is abelian every subgroup is normal, so by part (3) every intermediate field is Galois over $\mathbb{Q}$ (each is a quadratic, automatically normal).
\end{proof}

