\begin{dgx}
\dgi{Objects:} Left side: the subgroup lattice of $V_4=\{1,a,b,c\}$ drawn growing upward, with nodes at three
  levels -- trivial group $1$ (bottom), the three order-$2$ subgroups $\langle a\rangle,\langle b\rangle,\langle c\rangle$ (middle), and
  $V_4$ (top). Right side: the subfield lattice of $K/\mathbb{Q}$ drawn inverted (growing downward), with nodes --
  $\mathbb{Q}$ (top), $\mathbb{Q}(\sqrt3),\mathbb{Q}(\sqrt2),\mathbb{Q}(\sqrt6)$ (middle), and $K=\mathbb{Q}(\sqrt2,\sqrt3)$ (bottom). The dotted
  curved ties between the two lattices are the correspondence lines, not field or group morphisms.
\dgi{Arrows:} The solid edges within each lattice are inclusion relations. The dotted curved ties encode
  the bijection $H\leftrightarrow\Fix(H)$: each tie connects a subgroup on the left to its fixed field
  on the right at the same height. Specifically: $V_4\leftrightarrow\mathbb{Q}$ (top tie), $1\leftrightarrow K$
  (bottom tie), $\langle a\rangle\leftrightarrow\mathbb{Q}(\sqrt3)$ (since $a$ negates $\sqrt2$ but fixes $\sqrt3$),
  $\langle b\rangle\leftrightarrow\mathbb{Q}(\sqrt2)$ (since $b$ fixes $\sqrt2$), $\langle c\rangle\leftrightarrow\mathbb{Q}(\sqrt6)$
  (since $c$ negates both radicals so fixes their product).
\dgi{What commutes:} Equal-height pairing: $\abs{H}=[K:\Fix(H)]$ and $[V_4:H]=[\Fix(H):\mathbb{Q}]$
  for every subgroup $H$. So height from $1$ on the left (which encodes $\abs{H}$) equals height from $K$ on
  the right (which encodes $[K:\Fix(H)]$).
\dgi{Why it commutes:} Artin's theorem applied to each $H$: $K/\Fix(H)$ is Galois with $\Gal(K/\Fix(H))=H$,
  so $\abs{H}=[K:\Fix(H)]$. The subgroup-lattice grows up (by inclusion) while the field lattice is drawn
  inverted (inclusion goes down), so equal height encodes equal index -- the picture is literally the visual
  proof of inclusion-reversal.
\dgi{Why this matters here:} This is the fully explicit version of the paired lattice: it names every node and
  every tie-line, verifying the bijection concretely for $V_4$. It is placed here to show that the abstract
  theorem gives computable, checkable outputs for this specific $4$-element group.
\dgi{Concrete example:} Take $H=\langle c\rangle$ where $c\colon\sqrt2\mapsto-\sqrt2,\sqrt3\mapsto-\sqrt3$. Then
  $\Fix(\langle c\rangle)=\{r\in K:c(r)=r\}$. We have $c(\sqrt6)=\sqrt6$, so $\mathbb{Q}(\sqrt6)\subseteq\Fix(\langle c\rangle)$;
  since $[K:\Fix(\langle c\rangle)]=\abs{\langle c\rangle}=2$ by Artin and $[K:\mathbb{Q}(\sqrt6)]=2$, equality holds.
  This is the tie joining $\langle c\rangle$ to $\mathbb{Q}(\sqrt6)$ (the shallowest of the three curved middle ties).
\dgi{Common pitfall:} Students sometimes read the tie-lines as indicating field maps or ring homomorphisms.
  They are not: a tie $H\text{---}\Fix(H)$ records the bijection $H\leftrightarrow K^H$, which is a
  set-theoretic correspondence, not an algebraic map from the group to the field. The Galois correspondence
  is a bijection of posets, not a functor in the naive sense.
\dgi{Takeaway:} The point of this diagram is that placing the two lattices side-by-side at inverted heights
  makes the inclusion-reversal of the Galois correspondence geometrically obvious: going up on the left
  (bigger group) corresponds exactly to going up on the right (smaller field).
\end{dgx}

\begin{wex}{Computing $\Fix(\langle \sigma\tau\rangle)=\mathbb{Q}(\sqrt6)$}
Verify that the diagonal subgroup $\langle \sigma\tau\rangle$ fixes $\mathbb{Q}(\sqrt6)$ and nothing larger.
\wrec By Artin $[K:\Fix(\langle \sigma\tau\rangle)]=\abs{\langle \sigma\tau\rangle}=2$, so the fixed field is quadratic; find an explicit fixed element.
\wsol $\sigma\tau$ sends $\sqrt2\mapsto-\sqrt2$ and $\sqrt3\mapsto-\sqrt3$, hence $\sqrt6=\sqrt2\sqrt3\mapsto(-\sqrt2)(-\sqrt3)=\sqrt6$. So $\mathbb{Q}(\sqrt6)\subseteq\Fix(\langle \sigma\tau\rangle)$; both have degree $2$ over $\mathbb{Q}$ (the latter by Artin), so they are equal. Sanity check: $\sigma\tau(\sqrt2)=-\sqrt2\neq\sqrt2$, so $\sqrt2\notin\Fix(\langle \sigma\tau\rangle)$, confirming the fixed field is $\mathbb{Q}(\sqrt6)$ and not all of $K$.
\end{wex}

\begin{wex}{All subfields of the splitting field of $(x^2-2)(x^2-3)(x^2-5)$}
Find $\Gal(K/\mathbb{Q})$ and count the intermediate fields for $K=\mathbb{Q}(\sqrt2,\sqrt3,\sqrt5)$.
\wrec Independent square roots give $G\cong V_4\times\mathbb{Z}/(2)\mathbb{Z}\cong(\mathbb{Z}/(2)\mathbb{Z})^3$ by the biquadratic principle; subfields correspond to subgroups of $(\mathbb{Z}/(2)\mathbb{Z})^3$.
\wsol Each generator independently sends $\sqrt2,\sqrt3,\sqrt5$ to $\pm$ themselves, so $\abs{G}=8$ and $G\cong(\mathbb{Z}/(2)\mathbb{Z})^3$, with $[K:\mathbb{Q}]=8$. The number of subgroups of $(\mathbb{Z}/(2)\mathbb{Z})^3$ by order: one trivial, $7$ of order $2$ (one per nonzero vector), $7$ of order $4$ (one per $2$-dimensional subspace, equivalently per nonzero linear functional), one of order $8$, total $16$. Hence $16$ intermediate fields: $\mathbb{Q}$ itself, $7$ quadratic fields $\mathbb{Q}(\sqrt{d})$ for $d\in\{2,3,5,6,10,15,30\}$, $7$ biquadratic fields of degree $4$, and $K$. Sanity check: the $7$ quadratics correspond to the $7$ subgroups of \emph{index} $2$ (order $4$), and the $7$ degree-$4$ fields to the $7$ subgroups of order $2$ -- the order-reversal swaps the two counts, both equal to $2^3-1=7$.
\end{wex}

\begin{proof}[Idea]
The four roots of $x^4-2$ are $\theta,i\theta,-\theta,-i\theta=i^k\theta$, so $K=\mathbb{Q}(\theta,i)$. Now $[\mathbb{Q}(\theta):\mathbb{Q}]=4$ (Eisenstein at $2$) and $\theta\in\mathbb{R}$ while $i\notin\mathbb{R}$, so $[K:\mathbb{Q}(\theta)]=2$, giving $[K:\mathbb{Q}]=8$. The extension is Galois (splitting field of a separable polynomial), so $\abs{G}=8$. The map $\sigma$ permutes the roots cyclically and fixes $i$; computing $\sigma^2(\theta)=i^2\theta=-\theta$, $\sigma^4=\id$, so $\ord\sigma=4$. Complex conjugation $\tau$ fixes $\theta$ and inverts $i$, $\ord\tau=2$. Finally $\tau\sigma\tau^{-1}(\theta)=\tau\sigma(\theta)=\tau(i\theta)=-i\theta=\sigma^3(\theta)=\sigma^{-1}(\theta)$ and both fix $i$, so $\tau\sigma\tau^{-1}=\sigma^{-1}$: these are the dihedral relations, $G\cong D_8$.
\end{proof}

\begin{wex}{$\Fix(\langle \tau\rangle)=\mathbb{Q}(\theta)$ is not Galois over $\mathbb{Q}$}
Identify the fixed field of complex conjugation $\tau$ and explain why it is not normal over $\mathbb{Q}$.
\wrec $\tau$ fixes $\theta=2^{1/4}\in\mathbb{R}$; by Artin $[K:\Fix(\langle \tau\rangle)]=2$, so $\Fix(\langle \tau\rangle)$ is a degree-$4$ field. Non-normality of $\langle \tau\rangle$ in $G$ predicts the field is not Galois over $\mathbb{Q}$.
\wsol $\tau$ fixes $\theta$ and $\mathbb{Q}$, so $\mathbb{Q}(\theta)\subseteq\Fix(\langle \tau\rangle)$; since $[\mathbb{Q}(\theta):\mathbb{Q}]=4=[G:\langle \tau\rangle]$, equality holds, $\Fix(\langle \tau\rangle)=\mathbb{Q}(\theta)$. Now $\langle \tau\rangle$ is not normal: $\sigma\tau\sigma^{-1}$ sends $\theta\mapsto\sigma\tau(-i\theta)=\sigma(i\theta)=-\theta$ and $i\mapsto-i$, so $\sigma\tau\sigma^{-1}=\sigma^2\tau$ and $\sigma\langle \tau\rangle\sigma^{-1}=\langle \sigma\tau\sigma^{-1}\rangle=\langle \sigma^2\tau\rangle\neq\langle \tau\rangle$. Correspondingly $\mathbb{Q}(\theta)$ contains only the real roots $\pm\theta$ of $x^4-2$, not the conjugates $i\theta,-i\theta$, so it is not a splitting field and not normal over $\mathbb{Q}$. Sanity check: $\abs{\Aut(\mathbb{Q}(\theta)/\mathbb{Q})}=2$ (only $\theta\mapsto\pm\theta$ stay in the real field $\mathbb{Q}(\theta)$) while $[\mathbb{Q}(\theta):\mathbb{Q}]=4$, so by characterization (3) it is indeed not Galois.
\end{wex}

\begin{wex}{$\Fix(\langle \sigma^2\rangle)=\mathbb{Q}(i,\sqrt2)$ is Galois over $\mathbb{Q}$}
Find the fixed field of the center $\langle \sigma^2\rangle$ and identify $\Gal$ of that field over $\mathbb{Q}$.
\wrec $\langle \sigma^2\rangle$ is the center of $D_8$, hence normal; its fixed field is degree $[G:\langle \sigma^2\rangle]=4$ and Galois over $\mathbb{Q}$ with group $G/\langle \sigma^2\rangle$.
\wsol $\sigma^2$ sends $\theta\mapsto-\theta$ and fixes $i$, so it fixes $\theta^2=\sqrt2$ and $i$; thus $\mathbb{Q}(i,\sqrt2)\subseteq\Fix(\langle \sigma^2\rangle)$, and both are degree $4$ over $\mathbb{Q}$, so equal. Since $\langle \sigma^2\rangle\nor G$, the field $\mathbb{Q}(i,\sqrt2)$ is Galois over $\mathbb{Q}$ with $\Gal\cong G/\langle \sigma^2\rangle$. As $D_8/Z(D_8)\cong V_4$, we get $\Gal(\mathbb{Q}(i,\sqrt2)/\mathbb{Q})\cong V_4$. Sanity check: $\mathbb{Q}(i,\sqrt2)$ is itself a biquadratic field $\mathbb{Q}(\sqrt{-1},\sqrt2)$ whose group is visibly $V_4$ (independent sign changes on $i,\sqrt2$), agreeing with $D_8/Z\cong V_4$.
\end{wex}

\begin{wex}{The three quadratic subfields and which subgroups give them}
Determine the three quadratic subfields of $K=\mathbb{Q}(\theta,i)$ and the subgroups they correspond to.
\wrec Quadratic subfields $\leftrightarrow$ index-$2$ (order-$4$) subgroups of $G$; there are exactly three subgroups of order $4$ in $D_8$.
\wsol The order-$4$ subgroups are $\langle \sigma\rangle$ (cyclic), $\langle \sigma^2,\tau\rangle$, and $\langle \sigma^2,\sigma\tau\rangle$. Their fixed fields: $\Fix(\langle \sigma\rangle)=\mathbb{Q}(i)$ (since $\sigma$ fixes $i$ and moves $\theta$); $\Fix(\langle \sigma^2,\tau\rangle)=\mathbb{Q}(\sqrt2)$ (both fix $\theta^2=\sqrt2$, and $\tau$ moves $i$); $\Fix(\langle \sigma^2,\sigma\tau\rangle)=\mathbb{Q}(\sqrt{-2})$ (one checks $\sigma\tau$ fixes $i\theta^2=i\sqrt2$, and $\sigma^2$ fixes it too, with $(i\sqrt2)^2=-2$). All three are normal, so all three quadratics are Galois over $\mathbb{Q}$. Sanity check: the three quadratic subfields of any field containing $\mathbb{Q}(\sqrt2,i)$ that are $\mathbb{Q}(\sqrt d)$ must have $d\in\{2,-1,-2\}$ up to squares, and indeed $2\cdot(-1)=-2$, so $\{\mathbb{Q}(\sqrt2),\mathbb{Q}(i),\mathbb{Q}(\sqrt{-2})\}$ is exactly the $V_4$ family of quadratics inside $\mathbb{Q}(i,\sqrt2)$.
\end{wex}

\begin{wex}{A non-normal reflection subgroup and its conjugate field}
Show $\langle \tau\rangle$ and $\langle \sigma^2\tau\rangle$ are conjugate in $D_8$ and that their fixed fields $\mathbb{Q}(\theta),\mathbb{Q}(i\theta)$ are $\mathbb{Q}$-isomorphic but distinct.
\wrec Part (2) of the Fundamental Theorem: conjugate subgroups have conjugate (hence $F$-isomorphic) fixed fields, and a non-normal subgroup gives a non-Galois, hence properly conjugated, field.
\wsol Compute $\sigma\langle \tau\rangle\sigma^{-1}=\langle \sigma\tau\sigma^{-1}\rangle$. Since $\sigma\tau\sigma^{-1}=\sigma^2\tau$ (from $\tau\sigma=\sigma^{-1}\tau$, so $\sigma\tau=\tau\sigma^{-1}$ and $\sigma\tau\sigma^{-1}=\tau\sigma^{-2}=\tau\sigma^2=\sigma^2\tau$ using $\tau\sigma^2=\sigma^{-2}\tau=\sigma^2\tau$), we get $\sigma\langle \tau\rangle\sigma^{-1}=\langle \sigma^2\tau\rangle$. Hence by (2), $\sigma(\Fix(\langle \tau\rangle))=\Fix(\langle \sigma^2\tau\rangle)$, i.e.\ $\sigma(\mathbb{Q}(\theta))=\mathbb{Q}(\sigma\theta)=\mathbb{Q}(i\theta)$. The two fields $\mathbb{Q}(\theta)$ and $\mathbb{Q}(i\theta)$ are distinct (one is real, the other is not) but $\sigma$ is a $\mathbb{Q}$-isomorphism between them. Sanity check: both are roots-of-$x^4-2$ adjunctions, $[\mathbb{Q}(\theta):\mathbb{Q}]=[\mathbb{Q}(i\theta):\mathbb{Q}]=4$, and neither is normal over $\mathbb{Q}$ (each contains only one root pair of $x^4-2$), exactly as predicted for fixed fields of non-normal subgroups.
\end{wex}

\begin{proof}[Idea]
The minimal polynomial of $\zeta_p$ over $\mathbb{Q}$ is the $p$-th cyclotomic polynomial $\Phi_p(x)=x^{p-1}+\cdots+x+1$, irreducible (Eisenstein after $x\mapsto x+1$), so $[\mathbb{Q}(\zeta_p):\mathbb{Q}]=p-1$. The extension is the splitting field of $x^p-1$ (separable, since $p\neq0$ in $\mathbb{Q}$), hence Galois. An automorphism must send $\zeta_p$ to another primitive root $\zeta_p^a$ with $a\in\{1,\dots,p-1\}$, and $\sigma_a\sigma_b=\sigma_{ab}$, giving $\Gal\cong(\mathbb{Z}/(p)\mathbb{Z})^{\times}$, which is cyclic of order $p-1$ because $(\mathbb{Z}/(p)\mathbb{Z})^{\times}$ is cyclic for $p$ prime. Subgroups of a cyclic group are unique of each order, so intermediate fields are unique of each degree.
\end{proof}

\begin{wex}{The unique quadratic subfield of $\mathbb{Q}(\zeta_p)$}
Show $\mathbb{Q}(\zeta_p)$ contains a unique quadratic subfield, and identify it as $\mathbb{Q}(\sqrt{p^{*}})$ with $p^{*}=(-1)^{(p-1)/2}p$.
\wrec Cyclic group of order $p-1$ (even) has a unique subgroup of index $2$, hence a unique degree-$2$ subfield; the quadratic Gauss sum pins it down.
\wsol $\Gal\cong\mathbb{Z}/((p-1))\mathbb{Z}$ has a unique subgroup of index $2$ (the squares in $(\mathbb{Z}/(p)\mathbb{Z})^{\times}$), so by the Fundamental Theorem a unique quadratic subfield $E_2=\Fix(\text{squares})$. The quadratic Gauss sum $g=\sum_{a=1}^{p-1}\bigl(\tfrac{a}{p}\bigr)\zeta_p^{a}$ satisfies $g^2=p^{*}=(-1)^{(p-1)/2}p$ and lies in $\mathbb{Q}(\zeta_p)$, so $E_2=\mathbb{Q}(g)=\mathbb{Q}(\sqrt{p^{*}})$. Sanity check: for $p=5$, $p^{*}=(-1)^2\cdot5=5$, and indeed $\mathbb{Q}(\zeta_5)\supset\mathbb{Q}(\sqrt5)$ (the real subfield $\mathbb{Q}(\cos72^\circ)=\mathbb{Q}(\tfrac{-1+\sqrt5}{4})$); for $p=3$, $p^{*}=(-1)^1\cdot3=-3$ and $\mathbb{Q}(\zeta_3)=\mathbb{Q}(\sqrt{-3})$, matching $\zeta_3=\tfrac{-1+\sqrt{-3}}{2}$.
\end{wex}

\begin{wex}{Subfields of $\mathbb{Q}(\zeta_7)$}
List all subfields of $\mathbb{Q}(\zeta_7)$ and their degrees over $\mathbb{Q}$.
\wrec $\Gal(\mathbb{Q}(\zeta_7)/\mathbb{Q})\cong\mathbb{Z}/(6)\mathbb{Z}$, cyclic; subfields correspond to divisors of $6$, one per divisor.
\wsol Divisors of $6$ are $1,2,3,6$, so there are subfields of degrees $1,2,3,6$: $\mathbb{Q}$; the unique quadratic $\mathbb{Q}(\sqrt{-7})$ (since $7^{*}=(-1)^3\cdot7=-7$); the unique cubic $E_3=\Fix(\text{the order-}2\text{ subgroup})$, which is the real subfield $\mathbb{Q}(\zeta_7+\zeta_7^{-1})=\mathbb{Q}(\cos\tfrac{2\pi}{7})$; and $\mathbb{Q}(\zeta_7)$ itself. Sanity check: $4$ divisors of $6$ give $4$ subfields; the cubic $\mathbb{Q}(\cos\tfrac{2\pi}{7})$ is real of degree $3$ (it is $\Fix$ of complex conjugation $\zeta\mapsto\zeta^{-1}$, the unique order-$2$ subgroup), and $[\mathbb{Q}(\zeta_7):\mathbb{Q}(\cos\tfrac{2\pi}{7})]=2$ as it adjoins back the non-real $\zeta_7$.
\end{wex}

\begin{wex}{The fixed field of complex conjugation in $\mathbb{Q}(\zeta_p)$}
Identify $\Fix(\langle c\rangle)$ where $c\colon\zeta_p\mapsto\zeta_p^{-1}$ is complex conjugation.
\wrec $c=\sigma_{-1}$ has order $2$ in the cyclic group $\Gal$; its fixed field has degree $(p-1)/2$ and is the maximal real subfield.
\wsol Complex conjugation fixes $\eta=\zeta_p+\zeta_p^{-1}=2\cos\tfrac{2\pi}{p}\in\mathbb{R}$, and $\mathbb{Q}(\eta)$ is real of degree $(p-1)/2$ over $\mathbb{Q}$. Since $\langle c\rangle$ has order $2$, Artin gives $[\mathbb{Q}(\zeta_p):\Fix(\langle c\rangle)]=2$, so $[\Fix(\langle c\rangle):\mathbb{Q}]=(p-1)/2=[\mathbb{Q}(\eta):\mathbb{Q}]$, forcing $\Fix(\langle c\rangle)=\mathbb{Q}(\eta)=\mathbb{Q}(\zeta_p)\cap\mathbb{R}$. Sanity check: $\langle c\rangle$ is normal (the group is abelian), so $\mathbb{Q}(\eta)$ is Galois over $\mathbb{Q}$ of degree $(p-1)/2$ with group $\Gal/\langle c\rangle\cong\mathbb{Z}/(((p-1)/2))\mathbb{Z}$, cyclic -- the maximal totally real subfield, as expected.
\end{wex}

\begin{wex}{Galois over an intermediate field that is not Galois over the base}
In $K=\mathbb{Q}(\theta,i)$ with $\theta=2^{1/4}$, show $K/\mathbb{Q}(\theta)$ is Galois even though $\mathbb{Q}(\theta)/\mathbb{Q}$ is not.
\wrec ``Galois'' is relative: $K/E$ is always Galois for any intermediate $E$ (it is the splitting field of the same separable polynomial over $E$), but $E/F$ is Galois only when $\Gal(K/E)\nor\Gal(K/F)$.
\wsol Over $E=\mathbb{Q}(\theta)$, the polynomial $x^4-2=(x-\theta)(x+\theta)(x^2+\theta^2)$ has $K=E(i)$ as splitting field, separable, so $K/E$ is Galois with $\Gal(K/E)=\langle \tau\rangle$ of order $2$. But $\langle \tau\rangle$ is not normal in $D_8$, so $E/\mathbb{Q}$ is not Galois -- consistent with $\mathbb{Q}(\theta)$ containing only the two real roots $\pm\theta$ of $x^4-2$. Sanity check: $[K:E]=2=\abs{\langle \tau\rangle}$ confirms $K/E$ Galois by (3); and the failure of normality of $\langle \tau\rangle$ in $G$ is exactly the obstruction (3) of the Fundamental Theorem to $E/\mathbb{Q}$ being Galois.
\end{wex}

\begin{remark}
The relativity in the last example is the most common source of confusion. Being Galois is a property of a \emph{pair} of fields, never of a single field. In a tower $F\subseteq E\subseteq K$ with $K/F$ Galois, $K/E$ is automatically Galois, but $E/F$ is Galois precisely when the corresponding subgroup is normal. The Fundamental Theorem is what converts the field-theoretic question (is $E/F$ normal?) into a finite group-theoretic one (is $\Gal(K/E)\nor\Gal(K/F)$?).
\end{remark}

Define the maps $\sigma$ and $\tau$ of $k(t)$ to itself by $\sigma f(t)=f\left(\dfrac{1}{1-t}\right)$ and $\tau f(t)=f\left(\dfrac{1}{t}\right)$ for $f(t)\in k(t)$.
\begin{enumerate}
\item[(a)] Prove that $\sigma$ and $\tau$ are automorphisms of $k(t)$ (cf.\ Exercise 8 of Section 1) and that the group $G=\langle\sigma,\tau\rangle$ generated by them is isomorphic to $S_3$.
\item[(b)] Prove that the element $I=\dfrac{(t^2-t+1)^3}{t^2(t-1)^2}$ is fixed by all the elements of $G$.
\item[(c)] Prove that $k(I)$ is precisely the fixed field of $G$ in $k(t)$ [compute the degree of the extension].
\end{enumerate}

\item Prove that the fixed field of the subgroup of automorphisms generated by $\tau$ in the previous problem is $k(t+\dfrac{1}{t})$. Prove that the fixed field of the subgroup generated by the automorphism $\tau\sigma^2$ (which maps $t$ to $1-t$) is $k(t(1-t))$. Determine the fixed field of the subgroup generated by $\tau\sigma$ and the fixed field of the subgroup generated by $\sigma$.

\item Let $K$ be a finite extension of $F$ of degree $n$. Let $\alpha$ be an element of $K$.
\begin{enumerate}
