\begin{definition}
The \emph{Galois group of the separable polynomial} $f$ over $F$ is $\Gal(K/F)$, where $K$ is a splitting field of $f$ over $F$, realized as a subgroup of $S_n$ via its faithful action permuting the $n$ roots. A different numbering of the roots conjugates this subgroup inside $S_n$, so the Galois group is well defined up to conjugacy in $S_n$.
\end{definition}

\begin{theorem}[{transitivity criterion}]
Let $f\in F[x]$ be separable with splitting field $K$ and Galois group $G\sgr S_n$ acting on the roots. Then $f$ is irreducible over $F$ if and only if $G$ acts \emph{transitively} on the roots.
\end{theorem}

\begin{proof}[Idea]
If $f$ is irreducible and $\alpha_i,\alpha_j$ are two roots, both have the same minimal polynomial $f$, so there is an $F$-isomorphism $F(\alpha_i)\to F(\alpha_j)$ sending $\alpha_i\mapsto\alpha_j$; since $K/F$ is normal this extends to some $\sigma\in G$, giving $\sigma\alpha_i=\alpha_j$. Hence $G$ is transitive. Conversely, if $f=gh$ factors nontrivially, the roots of $g$ form a proper nonempty subset stable under $G$ (automorphisms preserve $g$), so no element of $G$ carries a root of $g$ to a root of $h$, and the action is intransitive.
\end{proof}

\begin{remark}
A transitive subgroup of $S_n$ has order divisible by $n$ (orbit-stabilizer: the single orbit has size $n$, so $n\mid\abs{G}$). This is the same statement as $n=\deg f=[F(\alpha):F]$ divides $[K:F]=\abs{G}$ when $f$ is irreducible. The transitive subgroups of $S_n$ are thus the only candidates for Galois groups of irreducible polynomials, which is exactly why the classification of transitive subgroups of $S_3$ and $S_4$ (below) is so useful.
\end{remark}

\begin{wex}{A reducible quadratic versus an irreducible one}
Compare the Galois groups of $x^2-1$ and $x^2-2$ over $\mathbb{Q}$.
\wrec By the transitivity criterion the group is transitive on the two roots iff the quadratic is irreducible; over $\mathbb{Q}$ a quadratic is irreducible iff its discriminant is not a square.
\wsol For $x^2-1=(x-1)(x+1)$ the splitting field is $\mathbb{Q}$ itself, so $\Gal=1$, the trivial (intransitive) subgroup of $S_2$. For $x^2-2$ the roots are $\pm\sqrt2$, splitting field $\mathbb{Q}(\sqrt2)$ of degree $2$, so $\Gal\cong S_2=\mathbb{Z}/(2)\mathbb{Z}$, which swaps $\sqrt2\leftrightarrow-\sqrt2$ transitively. Sanity check: $S_2$ has order $2=[\mathbb{Q}(\sqrt2):\mathbb{Q}]$, and $2\mid\abs{G}$ as transitivity requires; for $x^2-1$ the order is $1$ and the action is intransitive, matching reducibility.
\end{wex}

\begin{wex}{Reading transitivity off a factorization}
Determine whether the Galois group of $(x^2-2)(x^2-3)$ over $\mathbb{Q}$ acts transitively on its four roots.
\wrec Transitivity holds iff the degree-$4$ polynomial is irreducible; here it factors, so expect intransitivity, and the group should preserve the partition of roots into the two quadratic factors.
\wsol The splitting field is $\mathbb{Q}(\sqrt2,\sqrt3)$, with $\Gal\cong V_4=\mathbb{Z}/(2)\mathbb{Z}\times\mathbb{Z}/(2)\mathbb{Z}$ generated by $\sqrt2\mapsto-\sqrt2$ and $\sqrt3\mapsto-\sqrt3$. No automorphism sends $\sqrt2$ to $\sqrt3$, so the action on $\{\pm\sqrt2,\pm\sqrt3\}$ has two orbits $\{\pm\sqrt2\}$ and $\{\pm\sqrt3\}$ -- intransitive. Sanity check: $\abs{V_4}=4=[\mathbb{Q}(\sqrt2,\sqrt3):\mathbb{Q}]$, and as a subgroup of $S_4$ it is $\langle (12),(34)\rangle$, which indeed fixes the partition $\{1,2\}\cup\{3,4\}$, consistent with the reducible factorization.
\end{wex}

\begin{theorem}[{the fundamental theorem on symmetric functions}]
Every symmetric polynomial in $x_1,\dots,x_n$ over $F$ is a polynomial in the elementary symmetric functions $s_1,\dots,s_n$, and this expression is unique. Equivalently, the fixed field of $S_n$ acting on $F(x_1,\dots,x_n)$ by permuting the variables is exactly $F(s_1,\dots,s_n)$.
\end{theorem}

\begin{proof}[Idea]
For existence one runs a lexicographic-ordering algorithm: the leading monomial $x_1^{a_1}\cdots x_n^{a_n}$ of a symmetric polynomial must have $a_1\ge a_2\ge\cdots\ge a_n$, and subtracting the matching monomial $s_1^{a_1-a_2}s_2^{a_2-a_3}\cdots s_n^{a_n}$ cancels the leading term, strictly lowering the order; the process terminates. Uniqueness amounts to algebraic independence of $s_1,\dots,s_n$ over $F$. The field-theoretic statement follows because $F(x_1,\dots,x_n)$ is the splitting field of $\prod_i(x-x_i)$ over $F(s_1,\dots,s_n)$, of degree $n!$.
\end{proof}

\begin{proof}[Idea]
$S_n$ acts on $F(x_1,\dots,x_n)$ by permuting variables, fixing exactly $E=F(s_1,\dots,s_n)$ by the previous theorem. By Artin's theorem the extension $F(x_1,\dots,x_n)/E$ is Galois with group $S_n$, of degree $\abs{S_n}=n!$. Since $[F(x_1,\dots,x_n):E]=n!$ is also the degree of the splitting field of the degree-$n$ general polynomial, that polynomial \emph{is} its defining polynomial, and its Galois group is all of $S_n$.
\end{proof}

\begin{wex}{Newton's identity for the power sum $p_2$}
With $p_k=x_1^k+\cdots+x_n^k$, express $p_2$ in terms of the elementary symmetric functions.
\wrec $p_2$ is symmetric, so by the fundamental theorem it is a polynomial in $s_1,\dots,s_n$; being homogeneous of degree $2$ it involves only $s_1^2$ and $s_2$.
\wsol Expand $s_1^2=\bigl(\sum_ix_i\bigr)^2=\sum_ix_i^2+2\sum_{i<j}x_ix_j=p_2+2s_2$, hence $p_2=s_1^2-2s_2$. Sanity check with $n=2$, $x_1=2,x_2=3$: $s_1=5,s_2=6$, so $s_1^2-2s_2=25-12=13$, and directly $p_2=4+9=13$. Agreement.
\end{wex}

\begin{wex}{The discriminant of $x^2+bx+c$ as a symmetric function}
Write $(x_1-x_2)^2$ in terms of $s_1=x_1+x_2$ and $s_2=x_1x_2$, and relate it to $x^2+bx+c$.
\wrec $(x_1-x_2)^2$ is symmetric (a square of the antisymmetric difference), so it is a polynomial in $s_1,s_2$; it is the discriminant of the quadratic with roots $x_1,x_2$.
\wsol $(x_1-x_2)^2=(x_1+x_2)^2-4x_1x_2=s_1^2-4s_2$. For $x^2+bx+c$ with roots $x_1,x_2$ we have $s_1=-b$, $s_2=c$, so the discriminant is $b^2-4c$. Sanity check: this is the classical discriminant of a quadratic, positive exactly when the two roots are distinct reals, and a perfect square in the base field exactly when the roots are rational -- consistent with $x^2-1$ (disc $4$, a square) versus $x^2-2$ (disc $8$, not a square) above.
\end{wex}

\begin{proof}[Idea]
A transposition $(ij)$ swaps the factor $(\alpha_i-\alpha_j)$ with $-(\alpha_i-\alpha_j)$ and permutes the remaining factors among themselves, so it negates $\Delta$; a general $\sigma$ multiplies $\Delta$ by $\operatorname{sgn}(\sigma)$. Hence $\sigma$ fixes $\Delta$ iff $\operatorname{sgn}(\sigma)=1$, i.e.\ $\sigma\in A_n$. Therefore $G\sgr A_n$ iff every element fixes $\Delta$, i.e.\ $\Delta\in\Fix(G)=F$; and $\Delta\in F$ iff its square $D$ has a square root in $F$. (Characteristic $2$ is excluded because there $\operatorname{sgn}$ is trivial and one needs the Berlekamp discriminant instead.)
\end{proof}

\begin{wex}{Recovering the quadratic discriminant from $\Delta$}
For $f=x^2+bx+c$ verify $D=\Delta^2=b^2-4c$ and interpret the criterion in $S_2$.
\wrec $S_2=\{e,(12)\}$ and $A_2=\{e\}$; the criterion says $G\sgr A_2$ (i.e.\ $G$ trivial, $f$ split) iff $D$ is a square.
\wsol With roots $\alpha_1,\alpha_2$, $\Delta=\alpha_1-\alpha_2$ and $D=(\alpha_1-\alpha_2)^2=(\alpha_1+\alpha_2)^2-4\alpha_1\alpha_2=b^2-4c$. If $D$ is a square in $F$ then $\Delta\in F$, the roots $\tfrac{-b\pm\sqrt D}{2}$ lie in $F$, and $G$ is trivial; if not, $G=S_2=\langle (12)\rangle$. Sanity check: $x^2-2$ has $D=8$, not a square in $\mathbb{Q}$, so $G=S_2$; $x^2-1$ has $D=4=2^2$, a square, so $G=A_2=1$ -- exactly the warmups above.
\end{wex}

\begin{proof}[Idea]
By the resultant formula $D=(-1)^{3\cdot2/2}R(f,f')=-R(f,f')=-\prod_i f'(\alpha_i)$ with $f'(x)=3x^2+p$. Using $\alpha_i^3=-p\alpha_i-q$ to reduce $f'(\alpha_i)=3\alpha_i^2+p$ and multiplying over the three roots (or expanding $\prod_{i<j}(\alpha_i-\alpha_j)^2$ via Newton's identities) gives $-4p^3-27q^2$.
\end{proof}

\begin{proof}[Idea]
Irreducibility forces $G$ transitive, so $3\mid\abs{G}$ and $G\in\{A_3,S_3\}$. The discriminant criterion sends $G$ into $A_3$ exactly when $D$ is a square. In the square case $\abs{G}=3$, so the splitting field already has degree $3$ and equals $F(\alpha)$; otherwise $\abs{G}=6$ and adjoining $\sqrt D$ supplies the missing quadratic.
\end{proof}

\begin{wex}{$x^3-2$ over $\mathbb{Q}$ has Galois group $S_3$}
Compute the Galois group and splitting field of $x^3-2$ over $\mathbb{Q}$.
\wrec Eisenstein at $2$ gives irreducibility; the discriminant criterion then chooses between $A_3$ and $S_3$. Here $p=0$, $q=-2$.
\wsol $D=-4p^3-27q^2=-27\cdot4=-108$, which is negative, hence not a square in $\mathbb{Q}$, so $\Gal\cong S_3$ and $\idx K\mathbb{Q}=6$. Concretely the roots are $\sqrt[3]2,\ \zeta_3\sqrt[3]2,\ \zeta_3^2\sqrt[3]2$, so $K=\mathbb{Q}(\sqrt[3]2,\zeta_3)$ with $\idx K\mathbb{Q}=3\cdot2=6$, matching $\abs{S_3}=6$. Sanity check: $\sqrt D=\sqrt{-108}=6\sqrt{-3}$, and indeed $\mathbb{Q}(\sqrt{-3})=\mathbb{Q}(\zeta_3)$ is the quadratic subfield $\Fix(A_3)$ inside $K$, exactly the $F(\sqrt D)$ predicted by the theorem.
\end{wex}

\begin{wex}{$x^3-3x-1$ has Galois group $C_3$ and is totally real}
Show $x^3-3x-1$ is irreducible over $\mathbb{Q}$ with cyclic Galois group of order $3$, and that all its roots are real.
\wrec Rational-root test gives irreducibility (a cubic with no rational root is irreducible over $\mathbb{Q}$); then the discriminant decides. Here $p=-3$, $q=-1$.
\wsol The only candidate rational roots are $\pm1$, and $f(1)=-3$, $f(-1)=1$, both nonzero, so $f$ is irreducible. Discriminant $D=-4p^3-27q^2=-4(-27)-27(1)=108-27=81=9^2$, a square in $\mathbb{Q}$. Hence $\Gal\cong A_3=C_3$, $\idx K\mathbb{Q}=3$, and $K=\mathbb{Q}(\theta)$ for any root $\theta$. Since $D=81>0$ all three roots are real, so $\mathbb{Q}(\theta)\subset\mathbb{R}$ is a totally real cyclic cubic field. Sanity check: $D>0$ means the cubic has three distinct real roots, consistent with the field being real; and a cubic field generated by one root that already contains all conjugates must be Galois of degree $3$, forcing the cyclic group $C_3$, as found.
\end{wex}

\begin{wex}{A cubic with a quadratic-subfield discriminant: $x^3-x-1$}
Determine the Galois group of $x^3-x-1$ over $\mathbb{Q}$.
\wrec No rational root (test $\pm1$) gives irreducibility; compute $D$ with $p=-1$, $q=-1$.
\wsol $f(1)=1-1-1=-1$ and $f(-1)=-1+1-1=-1$, both nonzero, so $f$ is irreducible. $D=-4(-1)^3-27(-1)^2=4-27=-23$, not a square in $\mathbb{Q}$ (it is negative), so $\Gal\cong S_3$ with $\idx K\mathbb{Q}=6$ and $K=\mathbb{Q}(\alpha,\sqrt{-23})$. Sanity check: $D=-23<0$ signals exactly one real root and a complex-conjugate pair, so complex conjugation is a transposition in $G$, which an order-$3$ group $A_3$ cannot contain -- it must be $S_3$, agreeing with the discriminant test.
\end{wex}

\begin{wex}{Forcing $A_3$ by engineering a square discriminant}
For which integers $q$ does $x^3-3q^2x-q^3$ have a square discriminant pattern, and what does that say (when irreducible)?
\wrec Substitute into $D=-4p^3-27q^2$ with $p=-3q^2$ and the constant term $-q^3$; a perfect-square $D$ forces $A_3$ when the cubic is irreducible.
\wsol With $p=-3q^2$ and constant term $c=-q^3$, the discriminant of $x^3+px+c$ is $D=-4(-3q^2)^3-27(-q^3)^2=-4(-27q^6)-27q^6=108q^6-27q^6=81q^6=(9q^3)^2$, always a perfect square. So whenever this cubic is irreducible over $\mathbb{Q}$, its group is $A_3=C_3$. Sanity check: at $q=1$ this is $x^3-3x-1$ from the totally real example, where indeed $D=81=(9)^2$ and the group was $C_3$; the formula $81q^6$ specializes correctly.
\end{wex}

\begin{proof}[Idea]
$\disc(g)=\disc(f)$ because $\beta_1-\beta_2=(\alpha_1-\alpha_4)(\alpha_2-\alpha_3)$ and the like, so $\prod_{i<j}(\beta_i-\beta_j)^2$ rearranges into $\prod_{i<j}(\alpha_i-\alpha_j)^2$. The image of $G$ in $S_4/V_4\cong S_3$ is exactly $\Gal(g)$ as a permutation group on the $\beta_i$, so: $g$ irreducible $\Longleftrightarrow$ that image is transitive, i.e.\ $A_3$ or $S_3$ $\Longleftrightarrow$ $3\mid\abs G$ $\Longleftrightarrow$ $G\in\{S_4,A_4\}$ (distinguished by $D$; note $A_4$ maps onto $A_4/V_4\cong A_3$, not onto $S_3$); $g$ totally split $\Longleftrightarrow$ trivial image $\Longleftrightarrow$ $G\sgr V_4$, which for an irreducible (hence transitive) quartic forces $G=V_4$; $g$ with one root in $F$ $\Longleftrightarrow$ image of order $2$ $\Longleftrightarrow$ $\abs G=8$ or $4$, i.e.\ $D_8$ or $C_4$, separated by the behaviour of $f$ over $F(\sqrt D)$.
\end{proof}

\begin{wex}{$x^4+1$ over $\mathbb{Q}$ has Galois group $V_4$}
Determine the Galois group and splitting field of $x^4+1$ over $\mathbb{Q}$.
\wrec $x^4+1=\Phi_8$ is irreducible (Eisenstein after $x\mapsto x+1$), splitting field $\mathbb{Q}(\zeta_8)$; abelian Galois group $(\mathbb{Z}/(8)\mathbb{Z})^{\times}\cong V_4$. Cross-check with the resolvent cubic, here $p=0,q=0,r=1$.
\wsol The roots are the primitive $8$th roots of unity, so $K=\mathbb{Q}(\zeta_8)$ and $\Gal(\mathbb{Q}(\zeta_8)/\mathbb{Q})\cong(\mathbb{Z}/(8)\mathbb{Z})^{\times}=\{1,3,5,7\}\cong\mathbb{Z}/(2)\mathbb{Z}\times\mathbb{Z}/(2)\mathbb{Z}=V_4$. Resolvent cubic: $g(x)=x^3-0\cdot x^2-4x+(0-0)=x^3-4x=x(x-2)(x+2)$, which splits completely over $\mathbb{Q}$, so the table gives $G=V_4$. Sanity check: using the roots $0,2,-2$ of $g$, $D=\disc(g)=\bigl[(0-2)(0+2)(2-(-2))\bigr]^2=[(-2)(2)(4)]^2=(-16)^2=256=16^2$, a square -- consistent with $V_4\sgr A_4$. Also $\zeta_8=\tfrac{\sqrt2}2(1+i)$, so $K=\mathbb{Q}(i,\sqrt2)$, a biquadratic field of degree $4$, matching $\abs{V_4}=4$.
\end{wex}

\begin{wex}{$x^4-2$ over $\mathbb{Q}$ has Galois group $D_8$}
Determine the Galois group of $x^4-2$ over $\mathbb{Q}$ (cf.\ Section 14.2).
\wrec Eisenstein at $2$ gives irreducibility; the splitting field $\mathbb{Q}(\sqrt[4]2,i)$ has degree $8$ (computed in 14.2), so $\abs G=8$ and $G=D_8$. Confirm via the resolvent cubic with $p=0,q=0,r=-2$.
\wsol The roots are $\pm\sqrt[4]2,\pm i\sqrt[4]2$; $K=\mathbb{Q}(\sqrt[4]2,i)$ with $\idx K\mathbb{Q}=8$, so $G$ is a transitive order-$8$ subgroup of $S_4$, i.e.\ a $D_8$. Resolvent cubic: $g(x)=x^3-0\cdot x^2-4(-2)x+(0-0)=x^3+8x=x(x^2+8)$, which has exactly one rational root ($x=0$) since $x^2+8$ is irreducible over $\mathbb{Q}$. The table then gives $D_8$ or $C_4$; to separate, $D=\disc(f)$ for $x^4-2$ is $-2048<0$, not a square, and $f=x^4-2$ stays irreducible over $\mathbb{Q}(\sqrt D)=\mathbb{Q}(\sqrt{-2})$ (adjoining the root $\sqrt[4]2$ to $\mathbb{Q}(\sqrt{-2})$ gives a field containing $\sqrt2$ and $\sqrt{-2}$, hence $i$, so it is all of $K$ and has degree $8/2=4$ over $\mathbb{Q}(\sqrt{-2})$), giving $D_8$. Sanity check: $\abs{D_8}=8=\idx K\mathbb{Q}$, and $D_8$ is the Sylow $2$-subgroup of $S_4$; the geometric picture $\langle r,s\mid r^4=s^2=1,\ srs=r^{-1}\rangle$ matches $r:\sqrt[4]2\mapsto i\sqrt[4]2$ (order $4$) and $s$ = complex conjugation (order $2$).
\end{wex}

\begin{wex}{Computing and factoring a resolvent cubic: $x^4+8x+12$}
Form the resolvent cubic of $x^4+8x+12$ over $\mathbb{Q}$ and read off the Galois group.
\wrec This $f$ is irreducible over $\mathbb{Q}$ (no rational roots and no factorization into rational quadratics). Apply the method with $p=0$, $q=8$, $r=12$.
\wsol Resolvent: $g(x)=x^3-px^2-4rx+(4pr-q^2)=x^3-48x-64$. Test rational roots (divisors of $64$): $g(-4)=-64+192-64=64\ne0$; $g(8)=512-384-64=64\ne0$; $g(-2)=-8+96-64=24\ne0$; in fact $g$ has no rational root, so it is irreducible over $\mathbb{Q}$. Hence $G\in\{S_4,A_4\}$, decided by $D=\disc(g)=\disc(f)$. Compute $D=-4p^3-27\cdot(\text{const of }g)^2$ for $g=x^3-48x-64$: $D=-4(-48)^3-27(-64)^2=-4(-110592)-27(4096)=442368-110592=331776=576^2$, a perfect square. So $G=A_4$. Sanity check: $576^2=331776$ indeed, and $A_4$ is the unique transitive subgroup of $S_4$ of order $12$; $D$ a square places $G\sgr A_4$, while irreducibility of $g$ rules out the order-$4$ and order-$8$ groups, leaving exactly $A_4$.
\end{wex}

\begin{wex}{Distinguishing $D_8$ from $C_4$: $x^4+1$ revisited as a biquadratic $V_4$ versus a $C_4$ example}
Use the resolvent-cubic table to separate the $V_4$, $D_8$, $C_4$ outcomes for biquadratics $x^4+px^2+r$.
\wrec For $q=0$ the resolvent cubic is $g(x)=x^3-px^2-4rx+4pr=(x-p)(x^2-4r)$, which always has the rational root $x=p$. So a biquadratic never gives $S_4$ or $A_4$; the group is among $V_4,C_4,D_8$, decided by squareness of $r$ and of $r(p^2-4r)$.
\wsol Since $g$ factors as $(x-p)(x^2-4r)$, the quadratic factor $x^2-4r$ splits over $\mathbb{Q}$ iff $r$ is a square (then $g$ splits completely, $G=V_4$); if $r$ is not a square, $g$ has the single rational root $p$, so $G=D_8$ or $C_4$. The standard refinement: $G=V_4\Longleftrightarrow r$ is a square; $G=C_4\Longleftrightarrow r(p^2-4r)$ is a square (but $r$ is not); $G=D_8$ otherwise. For $x^4+1$ ($p=0,r=1$): $r=1$ is a square, so $V_4$ -- matching the earlier computation. For $x^4-x^2+1=\Phi_{12}$ ($p=-1,r=1$): again $r=1$ a square, $V_4$ (indeed $\mathbb{Q}(\zeta_{12})$ has group $(\mathbb{Z}/(12)\mathbb{Z})^{\times}\cong V_4$). For a genuine $C_4$ take $x^4+5x^2+5$ ($p=5,r=5$): here $r=5$ is not a square but $r(p^2-4r)=5(25-20)=25=5^2$ is a square, so $G=C_4$. Sanity check: $x^4+x^2-1$ ($p=1,r=-1$) has $r=-1$ (not a square) and $r(p^2-4r)=(-1)(1+4)=-5$ (not a square), giving $D_8$; $x^4-x^2+1$ giving $V_4$ and $x^4+5x^2+5$ giving $C_4$ exhibit all three biquadratic outcomes, so the criterion is internally consistent.
\end{wex}

\begin{wex}{A full $S_4$ example: $x^4+x+1$ over $\mathbb{Q}$}
Determine the Galois group of $x^4+x+1$ over $\mathbb{Q}$.
\wrec Irreducible over $\mathbb{Q}$ (no rational roots; the only quadratic-times-quadratic factorization over $\mathbb{Z}$ would need integer coefficients that fail to match). Apply the method with $p=0,q=1,r=1$.
\wsol Resolvent: $g(x)=x^3-0\cdot x^2-4x+(0-1)=x^3-4x-1$. Rational-root test $\pm1$: $g(1)=-4$, $g(-1)=2$, both nonzero, so $g$ is irreducible over $\mathbb{Q}$. Hence $G\in\{S_4,A_4\}$. Discriminant of $g=x^3-4x-1$: $D=-4(-4)^3-27(-1)^2=-4(-64)-27=256-27=229$, which is prime, hence not a perfect square. So $G=S_4$. Sanity check: $\disc(f)=\disc(g)=229$ is not a square, placing $G\not\sgr A_4$; combined with $g$ irreducible (transitive image in $S_3$) this forces the full $S_4$, the generic case for a quartic. (Complex conjugation gives no extra evidence here: $D=229>0$ means the number of complex-conjugate pairs of roots is even, and in fact $x^4+x+1>0$ on $\mathbb{R}$, so the roots form two conjugate pairs and complex conjugation is a double transposition, which lies in $A_4$; it is the non-square discriminant that excludes $A_4$.)
\end{wex}

\begin{pitfall}
When applying the discriminant criterion, "$D$ is a square" always means a square \emph{in the base field $F$}, not merely a positive integer. For example $\disc(x^3-x-1)=-23$ is negative, so it cannot be a square in $\mathbb{Q}$ regardless of magnitude, forcing $S_3$. Conversely $D$ can be a large positive non-square (like $229$ above): always factor or test for squareness in $F$, never judge by size or sign alone. And the resolvent-cubic table requires $f$ to be \emph{irreducible} first -- a reducible quartic has an intransitive group not on the list.
\end{pitfall}

\begin{wex}{Subfield tower for the $S_4$ quartic $x^4+x+1$}
Describe the distinguished subfields of the splitting field $K$ of $x^4+x+1$ predicted by the $S_4$ correspondence.
\wrec With $G=S_4$ (previous example, $D=229$, resolvent $g=x^3-4x-1$ irreducible), the normal series $1\nor V_4\nor A_4\nor S_4$ gives a canonical tower $F\subset F(\sqrt D)\subset\Fix(V_4)\subset K$.
\wsol Here $\idx K\mathbb{Q}=\abs{S_4}=24$. The quadratic resolvent is $\mathbb{Q}(\sqrt D)=\mathbb{Q}(\sqrt{229})$ (degree $2$, $=\Fix(A_4)$). The splitting field of the resolvent cubic $g=x^3-4x-1$ is $\Fix(V_4)$, of degree $[S_4:V_4]=6$ over $\mathbb{Q}$ and containing $\mathbb{Q}(\sqrt{229})$ (since $\disc g=229$ is a non-square, $\Gal(g)=S_3$). Finally $K$ itself has degree $24$. Sanity check: the degrees multiply correctly along the tower, $2\cdot3\cdot4=24$, matching $\abs{V_4}=4$, $[A_4:V_4]=3$, $[S_4:A_4]=2$; and $\mathbb{Q}(\sqrt{229})\subset\Fix(V_4)$ because $A_4\supset V_4$ forces $\Fix(A_4)\subset\Fix(V_4)$, exactly the inclusion-reversal of the Galois correspondence.
\end{wex}

\begin{wex}{Why $x^4-25$ is reducible and falls off the transitive list}
Determine the Galois group of $x^4-25$ over $\mathbb{Q}$ and explain why the resolvent-cubic table does not apply directly.
\wrec $x^4-25=(x^2-5)(x^2+5)$ is reducible, so its group is intransitive and not among the five transitive subgroups; analyze it as a compositum instead.
\wsol The roots are $\pm\sqrt5,\pm i\sqrt5$, so $K=\mathbb{Q}(\sqrt5,i\sqrt5)=\mathbb{Q}(\sqrt5,i)$, a biquadratic field of degree $4$ with $\Gal\cong V_4=\mathbb{Z}/(2)\mathbb{Z}\times\mathbb{Z}/(2)\mathbb{Z}$ generated by $\sqrt5\mapsto-\sqrt5$ and $i\mapsto-i$. As a subgroup of $S_4$ acting on $\{\sqrt5,-\sqrt5,i\sqrt5,-i\sqrt5\}$ it is intransitive: $\{\pm\sqrt5\}$ and $\{\pm i\sqrt5\}$ are separate orbits. Sanity check: although $\abs G=4$ matches a transitive $V_4$, the action here is the \emph{intransitive} $\langle (12),(34)\rangle$, not the transitive $\langle (12)(34),(13)(24)\rangle$; this is why the table -- which presupposes an irreducible quartic -- cannot be applied, and we read the group off the compositum $\mathbb{Q}(\sqrt5)\cdot\mathbb{Q}(i)$ directly.
\end{wex}

\begin{wex}{Locating complex conjugation as a permutation: $x^4-2$}
Identify complex conjugation as an explicit permutation of the roots of $x^4-2$ and confirm it lies in $D_8\setminus A_4$.
\wrec Complex conjugation restricts to an automorphism of the splitting field $\mathbb{Q}(\sqrt[4]2,i)$; it fixes the real roots and swaps each complex root with its conjugate, so it is a product of transpositions.
\wsol Number the roots $\alpha_1=\sqrt[4]2,\ \alpha_2=-\sqrt[4]2,\ \alpha_3=i\sqrt[4]2,\ \alpha_4=-i\sqrt[4]2$. Conjugation fixes $\alpha_1,\alpha_2$ (real) and swaps $\alpha_3\leftrightarrow\alpha_4$, so it is the transposition $(34)$, an odd permutation. Since $D_8=\langle r,s\rangle$ with $r=(1324)$ (a $4$-cycle sending $\sqrt[4]2\mapsto i\sqrt[4]2$) and $s=(34)$, conjugation is the reflection $s\in D_8$. Sanity check: $(34)$ is odd, so it is \emph{not} in $A_4$; this is consistent with $D=\disc(x^4-2)=-2048$ being a non-square (placing $G\not\sgr A_4$), and the presence of a transposition-type element confirms $G$ is not the all-even $A_4$ or $V_4$.
\end{wex}

\begin{wex}{The general quartic has group $S_4$}
Explain why the general quartic $x^4-s_1x^3+s_2x^2-s_3x+s_4$ over $\mathbb{Q}(s_1,s_2,s_3,s_4)$ has Galois group $S_4$.
\wrec This is the $n=4$ case of the general-polynomial theorem: over the field of symmetric functions the Galois group of $\prod_i(x-x_i)$ is the full $S_n$.
\wsol Take $x_1,x_2,x_3,x_4$ independent, $E=\mathbb{Q}(s_1,s_2,s_3,s_4)$ with the $s_i$ the elementary symmetric functions. Then $\mathbb{Q}(x_1,\dots,x_4)/E$ is Galois with group $S_4$ permuting the $x_i$, of degree $4!=24$. The Galois group $S_4$ permutes the roots $\beta_1,\beta_2,\beta_3$ of the resolvent cubic $g$ transitively and contains odd permutations, so $g$ is irreducible over $E$ and $D=\disc(f)$ is not a square in $E$, landing in the top row of the table: $S_4$. Sanity check: $[\mathbb{Q}(x_1,\dots,x_4):E]=24=\abs{S_4}$, and the normal tower $1\nor V_4\nor A_4\nor S_4$ exhibits the classical resolvent fields $E(\sqrt D)\subset E(\beta_1,\beta_2,\beta_3)$, the abstract template every specific $S_4$-quartic (like $x^4+x+1$) specializes.
\end{wex}

\begin{remark}
Throughout this section, to keep the cyclic theory uniform we usually work over a field $F$ of characteristic $0$ (or characteristic not dividing the $n$ in question), and we freely adjoin roots of unity. Adjoining $\zeta_n$ is itself a radical step (a root of $x^n-1$), and $F(\zeta_n)/F$ is abelian, hence harmless for solvability. The genuinely new content is the structure of the individual cyclic steps, to which we turn next.
\end{remark}

\begin{wex}{$\mathbb{Q}(\sqrt[3]{2},\zeta_3)$ is a radical extension}
Exhibit a radical tower realizing the splitting field of $x^3-2$ over $\mathbb{Q}$.
\wrec A radical tower adjoins one root at a time; the splitting field of $x^3-2$ is $\mathbb{Q}(\sqrt[3]{2},\zeta_3)$, and both generators are radicals ($\zeta_3$ a cube root of $1$, $\sqrt[3]{2}$ a cube root of $2$).
\wsol Take $K_0=\mathbb{Q}$, $K_1=\mathbb{Q}(\zeta_3)=\mathbb{Q}(\sqrt{-3})$ (adjoin a square root of $-3$, since $\zeta_3=\tfrac{-1+\sqrt{-3}}{2}$), and $K_2=K_1(\sqrt[3]{2})$. Then $\zeta_3^{\,3}=1\in K_0$ and $(\sqrt[3]2)^3=2\in K_1$, so the tower is radical, and $K_2=\mathbb{Q}(\sqrt[3]2,\zeta_3)$ is the splitting field of $x^3-2$. Sanity check: $[K_2:\mathbb{Q}]=[K_2:K_1]\cdot[K_1:\mathbb{Q}]=3\cdot2=6=\abs{S_3}$, matching $\Gal(x^3-2/\mathbb{Q})\cong S_3$.
\end{wex}

\begin{proof}[Idea]
The additive analogue of Hilbert 90 (the trace form: $\Tr_{K/F}(\beta)=0\iff\beta=\gamma-\sigma(\gamma)$) applies. Since $\charac F=p$, $\Tr_{K/F}(-1)=p\cdot(-1)=0$, so $-1=\alpha-\sigma(\alpha)$ for some $\alpha$, i.e.\ $\sigma(\alpha)=\alpha+1$. Then $\sigma(\alpha^p-\alpha)=(\alpha+1)^p-(\alpha+1)=\alpha^p+1-\alpha-1=\alpha^p-\alpha$, so $a:=\alpha^p-\alpha\in F$, and the conjugates $\alpha,\alpha+1,\dots,\alpha+(p-1)$ are distinct, forcing $[F(\alpha):F]=p$.
\end{proof}

\begin{wex}{The Galois group of $x^n-a$ over $\mathbb{Q}(\zeta_n)$}
With $F=\mathbb{Q}(\zeta_5)$ and $a=2$, identify $\Gal(F(\sqrt[5]2)/F)$.
\wrec $F$ contains $\zeta_5$, so by the Kummer theorem $F(\sqrt[5]2)/F$ is cyclic; its degree is the order of $2$ in $F^{\times}/(F^{\times})^5$.
\wsol $x^5-2$ is irreducible over $\mathbb{Q}$ (Eisenstein at $2$), so $\idx{\mathbb{Q}(\sqrt[5]2)}\mathbb{Q}=5$; since $\idx F\mathbb{Q}=\varphi(5)=4$ is coprime to $5$, the degree $[F(\sqrt[5]2):F]$ stays $5$, hence $2$ has order $5$ in $F^{\times}/(F^{\times})^5$ and $\Gal(F(\sqrt[5]2)/F)\cong\mathbb{Z}/(5)\mathbb{Z}$. The generator sends $\sqrt[5]2\mapsto\zeta_5\sqrt[5]2$. Sanity check: $5$ is prime, so the only possible degrees are $1$ or $5$; degree $1$ would mean $2$ is a $5$th power in $F$, impossible since $\sqrt[5]2$ already generates a degree-$5$ extension of $\mathbb{Q}$.
\end{wex}

\begin{wex}{A Lagrange resolvent computation in a $C_3$ extension}
Let $K/F$ be cyclic of degree $3$ with $\Gal(K/F)=\gen\sigma$ and $\zeta=\zeta_3\in F$. For $\theta\in K$ form $r=(\theta,\zeta)=\theta+\zeta\sigma\theta+\zeta^2\sigma^2\theta$ and verify $r^3\in F$.
\wrec $\sigma(\theta,\zeta)=\zeta^{-1}(\theta,\zeta)$ for any resolvent, so $r$ is an eigenvector of $\sigma$ with eigenvalue $\zeta^{-1}$ and $r^3$ is $\sigma$-fixed.
\wsol Apply $\sigma$: $\sigma(r)=\sigma\theta+\zeta\sigma^2\theta+\zeta^2\sigma^3\theta=\sigma\theta+\zeta\sigma^2\theta+\zeta^2\theta$ (since $\sigma^3=\id$). Factor out $\zeta^{-1}=\zeta^2$: $\zeta^2 r=\zeta^2\theta+\sigma\theta+\zeta\sigma^2\theta$, which equals $\sigma(r)$. So $\sigma(r)=\zeta^{-1} r$, hence $\sigma(r^3)=\zeta^{-3}r^3=r^3$, so $r^3\in\Fix(\gen\sigma)=F$. Sanity check: $\sigma$ has order $3$ and $r\neq0$ generically, so $r$ cannot be $\sigma$-fixed (that would put $r\in F$); indeed its eigenvalue $\zeta^{-1}\neq1$ confirms $r\notin F$ while $r^3\in F$ -- exactly a radical generator.
\end{wex}

\begin{wex}{Worked cubic: solve $x^3-3x-1=0$}
Apply the formula to $p=-3,q=-1$ and identify the splitting field's Galois group.
\wrec Cardano with $p=-3,q=-1$; the sign and shape of $\disc(f)$ decides whether the group is $C_3$ or $S_3$.
\wsol Here $\tfrac{q^2}4+\tfrac{p^3}{27}=\tfrac14+\tfrac{-27}{27}=\tfrac14-1=-\tfrac34$, so the inner square root is $\sqrt{-3/4}=\tfrac{\sqrt{-3}}2$. Then $(r_1/3)^3=-\tfrac q2+\tfrac{\sqrt{-3}}2=\tfrac12+\tfrac{\sqrt{-3}}2=e^{i\pi/3}$, a primitive $6$th root of unity; its cube root $e^{i\pi/9}$ and the cube root $e^{-i\pi/9}$ of $\tfrac12-\tfrac{\sqrt{-3}}2$ have product $1=-p/3$, so the formula gives the real root $\alpha_1=e^{i\pi/9}+e^{-i\pi/9}=2\cos(\pi/9)$, numerically $\approx1.879$. The discriminant is $\disc(f)=-4(-3)^3-27(-1)^2=108-27=81=9^2$, a perfect square, so $\Gal(f/\mathbb{Q})\cong A_3=C_3$ and $\mathbb{Q}(\alpha_1)/\mathbb{Q}$ is already the (cyclic, degree $3$) splitting field. Sanity check: $f$ is irreducible over $\mathbb{Q}$ (a rational root would be $\pm1$, but $f(1)=-3\neq0$ and $f(-1)=1\neq0$), so the group is transitive of order divisible by $3$; with square discriminant it lies in $A_3$, forcing exactly $C_3$ -- consistent with all three roots being real, $2\cos(\pi/9),2\cos(7\pi/9),2\cos(13\pi/9)$.
\end{wex}

\begin{proposition}[{closure properties of solvable groups}]
Subgroups and quotients of solvable groups are solvable; and if $N\nor G$ with $N$ and $G/N$ both solvable, then $G$ is solvable. Consequently a finite group is solvable iff its composition factors are all cyclic of prime order.
\end{proposition}

\begin{proof}[Idea]
Intersect a solvable series of $G$ with a subgroup $H$ (giving a series of $H$ with quotients embedding into the abelian $G_{i+1}/G_i$); push it forward along $G\twoheadrightarrow G/N$ (quotients are images of abelian groups). For the extension statement, splice a solvable series of $N$ onto the pullback of a solvable series of $G/N$. The composition-factor characterization follows because abelian-by-abelian-by-$\cdots$ refines to prime-cyclic factors.
\end{proof}

\begin{theorem}[{Galois's solvability criterion}]
Let $F$ have characteristic $0$ and let $f(x)\in F[x]$ with splitting field $K$. Then $f$ is solvable by radicals if and only if the Galois group $\Gal(K/F)$ is a solvable group.
\end{theorem}

\begin{wex}{Every quartic is solvable by radicals}
Explain why $\Gal(f/\mathbb{Q})\subseteq S_4$ is always solvable, so every degree $\le4$ polynomial has a radical formula.
\wrec Galois's criterion reduces ``radical formula exists'' to ``the group is solvable''; for $n\le4$ the group sits in $S_n$, and $S_2,S_3,S_4$ are all solvable.
\wsol $S_4$ has the subnormal series $1\pnor V_4\pnor A_4\pnor S_4$ with quotients $V_4\cong\mathbb{Z}/(2)\mathbb{Z}\times\mathbb{Z}/(2)\mathbb{Z}$, $A_4/V_4\cong\mathbb{Z}/(3)\mathbb{Z}$, $S_4/A_4\cong\mathbb{Z}/(2)\mathbb{Z}$ -- all abelian. So $S_4$ is solvable, and every subgroup (every possible quartic Galois group: $1,\mathbb{Z}/(2)\mathbb{Z},\mathbb{Z}/(3)\mathbb{Z},\mathbb{Z}/(4)\mathbb{Z},V_4,S_3,D_8,A_4,S_4$) is solvable by the closure proposition. By Galois's criterion every quartic is solvable by radicals. Sanity check: the Klein four-group $V_4$ inside $A_4$ is exactly the kernel of the action giving the ``resolvent cubic,'' the classical device for solving quartics -- the group series mirrors the algebraic reduction quartic $\to$ cubic $\to$ quadratics.
\end{wex}

\begin{theorem}[{$A_n$ simple, $S_n$ insolvable for $n\ge5$}]
For $n\ge5$ the alternating group $A_n$ is simple and nonabelian. Consequently $S_n$ is not solvable for $n\ge5$.
\end{theorem}

\begin{proof}[Idea]
Simplicity of $A_n$ ($n\ge5$) is proved by showing $A_n$ is generated by $3$-cycles and that any nontrivial normal subgroup must contain a $3$-cycle, hence all of them. A nonabelian simple group cannot be solvable: its only normal subgroups are $1$ and itself, so its only possible subnormal series is $1\pnor A_n$, whose quotient $A_n$ is nonabelian. Since $A_n\nor S_n$ is non-solvable, the subgroup-closure of solvability forces $S_n$ non-solvable.
\end{proof}

\begin{method}{Proving a specific quintic $f\in\mathbb{Q}[x]$ is not solvable by radicals.}
The goal is to show $\Gal(f/\mathbb{Q})=S_5$ (which is non-solvable), via three checks:
\begin{enumerate}[label=\textup{(\arabic*)},leftmargin=*]
\item \textbf{Irreducible.} Show $f$ is irreducible over $\mathbb{Q}$ (e.g.\ Eisenstein, or reduction mod a prime). Then the group acts \emph{transitively} on the $5$ roots, so $5\mid\abs{\Gal(f)}$; by Cauchy the group contains an element of order $5$, i.e.\ a \emph{$5$-cycle}.
\item \textbf{Exactly two non-real roots.} Use calculus (count real roots via sign changes / critical points) to show $f$ has exactly $3$ real and $2$ complex roots. Complex conjugation is then an element of $\Gal(f)$ fixing the $3$ real roots and swapping the conjugate pair: a \emph{transposition}.
\item \textbf{Generate $S_5$.} A $5$-cycle and a transposition in $S_5$ generate all of $S_5$ (when the prime $p=5$ and a transposition are both present, this always holds). Hence $\Gal(f)=S_5$, which is not solvable, so $f$ is not solvable by radicals.
\end{enumerate}
\end{method}

\begin{pitfall}
Step (3) needs $p=\deg f$ prime. A $p$-cycle plus a transposition generate $S_p$ because some power of the $p$-cycle (again a $p$-cycle, since $p$ is prime) carries one point of the transposition to the other; for composite $n$ an $n$-cycle and a transposition need not generate $S_n$ ($(1\,2\,3\,4)$ and $(1\,3)$ generate only $D_8\le S_4$), and a transposition together with a $4$-cycle in $S_5$, say, need not generate $S_5$. Also, ``two non-real roots'' must be exactly two: if there were $4$ non-real roots, complex conjugation would be a product of two transpositions (an even permutation in $A_5$), and the argument collapses.
\end{pitfall}

The subgroup $\mathbb{Z}/(5)\mathbb{Z} \le F_{20}$ in the left lattice is the group of automorphisms moving $\sqrt[5]{2}$ (it fixes $\zeta_5$), so it corresponds to $\mathbb{Q}(\zeta_5)$ (the field where $\sqrt[5]{2}$ is \emph{not} yet present). The factor $(\mathbb{Z}/(5)\mathbb{Z})^{\times} \cong \mathbb{Z}/(4)\mathbb{Z}$ describes automorphisms of $\zeta_5$ and is the Galois group of the $\mathbb{Q}(\zeta_5)/\mathbb{Q}$ step, not the $K/\mathbb{Q}(\zeta_5)$ step.
\dgi{Takeaway:} The point of this diagram is that the solvable series $1 \pnor \mathbb{Z}/(5)\mathbb{Z} \pnor F_{20}$ is precisely the group-theoretic shadow of the radical tower $\mathbb{Q} \subset \mathbb{Q}(\zeta_5) \subset K$, showing that Galois's criterion is not abstract -- it directly names the field steps that produce the radical solution.
\end{dgx}
The normal subgroup $\mathbb{Z}/(5)\mathbb{Z}\nor F_{20}$ corresponds to the subfield $\mathbb{Q}(\zeta_5)$, which is Galois over $\mathbb{Q}$ with group $F_{20}/\mathbb{Z}/(5)\mathbb{Z}\cong\mathbb{Z}/(4)\mathbb{Z}$.
\end{wex}

\begin{wex}{$x^5-4x+2$ is not solvable by radicals}
Confirm $f(x)=x^5-4x+2$ has Galois group $S_5$.
\wrec Same method: Eisenstein at $2$ for irreducibility, then count real roots via $f'$.
\wsol $f$ is Eisenstein at $2$, hence irreducible, giving a $5$-cycle. $f'(x)=5x^4-4$ has real critical points $x=\pm(4/5)^{1/4}\approx\pm0.946$. Values: $f(-2)=-32+8+2=-22<0$, $f(-1)=-1+4+2=5>0$, $f(1)=1-4+2=-1<0$, $f(2)=32-8+2=26>0$, so $f$ changes sign on $(-2,-1)$, on $(-1,1)$ and on $(1,2)$; since $f'$ has only two real zeros, $f$ has a local max near $x\approx-0.946$ (positive) and local min near $x\approx0.946$ (negative), giving exactly $3$ real roots and $2$ complex ones. Complex conjugation is a transposition; with the $5$-cycle it generates $S_5$. Sanity check: the pattern of signs $f(-2)<0<f(-1)$, $f(-1)>0>f(1)$, $f(1)<0<f(2)$ gives three sign changes hence three real roots, leaving exactly two non-real -- the transposition criterion is met, so $\Gal(f)=S_5$ and $f$ is not solvable by radicals.
\end{wex}

\begin{wex}{Insolvability is not just ``degree $5$'': a solvable vs.\ insolvable contrast}
Contrast $x^5-2$ (solvable, group $F_{20}$) with $x^5-6x+3$ (insolvable, group $S_5$) and locate the dividing line.
\wrec Both quintics are irreducible, so both groups are transitive subgroups of $S_5$ containing a $5$-cycle; the difference is whether a transposition is present (forcing $S_5$) or not.
\wsol For $x^5-2$ all that enters is one $5$-cycle plus the $\mathbb{Z}/(4)\mathbb{Z}$ acting on $\zeta_5$; the group $F_{20}$ has no transposition and is solvable, so the equation has a radical solution $\sqrt[5]2,\zeta_5\sqrt[5]2,\dots$. For $x^5-6x+3$, the extra structure ``exactly two non-real roots'' injects a transposition, and $\langle 5\text{-cycle},\text{transposition}\rangle=S_5$ is non-solvable, killing any radical formula. So degree $5$ alone is not the obstruction; the obstruction is the appearance of the simple group $A_5$ as a composition factor. Sanity check: up to conjugacy the transitive subgroups of $S_5$ are $\mathbb{Z}/(5)\mathbb{Z}\subset D_{10}\subset F_{20}$ (a chain of orders $5\mid10\mid20$) together with $A_5\subset S_5$ (orders $60\mid120$); note $F_{20}$ and $A_5$ are incomparable, since $F_{20}$ contains a $4$-cycle (an odd permutation) and so is \emph{not} inside $A_5$. The first three are solvable and the last two are not (both contain $A_5$), so an irreducible quintic is solvable by radicals iff its group lies in $F_{20}$ -- exactly the criterion of the text's exercises.
\end{wex}

\begin{wex}{Why no general quintic formula can exist}
Deduce that there is no formula in radicals for the roots of the ``generic'' quintic.
\wrec The generic polynomial $x^5-t_1x^4+\cdots\pm t_5$ over the field $\mathbb{Q}(t_1,\dots,t_5)$ of its coefficients has Galois group exactly $S_5$; insolvability of $S_5$ then applies.
\wsol Over $F=\mathbb{Q}(t_1,\dots,t_5)$ with the $t_i$ the elementary symmetric functions of independent transcendentals $x_1,\dots,x_5$, the splitting field is $\mathbb{Q}(x_1,\dots,x_5)$ and $\Gal=S_5$ (it permutes the $x_i$ and fixes the symmetric functions $t_i$). Since $S_5$ is not solvable, Galois's criterion says the generic quintic is not solvable by radicals: there is no universal radical formula in the coefficients. The explicit $x^5-6x+3$ shows this already fails over $\mathbb{Q}$, not merely generically. Sanity check: the same argument gives $\Gal=S_n$ for the generic degree-$n$ polynomial, solvable iff $n\le4$ -- recovering the classical existence of quadratic/cubic/quartic formulas and the nonexistence for all $n\ge5$.
\end{wex}

\begin{proof}[Idea]
Each prime $\mathfrak p$ of the splitting-field ring lying over $p$ has a Frobenius automorphism $\Frob_{\mathfrak p}\in G$, characterized by $\Frob_{\mathfrak p}(x)\equiv x^p\pmod{\mathfrak p}$. Because $p$ is unramified, reduction mod $\mathfrak p$ is a bijection between the roots of $f$ in characteristic $0$ and the roots of $\overline f$ in $\overline{\F_p}$. Frobenius acts on the latter as $\alpha\mapsto\alpha^p$, and on the roots of a single irreducible factor $\overline{g_i}$ of degree $d_i$ it acts as a single $d_i$-cycle (the roots of an irreducible over $\F_p$ form one Frobenius orbit, of size equal to the degree). Pulling this back through the bijection, $\Frob_{\mathfrak p}$ is an element of $G$ with cycle type $(d_1,\dots,d_k)$.
\end{proof}

\begin{remark}
Dedekind's theorem only ever produces \emph{lower} bounds: each prime hands us one cycle type known to occur in $G$. It never certifies that a cycle type is \emph{absent}. So the method is to collect cycle types from several primes and ask which transitive subgroup of $S_n$ is forced to contain all of them. The discriminant test and resolvents supply the complementary upper bounds.
\end{remark}

\begin{wex}{A 4-cycle and a transposition from two primes}
For $f(x)=x^4-x-1$, find primes exhibiting a $4$-cycle and a transposition in $\Gal(f/\mathbb{Q})$.
\wrec By Dedekind's theorem an irreducible reduction $\overline f$ of degree $4$ gives a $4$-cycle, and a factorization of type $2+1+1$ gives a transposition; we just factor mod small primes.
\wsol Mod $2$: $x^4-x-1\equiv x^4+x+1$, which is irreducible over $\F_2$ (no root since $0,1$ both give $1$; and the only way a rootless quartic could factor is as a product of two irreducible quadratics, but the unique irreducible quadratic over $\F_2$ is $x^2+x+1$, whose square $(x^2+x+1)^2=x^4+x^2+1\neq x^4+x+1$). Hence $\overline f$ is irreducible mod $2$, giving both transitivity (so $f$ is irreducible over $\mathbb{Q}$) and a $\mathbf 4$\textbf{-cycle}. So $G$ is a transitive subgroup of $S_4$ containing a $4$-cycle: $G\in\{C_4,D_8,S_4\}$. The discriminant is $\disc(f)=-283$, which is negative and hence not a perfect square, so $G\not\subseteq A_4$ (this is automatic here, since a $4$-cycle is already odd). Mod $17$: $x^4-x-1$ factors as a product of two linear factors and one irreducible quadratic (cycle type $2+1+1$), giving a \textbf{transposition} in $G$. This alone does not force $S_4$: $D_8$ also contains transpositions (e.g.\ $\langle (1\,2\,3\,4),(1\,3)\rangle=D_8$). Mod $7$: $\overline f=(x+4)(x^3+3x^2+2x+5)$ with the cubic irreducible (cycle type $3+1$), giving a \textbf{$3$-cycle}; then $3\mid\abs G$, which rules out $C_4$ and $D_8$, so $G=S_4$. Sanity check: $-283<0$ is certainly not a square, consistent with the odd $4$-cycle (and the transposition) lying in $G$; and $\abs G$ is divisible by $4$ and by $3$ while $G$ contains odd permutations, so $G\neq A_4$ and $\abs G=24$.
\end{wex}

\begin{proposition}[{transitivity from irreducibility}]
$f\in\mathbb{Q}[x]$ is irreducible if and only if $G=\Gal(f/\mathbb{Q})$ acts transitively on the roots. In particular an irreducible $f$ of degree $n$ has $n\mid\abs{G}$.
\end{proposition}

\begin{proof}[Idea]
$G$ is transitive iff there is a single orbit of roots iff the roots form one irreducible factor's worth, i.e.\ $f$ is irreducible over $\mathbb{Q}$. The orbit-stabilizer count gives $n=[G:G_{\alpha}]\mid\abs{G}$.
\end{proof}

\begin{theorem}[{the discriminant test}]
Let $f\in\mathbb{Q}[x]$ be separable of degree $n$ with roots $\alpha_i$ and $\disc(f)=\prod_{i<j}(\alpha_i-\alpha_j)^2$. Then $\sqrt{\disc(f)}\in\mathbb{Q}$ if and only if $G\subseteq A_n$. Equivalently, for monic $f\in\mathbb{Z}[x]$ with squarefree-checked discriminant, $G\subseteq A_n\iff\disc(f)$ is a perfect square in $\mathbb{Q}$.
\end{theorem}

\begin{proof}[Idea]
The element $\delta=\prod_{i<j}(\alpha_i-\alpha_j)$ satisfies $\delta^2=\disc(f)\in\mathbb{Q}$, and any $\sigma\in G$ sends $\delta\mapsto\operatorname{sgn}(\sigma)\,\delta$. Thus $\delta$ is fixed by all of $G$ (hence $\delta\in\mathbb{Q}$ and $\disc f$ is a square) exactly when every $\sigma\in G$ is even, i.e.\ $G\subseteq A_n$.
\end{proof}

\begin{pitfall}
Reduction mod $p$ never \emph{proves} a cycle type is missing from $G$, so you cannot conclude $G\neq S_n$ just because you have not seen a transposition. Likewise a square discriminant only says $G\subseteq A_n$; it does not by itself distinguish, say, $V_4$ from $A_4$ inside $S_4$, nor $A_n$ from a proper transitive subgroup of $A_n$. Always pair cycle-type evidence with the discriminant and, when needed, a resolvent.
\end{pitfall}

\begin{wex}{Discriminant forces $S_3$ vs.\ $A_3$ for a cubic}
Show $f(x)=x^3-x-1$ has Galois group $S_3$.
\wrec For an irreducible cubic, $G$ is transitive in $S_3$, so $G\in\{A_3,S_3\}$; the discriminant test decides which, since $\disc=-4a^3-27b^2$ for $x^3+ax+b$.
\wsol $f$ is irreducible over $\mathbb{Q}$ (no rational root: $\pm1$ give $-1,-1$). Here $a=-1,b=-1$, so $\disc(f)=-4(-1)^3-27(-1)^2=4-27=-23$. Since $-23$ is negative it is not a perfect square in $\mathbb{Q}$, so $G\not\subseteq A_3$, forcing $G=S_3$. Sanity check: mod $2$, $\overline f=x^3+x+1$ is irreducible, giving a $3$-cycle; mod $5$, $f(2)=8-2-1=5\equiv0$, so $x\equiv2$ is a root and $\overline f=(x-2)(x^2+2x-2)$ splits as (linear)(irreducible quadratic), a transposition. A $3$-cycle and a transposition generate $S_3$, confirming $G=S_3$.
\end{wex}

\begin{wex}{An $S_4$ quartic via discriminant and a 4-cycle}
Prove $f(x)=x^4+x+1$ has Galois group $S_4$.
\wrec Irreducible quartic gives transitive $G\sgr S_4$; a non-square discriminant rules out $A_4$ and $V_4$ (the transitive subgroups inside $A_4$), and a mod-$p$ $4$-cycle plus a $3$-cycle pin $S_4$.
\wsol Irreducibility over $\mathbb{Q}$: no rational roots ($\pm1$ give $3,1$), and $x^4+x+1$ is not a product of two rational quadratics (matching coefficients $x^4+x+1=(x^2+bx+c)(x^2-bx+d)$ forces $c+d-b^2=0,\ b(d-c)=1,\ cd=1$, which has no rational solution). So $G$ is transitive in $S_4$. Discriminant of $x^4+px+q$ is $-27p^4+256q^3$; with $p=q=1$ this is $-27+256=229$, which is prime, hence not a perfect square: $G\not\subseteq A_4$. Mod $2$: $x^4+x+1$ is irreducible over $\F_2$, giving a $4$-cycle. The transitive subgroups of $S_4$ are $C_4,V_4,D_8,A_4,S_4$; those containing a $4$-cycle are $C_4,D_8,S_4$. Of these, only $S_4$ contains an element of order $3$ ($\abs{C_4}=4$ and $\abs{D_8}=8$ are not divisible by $3$), so a $3$-cycle will pin down $S_4$. Mod $5$: testing residues, $f(0)=1,f(1)=3,f(2)=16+2+1=19\equiv4,f(3)=81+3+1=85\equiv0$, so $x\equiv3$ is a root mod $5$ and $\overline f=(x-3)\cdot(\text{cubic})$; that cubic is irreducible mod $5$ (it has no root among the remaining residues), giving cycle type $3+1$, a $3$-cycle. A $4$-cycle and a $3$-cycle generate $S_4$, so $G=S_4$. Sanity check: $\abs{S_4}=24$ is divisible by $4$ (transitivity) and by $3$ (the $3$-cycle); and $229$ not a square is consistent with the odd permutation (the $4$-cycle) lying in $G$.
\end{wex}

\begin{proof}[Idea]
The roots $\beta_i$ of $g$ are fixed exactly by $V_4=\{e,(12)(34),(13)(24),(14)(23)\}\nor S_4$, so $\Gal(g/\mathbb{Q})\cong G/(G\cap V_4)\sgr S_4/V_4\cong S_3$. The number of rational $\beta_i$ records how many of the three $V_4$-cosets $G$ collapses: all three rational $\iff G\sgr V_4$; exactly one rational $\iff$ $G$ stabilizes one pairing, i.e.\ $G\sgr C_4$ or $D_8$; none rational ($g$ irreducible) $\iff$ the image of $G$ in $S_3$ is transitive ($A_3$ or $S_3$), forcing $G\in\{A_4,S_4\}$, which the discriminant then separates.
\end{proof}

\begin{wex}{A $V_4$ quartic: square discriminant, split resolvent}
Determine $\Gal(f/\mathbb{Q})$ for $f(x)=x^4+1$.
\wrec Irreducible quartic; compute $\disc$ and the resolvent cubic. A completely split resolvent signals $V_4$.
\wsol $x^4+1=\Phi_8(x)$ is irreducible over $\mathbb{Q}$ (the $8$th cyclotomic polynomial). It is already depressed with $p=0,q=0,r=1$. Resolvent: $g(x)=x^3-0\cdot x^2-4x+0=x^3-4x=x(x-2)(x+2)$, which splits completely over $\mathbb{Q}$. By the theorem $G\cong V_4$. Sanity check: $\mathbb{Q}(\zeta_8)$ has degree $\varphi(8)=4$ over $\mathbb{Q}$ with abelian Galois group $(\mathbb{Z}/(8)\mathbb{Z})^{\times}\cong\mathbb{Z}/2\times\mathbb{Z}/2\cong V_4$, matching exactly; and $\disc(x^4+1)=256=16^2$ is a perfect square, consistent with $V_4\subseteq A_4$.
\end{wex}

\begin{wex}{$A_4$ vs.\ $V_4$ when the discriminant is a square}
Show $f(x)=x^4+8x+12$ has Galois group $A_4$.
\wrec Square discriminant puts $G\sgr A_4$, so $G\in\{V_4,A_4\}$; the resolvent cubic being irreducible (not split) selects $A_4$.
\wsol $f$ is irreducible over $\mathbb{Q}$ (no rational roots by the rational-root test on divisors of $12$, and no rational quadratic factorization). It is depressed: $p=0,q=8,r=12$. Discriminant of $x^4+qx+r$ is $-27q^4+256r^3=-27\cdot4096+256\cdot1728=-110592+442368=331776=576^2$, a perfect square, so $G\sgr A_4$. Resolvent cubic: $g(x)=x^3-0\cdot x^2-4(12)x+(0-64)=x^3-48x-64$. This is irreducible over $\mathbb{Q}$: a rational root would be an integer dividing $64$; for $\abs x\ge16$ we have $\abs{x^3-48x}=\abs x\,(x^2-48)>64$, and testing $\pm1,\pm2,\pm4,\pm8$ gives no zero (e.g.\ $g(8)=512-384-64=64\neq0$, $g(-4)=-64+192-64=64\neq0$). Since $g$ is irreducible and $D$ is a square, $G\cong A_4$. Sanity check: $\sqrt D=576\in\mathbb{Q}$ matches $G\subseteq A_4$; an irreducible resolvent means $\Gal(g/\mathbb{Q})=S_3$ or $A_3=C_3$, and $\disc(g)=\disc(f)$ is a square so $\Gal(g/\mathbb{Q})=C_3$, hence $G/(G\cap V_4)\cong C_3$, giving $\abs G=12$, i.e.\ $A_4$.
\end{wex}

\begin{wex}{$C_4$ vs.\ $D_8$: one rational resolvent root}
Identify $\Gal(f/\mathbb{Q})$ for $f(x)=x^4+5x^2+5$.
\wrec One rational resolvent root signals $C_4$ or $D_8$; the tiebreak is whether $f$ stays irreducible over $\mathbb{Q}(\sqrt D)$.
\wsol By the rational root test and Eisenstein at $5$, $f=x^4+5x^2+5$ is irreducible over $\mathbb{Q}$. Depressed with $p=5,q=0,r=5$. Resolvent: $g(x)=x^3-5x^2-20x+(4\cdot25-0)=x^3-5x^2-20x+100=(x-5)(x^2-20)$. So $g$ has exactly one rational root $x=5$ (since $x^2-20$ is irreducible over $\mathbb{Q}$), placing $G\in\{C_4,D_8\}$. Discriminant: $f$ is biquadratic, $x^2=\tfrac{-5\pm\sqrt5}{2}$, so the splitting field is $\mathbb{Q}\bigl(\sqrt{\tfrac{-5+\sqrt5}{2}}\bigr)$, which contains $\sqrt5$; one computes $D=\disc(f)=2000=400\cdot5$, so $\sqrt D=20\sqrt5$ and $\mathbb{Q}(\sqrt D)=\mathbb{Q}(\sqrt5)$. Over $\mathbb{Q}(\sqrt5)$ the quartic factors as $\bigl(x^2-\tfrac{-5+\sqrt5}{2}\bigr)\bigl(x^2-\tfrac{-5-\sqrt5}{2}\bigr)$, i.e.\ $f$ becomes reducible, so $G\cong C_4$. Sanity check: a biquadratic $x^4+px^2+r$ with $\sqrt r=\sqrt5$ irrational but $\sqrt{p^2-4r}=\sqrt{25-20}=\sqrt5$ relating the two radicals is the classic $C_4$ pattern (Galois group cyclic of order $4$), and indeed $\abs{\mathbb{Q}(\zeta):\mathbb{Q}}$-type cyclic structure gives $\abs G=4$ with a single $4$-cycle generator.
\end{wex}

\begin{wex}{Reading the resolvent backwards}
Given that an irreducible quartic $f$ has resolvent cubic $g$ with $\disc(g)$ a non-square and $g$ irreducible, name $G$.
\wrec $g$ irreducible means $\Gal(g/\mathbb{Q})$ is transitive in $S_3$; a non-square $\disc(g)=\disc(f)$ means $G\not\subseteq A_4$.
\wsol Irreducible $g$ with non-square discriminant has $\Gal(g/\mathbb{Q})=S_3$, so $G/(G\cap V_4)\cong S_3$ has order $6$; since $G$ is transitive, $4\mid\abs G=6\,\abs{G\cap V_4}$, so $12\mid\abs G$; and $G\neq A_4$, because the image of $A_4$ in $S_4/V_4\cong S_3$ is only $A_3$. Hence $\abs G=24$, giving $G\cong S_4$. Sanity check: this is exactly the first row of the table ($g$ irreducible, $D$ not a square $\Rightarrow S_4$), and $\abs{S_4}=24=6\cdot4$ matches $\abs{S_3}\cdot\abs{V_4}$.
\end{wex}

\begin{remark}
The canonical pair Dedekind cannot tell apart in $S_5$ is the cyclic $C_5$, the dihedral $D_{10}$, the Frobenius group $F_{20}$, and $A_5,S_5$: the transitive subgroups of $S_5$ are exactly $C_5\psgr D_{10}\psgr F_{20}\psgr S_5$ together with $A_5$. Each of $C_5,D_{10},F_{20}$ contains $5$-cycles, and cycle types alone (constrained also by the discriminant, which is a square iff $G\sgr A_5$) leave genuine ambiguity. A degree-$6$ \emph{sextic resolvent} is built from a polynomial expression $\theta$ in the roots whose stabilizer in $S_5$ is exactly $F_{20}$ (order $20$, index $6$), so that $S_5$ permutes the six conjugates of $\theta$ through $S_5/F_{20}$; this resolvent has a rational root precisely when $G$ fixes one of the six cosets, i.e.\ when $G$ is conjugate into $F_{20}$, separating the solvable groups $C_5,D_{10},F_{20}$ from $A_5,S_5$.
\end{remark}

\begin{method}{The low-degree playbook.}
\textup{Cubics ($n=3$):} irreducible $\Rightarrow G\in\{A_3,S_3\}$; $\disc$ a square $\iff A_3=C_3$, else $S_3$.
\textup{Quartics ($n=4$):} transitive subgroups $C_4,V_4,D_8,A_4,S_4$; use the resolvent cubic table above.
\textup{Quintics ($n=5$):} transitive subgroups $C_5,D_{10},F_{20},A_5,S_5$. First, $\disc$ a square $\iff G\sgr A_5$, separating $\{C_5,D_{10},A_5\}$ (square) from $\{F_{20},S_5\}$ (non-square). Then a transposition (cycle type $2+1+1+1$) or a single $2$-cycle from Dedekind forces $G=S_5$; a $5$-cycle is automatic from transitivity; an element of cycle type $2+2+1$ lies in $A_5$ and (with the discriminant) helps separate $C_5,D_{10},A_5$. The sextic resolvent separates the solvable trio $\{C_5,D_{10},F_{20}\}$ (rational root) from $\{A_5,S_5\}$ (no rational root).
\end{method}

\begin{wex}{$x^5-x-1$ has Galois group $S_5$}
Prove the irreducible quintic $f(x)=x^5-x-1$ has $\Gal(f/\mathbb{Q})=S_5$.
\wrec Irreducible quintic is transitive in $S_5$; by the playbook, exhibiting a $5$-cycle, an element of order $6$ (type $2+3$), and a transposition forces $S_5$, since $S_5$ is the only transitive subgroup of $S_5$ containing a transposition.
\wsol Irreducibility over $\mathbb{Q}$: mod $3$, $f(x)=x^5-x-1\equiv x^5+2x+2$. Testing $0,1,2$: $f(0)=2,f(1)=1+2+2=5\equiv2,f(2)=32-2-1=29\equiv2\pmod3$, no linear factor; one checks it has no quadratic factor either, so $\overline f$ is irreducible over $\F_3$ (a known irreducible quintic mod $3$). Hence $f$ is irreducible over $\mathbb{Q}$ and $\overline f$ irreducible mod $3$ gives a $\mathbf{5}$\textbf{-cycle}. Mod $2$: $x^5-x-1\equiv x^5+x+1=(x^2+x+1)(x^3+x^2+1)$ over $\F_2$ (both factors irreducible: the quadratic is the unique irreducible one, and the cubic has no root in $\F_2$). This gives cycle type $\mathbf{2+3}$, an element of order $\lcm(2,3)=6$. Its cube, $((2\text{-cycle})(3\text{-cycle}))^3$, equals the $2$-cycle (the $3$-cycle cubes to identity), so $G$ contains a \textbf{transposition}. The only transitive subgroup of $S_5$ that contains a transposition is $S_5$ itself (a transitive subgroup generated by transpositions and acting transitively is all of $S_5$; more directly, a transposition together with a $5$-cycle generates $S_5$). Hence $G=S_5$. Sanity check: $\disc(x^5-x-1)=2869=19\cdot151$, which is not a perfect square, so $G\not\subseteq A_5$, fully consistent with the odd transposition lying in $G$; and a $5$-cycle plus a transposition is the textbook generating set for $S_5$.
\end{wex}

\begin{wex}{$x^5+20x+16$ lands in $A_5$}
Show $f(x)=x^5+20x+16$ has Galois group $A_5$ (not $S_5$).
\wrec Square discriminant forces $G\sgr A_5$; combined with transitivity (a $5$-cycle) and a $3$-cycle (an even element of order $3$), which rules out the solvable groups $C_5,D_{10}$, we get $G=A_5$.
\wsol $f$ is irreducible over $\mathbb{Q}$ (Eisenstein fails at $2$ since $4\mid16$; instead reduce mod $3$: $x^5+20x+16\equiv x^5+2x+1$, irreducible over $\F_3$, so $f$ is irreducible over $\mathbb{Q}$). The mod-$3$ irreducibility gives a $\mathbf 5$\textbf{-cycle}. Discriminant: for $x^5+ax+b$, $\disc=4^4a^5+5^5b^4=256a^5+3125b^4$; with $a=20,b=16$ this is $256\cdot20^5+3125\cdot16^4$. Now $20^5=3.2\times10^6=3200000$, so $256\cdot3200000=819200000$; and $16^4=65536$, so $3125\cdot65536=204800000$; sum $=1024000000=32000^2$, a perfect square. So $G\sgr A_5$, i.e.\ $G\in\{C_5,D_{10},A_5\}$. Mod $7$: $x^5+20x+16\equiv(x+2)(x+3)(x^3+2x^2-2x-2)$ over $\F_7$, cycle type $\mathbf{3+1+1}$, a $3$-cycle (an even permutation), forcing $3\mid\abs G$. Since $3\nmid\abs{C_5}=5$ and $3\nmid\abs{D_{10}}=10$, neither $C_5$ nor $D_{10}$ can contain a $3$-cycle, so the only remaining even transitive group is $A_5$ ($\abs{A_5}=60$). Hence $G=A_5$. Sanity check: $1024000000=(32000)^2$ is a clean square, matching $G\subseteq A_5$; and $\abs{A_5}=60$ is divisible by $5$ (transitivity) and by $3$ (the $3$-cycle), exactly the primes our cycle types demanded, while $\abs{C_5}=5,\abs{D_{10}}=10$ both fail the divisibility-by-$3$ test. (One can also confirm an even $2+2+1$ element appears, e.g.\ mod $23$, consistent with $G\subseteq A_5$.)
\end{wex}

\begin{wex}{Two primes already forcing $S_n$}
Explain why for $f(x)=x^6+24x-20$ a transposition plus a reduction of type $5+1$ would force $S_6$, and contrast with the actual answer $A_6$.
\wrec If Dedekind ever delivers a transposition and (via another prime) a $p$-cycle on $n-1$ or all $n$ points appropriately, transitivity plus a transposition can force $S_n$; a square discriminant blocks any transposition, redirecting to $A_n$.
\wsol For a transitive $G\sgr S_n$, possessing a transposition and an $(n-1)$-cycle (with the fixed point disjoint) generates $S_n$; even just a transposition together with an $n$-cycle when $n$ is prime generates $S_n$. So, once $f$ is known to be irreducible, two well-chosen primes -- one giving cycle type $(n-1)+1$ (an $(n-1)$-cycle; when $n$ is prime an irreducible $\overline f$, i.e.\ an $n$-cycle, also works) and one giving cycle type $2+1+\cdots+1$ (a transposition) -- already force $G=S_n$. (For composite $n$ an $n$-cycle does not suffice: $\langle (1\,2\,3\,4\,5\,6),(1\,4)\rangle$ is transitive of order only $24$.) For $f=x^6+24x-20$, however, $\disc(f)$ turns out to be a perfect square, so $G\subseteq A_6$ and \emph{no} prime can ever produce a transposition (a single $2$-cycle is odd). Thus the transposition route is unavailable; instead one collects even cycle types (e.g.\ a $5$-cycle from an irreducible-quintic-times-linear reduction, type $5+1$, which is even; and a $3$-cycle, type $3+1+1+1$) and shows the only transitive even subgroup of $S_6$ generated by them is $A_6$. Sanity check: $5+1$ and $3+1+1+1$ are both even permutations (a $5$-cycle and a $3$-cycle), consistent with $G\subseteq A_6$; and a $5$-cycle together with a $3$-cycle inside a transitive group on $6$ points generates a large group, with $A_6$ the smallest containing both while respecting the square-discriminant constraint.
\end{wex}

\begin{wex}{Subfields forced by the $A_4$ identification}
For an irreducible quartic with $G\cong A_4$, list the degrees of the intermediate fields and the unique proper subfield that is normal over $\mathbb{Q}$ of small degree.
\wrec Intermediate fields correspond to subgroups of $A_4$; degrees over $\mathbb{Q}$ equal indices $[A_4:H]$. The only normal subgroup giving a small abelian quotient is $V_4\nor A_4$.
\wsol $\abs{A_4}=12$, so $[K:\mathbb{Q}]=12$. Subgroups of $A_4$: the trivial group, three subgroups of order $2$ (each $\langle (ab)(cd)\rangle$), one $V_4$ of order $4$, four $C_3$'s of order $3$, and $A_4$. The corresponding subfield degrees $[\,\cdot:\mathbb{Q}]=[A_4:H]$ are $12$ (top $K$), $6$ (from the order-$2$ subgroups), $3$ (from $V_4$), $4$ (from the $C_3$'s), and $1$ (base). The normal subgroup $V_4\nor A_4$ has quotient $A_4/V_4\cong C_3$, so $\Fix(V_4)$ is a \emph{cyclic} cubic field normal over $\mathbb{Q}$ -- the splitting field of the (irreducible, square-discriminant) resolvent cubic. Sanity check: $A_4$ has no subgroup of order $6$ (a classical fact), so there is \emph{no} intermediate field of degree $2$ over $\mathbb{Q}$; consistent with the resolvent test for $A_4$ requiring $g$ irreducible (no rational/quadratic resolvent root), hence no quadratic subfield other than $\mathbb{Q}$ itself -- indeed $\disc$ being a square means $\mathbb{Q}(\sqrt D)=\mathbb{Q}$.
\end{wex}

\begin{wex}{Residue degrees as cycle lengths}
With $f=x^4+x+1$ ($G=S_4$) and $p=5$, interpret the factorization $\overline f=(x-3)(\text{irreducible cubic})$ in terms of primes of $K$ above $5$.
\wrec The degrees of the irreducible factors of $\overline f$ over $\F_p$ are the residue degrees $f(\mathfrak p\mid p)$ of the primes $\mathfrak p$ of (the ring of integers of) the root field $\mathbb{Q}(\alpha)$ lying over $p$, and they form the cycle type of a Frobenius element; every prime of $K$ over $p$ has residue degree equal to the order of that Frobenius.
\wsol Mod $5$, $\overline f=(x-3)(x^3+\cdots)$ has factor degrees $1$ and $3$, so the Frobenius at $5$ has cycle type $(1,3)$ -- a $3$-cycle fixing one root. Correspondingly, in the field $\mathbb{Q}(\alpha)=\mathbb{Q}[x]/(f)$ the prime $5$ splits as $\mathfrak p_1\mathfrak p_2$ with residue degrees $1$ and $3$ (and ramification $1$, since $5\nmid\disc f=229$). In the full splitting field $K$ the prime $5$ is unramified with Frobenius conjugacy class equal to that of a $(1,3)$-element of $S_4$. Sanity check: the residue degrees sum to $1+3=4=\deg f=[\mathbb{Q}(\alpha):\mathbb{Q}]$, as required for an unramified prime; and a $3$-cycle is an even permutation, while the existence (at other primes) of odd permutations is what makes $G=S_4\not\subseteq A_4$.
\end{wex}

\begin{definition}
A subset $S=\{t_1,\dots,t_n\}\subseteq K$ is \emph{algebraically independent} over $F$ if there is no nonzero polynomial $g\in F[x_1,\dots,x_n]$ with $g(t_1,\dots,t_n)=0$; equivalently, the evaluation map $F[x_1,\dots,x_n]\to K$ is injective. A maximal algebraically independent subset of $K$ is a \emph{transcendence basis} of $K/F$, and its cardinality is the \emph{transcendence degree} $\operatorname{trdeg}_F K$. The extension is \emph{purely transcendental} if $K=F(S)$ for some algebraically independent $S$, so that $K$ is $F$-isomorphic to a rational function field $F(x_1,\dots,x_n)$.
\end{definition}

\begin{proof}[Idea]
Call $\alpha$ \emph{dependent} on a set $T$ if $\alpha$ is algebraic over $F(T)$. The Steinitz exchange axiom says: if $\alpha$ is dependent on $T\cup\{\beta\}$ but not on $T$, then $\beta$ is dependent on $T\cup\{\alpha\}$ -- this follows by clearing denominators in the polynomial relation witnessing the dependence and solving for $\beta$, which now appears to positive degree. Exchange forces all maximal independent sets to be equinumerous by the usual replacement argument (replace the elements of one basis one at a time by elements of another). Additivity in towers: concatenate a transcendence basis $S$ of $L/F$ with a transcendence basis $T$ of $K/L$. The union is algebraically independent over $F$: a relation $g(S,T)=0$ with $g$ over $F$, read as a polynomial in the elements of $T$ with coefficients in $F[S]\subseteq L$, has all these coefficients equal to $0$ because $T$ is independent over $L$, and then each coefficient is the zero polynomial because $S$ is independent over $F$. Maximality follows from transitivity of ``algebraic over'': $K$ is algebraic over $L(T)$, which is algebraic over $F(S\cup T)$ because $L$ is algebraic over $F(S)$.
\end{proof}

\begin{wex}{Transcendence degree of a rational function field}
Show $\operatorname{trdeg}_F F(x,y)=2$, where $x,y$ are independent transcendentals.
\wrec By definition $x,y$ independent means no nonzero $g\in F[X,Y]$ has $g(x,y)=0$; this is exactly the statement that $\{x,y\}$ is algebraically independent, and it is maximal because $F(x,y)$ is algebraic over itself.
\wsol The set $\{x,y\}$ is algebraically independent over $F$ by hypothesis, so $\operatorname{trdeg}_F F(x,y)\ge2$. It is maximal: any third element $z\in F(x,y)$ is a rational function $z=p(x,y)/q(x,y)$, hence satisfies $q(x,y)\,z-p(x,y)=0$, a nonzero polynomial relation among $x,y,z$ over $F$. So $\{x,y\}$ is a transcendence basis and $\operatorname{trdeg}_F F(x,y)=2$. Sanity check: additivity gives $\operatorname{trdeg}_F F(x,y)=\operatorname{trdeg}_F F(x)+\operatorname{trdeg}_{F(x)}F(x)(y)=1+1=2$, since $y$ is transcendental over $F(x)$.
\end{wex}

\begin{wex}{A dependent set and a transcendence basis inside $F(x)$}
Show $\{x^2,x^3\}$ is \emph{not} algebraically independent over $F$, while $\{x\}$ is a transcendence basis of $F(x)/F$.
\wrec Algebraic independence of $\{a,b\}$ fails as soon as one nonzero $g\in F[X,Y]$ kills $(a,b)$; here a single relation between $x^2$ and $x^3$ is visible.
\wsol Put $a=x^2,\ b=x^3$. Then $a^3=x^6=b^2$, so $g(X,Y)=X^3-Y^2$ is a nonzero polynomial with $g(a,b)=0$. Hence $\{x^2,x^3\}$ is algebraically \emph{dependent}; its transcendence degree is only $1$ (both lie in $F(x)$, which has transcendence degree $1$). On the other hand $\{x\}$ is algebraically independent (a single transcendental) and maximal, because every element of $F(x)$ is algebraic -- indeed rational -- over $F(x)$. So $\operatorname{trdeg}_F F(x)=1$. Sanity check: $F(x^2,x^3)=F(x)$ since $x=x^3/x^2$, so adjoining the dependent pair recovers the whole field, confirming both generate a transcendence-degree-$1$ extension, not $2$.
\end{wex}

\begin{wex}{Transcendence degree is insensitive to algebraic extensions}
Let $K=F(x,y)$ and let $L=K(\sqrt{x})=F(\sqrt{x},y)$. Compute $\operatorname{trdeg}_F L$.
\wrec Adjoining an algebraic element changes the algebraic part of an extension but not its transcendence degree, by additivity in the tower $F\subseteq K\subseteq L$ with $\operatorname{trdeg}_K L=0$.
\wsol Let $u=\sqrt{x}$, so $u^2=x$ and $u$ is algebraic over $K$. Then $L=K(u)$ is algebraic over $K$, giving $\operatorname{trdeg}_K L=0$. By additivity $\operatorname{trdeg}_F L=\operatorname{trdeg}_F K+\operatorname{trdeg}_K L=2+0=2$. A transcendence basis is $\{u,y\}$: indeed $x=u^2\in F(u,y)$ and $L=F(u,y)$ is purely transcendental of degree $2$ in $u,y$. Sanity check: $\{x,y\}$ and $\{u,y\}$ are both transcendence bases of $L$, each of size $2$, consistent with well-definedness; the only change is that $L/F(u,y)$ is trivial whereas $L/F(x,y)$ is algebraic of degree $2$.
\end{wex}

\begin{wex}{An elliptic relation: a non-purely-transcendental extension}
Show $\mathbb{Q}\bigl(k,\sqrt{k^3-k}\bigr)$ has transcendence degree $1$ over $\mathbb{Q}$ but is not purely transcendental.
\wrec Transcendence degree is computed by a greedy basis; pure transcendentality is a finer property that can fail even at degree $1$, detected by an irreducible relation of the wrong shape (an elliptic curve has genus $1$, not $0$).
\wsol Let $y=\sqrt{k^3-k}$, so $y^2=k^3-k$ with $k$ transcendental over $\mathbb{Q}$. Then $\{k\}$ is a transcendence basis: $y$ is algebraic of degree $2$ over $\mathbb{Q}(k)$, so $\operatorname{trdeg}_\mathbb{Q}\mathbb{Q}(k,y)=1$. It is not purely transcendental: a purely transcendental degree-$1$ field is $\mathbb{Q}(z)$, a rational function field, whose associated curve has genus $0$, whereas $y^2=k^3-k$ defines a smooth cubic (an elliptic curve) of genus $1$; a field of genus $1$ cannot equal one of genus $0$. Concretely, no rational parametrization $k=\phi(z),\ y=\psi(z)$ with $\phi$ nonconstant exists: it would identify $\mathbb{Q}(k,y)$ with a subfield of $\mathbb{Q}(z)$ strictly containing $\mathbb{Q}$, and by L\"uroth's theorem every such subfield is again a rational function field $\mathbb{Q}(w)$, of genus $0$. The obstruction is the genus, not a lack of rational points: the curve contains $(0,0)$, $(\pm1,0)$ and the rational point $[0:1:0]$ at infinity. Sanity check: contrast with $y^2=k^2-k$, which factors via $y=k\sqrt{1-1/k}$ -- a conic, genus $0$, which \emph{is} rational; the cubic's nonzero discriminant $\disc(k^3-k)=-4(-1)^3=4\neq0$ confirms $y^2=k^3-k$ is genuinely elliptic, not a degenerate conic.
\end{wex}

\begin{definition}
A transcendence basis $S$ of $K/F$ is a \emph{separating transcendence basis} if $K$ is a (finite) separable algebraic extension of $F(S)$. When such a basis exists, $K/F$ is called \emph{separably generated}.
\end{definition}

\begin{wex}{A separating transcendence basis exists}
Let $K=\F_p(t)(\alpha)$ where $\alpha^2-\alpha-t=0$ and $p$ is odd. Exhibit a separating transcendence basis.
\wrec An Artin--Schreier-type relation $\alpha^2-\alpha-t=0$ is separable when its derivative in $\alpha$ is nonzero; we look for a transcendental base leaving a separable residual extension.
\wsol Here $\{t\}$ is a transcendence basis and $\alpha$ is algebraic over $\F_p(t)$ with minimal polynomial $f(x)=x^2-x-t$. Its derivative $f'(x)=2x-1$ is nonzero ($p$ odd), and $\gcd(f,f')=1$, so $f$ is separable and $K/\F_p(t)$ is separable. Thus $\{t\}$ is a separating transcendence basis. Sanity check: alternatively take $\{\alpha\}$ as the basis -- then $t=\alpha^2-\alpha\in\F_p(\alpha)$ so $K=\F_p(\alpha)$ is purely transcendental in $\alpha$, hence trivially separable over $\F_p(\alpha)$; either basis separates.
\end{wex}

\begin{wex}{No separating transcendence base: infinitely many $p$-power roots}
Let $K=\bigcup_{k\ge0}\F_p\bigl(t^{1/p^k}\bigr)$, the field obtained from $\F_p(t)$ by adjoining all $p$-power roots of $t$. Show $\operatorname{trdeg}_{\F_p}K=1$ but $K/\F_p$ has no separating transcendence base.
\wrec Transcendence degree counts independent transcendentals; a separating base would make $K$ separable over a rational function field, but every element here has a $p$-th root in $K$, an obstruction to separability.
\wsol Each $t^{1/p^k}$ is transcendental over $\F_p$, and any two of them are algebraically dependent ($t^{1/p^k}=(t^{1/p^{k+1}})^p$), so $\operatorname{trdeg}_{\F_p}K=1$; e.g.\ $\{t\}$ is a transcendence basis. Suppose $\{u\}$ were a separating transcendence base, so $K/\F_p(u)$ is separable algebraic. Every element of $K$ is a $p$-th power in $K$: if $a=r(t^{1/p^k})$ with $r\in\F_p(X)$, then $a=\bigl(r(t^{1/p^{k+1}})\bigr)^p$, since the Frobenius fixes the coefficients of $r$. In particular $v=u^{1/p}\in K$. But $v$ is a root of $x^p-u=(x-v)^p$, which is irreducible over $\F_p(u)$ because the transcendental $u$ is not a $p$-th power in $\F_p(u)$; so $v$ is inseparable over $\F_p(u)$, a contradiction. Hence no separating base exists. Sanity check: $K$ being closed under $p$-th roots means $K=K^{1/p}$, the exact failure of separable generation; this matches that $K$ is not finitely generated over $\F_p$, the hypothesis under which separating bases are guaranteed over perfect fields.
\end{wex}

\begin{definition}
Let $K/F$ be finite and fix an algebraic closure $\overline F\supseteq K$. The \emph{separable degree} $[K:F]_s$ is the number of $F$-embeddings $K\hookrightarrow\overline F$. The \emph{inseparable degree} is the quotient $[K:F]_i=[K:F]/[K:F]_s$.
\end{definition}

\begin{proof}[Idea]
For a simple extension $F(\alpha)/F$ with minimal polynomial $m_\alpha$, the $F$-embeddings into $\overline F$ are in bijection with the \emph{distinct} roots of $m_\alpha$, so $[F(\alpha):F]_s$ counts distinct roots while $[F(\alpha):F]=\deg m_\alpha$ counts roots with multiplicity. In characteristic $p$, $m_\alpha(x)=g(x^{p^e})$ for a separable $g$, and every root has the same multiplicity $p^e$, so $[F(\alpha):F]_i=p^e$. Multiplicativity of $[\cdot:\cdot]_s$ comes from extending embeddings step by step through a tower (each of the $[L:F]_s$ embeddings of $L$ extends in exactly $[K:L]_s$ ways to $K$). Dividing the multiplicative relation for ordinary degree by that for separable degree gives multiplicativity of the inseparable degree, hence $[K:F]_i$ is a product of prime-power local inseparable degrees, a power of $p$.
\end{proof}

\begin{wex}{Separable degree equals degree for a separable extension}
Compute $[\mathbb{Q}(\sqrt[3]{2},\omega):\mathbb{Q}]_s$, where $\omega=e^{2\pi i/3}$.
\wrec In characteristic $0$ every extension is separable, so $[K:F]_s=[K:F]$ and $[K:F]_i=1$; we only need the ordinary degree.
\wsol $K=\mathbb{Q}(\sqrt[3]2,\omega)$ is the splitting field of $x^3-2$, with $[K:\mathbb{Q}]=6$. Since $\charac\mathbb{Q}=0$, $K/\mathbb{Q}$ is separable, so $[K:\mathbb{Q}]_s=6$ and $[K:\mathbb{Q}]_i=1$. Sanity check: $K/\mathbb{Q}$ is Galois with $\Gal(K/\mathbb{Q})\cong S_3$ of order $6$, and the number of $\mathbb{Q}$-embeddings of a Galois extension into $\overline\mathbb{Q}$ equals $\abs{\Gal(K/\mathbb{Q})}=6=[K:\mathbb{Q}]_s$, exactly as the separable degree should.
\end{wex}

\begin{wex}{A mixed example: computing $[K:F]_s$ and $[K:F]_i$}
Let $p$ be a prime, $F=\F_p(s,t)$ with $s,t$ independent transcendentals, and $K=F(\alpha,\beta)$ where $\alpha^p=s$ and $\beta^2-\beta-t=0$ (take $p$ odd). Find $[K:F]$, $[K:F]_s$, $[K:F]_i$.
\wrec Factor through the tower $F\subseteq F(\alpha)\subseteq K$. The first step $x^p-s$ is purely inseparable (one repeated root), contributing to $[\cdot:\cdot]_i$; the second step $x^2-x-t$ is separable, contributing to $[\cdot:\cdot]_s$.
\wsol Step one: $x^p-s$ is irreducible over $F$ (Eisenstein at the prime $s$ in $\F_p[s][t]$-localized, or since $s$ is not a $p$-th power in $F$) and equals $(x-\alpha)^p$ over $\overline F$, so $[F(\alpha):F]=p$ with a single root: $[F(\alpha):F]_s=1$, $[F(\alpha):F]_i=p$. Step two: $x^2-x-t$ has derivative $2x-1\ne0$, hence is separable of degree $2$ over $F(\alpha)$: $[K:F(\alpha)]=[K:F(\alpha)]_s=2$, $[K:F(\alpha)]_i=1$. Multiplying: $[K:F]=p\cdot2=2p$, $[K:F]_s=1\cdot2=2$, $[K:F]_i=p\cdot1=p$. Sanity check: $[K:F]_s\cdot[K:F]_i=2\cdot p=2p=[K:F]$, and $[K:F]_i=p$ is a power of $p$, both as required.
\end{wex}

\begin{wex}{Separable and inseparable degree each equal $p$}
Let $K=\F_p(x,y)$ with $x,y$ independent transcendentals and $F=\F_p(x^p-x,\ y^p-x)$. Show $[K:F]=p^2$ with $[K:F]_s=[K:F]_i=p$.
\wrec Write $s=x^p-x$ and $t=y^p-x$. Then $x$ is a root of a separable polynomial over $F$, while $y$ is a $p$-th root, the inseparable layer; build the tower so each layer's type is visible.
\wsol Over $F=\F_p(s,t)$, the element $x$ satisfies $x^p-x-s=0$, an Artin--Schreier polynomial: separable (derivative $px^{p-1}-1=-1\ne0$) and irreducible of degree $p$, so $[F(x):F]=[F(x):F]_s=p$ with $[F(x):F]_i=1$. Now over $F(x)$ we have $y^p=t+x$, i.e.\ $y$ is a root of $z^p-(t+x)=(z-y)^p$: purely inseparable of degree $p$, so $[K:F(x)]=[K:F(x)]_i=p$, $[K:F(x)]_s=1$. Hence $[K:F]=p\cdot p=p^2$, $[K:F]_s=p\cdot1=p$, $[K:F]_i=1\cdot p=p$. Sanity check: $[K:F]_s\,[K:F]_i=p\cdot p=p^2=[K:F]$; and $s-t=(x^p-x)-(y^p-x)=x^p-y^p=(x-y)^p\in F$, so $E=F(x-y)$ is a $p$-th root extension realizing the purely inseparable degree-$p$ piece, consistent with $[K:F]_i=p$.
\end{wex}

\begin{definition}
An algebraic extension $K/F$ of characteristic $p$ is \emph{purely inseparable} if every $\alpha\in K$ has $\alpha^{p^k}\in F$ for some $k\ge0$; equivalently the minimal polynomial of each $\alpha$ over $F$ has the form $x^{p^k}-a$. Then $[K:F]_s=1$, so $K/F$ admits only the identity embedding and $\Aut(K/F)=1$.
\end{definition}

\begin{proposition}[{purely inseparable means trivial separable degree}]
A finite extension $K/F$ is purely inseparable iff $[K:F]_s=1$, iff $[K:F]=[K:F]_i$. In that case $[K:F]$ is a power of $p$ and $\Aut(K/F)=\{\id\}$.
\end{proposition}

\begin{proof}[Idea]
If $\alpha^{p^k}=a\in F$ then $m_\alpha\mid x^{p^k}-a=(x-\alpha)^{p^k}$, so $\alpha$ is the only root: one embedding. Conversely if $[K:F]_s=1$ each generator has a single root in $\overline F$, forcing minimal polynomials of the shape $(x-\alpha)^{p^k}$, i.e.\ $x^{p^k}-\alpha^{p^k}$ with $\alpha^{p^k}\in F$. Finally, every $\sigma\in\Aut(K/F)$, followed by the inclusion $K\subseteq\overline F$, is an $F$-embedding $K\hookrightarrow\overline F$; the inclusion is the only one, so $\sigma=\id$ and $\Aut(K/F)=1$.
\end{proof}

\begin{definition}
A field $F$ is \emph{perfect} if every algebraic extension of $F$ is separable. Characteristic $0$ fields are perfect; a characteristic $p$ field $F$ is perfect iff the Frobenius $x\mapsto x^p$ is surjective, i.e.\ $F=F^p$. Finite fields and algebraically closed fields are perfect.
\end{definition}

\begin{wex}{The purely inseparable extension $\F_p(t^{1/p})/\F_p(t)$ of degree $p$}
Show $K=\F_p(t^{1/p})$ is purely inseparable of degree $p$ over $F=\F_p(t)$ with $\Aut(K/F)=1$, even though $K/F$ is normal.
\wrec $t$ is not a $p$-th power in $F=\F_p(t)$, so $x^p-t$ is irreducible; in characteristic $p$ it factors as $(x-t^{1/p})^p$, the signature of pure inseparability.
\wsol Let $\theta=t^{1/p}$, so $\theta^p=t$. Over $F$, $x^p-t=(x-\theta)^p$ has $\theta$ as its only root, with multiplicity $p$. The polynomial is irreducible (Eisenstein at $t$ in $\F_p[t]$), so $[K:F]=p$, $[K:F]_s=1$, $[K:F]_i=p$: purely inseparable. Any $\sigma\in\Aut(K/F)$ must send $\theta$ to a root of $x^p-t$, but $\theta$ is the only root, so $\sigma(\theta)=\theta$ and $\sigma=\id$. Thus $\Aut(K/F)=1$. Yet $K/F$ \emph{is} normal: $K$ is the splitting field of $x^p-t$ (it splits completely, as $(x-\theta)^p$). Sanity check: $\abs{\Aut(K/F)}=1\ne p=[K:F]$, so the would-be ``Galois group'' is too small -- this is precisely why normal $+$ inseparable is \emph{not} Galois; the count $\abs{\Aut(K/F)}=[K:F]$ holds only when $K/F$ is also separable.
\end{wex}

\begin{pitfall}
``Normal'' does not imply ``Galois.'' The extension $\F_p(t^{1/p})/\F_p(t)$ is normal (it is a splitting field) but $\abs{\Aut(K/F)}=1<p=[K:F]$. Galois requires normal \emph{and separable}; equivalently $\abs{\Aut(K/F)}=[K:F]$, which forces $[K:F]_s=[K:F]$. Whenever an extension has nontrivial inseparable degree, its automorphism group is strictly too small to ``see'' the whole extension.
\end{pitfall}

\begin{wex}{A perfect field: $F=F^p$ for finite fields}
Verify that $\F_q$ ($q=p^n$) is perfect by checking Frobenius is surjective.
\wrec A characteristic-$p$ field is perfect iff $x\mapsto x^p$ is onto; on a finite field an injective endomorphism is automatically onto.
\wsol Frobenius $\phi:\F_q\to\F_q$, $\phi(a)=a^p$, is a field homomorphism, hence injective (its kernel is $0$). An injective map from a finite set to itself is surjective, so $\phi$ is onto: $\F_q=\F_q^p$. Therefore $\F_q$ is perfect and every algebraic extension of $\F_q$ is separable. Sanity check: concretely in $\F_p$, $a^p=a$ for all $a$ (Fermat), so $\phi=\id$ is trivially surjective; and there are no purely inseparable extensions of a finite field, consistent with $\overline{\F_p}/\F_p$ being separable.
\end{wex}

\begin{wex}{An imperfect field and its separable closure}
Show $F=\F_p(t)$ is not perfect, and describe the separable closure of $F$ inside a purely inseparable extension.
\wrec $F$ imperfect means $F\ne F^p$: some element is not a $p$-th power. The separable closure $F^{\mathrm{sep}}$ of $F$ in $\overline F$ collects all elements separable over $F$; purely inseparable elements lie outside it.
\wsol In $F=\F_p(t)$, the element $t$ is not a $p$-th power: if $t=g(t)^p$ for $g\in F$, comparing degrees forces $1=p\deg g$, impossible. So $F\ne F^p$ and $F$ is imperfect. Inside $\overline F$, $F^{\mathrm{sep}}=\{\alpha\in\overline F:\alpha\text{ separable over }F\}$ is a field (the separable elements form a subfield), and $\overline F/F^{\mathrm{sep}}$ is purely inseparable. The element $t^{1/p}$ is \emph{not} in $F^{\mathrm{sep}}$: its minimal polynomial $x^p-t=(x-t^{1/p})^p$ is inseparable. Sanity check: $[F^{\mathrm{sep}}:F]=[\overline F:F]_s$ and $[\overline F:F^{\mathrm{sep}}]=[\overline F:F]_i$, factoring the closure into its separable-then-purely-inseparable layers; over the perfect field $\F_p$ this inseparable layer is trivial, matching the previous example.
\end{wex}

\begin{wex}{Every purely inseparable extension is normal}
Prove that a purely inseparable extension $K/F$ is normal.
\wrec Normal means every irreducible polynomial over $F$ with a root in $K$ splits in $K$. For purely inseparable $K/F$ the minimal polynomials have the single-root form $(x-\alpha)^{p^k}$, which trivially splits once it has one root.
\wsol Let $\alpha\in K$ with minimal polynomial $m_\alpha\in F[x]$. By pure inseparability $\alpha^{p^k}=a\in F$ for some $k$, so $m_\alpha\mid x^{p^k}-a=(x-\alpha)^{p^k}$; being irreducible and monic, $m_\alpha=(x-\alpha)^{p^j}$ for some $j\le k$. This polynomial splits completely in $K$ (all roots equal $\alpha\in K$). Since every such $m_\alpha$ splits in $K$, the extension $K/F$ is normal. Sanity check: this matches the example $\F_p(t^{1/p})/\F_p(t)$, which we already saw is a splitting field (of $x^p-t$), hence normal -- normality holds despite the trivial automorphism group.
\end{wex}

\begin{definition}
Let $K/F$ be Galois, possibly infinite. The \emph{Krull topology} on $G=\Gal(K/F)$ has, as a base of open neighborhoods of $\id$, the subgroups $\Gal(K/E)$ where $E/F$ ranges over the finite Galois subextensions $F\subseteq E\subseteq K$. These subgroups are normal of finite index, and $G$ becomes a Hausdorff, compact, totally disconnected topological group.
\end{definition}

\begin{proof}[Idea]
An automorphism $\sigma\in\Gal(K/F)$ is determined by its restrictions $\sigma|_E$ to all finite Galois $E/F$, and these restrictions are compatible: $(\sigma|_{E'})|_E=\sigma|_E$ for $E\subseteq E'$. This is exactly the data of an element of the inverse limit, giving an injective homomorphism $\sigma\mapsto(\sigma|_E)_E$. It is surjective because a compatible system glues to a well-defined automorphism of $K=\bigcup_E E$. The product $\prod_E\Gal(E/F)$ of finite (discrete) groups is compact by Tychonoff; the inverse limit is a closed subset, hence compact, and the subspace topology is the Krull topology.
\end{proof}

\begin{theorem}[{Fundamental Theorem for infinite Galois extensions}]
Let $K/F$ be Galois with group $G=\Gal(K/F)$ carrying the Krull topology. Then
\[
\{\text{closed subgroups }H\sgr G\}\ \xleftrightarrow{\ \Fix\ }\ \{\text{intermediate fields }F\sgr E\sgr K\}
\]
is an inclusion-reversing bijection, $H\mapsto\Fix(H)$ and $E\mapsto\Gal(K/E)$. Under it:
\begin{enumerate}[label=\textup{(\arabic*)},leftmargin=*]
\item \emph{open} subgroups correspond to \emph{finite-degree} subextensions $E/F$;
\item \emph{closed normal} subgroups correspond to Galois subextensions $E/F$, with $\Gal(E/F)\cong G/\Gal(K/E)$.
\end{enumerate}
Every open subgroup is closed of finite index, but not every (abstract) finite-index subgroup is open; the correspondence sees only closed subgroups.
\end{theorem}

\begin{proof}[Idea]
The finite case applies to each finite Galois layer $E/F$; passing to the limit, $\Gal(K/E)$ is closed (the intersection, over all $\alpha\in E$, of the open subgroups $\Gal(K/F(\alpha))$; $E/F$ need not be finitely generated). Closedness of $H$ is exactly the condition $H=\Gal(K/\Fix(H))$, i.e.\ that no extra automorphisms ``approximate'' $H$ in the Krull topology. For closed $H$: open $\iff$ finite index $\iff$ contains some $\Gal(K/E)$ with $E/F$ finite, which translates to $\Fix(H)/F$ finite. Normality and the quotient identification descend from the finite layers.
\end{proof}

\begin{wex}{An open subgroup and its finite subextension}
In $G=\Gal(\overline{\F_p}/\F_p)=\widehat\mathbb{Z}$, identify the open subgroup corresponding to $\F_{p^n}$ and its index.
\wrec Open subgroups $\leftrightarrow$ finite-degree subextensions; the subgroup fixing $\F_{p^n}$ is $\Gal(\overline{\F_p}/\F_{p^n})$, the closed (and open) subgroup $n\widehat\mathbb{Z}\sgr\widehat\mathbb{Z}$.
\wsol The intermediate field $\F_{p^n}$ has $[\F_{p^n}:\F_p]=n<\infty$, so it corresponds to an open subgroup $H=\Gal(\overline{\F_p}/\F_{p^n})$. As a subgroup of $\widehat\mathbb{Z}$ this is $n\widehat\mathbb{Z}=\overline{\langle \Frob_p^{\,n}\rangle}$, with $[\widehat\mathbb{Z}:n\widehat\mathbb{Z}]=n$. Indeed $H\cong\Gal(\overline{\F_p}/\F_{p^n})\cong\widehat\mathbb{Z}$ again (generated by $\Frob_{p^n}=\Frob_p^{\,n}$), since $\overline{\F_p}/\F_{p^n}$ has the same shape. Sanity check: the index $n$ equals $[\F_{p^n}:\F_p]=\abs{G/H}$, matching that $G/H\cong\Gal(\F_{p^n}/\F_p)\cong\mathbb{Z}/(n)\mathbb{Z}$ -- the open subgroup has finite index exactly equal to the finite degree it fixes.
\end{wex}

\begin{wex}{A closed-but-not-open subgroup}
Exhibit in $\widehat\mathbb{Z}=\Gal(\overline{\F_p}/\F_p)$ a closed subgroup of infinite index, and name its fixed field.
\wrec Closed subgroups $\leftrightarrow$ all intermediate fields; an infinite-index closed subgroup fixes an \emph{infinite}-degree subextension. The $\ell$-part of $\widehat\mathbb{Z}$ gives one.
\wsol Fix a prime $\ell$ and let $H=\prod_{q\ne\ell}\mathbb{Z}_q\sgr\widehat\mathbb{Z}=\prod_q\mathbb{Z}_q$ (drop the $\ell$-component). Then $H$ is closed (a product of closed factors), and $[\widehat\mathbb{Z}:H]$ is infinite (the quotient is $\mathbb{Z}_\ell$, infinite). Its fixed field $\Fix(H)=\bigcup_k\F_{p^{\ell^k}}$ is the union of all $\F_{p^{\ell^k}}$, an infinite algebraic extension of $\F_p$ with $\Gal\cong\mathbb{Z}_\ell$. This $H$ is \emph{not} open: open subgroups have finite index. Sanity check: $\Fix(H)/\F_p$ being infinite matches $H$ being closed but not open (item (1) of the Fundamental Theorem); and $\widehat\mathbb{Z}/H\cong\mathbb{Z}_\ell$ is itself profinite, consistent with $\Fix(H)/\F_p$ being Galois with group $\mathbb{Z}_\ell$.
\end{wex}

\begin{wex}{The motivating open problem: $\Gal(\overline\mathbb{Q}/\mathbb{Q})$}
Frame the absolute Galois group of $\mathbb{Q}$ as an inverse limit and state why it is hard.
\wrec Every finite Galois $E/\mathbb{Q}$ gives a finite quotient $\Gal(E/\mathbb{Q})$; the absolute group is their inverse limit, but unlike the finite-field case the finite quotients are not all cyclic and are far from understood.
\wsol Set $G_\mathbb{Q}=\Gal(\overline\mathbb{Q}/\mathbb{Q})=\varprojlim_E\Gal(E/\mathbb{Q})$ over finite Galois $E/\mathbb{Q}$, a profinite group under the Krull topology. By the Fundamental Theorem, closed subgroups of $G_\mathbb{Q}$ correspond to subfields of $\overline\mathbb{Q}$, and open subgroups to number fields (finite-degree $E/\mathbb{Q}$). Unlike $\widehat\mathbb{Z}=G_{\F_p}$, which is abelian and topologically cyclic, $G_\mathbb{Q}$ is highly nonabelian, and \emph{which} finite groups arise as quotients $\Gal(E/\mathbb{Q})$ is the unsolved Inverse Galois Problem. Sanity check: the abelianization $G_\mathbb{Q}^{\mathrm{ab}}=\Gal(\mathbb{Q}^{\mathrm{ab}}/\mathbb{Q})\cong\widehat\mathbb{Z}^\times$ is known (Kronecker--Weber: $\mathbb{Q}^{\mathrm{ab}}=\mathbb{Q}(\mu_\infty)$ is generated by all roots of unity), so even the \emph{abelian} part already requires the full profinite machinery of this section -- the nonabelian part remains open.
\end{wex}

\begin{definition}[Symmetric polynomial]
$g\in R[u_1,\dots,u_n]$ is \emph{symmetric} if $\sigma g=g$ for all $\sigma\in\Sym_n$, i.e.\ $g(u_{\sigma 1},\dots,u_{\sigma n})=g(u_1,\dots,u_n)$. The symmetric polynomials form a subring of $R[u]$. Equivalently, $g$ is symmetric iff any two monomials in the same $\Sym_n$-orbit (e.g.\ $u_1^2u_2$ and $u_2u_3^2$) occur with the same coefficient; the sum of the monomials in one orbit is an \emph{orbit sum}, and the orbit sums form an $R$-basis of the symmetric polynomials.
\end{definition}

\begin{lemma}[{coefficients are the elementary symmetric functions of the roots}]
\label{art:symmetric:vieta@c14}
If $f(x)=x^n-a_1x^{n-1}+\cdots+(-1)^n a_n$ splits as $f(x)=(x-\alpha_1)\cdots(x-\alpha_n)$ in a field $K$, then $a_k=e_k(\alpha_1,\dots,\alpha_n)$ for each $k$. That is, the coefficients are obtained by evaluating the elementary symmetric functions at the roots.
\end{lemma}

\begin{proof}
Substitute $u_i=\alpha_i$ into the expansion of $P(x)=\prod_i(x-u_i)$ above and compare coefficients with $f(x)=\prod_i(x-\alpha_i)$. The coefficient of $x^{n-k}$ in $\prod_i(x-\alpha_i)$ is exactly $(-1)^k$ times the sum of all products of $k$ distinct roots, namely $(-1)^k e_k(\alpha)$; matching against $(-1)^k a_k$ gives $a_k=e_k(\alpha)$.
\end{proof}

\begin{corollary}[{symmetric functions of roots stay in the base field}]
\label{art:symmetric:rational@c14}
Let $f(x)=x^n-a_1x^{n-1}+\cdots+(-1)^n a_n\in F[x]$ split completely in an extension $K/F$ with roots $\alpha_1,\dots,\alpha_n$. If $g(u_1,\dots,u_n)$ is any symmetric polynomial with coefficients in $F$, then $g(\alpha_1,\dots,\alpha_n)\in F$.
\end{corollary}

\begin{proof}
By Theorem~\ref{art:symmetric:fund@c14}, $g=G(e_1,\dots,e_n)$ with $G$ having coefficients in $F$. Evaluating at $u_i=\alpha_i$ and using Lemma~\ref{art:symmetric:vieta@c14}, $e_k(\alpha)=a_k\in F$. Hence $g(\alpha)=G(a_1,\dots,a_n)$ is a polynomial expression in the $a_k\in F$ with coefficients in $F$, so it lies in $F$. For instance $\alpha_1^k+\cdots+\alpha_n^k\in F$ for every $k$, even when no individual root lies in $F$.
\end{proof}

\begin{remark}
Corollary~\ref{art:symmetric:rational@c14} is the bridge to Galois theory: the coefficients $a_k$ \emph{are} the elementary symmetric functions of the roots, so any quantity invariant under permuting the roots is already expressible in the $a_k$ and therefore rational over $F$. The Galois group acts on the roots by permutations, and the symmetric (fully invariant) functions are precisely the ones fixed by the whole symmetric group -- the bottom of the fixed-field correspondence.
\end{remark}

\begin{pitfall}
The theorem expresses symmetric polynomials in the $e_i$ \emph{with coefficients in $R$} only; it does not let you divide. Newton's identity $p_k+\cdots+(-1)^k k\,e_k=0$ solves for $p_k$ in terms of lower data without dividing, but solving for $e_k$ in terms of the $p_j$ introduces the factor $\tfrac1k$. Hence the change of generators from $e$'s to power sums $p$'s is valid only when $1,2,\dots,n$ are invertible in $R$ (e.g.\ over a field of characteristic $0$, or any characteristic exceeding $n$), and can fail in small positive characteristic.
\end{pitfall}

\begin{proof}
A permutation $\tau\in\Sym_n$ of the variables sends each factor $(\alpha_i-\alpha_j)^2$ to another factor $(\alpha_{\tau(i)}-\alpha_{\tau(j)})^2$ of the same product: since $(\alpha_j-\alpha_i)^2=(\alpha_i-\alpha_j)^2$, the squaring kills the sign that the transposition would otherwise introduce, so $\tau$ merely permutes the $\binom{n}{2}$ factors among themselves and fixes their product. Thus $\disc(f)$ is symmetric. The Symmetric Functions Theorem then writes any symmetric integer polynomial uniquely as an integer polynomial $A(s_1,\dots,s_n)$ in the elementary symmetric functions. When the $\alpha_i$ are the roots of $f\in F[x]$, the $s_i$ are (up to sign) the coefficients of $f$, hence lie in $F$, so $\disc(f)=A(s_1,\dots,s_n)\in F$.
\end{proof}

\begin{remark}
For $n=2$, $f(x)=x^2-s_1x+s_2$ has $\disc(f)=(\alpha_1-\alpha_2)^2=(\alpha_1+\alpha_2)^2-4\alpha_1\alpha_2=s_1^2-4s_2$ -- the familiar $b^2-4ac$ for $x^2-s_1x+s_2$. The point that this is literally the \emph{square} of the difference of the roots is exactly what generalizes.
\end{remark}

\begin{theorem}[discriminant of a depressed cubic]\label{art:discriminant:cubic@c14}
Over a field of characteristic $\ne2,3$,
\[
\disc(x^3+px+q)=-4p^3-27q^2 .
\]
\end{theorem}

\begin{wex}{Discriminant of $x^3+3x+1$}
Compute $\disc(x^3+3x+1)$.
\wrec Already depressed ($p=3,\ q=1$); apply Theorem~\ref{art:discriminant:cubic@c14} directly.
\wsol $\disc=-4(3)^3-27(1)^2=-4\cdot27-27=-108-27=-135=-5\cdot3^3$. \textit{Check.} $-135<0$, and for a real cubic a negative discriminant signals one real and two complex-conjugate roots; here $x^3+3x+1$ is strictly increasing ($g'(x)=3x^2+3>0$), so it has exactly one real root, consistent with $\disc<0$.
\end{wex}

\begin{wex}{Discriminant of $x^3-3x+1$}
Compute $\disc(x^3-3x+1)$.
\wrec Depressed with $p=-3,\ q=1$; use $\disc=-4p^3-27q^2$.
\wsol $\disc=-4(-3)^3-27(1)^2=-4(-27)-27=108-27=81=3^4$. \textit{Check.} $81=9^2$ is a perfect square in $\mathbb{Q}$. Also $81>0$, predicting three distinct real roots; indeed $g(x)=x^3-3x+1=2\cos3\theta$-type behavior gives $g(-2)<0<g(-1)$, $g(0)>0>g(1)$, $g(1)<0<g(2)$, three real roots. Both checks agree.
\end{wex}

\begin{wex}{Reduce a non-depressed cubic first}
Compute $\disc(x^3-3x^2+1)$.
\wrec Not depressed; substitute $x=y+1$ (i.e.\ $x=y-a/3$ with $a=-3$) to remove the $x^2$ term, then apply the formula.
\wsol $x=y+1$: $(y+1)^3-3(y+1)^2+1=y^3+3y^2+3y+1-3y^2-6y-3+1=y^3-3y-1$, so $p=-3,\ q=-1$. Then $\disc=-4(-3)^3-27(-1)^2=108-27=81=3^4$. \textit{Check.} Translation by $1$ does not move root differences, so the answer must match a depressed cubic with the same differences; $y^3-3y-1$ has the same discriminant $81$ as $y^3-3y+1$ since $\disc$ depends on $q$ only through $q^2$.
\end{wex}

\begin{theorem}[discriminant criterion]\label{art:discriminant:An@c14}
Let $f\in F[x]$ be separable with splitting field $K$, $\operatorname{char}F\ne2$, and view $G=\Gal(K/F)$ as a subgroup of $\Sym_n$ via its action on the roots. Then
\[
\disc(f)\ \text{is a square in } F\iff G\sgr\mathrm{A}_n .
\]
\end{theorem}

\begin{proof}
Since $\disc(f)=\delta^2\in F$, we have $\delta\in F$ if and only if $\disc(f)$ is a square in $F$. Now $\delta\in F$ iff $\delta$ is fixed by every $\sigma\in G$ (Galois). But $\sigma(\delta)=\operatorname{sgn}(\sigma)\,\delta$ and $\delta\ne0$, so $\sigma(\delta)=\delta$ iff $\operatorname{sgn}(\sigma)=1$, i.e.\ iff $\sigma\in\mathrm{A}_n$. Hence $\delta\in F$ iff every element of $G$ is even, i.e.\ iff $G\sgr\mathrm{A}_n$. (Characteristic $\ne2$ guarantees $\operatorname{sgn}(\sigma)=-1$ is genuinely distinct from $+1$.)
\end{proof}

\begin{corollary}[Galois theory for a cubic]\label{art:discriminant:cubicgal@c14}
Let $f$ be an irreducible cubic over $F$ ($\operatorname{char}F\ne2,3$) with splitting field $K$ and $G=\Gal(K/F)$, and let $D=\disc(f)$.
\begin{itemize}\itemsep2pt
\item If $D$ is a square in $F$, then $G=\mathrm{A}_3$ and $[K:F]=3$.
\item If $D$ is not a square in $F$, then $G=\Sym_3$ and $[K:F]=6$.
\end{itemize}
\end{corollary}

\begin{proof}
Because $f$ is irreducible of degree $3$, $G$ is a transitive subgroup of $\Sym_3$, hence $G=\mathrm{A}_3$ or $G=\Sym_3$. By Theorem~\ref{art:discriminant:An@c14}, $G\sgr\mathrm{A}_3$ exactly when $D$ is a square in $F$; the only transitive subgroup of $\Sym_3$ contained in $\mathrm{A}_3$ is $\mathrm{A}_3$ itself. So $D$ square gives $G=\mathrm{A}_3$ with $[K:F]=|\mathrm{A}_3|=3$, and $D$ non-square gives $G=\Sym_3$ with $[K:F]=6$.
\end{proof}

\begin{wex}{Read off the group of $x^3+3x+1$ over $\mathbb{Q}$}
Determine $\Gal(K/\mathbb{Q})$ for the splitting field of $x^3+3x+1$.
\wrec $x^3+3x+1$ is irreducible over $\mathbb{Q}$ (no rational root: $\pm1$ fail), so use Corollary~\ref{art:discriminant:cubicgal@c14} with the discriminant computed above.
\wsol $\disc=-135$, and $-135$ is not a square in $\mathbb{Q}$ (it is negative). Hence $G=\Sym_3$ and $[K:\mathbb{Q}]=6$. \textit{Check.} A single real root and a complex-conjugate pair means complex conjugation acts as a transposition of the two non-real roots, an \emph{odd} permutation living in $G$ -- so $G\not\sgr\mathrm{A}_3$, confirming $G=\Sym_3$.
\end{wex}

\begin{wex}{Read off the group of $x^3-3x+1$ over $\mathbb{Q}$}
Determine $\Gal(K/\mathbb{Q})$ for the splitting field of $x^3-3x+1$.
\wrec Irreducible over $\mathbb{Q}$ ($\pm1$ are not roots); apply Corollary~\ref{art:discriminant:cubicgal@c14}.
\wsol $\disc=81=9^2$ is a square in $\mathbb{Q}$, so $G=\mathrm{A}_3$ and $[K:\mathbb{Q}]=3$. \textit{Check.} All three roots are real (we saw $\disc>0$), and $\delta=\sqrt{81}=9\in\mathbb{Q}$ is genuinely rational, so every automorphism fixes $\delta$ and is therefore even -- exactly $G=\mathrm{A}_3$. Since $3$ is prime there are no proper intermediate fields, matching $\mathrm{A}_3$ having no nontrivial proper subgroups.
\end{wex}

\begin{pitfall}
``Square in $F$'' is essential -- the discriminant is computed in $F$, but whether it is a \emph{square} depends on $F$. Over $\mathbb{Q}$, $\disc(x^3-3x+1)=81$ is a square and the group is $\mathrm{A}_3$; but $-135$ being negative is automatically a non-square in $\mathbb{Q}$, while over $\mathbb{C}$ \emph{every} element is a square, so this criterion is only informative over fields with genuine non-squares. Also remember $D=\delta^2$ is the square; the field-theoretic content lives in $\delta=\sqrt{D}$, not in $D$.
\end{pitfall}

\begin{remark}
Acting on the three roots, $\Gal(K/F)$ embeds as a \emph{transitive} subgroup of $S_3$. The only transitive subgroups of $S_3$ are $S_3$ itself and $A_3=\langle (1\,2\,3)\rangle$, the cyclic group of order $3$. So $G$ is one of these two, matched to the two degree cases above: $[K:F]=3\iff G=A_3$ and $[K:F]=6\iff G=S_3$.
\end{remark}

