\begin{theorem}[{resolvent cubic test, Artin 16.9.8}]
Let $G$ be the Galois group of an irreducible quartic $f$ with resolvent cubic $g$. Then $g$ is irreducible over $F$ if and only if $3\mid\ord G$. Moreover:
\begin{itemize}
\item if $g$ splits completely in $F$, then $G=V_4$;
\item if $g$ has exactly one root in $F$, then $G=D_4$ or $C_4$;
\item if $g$ is irreducible over $F$, then $G=S_4$ or $A_4$.
\end{itemize}
\end{theorem}

\begin{proof}
Let $B=\{\beta_1,\beta_2,\beta_3\}$, a set of size $3$ by the Lemma. The action of $S_4$ on $B$ is transitive with kernel $V_4$, giving $\varphi\colon S_4\to S_3$. The roots of $g$ are the $\beta_i$, so $g$ splits in $F$ iff $G$ fixes every $\beta_i$, i.e.\ iff $G\sgr\ker\varphi=V_4$; since $G$ is a transitive subgroup, this forces $G=V_4$.

If $g$ is irreducible over $F$, then $G$ acts transitively on its roots $B$, so $\varphi(G)$ is a transitive subgroup of $S_3$ and $3\mid\ord{\varphi(G)}\mid\ord G$. Conversely, if $3\mid\ord G$ then $G$ contains an element $\rho$ of order $3$ (Cauchy); $\rho\notin V_4=\ker\varphi$, so $\varphi(\rho)$ is a $3$-cycle permuting $B$ cyclically, whence $G$ acts transitively on $B$ and $g$ is irreducible. The transitive subgroups with $3\mid\ord G$ are exactly $S_4$ and $A_4$. The remaining case -- $g$ has one root in $F$ and the other two are conjugate over a quadratic -- leaves $G$ of order divisible by $2$ but not $3$ and not all of $V_4$, which by the list of five transitive subgroups means $G=D_4$ or $C_4$.
\end{proof}

\begin{method}{Identifying $\Gal(f/F)$ for an irreducible quartic.}
\begin{enumerate}[label=\textup{(\arabic*)},leftmargin=*]
\item Compute the discriminant $D$ and decide whether it is a square in $F$.
\item Form the resolvent cubic $g$ and find its factorization type over $F$ (split / one root / irreducible).
\item Read off $G$ from the table:
\[
\begin{array}{c|cc}
 & D\text{ a square} & D\text{ not a square}\\\hline
g\text{ reducible} & V_4 & D_4\text{ or }C_4\\
g\text{ irreducible} & A_4 & S_4
\end{array}
\]
\end{enumerate}
The one residual ambiguity ($D_4$ vs.\ $C_4$, when $D$ is not a square and $g$ has a single root in $F$) is not resolved by any symmetric expression in the roots; one decides it directly, e.g.\ by checking whether $f$ stays irreducible over $F(\sqrt D)$, or whether a product like $\alpha_i\alpha_j$ lies in the relevant quadratic field.
\end{method}

\begin{pitfall}
The labels are a perennial trap. Artin's $D_4$ is the dihedral group of \emph{order $8$} (D\&F's $D_8$), and his $D_2$ is the Klein four-group $V_4$ of order $4$. When you read off the table, match by \emph{order} and by the resolvent's factorization, not by the name alone. A second trap: the resolvent cubic test classifies $G$ only \emph{up to the $D_4$ vs.\ $C_4$ ambiguity}; no symmetric function in the roots distinguishes those two, so that last step always needs an explicit degree or subfield computation.
\end{pitfall}

\begin{proof}[Idea]
An ideal $\overline{\fb}\subseteq A/\fa$ pulls back to $\phi^{-1}(\overline{\fb})$, an ideal of $A$ containing $\ker\phi=\fa$; conversely an ideal $\fb\supseteq\fa$ pushes forward to $\phi(\fb)$. Because $\phi$ is surjective with kernel $\fa$, the two operations are mutually inverse on the indicated sets. The first-isomorphism statement is the usual factorization $A\to f(A)$ through $A/\ker f$.
\end{proof}

\begin{proposition}[{fields by their ideals}]
For a ring $A\neq0$ the following are equivalent: \textup{(i)} $A$ is a field; \textup{(ii)} the only ideals of $A$ are $(0)$ and $(1)$; \textup{(iii)} every homomorphism $f:A\to B$ into a nonzero ring $B$ is injective.
\end{proposition}

\begin{wex}{Ideals of $\mathbb{Z}$ and $k[x]$ are principal}
Show every ideal of $\mathbb{Z}$ is $(n)$ for a unique $n\ge0$, and every ideal of $k[x]$ ($k$ a field) is $(f)$ for a monic $f$ or $(0)$.
\wrec Both rings are Euclidean (division with remainder), and in a Euclidean domain a least-positive / least-degree element generates.
\wsol In $\mathbb{Z}$, given an ideal $\fa\neq(0)$, pick the least positive $n\in\fa$. For any $m\in\fa$ write $m=qn+r$ with $0\le r<n$; then $r=m-qn\in\fa$, forcing $r=0$, so $m\in(n)$ and $\fa=(n)$. Uniqueness: $(n)=(n')$ with $n,n'\ge0$ gives $n\mid n'$ and $n'\mid n$. In $k[x]$ the same argument with the degree as size function gives $\fa=(f)$ for $f$ of least degree, made monic by scaling (a unit of $k$). Sanity check: $(6)\cap(4)=(12)=(\lcm)$ and $(6)+(4)=(2)=(\gcd)$ in $\mathbb{Z}$, matching ``$\cap=\lcm$, sum$=\gcd$'' for principal ideals.
\end{wex}

\begin{wex}{Nilpotent vs.\ zero-divisor: a sharp non-implication}
In $A=\mathbb{Z}/12\mathbb{Z}$, find a nilpotent, an idempotent $\neq0,1$, and a zero-divisor that is not nilpotent.
\wrec Nilpotent means some power is $0$; idempotent means $e^{2}=e$; zero-divisors include all of these but more.
\wsol Nilpotent: $6$, since $6^{2}=36=0$. Idempotent: $4$, since $4^{2}=16=4$; also $9$, since $9^{2}=81=9$ (and indeed $4+9=13=1$, $4\cdot9=36=0$, a complete orthogonal pair). Zero-divisor not nilpotent: $3$, since $3\cdot4=12=0$ yet $3^{n}\in\{3,9,3,9,\dots\}$ never hits $0$. Sanity check: $12=4\cdot3$, so by CRT $\mathbb{Z}/12\mathbb{Z}\cong\mathbb{Z}/4\mathbb{Z}\times\mathbb{Z}/3\mathbb{Z}$; the nontrivial idempotents are exactly the images of $(1,0)$ and $(0,1)$, namely $9$ and $4$, confirming there are precisely two.
\end{wex}

