\begin{theorem}[{existence of maximal ideals, via Zorn}]
Every ring $A\neq0$ has at least one maximal ideal. Consequently:
\begin{enumerate}[label=\textup{(\arabic*)},leftmargin=*]
\item if $\fa\neq(1)$ is an ideal, there is a maximal ideal containing $\fa$;
\item every nonunit of $A$ lies in some maximal ideal.
\end{enumerate}
\end{theorem}

latex:
\begin{theorem}[{existence of maximal ideals, via Zorn}]
Every ring $A\neq0$ has at least one maximal ideal. Consequently:
\begin{enumerate}[label=\textup{(\arabic*)},leftmargin=*]
\item if $\fa\neq(1)$ is an ideal, there is a maximal ideal containing $\fa$;
\item every nonunit of $A$ lies in some maximal ideal.
\end{enumerate}
\end{theorem}

\begin{wex}{Spec of a field and of $\mathbb{Z}$}
Describe all prime ideals of a field $k$ and of $\mathbb{Z}$.
\wrec Primes correspond to domain quotients; in $\mathbb{Z}$ a quotient $\mathbb{Z}/n\mathbb{Z}$ is a domain iff $n=0$ or $n$ prime.
\wsol For a field $k$ the only ideals are $(0),(1)$, and $(0)$ is prime (the quotient is $k$, a domain), $(1)$ excluded; so $\Spec k=\{(0)\}$, a single point. For $\mathbb{Z}$: $\mathbb{Z}/n\mathbb{Z}$ is a domain iff $n$ is $0$ or a rational prime $p$, so $\Spec\mathbb{Z}=\{(0)\}\cup\{(p):p\text{ prime}\}$. The maximal ideals are exactly the $(p)$ (residue field $\F_{p}$); the prime $(0)$ is not maximal (residue field $\mathbb{Q}$, but $(0)\subset(p)$). Sanity check: the inclusion $(0)\subset(p)$ matches $\dim\mathbb{Z}=1$ -- a chain of primes of length one -- the ``arithmetic line.''
\end{wex}

\begin{wex}{Maximal ideals of $k[x_{1},\dots,x_{n}]$ at a point}
For $k$ a field and $a=(a_{1},\dots,a_{n})\in k^{n}$, show $\fm_{a}=(x_{1}-a_{1},\dots,x_{n}-a_{n})$ is maximal with residue field $k$.
\wrec Maximal $\iff$ quotient is a field; evaluation at $a$ realizes the quotient.
\wsol The evaluation map $\operatorname{ev}_{a}:k[x_{1},\dots,x_{n}]\to k$, $f\mapsto f(a)$, is a surjective ring homomorphism with kernel containing each $x_{i}-a_{i}$, hence containing $\fm_{a}$. By Taylor expansion about $a$, any $f$ equals $f(a)$ plus an element of $\fm_{a}$, so $\ker\operatorname{ev}_{a}=\fm_{a}$ and $k[x_{1},\dots,x_{n}]/\fm_{a}\cong k$, a field. Thus $\fm_{a}$ is maximal. Sanity check: this is exactly the ``point $a$ = maximal ideal'' dictionary; over an algebraically closed $k$, Hilbert's Nullstellensatz says \emph{all} maximal ideals arise this way, so $\mSpec=k^{n}$ literally is the geometric space.
\end{wex}

\begin{wex}{A prime that is not maximal, and a maximal that ``looks'' prime}
In $A=\mathbb{Z}[x]$ exhibit a chain $(0)\subset(p)\subset(p,x)$ of primes and identify which are maximal.
\wrec Use $A/\fp$ is a domain (prime) vs.\ a field (maximal); compute the quotients.
\wsol $A/(0)=\mathbb{Z}[x]$, a domain, so $(0)$ is prime, not maximal. $A/(p)=\F_{p}[x]$, a domain but not a field, so $(p)$ is prime, not maximal. $A/(p,x)\cong\F_{p}$, a field, so $(p,x)$ is maximal. Each inclusion is strict, giving a length-two chain of primes. Sanity check: this length-two chain matches $\dim\mathbb{Z}[x]=2$; geometrically $\Spec\mathbb{Z}[x]$ is a two-dimensional ``arithmetic surface,'' with $(p,x)$ a closed point lying over the prime $p$ of $\mathbb{Z}$.
\end{wex}

\begin{proposition}[{the nilradical is an ideal}]
The set $\nil(A)=\{x\in A:x^{n}=0\text{ for some }n>0\}$ of all nilpotents is an ideal, and $A/\nil(A)$ has no nonzero nilpotent element \textup{(}it is \emph{reduced}\textup{)}.
\end{proposition}

\begin{theorem}[{nilradical $=$ intersection of all primes}]
$\nil(A)=\bigcap_{\fp\in\Spec A}\fp.$
\end{theorem}

\begin{definition}[{Jacobson radical}]
The \emph{Jacobson radical} $\Jac(A)$ is the intersection of all maximal ideals of $A$. Since maximal ideals are prime, $\nil(A)\subseteq\Jac(A)$ always.
\end{definition}

\begin{proposition}[{characterization of $\Jac(A)$}]
$x\in\Jac(A)\iff 1-xy\in\units{A}$ for all $y\in A$.
\end{proposition}

\begin{proof}[Idea]
($\Rightarrow$) If $1-xy$ were a nonunit it would lie in a maximal ideal $\fm$; but $x\in\fm$ too, so $1=(1-xy)+xy\in\fm$, absurd. ($\Leftarrow$) If $x\notin\fm$ for some maximal $\fm$, then $\fm+(x)=(1)$, so $u+xy=1$ for some $u\in\fm,\ y\in A$; then $1-xy=u\in\fm$ is a nonunit, contradicting the hypothesis.
\end{proof}

\begin{wex}{Nilpotents lift units}
If $x\in\nil(A)$, show $1-x$ is a unit, and more generally $u+x\in\units{A}$ for any unit $u$.
\wrec Nilpotents lie in $\Jac(A)$, and the Jacobson criterion gives $1-(\text{Jac})\cdot y$ a unit; or sum a finite geometric series.
\wsol If $x^{n}=0$ then $(1-x)(1+x+x^{2}+\cdots+x^{n-1})=1-x^{n}=1$, so $1-x$ is a unit. For a unit $u$, $u+x=u(1+u^{-1} x)$ and $u^{-1} x$ is nilpotent, so $1+u^{-1} x=1-(-u^{-1} x)$ is a unit, hence so is $u+x$. Sanity check: in $\mathbb{Z}/8\mathbb{Z}$, $x=2$ is nilpotent ($2^{3}=8=0$), so $1-2=-1=7$ is a unit ($7\cdot7=49=1$); consistent.
\end{wex}

\begin{definition}[{local and semilocal}]
A ring with exactly one maximal ideal $\fm$ is \emph{local}; the field $k=A/\fm$ is its \emph{residue field}. A ring with finitely many maximal ideals is \emph{semilocal}. In a local ring, $\Jac(A)=\fm$ and every element outside $\fm$ is a unit.
\end{definition}

\begin{proof}[Idea]
(i) Every proper ideal consists of nonunits, hence lies in $\fm$; so $\fm$ is the unique maximal ideal. The ``equivalently'': nonunits forming an ideal is exactly the hypothesis that $A\setminus(\text{that ideal})$ are units. (ii) For $x\notin\fm$, maximality gives $(x)+\fm=(1)$, so $xy+t=1$ with $t\in\fm$; then $xy=1-t\in1+\fm$ is a unit, so $x$ is a unit, and (i) applies.
\end{proof}

\begin{proposition}[{idempotents split the ring}]
$A$ has a nontrivial idempotent $e$ \textup{(}$e\neq0,1$, $e^{2}=e$\textup{)} iff $A\cong A_{1}\times A_{2}$ as a product of two nonzero rings; then $e=(1,0)$. In particular a local ring has no nontrivial idempotents \textup{(}$\Spec A$ is connected\textup{)}.
\end{proposition}

\begin{proof}[Idea]
Given $e$, set $e'=1-e$; then $ee'=0$ and $e+e'=1$, so $A\cong Ae\times Ae'$ with units $e,e'$. Conversely a product has the orthogonal idempotents $(1,0),(0,1)$. If $A$ is local with maximal $\fm$ and $e^{2}=e$, then $e(1-e)=0$; one of $e,1-e$ is outside $\fm$, hence a unit, forcing the other to be $0$.
\end{proof}

