\begin{wex}{A local ring recognized by its nonunits}
Show the formal power series ring $A=k[[t]]$ is local with maximal ideal $\fm=(t)$.
\wrec Use the recognition criterion: if everything outside $(t)$ is a unit, $A$ is local with maximal ideal $(t)$.
\wsol A series $f=\sum_{n\ge0}a_{n}t^{n}$ is a unit iff $a_{0}\neq0$: when $a_{0}\neq0$ one solves $fg=1$ recursively for the coefficients of $g$; when $a_{0}=0$, $f\in(t)$ is a nonunit. Thus the nonunits are exactly $(t)$, an ideal, so $A$ is local with $\fm=(t)$ and residue field $A/(t)\cong k$. Sanity check: $1-t\cdot y$ has constant term $1\neq0$ for every $y\in A$, hence is a unit, confirming $t\in\Jac(A)=(t)$ via the unit criterion.
\end{wex}

\begin{wex}{Idempotents and the structure of $\mathbb{Z}/12\mathbb{Z}$}
Find all idempotents of $\mathbb{Z}/12\mathbb{Z}$ and the corresponding product decomposition.
\wrec Idempotents correspond to ways of writing $\Spec$ as a disjoint union; by CRT they come from the prime-power factorization.
\wsol $12=4\cdot3$ with $\gcd(4,3)=1$, so CRT gives $\mathbb{Z}/12\mathbb{Z}\cong\mathbb{Z}/4\mathbb{Z}\times\mathbb{Z}/3\mathbb{Z}$. The idempotents of a product are coordinatewise idempotents; since $\mathbb{Z}/4\mathbb{Z}$ and $\mathbb{Z}/3\mathbb{Z}$ are local (only idempotents $0,1$), the idempotents are $(0,0),(1,0),(0,1),(1,1)$, i.e.\ $0,9,4,1$ in $\mathbb{Z}/12\mathbb{Z}$. The nontrivial pair $4,9$ gives $\mathbb{Z}/12\mathbb{Z}\cong 4A\times 9A\cong\mathbb{Z}/3\mathbb{Z}\times\mathbb{Z}/4\mathbb{Z}$. Sanity check: $4+9=13=1$ and $4\cdot9=36=0$, the defining orthogonality $e+e'=1,\ ee'=0$.
\end{wex}

\begin{proof}[Idea]
(vi) is the nilradical theorem applied in $A/\fa$: $r(\fa)/\fa=\nil(A/\fa)=\bigcap(\text{primes of }A/\fa)$, and primes of $A/\fa$ are primes of $A$ containing $\fa$ by the correspondence theorem. The rest are direct computations: e.g.\ for (ii), $x^{n}\in\fa\cap\fb$ for some $n$ iff $x^{m}\in\fa$ and $x^{k}\in\fb$ for some $m,k$, take $n=\max$.
\end{proof}

\begin{wex}{Computing a radical in $\mathbb{Z}$}
Compute $r((72))$ in $\mathbb{Z}$.
\wrec In $\mathbb{Z}$ the radical of $(n)$ is $(\mathrm{rad}\,n)$, the product of distinct primes dividing $n$; equivalently $r((n))=\bigcap_{p\mid n}(p)$.
\wsol $72=2^{3}\cdot3^{2}$, so the primes dividing $72$ are $2,3$, and $r((72))=(2)\cap(3)=(6)$. Indeed $x^{n}\in(72)$ for some $n$ iff $2\mid x$ and $3\mid x$, i.e.\ $6\mid x$. Sanity check: $6^{2}=36\notin(72)$ but $6^{3}=216=3\cdot72\in(72)$, so $6\in r((72))$; and $r((72))=(6)$ matches ``intersection of primes $(2),(3)$ containing $(72)$.''
\end{wex}

\begin{wex}{An ideal quotient $(\fa:\fb)$ in a polynomial ring}
In $A=k[x,y]$, compute $((x^{2},xy):(x))$.
\wrec $(\fa:\fb)=\{f:f\fb\subseteq\fa\}$; here we need $f$ with $fx\in(x^{2},xy)=x(x,y)$.
\wsol $fx\in x(x,y)$ means $fx=x\cdot g$ with $g\in(x,y)$; since $A$ is a domain we cancel $x$ to get $f=g\in(x,y)$. Conversely any $f\in(x,y)$ has $fx\in x(x,y)=(x^{2},xy)$. So $((x^{2},xy):(x))=(x,y)$. Sanity check: $(x,y)$ is the maximal ideal at the origin, and indeed $(x^{2},xy)=x\cdot(x,y)$ collapses upon dividing by $(x)$ to $(x,y)$, consistent with $(\fa:\fb)\supseteq\fa$ and here strictly larger.
\end{wex}

\begin{wex}{Coprime ideals: product equals intersection}
In $\mathbb{Z}$, verify $(4)\cap(9)=(4)(9)$ and contrast with $(4)\cap(6)$.
\wrec $\fa\fb=\fa\cap\fb$ precisely when $\fa+\fb=(1)$; check coprimality via $\gcd$.
\wsol $(4)+(9)=(\gcd(4,9))=(1)$, coprime, so $(4)\cap(9)=(\lcm(4,9))=(36)=(4)(9)$. By contrast $(4)+(6)=(2)\neq(1)$: here $(4)(6)=(24)$ but $(4)\cap(6)=(\lcm(4,6))=(12)\neq(24)$, so product $\subsetneq$ intersection. Sanity check: $(4)(6)=(24)\subseteq(12)=(4)\cap(6)$, the general inclusion $\fa\fb\subseteq\fa\cap\fb$, strict exactly because $4,6$ are not coprime.
\end{wex}

\begin{wex}{Radical of a sum need not be the sum of radicals}
In $A=k[x,y]$, let $\fa=(x^{2}-y),\ \fb=(y)$. Show $r(\fa)=\fa,\ r(\fb)=\fb$, but $r(\fa+\fb)\neq\fa+\fb$.
\wrec Use $r(\fa+\fb)=r(r(\fa)+r(\fb))$; the failure of $r(\fa+\fb)=\fa+\fb$ shows ``$r$ of a sum'' is subtle.
\wsol $\fa=(x^{2}-y)$ is prime (the quotient $k[x,y]/(x^{2}-y)\cong k[x]$ via $y\mapsto x^{2}$ is a domain), so $r(\fa)=\fa$; likewise $\fb=(y)$ is prime with $r(\fb)=\fb$. Now $\fa+\fb=(x^{2}-y,\,y)=(x^{2},\,y)$, whose radical is $r((x^{2},y))=(x,y)\neq(x^{2},y)$ since $x\in r$ but $x\notin(x^{2},y)$. Sanity check: $(x,y)=r((x^{2})+(y))=r(r(\fa)+r(\fb))$ exactly as the proposition predicts; geometrically $V(\fa)\cap V(\fb)$ is the single (fat) point at the origin, whose reduced ideal is $(x,y)$.
\end{wex}

\begin{definition}[{extension and contraction}]
For an ideal $\fa\subseteq A$, its \emph{extension} is $\fa^{e}=B f(\fa)$, the ideal of $B$ generated by $f(\fa)$. For an ideal $\fb\subseteq B$, its \emph{contraction} is $\fb^{c}=f^{-1}(\fb)$, always an ideal of $A$. One has $\fa\subseteq\fa^{ec}$, $\fb\supseteq\fb^{ce}$, and the idempotent identities $\fa^{e}=\fa^{ece}$, $\fb^{c}=\fb^{cec}$.
\end{definition}

\begin{proposition}[{contraction of a prime is prime}]
If $\fq\subseteq B$ is prime, then $\fq^{c}=f^{-1}(\fq)$ is prime in $A$. \textup{(}This is the well-definedness of the induced map $\Spec B\to\Spec A$, $\fq\mapsto f^{-1}(\fq)$.\textup{)} Extension of a prime, by contrast, need not be prime.
\end{proposition}

\begin{proof}[Idea]
$f$ induces an injection $A/\fq^{c}\hookrightarrow B/\fq$; since $B/\fq$ is a domain and a subring of a domain is a domain, $A/\fq^{c}$ is a domain, so $\fq^{c}$ is prime. Equivalently: $xy\in f^{-1}(\fq)\Rightarrow f(x)f(y)\in\fq\Rightarrow f(x)\in\fq$ or $f(y)\in\fq\Rightarrow x\in f^{-1}(\fq)$ or $y\in f^{-1}(\fq)$.
\end{proof}

\begin{proof}[Idea]
The map into $\prod A/\fa_{i}$ has kernel $\bigcap\fa_{i}$. Surjectivity reduces (by the standard interpolation) to hitting $(1,0,\dots,0)$: coprimality of $\fa_{1}$ with each $\fa_{j}$ ($j\neq1$) gives $u_{j}\in\fa_{1},\ v_{j}\in\fa_{j}$ with $u_{j}+v_{j}=1$; the product $\prod_{j\neq1}v_{j}\equiv1\pmod{\fa_{1}}$ and $\equiv0\pmod{\fa_{j}}$. Pairwise coprimality also forces $\bigcap\fa_{i}=\prod\fa_{i}$ by induction (using $\fa\cap\fb=\fa\fb$ when $\fa+\fb=(1)$, together with $\fa_{1}+\prod_{j\ge2}\fa_{j}=(1)$).
\end{proof}

\begin{wex}{CRT recovers $\mathbb{Z}/12\mathbb{Z}\cong\mathbb{Z}/4\mathbb{Z}\times\mathbb{Z}/3\mathbb{Z}$}
Apply CRT to $\fa_{1}=(4),\ \fa_{2}=(3)$ in $\mathbb{Z}$.
\wrec Coprime ideals $(4),(3)$ give $\mathbb{Z}/(4)\cap(3)\cong\mathbb{Z}/(4)\times\mathbb{Z}/(3)$, with $\bigcap=\prod$.
\wsol $(4)+(3)=(\gcd(4,3))=(1)$, coprime. So $(4)\cap(3)=(4)(3)=(12)$ and $\mathbb{Z}/12\mathbb{Z}\cong\mathbb{Z}/4\mathbb{Z}\times\mathbb{Z}/3\mathbb{Z}$. The idempotent $(1,0)$ pulls back to $9$ (since $9\equiv1\bmod4,\ 9\equiv0\bmod3$) and $(0,1)$ to $4$. Sanity check: $\abs{\mathbb{Z}/12\mathbb{Z}}=12=4\cdot3=\abs{\mathbb{Z}/4\mathbb{Z}\times\mathbb{Z}/3\mathbb{Z}}$, and the idempotents $4,9$ found here match the structure computation done earlier.
\end{wex}

\begin{wex}{Contraction of primes under $\mathbb{Z}\hookrightarrow\mathbb{Z}[i]$}
Identify the contraction to $\mathbb{Z}$ of a prime $\fq\subseteq\mathbb{Z}[i]$, and check $\fq^{c}$ is prime.
\wrec Contraction of a prime is prime; for $\mathbb{Z}\hookrightarrow\mathbb{Z}[i]$ the contraction of $\fq$ is $\fq\cap\mathbb{Z}=(p)$ for the rational prime $p$ below $\fq$.
\wsol $\mathbb{Z}[i]$ is a PID; its primes lying over a rational prime $p$ are: $(1+i)$ over $2$ (ramified), the two conjugate primes $(\pi),(\overline{\pi})$ with $\pi\overline{\pi}=p$ over $p\equiv1\pmod4$ (split), and $(p)$ itself over $p\equiv3\pmod4$ (inert). In each case $\fq\cap\mathbb{Z}=(p)$, a prime of $\mathbb{Z}$. For instance $(1+i)\cap\mathbb{Z}=(2)$ since $(1+i)^{2}=2i$ gives $2\in(1+i)$, while $1\notin(1+i)$. Sanity check: $\mathbb{Z}/(2)\hookrightarrow\mathbb{Z}[i]/(1+i)$; the latter is $\F_{2}$ (since $\abs{\mathbb{Z}[i]/(1+i)}=N(1+i)=2$), a field, and $\mathbb{Z}/(2)=\F_{2}$ injects into it -- a domain inside a domain, confirming $\fq^{c}=(2)$ is prime.
\end{wex}

\begin{wex}{Extension of a prime need not be prime}
With $f:\mathbb{Z}\hookrightarrow\mathbb{Z}[i]$, show $(5)^{e}=(5)\mathbb{Z}[i]$ is not prime, though $(5)$ is prime in $\mathbb{Z}$.
\wrec Extension is generated by the image; whether it stays prime is governed by how $5$ factors upstairs.
\wsol In $\mathbb{Z}[i]$, $5=(2+i)(2-i)$ with $2\pm i$ non-associate primes. So $(5)^{e}=(2+i)(2-i)$ is a product of two distinct primes, hence not prime: $(2+i)(2-i)\in(5)^{e}$ yet neither factor lies in $(5)^{e}$ (each generates a strictly larger prime). Sanity check: $\mathbb{Z}[i]/(5)\cong\mathbb{Z}[i]/(2+i)\times\mathbb{Z}[i]/(2-i)\cong\F_{5}\times\F_{5}$ by CRT, which has zero-divisors $(1,0),(0,1)$, so $(5)^{e}$ is not prime -- the ``split prime'' phenomenon.
\end{wex}

\begin{wex}{$\fa\subseteq\fa^{ec}$ can be strict}
Let $f:\mathbb{Z}\to\mathbb{Q}$ be the inclusion. Compute $\fa^{e}$ and $\fa^{ec}$ for $\fa=(2)$.
\wrec Extension into a field collapses any proper nonzero ideal to $(1)$; contraction of $(1)$ is $(1)$.
\wsol $\fa^{e}=(2)\mathbb{Q}=\mathbb{Q}=(1)$ since $2$ is a unit in $\mathbb{Q}$. Then $\fa^{ec}=f^{-1}(\mathbb{Q})=\mathbb{Z}=(1)$. So $\fa=(2)\subsetneq(1)=\fa^{ec}$, a strict inclusion. Sanity check: geometrically $\Spec\mathbb{Q}\to\Spec\mathbb{Z}$ hits only the generic point $(0)$, so the prime $(2)$ has empty preimage and its extension ``sees nothing,'' consistent with $(2)^{e}=(1)$ being the unit ideal.
\end{wex}

\begin{proof}[Idea]
Each identity is a direct unwinding of ``$\fp\supseteq\,$''. For the union: $\fp\supseteq\fa\fb$ and $\fp$ prime force $\fp\supseteq\fa$ or $\fp\supseteq\fb$. For the radical: $\fp\supseteq\fa\iff\fp\supseteq r(\fa)$ because $r(\fa)=\bigcap_{\fp\supseteq\fa}\fp$.
\end{proof}

\begin{wex}{$V$ of the two coordinate axes}
In $A=k[x,y]$, describe $V((xy))$ and relate it to $V((x))$ and $V((y))$.
\wrec $V(\fa\fb)=V(\fa)\cup V(\fb)$; the ideal $(xy)=(x)(y)$ should give the union of the two axes.
\wsol $V((xy))=V((x)(y))=V((x))\cup V((y))$. The closed set $V((x))$ consists of primes containing $x$ -- geometrically the line $x=0$ (the $y$-axis), with generic point $(x)$ and closed points $(x,y-b)$; similarly $V((y))$ is the $x$-axis. So $V((xy))$ is the union of the two axes. Sanity check: $(xy)$ is not prime (it is not radical-prime: $r((xy))=(xy)$ here, but $(xy)$ fails primeness since $x\cdot y\in(xy)$ with $x,y\notin(xy)$), matching that $V((xy))$ is reducible -- a union of two irreducible components.
\end{wex}

\begin{wex}{Irreducible closed sets are $V(\fp)$ for $\fp$ prime}
Show that $V(\fa)$ is irreducible \textup{(}nonempty and not a union of two proper closed subsets\textup{)} iff $r(\fa)$ is prime; in particular $V(\fp)$ is irreducible for every prime $\fp$, and $\overline{\{\fp\}}=V(\fp)$.
\wrec Irreducibility of $V(\fa)$ corresponds to $r(\fa)$ being prime; the closure of a point $\fp$ is the smallest $V$ containing it.
\wsol The closure of $\{\fp\}$ is the intersection of all closed sets containing $\fp$, namely $V(\fp)$ itself (the smallest $V(\fa)$ with $\fp\in V(\fa)$ is $V(\fp)$). If $\fp$ is prime and $V(\fp)=V(\fb)\cup V(\fc)=V(\fb\fc)$, then $r(\fb\fc)=r(\fp)=\fp$, so $\fp\supseteq\fb\fc$, forcing $\fp\supseteq\fb$ or $\fp\supseteq\fc$, i.e.\ one piece is all of $V(\fp)$; since $V(\fa)=V(r(\fa))$, this covers every $\fa$ with $r(\fa)$ prime. Conversely, if $r(\fa)$ is not prime, then either $r(\fa)=(1)$ and $V(\fa)=\varnothing$, or there are $x,y\notin r(\fa)$ with $xy\in r(\fa)$; then $V(\fa)=V(\fa+(x))\cup V(\fa+(y))$ (a prime containing $\fa$ contains $xy$, hence $x$ or $y$), and both pieces are proper since $x,y\notin r(\fa)=\bigcap_{\fp\supseteq\fa}\fp$. Sanity check: the generic point $(0)$ of $\Spec\mathbb{Z}$ has closure $V((0))=\Spec\mathbb{Z}$ -- it is dense -- exactly because $(0)$ is the minimal prime of the domain $\mathbb{Z}$, the geometric counterpart of ``$\Spec$ of a domain is irreducible.''
\end{wex}

\begin{wex}{Closed points are the maximal ideals}
Show $\{\fp\}$ is closed in $\Spec A$ iff $\fp$ is maximal.
\wrec $\overline{\{\fp\}}=V(\fp)$, which is a single point iff no prime strictly contains $\fp$.
\wsol $\{\fp\}$ is closed iff $V(\fp)=\{\fp\}$, i.e.\ iff the only prime containing $\fp$ is $\fp$ itself; that is exactly maximality of $\fp$ (any proper containment would land in some maximal ideal $\supsetneq\fp$). Sanity check: in $\Spec\mathbb{Z}$ the closed points are the $(p)$ (maximal), while $(0)$ is not closed -- its closure is the whole line -- recovering ``maximal ideal $=$ classical point, prime ideal $=$ irreducible subvariety / generic point.''
\end{wex}

