The Nullstellensatz requires $E$ \emph{algebraically closed}. Over $\mathbb{R}$ or $\mathbb{Q}$ it fails: $(x^2+1)$ is its own radical yet $I(V(x^2+1))=\mathbb{R}[x]
e(x^2+1)$. Also, $V( a)
e\varnothing$ for proper $ a$ uses algebraic closure: the weak Nullstellensatz gives a common zero precisely because $ad a
e(1)$.
\end{pitfall}

\begin{wex}{Reading off components via the Nullstellensatz}
Over $\mathbb{C}$, find the irreducible components of $V(xz,yz)\subseteq\Aff^3$.
\wrec Components $\leftrightarrow$ minimal primes over $\rad(xz,yz)$; compute the radical and factor it as an intersection of primes.
\wsol $(xz,yz)=(z)\cap(x,y)$: a polynomial vanishing wherever $z=0$ or $x=y=0$ lies in this intersection, and both $(z)$ and $(x,y)$ are prime. The ideal is already radical (intersection of primes), with minimal primes $(z)$ and $(x,y)$, which are incomparable. So $V(xz,yz)=V(z)\cup V(x,y)$ is the union of the plane $z=0$ and the $z$-axis. Sanity check: the $z=0$ plane has dimension $2$ and the $z$-axis dimension $1$; they are the two components, meeting in the origin -- an embedded incidence but two genuine top-level components since neither prime contains the other.
\end{wex}

\begin{wex}{Radical membership decides vanishing}
Over $\mathbb{C}$, does $g=x^2y$ vanish on $V(\fa)$ for $\fa=(x^3,\,xy^2)$? Compute $I(V(\fa))$.
\wrec By the Nullstellensatz $g$ vanishes on $V(\fa)$ iff $g\in\rad\fa$; find $\rad\fa$ as an intersection of primes.
\wsol $V(\fa)=V(x^3)\cap V(xy^2)=V(x)$, the $y$-axis (the line $x=0$ in $\Aff^2$). So $I(V(\fa))=I(V(x))=(x)=\rad\fa$ (indeed $x\in\rad\fa$ since $x^3\in\fa$). Now $g=x^2y\in(x)$, so $g$ vanishes on $V(\fa)$. Sanity check: directly, every point of $V(\fa)$ has $x=0$, so $x^2y=0$ there; and $\rad(x^3,xy^2)=(x)$ because $x^3\in\fa$ gives $x\in\rad\fa$, while $\fa\subseteq(x)$ gives $\rad\fa\subseteq\rad(x)=(x)$.
\end{wex}

\begin{wex}{Maximal ideals are points over $\mathbb{C}$}
Over $\mathbb{C}$, identify the maximal ideals of $\mathbb{C}[x,y]$ and the corresponding algebraic sets.
\wrec The weak Nullstellensatz: every maximal ideal of $E[x_1,\dots,x_n]$ with $E=\overline E$ is $\fm_P=(x_1-a_1,\dots,x_n-a_n)$.
\wsol Each point $P=(a,b)\in\Aff^2_\mathbb{C}$ gives the maximal ideal $\fm_P=(x-a,y-b)$ with $\mathbb{C}[x,y]/\fm_P\cong\mathbb{C}$, and $V(\fm_P)=\{P\}$. Conversely every maximal ideal arises this way, so maximal ideals $\leftrightarrow$ points bijectively. Sanity check: this is the bottom row of the dictionary square; over $\mathbb{R}$ it fails, since $(x^2+1)\subseteq\mathbb{R}[x]$ is maximal but is no point's ideal -- a maximal ideal with empty zero set, impossible over $\mathbb{C}$.
\end{wex}

\begin{wex}{The radical ideal $\leftrightarrow$ algebraic set bijection in action}
Over $\mathbb{C}$, verify $V$ and $I$ are inverse on $\fa=(x^2-y)$ and on the set $A=V(\fa)$.
\wrec Check $I(V(\fa))=\rad\fa$ and $V(I(A))=A$ for a specific prime (hence radical) ideal.
\wsol $x^2-y$ is irreducible, so $(x^2-y)$ is prime, hence radical, and $A=V(x^2-y)$ is the parabola $y=x^2$. Then $I(A)=(x^2-y)$ by the Nullstellensatz (it equals $\rad(x^2-y)=(x^2-y)$), and $V(I(A))=V(x^2-y)=A$. Sanity check: $(x^2-y)$ prime $\Rightarrow A$ a variety; the round trips $\fa\mapsto V(\fa)\mapsto I(V(\fa))=\fa$ and $A\mapsto I(A)\mapsto V(I(A))=A$ both close, exactly the bijection the Nullstellensatz asserts.
\end{wex}

Prove that $\fq \subset \fp$, i.e., there are nonzero prime ideals properly contained in $\fp$.
\end{enumerate}

\item Let $A$ be any ideal in $R = k[x_1, \ldots, x_n, y_1, \ldots, y_m]$.
\begin{enumerate}
\item[(a)] Show that $\rad(A \cap k[y_1, \ldots, y_m]) = \rad A \cap k[y_1, \ldots, y_m]$.
\item[(b)] Suppose $(f_1, \ldots, f_s)$ is an ideal in $k[x_1, \ldots, x_n]$. Let $F_1, \ldots, F_t$ be generators for the radical of $(f_1, \ldots, f_s)$, computed in $k[x_1, \ldots, x_n]$. Suppose $J$ is an ideal in $R$ and let $A = J + (f_1, \ldots, f_s)$, $B = J + (F_1, \ldots, F_t)$ as ideals in $R$. Prove that $\rad A = \rad B$.
\item[(c)] Conclude from (a) and (b) that $A = (y_1 - x_1, \ldots, y_m - x_m, f_1, \ldots, f_s) \cap k[y_1, \ldots, y_m]$ and $B = (y_1 - x_1, \ldots, y_m - x_m, F_1, \ldots, F_t) \cap k[y_1, \ldots, y_m]$ have the same zero sets over an algebraically closed field $k$. [Use Hilbert's Nullstellensatz.]
\end{enumerate}

\item Determine the Zariski closure in $\mathbb{C}^3$ of the points on the curve $\{(a^2, a^3, a^4) \mid a \in \mathbb{C}\}$.

\item Show that $\mathcal{Z}(x^3 - xyz + z^2)$ is the smallest algebraic set in $\mathbb{R}^3$ containing the points $\{(st, s + t, s^2 t) \mid s, t \in \mathbb{R}\}$.

\item Show that $\mathcal{Z}(x^3 z^2 - 3xy^2 z^2 - y^6 - z^4)$ is the smallest algebraic set in $\mathbb{R}^3$ containing the points $\{(s^2 + t^2, st, s^3) \mid s, t \in \mathbb{R}\}$.

\item Find equations defining the Zariski closure of the set of points $\{(s^4, s^3 t, st^3, t^4) \mid s, t \in \mathbb{R}\}$.

\item Show that $V = \mathcal{Z}(x^2 - y^2 z)$ (the \emph{Whitney umbrella} surface) is the smallest algebraic set in $\mathbb{R}^3$ containing the points $S = \{(st, s, t^2) \mid s, t \in \mathbb{R}\}$. Show that $S$ is not Zariski closed in $V$ (the missing points explain the name for the surface). Do the same over $\mathbb{C}$, but show that in this case $S = V$ is closed.

\item Let $V = \mathcal{Z}(xz^2 - w^3, \; xw^2 - y^4, \; y^4 z^2 - w^5) \subseteq \mathbb{C}^4$. Determine the Zariski closure of the image of $V$ under the projection $\pi((x, y, z, w)) = (x, y, z)$.

\item Let $V = \mathcal{Z}(xy - 1)$ in $\Aff^2$ and let $S$ be the projection of $V$ onto the $x$-axis in $\Aff^1$.
\begin{enumerate}
\item[(a)] If $k = \mathbb{R}$, show that $\mathcal{I}(V) = (xy - 1) \subseteq \mathbb{R}[x, y]$ and that $(u - x, xy - 1) \cap \mathbb{R}[u] = 0$ in $\mathbb{R}[x, y, u]$. Use Propositions 8 and 16 to conclude that the Zariski closure of $S$ is $\Aff^1$ and show that $S$ is not itself closed.
\item[(b)] If $k = \F_3$, show that $\mathcal{I}(V) = (xy - 1, x^3 - x, y^3 - y) \subseteq \F_3[x, y]$ and that $(u - x, xy - 1, x^3 - x, y^3 - y) \cap \F_3[u] = (u^2 - 1)$ in $\F_3[x, y, u]$. Use Propositions 8 and 16 to conclude that $S$ is Zariski closed in $\Aff^1$.
\end{enumerate}

\item Recall the ideal quotient $(I : J) = \{r \in R \mid rJ \subseteq I\}$ of two ideals $I, J$ in a ring $R$ (cf. Exercise 34 ff. in Section 9.6). Clearly $I \subseteq (I : J)$.
\begin{enumerate}
\item[(a)] Show that $\mathcal{Z}(I) - \mathcal{Z}(J)$, the set of elements of $\mathcal{Z}(I)$ not lying in $\mathcal{Z}(J)$, is contained in $\mathcal{Z}((I : J))$ and conclude that the Zariski closure of $\mathcal{Z}(I) - \mathcal{Z}(J)$ is contained in $\mathcal{Z}((I : J))$.
\item[(b)] Show that if $k$ is algebraically closed and $I$ is a radical ideal then $\mathcal{Z}((I : J))$ is precisely the Zariski closure of $\mathcal{Z}(I) - \mathcal{Z}(J)$.
\item[(c)] Show that if $V$ and $W$ are affine algebraic sets then $(\mathcal{I}(V) : \mathcal{I}(W)) = \mathcal{I}(V - W)$.
\end{enumerate}
\end{exers}

\begin{remark}
The endomorphism-ring viewpoint is the conceptual core. A module is a ring acting on an abelian group; a representation of $A$. When $A=k[G]$ is the group ring of a finite group $G$ over a field $k$, an $A$-module is exactly a $k$-linear representation of $G$ -- so representation theory is a chapter of module theory. When $A=k[x]$, an $A$-module is a $k$-vector space equipped with a single distinguished endomorphism (the action of $x$); the structure theory of such modules is the theory of rational/Jordan canonical forms in D\&F Chapter 12.
\end{remark}

\begin{definition}[{submodule, quotient, homomorphism}]
A \emph{submodule} $M'\subseteq M$ is a subgroup closed under the $A$-action; the quotient group $M/M'$ then inherits an $A$-action $a(x+M')=ax+M'$ and is the \emph{quotient module}. An \emph{$A$-module homomorphism} (or $A$-linear map) $f:M\to N$ is an additive map with $f(ax)=a\,f(x)$ for all $a\in A$, $x\in M$. Its \emph{kernel} $\ker f=\{x:f(x)=0\}$ is a submodule of $M$, its \emph{image} $\im f=f(M)$ a submodule of $N$, and its \emph{cokernel} $\coker f=N/\im f$ a quotient of $N$. The set $\Hom_A(M,N)$ of all $A$-linear maps is itself an $A$-module under $(f+g)(x)=f(x)+g(x)$ and $(af)(x)=a\,f(x)$.
\end{definition}

\begin{method}{Building and recognizing modules}
To produce an $A$-module: take an abelian group on which $A$ acts, or a quotient/submodule/$\Hom$/direct sum of known modules. To recognize the action concretely, find the ring homomorphism $A\to\End(M)$. To verify a subset is a submodule, check it is a nonempty subgroup stable under multiplication by every $a\in A$ (it suffices to test the scalars in a ring-generating set of $A$, since stability propagates through sums and products of scalars; testing only the module generators is \emph{not} enough -- stability is required for all scalars).
\end{method}

\begin{wex}{The annihilator and faithful modules}
Define $\Ann(M)$ and show $M$ is naturally a faithful module over $A/\Ann(M)$.
\wrec The annihilator $\Ann(M)=\{a\in A:aM=0\}$ measures ``how much of $A$ acts trivially''; quotienting it out makes the action faithful.
\wsol $\Ann(M)=\{a\in A:ax=0\ \forall x\in M\}$ is an ideal: if $a,b$ kill $M$ so does $a-b$, and if $a$ kills $M$ then so does $ca$ for any $c$. The action factors through $A/\Ann(M)$ because $a\in\Ann(M)$ acts as $0$; the induced module is \emph{faithful}, meaning $\Ann_{A/\Ann(M)}(M)=0$, since by construction nothing outside $\Ann(M)$ kills all of $M$. Sanity check: for $M=\mathbb{Z}/n\mathbb{Z}$ over $A=\mathbb{Z}$ we get $\Ann(M)=n\mathbb{Z}$ and $M$ is faithful over $\mathbb{Z}/n\mathbb{Z}$; for a finite-dimensional $k[x]$-module, $\Ann(M)=(m(x))$ is generated by the minimal polynomial.
\end{wex}

\begin{wex}{$\Hom$ functoriality}
For $u:M'\to M$ and $v:N\to N''$, describe the induced maps on $\Hom$ and their variance.
\wrec $\Hom_A(-,N)$ is contravariant and $\Hom_A(M,-)$ is covariant; precomposition reverses arrows, postcomposition preserves them.
\wsol Given $u:M'\to M$, define $\bar u:\Hom_A(M,N)\to\Hom_A(M',N)$ by $\bar u(f)=f\circ u$ (contravariant). Given $v:N\to N''$, define $\bar v:\Hom_A(M,N)\to\Hom_A(M,N'')$ by $\bar v(f)=v\circ f$ (covariant). Both are $A$-linear. Sanity check: identities go to identities and $\overline{u_1u_2}=\bar u_2\bar u_1$ (order reversed) while $\overline{v_1v_2}=\bar v_1\bar v_2$ (order preserved), the signature of contra- vs.\ covariance.
\end{wex}

\begin{proof}[Idea]
These are pure diagram chases. For the first: a map $M''\to N$ pulls back along $v$ to a map $M\to N$ killing $\im u=\ker v$, and conversely a map $M\to N$ that kills $\ker v$ descends through the surjection $v$. Injectivity of $\bar v$ is surjectivity of $v$; exactness in the middle is $\im u=\ker v$. Note the right end is \emph{not} surjective in general: not every $M'\to N$ extends. So $\Hom$ is only \emph{left}-exact -- the failure of right-exactness is measured by the $\Ext$ functors.
\end{proof}

\begin{proof}[Idea]
Atiyah--Macdonald's Proposition 2.10 is exactly this for the truncated version (rows $0\to M'\to M\to M''\to0$). The map $\delta$ is built by the only route the diagram allows: take $x''\in\ker f''$; lift it to $x\in M$ via the surjection $v$; then $f(x)$ maps to $f''(x'')=0$ in $N''$, so $f(x)=u'(y')$ for a unique $y'\in N'$; set $\delta(x'')=y'+\im f'$. ``Well-defined and exact'' is the canonical diagram chase. The snake is the engine behind every long exact sequence in homological algebra.
\end{proof}

\begin{wex}{Additive functions on short exact sequences}
Let $\lambda$ be a $\mathbb{Z}$-valued function on a class $\mathcal C$ of modules, additive on short exact sequences whose terms lie in $\mathcal C$. Prove $\sum_{i=0}^{n}(-1)^i\lambda(M_i)=0$ for an exact sequence $0\to M_0\to\cdots\to M_n\to0$ in which all the $M_i$ and all the kernels of the maps lie in $\mathcal C$.
\wrec Additivity means $\lambda(M)=\lambda(M')+\lambda(M'')$ for $0\to M'\to M\to M''\to0$; this is the abstract Euler characteristic / dimension count.
\wsol Splice into short exact sequences $0\to N_{i-1}\to M_i\to N_i\to0$ with $N_{-1}=0=N_n$ (A\&M Prop.\ 2.11). Additivity gives $\lambda(M_i)=\lambda(N_{i-1})+\lambda(N_i)$. Form $\sum(-1)^i\lambda(M_i)=\sum(-1)^i\bigl(\lambda(N_{i-1})+\lambda(N_i)\bigr)$; the $N$-terms telescope and cancel because each $N_i$ appears once with sign $(-1)^i$ and once with $(-1)^{i+1}$, leaving $0$. Sanity check: for $0\to M'\to M\to M''\to0$ this is just additivity; for finite-dimensional $k$-vector spaces $\lambda=\dim$ recovers rank--nullity $\dim M=\dim\ker+\dim\im$.
\end{wex}

\begin{definition}[{direct sum and product}]
For a family $(M_i)_{i\in I}$ of $A$-modules, the \emph{direct product} $\prod_{i\in I}M_i$ is the set of all families $(x_i)$ with the componentwise operations; the \emph{direct sum} $\bigoplus_{i\in I}M_i$ is the submodule of families $(x_i)$ with $x_i=0$ for all but finitely many $i$. For finite $I$ the two coincide. A \emph{free} module is one isomorphic to $\bigoplus_{i\in I}A$, written $A^{(I)}$; the finite free modules are $A^n$.
\end{definition}

\begin{wex}{$\Hom$ and direct sums vs.\ products}
Establish $\Hom_A\bigl(\bigoplus_i M_i,N\bigr)\cong\prod_i\Hom_A(M_i,N)$ and $\Hom_A\bigl(N,\prod_i M_i\bigr)\cong\prod_i\Hom_A(N,M_i)$.
\wrec A map out of a direct sum is a tuple of maps on the summands (universal property of $\oplus$); a map into a product is a tuple of maps to the factors (universal property of $\prod$).
\wsol For the first, restrict $f:\bigoplus M_i\to N$ to each summand to get $(f|_{M_i})_i$; conversely glue $(f_i)$ by $f((x_i))=\sum_i f_i(x_i)$ -- a \emph{finite} sum since $(x_i)\in\bigoplus$. These are mutually inverse $A$-isomorphisms. For the second, post-compose $g:N\to\prod M_i$ with the projections $\pi_i$ to get $(\pi_i g)_i$; conversely assemble. Sanity check: with $M_i=A$ for $i\in I$ we get $\Hom_A(A^{(I)},N)\cong N^I=\prod_I N$, the ``dual of free is product'' statement; for finite $I$ both sides are $N^{|I|}$.
\end{wex}

\begin{wex}{Quotient of $A$ by an ideal as a sum decomposition (CRT)}
For coprime ideals show $A/(\fa\cap\fb)\cong A/\fa\oplus A/\fb$ as $A$-modules.
\wrec When $\fa+\fb=A$ the Chinese Remainder map is an isomorphism; this is a module (indeed ring) decomposition.
\wsol The map $A\to A/\fa\oplus A/\fb$, $x\mapsto(x+\fa,x+\fb)$, is $A$-linear with kernel $\fa\cap\fb$. Coprimality $\fa+\fb=A$ gives surjectivity (pick $e\in\fa$, $f\in\fb$ with $e+f=1$; then $f\equiv1,\ e\equiv0\pmod{\fa}$ and vice versa, so any target $(\bar s,\bar t)$ is hit by $sf+te$). Hence $A/(\fa\cap\fb)\cong A/\fa\oplus A/\fb$, and $\fa\cap\fb=\fa\fb$ in this case. Sanity check: $A=\mathbb{Z}$, $\fa=3\mathbb{Z}$, $\fb=5\mathbb{Z}$ gives $\mathbb{Z}/15\cong\mathbb{Z}/3\oplus\mathbb{Z}/5$, the classical CRT, an isomorphism of $\mathbb{Z}$-modules of order $15$.
\end{wex}

\begin{wex}{Free of rank determined: $A^m\cong A^n\Rightarrow m=n$}
Show that over a nonzero commutative ring, free modules have a well-defined rank.
\wrec Pass to a residue field: tensoring (or quotienting) by a maximal ideal turns $A^n$ into a vector space of dimension $n$, and dimension is an invariant.
\wsol Let $\fm$ be a maximal ideal of $A$, $k=A/\fm$. An isomorphism $A^m\cong A^n$ induces, after reducing mod $\fm$ (i.e.\ applying $A/\fm\otimes_A-$, see below), an isomorphism of $k$-vector spaces $k^m\cong k^n$. Hence $m=\dim_k k^m=\dim_k k^n=n$. Sanity check: the argument needs $A\neq0$ so that a maximal ideal exists; over the zero ring $A^m=0=A^n$ for all $m,n$ and rank is meaningless, consistent with the hypothesis.
\end{wex}

\begin{proof}[Idea]
Pick generators $x_1,\dots,x_n$ of $M$. Since $\phi(x_i)\in\fa M$, write $\phi(x_i)=\sum_j a_{ij}x_j$ with $a_{ij}\in\fa$. Then $\sum_j(\delta_{ij}\phi-a_{ij})x_j=0$, i.e.\ the matrix $\Phi=(\delta_{ij}\phi-a_{ij})$ over the commutative ring $A[\phi]$ kills the vector $(x_1,\dots,x_n)$. Multiply by the adjugate: $\operatorname{adj}(\Phi)\Phi=\det(\Phi)\cdot I$, so $\det(\delta_{ij}\phi-a_{ij})$ annihilates every $x_j$, hence all of $M$. Expanding the determinant gives the monic equation with coefficients in $\fa$. This is literally Cayley--Hamilton with entries in $A[\phi]$.
\end{proof}

\begin{corollary}[{A\&M 2.5}]
If $M$ is f.g.\ and $\fa M=M$ for an ideal $\fa$, then there exists $x\equiv1\pmod{\fa}$ (i.e.\ $x=1+a$, $a\in\fa$) with $xM=0$.
\end{corollary}

\begin{theorem}[{Nakayama's lemma}]
Let $M$ be a finitely generated $A$-module and $\fa\subseteq\Jac(A)$ an ideal contained in the Jacobson radical. If $\fa M=M$ then $M=0$.
\end{theorem}

\begin{proof}[Idea]
By the corollary there is $x=1+a$ with $a\in\fa\subseteq\Jac(A)$ and $xM=0$. But $\Jac(A)$ is characterized as $\{a:1+ab\in\units{A}\ \forall b\}$, so $x=1+a$ is a unit. Multiplying $xM=0$ by $x^{-1}$ gives $M=0$. The finite-generation hypothesis is essential (see the pitfall).
\end{proof}

\begin{proof}[Idea]
(1) Apply Nakayama to $M/N$, which is f.g.\ with $\fm(M/N)=M/N$, forcing $M/N=0$. (2) The $\bar x_i$ span $M/\fm M$ iff $\sum Ax_i+\fm M=M$ iff (by (1)) $\sum Ax_i=M$; and a spanning set of the vector space $M/\fm M$ is a basis iff it is minimal. The point: \emph{over a local ring, counting minimal generators of a f.g.\ module is linear algebra over the residue field.}
\end{proof}

\begin{pitfall}
Nakayama fails without finite generation. Take $A=\mathbb{Z}_{(p)}$ (local, $\fm=p\mathbb{Z}_{(p)}$) and $M=\mathbb{Q}$. Then $\fm M=p\mathbb{Q}=\mathbb{Q}=M$ but $M\neq0$. The determinant trick needs a \emph{finite} generating set to form the matrix; $\mathbb{Q}$ is not finitely generated over $\mathbb{Z}_{(p)}$. Likewise the hypothesis $\fa\subseteq\Jac(A)$ cannot be dropped: $\fa=A$ trivially has $\fa M=M$ for every $M$.
\end{pitfall}

\begin{wex}{Cayley--Hamilton recovered}
Recover the classical Cayley--Hamilton theorem from A\&M 2.4.
\wrec Take $A=$ the base ring, $M=A^n$ free with the standard basis, $\fa=A$, and $\phi$ a given matrix; the trick produces the characteristic-polynomial equation.
\wsol Let $T\in\Mat_n(A)$ act on $M=A^n$. With $\fa=A$ and generators the standard basis, the matrix in the proof is $tI-T$ evaluated at $t=\phi=T$, and $\det(tI-T)=\chi_T(t)$ is the characteristic polynomial. The determinant trick gives $\chi_T(T)=0$. Sanity check: for $n=1$, $T=(a)$, $\chi_T(t)=t-a$ and $\chi_T(T)=T-aI=0$; the general statement is exactly Cayley--Hamilton.
\end{wex}

\begin{wex}{Surjective endomorphism of a f.g.\ module is injective}
Show every surjective $A$-endomorphism $\phi$ of a finitely generated $A$-module $M$ is an isomorphism.
\wrec View $M$ as a module over $B=A[t]$ with $t$ acting as $\phi$; surjectivity says $tM=M$ over the ideal $(t)$, and a Nakayama-style argument applies.
\wsol Regard $M$ as an $A[t]$-module via $t\cdot x=\phi(x)$; $M$ is f.g.\ over $A[t]$ (already over $A$). Surjectivity of $\phi$ means $(t)M=M$ where $(t)\subseteq A[t]$. By the determinant trick (A\&M 2.4 with $\fa=(t)$ and the identity endomorphism) there is $x=1+t\,h(t)$ with $xM=0$, i.e.\ $\bigl(1+t\,h(t)\bigr)M=0$. Reading off in terms of $\phi$: $\id=-\phi\,h(\phi)$ on $M$, so $\phi$ has the two-sided inverse $-h(\phi)$, hence is injective and an isomorphism. Sanity check: this fails for non-f.g.\ modules -- the shift $\phi(a_0,a_1,\dots)=(a_1,a_2,\dots)$ on $A^{(\Zpos)}$ is surjective but not injective.
\end{wex}

\begin{wex}{Minimal generators of a module over a local ring}
Let $A=k[x,y]_{(x,y)}$, $\fm=(x,y)$, and $M=\fm$. Compute the minimal number of generators of $M$.
\wrec Over a local ring this number is $\dim_k M/\fm M$ by the local Nakayama corollary.
\wsol Here $M=\fm=(x,y)$ and $\fm M=\fm^2=(x^2,xy,y^2)$. So $M/\fm M=\fm/\fm^2$ has $k$-basis the images of $x,y$, giving $\dim_k\fm/\fm^2=2$. Hence the minimal number of generators of $\fm$ is $2$, realized by $\{x,y\}$. Sanity check: any single element $f\in\fm$ has $f\in\fm^2+kx+ky$ but cannot span $\fm/\fm^2$ (dimension $2$), so $\fm$ is not principal -- correctly, the maximal ideal of a $2$-dimensional regular local ring needs exactly $2$ generators.
\end{wex}

\begin{wex}{$N+\fm M=M\Rightarrow N=M$ in practice}
With $A=\mathbb{Z}_{(2)}$, $M=A^2$, $N=A\cdot(1,1)+A\cdot(0,2)$, decide whether $N=M$.
\wrec Reduce mod $\fm=2A$: $N=M$ iff the images of the generators span $M/\fm M=k^2$, $k=\F_2$.
\wsol Mod $2$, the generators become $(1,1)$ and $(0,0)$, spanning only a $1$-dimensional subspace of $\F_2^2$. So $N+\fm M\neq M$, and indeed $N\neq M$ (e.g.\ $(1,0)\notin N$, since $a(1,1)+b(0,2)=(a,a+2b)=(1,0)$ forces $a=1$, $1+2b=0$, impossible in $\mathbb{Z}_{(2)}$). Sanity check: had we used $(1,1)$ and $(0,1)$, the reductions $(1,1),(0,1)$ span $\F_2^2$, and then Nakayama gives $N=M$ -- which one verifies directly since $(1,0)=(1,1)-(0,1)\in N$.
\end{wex}

\begin{theorem}[{tensor product, A\&M 2.12}]
There is a pair $(T,g)$ -- an $A$-module $T=M\otimes_A N$ and an $A$-bilinear map $g:M\times N\to T$, $g(x,y)=x\otimes y$ -- with the universal property: for every $A$-module $P$ and every $A$-bilinear $f:M\times N\to P$ there is a unique $A$-linear $f':T\to P$ with $f=f'\circ g$. The pair is unique up to unique isomorphism.
\end{theorem}

\begin{pitfall}
The notation $x\otimes y$ is ambiguous about the ambient tensor product, and ``$x\otimes y=0$'' can change meaning under enlargement. Over $A=\mathbb{Z}$, take $M=\mathbb{Z}$, $N=\mathbb{Z}/2$. In $\mathbb{Z}\otimes\mathbb{Z}/2$ the element $2\otimes x$ equals $1\otimes 2x=1\otimes0=0$. But the same symbol inside $2\mathbb{Z}\otimes\mathbb{Z}/2$ need not vanish (A\&M, Remark ii after 2.12; cf.\ Cor.\ 2.13: if $\sum x_i\otimes y_i=0$ in $M\otimes N$ it already vanishes in $M_0\otimes N_0$ for some \emph{finitely generated} submodules). Always name the tensor product you are in.
\end{pitfall}

\begin{wex}{$A\otimes_A M\cong M$ and $A/\fa\otimes_A M\cong M/\fa M$}
Prove the unit law and the base-change-to-a-quotient formula.
\wrec Both follow from the universal property: a bilinear map out of $A\times M$ is determined by the action $a\cdot(-)$, and tensoring with $A/\fa$ imposes exactly the relations $\fa M=0$.
\wsol For $A\otimes_A M\cong M$: the bilinear map $(a,x)\mapsto ax$ induces $A\otimes M\to M$, $a\otimes x\mapsto ax$, with inverse $x\mapsto1\otimes x$; these compose to identities. For $A/\fa\otimes_A M$: apply $-\otimes_A M$ to $0\to\fa\to A\to A/\fa\to0$ (right-exactness, below) to get $\fa\otimes M\to M\to A/\fa\otimes M\to0$. The image of $\fa\otimes M\to M$ is $\fa M$, so $A/\fa\otimes_A M\cong M/\fa M$. Sanity check: $\mathbb{Z}/n\otimes_\mathbb{Z}\mathbb{Z}/m\cong(\mathbb{Z}/m)/n(\mathbb{Z}/m)\cong\mathbb{Z}/\gcd(n,m)$ -- e.g.\ $\mathbb{Z}/2\otimes\mathbb{Z}/3=0$ and $\mathbb{Z}/2\otimes\mathbb{Z}/4\cong\mathbb{Z}/2$.
\end{wex}

\begin{wex}{Tensor product of homomorphisms}
For $f:M\to M'$ and $g:N\to N'$, construct $f\otimes g:M\otimes N\to M'\otimes N'$ and verify functoriality.
\wrec The map $(x,y)\mapsto f(x)\otimes g(y)$ is bilinear, so it induces a unique linear map on the tensor product.
\wsol Bilinearity of $(x,y)\mapsto f(x)\otimes g(y)$ gives a well-defined $A$-linear $f\otimes g$ with $(f\otimes g)(x\otimes y)=f(x)\otimes g(y)$. Since simple tensors generate, $f\otimes g$ is unique. Functoriality $(f'\circ f)\otimes(g'\circ g)=(f'\otimes g')\circ(f\otimes g)$ holds on simple tensors, hence everywhere. Sanity check: $\id_M\otimes\id_N=\id_{M\otimes N}$, and $f\otimes g=0$ whenever $f=0$ or $g=0$, consistent with $(0\otimes g)(x\otimes y)=0\otimes g(y)=0$.
\end{wex}

\begin{definition}[{restriction and extension of scalars}]
\emph{Restriction:} a $B$-module $N$ becomes an $A$-module by $a\cdot x:=f(a)x$. \emph{Extension (base change):} an $A$-module $M$ becomes a $B$-module $M_B:=B\otimes_A M$, with $B$ acting on the left factor, $b'(b\otimes x)=b'b\otimes x$. These are adjoint: $\Hom_B(B\otimes_A M,N)\cong\Hom_A(M,N)$ naturally (extension is left adjoint to restriction).
\end{definition}

\begin{proof}[Idea]
Adjunction: an $A$-bilinear map $M\times N\to P$ is the same as an $A$-linear $M\to\Hom_A(N,P)$ (curry the second variable), which is the same as an $A$-linear $M\otimes N\to P$. So $T(-)=-\otimes N$ is left adjoint to $\Hom_A(N,-)$. Left adjoints preserve cokernels (right-exactness): apply the left-exact $\Hom(-,\Hom(N,P))$ and the left-exactness of $\Hom(T(-),P)$ to deduce exactness of $T$ on the right end, for all $P$. Tensoring need \emph{not} preserve injections on the left.
\end{proof}

\begin{definition}[{flat module}]
An $A$-module $N$ is \emph{flat} if $-\otimes_A N$ is exact, equivalently (A\&M 2.19) if tensoring any \emph{injection} $M'\hookrightarrow M$ with $N$ stays injective; it suffices to test injections $\fa\hookrightarrow A$ with $\fa$ finitely generated. Free modules are flat; localizations $S^{-1} A$ are flat (Section~15.5); over a PID, flat $=$ torsion-free.
\end{definition}

\begin{wex}{Tensor is not left-exact: a witness}
Exhibit an injection that fails to stay injective after tensoring.
\wrec Right-exactness can drop an injection to a non-injection; the standard witness is multiplication by $2$ tensored with $\mathbb{Z}/2$.
\wsol Take $0\to\mathbb{Z}\xrightarrow{2}\mathbb{Z}$ over $A=\mathbb{Z}$ and tensor with $N=\mathbb{Z}/2$. The map becomes $\mathbb{Z}/2\xrightarrow{\,\overline{2}\,}\mathbb{Z}/2$, which is multiplication by $2=0$ on $\mathbb{Z}/2$, the zero map -- not injective, although the original was. So $-\otimes\mathbb{Z}/2$ is not exact and $\mathbb{Z}/2$ is not a flat $\mathbb{Z}$-module. Sanity check: $\mathbb{Z}/2$ has $2$-torsion, and over the PID $\mathbb{Z}$ ``flat $=$ torsion-free'' predicts non-flatness; the right-exact sequence $\mathbb{Z}\xrightarrow{2}\mathbb{Z}\to\mathbb{Z}/2\to0$ tensored with $\mathbb{Z}/2$ correctly gives $\mathbb{Z}/2\xrightarrow{0}\mathbb{Z}/2\to\mathbb{Z}/2\to0$, exact only on the right.
\end{wex}

\begin{wex}{Free modules are flat}
Show $A^n$ (and more generally any free module) is flat.
\wrec Tensoring with $A$ is the identity functor, and tensoring with a direct sum is the direct sum of the tensors; direct sums of exact sequences are exact.
\wsol For an injection $M'\hookrightarrow M$, tensoring with $A$ gives $M'\hookrightarrow M$ unchanged (since $A\otimes-\cong\id$), still injective. Tensoring with $A^{(I)}=\bigoplus_I A$ gives $\bigoplus_I M'\hookrightarrow\bigoplus_I M$, injective because a direct sum of injections is injective. Hence every free module is flat. Sanity check: $\mathbb{Z}^n$ is torsion-free, consistent with flat $=$ torsion-free over $\mathbb{Z}$; and the failure example above used the \emph{non}-free $\mathbb{Z}/2$.
\end{wex}

\begin{wex}{Extension of scalars preserves finite generation}
If $M$ is generated by $x_1,\dots,x_n$ over $A$, show $M_B=B\otimes_A M$ is generated by $1\otimes x_1,\dots,1\otimes x_n$ over $B$.
\wrec Simple tensors $b\otimes x$ generate $M_B$, and $b\otimes x$ rewrites in terms of the $1\otimes x_i$ using bilinearity.
\wsol Any element of $M_B$ is a finite sum $\sum b_j\otimes m_j$. Writing $m_j=\sum_i a_{ij}x_i$ with $a_{ij}\in A$ and pulling scalars across, $b_j\otimes m_j=\sum_i b_j\otimes a_{ij}x_i=\sum_i(b_j f(a_{ij}))(1\otimes x_i)$. So everything is a $B$-combination of the $1\otimes x_i$. Sanity check (A\&M 2.16--2.17): if moreover $B$ is f.g.\ as an $A$-module by $y_1,\dots,y_m$, then the $mn$ products $y_k x_i$ generate $N$ over $A$ whenever $N$ is f.g.\ over $B$ -- the tower-of-generators principle.
\end{wex}

\begin{wex}{A torsion-free non-flat module needs a non-PID}
Over $A=k[x,y]$ show the ideal $\fm=(x,y)$ is torsion-free but not flat.
\wrec Over a non-PID, torsion-free no longer forces flat; test flatness by tensoring the inclusion $\fm\hookrightarrow A$ or by finding a nonzero element of $\Tor_1$.
\wsol $\fm$ is a submodule of the domain $A$, hence torsion-free. But consider the relation $y\cdot x-x\cdot y=0$ among the generators $x,y$ of $\fm$. In $\fm\otimes_A\fm$ the element $x\otimes y-y\otimes x$ is nonzero (it spans the kernel $\Tor_1^A(A/\fm,\fm)\cong\Tor_2^A(A/\fm,A/\fm)\cong k$ of $\fm\otimes_A\fm\to\fm$), so $-\otimes_A\fm$ does not stay injective on $\fm\hookrightarrow A$: the induced $\fm\otimes\fm\to A\otimes\fm=\fm$ kills $x\otimes y-y\otimes x\neq0$. Hence $\fm$ is not flat. Sanity check: this is impossible over a PID, matching that $k[x,y]$ is not a PID; the obstruction lives exactly where $\fm$ fails to be free (it is not, by the local computation above needing $2$ generators).
\end{wex}

\begin{definition}[{$A$-algebra}]
An \emph{$A$-algebra} is a ring $B$ together with a ring homomorphism $f:A\to B$; equivalently, a ring $B$ that is also an $A$-module with compatible multiplication. An \emph{$A$-algebra homomorphism} $h:B\to C$ is a ring map commuting with the structure maps, $h\circ f=g$. $B$ is \emph{finite} over $A$ if it is f.g.\ as an $A$-module, and \emph{of finite type} (finitely generated as an algebra) if $B=A[x_1,\dots,x_n]$ for finitely many $x_i$, i.e.\ a quotient of a polynomial ring $A[t_1,\dots,t_n]\twoheadrightarrow B$.
\end{definition}

\begin{remark}
This is where arithmetic and geometry merge in the A\&M sense. Every ring is uniquely a $\mathbb{Z}$-algebra (the map $n\mapsto n\cdot1$), so commutative-ring theory \emph{is} the theory of $\mathbb{Z}$-algebras. Geometrically, when $k$ is algebraically closed and $I$ is prime, a finite-type $k$-algebra $B=k[t_1,\dots,t_n]/I$ is the coordinate ring of the affine variety $V(I)\subseteq\Aff^n_k$; an $A$-algebra map is a morphism of the associated $\Spec$'s in the opposite direction (Section~15.8). The two readings of $\Spec A$ -- ``primes of arithmetic'' for $A=\mathbb{Z}$ and ``points of geometry'' for $A=k[t_1,\dots,t_n]/I$ -- are the same construction applied to two flavors of algebra.
\end{remark}

\begin{proof}[Idea]
Well-definedness of the multiplication is the only subtle point: the naive formula on representatives must be checked independent of representatives, which A\&M do by realizing it through the universal property in two stages ($(2.12^*)$ and $(2.14)$) rather than by hand. Once the product is defined, $u,v$ are visibly $A$-algebra maps and any pair $B\to E$, $C\to E$ of $A$-algebra maps glues to $b\otimes c\mapsto(\text{image of }b)(\text{image of }c)$ on $D$.
\end{proof}

\begin{wex}{Polynomial rings tensor to polynomial rings}
Compute $A[x]\otimes_A A[y]$.
\wrec Tensor product of free algebras adds variables; the universal property says a map out is a choice of images for $x$ and $y$.
\wsol $A[x]\otimes_A A[y]\cong A[x,y]$ via $x\otimes1\mapsto x$, $1\otimes y\mapsto y$. As $A$-modules both sides are free on the monomials $x^i y^j$, and the multiplications match by the algebra-tensor rule $(x\otimes1)(1\otimes y)=x\otimes y\mapsto xy$. Sanity check: this is the pushout/coproduct statement -- $A[x,y]$ is the free $A$-algebra on $\{x,y\}$, exactly the coproduct of the free algebras on $\{x\}$ and $\{y\}$; geometrically $\Aff^1\times_{\Spec A}\Aff^1=\Aff^2$.
\end{wex}

\begin{wex}{Base change of a quotient algebra}
For an ideal $I\subseteq A[x]$, compute $B\otimes_A\bigl(A[x]/I\bigr)$.
\wrec Extension of scalars commutes with quotients (right-exactness) and with adjoining variables, so it turns $A[x]/I$ into $B[x]/I^e$.
\wsol Right-exactness applied to $0\to I\to A[x]\to A[x]/I\to0$ tensored with $B$ gives $B\otimes_A(A[x]/I)\cong(B\otimes_A A[x])/(\text{image of }B\otimes I)\cong B[x]/I^e$, where $I^e=I\cdot B[x]$ is the extension. Sanity check: $\mathbb{R}\otimes_\mathbb{R}\mathbb{R}[x]/(x^2+1)\cong\mathbb{R}[x]/(x^2+1)\cong\mathbb{C}$, while $\mathbb{C}\otimes_\mathbb{R}\mathbb{R}[x]/(x^2+1)\cong\mathbb{C}[x]/(x^2+1)\cong\mathbb{C}[x]/((x-i)(x+i))\cong\mathbb{C}\times\mathbb{C}$ -- the extension splits, the geometric fibre over $\Spec\mathbb{R}$ acquires two points after base change to $\mathbb{C}$.
\end{wex}

\begin{wex}{A tensor product of fields that is not a field}
Show $\mathbb{C}\otimes_\mathbb{R}\mathbb{C}\cong\mathbb{C}\times\mathbb{C}$.
\wrec Write one factor as $\mathbb{R}[x]/(x^2+1)$ and base-change; the quadratic splits over $\mathbb{C}$, so the tensor product breaks into a product.
\wsol $\mathbb{C}\otimes_\mathbb{R}\mathbb{C}\cong\mathbb{C}\otimes_\mathbb{R}\mathbb{R}[x]/(x^2+1)\cong\mathbb{C}[x]/(x^2+1)\cong\mathbb{C}[x]/(x-i)\times\mathbb{C}[x]/(x+i)\cong\mathbb{C}\times\mathbb{C}$ by CRT (the factors $(x-i),(x+i)$ are coprime in $\mathbb{C}[x]$). Sanity check: as $\mathbb{R}$-vector spaces both sides have dimension $4$; and $\mathbb{C}\otimes_\mathbb{R}\mathbb{C}$ has nonzero zero-divisors (the idempotents $\tfrac12(1\otimes1\mp i\otimes i)$), so it is not a field even though both factors are -- tensor of fields over a subfield need not be a field. Geometrically $\Spec(\mathbb{C}\otimes_\mathbb{R}\mathbb{C})$ is two points: the two ways to embed $\mathbb{C}$ into $\mathbb{C}$ over $\mathbb{R}$.
\end{wex}

\begin{wex}{Localization as base change and its flatness}
Realize the ring of fractions $S^{-1} M$ as $S^{-1} A\otimes_A M$, anticipating Section~15.5.
\wrec Localization is extension of scalars along $A\to S^{-1} A$; the resulting functor is exact, which is the flatness of $S^{-1} A$.
\wsol For a multiplicative set $S\subseteq A$, there is a natural isomorphism $S^{-1} A\otimes_A M\cong S^{-1} M$, $(\tfrac{a}{s})\otimes x\mapsto\tfrac{ax}{s}$ (Section~15.5 makes this precise). Because localizing is exact -- it preserves injections, surjections, kernels -- $S^{-1} A$ is a \emph{flat} $A$-module, and $-\otimes_A S^{-1} A=S^{-1}(-)$ is an exact functor. Sanity check: exactness is visible on the witness above -- tensoring $0\to\mathbb{Z}\xrightarrow{2}\mathbb{Z}$ with the flat module $\mathbb{Z}_{(3)}=S^{-1}\mathbb{Z}$ ($S=\mathbb{Z}\setminus3\mathbb{Z}$) keeps $2$ a unit times an injection, so injectivity survives, unlike tensoring with $\mathbb{Z}/2$. This interaction of tensor and localization is the technical bridge to the next section.
\end{wex}

\begin{definition}[{multiplicatively closed set}]
A subset $S\subseteq R$ of a commutative ring with $1$ is \emph{multiplicatively closed} (a \emph{multiplicative set}) if $1\in S$ and $a,b\in S\implies ab\in S$. (D\&F write $D$ for this set; A\&M write $S$. We use $S$.)
\end{definition}

