The three motivating examples already cover most of the theory:
\begin{itemize}[leftmargin=*]
\item $S=\{1,f,f^2,f^3,\dots\}$ for a fixed $f\in R$ (inverting one element);
\item $S=R\setminus\fp$ for a prime ideal $\fp$ (the complement of a prime is multiplicative precisely because $\fp$ is prime); this is localization at a point $\fp\in\Spec R$;
\item $S=R\setminus\{zero divisors\}$, giving the total ring of fractions (when $R$ is a domain, $S=R\setminus\{0\}$ and we recover $\Frac R$).
\end{itemize}

latex:
The three motivating examples already cover most of the theory:
\begin{itemize}[leftmargin=*]
\item $S=\{1,f,f^2,f^3,\dots\}$ for a fixed $f\in R$ (inverting one element);
\item $S=R\setminus\fp$ for a prime ideal $\fp$ (the complement of a prime is multiplicative \emph{precisely because} $\fp$ is prime); this is localization \emph{at a point} $\fp\in\Spec R$;
\item $S=R\setminus\{\text{zero divisors}\}$, giving the total ring of fractions (when $R$ is a domain, $S=R\setminus\{0\}$ and we recover $\Frac R$).
\end{itemize}

\begin{remark}[{philosophy: $\Spec$ and concentration}]
The universal property says $S^{-1}R$ is the \emph{universal} (initial) $R$-algebra in which the elements of $S$ become invertible. Geometrically, the map $\pi^{*}\colon\Spec(S^{-1}R)\to\Spec R$ realizes $\Spec(S^{-1}R)$ as the subset of points (primes) that ``survive'' inverting $S$ -- those missing $S$. Inverting $f$ keeps the open set where $f\ne0$; inverting $R\setminus\fp$ keeps only the primes contained in $\fp$, i.e.\ concentrates on an infinitesimal neighborhood of the point $\fp$. This is the recurring A\&M slogan: \emph{the prime ideal is the common generalization of a prime of arithmetic and a point of geometry, and localization concentrates near such a point.}
\end{remark}

\begin{method}{Computing in $S^{-1}R$}
To test $r/s=r'/s'$, clear denominators \emph{with a slack factor}: find $x\in S$ with $x(s'r-sr')=0$. To test $r/s=0$, find $s'\in S$ with $s'r=0$. To invert: $s/1$ has inverse $1/s$. Never assume $R\hookrightarrow S^{-1}R$ -- that holds only when $S$ has no zero divisors.
\end{method}

\begin{wex}{The slack factor is necessary}
In $R=k[x,y]/(xy)$ with $S=\{1,x,x^2,\dots\}$, show $y/1=0$ in $S^{-1}R=R_x$.
\wrec Use $\ker\pi=\{r:\ sr=0,\ s\in S\}$; here $x\cdot y=0$ in $R$ and $x\in S$.
\wsol Since $xy=0$ in $R$ and $x\in S$, the element $y$ lies in $\ker\pi$, so $y/1=0/1$ in $R_x$. Concretely $y=xy/x=0/x=0$. Hence $\pi\colon R\to R_x$ is not injective: $x$ is a zero divisor of $R$. In fact $\pi(R)=k[x]$ and $R_x=k[x,x^{-1}]$, the Laurent polynomials. Sanity check: the only obstruction $0\in S$ would force $R_x=0$; but $x$ is not nilpotent, so $R_x\ne0$, and indeed $k[x,x^{-1}]\ne0$.
\end{wex}

\begin{wex}{$R_f\cong R[t]/(tf-1)$}
For $f\in R$ and $S=\{f^n\}$, identify $R_f$ with a quotient of a polynomial ring.
\wrec Inverting $f$ means adjoining a formal inverse $t$ with $tf=1$; the universal property pins down the isomorphism.
\wsol Let $T=R[t]/(tf-1)$, with $\bar t$ the class of $t$, so $\bar t\,f=1$ in $T$: thus $f$ is a unit in $T$. The map $R\to T$ inverts $f$, so by the universal property factors uniquely through $R_f\to T$, $1/f\mapsto\bar t$. Conversely $R\to R_f$ sends $f$ to a unit, so $R[t]\to R_f$, $t\mapsto1/f$, kills $tf-1$ and factors through $T\to R_f$. These are mutually inverse, so $R_f\cong R[t]/(tf-1)$. Sanity check: if $f$ is nilpotent, $f^n=0\in S$ forces $R_f=0$; correspondingly $T=R[t]/(tf-1)$ collapses, since in $T$ we have $1=(tf)^n=t^n f^n=t^n\cdot0=0$, so $R[t]/(tf-1)=0$, matching.
\end{wex}

\begin{wex}{$\mathbb{Z}_{(p)}$ and $\mathbb{Z}[1/p]$: localizing at vs.\ away from $(p)$}
Describe $S^{-1}\mathbb{Z}$ for $S=\mathbb{Z}\setminus(p)$, and for $S=\{1,p,p^2,\dots\}$.
\wrec $\fp=(p)$ is prime, so $S=\mathbb{Z}\setminus(p)$ is multiplicative; localizing at it inverts every integer \emph{not} divisible by $p$. Inverting the powers of $p$ does the opposite.
\wsol $\mathbb{Z}_{(p)}=\{a/b\in\mathbb{Q}:\ p\nmid b\}$: the rationals with denominator prime to $p$. Its unique maximal ideal is $p\mathbb{Z}_{(p)}=\{a/b:\ p\mid a,\ p\nmid b\}$, and every $b$ with $p\nmid b$ is a unit. By contrast $\mathbb{Z}[1/p]=\{a/p^n\}$ inverts $p$ and keeps all primes $\ne(p)$. Sanity check: $(p)$ is the only prime meeting $S=\{p^n\}$, so $\Spec\mathbb{Z}[1/p]$ is $\Spec\mathbb{Z}$ minus the point $(p)$; whereas $\Spec\mathbb{Z}_{(p)}=\{(0),(p)\}$, the two primes contained in $(p)$ -- concentration near the point $(p)$.
\end{wex}

\begin{wex}{Localizing a ring of functions at a point}
Let $R$ be a ring of $k$-valued functions on a set $V$ containing the constants, and for $a\in V$ let $\fm_a=\{f:\ f(a)=0\}$. Identify $R_{\fm_a}$.
\wrec Evaluation at $a$ is a surjection $R\to k$ with kernel $\fm_a$, so $\fm_a$ is maximal; $S=R\setminus\fm_a$ consists of functions \emph{nonvanishing} at $a$.
\wsol $R_{\fm_a}=\{f/g:\ f,g\in R,\ g(a)\ne0\}$. Each such fraction has a well-defined value $(f/g)(a)=f(a)/g(a)\in k$ independent of representative, so $R_{\fm_a}$ is a ring of ``rational functions defined at $a$.'' Sanity check: the residue field is $R_{\fm_a}/\fm_a R_{\fm_a}\cong k$ via $f/g\mapsto f(a)/g(a)$ -- evaluation at the point survives localization, which is precisely the meaning of ``germ at $a$.''
\end{wex}

\begin{proof}[Idea]
The map $S^{-1}R\times M\to S^{-1}M$, $(r/s,m)\mapsto rm/s$, is $R$-bilinear, inducing $S^{-1}R\otimes_R M\to S^{-1}M$; the rule $m/s\mapsto(1/s)\otimes m$ is a well-defined inverse (one checks independence of representative using the slack factor). Both directions are $S^{-1}R$-linear, so they are mutually inverse isomorphisms.
\end{proof}

\begin{proof}[Idea]
It suffices (A\&M 3.3) to show $S^{-1}$ preserves \emph{exactness at a single spot}: if $M'\xrightarrow{f}M\xrightarrow{g}M''$ is exact at $M$ then so is the localized sequence. ``$\supseteq$'': $g f=0$ gives $S^{-1}g\,S^{-1}f=0$. ``$\subseteq$'': if $(S^{-1}g)(m/s)=g(m)/s=0$, then $t\,g(m)=0=g(tm)$ for some $t\in S$, so $tm=f(m')$ by exactness, whence $m/s=f(m')/(ts)=(S^{-1}f)(m'/ts)$. Applying this to $0\to M'\to M$ shows $S^{-1}f$ is injective, giving full short-exactness; flatness is the tensor restatement.
\end{proof}

\begin{remark}[{why flatness matters}]
Flatness is exactly the statement that localizing never creates spurious relations: a relation among fractions can always be cleared (multiply by a common $s\in S$) back to a relation in $M$. This is the technical engine behind every local-global principle below. A\&M emphasize that flatness, injectivity of a map, and being zero are all properties that can be \emph{checked locally}.
\end{remark}

\begin{wex}{Localization kills $S$-torsion}
Show $S^{-1}M=0$ iff every $m\in M$ is annihilated by some $s\in S$ (i.e.\ $M$ is $S$-torsion).
\wrec $m/1=0$ in $S^{-1}M$ iff $sm=0$ for some $s\in S$; $S^{-1}M=0$ means every $m/1$, hence every $m/t$, is zero.
\wsol If $S^{-1}M=0$ then $m/1=0$ for all $m$, so each $m$ has $s_m\in S$ with $s_m m=0$. Conversely if each $m$ is $S$-torsion, then any $m/t=0$ since $s_m(m)=0$. Sanity check: for $R=\mathbb{Z}$, $M=\mathbb{Z}/6\mathbb{Z}$, $S=\mathbb{Z}\setminus(2)$: every element is killed by $3\in S$? No -- $3\cdot\bar1=\bar3\ne0$, but $3\cdot\bar2=\bar0$; the $2$-torsion-free part dies. Indeed $M_{(2)}=\mathbb{Z}/2\mathbb{Z}\ne0$, consistent with $M$ \emph{not} being $S$-torsion. (Compare the next example.)
\end{wex}

\begin{wex}{Localizing a finite abelian group at a prime}
For $M=\mathbb{Z}/6\mathbb{Z}$ as a $\mathbb{Z}$-module, compute $M_{(p)}$ for each prime $p$ and $M_{(0)}$.
\wrec $M_{(p)}$ inverts all integers prime to $p$; this projects $M$ onto its $p$-primary component (Sylow $p$-subgroup).
\wsol $\mathbb{Z}/6\mathbb{Z}\cong\mathbb{Z}/2\mathbb{Z}\oplus\mathbb{Z}/3\mathbb{Z}$. Inverting $S=\mathbb{Z}\setminus(2)$ makes $3$ a unit, so the $\mathbb{Z}/3\mathbb{Z}$ summand (killed by $3\in S$) dies: $M_{(2)}\cong\mathbb{Z}/2\mathbb{Z}$. Symmetrically $M_{(3)}\cong\mathbb{Z}/3\mathbb{Z}$. For $p\notin\{2,3\}$, both $2,3\in S$ are units, so all of $M$ is $S$-torsion and $M_{(p)}=0$. At $\fp=(0)$, $S=\mathbb{Z}\setminus\{0\}$ inverts everything, killing the entire torsion group: $M_{(0)}=0$. Sanity check: $M_{(p)}$ is the $p$-primary component, nonzero only for $p\in\{2,3\}$, exactly the primes dividing $6$.
\end{wex}

\begin{wex}{Localization commutes with direct sums and quotients}
Verify $S^{-1}(M\oplus N)\cong S^{-1}M\oplus S^{-1}N$ and $S^{-1}(M/N)\cong S^{-1}M/S^{-1}N$.
\wrec Both follow from exactness (or from $S^{-1}R\otimes_R(\cdot)$ commuting with $\oplus$ and right-exactness).
\wsol For sums: $(m,n)/s\mapsto(m/s,n/s)$ is an $S^{-1}R$-isomorphism. For quotients: apply the exact functor $S^{-1}$ to $0\to N\to M\to M/N\to0$, getting $0\to S^{-1}N\to S^{-1}M\to S^{-1}(M/N)\to0$, so $S^{-1}(M/N)\cong S^{-1}M/S^{-1}N$ with $S^{-1}N\subseteq S^{-1}M$ a submodule. Sanity check: take $R=\mathbb{Z}$, $M=\mathbb{Z}$, $N=6\mathbb{Z}$, $S=\mathbb{Z}\setminus(2)$. Then $S^{-1}M=\mathbb{Z}_{(2)}$, $S^{-1}N=6\mathbb{Z}_{(2)}=2\mathbb{Z}_{(2)}$ (since $3$ is a unit), and $\mathbb{Z}_{(2)}/2\mathbb{Z}_{(2)}\cong\mathbb{Z}/2\mathbb{Z}\cong(\mathbb{Z}/6\mathbb{Z})_{(2)}$, matching.
\end{wex}

\begin{wex}{$S^{-1}(\Ann M)=\Ann(S^{-1}M)$ for finitely generated $M$}
Show that for finitely generated $M$, localization commutes with the annihilator.
\wrec For a \emph{single} generator $\Ann(Rm)$ this is clear; reduce a finite generating set via $\Ann(M+N)=\Ann M\cap\Ann N$ and the fact that $S^{-1}$ commutes with finite intersections.
\wsol If $M=Rm$ then $\Ann(S^{-1}M)=\{r/s:\ (r/s)(m/1)=0\}=\{r/s:\ s'rm=0\}=S^{-1}\Ann(M)$. For $M=\sum_{i=1}^n Rm_i$, write $\Ann M=\bigcap_i\Ann(Rm_i)$; since $S^{-1}$ commutes with finite intersections, $S^{-1}\Ann M=\bigcap_i S^{-1}\Ann(Rm_i)=\bigcap_i\Ann(S^{-1}Rm_i)=\Ann(S^{-1}M)$. Sanity check: finiteness is needed -- for $M=\bigoplus_{p}\mathbb{Z}/p\mathbb{Z}$ over $\mathbb{Z}$, $\Ann M=0$ but $S^{-1}M$ can have nonzero annihilator after localizing away infinitely many torsion pieces.
\end{wex}

\begin{proof}[Idea]
(1) Given $a/s\in\fb$, also $a/1=s(a/s)\in\fb$, so $a\in\fb^{c}$ and $a/s\in(\fb^{c})^{e}$; the reverse inclusion is clear. (2) $r\in\fa^{ec}\iff r/1\in S^{-1}\fa\iff r/1=a/s$ with $a\in\fa\iff x(sr-a)=0$ some $x\in S\iff (xs)r\in\fa$, i.e.\ $r\in(\fa:xs)$. (3) Sums/intersections/products: clear denominators with a common $s$. Radicals: $(a/s)^n=a^n/s^n\in S^{-1}\fa\iff t a^n\in\fa$ some $t\iff(ta)^n\in\fa\iff ta\in\rad\fa$, giving $\rad(S^{-1}\fa)=S^{-1}(\rad\fa)$. The quotient formula is exactness applied to $0\to\fa\to R\to R/\fa\to0$. (4) Chains in $S^{-1}R$ contract (injectively, by (1)) to chains in $R$.
\end{proof}

\begin{remark}[{saturation, geometrically}]
Loosely, $\fa^{ec}$ collects the elements that \emph{would} lie in $\fa$ if denominators from $S$ were allowed. Ideals meeting $S$ ``blow up'' to the unit ideal -- they vanish from $\Spec(S^{-1}R)$ -- while primes disjoint from $S$ are the ones localization remembers (a non-prime ideal disjoint from $S$ can still grow under $\fa\mapsto\fa^{ec}$, as the next example shows). This is why A\&M say localization \emph{cuts out} the part of $\Spec R$ disjoint from $S$.
\end{remark}

\begin{wex}{Saturation that strictly enlarges $\fa$}
In $R=\mathbb{Z}$, $S=\mathbb{Z}\setminus(2)$, compute the saturation of $\fa=(12)$.
\wrec $\fa^{ec}=\{r:\ sr\in(12),\ s\in S\}$; inverting odd numbers should strip the odd part $3$ from $12=2^2\cdot3$.
\wsol With $s=3\in S$ and $r=4$: $3\cdot4=12\in(12)$, so $4\in\fa^{ec}$, though $4\notin(12)$. In general $r\in\fa^{ec}\iff$ some odd multiple of $r$ is divisible by $12=2^2\cdot3\iff 4\mid r$ (the odd factor $3$ is absorbed by $S$). Hence $\fa^{ec}=(4)$, the $2$-primary part of $(12)$. Sanity check: in $\mathbb{Z}_{(2)}$, $3$ is a unit, so $(12)^e=(4\cdot3)^e=(4)^e$, and contracting $(4)\mathbb{Z}_{(2)}$ gives back $(4)$ -- exactly the saturation.
\end{wex}

\begin{wex}{An ideal that becomes the whole ring}
With $R=\mathbb{Z}$, $S=\mathbb{Z}\setminus(2)$, show $(3)^{e}=\mathbb{Z}_{(2)}$.
\wrec $\fa^{e}=S^{-1}R$ iff $\fa\cap S\ne\varnothing$; here $3\in(3)\cap S$.
\wsol Since $3\in(3)$ and $3\in S=\mathbb{Z}\setminus(2)$, we have $3\in(3)\cap S$, so $(3)^{e}$ contains the unit $3/1$, forcing $(3)^{e}=\mathbb{Z}_{(2)}$. Sanity check: $(3)$ corresponds to the point $(3)\in\Spec\mathbb{Z}$, which is \emph{not} contained in $(2)$, so it disappears when we concentrate near $(2)$ -- its extension is the unit ideal.
\end{wex}

\begin{wex}{Localization commutes with radicals}
In $R=k[x,y]$, $S=\{1,y,y^2,\dots\}$, verify $\rad((x^2)^e)=((x))^e$ in $R_y$.
\wrec $S^{-1}(\rad\fa)=\rad(S^{-1}\fa)$; here $\rad(x^2)=(x)$ in $k[x,y]$.
\wsol In $R$, $\rad(x^2)=(x)$. Extending: $\rad((x^2)^e)=(\rad(x^2))^e=(x)^e$ in $R_y=k[x,y,y^{-1}]$. Directly: $(x/1)^2=x^2/1$ generates $(x^2)^e$, and its radical is generated by $x/1$. Sanity check: $y$ is a unit in $R_y$ and $y\notin(x)$, so the extension is a proper prime ideal (it is $(x)R_y$, with quotient $R_y/(x)R_y\cong k[y,y^{-1}]$, a domain), confirming $(x)^e$ is radical (indeed prime).
\end{wex}

\begin{proof}[Idea]
The contraction of a prime is always prime, and lands in a prime disjoint from $S$ (else its extension is the unit ideal). For $\fq$ prime with $\fq\cap S=\varnothing$: if $(a/s)(b/t)\in S^{-1}\fq$, clear denominators to get $x\,ab\in\fq$ for some $x\in S$; since $x\notin\fq$ and $\fq$ is prime, $ab\in\fq$, hence $a\in\fq$ or $b\in\fq$, so $a/s$ or $b/t\in S^{-1}\fq$ -- thus $S^{-1}\fq$ is prime. Finally $\fq^{ec}=\fq$ by the saturation formula and primality.
\end{proof}

\begin{proof}[Idea]
A prime $\fq$ is disjoint from $S=R\setminus\fp$ iff $\fq\subseteq\fp$. Among these, $\fp$ itself is the largest, so $S^{-1}\fp$ is the largest -- hence unique maximal -- ideal of $R_{\fp}$. Equivalently, every $a/s$ with $a\notin\fp$ has $a\in S$, so $a/s$ is a unit; the nonunits are exactly $S^{-1}\fp$, which is therefore an ideal (Prop.\ on local rings). The residue field statement is the quotient formula $R_{\fp}/\fp R_{\fp}\cong S^{-1}(R/\fp)=\Frac(R/\fp)$.
\end{proof}

\begin{remark}[{the local ring is the germ at a point}]
$\Spec R_{\fp}$ is the set of primes $\subseteq\fp$ -- the points of $\Spec R$ that \emph{specialize to} $\fp$, i.e.\ an infinitesimal neighborhood of the point $\fp$. The closed point is $\fp R_{\fp}$, the generic point is $(0)$ when $R$ is a domain. The residue field $\Frac(R/\fp)$ is the field of values ``at the point.'' This is the precise sense in which $R_{\fp}$ is the ring of germs of functions near $\fp$.
\end{remark}

\begin{wex}{$\Spec R_{\fp}$ for $R=k[x,y]$, $\fp=(x)$}
Identify the primes of the local ring $R_{(x)}$ and its residue field.
\wrec Primes of $R_{\fp}\leftrightarrow$ primes $\fq\subseteq\fp=(x)$ of $k[x,y]$.
\wsol The primes of $k[x,y]$ contained in $(x)$ are $(0)$ and $(x)$ itself (a prime $\fq$ with $(0)\subsetneq\fq\subsetneq(x)$ would give $\hgt(x)\ge2$, but $(x)$ has height $1$). So $\Spec R_{(x)}=\{(0)\subsetneq(x)R_{(x)}\}$, a chain of length one. The residue field is $R_{(x)}/(x)R_{(x)}\cong\Frac(k[x,y]/(x))=\Frac(k[y])=k(y)$. Sanity check: $\dim R_{(x)}=\hgt(x)=1$, matching the length-one chain of primes; the residue field $k(y)$ records the coordinate $y$ left free along the line $x=0$ (the transverse coordinate $x$ vanishes there).
\end{wex}

\begin{wex}{Localizing at a maximal ideal: residue field $k$}
For $R=k[x,y]$ ($k=\bar k$) and $\fm=(x-a,y-b)$, compute the residue field of $R_{\fm}$.
\wrec $\fm$ is maximal with $R/\fm\cong k$ (evaluation at $(a,b)$); localizing keeps the functions defined at the point $(a,b)$.
\wsol $R_{\fm}=\{f/g:\ g(a,b)\ne0\}$ is the ring of rational functions regular at $(a,b)$. Its maximal ideal is $\fm R_{\fm}=\{f/g:\ f(a,b)=0\}$ and the residue field is $R_{\fm}/\fm R_{\fm}\cong\Frac(R/\fm)=\Frac(k)=k$. Sanity check: evaluation $f/g\mapsto f(a,b)/g(a,b)\in k$ is a surjective ring map with kernel $\fm R_{\fm}$, and over $k=\bar k$ the residue field at a closed point is $k$ itself (Nullstellensatz).
\end{wex}

\begin{wex}{Prime correspondence for $R_f$}
With $R=k[x]$, $f=x$, list the primes of $R_x=k[x,x^{-1}]$.
\wrec Primes of $R_f\leftrightarrow$ primes $\fq$ with $\fq\cap\{1,x,x^2,\dots\}=\varnothing$, i.e.\ primes not containing $x$.
\wsol Primes of $k[x]$ are $(0)$ and the maximals $(p(x))$ for monic irreducible $p$. Those meeting $S=\{x^n\}$ are exactly the ones containing $x$, namely $(x)$. So $\Spec R_x=\{(0)\}\cup\{(p(x)):\ p\ne x\}$ -- all primes except $(x)$. Sanity check: geometrically $\Spec k[x,x^{-1}]=\Aff^1\setminus\{0\}$, the punctured line; removing the origin $(x)$ is exactly inverting $x$.
\end{wex}

\begin{wex}{A localization with a unique nonzero prime}
If $\fp$ is a height-one prime of a domain $R$ that is minimal among nonzero primes, show $R_{\fp}$ has exactly one nonzero prime.
\wrec Primes of $R_{\fp}\leftrightarrow$ primes $\subseteq\fp$; minimality of $\fp$ over $(0)$ leaves only $(0)$ and $\fp$.
\wsol The primes of $R$ contained in $\fp$ are $(0)$ (since $R$ is a domain) and $\fp$ (if $\fp$ is minimal nonzero, nothing sits strictly between). Hence $\Spec R_{\fp}=\{(0),\fp R_{\fp}\}$, so $R_{\fp}$ has the single nonzero prime $\fp R_{\fp}$, which is also maximal. Sanity check: $R=\mathbb{Z}$, $\fp=(p)$ gives $R_{\fp}=\mathbb{Z}_{(p)}$, a DVR with the unique nonzero prime $(p)\mathbb{Z}_{(p)}$ -- the prototypical local ring of dimension one.
\end{wex}

