\begin{theorem}[{$M=0$ is local}]
Let $M$ be an $R$-module. The following are equivalent:
\begin{enumerate}[label=\textup{(\arabic*)},leftmargin=*]
\item $M=0$;
\item $M_{\fp}=0$ for every prime $\fp$ of $R$;
\item $M_{\fm}=0$ for every maximal ideal $\fm$ of $R$.
\end{enumerate}
\end{theorem}

