\begin{lemma}[{two Noetherian lemmas}]
In a Noetherian ring $R$:
\begin{enumerate}[label=\textup{(\arabic*)},leftmargin=*]
\item every proper ideal is a finite intersection of irreducible ideals;
\item every irreducible ideal is primary.
\end{enumerate}
\end{lemma}

\begin{proof}[Idea]
(1) If the set of proper ideals \emph{not} so expressible were nonempty, Noetherianity gives a maximal counterexample $\fa$; $\fa$ is not irreducible, so $\fa=\fb\cap\fc$ properly, each of $\fb,\fc$ is a finite intersection of irreducibles, hence so is $\fa$ --- contradiction. (2) Pass to $R/\fa$ and show $0$ irreducible $\Rightarrow$ $0$ primary: if $xy=0$, $y\ne0$, the ascending chain $\Ann(x)\subseteq\Ann(x^2)\subseteq\cdots$ stabilizes at $\Ann(x^n)$; then $(x^n)\cap(y)=0$, and irreducibility with $(y)\ne0$ forces $x^n=0$.
\end{proof}

\begin{theorem}[{Lasker--Noether: existence}]
In a Noetherian ring $R$ every proper ideal has a (minimal) primary decomposition. Consequently every proper ideal has finitely many associated primes, finitely many minimal primes, and a well-defined $\Ass(\fa)$.
\end{theorem}

\begin{proof}[Idea]
Combine the two lemmas: finite intersection of irreducibles $=$ finite intersection of primary ideals; then reduce to a minimal decomposition by grouping equal radicals and discarding redundant components.
\end{proof}

