\begin{wex}{Existence forced by Noetherianity, failure without it}
Show $(0)$ has no primary decomposition in $R=k[x_1,x_2,\dots]/(x_1x_2,x_3x_4,x_5x_6,\dots)$.
\wrec Lasker--Noether needs Noetherian; this $R$ has infinitely many minimal primes, so $(0)$ cannot be a finite intersection of primaries.
\wsol Every prime of $R$ contains $\bar x_{2i-1}$ or $\bar x_{2i}$ for each $i$ (their product is $0$), and for every choice of one variable from each pair the ideal generated by the chosen variables is prime (the quotient is a polynomial ring in the remaining variables); so these ideals are exactly the minimal primes of $R$, and there are infinitely many of them, pairwise incomparable. If $(0)=\fq_1\cap\cdots\cap\fq_m$ were a finite primary decomposition, then by the proposition on isolated primes (the minimal primes over a decomposable ideal are its isolated associated primes) $(0)$ would have only finitely many minimal primes (the isolated $\rad\fq_i$). But it has infinitely many. Contradiction. Sanity check: $R$ is non-Noetherian (the ideal $(x_1,x_3,x_5,\dots)$ is not finitely generated), so the existence theorem simply does not apply --- exactly the hypothesis that fails.
\end{wex}

\begin{wex}{Symbolic powers differ from ordinary powers}
In $R=k[x,y,z]/(xy-z^2)$ with $\fp=(\bar x,\bar z)$, compare $\fp^2$ and $\fp^{(2)}$.
\wrec $\fp^2$ was shown non-primary (embedded origin); $\fp^{(2)}$ is its isolated $\fp$-primary component, so they should differ.
\wsol We found $\fp^2=\bar x(\bar x,\bar y,\bar z)$ is not primary, with $\bar y$ a zero-divisor mod $\fp^2$ that is not nilpotent. The symbolic power $\fp^{(2)}=(\fp^2R_\fp)^c=\{r:sr\in\fp^2,\ s\notin\fp\}$. Since $\bar y\notin\fp$, the relation $\bar y\cdot\bar x=\bar z^2\in\fp^2$ shows $\bar x\in\fp^{(2)}$, whereas $\bar x\notin\fp^2$. Thus $\fp^2\subsetneq\fp^{(2)}$, and $\fp^{(2)}$ is the genuine $\fp$-primary component (one checks $\fp^{(2)}=(\bar x,\bar z^2)$-type primary, the contraction making $\bar y$ a unit). Sanity check: $\fp^2\subseteq\fp^{(2)}\subseteq\fp$ with strict first inclusion, exactly the predicted behavior $\fp^n\subseteq\fp^{(n)}$ with equality failing precisely when $\fp^n$ is not primary.
\end{wex}

\begin{wex}{Support equals the union of components}
For $M=R/\fa$ with $\fa=(x)\cap(x,y)^2$ in $R=k[x,y]$, describe $\Supp(M)$ and confirm it is $\bigcup_{\fp\in\Ass}V(\fp)$.
\wrec $\Supp(R/\fa)=V(\fa)=V(\rad\fa)$ as a set; $\Ass(\fa)=\{(x),(x,y)\}$.
\wsol $\Supp(R/\fa)=V(\Ann(R/\fa))=V(\fa)$, and as a topological subset of $\Spec R$ this equals $V(\rad\fa)=V((x))$, the $y$-axis line in $\Spec k[x,y]$ (all primes containing $x$). Now $\bigcup_{\fp\in\Ass}V(\fp)=V((x))\cup V((x,y))=V((x))\cup\{(x,y)\}=V((x))$, since the point $(x,y)$ already lies on the line $V((x))$. So $\Supp(M)=V((x))=\bigcup_\fp V(\fp)$. Sanity check: the embedded prime $(x,y)$ contributes \emph{no new points} to the support --- it sits inside the component $V((x))$ --- which is exactly why $\Supp$ sees only the underlying space while $\Ass$ additionally records the embedded $(x,y)$.
\end{wex}

\begin{wex}{Zero-divisors and nilpotents via associated primes}
Let $R=k[x,y]/(x^2,xy)$. Using $\Ass$ of the lifted ideal, describe the zero-divisors and nilpotents of $R$.
\wrec For $(0)=\bigcap_i\fq_i$ minimal in a Noetherian ring, zero-divisors $=\bigcup\fp_i$ and nilpotents $=\bigcap\fp_i=\rad(0)$.
\wsol Lift to $\fa=(x^2,xy)$ in $k[x,y]$ with $\Ass(\fa)=\{(x),(x,y)\}$. In $R$ the zero-divisors are the image of $(x)\cup(x,y)=(x,y)$ and the nilpotents are the image of $(x)\cap(x,y)=(x)$, i.e.\ $\bar x$ generates the nilradical ($\bar x^2=0$). Sanity check: directly $\bar x^2=0$ so $\bar x$ is nilpotent (hence a zero-divisor), $\bar y\bar x=0$ so $\bar y$ is a zero-divisor; and $\bar y$ is not nilpotent ($y^n\notin(x^2,xy)$), matching $\bar y\in\bigcup\fp_i\setminus\bigcap\fp_i$.
\end{wex}

Prove that $Q \subset P$, i.e., there are nonzero prime ideals properly contained in $P$.
\end{enumerate}

\item Let $A$ be any ideal in $R = k[x_1, \ldots, x_n, y_1, \ldots, y_m]$.
\begin{enumerate}
\item[(a)] Show that $\rad(A \cap k[y_1, \ldots, y_m]) = \rad A \cap k[y_1, \ldots, y_m]$.
\item[(b)] Suppose $(f_1, \ldots, f_s)$ is an ideal in $k[x_1, \ldots, x_n]$. Let $F_1, \ldots, F_t$ be generators for the radical of $(f_1, \ldots, f_s)$, computed in $k[x_1, \ldots, x_n]$. Suppose $J$ is an ideal in $R$ and let $\mathcal{A} = J + (f_1, \ldots, f_s)$, $\mathcal{B} = J + (F_1, \ldots, F_t)$ as ideals in $R$. Prove that $\rad \mathcal{A} = \rad \mathcal{B}$.
\item[(c)] Conclude from (a) and (b) that $\mathcal{A} = (y_1 - x_1, \ldots, y_m - x_m, f_1, \ldots, f_s) \cap k[y_1, \ldots, y_m]$ and $\mathcal{B} = (y_1 - x_1, \ldots, y_m - x_m, F_1, \ldots, F_t) \cap k[y_1, \ldots, y_m]$ have the same zero sets over an algebraically closed field $k$. [Use Hilbert's Nullstellensatz.]
\end{enumerate}

\item Determine the Zariski closure in $\mathbb{C}^3$ of the points on the curve $\{(a^2, a^3, a^4) \mid a \in \mathbb{C}\}$.

\item Show that $Z(x^3 - xyz + z^2)$ is the smallest algebraic set in $\mathbb{R}^3$ containing the points $\{(st, s + t, s^2 t) \mid s, t \in \mathbb{R}\}$.

\item Show that $Z(x^3 z^2 - 3xy^2 z^2 - y^6 - z^4)$ is the smallest algebraic set in $\mathbb{R}^3$ containing the points $\{(s^2 + t^2, st, s^3) \mid s, t \in \mathbb{R}\}$.

\item Find equations defining the Zariski closure of the set of points $\{(s^4, s^3 t, s t^3, t^4) \mid s, t \in \mathbb{R}\}$.

\item Show that $V = Z(x^2 - y^2 z)$ (the Whitney umbrella surface) is the smallest algebraic set in $\mathbb{R}^3$ containing the points $S = \{(st, s, t^2) \mid s, t \in \mathbb{R}\}$. Show that $S$ is not Zariski closed in $V$ (the missing points explain the name for the surface). Do the same over $\mathbb{C}$, but show that in this case $S = V$ is closed.

\item Let $V = Z(xz^2 - w^3, \; xw^2 - y^4, \; y^4 z^2 - w^5) \subseteq \mathbb{C}^4$. Determine the Zariski closure of the image of $V$ under the projection $\pi((x, y, z, w)) = (x, y, z)$.

\item Let $V = Z(xy - 1)$ in $\Aff^2$ and let $S$ be the projection of $V$ onto the $x$-axis in $\Aff^1$.
\begin{enumerate}
\item[(a)] If $k = \mathbb{R}$, show that $I(V) = (xy - 1) \subseteq \mathbb{R}[x, y]$ and that $(u - x, xy - 1) \cap \mathbb{R}[u] = 0$ in $\mathbb{R}[x, y, u]$. Use Propositions 8 and 16 to conclude that the Zariski closure of $S$ is $\Aff^1$ and show that $S$ is not itself closed.
\item[(b)] If $k = \F_3$, show that $I(V) = (xy - 1, x^3 - x, y^3 - y) \subseteq \F_3[x, y]$ and that $(u - x, xy - 1, x^3 - x, y^3 - y) \cap \F_3[u] = (u^2 - 1)$ in $\F_3[x, y, u]$. Use Propositions 8 and 16 to conclude that $S$ is Zariski closed in $\Aff^1$.
\end{enumerate}

\item Recall the ideal quotient $(I : J) = \{r \in R \mid rJ \subseteq I\}$ of two ideals $I, J$ in a ring $R$ (cf. Exercise 34 ff. in Section 9.6). Clearly $I \subseteq (I : J)$.
\begin{enumerate}
\item[(a)] Show that $Z(I) - Z(J)$, the set of elements of $Z(I)$ not lying in $Z(J)$, is contained in $Z((I : J))$ and conclude that the Zariski closure of $Z(I) - Z(J)$ is contained in $Z((I : J))$.
\item[(b)] Show that if $k$ is algebraically closed and $I$ is a radical ideal then $Z((I : J))$ is precisely the Zariski closure of $Z(I) - Z(J)$.
\item[(c)] Show that if $V$ and $W$ are affine algebraic sets then $(I(V) : I(W)) = I(V - W)$.
\end{enumerate}
\end{exers}

