\begin{proposition}[{characterizations of integrality; A\&M 5.1}]
Let $A\subseteq B$ and $x\in B$. The following are equivalent:
\begin{enumerate}[label=\textup{(\roman*)},leftmargin=*]
\item $x$ is integral over $A$;
\item $A[x]$ is a finitely generated $A$-module;
\item $A[x]$ is contained in a subring $C$ with $A\subseteq C\subseteq B$ that is a finitely generated $A$-module;
\item there is a faithful $A[x]$-module $M$ that is finitely generated as an $A$-module.
\end{enumerate}
\end{proposition}

\begin{proof}[Idea]
(i)$\Rightarrow$(ii): the monic relation lets one rewrite $x^n$, hence every $x^{n+r}$, as an $A$-combination of $1,x,\dots,x^{n-1}$, so $A[x]=A1+Ax+\cdots+Ax^{n-1}$. (ii)$\Rightarrow$(iii): take $C=A[x]$. (iii)$\Rightarrow$(iv): take $M=C$, faithful because $1\in C$. (iv)$\Rightarrow$(i) is the determinant trick: multiplication by $x$ on the finitely generated module $M=Av_1+\cdots+Av_n$ gives $xv_i=\sum_j a_{ij}v_j$, so $(xI-(a_{ij}))v=0$; multiplying by the adjugate yields $\det(xI-(a_{ij}))\cdot v_i=0$ for all $i$. Faithfulness forces $\det(xI-(a_{ij}))=0$, a monic equation for $x$ over $A$.
\end{proof}

\begin{proof}[Idea]
For (1): $A[x]$ and $A[y]$ are finite $A$-modules, so $A[x,y]=\sum_{i,j}Ax^iy^j$ is too; it contains $x\pm y$ and $xy$, so (iii) of the proposition applies. (2) iterates (1) up the tower $A[x_1]\subseteq A[x_1,x_2]\subseteq\cdots$. (3): if $x\in C$ satisfies a monic equation with coefficients $b_i\in B$, then $A[b_0,\dots,b_{n-1}]$ is a finite $A$-module and $A[b_0,\dots,b_{n-1}][x]$ is a finite module over it; transitivity of finiteness of modules and (iii) give the claim. (4) is (3) read with $C=\overline{\overline A}$.
\end{proof}

\begin{remark}[A\&M's slogan]
Corollary~(2) is the identity \textbf{finite type $+$ integral $=$ finite}: a ring extension that is both finitely generated as an algebra and integral is finitely generated as a module. This is the precise sense in which a ramified cover $C\to\Aff^1$ is ``finite over the base.''
\end{remark}

\begin{wex}{$\sqrt2$ is an algebraic integer; $1/2$ is not}
Decide which of $\sqrt2,\ \tfrac{1+\sqrt5}{2},\ \tfrac12\in\mathbb{Q}$ are integral over $\mathbb{Z}$.
\wrec An element of $\mathbb{Q}$ is integral over the UFD $\mathbb{Z}$ iff it lies in $\mathbb{Z}$ (rational root test); for irrationals, exhibit a monic integer equation.
\wsol $\sqrt2$ satisfies $x^2-2=0$, monic over $\mathbb{Z}$, so it is integral. The golden ratio $\tau=\tfrac{1+\sqrt5}{2}$ satisfies $x^2-x-1=0$, monic over $\mathbb{Z}$, so it is integral. But $\tfrac12$ is integral over $\mathbb{Z}$ iff $\tfrac12\in\mathbb{Z}$ (since $\mathbb{Z}$ is a UFD, hence integrally closed): if $(1/2)^n+a_{n-1}(1/2)^{n-1}+\cdots+a_0=0$ then clearing denominators gives $1=-2(a_{n-1}+\cdots+2^{n-1}a_0)$, forcing $2\mid1$, impossible. Sanity check: the minimal polynomial of $\tfrac12$ over $\mathbb{Q}$ is $x-\tfrac12$, not monic over $\mathbb{Z}$, matching Proposition~28 of D\&F that $\alpha$ is an algebraic integer iff $m_{\alpha,\mathbb{Q}}\in\mathbb{Z}[x]$.
\end{wex}

\begin{wex}{Integral closure need not equal the subring: the cuspidal cubic}
Let $R=k[x,y]/(x^2-y^3)=k[\bar x,\bar y]$. Show $R$ is not integrally closed in its fraction field.
\wrec Look for an element of $\Frac(R)$ satisfying a monic equation over $R$ but lying outside $R$; the cusp at the origin is the geometric obstruction.
\wsol In $\Frac(R)$ set $t=\bar x/\bar y$. Then $t^2=\bar x^2/\bar y^2=\bar y^3/\bar y^2=\bar y$, so $t$ satisfies the monic equation $T^2-\bar y=0$ over $R$; hence $t$ is integral over $R$. But $t=\bar x/\bar y\notin R$: the parametrization $\bar x\mapsto s^3,\ \bar y\mapsto s^2$ identifies $R$ with $k[s^2,s^3]\subseteq k[s]$, and $t\mapsto s\notin k[s^2,s^3]$. The normalization is $k[s]=k[t]$, the smooth line resolving the cusp. Sanity check: $t$ also satisfies $T^3-\bar x=0$ (since $t^3=\bar x^3/\bar y^3=\bar x^3/\bar x^2=\bar x$), a second monic witness; and $R$ being non-normal forces it to be a non-UFD, consistent with $\bar x^2=\bar y^3$ giving two distinct factorizations of the same element.
\end{wex}

\begin{wex}{Every UFD is integrally closed}
Show that a UFD $A$ is integrally closed in $\Frac(A)$.
\wrec Use the rational root argument: a fraction in lowest terms satisfying a monic equation must have unit denominator.
\wsol Let $a/b\in\Frac(A)$ in lowest terms ($\gcd(a,b)=1$) satisfy $(a/b)^n+r_{n-1}(a/b)^{n-1}+\cdots+r_0=0$ with $r_i\in A$. Clearing $b^n$: $a^n=-b(r_{n-1}a^{n-1}+\cdots+r_0b^{n-1})$, so every irreducible dividing $b$ divides $a^n$, hence divides $a$. Since $\gcd(a,b)=1$, $b$ has no irreducible factors, i.e.\ $b$ is a unit and $a/b\in A$. Sanity check: $\mathbb{Z}$, $k[x]$, and $k[x_1,\dots,x_n]$ are all UFDs, hence all integrally closed -- recovering Example~(1) above and the normality of polynomial rings used in the Nullstellensatz.
\end{wex}

\begin{wex}{The ring of integers of $\mathbb{Q}(\sqrt D)$}
For squarefree $D$, compute the normalization of $\mathbb{Z}$ in $\mathbb{Q}(\sqrt D)$.
\wrec Test $\alpha=a+b\sqrt D$ ($a,b\in\mathbb{Q}$): integral iff its $\mathbb{Q}$-minimal polynomial $x^2-2ax+(a^2-b^2D)$ has integer coefficients.
\wsol Integrality forces $2a\in\mathbb{Z}$ and $a^2-b^2D\in\mathbb{Z}$; then $(2b)^2D=(2a)^2-4(a^2-b^2D)\in\mathbb{Z}$, and as $D$ is squarefree this forces $2b\in\mathbb{Z}$. Writing $a=x/2,\ b=y/2$ with $x,y\in\mathbb{Z}$ gives $x^2-y^2D\equiv0\pmod4$. As squares are $0,1\bmod4$ and $D$ is squarefree, either $D\equiv2,3\pmod4$ with $x,y$ both even (so $a,b\in\mathbb{Z}$), or $D\equiv1\pmod4$ with $x,y$ of equal parity. Hence
\[
\mathcal O_{\mathbb{Q}(\sqrt D)}=\begin{cases}\mathbb{Z}[\sqrt D],&D\equiv2,3\pmod4,\\[2pt]\mathbb{Z}\!\left[\tfrac{1+\sqrt D}{2}\right],&D\equiv1\pmod4.\end{cases}
\]
Sanity check: for $D=5$, $\tfrac{1+\sqrt5}{2}$ is integral (Worked Example above), so $\mathbb{Z}[\sqrt5]\subsetneq\mathcal O_{\mathbb{Q}(\sqrt5)}$ -- $\mathbb{Z}[\sqrt5]$ is the non-maximal, non-integrally-closed order, and adjoining the golden ratio normalizes it.
\end{wex}

\begin{proof}[Idea]
(1): if $A$ is a field and $0\neq s\in B$ satisfies a monic equation with nonzero constant term $a_0$, then $s\cdot(-a_0^{-1})(s^{n-1}+\cdots+a_1)=1$ gives $s^{-1}\in B$. Conversely if $B$ is a field and $0\neq r\in A$, then $r^{-1}\in B$ is integral, and its monic equation rearranges to express $r^{-1}$ as an $A$-combination of nonnegative powers of $r$, so $r^{-1}\in A$. (2): reduce mod the primes -- $B/\fq$ is integral over $A/(\fq\cap A)$, so (1) gives the maximality statement; existence of \emph{some} $\fq$ is the localization argument $S^{-1} A\subseteq S^{-1} B$ at $S=A\setminus\fp$ (a maximal ideal $\fn$ of $S^{-1} B$ contracts, by the maximality statement applied to the integral extension $S^{-1} A\subseteq S^{-1} B$, to the maximal ideal $\fp S^{-1} A$ of the local ring $S^{-1} A$, so the contraction of $\fn$ to $B$ is a prime of $B$ lying over $\fp$). (3) is an induction reducing to $n=2$, $m=1$: pass to $\overline A=A/\fp_1\subseteq\overline B=B/\fq_1$, apply Lying Over to $\fp_2/\fp_1$, and pull back. (4) is A\&M 5.16: reduce to $n=2$, $m=1$; since $A$ is integrally closed, A\&M 5.15 is used to show that $\fp_2B$ does \emph{not} meet the multiplicative set $(A\setminus\fp_2)(B\setminus\fq_1)$, and an ideal of $B$ maximal among those containing $\fp_2B$ and disjoint from this set is a prime $\fq_2\subseteq\fq_1$ with $\fq_2\cap A=\fp_2$.
\end{proof}

\begin{remark}[contraction is a continuous map of spectra]
The assignment $\fq\mapsto\fq\cap A$ is the continuous map $\Spec B\to\Spec A$ induced by $A\hookrightarrow B$. Lying Over says it is \emph{surjective}; Going Up says it is a \emph{closed} map (A\&M Ex.~5.1); Going Down says the generizations lift, which geometrically forbids the cover from ``jumping'' to a lower-dimensional sheet. For finite $B$ over $A$, the fibers are finite and nonempty -- a genuine branched covering of $\Spec A$.
\end{remark}

\begin{corollary}[{finitely many primes over a maximal ideal; D\&F 27}]
If $B$ is integral and finitely generated as a ring over $A$, and $\fm\subseteq A$ is maximal, then the set of maximal ideals $\fq\subseteq B$ with $\fq\cap A=\fm$ is finite and nonempty.
\end{corollary}

\begin{wex}{$\mathbb{Z}\subseteq\mathbb{Z}[i]$: primes lying over $(p)$}
Describe the primes of $\mathbb{Z}[i]$ lying over the rational primes $(2),(5),(7)$.
\wrec $\mathbb{Z}[i]$ is integral over $\mathbb{Z}$ (each $a+bi$ satisfies a monic quadratic); Lying Over guarantees a prime over each $(p)$, and the splitting type is read from $x^2+1\bmod p$.
\wsol Since $\mathbb{Z}[i]\cong\mathbb{Z}[x]/(x^2+1)$, primes over $(p)$ correspond to irreducible factors of $x^2+1$ in $\F_p[x]$. Over $(5)$: $x^2+1=(x-2)(x+2)$, so $(5)$ \emph{splits}: two primes $(2+i),(2-i)$ lie over it. Over $(2)$: $x^2+1=(x+1)^2$, so $(2)$ \emph{ramifies}: the single prime $(1+i)$ lies over it with $(2)=(1+i)^2$ up to a unit. Over $(7)$: $x^2+1$ is irreducible mod $7$ ($-1$ is a non-residue), so $(7)$ is \emph{inert}: $(7)$ stays prime in $\mathbb{Z}[i]$. Sanity check: each fiber is finite and nonempty (Corollary), and $\fq\cap\mathbb{Z}=(p)$ is maximal iff $\fq$ is maximal -- indeed all three primes $(1+i),(2+i),(7)$ are maximal in the Dedekind domain $\mathbb{Z}[i]$.
\end{wex}

\begin{wex}{Lying Over can fail without monic: $\mathbb{Z}\subseteq\mathbb{Q}$}
Show $\mathbb{Q}$ is not integral over $\mathbb{Z}$, and that contraction $\Spec\mathbb{Q}\to\Spec\mathbb{Z}$ is not surjective.
\wrec Integrality is essential in Lying Over; drop it and surjectivity dies.
\wsol $\mathbb{Q}$ is the localization $S^{-1}\mathbb{Z}$ at $S=\mathbb{Z}\setminus\{0\}$, a non-integral extension ($\tfrac12$ is not integral, Worked Example above). $\Spec\mathbb{Q}=\{(0)\}$ has one point, and contraction sends it to $(0)\subseteq\mathbb{Z}$; no rational prime $(p)$ is hit. Sanity check: this matches the general principle that localization \emph{removes} the closed points $V(p)$ -- ``concentrating near the generic point'' -- whereas integral extensions, by contrast, hit every point of the base.
\end{wex}

\begin{wex}{$A$ field iff $B$ field, in action}
Let $A=k$ a field and $B$ a domain integral over $k$. Show $B$ is a field.
\wrec Apply the direction ``$A$ a field $\Rightarrow$ $B$ a field'' of part~(1) of the theorem; it is the converse direction that kills the polynomial ring inside the Nullstellensatz proof.
\wsol By (1), $A=k$ a field and $B$ a domain integral over $A$ forces $B$ to be a field. Concretely, each $0\neq b\in B$ satisfies $b^n+a_{n-1}b^{n-1}+\cdots+a_0=0$ with $a_i\in k$; we may take $a_0\neq0$ (cancel powers of $b$ in the domain $B$), and then $b^{-1}=-a_0^{-1}(b^{n-1}+\cdots+a_1)\in B$. Sanity check: if instead $B=k[y]$ (a polynomial ring), then $y$ is transcendental over $k$, so it satisfies no monic equation over $k$ and $k[y]$ is \emph{not} integral over $k$; correspondingly $B=k[y]$ is not a field -- consistent with the theorem, since its hypothesis fails. The contrapositive ``$B$ not a field $\Rightarrow$ $B$ not integral over the field $k$'' is the direction shown here; what forces $q=0$ in the proof of Zariski's Lemma below is the converse direction of (1): a field that is integral over a subring forces that subring to be a field.
\end{wex}

\begin{definition}[algebraic independence]
Elements $y_1,\dots,y_q$ of a $k$-algebra are \emph{algebraically independent over $k$} if no nonzero polynomial $p\in k[X_1,\dots,X_q]$ has $p(y_1,\dots,y_q)=0$; equivalently $k[y_1,\dots,y_q]\cong k[X_1,\dots,X_q]$ as $k$-algebras.
\end{definition}

\begin{theorem}[{Noether Normalization Lemma; D\&F 30}]
Let $k$ be a field and $A=k[r_1,\dots,r_m]$ a finitely generated $k$-algebra. Then there exist $0\le q\le m$ and algebraically independent $y_1,\dots,y_q\in A$ such that $A$ is integral over the polynomial subring $k[y_1,\dots,y_q]$.
\end{theorem}

\begin{proof}[Idea]
Induct on $m$. If the $r_i$ are algebraically independent, take $y_i=r_i$. Otherwise a nonzero relation $f(r_1,\dots,r_m)=0$ holds. The key move is a change of variables $X_i=x_i-x_m^{\alpha_i}$ with $\alpha_i=(1+d)^i$ (where $d=\deg f$): in base $b=d+1$ the exponents separate, so $g(X_1,\dots,X_{m-1},x_m)=f(X_1+x_m^{\alpha_1},\dots,x_m)$ has a single highest pure power $cx_m^N$. Dividing by $c$ makes $r_m$ \emph{monic}, hence integral, over $B=k[s_1,\dots,s_{m-1}]$ where $s_i=r_i-r_m^{\alpha_i}$; each $r_i$ ($i<m$) is then integral over $B[r_m]$, so $A$ is integral over $B$ by transitivity. As $B$ is generated by $m-1$ elements, induction finishes.
\end{proof}

\begin{theorem}[{Zariski's Lemma; A\&M Cor.~5.24}]
Let $k$ be a field and let $L\supseteq k$ be a field that is finitely generated as a $k$-\emph{algebra}. Then $L$ is a finite (hence algebraic) field extension of $k$.
\end{theorem}

\begin{proof}[Idea]
By Noether Normalization, $L=k[r_1,\dots,r_m]$ is integral over a polynomial ring $k[y_1,\dots,y_q]$. By the ``fields together'' theorem (part~1), since $L$ is a field and integral over the domain $k[y_1,\dots,y_q]$, that subring must be a field too. But a polynomial ring in $q\ge1$ variables is never a field. Hence $q=0$, so $L$ is integral over $k$, i.e.\ algebraic, and being finitely generated and algebraic it is finite over $k$.
\end{proof}

\begin{remark}[A\&M's transcendence-degree proof]
A\&M reach Zariski's Lemma without normalization, via Proposition~5.23 (extending homomorphisms to $\Omega$): if $A\subseteq B$ are domains with $B$ finitely generated over $A$, then there is $0\neq u\in A$ such that, for any algebraically closed $\Omega$, every homomorphism $\varphi:A\to\Omega$ with $\varphi(u)\neq0$ extends to $B$. Applied with $A=k$ and $B=L$ (A\&M Corollary~5.24), the inclusion $k\hookrightarrow\overline k$ extends to a homomorphism $L\to\overline k$, which is injective because $L$ is a field; so $L$ is algebraic over $k$. Both routes deliver the same arithmetic-geometry payoff.
\end{remark}

\begin{wex}{Normalizing $k[x,y]/(xy-1)$}
Exhibit a Noether normalization of $A=k[x,y]/(xy-1)$ (the hyperbola, $\cong k[t,t^{-1}]$).
\wrec Find one algebraically independent element over which $A$ is integral; the relation $xy=1$ must be turned into a monic equation.
\wsol Here $\bar x,\bar y$ satisfy $\bar x\bar y=1$, so they are algebraically dependent ($q<2$). Set $u=\bar x+\bar y$. Then $\bar x,\bar y$ are the two roots of $T^2-uT+1=0$ (since $\bar x+\bar y=u$, $\bar x\bar y=1$), a monic equation over $k[u]$; hence $A=k[u][\bar x]$ is integral over $k[u]$, and $u$ is algebraically independent (transcendental) over $k$. So $q=1$ and $k[u]\hookrightarrow A$ is a normalization. Sanity check: $\dim A=1$ matches $q=1$ (the number of normalizing parameters equals the Krull dimension); and $A=k[t,t^{-1}]$ is indeed integral over $k[t+t^{-1}]$, so the hyperbola is finite over the line with coordinate $u=\bar x+\bar y$ -- but \emph{not} over the $x$-axis, since $\bar y=\bar x^{-1}$ is not integral over the integrally closed ring $k[\bar x]$.
\end{wex}

\begin{wex}{Why a polynomial ring is never a field}
Verify the step ``$q\ge1\Rightarrow k[y_1,\dots,y_q]$ not a field'' used in Zariski's Lemma.
\wrec A field has every nonzero element invertible; produce a non-invertible element of the polynomial ring.
\wsol In $k[y_1,\dots,y_q]$ with $q\ge1$, the element $y_1$ is nonzero but not a unit: if $y_1\cdot g=1$ then comparing degrees gives $1+\deg g=0$, impossible. So $k[y_1,\dots,y_q]$ is not a field. Sanity check: this is precisely why $q=0$ is forced, collapsing $L$ to an algebraic extension of $k$ -- the linchpin of the weak Nullstellensatz.
\end{wex}

\begin{wex}{Noether normalization of a hypersurface}
Normalize $A=k[x,y]/(y^2-x^3-x)$ over an infinite field $k$.
\wrec After a linear change ensuring the top-degree form is monic in one variable, that variable becomes integral over the others.
\wsol The relation $y^2=x^3+x$ is monic in $y$ over $k[x]$ ($y^2-(x^3+x)=0$), so $\bar y$ is integral over $k[\bar x]$, and $\bar x$ is transcendental over $k$ (no relation in $x$ alone). Thus $A=k[\bar x][\bar y]$ is integral over $k[\bar x]$ with $q=1$. Sanity check: $A$ is a free $k[\bar x]$-module on $\{1,\bar y\}$ of rank $2$ -- for $\charac k\neq2$ the elliptic curve presents itself as a degree-$2$ ramified cover of the $x$-line, branched where $x^3+x=0$, exactly the ``ramified covering'' picture A\&M opens the chapter with.
\end{wex}

\begin{proof}[Idea]
Each $(x_1-a_1,\dots,x_n-a_n)$ is maximal (the quotient is $k$). Conversely, for maximal $\fm$, the field $E=k[x_1,\dots,x_n]/\fm$ is finitely generated as a $k$-algebra, so by Zariski's Lemma $E$ is algebraic over $k$; as $k=\overline k$, $E=k$. Thus each $x_i$ maps to some $a_i\in k$, giving $x_i-a_i\in\fm$, whence $\fm=(x_1-a_1,\dots,x_n-a_n)$. For the last clause, a proper $I$ lies in a maximal $\fm=(x_i-a_i)$, so $(a_1,\dots,a_n)\in Z(I)$.
\end{proof}

\begin{proof}[Idea]
$\rad I\subseteq I(Z(I))$ is clear. For the reverse, the \emph{Rabinowitsch trick}: given $g\in I(Z(I))$ with $I=(f_1,\dots,f_m)$, the ideal $I'=(f_1,\dots,f_m,x_{n+1}g-1)$ in $k[x_1,\dots,x_{n+1}]$ has empty zero set (wherever the $f_i$ vanish, $g$ vanishes, so $x_{n+1}g-1$ cannot). By the Weak Form, $1\in I'$; writing $1=\sum a_if_i+a_{m+1}(x_{n+1}g-1)$, substituting $x_{n+1}=1/g$ and clearing denominators yields $g^N\in I$, i.e.\ $g\in\rad I$.
\end{proof}

\begin{remark}[the geometric dictionary, completed]
Combined with $\S15.2$: \emph{points} $\leftrightarrow$ maximal ideals; \emph{irreducible} algebraic sets $\leftrightarrow$ prime ideals; \emph{algebraic sets} $\leftrightarrow$ radical ideals; and unique decomposition of an algebraic set into irreducible components mirrors the unique writing of a radical ideal as an irredundant intersection of finitely many primes (its minimal primes). The Nullstellensatz is the statement that $k[\Aff^n]\rightsquigarrow\Aff^n$ loses no information when $k=\overline k$: geometry and the algebra of $k[\Aff^n]$ are the same subject. The variant for arbitrary $k$ (D\&F Cor.~33) recovers $I_k(Z_{\overline k}(I))=\rad I$ by base-changing to $\overline k$.
\end{remark}

\begin{wex}{Maximal ideals of $\mathbb{C}[x,y]$}
List the maximal ideals of $\mathbb{C}[x,y]$ and identify the one at the origin.
\wrec $\mathbb{C}$ is algebraically closed, so the Weak Nullstellensatz applies: maximal ideals are points.
\wsol Every maximal ideal of $\mathbb{C}[x,y]$ has the form $(x-a,y-b)$ for a unique $(a,b)\in\mathbb{C}^2$, with quotient $\mathbb{C}[x,y]/(x-a,y-b)\cong\mathbb{C}$ via $x\mapsto a,\ y\mapsto b$. The origin corresponds to $(x,y)$. Sanity check: $(x-a,y-b)$ is the kernel of evaluation $\operatorname{ev}_{(a,b)}:\mathbb{C}[x,y]\to\mathbb{C}$, a surjection onto a field, so the kernel is maximal; and distinct points give distinct kernels, so the correspondence is a bijection.
\end{wex}

\begin{wex}{Weak Form fails over $\mathbb{R}$}
Show $(x^2+1)\subseteq\mathbb{R}[x]$ is maximal but not of the form $(x-a)$.
\wrec Algebraic closure is essential; over $\mathbb{R}$, $E=\mathbb{R}[x]/\fm$ may be a proper algebraic extension of $\mathbb{R}$.
\wsol $\mathbb{R}[x]/(x^2+1)\cong\mathbb{C}$ is a field, so $(x^2+1)$ is maximal, yet it is not $(x-a)$ for any $a\in\mathbb{R}$ (it has no real root). The Weak Nullstellensatz fails because $\mathbb{R}\neq\overline\mathbb{R}$: here $E=\mathbb{C}$ is algebraic over $\mathbb{R}$ of degree $2$ but $\neq\mathbb{R}$. Sanity check: over $\mathbb{C}$, $x^2+1=(x-i)(x+i)$ factors and the two maximal ideals $(x-i),(x+i)$ \emph{are} points -- the obstruction is purely the failure of $\mathbb{R}$ to be algebraically closed.
\end{wex}

\begin{wex}{$I(Z(I))=\rad I$ on a concrete ideal}
For $I=(x^2,y)\subseteq\mathbb{C}[x,y]$, compute $Z(I)$, $I(Z(I))$, and $\rad I$, and check equality.
\wrec Compute the zero set, take the ideal of that set, and independently compute the radical; the Strong Form predicts they match.
\wsol $Z(I)=\{(x,y):x^2=0,\ y=0\}=\{(0,0)\}$, the origin. Then $I(Z(I))=I(\{(0,0)\})=(x,y)$, the maximal ideal at the origin. Independently $\rad(x^2,y)=(x,y)$: $x\in\rad I$ since $x^2\in I$, and $(x,y)$ is already prime (quotient $\cong\mathbb{C}$) hence radical, and contains $I$. So $I(Z(I))=(x,y)=\rad I$. Sanity check: $I=(x^2,y)\subsetneq(x,y)=\rad I$ is a strict containment -- the non-reducedness $x^2$ (a ``double point'' / embedded thickening) is invisible to $Z$, exactly what passing to the radical erases.
\end{wex}

\begin{wex}{A proper ideal with empty zero set forces $k\neq\overline k$}
Find a proper ideal $I\subseteq\mathbb{R}[x]$ with $Z(I)=\varnothing$ in $\mathbb{R}$, and reconcile with the Weak Form.
\wrec The ``moreover'' clause $Z(I)\neq\varnothing$ for proper $I$ requires $k=\overline k$.
\wsol Take $I=(x^2+1)\subseteq\mathbb{R}[x]$. It is proper (not all of $\mathbb{R}[x]$) yet $Z(I)=\{a\in\mathbb{R}:a^2+1=0\}=\varnothing$. This does not contradict the theorem because $\mathbb{R}$ is not algebraically closed. Over $\mathbb{C}$, $Z(x^2+1)=\{i,-i\}\neq\varnothing$, restoring the conclusion. Sanity check: this is the one-variable shadow of why algebraic closure is a hypothesis -- $1\notin(x^2+1)$ but the ideal still ``has no points'' over the non-closed field $\mathbb{R}$.
\end{wex}

\begin{definition}[valuation ring; dominance]
Let $K$ be a field. A subring $B\subseteq K$ is a \emph{valuation ring of $K$} if for every $0\neq x\in K$, at least one of $x,\ x^{-1}$ lies in $B$. Given local rings $A\subseteq B$ with maximal ideals $\fm_A,\fm_B$, we say $B$ \emph{dominates} $A$ if $A\subseteq B$ and $\fm_B\cap A=\fm_A$.
\end{definition}

