\begin{proposition}[{characterization of valuation rings; A\&M 5.18}]
Let $B$ be a valuation ring of $K$. Then:
\begin{enumerate}[label=\textup{(\roman*)},leftmargin=*]
\item $B$ is a local ring (its non-units $\fm=\{x:x=0\text{ or }x^{-1}\notin B\}$ form an ideal);
\item if $B\subseteq B'\subseteq K$ is any intermediate ring, then $B'$ is again a valuation ring of $K$;
\item $B$ is integrally closed in $K$ (normal).
\end{enumerate}
\end{proposition}

\begin{proof}[Idea]
(i): if $x,y$ are non-units, then $x/y$ or $y/x\in B$, say $x/y\in B$, whence $x+y=(1+x/y)y\in By\subseteq\fm$; and $ax\in\fm$ for $a\in B$; so $\fm$ is an ideal, the unique maximal one. (ii): immediate from the definition, since $x$ or $x^{-1}$ already lies in $B\subseteq B'$. (iii): if $x\in K$ is integral over $B$, $x^n+b_{n-1}x^{n-1}+\cdots+b_0=0$; if $x\notin B$ then $x^{-1}\in B$, and multiplying by $x^{-(n-1)}$ gives $x=-(b_{n-1}+b_{n-2}x^{-1}+\cdots+b_0x^{-(n-1)})\in B$, a contradiction. So $x\in B$.
\end{proof}

\begin{theorem}[{maximal dominated rings are valuation rings; A\&M 5.19--5.21}]
Let $K$ be a field, $\Omega$ an algebraically closed field, and let $\Sigma$ be the set of pairs $(A,f)$ with $A$ a subring of $K$ and $f:A\to\Omega$ a homomorphism, ordered by extension. A maximal element $(B,g)\in\Sigma$ has $B$ a valuation ring of $K$, with maximal ideal $\ker g$. Equivalently: the rings dominating a given local subring of $K$ have, among them, valuation rings as the maximal elements under dominance.
\end{theorem}

\begin{proof}[Idea]
Zorn's Lemma gives a maximal $(B,g)$; $\fm=\ker g$ is prime in $B$ since $g(B)\subseteq\Omega$ is a domain inside a field; $g$ extends to $B_\fm$, so maximality forces $B=B_\fm$, a local ring with maximal ideal $\fm$ (Lemma 5.19). For $x\neq0$ in $K$, comparing the extensions of $\fm$ in $B[x]$ and $B[x^{-1}]$ shows at least one is proper, so $g$ extends to $B[x]$ or $B[x^{-1}]$ (Lemma 5.20); maximality forces $x\in B$ or $x^{-1}\in B$. Hence $B$ is a valuation ring.
\end{proof}

\begin{proof}[Idea]
($\subseteq$) Every valuation ring $B\supseteq A$ is integrally closed (Prop.~5.18(iii)) and contains $A$, hence contains $\overline A$. ($\supseteq$) If $x\in K$ is \emph{not} integral over $A$, then $x^{-1}$ is a non-unit in $A'=A[x^{-1}]$, so $x^{-1}$ lies in a maximal ideal $\fm'$; extending the residue map $A'\to A'/\fm'\hookrightarrow\Omega$ to a maximal pair gives a valuation ring $B\supseteq A$ with $x^{-1}\in\fm_B$, so $x\notin B$. Thus anything in every such $B$ is integral.
\end{proof}

\begin{remark}[orders of vanishing; tie-back to $\S15.2$]
A valuation ring of $k(C)$ (the function field of a curve) records, at a chosen point $P$, the \emph{order of vanishing} of a rational function: $B=\{f:\operatorname{ord}_P(f)\ge0\}$ with maximal ideal $\{f:\operatorname{ord}_P(f)>0\}$. Dominance ``$B$ dominates the local ring $\mathcal O_{C,P}$'' is the algebraic statement ``the valuation is centered at $P$.'' The theorem then reads: a function is integral over the coordinate ring iff it has nonnegative order at every point -- i.e.\ \emph{regular functions are those with no poles}, the bridge from this section's integrality to the $\S15.2$ geometry of $Z(\cdot)$ and normal varieties.
\end{remark}

\begin{wex}{$\mathbb{Z}_{(p)}$ is a valuation ring of $\mathbb{Q}$}
Show the localization $\mathbb{Z}_{(p)}=\{a/b\in\mathbb{Q}:p\nmid b\}$ is a valuation ring of $\mathbb{Q}$, and identify its valuation.
\wrec Check the defining dichotomy $x$ or $x^{-1}\in B$ via the $p$-adic valuation $v_p$.
\wsol Write $0\neq x=p^n\cdot u$ with $u\in\mathbb{Q}^\times$ a unit at $p$ (numerator and denominator prime to $p$); set $v_p(x)=n$. Then $x\in\mathbb{Z}_{(p)}\iff v_p(x)\ge0$, and $x^{-1}$ has $v_p(x^{-1})=-n$, so exactly one of $v_p(x),v_p(x^{-1})$ is $\ge0$ (both if $n=0$). Hence $x$ or $x^{-1}\in\mathbb{Z}_{(p)}$: it is a valuation ring. Its maximal ideal is $p\mathbb{Z}_{(p)}=\{x:v_p(x)>0\}$. Sanity check: $\mathbb{Z}_{(p)}$ is local with residue field $\F_p$, and it is integrally closed (it is a localization of the UFD $\mathbb{Z}$), matching Prop.~5.18(iii). The ``point'' it centers on is the prime $(p)\in\Spec\mathbb{Z}$.
\end{wex}

\begin{wex}{$k[x]_{(x)}$ as order of vanishing at $0$}
Identify the valuation ring $k[x]_{(x)}\subseteq k(x)$ and its valuation geometrically.
\wrec The local ring of the line at the origin records vanishing order at $x=0$.
\wsol $B=k[x]_{(x)}=\{f/g:g(0)\neq0\}$. For $0\neq h\in k(x)$ write $h=x^n\cdot(p/q)$ with $p(0),q(0)\neq0$; then $\operatorname{ord}_0(h)=n$ and $h\in B\iff n\ge0$. So $h$ or $h^{-1}\in B$ always, and $B$ is the valuation ring of order-of-vanishing at the origin, with maximal ideal $(x)$ and residue field $k$. Sanity check: a rational function lies in $B$ iff it has no pole at $0$ -- ``regular at the origin'' -- the local-ring picture from $\S15.5$ realized as a valuation; and $\bigcap_{a\in k}k[x]_{(x-a)}\supseteq k[x]$ recovers global regularity as ``regular at every point.''
\end{wex}

\begin{wex}{A non-valuation subring}
Show $k[x,y]_{(x,y)}$ is local but \emph{not} a valuation ring of $k(x,y)$.
\wrec Test the dichotomy on $x/y$: a valuation ring must contain $x/y$ or $y/x$.
\wsol The element $x/y\in k(x,y)$ is not in $B=k[x,y]_{(x,y)}$ (its denominator $y$ vanishes at the maximal ideal's point), and neither is $y/x$. So $B$ fails the valuation dichotomy: $B$ is a local ring that is \emph{not} a valuation ring. Sanity check: this reflects that the local ring of the \emph{plane} at the origin has dimension $2$, whereas a rank-one (discrete) valuation records only codimension-one (order-one) data; one must \emph{blow up} or pass to a curve through the origin to obtain an honest valuation dominating $B$ -- consistent with A\&M~5.21, where valuation rings arise as maximal dominating rings, not arbitrary local rings.
\end{wex}

\begin{wex}{$\mathbb{Z}$ as an intersection of valuation rings}
Express $\mathbb{Z}$ as an intersection of valuation rings of $\mathbb{Q}$, illustrating Theorem 5.22.
\wrec $\mathbb{Z}$ is integrally closed in $\mathbb{Q}$ (it is a UFD), so it must equal an intersection of valuation rings; the $\mathbb{Z}_{(p)}$ are the natural candidates.
\wsol $\bigcap_{p\ \mathrm{prime}}\mathbb{Z}_{(p)}=\{a/b\in\mathbb{Q}:p\nmid b\text{ for all }p\}=\{a/b:b=\pm1\}=\mathbb{Z}$. Each $\mathbb{Z}_{(p)}$ is a valuation ring containing $\mathbb{Z}$ (previous Worked Example), and an element of $\mathbb{Q}$ lies in all of them iff its reduced denominator has no prime factor, i.e.\ is a unit. Sanity check: this is Theorem 5.22 with $A=K\cap\mathbb{Z}=\mathbb{Z}$ already integrally closed -- $\overline\mathbb{Z}=\mathbb{Z}=\bigcap_p\mathbb{Z}_{(p)}$ -- and geometrically it says ``an integer is a rational function on $\Spec\mathbb{Z}$ with no poles at any prime,'' the arithmetic analogue of a regular function on a curve.
\end{wex}

\begin{wex}{Going Down over a normal base, in $\mathbb{Z}[\sqrt{-5}]$}
Illustrate that normality of the base is what powers Going Down, using $\mathbb{Z}\subseteq\mathbb{Z}[\sqrt{-5}]$.
\wrec Going Down needs $A$ integrally closed in its fraction field (normal), not in $B$; $\mathbb{Z}$ is normal, so chains descend.
\wsol $\mathbb{Z}$ is integrally closed (UFD), and $\mathbb{Z}[\sqrt{-5}]=\mathcal O_{\mathbb{Q}(\sqrt{-5})}$ (here $-5\equiv3\bmod4$) is integral over $\mathbb{Z}$. Take the chain $(2)\supseteq(0)$ in $\mathbb{Z}$ and a prime $\fq_1=(2,1+\sqrt{-5})$ over $(2)$. Going Down completes it downward: there is $\fq_2\subseteq\fq_1$ with $\fq_2\cap\mathbb{Z}=(0)$, namely $\fq_2=(0)$ itself (a prime of the domain $\mathbb{Z}[\sqrt{-5}]$ contracting to $(0)$). Sanity check: had $A$ been non-normal the descent could fail in general, but for this short chain the lower prime is automatic -- $\fq_2=(0)$ lies over $(0)$ simply because $\mathbb{Z}[\sqrt{-5}]$ is a domain -- and no valuation ring is involved; the hypothesis ``$A$ integrally closed'' of A\&M's Theorem~5.16 enters the general proof through A\&M 5.15. Note $\fq_1^2=(2)$ here since $(2)$ ramifies as $(2)=(2,1+\sqrt{-5})^2$, consistent with $2$ being a ramified (non-split) prime.
\end{wex}

\begin{wex}{Integral closure of $k[x^2,x^3]$ via the valuation criterion}
Confirm the normalization of $A=k[x^2,x^3]$ is $k[x]$ using Theorem 5.22's ``no poles'' reading.
\wrec An element of $k(x)=\Frac(A)$ is in $\overline A$ iff it lies in every valuation ring of $k(x)$ containing $A$; equivalently, it is a polynomial (no poles).
\wsol $\Frac(A)=k(x)$ since $x=x^3/x^2\in\Frac(A)$. The nontrivial valuation rings of $k(x)/k$ are the localizations $k[x]_{(p)}$ at the monic irreducibles $p\in k[x]$ (the finite places, of which the $k[x]_{(x-a)}$ are the degree-one ones) together with the order-at-infinity ring $\{f/g:\deg f\le\deg g\}$; an element regular at every finite place and at infinity is a constant, but the ring at infinity does not contain $A$ ($x^2$ has a pole at infinity), so the valuation rings containing $A$ are $k(x)$ and the finite ones, leaving exactly the polynomials regular at all finite places: $\overline A=\bigcap_{p\ \mathrm{monic\ irred.}}k[x]_{(p)}=k[x]$. Indeed $x=x^3/x^2$ is integral over $A$ ($x$ satisfies $T^2-x^2=0$). Sanity check: $A=k[x^2,x^3]=k[s,t]/(t^2-s^3)$ is the cusp again; its normalization $k[x]$ smooths the cusp, matching the earlier direct computation and the geometric slogan ``normalize $=$ remove the singularity by demanding no poles.''
\end{wex}

\begin{wex}{Algebraic integers form a ring -- without finding a formula}
Show $\sqrt2+\sqrt3$ is an algebraic integer, using the ``integral closure is a ring'' corollary rather than computing a minimal polynomial by hand first.
\wrec Sums and products of integral elements are integral (Corollary), so it suffices that $\sqrt2,\sqrt3$ are integral.
\wsol $\sqrt2$ and $\sqrt3$ are integral over $\mathbb{Z}$ (roots of $x^2-2,\ x^2-3$), and the integral closure $\overline\mathbb{Z}$ in $\overline\mathbb{Q}$ is a ring, so $\sqrt2+\sqrt3\in\overline\mathbb{Z}$ is an algebraic integer. To exhibit a witness: $\alpha=\sqrt2+\sqrt3$ gives $\alpha^2=5+2\sqrt6$, so $(\alpha^2-5)^2=24$, i.e.\ $\alpha^4-10\alpha^2+1=0$, monic over $\mathbb{Z}$. Sanity check: the abstract closure-is-a-ring argument predicts integrality before any computation; the explicit quartic $x^4-10x^2+1$ confirms it and is the minimal polynomial of $\sqrt2+\sqrt3$ over $\mathbb{Q}$, with integer coefficients as Proposition~28 demands.
\end{wex}

\begin{exers}{Exercises (Dummit \& Foote).}
\item Use the fact that a U.F.D. is integrally closed to prove that the Gaussian integers $\mathbb{Z}[i]$ is the ring of integers in $\mathbb{Q}(i)$.

\item Suppose $k$ is a field and let $t = x/y$ in the field of fractions of the integral domain $R = k[x,y]/(x^2 - y^3)$. Prove that $K = k(t)$ is the fraction field of $R$ and $k[t]$ is the integral closure of $R$ in $K$.

\item Suppose $k$ is a field and $i$ and $j$ are relatively prime positive integers. Find the normalization of the integral domain $R = k[x,y]/(x^i - y^j)$ (cf.\ Exercise 14, Section 9.1).

\item Suppose $k$ is a field and let $P$ be the ideal $(y^2 - x^3 - x^2)$ in the polynomial ring $k[x,y]$. Prove that $P$ is a prime ideal and find the normalization of the integral domain $R = k[x,y]/P$. [To prove $P$ is prime, show that $y^2 - x^3 - x^2$ is irreducible in the U.F.D.\ $k[x,y]$. Then consider $t = y/x$ in the field of fractions of $R$.]

\item If $R$ is an integral domain with field of fractions $F$, show that $F$ is a finitely generated $R$-module if and only if $R = F$.

\item For each of the following give specific rings $R \subseteq S$ and explicit ideals in these rings that exhibit the specified relation:
\begin{enumerate}
\item[(a)] an ideal $I$ of $R$ such that $I \neq IS \cap R$ (so the contraction of the extension of an ideal $I$ need not equal $I$);
\item[(b)] a prime ideal $P$ of $R$ such that there is no prime ideal $Q$ of $S$ with $P = Q \cap R$;
\item[(c)] a maximal ideal $M$ of $S$ such that $M \cap R$ is not maximal in $R$;
\item[(d)] a prime ideal $P$ of $R$ whose extension $PS$ to $S$ is not a prime ideal in $S$;
\item[(e)] an ideal $J$ of $S$ such that $J \neq (J \cap R)S$ (so the extension of the contraction of an ideal $J$ need not equal $J$).
\end{enumerate}

\item Let $\mathcal{O}_K$ be the ring of integers in a number field $K$.
\begin{enumerate}
\item[(a)] Suppose that every nonzero ideal $I$ of $\mathcal{O}_K$ can be written as the product of powers of prime ideals. Prove that an ideal $Q$ of $\mathcal{O}_K$ is $P$-primary if and only if $Q = P^m$ for some $m \geq 1$. [Show first that since nonzero primes in $\mathcal{O}_K$ are maximal that $P_1^{m_1} \subseteq P_2^{m_2}$ for distinct nonzero primes $P_1, P_2$ implies $P_1 = P_2$.]
\item[(b)] Suppose that an ideal $Q$ of $\mathcal{O}_K$ is $P$-primary if and only if $Q = P^m$ for some $m \geq 1$. Assuming all of Theorem 21, prove that every nonzero ideal $I$ of $\mathcal{O}_K$ can be written uniquely as the product of powers of prime ideals. [Prove that $P_1^{m_1}$ and $P_2^{m_2}$ are comaximal ideals if $P_1$ and $P_2$ are distinct nonzero prime ideals and use the Chinese Remainder Theorem.]
\end{enumerate}

\item Prove that if $s_1, \ldots, s_n \in S$ are integral over $R$, then the ring $R[s_1, \ldots, s_n]$ is a finitely generated $R$-module.

\item Suppose that $S$ is integral over $R$ and that $P$ is a prime ideal in $R$. Prove that every element $s$ in the ideal $PS$ generated by $P$ in $S$ satisfies an equation $s^n + a_{n-1}s^{n-1} + \cdots + a_1 s + a_0 = 0$ where the coefficients $a_0, a_1, \ldots, a_{n-1}$ are elements of $P$. [If $s = p_1 s_1 + \cdots + p_m s_m \in PS$, show that $T = R[s_1, \ldots, s_m]$ satisfies the hypotheses in Proposition 23(3). Follow the proof in Proposition 23 that $s$ is integral, noting that $s \in PT$ so that the $a_{ij}$ are elements of $P$.]

\item Prove the following generalization of Proposition 28: Suppose $R$ is an integrally closed integral domain with field of fractions $k$ and $\alpha$ is an element of an extension field $K$ of $k$. Show that $\alpha$ is integral over $R$ if and only if $\alpha$ is algebraic over $k$ and the minimal polynomial $m_{\alpha,k}(x)$ for $\alpha$ over $k$ has coefficients in $R$. [If $\alpha$ is integral prove the conjugates of $\alpha$, i.e., the roots of $m_{\alpha,k}(x)$, are also integral, so the elementary symmetric functions of the conjugates are elements of $k$ that are integral over $R$.]

\item Suppose $R$ is an integrally closed integral domain with field of fractions $k$ and $p(x) \in R[x]$ is a monic polynomial. Show that if $p(x) = a(x)b(x)$ with monic polynomials $a(x), b(x) \in k[x]$ then $a(x), b(x) \in R[x]$ (compare to Gauss' Lemma, Proposition 5, Section 9.3). [See the previous exercise.]

\item Suppose $S$ is an integral domain that is integral over a ring $R$ as in the previous exercise. If $P$ is a prime ideal in $R$, let $s$ be any element in the ideal $PS$ generated by $P$ in $S$. Prove that, with the exception of the leading term, the coefficients of the minimal polynomial $m_{s,k}(x)$ for $s$ over $k$ are elements of $P$. [By Exercise 10, $m_{s,k}(x) \in R[x]$. Exercise 9 shows that $s$ is a root of a monic polynomial $p(x) = x^n + a_{n-1}x^{n-1} + \cdots + a_0$ with $a_0, \ldots, a_{n-1} \in P$. Use the previous exercise to show that $p(x) = m_{s,k}(x)b(x)$ with $b(x)$ in $R[x]$, and consider this equation in the integral domain $(R/P)[x]$.]

\item Let $K$ be a field of characteristic $0$ and let $A$ be a subring of $K$ maximal with respect to $1/2 \notin A$. (Such $A$ exists by Zorn's Lemma.) Let $F$ be the field of fractions of $A$ in $K$.
\begin{enumerate}
\item[(a)] Show that $K$ is algebraic over $F$. [If $t$ is transcendental over $F$, show that $1/2 \notin A[t]$.]
\item[(b)] Show that $A$ is integrally closed in $K$. [Show that $1/2$ is not in the integral closure of $A$ in $K$.]
\item[(c)] Deduce from (a) and (b) that $K = F$.
\end{enumerate}

\item Show that a field $K$ is the field of fractions of some proper subring of $K$ if and only if $K$ is not a subfield of the algebraic closure of a finite field. [If $K$ contains $t$ transcendental over $\F_p$ argue as in the preceding exercise with $1/t$ in place of $1/2$ to show that $K$ is the quotient field of some proper subring.]

\item Let $V$ be an affine algebraic set over an algebraically closed field $k$.

For (c) implies (a) use Exercise 37 in Section 9.6. Show (b) implies (d). For (d) implies (b) show the product $m_{a_1,k}(x_i) \cdots m_{a_N,k}(x_i)$ of the minimal polynomials of the $i$th coordinates $a_1, \ldots, a_N$ of the points in $Z_{\bar{k}}(I)$ is a nonzero polynomial in $\mathcal{I}(Z_{\bar{k}}(I))$ and apply Corollary 33.]

\item Let $I$ be a zero-dimensional ideal in $k[x_1, \ldots, x_n]$ and let $I'$ be the ideal generated by $I$ in $\bar{k}[x_1, \ldots, x_n]$ where $\bar{k}$ is the algebraic closure of $k$. Let $Z(I)$ be the zero set of $I$ in $k^n$ and let $Z_{\bar{k}}(I)$ be the zero set of $I$ (equivalently, of $I'$) in $\bar{k}^n$.
\begin{enumerate}
\item[(a)] Prove that $\abs{Z_{\bar{k}}(I)} = \dim_{\bar{k}} \bar{k}[x_1, \ldots, x_n]/\rad I'$. [Show that $\rad I'$ is the product of the maximal ideals corresponding to the points in $Z_{\bar{k}}$ and use the Chinese Remainder Theorem.]
\item[(b)] Show $\abs{Z(I)} \leq \dim_k k[x_1, \ldots, x_n]/I$. [One approach: use Exercise 43 in Section 1 and observe that $\dim_{\bar{k}} \bar{k}[x_1, \ldots, x_n]/\rad I' \leq \dim_{\bar{k}} \bar{k}[x_1, \ldots, x_n]/I'$.]
\end{enumerate}

\item Suppose $I$ is a zero-dimensional ideal in $k[x_1, \ldots, x_n]$, and suppose $I \cap k[x_i]$ is generated by the nonzero polynomial $h_i$ (cf.\ Exercise 26). Let $r_i$ be the product of the irreducible factors of $h_i$ (the `squarefree part' of $h_i$).
\begin{enumerate}
\item[(a)] Prove that $I + (r_1, \ldots, r_n) \subseteq \rad I$.
\item[(b)] \emph{(Radicals of zero-dimensional ideals for perfect fields)} If $k$ is a perfect field, prove that $\rad I = I + (r_1, \ldots, r_n)$. [Use induction on $n$. Write $r_1 = p_1 \cdots p_\ell$ with distinct irreducibles $p_i$ in $k[x_1]$. If $J = I + (r_1, \ldots, r_n)$ show that $J = J_1 \cap \cdots \cap J_\ell$ where $J_i = I + (p_i)$. Show for each $i$ that reduction modulo $p_i$ induces an isomorphism $k[x_1, \ldots, x_n]/J_i \cong K[x_2, \ldots, x_n]/J_i'$ where $K$ is the extension field $k[x]/(p_i)$ and $J_i' \subseteq K[x_2, \ldots, x_n]$ is the reduction of the ideal $J_i$ modulo $(p_i)$. Use Exercise 11 of Section 13.5 to show that the image of $r_j$ in $J_i' \cap K[x_j]$ remains a nonzero squarefree polynomial for each $j = 2, \ldots, n$ since $k$ is perfect. Conclude by induction that $J_i'$ is a radical ideal. Deduce that $J_i$ is a radical ideal, and finally that $J$ is a radical ideal.]
\item[(c)] Find the radicals of $(x^7 + x + y^3,\ x^4 + y^3 + y)$, $(x^3 - xy^2 + x,\ x^2 y + y^3)$, and $(x^4 + y^3,\ x^3 - xy + y^2)$ in $\mathbb{Q}[x,y]$ and of $(x^2 + y^2 z,\ x^2 y^2 + z^3,\ y^2 + z^2)$ in $\mathbb{Q}[x,y,z]$.
\item[(d)] Let $k = \F_p(t)$. Show that $I = (x^p + t,\ y^p - t)$ is a zero-dimensional ideal in $k[x,y]$ such that both $I \cap k[x]$ and $I \cap k[y]$ contain nonzero squarefree polynomials, but that $I$ is not a radical ideal (so the result in (b) need not hold if $k$ is not perfect). [Show that $x + y \in \rad I$ but $x + y \notin I$.]
\end{enumerate}
\end{exers}

