\begin{wex}{$\Spec$ of a field and of $\mathbb{Z}$}
Describe $\Spec R$ and $\mSpec R$ for $R$ a field and for $R=\mathbb{Z}$.
\wrec A field has a unique prime $(0)$; $\mathbb{Z}$ is a PID, so its nonzero primes are the $(p)$.
\wsol If $R$ is a field then $(0)$ is its only proper ideal that is prime (it is even maximal), so $\Spec R=\mSpec R=\{(0)\}$, a one-point space. For $R=\mathbb{Z}$: the primes are $(0)$ together with $(p)$ for each rational prime $p>0$. The maximal ideals are exactly the $(p)$, so $\mSpec\mathbb{Z}=\Spec\mathbb{Z}\setminus\{(0)\}$. Sanity check: $(0)$ is prime because $\mathbb{Z}$ is a domain but not maximal because $\mathbb{Z}$ is not a field; each $(p)$ is maximal since $\mathbb{Z}/p\mathbb{Z}=\F_p$ is a field. The lone non-maximal prime $(0)$ is the ``generic point'' we meet below.
\end{wex}

\begin{wex}{$\Spec\mathbb{Z}[x]$: the four families of primes}
List the prime ideals of $\mathbb{Z}[x]$ and identify the maximal ones.
\wrec $\mathbb{Z}[x]$ has Krull dimension $2$; primes come in chains of length $\le2$ governed by ``which integer prime, which polynomial mod it.''
\wsol The primes of $\mathbb{Z}[x]$ are: (a) $(0)$; (b) $(p)$ for a rational prime $p$; (c) $(f)$ where $f$ has content $1$ and is irreducible in $\mathbb{Q}[x]$; (d) $(p,g)$ where $p$ is prime and $g$ is monic and irreducible modulo $p$. Only the type-(d) ideals are maximal: $\mathbb{Z}[x]/(p,g)\cong\F_p[x]/(\overline g)$ is a finite field. Sanity check on dimension: a maximal chain is $(0)\subsetneq(p)\subsetneq(p,g)$ of length $2$, matching $\dim\mathbb{Z}[x]=\dim\mathbb{Z}+1=2$; and $(0)\subsetneq(f)\subsetneq(p,g)$ when $g\mid f\bmod p$ gives another length-$2$ chain.
\end{wex}

\begin{proof}[Idea]
$V(\fa)=V(\rad\fa)$ because a prime containing $\fa$ contains $\rad\fa$; and $\rad\fa=\bigcap_{\fa\subseteq\fp}\fp$ (the radical is the intersection of the primes above it) gives $I(V(\fa))=\rad\fa$. For (2): $\fp\supseteq\fa\fb$ and $\fp$ prime force $\fp\supseteq\fa$ or $\fp\supseteq\fb$. Inclusion-reversal is immediate from $\fa\subseteq\fb\Rightarrow V(\fb)\subseteq V(\fa)$.
\end{proof}

\begin{proof}[Idea]
(1) $f$ a unit $\iff$ no prime contains it; $f$ nilpotent $\iff$ every prime contains it ($\nil R=\bigcap\fp$). (3) $D(f)\subseteq\bigcup D(g_i)$ says every prime containing $(g_1,\dots,g_n)$ contains $f$, i.e.\ $f\in\bigcap_{(g_i)\subseteq\fp}\fp=\rad(g_1,\dots,g_n)$. (4) Localization $R\to R_f$ gives a bijection of primes of $R_f$ with primes of $R$ missing $\{1,f,f^2,\dots\}$, i.e.\ with $D(f)$, and it is bicontinuous. (5) Quasi-compactness: if $X=\bigcup_i D(g_i)$ then $(g_i)=R$ (no prime contains all $g_i$), so $1=\sum_{j=1}^m a_jg_{i_j}$ is a finite relation, and the corresponding $D(g_{i_1}),\dots,D(g_{i_m})$ already cover $X$.
\end{proof}

\begin{method}{Reading $\Spec$ from the ideal theory of $R$}
To analyze $\Spec R$ as a space: (i) closed points $=$ maximal ideals; (ii) the closure of $\{\fp\}$ is $V(\fp)=\{\fq:\fq\supseteq\fp\}$, so smaller primes are ``more generic''; (iii) $X$ irreducible $\iff\nil R$ prime; irreducible components $\leftrightarrow$ minimal primes of $R$; (iv) test separation/connectedness via idempotents and basic opens; (v) compute fibers of $\varphi^*\colon\Spec S\to\Spec R$ over $\fp$ by factoring in $S\otimes_R\kappa(\fp)$, where $\kappa(\fp)=\Frac(R/\fp)$.
\end{method}

\begin{wex}{Closure of a point; closed points are maximal}
Compute the closure $\overline{\{\fp\}}$ of a point, and show $\fp$ is closed iff $\fp$ is maximal.
\wrec The smallest closed set containing $\fp$ is $V(\fp)$; a point is closed iff it equals its closure.
\wsol The closed sets containing $\fp$ are the $V(\fa)$ with $\fa\subseteq\fp$, the smallest being $V(\fp)=\{\fq:\fq\supseteq\fp\}$. Hence $\overline{\{\fp\}}=V(\fp)$. So $\{\fp\}$ is closed $\iff V(\fp)=\{\fp\}\iff$ no prime strictly contains $\fp$ $\iff\fp$ is maximal. Sanity check: in $\Spec\mathbb{Z}$, $\overline{\{(0)\}}=V((0))=\Spec\mathbb{Z}$ (so $(0)$ is dense), while $\overline{\{(p)\}}=\{(p)\}$ since $(p)$ is maximal. The topology is generally not $T_1$ (non-closed points exist) but it is always $T_0$.
\end{wex}

\begin{wex}{$\Spec R$ is $T_0$ but rarely Hausdorff}
Show any two distinct points of $\Spec R$ are topologically distinguishable, yet $\Spec\mathbb{Z}$ is not Hausdorff.
\wrec $T_0$ means: for $\fp\ne\fq$ some open set contains one but not the other. Hausdorff fails because of the generic point.
\wsol If $\fp\ne\fq$, say $f\in\fp\setminus\fq$; then $D(f)$ contains $\fq$ but not $\fp$, giving $T_0$. For $\mathbb{Z}$: any nonempty open set is the complement of a finite set of closed points (since proper closed sets $V(\fa)$, $\fa\ne0$, are finite), so any two nonempty opens meet -- no disjoint neighborhoods exist, hence not Hausdorff. Sanity check: in $\Spec\mathbb{Z}$ every nonempty open contains $(0)$, the generic point, so opens can never be disjoint.
\end{wex}

\begin{wex}{Quasi-compact but not compact: an infinite cover with no finite subcover of an open subset}
Show $\Spec R$ is quasi-compact, but exhibit an open subset of some $\Spec R$ whose cover has no finite subcover.
\wrec $\Spec R$ itself is always quasi-compact by the unit-relation argument; non-quasi-compact \emph{open subsets} arise in non-Noetherian rings.
\wsol Quasi-compactness of $X$ was proved above. For the failure on an open subset, take $R=k[x_1,x_2,\dots]$ (infinitely many variables) and $U=\bigcup_{i\ge1}D(x_i)$, the complement of the closed set $V(x_1,x_2,\dots)$. Given any finite subfamily $D(x_{i_1}),\dots,D(x_{i_m})$, consider the prime $\fp=(x_{i_1},\dots,x_{i_m})$ (prime since $R/\fp\cong k[x_k:k\notin\{i_1,\dots,i_m\}]$ is a domain). It contains each $x_{i_j}$, so $\fp\notin D(x_{i_j})$ for every $j$; yet $\fp\in U$, since it omits any $x_k$ with $k\notin\{i_1,\dots,i_m\}$, whence $\fp\in D(x_k)\subseteq U$. Thus the finite union fails to cover $U$, and no finite subcover exists. Sanity check: $U$ is quasi-compact iff it is a \emph{finite} union of basic opens (Section~15.8, Exercise 12); here it is genuinely infinite, consistent with $R$ non-Noetherian.
\end{wex}

\begin{proof}[Idea]
(1) If $\rad\fa=\fp$ is prime and $V(\fp)=V(\fb)\cup V(\fc)=V(\fb\cap\fc)$, then $\fp=\rad(\fb\cap\fc)\supseteq\fb\fc$, so $\fp\supseteq\fb$ or $\fp\supseteq\fc$, forcing $V(\fp)$ equal to one piece. Conversely if $\rad\fa$ is not prime, pick $fg\in\rad\fa$ with $f,g\notin\rad\fa$; then $V(\fa)=V(\fa+(f))\cup V(\fa+(g))$ is a proper decomposition. (2) is (1) with $\fa=0$. (3) An irreducible component is a maximal irreducible closed set $=V(\fp)$ with $\fp$ minimal, since $V(\fp)\subseteq V(\fq)\iff\fq\subseteq\fp$.
\end{proof}

\begin{wex}{$\Spec\mathbb{Z}/12\mathbb{Z}$ and the nilradical}
Compute $\Spec(\mathbb{Z}/12\mathbb{Z})$ as a topological space and verify it equals $\Spec$ of its reduction.
\wrec $\mathbb{Z}/12\mathbb{Z}$ is Artinian; its primes are the maximal ideals coming from the prime divisors of $12$. The nilradical kills the square factor.
\wsol $12=2^2\cdot3$, so $\mathbb{Z}/12\mathbb{Z}\cong\mathbb{Z}/4\mathbb{Z}\times\mathbb{Z}/3\mathbb{Z}$ by CRT. Its primes are $(2)/(12)$ and $(3)/(12)$ -- two points, both closed (maximal), with the discrete topology. The nilradical is $(6)/(12)$ (since $6^2=36\equiv0$), and $R_{\mathrm{red}}=\mathbb{Z}/12\mathbb{Z}/(6)\cong\mathbb{Z}/6\mathbb{Z}\cong\F_2\times\F_3$, which again has exactly the two points $(2),(3)$. Sanity check: $\abs{\Spec}=2=$ number of distinct prime divisors of $12$; squaring the $2$ (from $4$) added nilpotents but no new points, confirming $\Spec R=\Spec R_{\mathrm{red}}$.
\end{wex}

\begin{wex}{Generic point of $\Spec k[x,y]$ and the curve points}
With $R=k[x,y]$ ($k$ algebraically closed), identify the generic point and describe the closure of $(f)$.
\wrec Primes are $(0)$, the $(f)$ for $f$ irreducible, and the maximals $(x-a,y-b)$; closure of $\fp$ is $V(\fp)$.
\wsol $(0)$ is prime (the domain $k[x,y]$), and $\overline{\{(0)\}}=V(0)=\Spec R$, so $(0)$ is the generic point of the irreducible space $\Spec k[x,y]$ ($=$ the plane $\Aff^2$). For an irreducible $f$, $\overline{\{(f)\}}=V(f)=\{(f)\}\cup\{(x-a,y-b):f(a,b)=0\}$: the point $(f)$ itself together with exactly the closed points lying on the curve $f=0$. Sanity check: $V(f)$ is irreducible because $(f)$ is prime; its generic point $(f)$ is the curve ``as a whole,'' its closed points are the geometric points on it -- precisely the classical picture of Section~15.3 with one extra generic dot.
\end{wex}

\begin{wex}{An irreducible component count: $\Spec k[x,y]/(xy)$}
Show $X=\Spec k[x,y]/(xy)$ is connected but reducible, with two irreducible components.
\wrec $(xy)=(x)\cap(y)$ is radical but not prime; minimal primes give components.
\wsol In $S=k[x,y]/(xy)$ the minimal primes are $(x)$ and $(y)$ (since $(xy)=(x)\cap(y)$ and $x\cdot y=0$). Their closures $V(x)$ and $V(y)$ are the two coordinate axes, each homeomorphic to $\Spec k[x]\cong\Aff^1$. So $X=V(x)\cup V(y)$ is reducible with two components. It is connected because the two axes meet at the origin $(x,y)/(xy)$. Sanity check: $\nil S=0$ (the ring is reduced) yet $\nil S$ is not prime, matching ``$X$ irreducible $\iff\nil$ prime''; two minimal primes $=$ two components.
\end{wex}

\begin{wex}{$\Spec R$ connected $\iff$ no nontrivial idempotent}
Show $\Spec R$ is disconnected iff $R\cong R_1\times R_2$ with $R_i\ne0$ iff $R$ has an idempotent $e\ne0,1$.
\wrec A clopen decomposition of $X$ corresponds to a product decomposition of $R$ via an idempotent.
\wsol If $R=R_1\times R_2$ then $X=\Spec R$ is the disjoint union $V(0\times R_2)\sqcup V(R_1\times0)$ of two nonempty clopen pieces $\cong\Spec R_1,\Spec R_2$ (a prime of a product lives in one factor). Conversely a disconnection $X=Y_1\sqcup Y_2$ into clopen sets gives complementary idempotents: $Y_i=D(e_i)=V(1-e_i)$ with $e_1+e_2=1$, $e_1e_2=0$, so $e=e_1$ is a nontrivial idempotent and $R\cong Re_1\times Re_2$. Sanity check: a local ring or a domain has only the idempotents $0,1$, so its spectrum is connected -- e.g.\ $\Spec\mathbb{Z}$ is connected, with generic point $(0)$ gluing all closed points together.
\end{wex}

\begin{wex}{$\Spec$ of a product is a disjoint union}
For $R=\mathbb{Z}/6\mathbb{Z}\cong\F_2\times\F_3$ and for $R=k\times k\times k$, describe $\Spec R$ topologically.
\wrec $\Spec(R_1\times R_2)=\Spec R_1\sqcup\Spec R_2$ as spaces, each piece clopen.
\wsol $\mathbb{Z}/6\mathbb{Z}\cong\F_2\times\F_3$: $\Spec=\Spec\F_2\sqcup\Spec\F_3=\{(2)\}\sqcup\{(3)\}$, two isolated (clopen) points. For $k\times k\times k$: three isolated points, the discrete three-point space. Sanity check: $\abs{\Spec(k^n)}=n$ with the discrete topology; idempotents $e_i=(0,\dots,1,\dots,0)$ are the nontrivial idempotents witnessing total disconnection, matching the previous example.
\end{wex}

\begin{proof}[Idea]
$\varphi^{-1}(\fq)$ is prime: if $ab\in\varphi^{-1}(\fq)$ then $\varphi(a)\varphi(b)\in\fq$, so one of $\varphi(a),\varphi(b)\in\fq$. The preimage formula: $\varphi^{*}(\fq)\in V(\fa)\iff\fa\subseteq\varphi^{-1}(\fq)\iff\varphi(\fa)\subseteq\fq\iff\fq\in V(\varphi(\fa)S)$. Since preimages of closed sets are closed, $\varphi^{*}$ is continuous; the basic-open statement is the special case $\fa=(f)$.
\end{proof}

\begin{wex}{The inclusion $\mathbb{Z}\hookrightarrow\mathbb{Z}[i]$ and its fibers}
Describe $\varphi^{*}\colon\Spec\mathbb{Z}[i]\to\Spec\mathbb{Z}$ for $\varphi\colon\mathbb{Z}\hookrightarrow\mathbb{Z}[i]$, computing the fiber over each $(p)$.
\wrec Fibers of $\varphi^{*}$ over $(p)$ are read off from the factorization of $p$ in the Gaussian integers, i.e.\ from $p\bmod4$.
\wsol The fiber over $(p)$ is $\{\fq\in\Spec\mathbb{Z}[i]:\fq\cap\mathbb{Z}=(p)\}$, the primes of $\mathbb{Z}[i]$ above $p$. By the theory of $\mathbb{Z}[i]$ (a PID): if $p=2$, $2=-i(1+i)^2$ is ramified, one point $(1+i)$; if $p\equiv3\pmod4$, $p$ is inert, one point $(p)$; if $p\equiv1\pmod4$, $p=\pi\overline\pi$ splits, two points $(\pi),(\overline\pi)$. Over $(0)$ lies the single generic point $(0)$. Sanity check: the residue field $\mathbb{Z}[i]/\fq$ has order $p^f$ with $f=1$ (split/ramified) or $f=2$ (inert), and $\sum_{\fq\mid p}e_\fq f_\fq=2=[\mathbb{Q}(i):\mathbb{Q}]$ in each case ($e=2,f=1$ ramified; $e=f=1$ twice split; $e=1,f=2$ inert).
\end{wex}

\begin{wex}{The projection $k[x]\hookrightarrow k[x,y]$ and vertical-line fibers}
For $k$ algebraically closed and $\varphi\colon k[x]\hookrightarrow k[x,y]$, describe $\varphi^{*}\colon\Spec k[x,y]\to\Spec k[x]$ and the fiber over $(x-a)$.
\wrec $\varphi^{*}$ is the projection $\Aff^2\to\Aff^1$; the fiber over a point of the line is the vertical line above it (plus its generic point).
\wsol $\varphi^{*}(\fq)=\fq\cap k[x]$. Over the closed point $(x-a)\in\Spec k[x]$ the fiber consists of the primes $\fq$ of $k[x,y]$ with $\fq\cap k[x]=(x-a)$: these are the maximal ideals $(x-a,y-b)$ for $b\in k$ together with the height-$1$ prime $(x-a)$ itself (the whole vertical line, its generic point). Over $(0)$ the fiber adds the generic point $(0)$ of the plane and all the ``slanted'' curve primes $(f)$ with $f\notin k[x]$. Sanity check: setting $x=a$, the fiber ring is $k[x,y]/(x-a)\cong k[y]$, whose spectrum is the $y$-line $\{(y-b)\}\cup\{(0)\}$ -- exactly the points found.
\end{wex}

\begin{wex}{Closed immersion: $\Spec R/\fa\hookrightarrow\Spec R$}
Show the quotient map $R\to R/\fa$ induces a homeomorphism of $\Spec R/\fa$ onto the closed set $V(\fa)\subseteq\Spec R$.
\wrec Primes of $R/\fa$ correspond to primes of $R$ containing $\fa$, order-preservingly.
\wsol By the correspondence theorem, $\pi\colon R\to R/\fa$ gives $\fq\mapsto\pi^{-1}(\fq)$, a bijection from $\Spec R/\fa$ onto $\{\fp\supseteq\fa\}=V(\fa)$, preserving inclusions and hence the subspace topology. Thus $\pi^{*}$ is a homeomorphism onto $V(\fa)$. Sanity check: taking $\fa=\nil R$ recovers $\Spec R_{\mathrm{red}}\cong\Spec R$ (here $V(\nil R)=X$); taking $\fa=\fp$ prime gives $\Spec R/\fp\cong V(\fp)=\overline{\{\fp\}}$, the irreducible closed set with generic point $\fp$.
\end{wex}

\begin{wex}{Localization as an open immersion: $\Spec R_f\hookrightarrow\Spec R$}
Show the localization map $R\to R_f$ realizes $\Spec R_f$ as the open set $D(f)$.
\wrec Primes of $R_f$ correspond to primes of $R$ not containing $f$; that set is $D(f)$.
\wsol The map $R\to R_f$ inverts $f$, so $\fq\mapsto\fq\cap R$ is a bijection $\Spec R_f\to\{\fp:f\notin\fp\}=D(f)$, bicontinuous since every ideal of $R_f$ is extended. Thus localization at $f$ is the algebraic operation realizing the \emph{open} subset $D(f)$, dual to quotient realizing the \emph{closed} subset $V(\fa)$. Sanity check: $R=\mathbb{Z}$, $f=6$ gives $R_6=\mathbb{Z}[1/6]$ and $D(6)=\Spec\mathbb{Z}\setminus\{(2),(3)\}=\{(0)\}\cup\{(p):p\ne2,3\}$ -- precisely the primes missing $2$ and $3$, the points where $6$ is invertible.
\end{wex}

\begin{wex}{A morphism with non-surjective $\varphi^{*}$, and a non-local subtlety}
For $\varphi\colon\mathbb{Z}\to\mathbb{Z}_{(2)}$ (localization at $(2)$), describe $\varphi^{*}$ and note which primes of $\mathbb{Z}$ are hit.
\wrec Localizing at the prime $(2)$ keeps only primes contained in $(2)$, i.e.\ $(0)$ and $(2)$.
\wsol $\mathbb{Z}_{(2)}=\{a/b:b\text{ odd}\}$ is local with maximal ideal $2\mathbb{Z}_{(2)}$ and primes $(0)\subsetneq(2)\mathbb{Z}_{(2)}$. So $\Spec\mathbb{Z}_{(2)}=\{(0),(2)\}$ and $\varphi^{*}$ embeds it as the two points $(0),(2)$ of $\Spec\mathbb{Z}$; every other $(p)$ is missed. Sanity check: $\Spec$ of a local ring has a unique closed point (here $(2)$) and is connected; $\varphi^{*}$ here is the inclusion of the ``germ of $\Spec\mathbb{Z}$ near $(2)$.'' This local example is the source of the local-homomorphism condition needed below for scheme morphisms.
\end{wex}

\begin{proof}[Idea]
$\mathcal O_X(D(f))\cong R_f$ is a sheaf-gluing computation: a locally-fraction section on $D(f)$ is patched from compatible fractions $a_i/g_i^{n}$ on a finite cover $D(g_i)$ (using quasi-compactness), and the identities $f^{N}=\sum b_ig_i^{n}$ assemble a single global $a/f^{M}$. The stalk is the direct limit $\varinjlim_{\fp\in D(f)}\mathcal O_X(D(f))=\varinjlim_{f\notin\fp}R_f=R_\fp$. The local-homomorphism condition is forced because $\varphi^{-1}(\fq)=\fp$ means $\varphi_\fp^{-1}(\fq S_\fq)=\fp R_\fp$; the example $\mathbb{Z}_{(2)}\hookrightarrow\mathbb{Q}$ shows a non-local map of stalks does \emph{not} come from a ring map of the right spectra.
\end{proof}

\begin{remark}
The terminology is geometric: above each point $\fp$ sits the local ring $R_\fp$ -- the ``stalk'' (as of wheat) -- and a section over $U$ is a choice of germ at each point, locally given by one fraction; the totality is the ``sheaf'' (bundle) of stalks. Localization is literally ``concentrating near a point'': $R_\fp$ is the ring of rational functions defined in some Zariski neighborhood of $\fp$, and $\kappa(\fp)$ is the field of values at the generic point of $V(\fp)$. A scheme is glued from affine charts $(\Spec R_i,\mathcal O)$ exactly as a manifold is glued from Euclidean charts.
\end{remark}

\begin{wex}{Structure sheaf on $\Spec\mathbb{Z}$}
Compute $\mathcal O(D(n))$, the global sections, and the stalks for $X=\Spec\mathbb{Z}$.
\wrec $\mathbb{Z}$ is a PID, so every open is basic: $D(n)=\{\fp:n\notin\fp\}$, and $\mathcal O(D(n))=\mathbb{Z}_n=\mathbb{Z}[1/n]$.
\wsol For $n\ge1$, $D(n)=\{(p):p\nmid n\}\cup\{(0)\}$ and $\mathcal O(D(n))=\mathbb{Z}[1/n]=\{a/b\in\mathbb{Q}:p\mid b\Rightarrow p\mid n\}$. Global sections: $\mathcal O(X)=\mathcal O(D(1))=\mathbb{Z}$. Stalks: $\mathcal O_{(p)}=\mathbb{Z}_{(p)}$ (rationals with denominator prime to $p$) and $\mathcal O_{(0)}=\mathbb{Z}_{(0)}=\mathbb{Q}$ at the generic point. All restriction maps are the evident inclusions inside $\mathbb{Q}$. Sanity check: $\mathcal O(X)=\mathbb{Z}$ recovers ``functions regular everywhere $=$ the ring,'' the arithmetic analogue of ``polynomial functions on $\Aff^n$ regular everywhere are polynomials.''
\end{wex}

\begin{wex}{Structure sheaf on $\Spec$ of a local ring}
For the local ring $R=\mathbb{Z}_{(2)}$ describe the open sets, sections, and stalks of $\Spec R$.
\wrec $\Spec R=\{(0),(2)\}$ with $(2)$ the unique closed point; $\{(0)\}=D(2)$ is the only nontrivial open.
\wsol Open sets: $\varnothing$, $\{(0)\}=D(2)$, and $X=\{(0),(2)\}$. Sections: $\mathcal O(X)=R=\mathbb{Z}_{(2)}$ (global sections $=$ the ring) and $\mathcal O(D(2))=R_2=\mathbb{Q}$. Stalks: $\mathcal O_{(0)}=R_{(0)}=\mathbb{Q}$, $\mathcal O_{(2)}=R_{(2)}=R$ itself (already local). Sanity check: the stalk at the closed point of $\Spec$ of a local ring is the ring itself, and $\Spec$ is connected with a unique generic point $(0)$ specializing to $(2)$.
\end{wex}

\begin{wex}{Values, the nilradical, and functions not determined pointwise}
In $R=k[x]/(x^2)$ show two distinct elements have identical values at every point of $\Spec R$.
\wrec $\Spec R$ is a single point; values lie in $R/\fp$, and the difference of equal-valued elements lies in $\nil R$.
\wsol $R=k[x]/(x^2)$ is local with unique prime $\fp=(x)$ (the nilradical), $R_{\mathrm{red}}=k$. So $\Spec R=\{(x)\}$ is one point and $\kappa(\fp)=R/(x)=k$. The elements $0$ and $\overline x$ are distinct in $R$ but both have value $0$ in $R/(x)=k$, since $\overline x\in\nil R$. Sanity check: $f,g$ agree at all points $\iff f-g\in\nil R$; here $\overline x-0=\overline x$ is nilpotent ($\overline x^2=0$), so the two functions are pointwise equal yet algebraically different -- the nilpotent ``thickening'' invisible to $\Spec$ but recorded in $\mathcal O$.
\end{wex}

\begin{wex}{$\Spec\mathbb{Z}[x]$ fibered over $\Spec\mathbb{Z}$ via a cubic}
For $f=x^3+x+1$, locate the closed points of $V(f)\subseteq\Spec\mathbb{Z}[x]$ in the fibers over $(2),(3),(5)$.
\wrec Closed points of $V(f)$ over $(p)$ are the maximals $(p,g)$ with $g\mid\overline f$ in $\F_p[x]$, one per irreducible factor.
\wsol Reduce $f$ modulo each prime: $f\equiv x^3+x+1\pmod2$ is irreducible (no root in $\F_2$, since $f(0)=f(1)=1$), giving one closed point $(2,x^3+x+1)$; modulo $3$ the only root is $x=1$ ($f(0)=1$, $f(1)=0$, $f(2)=2$), so $f\equiv(x-1)(x^2+x+2)\pmod3$ with $x^2+x+2$ irreducible over $\F_3$, giving the two points $(3,x-1)$ and $(3,x^2+x+2)$; modulo $5$, $f$ has no root ($f(0),\dots,f(4)=1,3,1,1,4$), so as a rootless cubic it is irreducible, giving one closed point $(5,x^3+x+1)$. Sanity check: the number of closed points over $(p)$ equals the number of \emph{distinct} irreducible factors of $f\bmod p$ ($1,2,1$ respectively), and the splitting type is governed by the Galois group of $f$ over $\mathbb{Q}$ acting on the roots ($f$ is irreducible over $\mathbb{Q}$, as it has no rational root).
\end{wex}

\begin{wex}{$\Spec k[x]$ over an algebraically closed $k$, and a non-closed comparison}
Describe $\Spec k[x]$ for $k$ algebraically closed, and contrast with $\Spec\mathbb{R}[x]$.
\wrec Over $\overline k$ every nonzero prime of $k[x]$ is $(x-a)$; over $\mathbb{R}$ there are also degree-$2$ primes.
\wsol For $k=\overline k$: $\Spec k[x]=\{(0)\}\cup\{(x-a):a\in k\}$, the generic point plus the affine line $\Aff^1(k)=\mSpec$. For $R=\mathbb{R}[x]$: primes are $(0)$, the $(x-a)$ with $a\in\mathbb{R}$ (residue field $\mathbb{R}$), and the $(x^2+bx+c)$ with negative discriminant (residue field $\mathbb{C}$); the latter ``hide'' a conjugate pair of complex points. Sanity check: $\Spec\mathbb{R}[x]=\{(0)\}\sqcup\mSpec\mathbb{R}[x]$, where $\mSpec\mathbb{R}[x]=\mathbb{R}\sqcup\{\text{conjugate pairs in }\mathbb{C}\setminus\mathbb{R}\}$ is in bijection with $\mathbb{C}/(\text{complex conjugation})$ -- exactly the failure of $k$ not being algebraically closed, and the reason the Nullstellensatz bijection $\mSpec\leftrightarrow$ points needs $k=\overline k$.
\end{wex}

