\end{enumerate}

\item Suppose $I = Q_1 \cap \cdots \cap Q_n$ is a minimal primary decomposition of the ideal $I$ in the Noetherian ring $R$ with $P_i = \rad Q_i$, $i = 1, \ldots, n$. This exercise proves that $\Ass_R(R/I) = \{P_1, \ldots, P_n\}$.
\begin{enumerate}
\item[(a)] Prove that the natural projection homomorphisms induce an injection of $R/I$ into $R/Q_1 \oplus \cdots \oplus R/Q_n$ and deduce that $\Ass_R(R/I) \subseteq \{P_1, \ldots, P_n\}$. [Use Exercise 34 in Section 1 and the previous exercise.]
\item[(b)] Let $Q_i' = \bigcap_{j \neq i} Q_j$. Show that the minimality of the decomposition implies that $0 \neq Q_i'/I = (Q_i' + Q_i)/Q_i \subseteq R/Q_i$. Deduce that $\Ass_R(Q_i'/I) = \{P_i\}$. [Use Exercises 33--34 in Section 1 and the previous exercise.] Deduce that $P_i \in \Ass_R(R/I)$, so that $\Ass_R(R/I) = \{P_1, \ldots, P_n\}$. [Use $Q_i'/I \subseteq R/I$ and Exercise 34 in Section 1.]
\end{enumerate}

\item Let $I$ be the ideal $(x^2, xy, xz, yz)$ in $R = k[x, y, z]$. Prove that $\Ass_R(R/I)$ consists of the primes $\{(x, y), (x, z), (x, y, z)\}$.

\item (Spec for Quadratic Integer Rings) Let $R$ be the ring of integers in the quadratic field $K = Q(\sqrt{D})$ where $D$ is a squarefree integer and let $P$ be a nonzero prime ideal in $R$. This exercise shows how the prime ideals in $R$ are determined explicitly from the primes $(p)$ in $Z$, giving in particular a description of $\Spec R$ fibered over $\Spec Z$. As in the discussion and example following Theorem 29, we have $R = Z[\omega]$ where $\omega = \sqrt{D}$ if $D \equiv 2, 3 \pmod 4$ (respectively, $\omega = (1 + \sqrt{D})/2$ if $D \equiv 1 \pmod 4$), with minimal polynomial $m_\omega(x) = x^2 - D$ (respectively, $m_\omega(x) = x^2 - x + (1 - D)/4$), and $P \cap Z = pZ$ is a nonzero prime ideal of $Z$.
\begin{enumerate}
\item[(a)] For any prime $p$ in $Z$ show that $R/pR \cong Z[x]/(p, m_\omega(x)) \cong \F_p[x]/(\overline{m_\omega}(x))$ as rings, where $\overline{m_\omega}(x)$ is the reduction of $m_\omega(x)$ modulo $p$. Deduce that there is a prime ideal $P$ in $R$ with $P \cap Z = (p)$ (this gives an alternate proof of Theorem 26(2) in this case).
\item[(b)] Use the isomorphism in (a) to prove that $P$ is determined explicitly by the factorization of $\overline{m_\omega}(x)$ modulo $p$:
\begin{enumerate}
\item[(i)] If $\overline{m_\omega}(x) = (x - a)^2 \bmod p$ where $a \in Z$ then $P = (p, \omega - a)$ and $pR = P^2$. Show that this case occurs only for the finitely many primes $p$ dividing the discriminant of $m_\omega(x)$.
\item[(ii)] If $\overline{m_\omega}(x) = (x - a)(x - b) \bmod p$ with integers $a, b \in Z$ that are distinct modulo $p$ then $P$ is either $P_1 = (p, \omega - a)$ or $P_2 = (p, \omega - b)$ and $P_1, P_2$ are distinct prime ideals in $R$ with $pR = P_1 P_2$.
\item[(iii)] If $\overline{m_\omega}(x)$ is irreducible modulo $p$ then $P = pR$.
\end{enumerate}
\item[(c)] Show that the picture for $\Spec R$ over $\Spec Z$ for any $D$ is similar to that for the case $R = Z[i]$ when $D = -1$: there is precisely one nonclosed point $(0) \in \Spec R$ over $(0) \in \Spec Z$, precisely one closed point $P \in \Spec R$ over each of the primes $(p)$ in $\Spec Z$ in (i) (called ramified primes) and over the primes in (iii) (called inert primes), and precisely two closed points over the primes in (ii) (called split primes).
\end{enumerate}
\end{exers}

