\begin{theorem}[{Krull intersection theorem}]\label{thm:krull@c15}
Let $R$ be Noetherian, $\fa$ an ideal, $M$ a finitely generated $R$-module, and $E=\bigcap_{n\ge1}\fa^n M$. Then $\fa E=E$; equivalently $E$ is annihilated by some element of $1+\fa$. Consequently:
\begin{enumerate}[label=\textup{(\arabic*)},leftmargin=*]
\item if $\fa\subseteq\Jac(R)$ (the Jacobson radical), then $\bigcap_n\fa^n M=0$, so the $\fa$-adic topology of $M$ is Hausdorff;
\item (local case) if $(R,\fm)$ is Noetherian local, then $\bigcap_n\fm^n=0$ and $\bigcap_n\fm^n M=0$;
\item if $R$ is a Noetherian domain and $\fa\neq(1)$, then $\bigcap_n\fa^n=0$.
\end{enumerate}
\end{theorem}

\begin{proof}[Idea]
By Artin--Rees the filtration $(\fa^n M\cap E)$ is stable, but $\fa^n M\cap E=E$ for all $n$, so stability forces $\fa E=\fa^n M\cap E$ to equal $E$ from some point on, i.e.\ $\fa E=E$. Now $E$ is a finitely generated module with $\fa E=E$, so by the determinant trick (Cayley--Hamilton form of Nakayama) some $x\equiv1\pmod\fa$ kills $E$. If $\fa\subseteq\Jac(R)$ then $x=1-a$ with $a\in\Jac(R)$ is a unit, forcing $E=0$, giving (1) and its special case (2). If $R$ is a domain and $\fa\neq(1)$, then $1+\fa$ contains no zero-divisors and $x\neq0$, so again $E=0$, giving (3).
\end{proof}

\begin{remark}
Both Krull's theorem and the exactness of completion are downstream of Artin--Rees, which is why A\&M give that lemma the central role. The hypotheses cannot be dropped: over the non-Noetherian $C^\infty$ ring the maximal ideal $\fa$ at $0$ has $\bigcap_n\fa^n\neq0$ (the flat function $e^{-1/x^2}$), and no element of $1+\fa$ kills $e^{-1/x^2}$ (such an element $u$ would vanish at every $x\neq0$, hence at $0$ by continuity, while $u(0)=1$), so Krull's conclusion fails -- the obstruction is exactly non-Noetherianity.
\end{remark}

\begin{wex}{Krull intersection in a Noetherian local domain}
Let $(R,\fm)$ be a Noetherian local domain. Show $\bigcap_n\fm^n=0$.
\wrec $\fm\subseteq\Jac(R)=\fm$ (local), and $R$ is a domain, so Theorem~\ref{thm:krull@c15}(2)/(3) applies.
\wsol Put $E=\bigcap_n\fm^n$. By Krull $\fm E=E$ with $E$ finitely generated, so Nakayama (with $\fm\subseteq\Jac R$) gives $E=0$. Sanity check: in $R=k[x]_{(x)}$, $\fm=(x)$, indeed $\bigcap_n(x)^n=0$ -- a germ vanishing to all orders is the zero germ; and the completion $\widehat R=k[[x]]$ is Hausdorff, consistent with $E=0$.
\end{wex}

\begin{wex}{Krull's theorem can fail for non-domains without the radical hypothesis}
Show $\bigcap_n\fa^n\neq0$ is possible when $\fa\not\subseteq\Jac(R)$, using $R=\mathbb{Z}/6\mathbb{Z}$, $\fa=(2)$.
\wrec Theorem~\ref{thm:krull@c15}(1) needs $\fa\subseteq\Jac(R)$; in a product of fields $\Jac(R)=0$, so the conclusion is not guaranteed.
\wsol In $R=\mathbb{Z}/6\mathbb{Z}\cong\mathbb{Z}/2\mathbb{Z}\times\mathbb{Z}/3\mathbb{Z}$, the ideal $\fa=(2)$ corresponds to $0\times\mathbb{Z}/3\mathbb{Z}$, which is idempotent: $\fa^2=\fa$. Hence $\bigcap_n\fa^n=\fa\neq0$. Here $\Jac(R)=0$ (a product of fields), so $\fa\not\subseteq\Jac(R)$ and Krull(1) does not apply. The element of $1+\fa$ annihilating $E=\fa$: take $1+2=3$, and indeed $3\cdot\fa=3\cdot(0\times\mathbb{Z}/3\mathbb{Z})=0$, so $\fa E=E$ with annihilator $3\in1+\fa$, consistent with the theorem's $\fa E=E$ conclusion. Sanity check: the theorem's true assertion ($\fa E=E$) holds; only the \emph{stronger} $E=0$ fails, exactly because the radical hypothesis is absent.
\end{wex}

\begin{wex}{The associated graded of $\mathbb{Z}$ at $(p)$}
Compute $\gr_{(p)}(\mathbb{Z})$.
\wrec $\gr_\fa(R)=\bigoplus_n\fa^n/\fa^{n+1}$; here $\fa^n=p^n\mathbb{Z}$.
\wsol Each graded piece $p^n\mathbb{Z}/p^{n+1}\mathbb{Z}\cong\mathbb{Z}/p\mathbb{Z}=\F_p$, generated by the class $\bar p^{\,n}$ of $p^n$. Multiplication sends $\bar p^{\,m}\cdot\bar p^{\,n}\mapsto\bar p^{\,m+n}$, so $\gr_{(p)}(\mathbb{Z})\cong\F_p[t]$ with $t=\bar p$ the class of $p$ in degree $1$. Sanity check: $\F_p[t]$ is a Noetherian domain (matching Proposition~\ref{prop:grnoeth@c15}(ii)); its degree-$0$ part $\F_p=\mathbb{Z}/p\mathbb{Z}=R/\fa$, as required.
\end{wex}

\begin{wex}{The associated graded of a regular local ring is a polynomial ring}
For $R=k[x_1,\dots,x_n]_{(x_1,\dots,x_n)}$, $\fm=(x_1,\dots,x_n)$, identify $\gr_\fm(R)$.
\wrec $\gr_\fm(R)=\bigoplus_d\fm^d/\fm^{d+1}$; the $d$-th piece is the space of degree-$d$ forms in the $x_i$.
\wsol $\fm^d/\fm^{d+1}$ has basis the monomials of total degree $d$ in $x_1,\dots,x_n$, and the product respects degree, so $\gr_\fm(R)\cong k[x_1,\dots,x_n]$ as a graded ring (a polynomial ring, $n$ variables in degree $1$). Sanity check: $\dim_k\fm^d/\fm^{d+1}=\binom{d+n-1}{n-1}$, the number of degree-$d$ monomials -- the Hilbert function of the tangent cone of the smooth point, which for a regular point is that of affine $n$-space, confirming the "tangent cone $=\Aff^n$" picture.
\end{wex}

\begin{wex}{$\gr_\fa(R)\cong\gr_{\widehat\fa}(\widehat R)$}
For $R$ Noetherian, show completion does not change the associated graded ring.
\wrec Use $\widehat R/\widehat\fa^{\,n}\cong R/\fa^n$, hence $\widehat\fa^{\,n}/\widehat\fa^{\,n+1}\cong\fa^n/\fa^{n+1}$.
\wsol From $\widehat R/\widehat\fa^{\,n}\cong R/\fa^n$ (earlier example) the short exact sequences $0\to\widehat\fa^{\,n}/\widehat\fa^{\,n+1}\to\widehat R/\widehat\fa^{\,n+1}\to\widehat R/\widehat\fa^{\,n}\to0$ match those for $R$, giving $\widehat\fa^{\,n}/\widehat\fa^{\,n+1}\cong\fa^n/\fa^{n+1}$ in each degree, compatibly with products. Hence $\gr_{\widehat\fa}(\widehat R)\cong\gr_\fa(R)$. Sanity check: with $R=\mathbb{Z}$, $\fa=(p)$: $\gr_{(p)}(\mathbb{Z})\cong\F_p[t]\cong\gr_{p\mathbb{Z}_p}(\mathbb{Z}_p)$ -- the graded ring sees only the finite residues $\fa^n/\fa^{n+1}$, which completion preserves.
\end{wex}

\begin{lemma}[{filtered comparison}]\label{lem:filtcomp@c15}
Let $\phi\colon A\to B$ be a homomorphism of filtered groups with $\phi(A_n)\subseteq B_n$, inducing $\gr(\phi)\colon\gr(A)\to\gr(B)$ and $\widehat\phi\colon\widehat A\to\widehat B$. If $A$ is complete, $B$ Hausdorff, and $\gr(\phi)$ is surjective (resp.\ injective), then $\widehat\phi$ -- equivalently $\phi$ under completeness -- is surjective (resp.\ injective).
\end{lemma}

\begin{proposition}[{Noetherian lifting}]\label{prop:lift@c15}
Let $A$ be a filtered ring, complete and Hausdorff, with $\bigcap A_n=0$. If $\gr(A)$ is Noetherian, then $A$ is Noetherian.
\end{proposition}

\begin{theorem}[{$\widehat R$ is Noetherian}]\label{thm:noeth@c15}
If $R$ is Noetherian and $\fa\subseteq R$ an ideal, then the $\fa$-adic completion $\widehat R$ is Noetherian.
\end{theorem}

\begin{proof}[Idea]
By Proposition~\ref{prop:grnoeth@c15}(ii), $\gr_\fa(R)$ is Noetherian, and $\gr_{\widehat\fa}(\widehat R)\cong\gr_\fa(R)$ (earlier example) is therefore Noetherian. Now $\widehat R$ is complete and Hausdorff for the $\widehat\fa$-topology with $\bigcap_n\widehat\fa^{\,n}=0$, so Proposition~\ref{prop:lift@c15} lifts Noetherianity from the graded ring to $\widehat R$ itself.
\end{proof}

\begin{corollary}[{formal power series are Noetherian}]\label{cor:fps@c15}
If $R$ is Noetherian then $R[[x_1,\dots,x_n]]$ is Noetherian; in particular $k[[x_1,\dots,x_n]]$ ($k$ a field or PID) and $\mathbb{Z}_p$ are Noetherian.
\end{corollary}

\begin{proof}[Idea]
$R[x_1,\dots,x_n]$ is Noetherian (Hilbert basis), and $R[[x_1,\dots,x_n]]$ is its $(x_1,\dots,x_n)$-adic completion, so Theorem~\ref{thm:noeth@c15} applies.
\end{proof}

\begin{remark}
A\&M also record (Proposition 10.16) that if $(R,\fm)$ is Noetherian local then $\widehat R$ is again local with maximal ideal $\widehat\fm$ and residue field $\widehat R/\widehat\fm\cong R/\fm$. Completion thus preserves the local-ring structure while improving it: $\widehat R$ is complete, so Hensel's lemma is available.
\end{remark}

\begin{theorem}[{Hensel's lemma, statement}]
Let $(R,\fm)$ be a complete Noetherian local ring with residue field $k=R/\fm$, and let $f\in R[x]$ be monic. If $\bar f\in k[x]$ factors as $\bar f=\bar g\,\bar h$ with $\bar g,\bar h$ monic and \emph{coprime} (in particular if $\bar a\in k$ is a \emph{simple} root of $\bar f$, $\bar f'(\bar a)\neq0$), then the factorization lifts: there exist monic $g,h\in R[x]$ with $f=gh$, $\bar g,\bar h$ the given factors (in the simple-root case, a root $a\in R$ with $f(a)=0$ and $a\equiv\bar a$). The lift is unique.
\end{theorem}

\begin{wex}{$\mathbb{Z}_p$ is a Noetherian complete DVR}
Confirm $\mathbb{Z}_p$ is Noetherian and describe its ideals.
\wrec $\mathbb{Z}_p$ is the $(p)$-adic completion of the Noetherian $\mathbb{Z}$, so Theorem~\ref{thm:noeth@c15} applies; locate its ideals via $\widehat{(p^k)}$.
\wsol By Theorem~\ref{thm:noeth@c15}, $\mathbb{Z}_p$ is Noetherian. Its nonzero ideals are $p^k\mathbb{Z}_p=\widehat{(p^k)}$ for $k\ge0$, since every nonzero $x\in\mathbb{Z}_p$ is $p^{v}\cdot u$ with $u$ a unit ($v=v_p(x)<\infty$ as $\bigcap p^n\mathbb{Z}_p=0$). Thus $\mathbb{Z}_p$ is a discrete valuation ring: local, with maximal ideal $p\mathbb{Z}_p$, residue field $\F_p$, and $\gr_{(p)}(\mathbb{Z}_p)\cong\F_p[t]$. Sanity check: the ideals of $\mathbb{Z}_p$ form the single chain $\mathbb{Z}_p\supset p\mathbb{Z}_p\supset p^2\mathbb{Z}_p\supset\cdots\supset0$; its only primes are $p\mathbb{Z}_p$ and $0$, so the longest chain of primes is $0\subsetneq p\mathbb{Z}_p$, matching $\dim\mathbb{Z}_p=1$, and every ascending chain of ideals stops, matching the Noetherian conclusion.
\end{wex}

\begin{wex}{$k[[x]]$ is a complete DVR}
Show $k[[x]]$ is Noetherian local with maximal ideal $(x)$, and identify its fraction field.
\wrec $k[[x]]$ is the $(x)$-adic completion of $k[x]$; apply Corollary~\ref{cor:fps@c15} and the local-completion remark.
\wsol $k[[x]]$ is Noetherian by Corollary~\ref{cor:fps@c15}. A series is a unit iff its constant term is nonzero, so the non-units form the maximal ideal $(x)$; every nonzero series is $x^v\cdot(\text{unit})$, so the ideals are $(x^k)$ and $k[[x]]$ is a complete DVR. Its fraction field is the formal Laurent series field $k((x))=k[[x]][x^{-1}]$. Sanity check: $\bigcap_n(x)^n=0$ (a nonzero series has finite order), so $k[[x]]$ is Hausdorff and equals its own completion, as a complete DVR must.
\end{wex}

\begin{wex}{Hensel: $(p-1)$-th roots of unity in $\mathbb{Z}_p$}
Show $\mathbb{Z}_p$ contains $p-1$ distinct $(p-1)$-th roots of unity (the Teichmuller lifts).
\wrec Apply Hensel to $f(x)=x^{p-1}-1$; over $\F_p$ it splits into distinct linear factors (all simple roots) by Fermat.
\wsol Over $\F_p$, $x^{p-1}-1=\prod_{c\in\F_p^\times}(x-c)$ has $p-1$ distinct simple roots (each nonzero $c$ satisfies $c^{p-1}=1$ and $\bar f'(c)=(p-1)c^{p-2}\neq0$). Hensel lifts each to a unique $\omega_c\in\mathbb{Z}_p$ with $\omega_c^{p-1}=1$ and $\omega_c\equiv c\pmod p$. These $p-1$ lifts are distinct (distinct residues), giving a cyclic group $\mu_{p-1}\subset\mathbb{Z}_p^\times$. Sanity check: the $\omega_c$ are the Teichmuller representatives, and $\mathbb{Z}_p^\times\cong\mu_{p-1}\times(1+p\mathbb{Z}_p)$, consistent with $\abs{(\mathbb{Z}/p)^\times}=p-1$ on residues.
\end{wex}

\begin{wex}{Completion of a Noetherian ring stays Noetherian: $\mathbb{Z}[x]$ at $(p,x)$}
Identify the $(p,x)$-adic completion of $R=\mathbb{Z}[x]$ and confirm Noetherianity.
\wrec $R=\mathbb{Z}[x]$ is Noetherian; Theorem~\ref{thm:noeth@c15} gives $\widehat R$ Noetherian, and concretely $\widehat R$ is a two-variable formal power series object.
\wsol With $\fa=(p,x)$, $R/\fa^n$ is residues mod $p$ and $x$ to total order $n$; the completion is $\widehat R=\varprojlim\mathbb{Z}[x]/(p,x)^n\cong\mathbb{Z}_p[[x]]$, formal power series over $\mathbb{Z}_p$. By Corollary~\ref{cor:fps@c15} (with the Noetherian base $\mathbb{Z}_p$) this is Noetherian. Sanity check: $\widehat R$ is local with maximal ideal $(p,x)\widehat R$ and residue field $\F_p$, and $\gr_{(p,x)}(\mathbb{Z}[x])\cong\F_p[s,t]$ (with $s=\bar p,t=\bar x$), a Noetherian polynomial ring -- matching the lifting argument of Theorem~\ref{thm:noeth@c15}.
\end{wex}

\begin{wex}{Flatness in action: $\widehat R$ detects intersections}
Use flatness of $\widehat R$ over a Noetherian $R$ to show $\widehat{\fb\cap\fc}=\widehat\fb\cap\widehat\fc$ for ideals $\fb,\fc$.
\wrec A flat module preserves finite intersections of finitely generated submodules: $\widehat R\otimes(\fb\cap\fc)=(\widehat R\otimes\fb)\cap(\widehat R\otimes\fc)$ inside $\widehat R$.
\wsol Flatness applied to $0\to\fb\cap\fc\to\fb\oplus\fc\to\fb+\fc\to0$ (the Mayer--Vietoris sequence, with the last map $(x,y)\mapsto x-y$) stays exact after $\widehat R\otimes_R(-)$, identifying $\widehat{\fb\cap\fc}=\widehat R(\fb\cap\fc)=\widehat R\fb\cap\widehat R\fc=\widehat\fb\cap\widehat\fc$. Sanity check: with $R=\mathbb{Z}$, $\fb=(4)$, $\fc=(6)$, $\fa=(2)$: $\fb\cap\fc=(12)$, and in $\mathbb{Z}_2$, $4\mathbb{Z}_2\cap6\mathbb{Z}_2=4\mathbb{Z}_2$ (since $6=2\cdot3$ with $3$ a unit, $6\mathbb{Z}_2=2\mathbb{Z}_2$, so $4\mathbb{Z}_2\cap2\mathbb{Z}_2=4\mathbb{Z}_2$) -- and $\widehat{(12)}=12\mathbb{Z}_2=4\mathbb{Z}_2$ likewise (since $12=4\cdot3$, $3$ a unit), matching.
\end{wex}

Prove that there exists a formal power series $y(x) = \sum_{n=0}^{\infty} a_n x^n$ such that $f(x, y(x)) = 0$. (This gives the ``analytic branch'' of the curve $f = 0$ through the point $(0, a_0)$.)
\end{enumerate}

\item Show that the converse of (10.26) is false, even if we assume that $A$ is local and that $\widehat{A}$ is a finitely-generated $A$-module. [Take $A$ to be the ring of germs of $C^{\infty}$ functions of $x$ at $x = 0$, and use Borel's Theorem (every power series occurs as the Taylor expansion of some $C^{\infty}$ function).]

\item If $A$ is Noetherian, then $A[[x_1, \ldots, x_n]]$ is a faithfully flat $A$-algebra. [Express $A \to A[[x_1, \ldots, x_n]]$ as a composition of flat extensions, and use Exercise 5(v) of Chapter 1.]
\end{exers}

\begin{definition}[{Krull dimension}]
The \emph{Krull dimension} $\dim A$ of a ring $A$ is the supremum of the lengths $n$ of chains of prime ideals $\fp_0\subsetneq\fp_1\subsetneq\cdots\subsetneq\fp_n$ in $A$. The \emph{height} of a prime $\fp$, written $\hgt\fp$, is the supremum of the lengths of chains $\fp_0\subsetneq\cdots\subsetneq\fp_n=\fp$ descending from $\fp$; equivalently $\hgt\fp=\dim A_\fp$, the dimension of the local ring at $\fp$. Dually the \emph{coheight} (or dimension of $\fp$) is the sup of lengths of chains ascending from $\fp$, equal to $\dim(A/\fp)$.
\end{definition}

\begin{remark}
Geometrically, $\Spec A$ carries the Zariski topology in which irreducible closed sets are exactly $V(\fp)$ for $\fp$ prime, and $V(\fp)\subseteq V(\fq)\iff\fq\subseteq\fp$. A chain of primes $\fp_0\subsetneq\cdots\subsetneq\fp_n$ is therefore a chain of irreducible closed subsets $V(\fp_0)\supsetneq\cdots\supsetneq V(\fp_n)$, so $\dim A$ is the longest such tower. This is the prime ideal serving as ``the common generalization of the primes of arithmetic and the points of geometry'' (A\&M, Introduction): in $\mathbb{Z}$ the chain $(0)\subsetneq(p)$ has length $1$; in $k[x]$ the chain $(0)\subsetneq(x-a)$ also has length $1$; both rings are one-dimensional, arithmetic and geometric for the same reason.
\end{remark}

\begin{wex}{Dimension of a field, a PID, and $\mathbb{Z}$}
Compute $\dim k$, $\dim k[x]$, and $\dim\mathbb{Z}$ directly from chains of primes.
\wrec A field has only the prime $(0)$; in a PID that is not a field, the nonzero primes are maximal, so the longest chain is $(0)\subsetneq(p)$.
\wsol In a field $k$ the only ideals are $(0)$ and $k$, so the only prime is $(0)$: the longest chain has length $0$, $\dim k=0$. In $\mathbb{Z}$ the primes are $(0)$ and $(p)$ for $p$ prime; since $(p)$ is maximal, no prime lies strictly between $(p)$ and $\mathbb{Z}$, and the longest chain is $(0)\subsetneq(p)$, giving $\dim\mathbb{Z}=1$. Likewise in $k[x]$ the primes are $(0)$ and the maximal ideals $(f)$ with $f$ irreducible, so the longest chain is $(0)\subsetneq(f)$ and $\dim k[x]=1$. Sanity check: $\hgt(p)=\dim\mathbb{Z}_{(p)}=1$ and $\dim(\mathbb{Z}/(p))=\dim\F_p=0$, so $\hgt(p)+\dim(\mathbb{Z}/(p))=1=\dim\mathbb{Z}$, consistent with the height/coheight splitting.
\end{wex}

\begin{wex}{Height of a prime versus dimension of the quotient}
In $A=k[x,y,z]$, with $\fp=(x,y)$, compute $\hgt\fp$ and $\dim(A/\fp)$, and check they add to $\dim A$.
\wrec $\hgt(x,y)=\dim A_\fp$ counts chains descending from $(x,y)$; $\dim(A/\fp)=\dim k[z]$ counts the room above.
\wsol Descending: $(0)\subsetneq(x)\subsetneq(x,y)$ has length $2$, and one checks no longer chain ends at $(x,y)$, so $\hgt(x,y)=2$. Above: $A/(x,y)\cong k[z]$, which is one-dimensional, so $\dim(A/\fp)=1$. Then $\hgt\fp+\dim(A/\fp)=2+1=3$. Sanity check: $\dim k[x,y,z]=3$ (proved below), so the sum equals $\dim A$ and the chain $(0)\subsetneq(x)\subsetneq(x,y)\subsetneq(x,y,z)$ of length $3$ realizes both pieces at once.
\end{wex}

\begin{corollary}[{the case of degree-one generators}]
If all $k_i=1$, then for all large $n$, $\lambda(M_n)$ agrees with a polynomial in $n$ of degree $d-1$, where $d$ is the order of the pole of $P(M,t)$ at $t=1$. We write $d(M)$ for this order; it is a measure of the ``size'' of $M$.
\end{corollary}

\begin{proof}[Idea]
With $k_i=1$, $P(M,t)=f(t)(1-t)^{-s}$; cancel the factor $(1-t)$ to its true order $d$, so $P(M,t)=g(t)(1-t)^{-d}$ with $g(1)\ne0$. Expanding $(1-t)^{-d}=\sum_k\binom{d+k-1}{d-1}t^k$ and reading off the coefficient of $t^n$ shows $\lambda(M_n)$ equals a polynomial in $n$ of degree $d-1$ for $n\ge N$ (use the convention $\binom{n}{-1}=0$ and that the leading coefficient $g(1)/(d-1)!\ne0$).
\end{proof}

