embedding_text:
Course: abstract algebra notes
Section: Artinian Rings, Discrete Valuation Rings, and Dedekind Domains > Discrete Valuation Rings > Discrete valuations and their valuation rings
Type: definition
Title: {discrete valuation}
Content:
\begin{definition}[{discrete valuation}]
A discrete valuation on a field $K$ is a function $v:\units{K}\toZ$ (where $\units{K}=K\setminus\{0\}$) satisfying
\begin{enumerate}[label=\textup{(\roman*)},leftmargin=*]
\item $v$ is surjective;
\item $v(xy)=v(x)+v(y)$ for all $x,y\in\units{K}$ (so $v$ is a group homomorphism $\units{K}\toZ$);
\item $v(x+y)\ge\min\{v(x),v(y)\}$ for all $x,y\in\units{K}$ with $x+y\neq0$.
\end{enumerate}
The set
\[
R=\{x\in K:v(x)\ge0\}\cup\{0\}
\]
is a subring of $K$, the valuation ring of $v$. An integral domain $R$ is a discrete valuation ring (DVR) if $R$ is the valuation ring of a discrete valuation $v$ on its fraction field $K=\Frac(R)$.
\end{definition}

latex:
\begin{definition}[{discrete valuation}]
A \emph{discrete valuation} on a field $K$ is a function $v:\units{K}\to\mathbb{Z}$ (where $\units{K}=K\setminus\{0\}$) satisfying
\begin{enumerate}[label=\textup{(\roman*)},leftmargin=*]
\item $v$ is surjective;
\item $v(xy)=v(x)+v(y)$ for all $x,y\in\units{K}$ (so $v$ is a group homomorphism $\units{K}\to\mathbb{Z}$);
\item $v(x+y)\ge\min\{v(x),v(y)\}$ for all $x,y\in\units{K}$ with $x+y\neq0$.
\end{enumerate}
The set
\[
R=\{x\in K:v(x)\ge0\}\cup\{0\}
\]
is a subring of $K$, the \emph{valuation ring} of $v$. An integral domain $R$ is a \emph{discrete valuation ring} (DVR) if $R$ is the valuation ring of a discrete valuation $v$ on its fraction field $K=\Frac(R)$.
\end{definition}

\begin{remark}
Axiom (ii) forces $v(1)=v(1\cdot1)=2v(1)$, so $v(1)=0$; hence $1\in R$ and $v(u^{-1})=-v(u)$ for any unit. Because $R\subseteq K$ is a subring of a field, $R$ is automatically an integral domain with $\Frac(R)=K$. The structural slogan, which the next subsection makes precise, is: a DVR is a \emph{Noetherian local domain of dimension $1$ that is integrally closed} -- the local building block of a Dedekind domain.
\end{remark}

\begin{wex}{The $p$-adic valuation on $\mathbb{Q}$}
Verify that $v_p$ is a discrete valuation on $\mathbb{Q}$ and identify its valuation ring.
\wrec Every nonzero rational has a unique form $p^n(a/b)$ with $p\nmid a$, $p\nmid b$; set $v_p=n$.
\wsol Write $x=p^n(a/b)\in\units{\mathbb{Q}}$ with $a,b$ prime to $p$. Surjectivity is clear ($v_p(p^n)=n$). For (ii), if $x=p^m(a/b)$ and $y=p^n(c/d)$ then $xy=p^{m+n}(ac/bd)$ with $ac,bd$ prime to $p$, so $v_p(xy)=m+n=v_p(x)+v_p(y)$. For (iii), with $m\le n$, $x+y=p^m\bigl(a/b+p^{n-m}c/d\bigr)=p^m\cdot\tfrac{ad+p^{n-m}bc}{bd}$; the denominator is prime to $p$, the numerator may or may not be, so $v_p(x+y)\ge m=\min\{v_p(x),v_p(y)\}$. The valuation ring is $\{a/b:p\nmid b\}=\mathbb{Z}_{(p)}$, the localization of $\mathbb{Z}$ at $(p)$. Sanity check: $v_p(p)=1$ and $v_p(1/p)=-1$, so $p\in\mathbb{Z}_{(p)}$ but $1/p\notin\mathbb{Z}_{(p)}$, exactly the elements with nonnegative valuation.
\end{wex}

\begin{wex}{The order valuation on a rational function field}
For $K=F(x)$ and an irreducible $f\in F[x]$, show $v_f$ is a discrete valuation and find its ring.
\wrec Each nonzero element of $F(x)$ is uniquely $f^n(a/b)$ with $f\nmid a$, $f\nmid b$.
\wsol The verification is identical to the $p$-adic case with the prime $p$ replaced by the irreducible $f$ and $\mathbb{Z}$ replaced by the UFD $F[x]$: $v_f(gh)=v_f(g)+v_f(h)$ and the ultrametric inequality both follow from unique factorization. The valuation ring is the localization $F[x]_{(f)}$ of rational functions whose reduced denominator is not divisible by $f$. When $f=x-a$ has degree $1$, $v_f$ measures the \emph{order of vanishing} at $x=a$: $v_f\ge0$ means defined at $a$, $v_f<0$ means a pole. Sanity check: $v_{x-a}\bigl(\tfrac{1}{x-a}\bigr)=-1$ (simple pole), $v_{x-a}\bigl((x-a)^2\bigr)=2$ (double zero), consistent with (ii).
\end{wex}

\begin{wex}{The valuation on formal Laurent series}
Show the order map on $F((x))$ is a discrete valuation with ring $F[[x]]$.
\wrec A nonzero Laurent series $\sum_{i\ge n}a_ix^i$ with $a_n\neq0$ has order $n$.
\wsol Define $v\bigl(\sum_{i\ge n}a_ix^i\bigr)=n$ where $a_n\neq0$ is the lowest nonzero coefficient. Multiplying two series, the lowest terms multiply to give $a_nb_m x^{n+m}$ (nonzero, as $F$ is a domain), so $v$ is additive. For the sum, the lowest possible surviving term has exponent $\ge\min(n,m)$, giving (iii). The valuation ring $\{v\ge0\}\cup\{0\}$ is the power series ring $F[[x]]$. Sanity check: $v(x)=1$ and $v(x^{-1})=-1$, so $x\in F[[x]]$, $x^{-1}\notin F[[x]]$; and $F((x))=\Frac(F[[x]])$ since inverting $x$ recovers all Laurent series.
\end{wex}

\begin{definition}[{uniformizer}]
If $R$ is a DVR with valuation $v$, an element $t\in R$ with $v(t)=1$ is a \emph{uniformizing parameter} (or \emph{uniformizer}, or \emph{local parameter}). Such $t$ exists by surjectivity of $v$.
\end{definition}

\begin{proof}[Idea]
(1) If $uw=1$ with $w\in R$ then $v(u)+v(w)=v(1)=0$ with both $\ge0$, forcing $v(u)=0$; conversely $v(u)=0$ gives $v(u^{-1})=0$, so $u^{-1}\in R$. (2) If $v(x)=n$ then $v(xt^{-n})=0$, so $xt^{-n}=u$ is a unit and $x=ut^n$. (3) For a nonzero ideal $I$ pick $r\in I$ of minimal valuation $n$; then $r=ut^n$ gives $t^n\in I$, so $(t^n)\subseteq I$, and any $a\in I$ has $v(a)\ge n$, whence $at^{-n}\in R$ and $a\in(t^n)$. So $I=(t^n)$.
\end{proof}

\begin{proof}[Idea]
A DVR is a PID, hence a UFD, hence integrally closed in its fraction field. Locality and the ideal description come from the previous proposition; the chain $\fm^n$ has trivial intersection $\bigcap_n\fm^n=0$ since $v$ of a nonzero element is finite. As every nonzero ideal is some $\fm^n$ and a prime containing $\fm^n$ contains $\fm$, the only nonzero prime is $\fm$.
\end{proof}

