\begin{wex}{A nonzero prime that is maximal but not principal}
Show $\fp_3=(3,1+\sqrt{-5})$ in $\mathbb{Z}[\sqrt{-5}]$ is maximal yet not principal.
\wrec Dimension $1$ forces every nonzero prime maximal; non-principality is detected by the norm ($N(\fp_3)=3$) against the absence of elements of norm $3$.
\wsol The quotient $\mathcal O_K/\fp_3\cong\F_3$ is a field, so $\fp_3$ is maximal. If $\fp_3=(\alpha)$ then $N(\alpha)=\abs{\mathcal O_K/\fp_3}=3$, i.e.\ $a^2+5b^2=3$ for integers $a,b$, which is impossible. Hence $\fp_3$ is not principal. Sanity check: consistent with dimension $1$ ($\fp_3$ is maximal) and with a nontrivial class group (a nonprincipal yet invertible prime), exactly as Theorem~15 allows.
\end{wex}

\begin{wex}{Coordinate ring of a smooth affine curve is Dedekind}
Let $C$ be a nonsingular irreducible affine curve over an algebraically closed field $k$. Show $k[C]$ is a Dedekind domain.
\wrec Use criterion (2): $k[C]$ is Noetherian of dimension $1$, and smoothness says each local ring $\mathcal O_{v,C}$ is a DVR.
\wsol $k[C]$ is a finitely generated $k$-algebra and a domain, hence Noetherian; its dimension equals the transcendence degree of $k(C)$ over $k$, namely $1$. Smoothness at $v$ means $\dim_k(\fm_v/\fm_v^2)=1$, which for the Noetherian local ring $\mathcal O_{v,C}$ of dimension $1$ is exactly the DVR condition. So every localization at a closed point is a DVR; by (2), $k[C]$ is Dedekind. Sanity check: equivalently, $C$ is smooth iff $k[C]$ is integrally closed (normal), recovering criterion (1) -- "smooth curve $=$ normal one-dimensional ring."
\end{wex}

\begin{wex}{$k[x,y]/(y^2-x^3)$ is not Dedekind}
Show the cuspidal cubic coordinate ring $R=k[x,y]/(y^2-x^3)$ fails to be Dedekind.
\wrec A Dedekind domain is integrally closed; the cusp is a singular point, so normality fails.
\wsol Writing $t=y/x$ in the fraction field, $t^2=y^2/x^2=x^3/x^2=x$ and $t^3=tx=y$, so $t$ is integral over $R$ ($t^2-x=0$) but $t\notin R$. Thus $R$ is not integrally closed and not Dedekind; its integral closure is $k[t]$, the coordinate ring of the smooth normalization $\Aff^1$. Sanity check: this matches Worked Example~16.3.6 above, where $\fm=(x,y)$ was a non-invertible ideal -- non-invertibility of some ideal is exactly the failure of Theorem~15(3) caused by the singular point.
\end{wex}

\begin{corollary}[{Cor.~9.9 / Exercise 6: the group of ideals is free}]
Let $R$ be a Dedekind domain. The nonzero fractional ideals form an abelian group $I(R)$ under multiplication. Every nonzero fractional ideal is uniquely $\prod_P P^{a_P}$ over the nonzero primes $P$, with $a_P\in\mathbb{Z}$ and almost all $a_P=0$. Hence $I(R)$ is the \emph{free abelian group on the set of nonzero prime ideals}.
\end{corollary}

\begin{proof}[Idea]
Unique factorization of integral ideals (Theorem~15(5)) extends to fractional ideals: $A=d^{-1} I$ gives $A=(d)^{-1} I$ in $I(R)$, and the exponents subtract. Freeness is exactly existence-and-uniqueness of the exponent vector $(a_P)_P$.
\end{proof}

\begin{theorem}[{Cor.~20: $\operatorname{Cl}$ measures failure of UFD}]
A Dedekind domain $R$ is a PID iff $\operatorname{Cl}(R)$ is trivial $(h_R=1)$ iff $R$ is a UFD.
\end{theorem}

\begin{proof}[Idea]
PID $\Leftrightarrow$ every ideal principal $\Leftrightarrow$ $P(R)=I(R)$ $\Leftrightarrow$ $\operatorname{Cl}(R)=1$. PID $\Rightarrow$ UFD always. For the converse, in a UFD a prime ideal $P$ contains an irreducible $a'$, and $P=(a')$ because $(a')$ is already a nonzero prime; since every ideal factors into primes, every ideal is principal.
\end{proof}

\begin{remark}
For Dedekind domains arising in number theory the class group is a \emph{finite} group: $\operatorname{Cl}(\mathcal O_K)$ is finite, its order $h_K$ being a central arithmetic invariant. The unit group is finitely generated by Dirichlet: $\units{\mathcal O_K}\cong\mu_K\times\mathbb{Z}^{r_1+r_2-1}$, where $r_1,r_2$ count real and complex-conjugate-pair embeddings. For general Dedekind domains finiteness can fail spectacularly: every abelian group $A$ (finite or infinite) is the class group of some Dedekind domain.
\end{remark}

\begin{wex}{The class number of $\mathbb{Z}[\sqrt{-5}]$ is $2$}
Show $\operatorname{Cl}(\mathbb{Z}[\sqrt{-5}])\cong\mathbb{Z}/(2)\mathbb{Z}$ using the primes computed above.
\wrec Each ideal class is represented by an integral ideal of small norm; $\fp_2,\fp_3,\fp_3'$ are non-principal, and one checks the products that become principal.
\wsol The nonprincipal primes $\fp_2,\fp_3,\fp_3'$ all lie in one nontrivial class: $\fp_2\fp_3=(1+\sqrt{-5})$ and $\fp_2\fp_3'=(1-\sqrt{-5})$ are principal, so $[\fp_3]=[\fp_3']=[\fp_2]^{-1}=[\fp_2]$ (as $\fp_2^2=(2)$ is principal, $[\fp_2]$ has order $2$). Thus the class group is generated by $[\fp_2]$ with $[\fp_2]^2=1$, giving $\operatorname{Cl}\cong\mathbb{Z}/(2)\mathbb{Z}$. Sanity check: $h=2\ne1$ certifies $\mathbb{Z}[\sqrt{-5}]$ is not a UFD, in exact agreement with $6=2\cdot3=(1+\sqrt{-5})(1-\sqrt{-5})$ being two genuinely different element-factorizations.
\end{wex}

\begin{wex}{Units of $\mathbb{Z}[i]$ and the trivial class group}
Identify $\units{\mathbb{Z}[i]}$ and explain why $\operatorname{Cl}(\mathbb{Z}[i])=1$.
\wrec $\mathbb{Z}[i]$ is a Euclidean domain, hence a PID, hence a Dedekind domain with trivial class group; units are the elements of norm $1$.
\wsol $u\in\units{\mathbb{Z}[i]}\Leftrightarrow N(u)=a^2+b^2=1\Leftrightarrow u\in\{1,-1,i,-i\}=\mu_4$. As a PID, $\operatorname{Cl}(\mathbb{Z}[i])=1$ and $h=1$. Sanity check: here $K=\mathbb{Q}(i)$ has $r_1=0$, $r_2=1$, so the Dirichlet rank is $r_1+r_2-1=0$ and $\units{\mathbb{Z}[i]}$ is purely torsion -- exactly the $4$ roots of unity found.
\end{wex}

\begin{wex}{Units of $\mathbb{Z}[\sqrt2]$ are infinite, class number still $1$}
Describe $\units{\mathbb{Z}[\sqrt2]}$ and its class group.
\wrec $\mathbb{Q}(\sqrt2)$ is real quadratic; $\mathbb{Z}[\sqrt2]$ is a PID (Euclidean), so $h=1$, but the unit group has positive rank.
\wsol $\mathbb{Z}[\sqrt2]$ is Euclidean for the norm, so it is a PID and $\operatorname{Cl}=1$. The fundamental unit is $1+\sqrt2$ (norm $(1)^2-2(1)^2=-1$), and $\units{\mathbb{Z}[\sqrt2]}=\{\pm(1+\sqrt2)^n:n\in\mathbb{Z}\}\cong\{\pm1\}\times\mathbb{Z}$. Sanity check: $K=\mathbb{Q}(\sqrt2)$ has $r_1=2,r_2=0$, Dirichlet rank $r_1+r_2-1=1$, matching the single fundamental unit $1+\sqrt2$ of infinite order.
\end{wex}

\begin{wex}{Reading the exact sequence for $\mathbb{Z}$}
Interpret $1\to\units R\to K^\times\to I(R)\to\operatorname{Cl}(R)\to1$ for $R=\mathbb{Z}$.
\wrec The maps are $\units\mathbb{Z}\hookrightarrow\mathbb{Q}^\times\to I(\mathbb{Z})\to\operatorname{Cl}(\mathbb{Z})$; identify each term.
\wsol $\units\mathbb{Z}=\{\pm1\}$; $\mathbb{Q}^\times\to I(\mathbb{Z})$ sends $x=\pm\prod p^{a_p}$ to the fractional ideal $\prod (p)^{a_p}$, with kernel $\{\pm1\}$; $I(\mathbb{Z})$ is free abelian on $\{(p)\}$; and $\operatorname{Cl}(\mathbb{Z})=1$ since $\mathbb{Z}$ is a PID. Sanity check: the sequence collapses to $1\to\{\pm1\}\to\mathbb{Q}^\times\to I(\mathbb{Z})\to1$, the statement that a positive rational is uniquely $\prod p^{a_p}$ -- the fundamental theorem of arithmetic, recast multiplicatively.
\end{wex}

\begin{definition}[{divides}]
For ideals $A,B$ of a domain $R$, say $B$ \emph{divides} $A$ (written $B\mid A$) if $A=BC$ for some ideal $C$. Then $B\mid A\Rightarrow A\subseteq B$ always; in a Dedekind domain the converse holds: $A\subseteq B$ gives $C=AB^{-1}\subseteq BB^{-1}=R$, an integral ideal with $BC=A$.
\end{definition}

