\begin{proposition}[{Prop.~17: gcd via factorization}]
Let $R$ be Dedekind and $A=\prod P_i^{e_i}$, $B=\prod P_i^{f_i}$ ($e_i,f_i\ge0$). Then
\begin{enumerate}[label=\textup{(\arabic*)},leftmargin=*]
\item $A\subseteq B \iff B\mid A \iff f_i\le e_i$ for all $i$;
\item $A+B=\gcd(A,B)=\prod P_i^{\min(e_i,f_i)}$ and $A\cap B=\operatorname{lcm}(A,B)=\prod P_i^{\max(e_i,f_i)}$. In particular $A+B=R$ (coprime) iff $A,B$ share no prime factor.
\end{enumerate}
\end{proposition}

\begin{proof}[Idea]
(1) is "contain $=$ divide" read off exponents. For (2): $A+B$ is the smallest ideal containing both, so every common divisor of $A$ and $B$ (an ideal containing both) contains $A+B$, i.e.\ divides it; matching exponents gives the min, and dually $A\cap B$ gives the max.
\end{proof}

\begin{proof}[Idea]
Distinct primes are maximal (dimension $1$), so the $P_i^{a_i}$ are pairwise comaximal; CRT for comaximal ideals applies, and $\bigcap P_i^{a_i}=\prod P_i^{a_i}$.
\end{proof}

\begin{proof}[Idea]
(1) For $I=\prod P_i^{e_i}$ pick $r_i\in P_i^{e_i}\setminus P_i^{e_i+1}$ and use CRT to get $a$ with $v_{P_i}(a)=e_i$ exactly; then $(a)=IJ$ with $J$ coprime to $I$. (2) reduces via CRT to $R/P^m\cong R_P/P^mR_P$, a quotient of a DVR (a local PID), where ideals are principal. (3) is (2) applied with $I_1=I$, $b$ lifting a generator.
\end{proof}

\begin{wex}{CRT in $\mathbb{Z}$ recovered}
Specialize Proposition~18 to $R=\mathbb{Z}$ with $P_i=(p_i)$.
\wrec $\mathbb{Z}$ is Dedekind; distinct primes $(p_i)$ are comaximal, so CRT for ideals is ordinary CRT for integers.
\wsol With $m=\prod p_i^{a_i}$, $\mathbb{Z}/m\mathbb{Z}\cong\prod_i\mathbb{Z}/p_i^{a_i}\mathbb{Z}$, the classical statement. Solving $x\equiv r_i\pmod{p_i^{a_i}}$ has a unique solution mod $m$. Sanity check: e.g.\ $\mathbb{Z}/12\mathbb{Z}\cong\mathbb{Z}/4\mathbb{Z}\times\mathbb{Z}/3\mathbb{Z}$ from $12=2^2\cdot3$, and $\abs{\mathbb{Z}/12\mathbb{Z}}=12=4\cdot3$ matches.
\end{wex}

\begin{wex}{gcd of two ideals in $\mathbb{Z}[i]$}
Compute $(3+i)+(1+3i)$ and $(3+i)\cap(1+3i)$ in $\mathbb{Z}[i]$ via factorization.
\wrec In the Dedekind (in fact principal) domain $\mathbb{Z}[i]$, sum $=\gcd$ and intersection $=\operatorname{lcm}$, read off prime factorizations.
\wsol Norms: $N(3+i)=10=2\cdot5$, $N(1+3i)=10$. With $\pi_2=(1+i)$ ($N=2$) and the split primes over $5$, $\pi_5=(2+i),\bar\pi_5=(2-i)$, one finds $(3+i)=\pi_2\,(2-i)$ up to units and $(1+3i)=\pi_2\,(2+i)$. So $\gcd=(3+i)+(1+3i)=\pi_2=(1+i)$ and $\operatorname{lcm}=(3+i)\cap(1+3i)=\pi_2(2+i)(2-i)=(1+i)(5)=(5+5i)$ up to units. Sanity check: norms multiply correctly, $N(\gcd)\cdot N(\operatorname{lcm})=2\cdot 50=100=N(3+i)N(1+3i)=10\cdot10$, the ideal analogue of $\gcd\cdot\operatorname{lcm}=$ product.
\end{wex}

\begin{wex}{Every ideal of $\mathbb{Z}[\sqrt{-5}]$ needs at most two generators}
Illustrate Corollary~19(3) on $\fp_2=(2,1+\sqrt{-5})$.
\wrec Two-generation: pick any nonzero $a\in I$, then $I=Ra+Rb$; here $a=2$.
\wsol $\fp_2$ is already exhibited with two generators $2$ and $1+\sqrt{-5}$, and it is not principal (as in Worked Example~16.3.7: no element of norm $2$), so two is the minimum. Sanity check: this is sharp -- a non-principal ideal in a Dedekind domain genuinely needs two generators but never more, matching Corollary~19(3).
\end{wex}

\begin{wex}{Finding a coprime ideal in the inverse class}
For $I=\fp_3=(3,1+\sqrt{-5})$ in $\mathbb{Z}[\sqrt{-5}]$, find $J$ coprime to $I$ with $IJ$ principal.
\wrec Corollary~19(1): $J$ should sit in $[I]^{-1}$; here $\fp_3'=(3,1-\sqrt{-5})$ is coprime to $\fp_3$ and $\fp_3\fp_3'=(3)$.
\wsol Take $J=\fp_3'$. Then $\fp_3+\fp_3'=R$ (they share no prime factor) and $\fp_3\fp_3'=(3)$ is principal. Sanity check: $[\fp_3'][\fp_3]=[(3)]=1$ in $\operatorname{Cl}(R)$, so indeed $[J]=[I]^{-1}$, exactly as the corollary promises.
\end{wex}

\begin{proof}[Idea]
(1) multiplication by $a$ is an isomorphism $J\to(a)J$; conversely an $R$-isomorphism $\varphi:I\to J$ is multiplication by the constant $c=\varphi(x)/x\in K^\times$ (since $x\varphi(y)=y\varphi(x)$), so $J=cI$, i.e.\ $I=(c^{-1})J$. The key reduction in (3) is the splitting $I\oplus J\cong R\oplus IJ$: replacing $I,J$ by coprime integral representatives, the sum map $I\oplus J\to I+J=R$ has kernel $I\cap J=IJ$, giving a short exact sequence $0\to IJ\to I\oplus J\to R\to0$ that splits because $R$ is free. Iterating gives (3); (2) follows by tracking the product class via a determinant.
\end{proof}

\begin{proof}[Idea]
A finitely generated torsion-free $M$ embeds in $M\otimes_R K\cong K^n$; projecting to a last coordinate gives $0\to\ker\to M\to I_1\to0$ with $I_1$ a nonzero ideal, which splits because $I_1$ is projective (Theorem~15(4)). Induction yields $M\cong I_1\oplus\cdots\oplus I_n$, and Prop.~21(3) collapses this to $R^{n-1}\oplus(I_1\cdots I_n)$. For general $M$ the sequence $0\to\Tor(M)\to M\to M/\Tor(M)\to0$ splits (the quotient is torsion-free, hence projective). The torsion part is handled prime by prime: $\Tor(M)\cong\bigoplus N/P_i^{e_i}N$, and each piece, being a module over the DVR $R_{P_i}$, decomposes by the PID structure theorem.
\end{proof}

\begin{corollary}[{Cor.~23: projective $=$ torsion-free}]
A finitely generated module over a Dedekind domain is projective iff it is torsion-free. Moreover the class number is $1$ iff every finitely generated projective $R$-module is free.
\end{corollary}

\begin{wex}{A PID that is not a field is a Dedekind domain of class number $1$}
Show Theorem~22 reduces to the PID structure theorem when $\operatorname{Cl}(R)=1$.
\wrec If $h_R=1$ every ideal $I$ is principal, hence $I\cong R$ as a module, so the Steinitz class drops out.
\wsol When $\operatorname{Cl}(R)=1$, $[I]=[R]$ forces $I\cong R$, so $R^{n-1}\oplus I\cong R^n$ and $M\cong R^n\oplus\bigoplus R/P_i^{e_i}$ -- the elementary-divisor form of the PID theorem. Sanity check: for $R=\mathbb{Z}$, $P_i=(p_i)$, this is $M\cong\mathbb{Z}^n\oplus\bigoplus\mathbb{Z}/p_i^{e_i}\mathbb{Z}$, the classification of finitely generated abelian groups.
\end{wex}

\begin{wex}{A rank-one nonfree projective module}
Exhibit a finitely generated projective module over $\mathbb{Z}[\sqrt{-5}]$ that is not free.
\wrec By Cor.~23, projective $=$ torsion-free; a non-principal ideal is torsion-free (projective) but not $\cong R$ (not free) when its class is nontrivial.
\wsol Take $M=\fp_2=(2,1+\sqrt{-5})$. As a fractional ideal it is invertible, hence projective; it has rank $1$. It is \emph{not} free: free of rank $1$ would mean $\fp_2\cong R$, i.e.\ $\fp_2$ principal, which it is not. Sanity check: $[\fp_2]\ne1$ in $\operatorname{Cl}(\mathbb{Z}[\sqrt{-5}])\cong\mathbb{Z}/(2)\mathbb{Z}$, so by the last clause of Cor.~23 not every projective is free, consistent with $h=2\ne1$.
\end{wex}

\begin{wex}{Steinitz class detects a non-split direct sum}
Decide whether $\fp_2\oplus\fp_2\cong R\oplus R$ over $R=\mathbb{Z}[\sqrt{-5}]$.
\wrec Use Prop.~21(2)/(3): $\fp_2\oplus\fp_2\cong R\oplus\fp_2^2$, and $\fp_2^2=(2)$ is principal.
\wsol $\fp_2\oplus\fp_2\cong R\oplus(\fp_2\cdot\fp_2)=R\oplus\fp_2^2=R\oplus(2)\cong R\oplus R$, since $(2)\cong R$ as a module. So yes, $\fp_2\oplus\fp_2\cong R^2$. Sanity check: the Steinitz class is $[\fp_2^2]=[\fp_2]^2=1$ in $\mathbb{Z}/(2)\mathbb{Z}$, so the rank-$2$ projective is free even though each summand $\fp_2$ is not -- the class group is where the obstruction lives, and it vanishes after squaring.
\end{wex}

\begin{wex}{Torsion module over a Dedekind domain}
Classify $M=R/\fp_2^3\oplus R/\fp_3$ as in Theorem~22 over $R=\mathbb{Z}[\sqrt{-5}]$.
\wrec This is already in elementary-divisor form: the prime powers are $\fp_2^3$ and $\fp_3^1$, the module is pure torsion (rank $0$).
\wsol The rank is $0$, so there is no free or Steinitz part; $\Tor(M)=M$ with elementary divisors $\fp_2^3$ and $\fp_3$. Sanity check: the two primes are distinct, so by CRT (Prop.~18) the summands are coprime and combine into the cyclic module $M\cong R/\fp_2^3\fp_3$ (the invariant-factor form); the elementary divisors $\{\fp_2^3,\fp_3\}$ are the unique invariants.
\end{wex}

\begin{wex}{Quotient $R/I$ is Artinian}
Show that for a nonzero ideal $I$ of a Dedekind domain $R$, the ring $R/I$ is Artinian.
\wrec $R$ is Noetherian of dimension $1$; modding out a nonzero ideal kills the dimension, and Noetherian $+$ dimension $0$ $=$ Artinian.
\wsol Write $I=\prod P_i^{e_i}$. By CRT $R/I\cong\prod R/P_i^{e_i}$, and each $R/P_i^{e_i}\cong R_{P_i}/P_i^{e_i}R_{P_i}$ is a quotient of a DVR by a power of its maximal ideal, hence a local Artinian ring (a finite-length module over itself). A finite product of Artinian rings is Artinian. Sanity check: $R/I$ is Noetherian (quotient of Noetherian) with every prime maximal (dimension $0$), and Noetherian $+$ dimension $0$ is exactly Artinian -- the Akizuki--Hopkins criterion, tying back to Section 16.1.
\end{wex}

\begin{wex}{Localizing a Dedekind domain stays Dedekind}
If $R$ is Dedekind and $S\subseteq R$ is multiplicatively closed with $0\notin S$, show $S^{-1} R$ is Dedekind or a field.
\wrec Localization preserves Noetherian, integral closure, and can only lower dimension; the primes of $S^{-1} R$ are those of $R$ missing $S$.
\wsol $S^{-1} R$ is Noetherian (localization of Noetherian), integrally closed (integral closure commutes with localization), and a domain with fraction field $K$. Its nonzero primes correspond to nonzero primes of $R$ disjoint from $S$, each still maximal; so $\dim S^{-1} R\le1$. If some nonzero prime survives, $S^{-1} R$ is Dedekind; if all nonzero primes meet $S$, then $S^{-1} R=K$, a field. Sanity check: taking $S=R\setminus P$ recovers the localization $R_P$, which is a DVR -- a local Dedekind domain -- exactly criterion (2) of Theorem~15. The induced map on ideals $I(R)\to I(S^{-1} R)$ is the surjection sending the killed primes to $1$, so $\operatorname{Cl}(S^{-1} R)$ is a quotient of $\operatorname{Cl}(R)$.
\end{wex}

\begin{proof}
A rational $a$ has irreducible polynomial $x-a$, which has integer coefficients exactly when
$a\in\mathbb{Z}$. For the second statement, when $b\ne0$ the irreducible polynomial is
$x^2-2a\,x+(a^2-b^2 d)$, integral precisely when $2a$ and $a^2-b^2 d$ lie in $\mathbb{Z}$; the case
$b=0$ is the first statement.
\end{proof}

\begin{remark}
For $d<0$ the ring $R$ is a \emph{lattice} in $\mathbb{C}$: rectangular when $d\equiv2,3\pmod4$
(basis $1,\delta$ with $\delta$ purely imaginary) and ``isosceles-triangular'' when
$d\equiv1\pmod4$ (basis $1,\eta$). Two famous cases: $d=-1$ gives the Gauss integers
$\mathbb{Z}[i]$ on a \emph{square} lattice, and $d=-3$ gives $\mathbb{Z}[\eta]$ on an \emph{equilateral}
triangular lattice. The geometry of $R$ as a lattice is what makes the imaginary case
tractable, and it drives the unit count below.
\end{remark}

