\begin{definition}[{conjugate ideal}]
The \emph{conjugate} of an ideal $A$ is $\overline A=\{\overline\alpha:\alpha\in A\}$, again an ideal of $R$. If $(\alpha,\beta)$ is a lattice basis for $A$, then $(\overline\alpha,\overline\beta)$ is a lattice basis for $\overline A$. The \emph{norm} of $A$ is the lattice index $\Nm(A)=[R:A]$.
\end{definition}

\begin{proof}
Every element of $AB$ is a finite sum $\sum_k a_k b_k$ with $a_k\in A,\ b_k\in B$; expanding $a_k=\sum_i r_{ki}\alpha_i$, $b_k=\sum_j s_{kj}\beta_j$ and collecting coefficients in $R$ writes it as an $R$-combination of the $\alpha_i\beta_j$, proving (a). Parts (b) and (c) are the case $m=1$.
\end{proof}

\begin{corollary}[{Artin 13.4.9: cancellation and ``to contain is to divide''}]
For nonzero ideals $A,B,C$ of $R$: \textup{(a)} $AB=AC\iff B=C$, and $AB\subseteq AC\iff B\subseteq C$; \textup{(b)} $A\supseteq B$ if and only if $A$ \emph{divides} $B$, i.e.\ $B=AC$ for some ideal $C$.
\end{corollary}

\begin{proof}
(a) If $AB=AC$, multiply by $\overline A$: by the Main Lemma $A\overline A=(n)$, so $nB=nC$, and dividing by $n$ gives $B=C$. (b) If a principal $(n)\supseteq B$ then $n$ divides every element of $B$, and $C=n^{-1}B$ is an ideal with $(n)C=B$. In general $A\supseteq B$ gives $(n)=A\overline A\supseteq\overline AB$, so $\overline AB=(n)C=A\overline AC$ for some $C$, and cancellation yields $B=AC$. Conversely $B=AC$ gives $B=AC\subseteq AR=A$.
\end{proof}

\begin{theorem}[{Artin 13.5.5: unique factorization of ideals}]
Let $R$ be the ring of integers in an imaginary quadratic field. Every nonzero proper ideal of $R$ is a product of nonzero prime (= maximal) ideals, and the factorization is unique up to the order of the factors.
\end{theorem}

\begin{proof}
\emph{Existence.} If $B$ is maximal it is prime. Otherwise some ideal $A$ properly contains $B$; by Artin's Corollary 13.4.9(b), $A$ divides $B$, say $B=AC$, and cancellation forces $C\supsetneq B$ too. Since only finitely many ideals contain $B$ (each has $[R:B]<\infty$), recursively factoring $A$ and $C$ terminates with all factors maximal.

\emph{Uniqueness.} Suppose $P_1\cdots P_r=Q_1\cdots Q_s$ with all $P_i,Q_j$ prime. Then $P_1\supseteq Q_1\cdots Q_s$, so by primeness $P_1\supseteq Q_j$ for some $j$, say $j=1$; as $Q_1$ is maximal, $P_1=Q_1$. Cancel $P_1$ (Artin's Corollary 13.4.9(a)) and induct.
\end{proof}

\begin{remark}
A prime $p\in\mathbb{Z}$ either \emph{remains prime} (if $(p)$ is a prime ideal), or \emph{splits} as $(p)=P\overline P$ with $P\neq\overline P$, or \emph{ramifies} when $P=\overline P$. The Main Lemma's $P\overline P=(\Nm P)$ forces $\Nm P$ to be $p$ or $p^2$, matching this trichotomy.
\end{remark}

\begin{wex}{The split prime $3$ and the mixed products}
Show $B\overline B=(3)$, and $A B=(1+\delta)$, $\overline A\,\overline B=(1-\delta)$.
\wrec Same generator-product computation; each product ideal turns out principal, generated by a shared divisor of all four generators.
\wsol For $B\overline B$ the four products are $9,\,3(1-\delta),\,3(1+\delta),\,6$, all divisible by $3$, and $3=9-6\in B\overline B$, so $B\overline B=(3)$. For $AB$ the four products of $\{2,1+\delta\}$, $\{3,1+\delta\}$ are $6,\,2(1+\delta),\,3(1+\delta),\,(1+\delta)^2$, each divisible by $1+\delta$; moreover $1+\delta=3(1+\delta)-2(1+\delta)\in AB$, so $AB=(1+\delta)$. Conjugating gives $\overline A\,\overline B=(1-\delta)$. \textit{Check.} $\Nm(AB)=\abs{1+\delta}^2=6=[R:A][R:B]=2\cdot3$, consistent with norms being multiplicative.
\end{wex}

\begin{remark}
The phenomenon is sharp: $A=\overline A$ here (an accidental symmetry of this lattice, since $1-\delta=2-(1+\delta)\in A$), so $2$ ramifies, $(2)=A^2$; whereas $B\neq\overline B$, so $3$ splits, $(3)=B\overline B$. The failure of \emph{element} factorization is precisely the failure of these prime ideals to be principal -- which the class number $2$ measures. Restoring unique factorization at the level of ideals is exactly the order that the geometry of lattices recovers.
\end{remark}

