\begin{wex}{The prime $11$ is inert in $\mathbb{Z}[\sqrt{-5}]$}
Show that $(11)$ is a prime ideal of $\mathbb{Z}[\sqrt{-5}]$.
\wrec Inertness is the case $\left(\frac{d}{p}\right)=-1$: $x^2-d$ stays irreducible mod $p$, so $(p)$ is already maximal.
\wsol Modulo $11$, $-5\equiv6$. The nonzero squares mod $11$ are $\{1,4,9,5,3\}$, and $6$ is not among them, so $\left(\frac{-5}{11}\right)=-1$. Hence $x^2+5\equiv x^2-6$ has no root in $\F_{11}$ and is irreducible there, so by part (c) of the theorem $(11)=11R$ is prime in $\mathbb{Z}[\sqrt{-5}]$: $11$ is inert.
\textit{Check.} $R/(11)\cong\F_{11}[x]/(x^2-6)\cong\F_{121}$ is a field, confirming $(11)$ is maximal; the norm of the prime $(11)$ is $11^2=121$, the inert signature.
\end{wex}

\begin{definition}[{similar ideals, ideal classes}]
Two nonzero ideals $A,A'$ of $R$ are \emph{similar} if $A'=\lambda A$ for some $\lambda\in\units{\mathbb{C}}$. Similarity is an equivalence relation; its classes are the \emph{ideal classes}. The class of $A$ is written $(A)$. Geometrically $A\sim A'$ iff, as lattices in $\mathbb{C}$, they are orientation-preservingly similar figures (a rotation followed by a scaling), since a lattice looks the same at each point and the similarity may be assumed to carry $0\mapsto0$, i.e.\ to be multiplication by some $\lambda$.
\end{definition}

\begin{lemma}[{the principal class}]
The class $(R)$ of the unit ideal consists of exactly the principal ideals.
\end{lemma}

\begin{proof}
If $(A)=(R)$ then $A=\lambda R$ for some $\lambda\in\mathbb{C}$. Since $1\in R$ we get $\lambda\in A\subseteq R$, so $A=\lambda R=(\lambda)$ is principal. Conversely $(\lambda)=\lambda R\sim R$.
\end{proof}

\begin{proposition}[{the class group}]
The ideal classes form an abelian group $C$ under $(A)(B)=(AB)$, with identity $1=(R)$. It is the \emph{class group} of $R$; its order is the \emph{class number} $h$.
\end{proposition}

\begin{proof}
If $(A)=(A')$ and $(B)=(B')$, say $A'=\lambda A$, $B'=\mu B$, then $A'B'=\lambda\mu AB$, so $(A'B')=(AB)$ and the law is well defined. Commutativity and associativity descend from ideal multiplication, and $(R)$ is the identity since $AR=A$. For inverses, the Main Lemma gives $A\overline A=(n)$ principal, so $(A)(\overline A)=(A\overline A)=(R)=1$ and $(A)^{-1}=(\overline A)$.
\end{proof}

\begin{remark}
Thus $R$ is a principal ideal domain iff $h=1$, and for these rings PID $\Leftrightarrow$ UFD. The class number quantifies how badly element factorization fails: when $h=2$, for instance, the product of any two non-principal ideals is principal (the non-trivial class has order $2$).
\end{remark}

