\begin{theorem}[{Minkowski-type bound and finiteness}]
Let $R$ be the ring of integers of $Q[\sqrt d\,]$, $d<0$, and put
\[
\mu=\begin{cases}\dfrac{2}{\sqrt3}\sqrt{\,\abs{d}\,}, & d\equiv 2,3\pmod 4,\\[2ex]\dfrac{1}{\sqrt3}\sqrt{\,\abs{d}\,}, & d\equiv 1\pmod 4.\end{cases}
\]
Then:
\begin{enumerate}[label=\textup{(\alph*)},leftmargin=*]
\item every ideal class contains an ideal $A$ with $\Nm(A)\le\mu$;
\item $C$ is generated by the classes of prime ideals $P$ whose norm is a prime integer $p\le\mu$;
\item $C$ is finite.
\end{enumerate}
\end{theorem}

latex:
\begin{theorem}[{Minkowski-type bound and finiteness}]
Let $R$ be the ring of integers of $\mathbb{Q}[\sqrt d\,]$, $d<0$, and put
\[
\mu=\begin{cases}\dfrac{2}{\sqrt3}\sqrt{\,\abs{d}\,}, & d\equiv 2,3\pmod 4,\\[2ex]\dfrac{1}{\sqrt3}\sqrt{\,\abs{d}\,}, & d\equiv 1\pmod 4.\end{cases}
\]
Then:
\begin{enumerate}[label=\textup{(\alph*)},leftmargin=*]
\item every ideal class contains an ideal $A$ with $\Nm(A)\le\mu$;
\item $C$ is generated by the classes of prime ideals $P$ whose norm is a prime integer $p\le\mu$;
\item $C$ is finite.
\end{enumerate}
\end{theorem}

\begin{method}{Computing $C$ from the splitting of small primes.}
\begin{enumerate}[label=\textup{\arabic*.},leftmargin=*]
\item Compute $\lfloor\mu\rfloor$ and list the primes $p\le\mu$.
\item Determine the splitting of each such $p$. For $d\equiv2,3\pmod 4$: $p=2$ and the odd $p\mid d$ \emph{ramify}, $(p)=P\overline P$ with $P=\overline P$, so $(P)^2=1$ (order $\le2$); an odd $p\nmid d$ \emph{splits} iff $x^2-d$ has a root in $\F_p$; if $p$ stays prime, $(p)$ has trivial class and is discarded. For each prime that splits or ramifies, include one prime factor's class as a generator.
\item Find relations by computing element norms: a factorization $\Nm(\alpha)=p^iq^js^k$, with $\alpha$ divisible by none of the integers $p,q,s$, yields an ideal relation $(\alpha)=P^i Q^j S^k$ (up to conjugates), hence a relation $(P)^i(Q)^j(S)^k=1$ in $C$.
\item Read off the group from generators and relations; a prime $P$ over $p$ is non-principal iff $p$ has no proper factor (norm-$p$ element) in $R$.
\end{enumerate}
\end{method}

\begin{lemma}[{why norms detect relations}]
If $P,Q,S$ are primes of norms $p,q,s$ and $(P)^i(Q)^j(S)^k=1$ in $C$, then there is $\alpha\in R$ with $\Nm(\alpha)=p^iq^js^k$.
\end{lemma}

\begin{proof}
The relation says $P^iQ^jS^k=(\alpha)$ is principal. Then $(\alpha)(\overline\alpha)=(P\overline P)^i(Q\overline Q)^j(S\overline S)^k=(p)^i(q)^j(s)^k=(p^iq^js^k)$, so $\Nm(\alpha)=\alpha\overline\alpha=p^iq^js^k$.
\end{proof}

\begin{wex}{The class group for $d=-5$ ($h=2$)}
Compute $C$ for $R=\mathbb{Z}[\delta]$, $\delta=\sqrt{-5}$, and exhibit the non-trivial class.
\wrec $d=-5\equiv3\pmod4$, so $\mu=\tfrac{2}{\sqrt3}\sqrt5\approx2.58$, $\lfloor\mu\rfloor=2$: only the prime $p=2$ need be examined.
\wsol The prime $2$ ramifies: $x^2-(-5)=x^2+5\equiv x^2+1\equiv(x+1)^2\pmod2$, and $(2)=A\overline A$ with $A=(2,\,1+\delta)$, $A=\overline A$. By the ramified-prime analysis $(A)$ has order $1$ or $2$, and order $1$ would make $A=(\alpha)$ with $\Nm(\alpha)=\Nm(A)=2$, i.e.\ $a^2+5b^2=2$ for integers $a,b$ -- impossible. So $(A)$ has order $2$. Every class is represented by an ideal of norm $\le2$; the ideals of norm $1$ form the class $1$ and the only ideal of norm $2$ is $A$, giving exactly two classes. Hence $C\cong\mathbb{Z}/2\mathbb{Z}$, generated by $(A)$, and $R$ is \emph{not} a UFD.

\textit{Check.} The failure of unique factorization is visible directly: $6=2\cdot3=(1+\delta)(1-\delta)$ with all four factors irreducible, while at the ideal level $(6)=(2)(3)=A\overline A\,B\overline B$ refines both, where $B=(3,1+\delta)$, $A\overline A=(2)$, $B\overline B=(3)$, and $AB=(1+\delta)$ is principal -- confirming $(A)(B)=1$, i.e.\ $(B)=(A)^{-1}=(A)$, consistent with a group of order $2$.
\end{wex}

\begin{pitfall}
Do not conflate the two norms. $\Nm(\alpha)=\alpha\overline\alpha$ is an integer attached to an \emph{element}; $\Nm(A)=n$ where $A\overline A=(n)$ is attached to an \emph{ideal}. They agree only on principal ideals, $\Nm((\alpha))=\Nm(\alpha)$. The algorithm works precisely by passing between them: a multiplicative element norm $\Nm(\alpha)=p^iq^js^k$, with $\alpha$ divisible by none of $p,q,s$, certifies a principal ideal $P^iQ^jS^k=(\alpha)$ (up to conjugates), hence a relation in $C$. Also, an integer prime $p$ with $\Nm(P)=p^2$ means $(p)=P$ stayed prime -- its class is trivial and must be discarded, not used as a generator.
\end{pitfall}

\begin{remark}
The same procedure runs for any imaginary quadratic $d$: a UFD is detected exactly when no prime $p\le\mu$ contributes a non-trivial class (e.g.\ $d=-1,-2$ give $\mu<2$ with no primes to check, and $d=-163$, where $x^2-x+41$ stays irreducible mod $2,3,5,7$, both give $h=1$). The finiteness of $C$ -- a theorem here proved by the lattice bound -- is the first structural invariant of a number field beyond its degree, and the class group $\cong\mathbb{Z}/h\mathbb{Z}$ in all examples above is the cyclic shadow of how far $R$ sits from being a principal ideal domain.
\end{remark}

\begin{wex}{Reading the norm as a product of coordinates}
For $\alpha=1+\sqrt2$ in $R=\mathbb{Z}[\sqrt2]$, compute $\Phi(\alpha)$ and $\Nm(\alpha)$ and check the two agree.
\wrec Apply $\Phi$ coordinatewise; the norm is $a^2-b^2d$ and also the product $uv$.
\wsol Here $a=b=1$, $d=2$, so $u=1+\sqrt2$ and $v=1-\sqrt2$, giving $\Phi(\alpha)=(1+\sqrt2,\,1-\sqrt2)$. Then $\Nm(\alpha)=a^2-b^2d=1-2=-1$, and indeed $uv=(1+\sqrt2)(1-\sqrt2)=1-2=-1$. \textit{Check.} The point lies on the hyperbola $uv=-1$, with $u\approx2.414$, $v\approx-0.414$, so $uv=-1$ to the displayed accuracy.
\end{wex}

\begin{proof}
If $\alpha$ is a unit with inverse $\beta\in R$, then $\Nm(\alpha)\Nm(\beta)=\Nm(1)=1$ in $\mathbb{Z}$, and both factors are integers, so $\Nm(\alpha)=\pm1$. Conversely, if $\Nm(\alpha)=\alpha\overline{\alpha}=\pm1$, then $\overline{\alpha}$ or $-\overline{\alpha}$ is an inverse of $\alpha$ lying in $R$ (the conjugate of an algebraic integer is again an algebraic integer in $R$), so $\alpha\in\units{R}$. The condition $\Nm(\alpha)=uv=\pm1$ is exactly membership of $\Phi(\alpha)$ in the two hyperbolas.
\end{proof}

