  \draw[thick,domain=-3.1:-0.34,smooth,variable=\x] plot ({\x},{1/\x});
  % hyperbola uv=-1 (branches in quadrants II and IV)
  \draw[thick,dashed,domain=0.34:3.1,smooth,variable=\x] plot ({\x},{-1/\x});
  \draw[thick,dashed,domain=-3.1:-0.34,smooth,variable=\x] plot ({\x},{-1/\x});
  % a few lattice points of Z[sqrt2]: (a+b sqrt2, a-b sqrt2)
  % epsilon = 1+sqrt2 -> (2.414,-0.414) on uv=-1
  \fill (2.414,-0.414) circle (1.8pt) node[below right,font=\scriptsize]{$1+\sqrt2$};
  % epsilon^2 = 3+2sqrt2 -> (5.83,0.17) off-figure; use epsilon^{-1}=-1+sqrt2 -> (0.414,-2.414)
  \fill (0.414,-2.414) circle (1.8pt) node[right,font=\scriptsize]{$\sqrt2-1$};
  % conjugate point of epsilon under v->u : (-0.414,2.414) is -(sqrt2-1)... mark 1 and -1
  \fill (1,1) circle (1.8pt) node[above right,font=\scriptsize]{$1$};
  \fill (-1,-1) circle (1.8pt) node[below left,font=\scriptsize]{$-1$};
  \node[font=\scriptsize] at (2.7,2.0) {$uv=1$};
  \node[font=\scriptsize] at (-2.7,2.0) {$uv=-1$};
\end{tikzpicture}
\end{center}

The two hyperbolas $uv=\pm1$ for $d=2$, with the points $\Phi(\alpha)$ of the units $\alpha=\pm1$, $1+\sqrt2$, $\sqrt2-1$ marked; the units of $R$ are exactly the points of the lattice $\Phi(R)$ lying on these curves.

\begin{method}{To locate the fundamental unit $\epsilon$ of $\mathbb{Z}[\sqrt d]$.}
Seek the smallest $\epsilon=a+b\sqrt d>1$ with $a,b>0$ and $a^2-b^2d=\pm1$ by scanning $b=1,2,3,\dots$ and testing whether $b^2d\pm1$ is a perfect square $a^2$. The first hit gives $\epsilon$; every unit is then $\pm\epsilon^{\,n}$, $n\in\mathbb{Z}$. The first quadrant units (those with $u>0$, $v>0$, which are the powers $\epsilon^{n}$ of norm consistent with $uv=1$ after squaring) form the infinite cyclic group $U_0$ of Artin's Exercise 9.5.
\end{method}

\begin{wex}{The fundamental unit for $d=3$}
Find the fundamental unit of $\mathbb{Z}[\sqrt3]$ and the generator of the first-quadrant group $U_0$.
\wrec Scan $b=1$: need $3\cdot1^2\pm1=a^2$, i.e.\ $a^2\in\{2,4\}$; the value $4$ works.
\wsol With $b=1$, $3b^2+1=4=2^2$, so $a=2$ and $\epsilon=2+\sqrt3$ has $\Nm(\epsilon)=4-3=1$. No smaller $a,b>0$ gives a square ($b=1,a=1$ fails since $3\pm1\in\{2,4\}$ only matched $a=2$), so $\epsilon=2+\sqrt3$ is fundamental. Because $\Nm(\epsilon)=+1$ already, every power has norm $1$ and $\Phi(\epsilon^n)$ lies on $uv=1$ in the first quadrant for $n\ge0$; thus $U_0=\langle \epsilon\rangle=\langle 2+\sqrt3\rangle$ is infinite cyclic. \textit{Check.} $\epsilon^{-1}=2-\sqrt3=\overline{\epsilon}$ since $\epsilon\overline\epsilon=\Nm(\epsilon)=1$, and $\epsilon^2=(2+\sqrt3)^2=7+4\sqrt3$ with $\Nm=49-48=1$, matching Artin's Exercise 9.5(b) for $d=3$.
\end{wex}

\begin{proof}
The equation $x^2-dy^2=1$ is precisely $\Nm(x+y\sqrt d)=1$, so its solutions are the norm-$+1$ elements of $R$, a subgroup of $\units{R}$ of index $1$ or $2$ (the kernel of $\Nm:\units{R}\to\{\pm1\}$). Inside $\units{R}=\langle -1\rangle\times\gen\epsilon$ this kernel is $\langle -1\rangle\times\langle \epsilon_1\rangle$ with $\epsilon_1=\epsilon$ if $\Nm(\epsilon)=+1$ and $\epsilon_1=\epsilon^2$ if $\Nm(\epsilon)=-1$ (so that $\Nm(\epsilon_1)=(\pm1)^2=1$). Discarding the sign, the positive solutions are the positive powers $\epsilon_1^{\,n}$, ordered by size since $\epsilon_1>1$.
\end{proof}

\begin{pitfall}
The lattice picture and the norm $a^2-b^2d$ are tied to the ring $R=\mathbb{Z}[\sqrt d]$, valid when $d\equiv2,3\bmod4$. When $d\equiv1\bmod4$ the ring of integers is the larger $\mathbb{Z}[\tfrac{1+\sqrt d}2]$, the fundamental unit may have a half-integer coordinate (e.g.\ $\epsilon=\tfrac{1+\sqrt5}2$ for $d=5$), and the Pell correspondence then runs through $x^2-dy^2=\pm4$ rather than $\pm1$. The structure theorem $\units{R}\cong\langle -1\rangle\times\langle \epsilon\rangle$ is unchanged.
\end{pitfall}

