 \begin{array}{cccc}
 20\% homework + 25\% midterm 1 + 25\% midterm 2 + 30\% final \\
 20\% homework + 25\% midterm 1 + 15\% midterm 2 + 40\% final \\
 20\% homework + 15\% midterm 1 + 25\% midterm 2 + 40\% final
 \end{array}
\right\}. \]

