Type: problem
Title: Proving Irreducibility
Content:
\begin{problem}[Proving Irreducibility]
\begin{parts}
\item If $\partial f \leq 3$ then it is irreducbile if it has no roots.
\item 
\begin{theorem}
Assume $f(x) \in Z[x]$, and assume that $p$ is a prime such that $p$ doesn't divide $a_n$ and $\bar{f}(x) = \bar{a}_nx^n$ is irreducible, then $f$ is irreducible over $Z[x]$. This is a reduction ring homomorphism $Z[x] \to \F_p[x]$.
\end{theorem}
\end{parts}
\end{problem}

latex:
\begin{problem}[Proving Irreducibility]
\begin{parts}
\item If $\partial f \leq 3$ then it is irreducbile if it has no roots.
\item 
\begin{theorem}
Assume $f(x) \in \mathbb{Z}[x]$, and assume that $p$ is a prime such that $p$ doesn't divide $a_n$ and $\bar{f}(x) = \bar{a}_nx^n$ is irreducible, then $f$ is irreducible over $\mathbb{Z}[x]$. This is a reduction ring homomorphism $\mathbb{Z}[x] \to \F_p[x]$.
\end{theorem}
\end{parts}
\end{problem}

\begin{definition}[Primitive]
A polynomial $f \in \mathbb{Z}[x]$ if its coefficients are \emph{all} relatively prime, so that the ideal $(a_0, \dotsc, a_n)$ is simply $\mathbb{Z}$, or equivalently that there exist $b_0,\dotsc,b_n \in \mathbb{Z}$ such that $\sum b_ia_i = 1$.
\end{definition}

\begin{example}
The polynomial $4x^3 + 6x^2 + 15x + 9$ is primitive while $4x^3 + 6x^2 + 16x + 18$ is not, since every term is divisible by $2$.
\end{example}

\begin{proposition}
A polynomial $f \in \mathbb{Z}[x]$ is primitive if and only if its reduction $\bar{f}$ modulo $p$ is not the zero polynomial for all prime $p$.
\end{proposition}

\begin{remark}
Without the sign convention, $X=1\cdot X=(-1)\cdot(-X)$ gives two decompositions.
The zero polynomial is excluded because it has no such unique primitive part.
\end{remark}

\begin{lemma}
If we start with a polynomial in $\mathbb{Z}[x]$, then the $c$ which we pull out will also be an integer.
\end{lemma}

\begin{lemma}
Let $f,g \in \mathbb{Z}[x]$ be primitive. Then $f\cdot g \in \mathbb{Z}[x]$ is also primitive.
\end{lemma}

\begin{proof}
For every prime $p$, the reductions $\bar f,\bar g\in\mathbb F_p[X]$
are nonzero because $f$ and $g$ are primitive. The polynomial ring
$\mathbb F_p[X]$ is an integral domain, so $\overline{fg}=\bar f\bar g\ne0$.
Thus no prime divides every coefficient of $fg$, and $fg$ is primitive.
\end{proof}

\begin{lemma}
If $f \in \mathbb{Z}[x]$ is primitive and $g \in \mathbb{Z}[x]$ is any polynomial, then if $f$ divides $g$ in $\mathbb{Q}[x]$ then $f$ divides $g$ in $\mathbb{Z}[x]$.
\end{lemma}

\begin{example}[Counter example when not primitive]
Consider that $4x$ divides $x(x-1)$ in $\mathbb{Q}[x]$ but not in $\mathbb{Z}[x]$ because $4x$ is not primitive.
\end{example}

\begin{proof}
There exists some unique way of writing $g$ as $c \cdot g_0$. Since $f$ divides $g$ in $\mathbb{Q}[x]$ then $g = f \cdot h$ for some $h \in \mathbb{Q}[x]$. Thus $f \cdot h = c \cdot g_0$, and we can write $h = d \cdot h_0$. Then $g = d \cdot f \cdot h_0$, and since $f$ and $h_0$ are primitive we know that $fh_0$ is primitive as well. Since this decomosition is unique, this implies that $c = d$ and $g_0 = f h_0$. Then $f$ divides $g_0$ and $g_0$ divides $g$ in $\mathbb{Z}[x]$, so $f$ divides $g$ in $\mathbb{Z}[x]$.
\end{proof}

\begin{lemma}[Gauss]
Let $f \in \mathbb{Z}[x]$. If $f$ is an irreducible polynomial in $\mathbb{Z}[x]$ then $f$ is irreducible in $\mathbb{Q}[x]$.
\end{lemma}

\begin{proof}
Assume $f = gh$ in $\mathbb{Q}[x]$ where $\partial g > 0$. Write $f = bf_0$, $g = cg_0$, and $h = dh_0$. Then $bf_0 = gh = cdg_0h_0$. Then $g_0h_0$ is primitive, so $f_0 = g_0h_0$ and $f = bg_0h_0$.
\end{proof}

\begin{lemma}[Eisenstein's Criterion]
Let $f = \sum a_ix^i \in \mathbb{Z}[x]$. Fix a prime $p$ and assume the following:
\begin{enumerate}
\item $p$ does not divide $a_n$;
\item $p$ divides all $a_i$ where $0 \leq i \leq n-1$; and 
\item $p^2$ does not divide $a_0$.
\end{enumerate}
Then $f$ is irreducible in $\mathbb{Z}[x]$, and by Gauss' Lemma in $\mathbb{Q}[x]$ as well.
\end{lemma}

\begin{proof}
Proof by contradiction. Assume $f$ has the requisite properties but $f$ is reducible in $\mathbb{Z}[x]$, so $f = gh$. Let $g = \sum_{0 \leq i \leq m} g_ix^i$ and $h = \sum_{0 \leq i \leq \ell} h_ix^i$. Consdier $\bar{f} = \bar{a}_nx^n = \bar{g}\bar{h}$. Recall that $a_n = g_mh_\ell$ and $a_0 = g_0h_0$. Then $p$ divides $g_0$ and $h_0$; then $p^2$ divides $g_0h_0 = a_0$ which is a contradiction.
\end{proof}

\begin{example}
Consider that $x^2-p$ is irreducible in $\mathbb{Q}[x]$ by Eisenstein. Thus $\sqrt{p}$ is irrational. And just like that, most of ancient greek mathematics is solved.
\end{example}

\begin{example}
Notice that $x^p - 1 = (x-1) \cdot x^{p-1} + x^{p-2} + \cdots + 1 = (x-1)\Phi_p(x)$. This is irreducible by Eisenstein.

\begin{proof}
Consider $\Phi_p(x+1)$, so $(x+1)^p - 1 = x \cdot \Phi_p(x+1)$. We can use the binomial theorem to say that 
\[ (x+1)^p = \sum {p \choose i}x^i = x^p + px^{p-1} + \cdots + px + 1. \]
Then 
\[ \Phi_p(x+1) = x^{p-1} + px^{p-1} + \cdots + p. \]
Recall that $p$ divides ${p \choose i}$ for all $1 \leq i \leq p-1$. Then $\Phi_p(x+1)$ is Eisenstein, and so $\Phi_p(x+1)$ is irreducible, and so $\Phi_p(x)$ is irreducible.
\end{proof}
\end{example}

\begin{problem}[Challenge, find a better proof than the current one which is terrible]
Prove that $x^n + x + 1 \in \F_2[x]$ is irreducible for $n \geq 2$.
\end{problem}

\begin{example}
If $k$ is an extension of $F$ then $k$ has the structure of an $F$-vector space. The cannonical example for this is thinking of $\mathbb{C}$ as a two-dimensional $\mathbb{R}$-vector space with basis $\{1, i\}$.
\end{example}

\begin{definition}
An extension $k/F$ is finite if $k$ is a finite dimensional $F$-vector space. The degree of $k/F$, written as $[k : F] = \dim_Fk$ is the $F$ dimension of $k$.
\end{definition}

\begin{example}[Examples of degrees]
\begin{enumerate}
\item $\mathbb{C}/\mathbb{R}$ is finite and $[\mathbb{C} : \mathbb{R}] = 2$.
\item $\mathbb{R}/\mathbb{Q}$ is infinite since $n$-tuples of $\mathbb{Q}$ are countable and $\mathbb{R}$ is uncountable.
\item Let $\mathbb{Q}(i) = \{x + iy \in \mathbb{C} \mid x,y \in \mathbb{Q}\}$. Then $\mathbb{Q}(i)/\mathbb{Q}$ is finite with degree $2$.
\end{enumerate}
\end{example}

\begin{example}
Consider $\mathbb{Q}[i]$ and $\mathbb{Q}(i)$. We say that $\mathbb{Q}[i]$ are rational polynomials in $i$ and $\mathbb{Q}(i)$ are quotients of these polynomials, understanding that even powers of $i$ and odd powers of $i$ to collapse it into rational and imaginary components. These are equal to one another. However, $\mathbb{Q}[\pi] \subset \mathbb{Q}(\pi)$ but they are not equal (since the field extension is not finite as $\pi$ is not algebraic).
\end{example}

\begin{theorem}[Tower Law]
Let $L/k$ and $k/F$ be field extensions. Then $[L : F] = [L : k] \cdot [k : F]$.
\end{theorem}

\begin{proof}
If $L$ is a finite dimensional $F$-vector space then $L$ is a finite dimensional $k$-vector space since if $z_1,\dotsc,z_p$ is an $F$-basis for $L$ then in turn $\alpha = \sum a_iz_i \in F $ for all $\alpha \in L$ so $z_1,\dotsc,z_p$ is a generating set. On the other hand, $k \subseteq L$ is an $F$-vector space. Assume that $[L : k] = n$ with $x_i$ a $k$-basis for $L$ and $[k : F] = m$ with $y_i$ and $F$-basis for $k$. Then we first show that $\{x_iy_j\}$ is an $F$-basis of $L$ so $[L:F] = nm$. First, linear independence: assume that $\sum a_{i,j}x_iy_j = 0$ for $a_{i,j} \in F$. Rewrite this as $\sum\qty(\sum a_{i,j}y_i)x_i = 0$, so $\sum a_{i,j}y_i = 0$ so $a_{i,j} = 0$ and the set is linearly independent. Next, we show this generates $L$ over $F$. Let $\alpha \in L$ be written as $\alpha = \sum \beta_ix_i$ for $\beta_i \in k$. But for each $i$ we have $\beta_i = \sum a_{i,j}y_i$ so $\alpha = \sum\qty(\sum a_{i,j}y_i)x_i = \sum a_{i,j}x_iy_i$, so these generate. Then this is a basis, and the proposition holds.
\end{proof}

