\begin{theorem}
Let $F$ be a field, let $\Omega/F$ be a field extension, let $\alpha \in \Omega$, and let $k = F(\alpha)$. Then either 
\begin{enumerate}
\item $\alpha$ is trancendental, in which case $k/F$ is not finite; or
\item $\alpha$ is algebraic, in which case $k/F$ has finite degree $n$, $F[\alpha] = F(\alpha)$, and there exists a unique monic irreducible polynomial $m_\alpha(x) \in F[x]$ of degree $n$ such that $m_\alpha(\alpha) = 0$. This $m_\alpha$ is called the minimal polynomial of $\alpha$ over $F$.
\end{enumerate}
\end{theorem}

\begin{lemma}
If $\alpha$ is trancendental over $F$ then $k = F(\alpha)$ is infinite over $F$ and $F[\alpha] \cong F[x]$.
\end{lemma}

\begin{lemma}\label{lemma:minimal}
The polynomial $m_\alpha$ is the unique monic polynomial of minimal degree which has $\alpha$ as a root; consequently, it is irreducible.
\end{lemma}

\begin{proof}[Proof of~\ref{lemma:minimal}]
By the proof of $\textsc{euclidean} \implies \textsc{pid}$ (i.e., any element of minimal degree in an ideal of $F[x]$ generates the ideal). Hence $m_\alpha(x)$ generates the idea, and so it is the unique monic element of minimal degree. To show it is irreducible, suppose that $m_\alpha = fg$; then $m_\alpha(\alpha) = f(\alpha)g(\alpha) = 0$. Since $K$ has no zero divisors we know that $f(\alpha) = 0$ or $g(\alpha)=  0$. Assume without a loss of generality that $f(\alpha) = 0$. Assume (to get a contradiction) that $\partial f, \partial g < \partial m_\alpha$. However, if this is the case then we have a polynomial with $\alpha$ as a root with a smaller degree than $m_\alpha$, which we had already shown to be minimal. This presents a contradiction, and so $m_\alpha$ is irreducible.
\end{proof}

\begin{proof}[Proof of part 2]
Since $\alpha$ is alegebraic, we know that the homomorphism is not injective. Then its kernel is a nontrivial ideal $I \subseteq F[x]$, so by \textsc{pid}-ness $I = (g(x))$ for some nonzero $g \in F[x]$. We can call this polynomial $g = m_\alpha$.
\end{proof}

\begin{corollary}
If $\alpha$ is algebraic over $F$ then $F[x]/(m_\alpha(x))$ is a field which is isomorphic to $F[\alpha]$ by the first isomorphism theorem.
\end{corollary}

\begin{proof}
Recall that the minimal polynomial is irreducible, and in a \textsc{pid} irreducibility implies that it is prime. Then $(m_\alpha)$ is a prime ideal and so maximal. Then $F[x]/(m_\alpha)$ is a field.
\end{proof}

\begin{corollary}
If $\alpha$ is algebraic over $F$ then $F[\alpha] = F(\alpha)$.
\end{corollary}

\begin{proof}
By definition $F[\alpha] \subseteq F(\alpha)$. Since $F[\alpha]$ is a field containing $F,\alpha$ and $F(\alpha)$ is the smallest extension of $F$ containing $\alpha$ then $F(\alpha) \subseteq F[\alpha]$, and so they are equal by dual containment.
\end{proof}

\begin{theorem}
Let $f(X) \in F[x]$ be irreducible of degree $n$. Then $F[x]/(f)$ is a field extension of $F$ of degree $n$ with an $F$-basis $\{\bar{1}, \bar{x}, \bar{x}^2, \dotsc, \bar{x}^{n-1}\}$ where $\bar{x}$ is the coset in $F[x]/(f)$ represented by $x$.
\end{theorem}

\begin{proof}
By the corollaries, $K = F[x]/(f)$ is a field extension of $F$. Let $f(x) = a_0 + a_1x + \cdots + a_nx^n$. We claim then taht $1, \bar{x}, \dotsc, \bar{x}^{n-1}$ is generates $K$ over $F$. We know that $K$ is generated by the infinite set $\bar{1}, \bar{x}, \bar{x}^2,\dotsc$. However we see that $\bar{x}^n = 1\frac{1}{a_n}(a_0 + a_1\bar{x} + \cdots + a_{n-1}\bar{x}^{n-1})$, and so on for $\bar{x}^{k}$ for $k \geq n$. All of these expressions are linear combinations of $\bar{1}, \bar{x}, \dotsc, \bar{x}^{n-1}$. Then we must show that these are all linearly independent. Suppose that 
\[b + b_1\bar{x} + \cdots + b_{n-1}\bar{x}^{n-1} = 0.  \]
Notice that $\bar{x} \in K$ satisfies $f(\bar{x}) = 0$ and $f$ is irreducible ofer $F$. Then $\frac{1}{a_n}f(x)$ is the minimal polynomial of $\bar{x} \in K$. Then no polynomial of smaller degree can have $\bar{x}$ as a root, yet we just found $\star$ to have $\bar{x}$ as a root, and so $b_i = 0$ for all $i$ and this set is linearly independent.
\end{proof}

\begin{corollary}
Let $\alpha, \beta \in \Omega$ have the same minimal polynomial over $F$. Then $F(\alpha) \cong F(\beta)$.
\end{corollary}

\begin{definition}
$F(\alpha_1, \dotsc, \alpha_n)$ is a field extension of $F$ which is finitely generated.
\end{definition}

