\begin{lemma}
The angle $2\pi/n$ is constructible if and only if $\zeta_n$ is constructible if and only if $\cos(2\pi/n)$ and $\sin(2\pi/n)$ are constructible.
\end{lemma}

\begin{example}
Consider $f(x) = x^3 - 2 \in \mathbb{Q}$. We know that $\sqrt[3]{2}$ is a real root. How does $f(x)$ split in $\mathbb{Q}\qty(\sqrt[3]{2})$. Since it has a root, we know it factors as $f = (x-\sqrt[3]{2})g(x)$ where $g \in \mathbb{Q}\qty(\sqrt[3]{2})[x]$ has degree two. We can calculate what $g$ is through polynomial division to get that
\[ f(x) = \qty(x-\sqrt[3]{2})\qty(x^2 + \sqrt[3]{2}x + \sqrt[3]{2}^2). \]
We can check the discriminant is negative to see that the remaining quadratic has complex roots, and so cannot split further over $\mathbb{Q}\qty(\sqrt[3]{2})$.
\end{example}

\begin{definition}[Splitting field]
A splitting field for $f(x) \in F[x]$ is an extension $E/F$ such that 
\begin{itemize}
\item $f(x)$ splits in $E$, so $f = a\prod (x-\alpha_i)$
\item $E = F(\alpha_1, \dotsc, \alpha_n)$.
\end{itemize}
In this way, it is kinda like the ``minimal field'' over which $f$ splits.
\end{definition}

\begin{theorem}
Let $f \in F[x]$. Then a splitting field $E/F$ for $f$ exists, and moreover if $\deg(f) = n$ then $[E:F] \leq n!$.
\end{theorem}

\begin{example}
Recall the Cyclotomic polynomial $\Phi_p(x) = (x^p-1)/(x-1)$ for prime $p$. Any $p$\textsuperscript{th} root of $1$ is a root since $\Phi_p(\zeta_p) = (\zeta_p^p-1)/(\zeta_p-1) = 0$. But $\zeta_p^k$ is also a root, and there are $p-1$ of them, which is the degree of $\Phi_p(x)$. So in fact $\Phi_p(x)$ splits over $\mathbb{Q}(\zeta_p)$.
\end{example}

\begin{proof}[Proof of the existence of a finite splitting field]
We can find the splitting field by adjoining all the roots to $\mathbb{Q}$. Then its finitely generated and algebraic, so it is finite.
\end{proof}

\begin{proof}[Proof of the bound on the degree]
Just divide the polynomial by the one root we do have to get a polynomial of degree $n-1$. Then repeat the procedure until we get linear terms. Then we have a tower where the relative degree of the $i$\textsuperscript{th} is $n-i$, and so the degree of the full extension is bounded by $n \cdot (n-1) \cdots 1 = n!$.
\end{proof}

\begin{theorem}
Splitting fields are unique up to an $F$-isomorphism.
\end{theorem}

