{F(\alpha_1,\alpha_2)} \arrow[uu, no head, dotted] \arrow[rruu, "\phi_2" description] & & \\
F(\alpha) \arrow[u, no head] \arrow[rruuu, "\phi_1" description] & & \\
F \arrow[u, no head] & & 
\end{tikzcd}

\end{enumerate}
\end{proof}

