For any polynomial $f = \sum a_ix^i$, define $f' = \sum ia_ix^{i-1}$. This has some nice properties:
\begin{itemize}
\item $d/dx\colon F[x] \to F[x]$ is $F$-linear;
\item $d/dx(a) = 0$ for constant $a$;
\item The Chain Rule;
\item The Product Rule;
\end{itemize}

\begin{proof}
Induction.
\end{proof}

\begin{proposition}
Let $f \in F[x]$. Then $f$ is seperable if and only if $f$ and $f'$ are relatively prime.
\end{proposition}

\begin{proof}
``$\implies$'' Let $f$ be seperable, and let $\Omega$ be a field where $f$ splits, and let $\alpha \in \Omega$ be a root of $f$. Then $\alpha$ is simple if and only if $f(x) = (x-\alpha)h(x)$ and $h(\alpha) \not= 0$. Consider $f'(x) = h(x) + (x-\alpha)h'(x)$ by the chain/product rules, and so $f'(\alpha) \not= 0$. Thus no root of $f$ is a root of $f'$, and hence they share no common factors and so are relatively prime in $F$.

``$impliedby$'' Proof by contrapositive. Assume that $f$ is not seperable, and let $\alpha$ be a multiple root. Hence $f(x) = (x-\alpha)^2g(x)$ over $\Omega$. Then $f' = 2(x-\alpha)g(x) + (x-\alpha)^2g'(x)$, and so $f'(\alpha) = 0$. Then $f$ and $f'$ have a common root, and so $m_\alpha(x)$ divides both $f$ and $f'$ over $F$. Thus their \textsc{gcd} is not $1$, and so they are not relatively prime.
\end{proof}

\begin{exercise}
Let $D\colon F[x] \to F[x]$ be an $F$-linear map satisfying the product rule and $D(x) = 1$. Prove that $D$ is exactly the derivative. (Hint: Try Induction.)
\end{exercise}

\begin{definition}[Seperable Extension]
An algebraic etension $K/F$ is called seperable if every element $\alpha \in K$ satisfies a seperable polynomial over $F$. Equivalently, the minimal polynomial over $F$ of every $\alpha \in K$ is seperable.
\end{definition}

\begin{proposition} Some nice facts:
\begin{enumerate}
\item Let $f \in F$ be irreducible. Then $f$ is seperable if and only if the derivative doesn't vanish.
\item If $\operatorname{char} F = 0$ (so $\mathbb{Q} \subseteq F$) then every irreducible polynomial is seperable.
\item If $\operatorname{char} F = p$ (so $p=0 \in F$) then $f$ is not seperable if and only if $f(x)$ is a polynomial in $x^p$, so $f(x) = g(x^p)$.
\end{enumerate}
\end{proposition}

\epigraph{``Let's do more boring stuff.''}{Asher}

Recall splitting fields. Let $K$ be the splitting field of $x^3 - 2$. We showed that $K = \mathbb{Q}(\sqrt[3]{2}, \omega)$ with the following structure.

\begin{tikzcd}
                                                & K \arrow[ldd, "3" description, no head] \arrow[rd, "2" description, no head] \arrow[rrd, "2" description, no head] \arrow[rrrd, "2" description, no head] &                                                         &                                                                &                                                                       \\
                                                &                                                                                                                                                           & {\mathbb{Q}(\sqrt[3]{2})} \arrow[ldd, "3" description, no head] & {\mathbb{Q}(\sqrt[3]{2}\omega)} \arrow[lldd, "3" description, no head] & {\mathbb{Q}(\sqrt[3]{2}\bar{\omega})} \arrow[llldd, "3" description, no head] \\
\mathbb{Q}(\omega) \arrow[rd, "2" description, no head] &                                                                                                                                                           &                                                         &                                                                &                                                                       \\
                                                & \mathbb{Q}                                                                                                                                                        &                                                         &                                                                &                                                                      
\end{tikzcd}

We know that $\#\Aut_\mathbb{Q}(K) \leq 6$ since any $\phi\colon K \to K$ is determined by the three choices for $\phi(\sqrt[3]{2})$ and the two choices for $\phi(\omega)$.

$K/\mathbb{Q}(\sqrt[3]{2}\omega^2)$ is a degree two extension.

Consider $\sigma_i\colon K \to K$ where $\sigma\colon \omega \mapsto \bar{\omega}$. Then we get the following possible automorphisms:

\begin{align*}
	\sigma_0\colon &= \sqrt[3]{2} \mapsto \sqrt[3]{2}, \omega \mapsto \bar{\omega} \\
	\sigma_1\colon &= \sqrt[3]{2}\omega \mapsto \sqrt[3]{2}\omega, \omega \mapsto \bar{\omega} \\
	\sigma_2\colon &= \sqrt[3]{2}\bar{\omega} \mapsto \sqrt[3]{2}\bar{\omega}, \omega \mapsto \bar{\omega}
\end{align*}

Now consider 
\begin{align*}
	\rho = \sigma_2\sigma_0\colon &K \longrightarrow K \\
	                              & \sqrt[3]{2} \mapsto \sqrt[3]{2} \mapsto \sqrt[3]{2}\omega \\
	                              & \omega \mapsto \bar{\omega} \mapsto \omega
\end{align*}
and
\begin{align*}
	\tau = \sigma_1\sigma_0\colon &K \longrightarrow K \\
	                              & \sqrt[3]{2} \mapsto \sqrt[3]{2} \mapsto \sqrt[3]{2}\bar{\omega} \\
	                              & \omega \mapsto \bar{\omega} \mapsto \omega
\end{align*}

Then we've found six automorphisms $\{\operatorname{id}_K, \sigma_0, \sigma_1, \sigma_2, \rho, \tau\}$. Since our upper bound was six, we've found all possible automorphisms of $\Aut_\mathbb{Q}(K)$. Furthermore, note that every $\sigma_i$ has order $2$. Now we wan't to find some relations. Note that $\rho^2 = \tau$ and $\rho^3 = \operatorname{id}_K$. From this, we can tell that $\Aut_\mathbb{Q}(K) \cong D_6 \cong S_3$.

Remember that $\Aut_\mathbb{Q}(K)$ permutes the roots of $x^3 - 2$. This is a general phenomenon. If $f$ is a polynomial over $F$ and $E$ is the splitting field of $f$ over $F$ then $\Gal(f) = \Aut_F(E)$. Assume $f$ is seperable of degree $n$ with roots $\{\alpha_i\}$ and so $E = F(\{\alpha_i\})$. Then $\Gal(f)$ acts on $\{\alpha_i\}$ and $\Gal(f)$ acts on $E$ by $F$-automorphism. The action of $\Gal(f)$ on $\{\alpha_i\}$ is faithful, so the kernel of the action is trivial.

\begin{proof}
If $\sigma \in \Gal(f)$ fixes all $\alpha_i$ then $\sigma = \operatorname{id}$ on $E$ since $\alpha_i$ generate $E$ over $F$.
\end{proof}

\begin{corollary}
If $f$ is seperable of degree $n$ over $F$ then $\Gal(f)$ is isomorphic to a subgroup of $S_n$. We will soon prove that $[E : F] = \#\Gal(f)$, which gives immediately that $[E:F] \mid n!$ by Lagrange. Given any $K/F$ finite, we'll soon prove that $\#\Aut_FK \leq [K : F]$.
\end{corollary}

\begin{definition}[Galois Extension]
A finite extension $K/F$ is Galois if \[\#\Aut_F K = [K : F].\]
\end{definition}

\begin{definition}
Define the following set
\[  \Hom_{F\text{-vs}}(K, \Omega) = \left\{ \varphi\colon K \to \Omega \mid \text{$\varphi$ is $F$-linear} \right\}. \]
\end{definition}

\begin{definition}[Fixed Field]
The fixed field $K^H = \{\alpha \in K \mid \sigma(\alpha) = \alpha\, \forall\sigma \in H\}$.
\end{definition}

\begin{claim}
We have a tower of extensions $K/K^H/F$.
\end{claim}

\begin{proof}
Let $\alpha,\beta \in K^H \subseteq K$. We konw that $\sigma(\alpha) = \alpha$ and $\sigma(\beta) = \beta$ for all $\sigma \in H$. Then $\sigma(\alpha + \beta) = \sigma(\alpha) + \sigma(\beta) = \alpha + \beta$ and $\sigma(\alpha \cdot \beta) = \sigma(\alpha) \cdot \sigma(\beta) = \alpha \cdot \beta$, so $\alpha + \beta$ and $\alpha\beta$ are in $K^H$. Furthermore, we know that $\alpha\alpha^{-1} = \sigma(\alpha)\sigma(\alpha^{-1}) = 1$, and so $\alpha^{-1} \in K$. Finally, since $\sigma$ is an $F$-automorphism then for any $\lambda \in F$ we know that $\sigma(\lambda) = \lambda$, and so $K^H$ is a field.
\end{proof}

\begin{claim}
Given a tower $K/L/F$, there exists a subgroup of $\Gal(K/F)$ which fixes $L$.
\end{claim}

\begin{proof}
Notes that $\Aut_L K \subseteq \Aut_F K = \Gal(K/F)$. Then simply define $H$ to be the subset of $\Gal(K/F)$ which does fix $L$, and by similar logic about compositions it will be a subgroup. Thus there is a one-to-one correspondence between subgroups of $\Gal(K/F)$ and subextensions of $K/F$.
\end{proof}

