\begin{definition}[Divisibility]
We say that $a$ divides $b$ if $b = ac$ for some $c \in \mathbb{Z}$.
\end{definition}

\begin{definition}[Division Algorithm]
Fix $a$ and $b$. We want to divide $a$ by $b$. Then there exists some unique $q$ and some $0 \leq r \leq a$ such that $b = aq + r$.
\end{definition}

\begin{definition}[Prime]
A number is prime if its only positive divisors are $1$ and itself.
\end{definition}

\begin{theorem}[Well-Ordering Principle]
Every nonempty subset of $\mathbb{Z}_{<0}$ has a least element. This is the defining property of $\mathbb{Z}$.
\end{theorem}

\begin{definition}[GCD]
Let $a,b \in \mathbb{Z}$. The greatest common divisor is the largest common divisor of $a$ and $b$, so $\gcd(a,b) = \max\{d \mid \text{$d$ divides $a$ and $b$}\}$. We know this exists because of well-ordering.
\end{definition}

\begin{definition}[GCD]
Alternatively, the gcd of $a$ and $b$ is a $d$ such that all other common divisors of $a$ and $b$ divide $d$ as well. Eventually we'll prove that these are equivalent.
\end{definition}

\begin{definition}[GCD]
Given $a$ and $b$ in some PID, we say that the GCD is he principal generator $d$ of the ideal $(a,b)$, so $(a,b) = (d)$. Alternatively, the gcd is the smallest positive number in $(a,b)$ if we're working in $\mathbb{Z}$.
\end{definition}

\begin{notation}[GCD]
As a nod to the last definition, we often write the GCD of two numbers as $(a,b)$ to emphasize the relation to ideals.
\end{notation}

\begin{lemma}
Let $d$ be the greatest common divisor of $a$ and $b$. Then for any $x \in \mathbb{Z}$ we know that $(a, b+ax) = d$ as well. Then the GCD is unchanged under linear combinations.
\end{lemma}

\begin{proof}
It's clear that $d$ still divides $b+ax$ if it divides $a$ and $b$, so its clear that $(a,b+ax) \geq (a,b)$. Independently, we know that there can't be a larger divisor since if $d'$ divides $b + ax$ then $d'$ divides $b$, and we already know that $d$ is the largest divisor of $b$ which also divides $ax$. Thus $(a,b+ax) \leq (a,b)$ so $(a,b+ax) = d$.
\end{proof}

\begin{lemma}
Let $I = \{ax+by \mid x,y \in \mathbb{Z}\} = (a,b)$. Then $I = \{dx \mid x \in \mathbb{Z}\}$ where $d$ is the greatest common divisor of $a$ and $b$.
\end{lemma}

\begin{proof}
We show containment each way. First we note that $I \subseteq d\mathbb{Z}$ since every element of $I$ is divisible by $d$ since if $d$ divides $a$ and $b$ then it divides $ax+by$. Then we show that $d\mathbb{Z} \subseteq I$ (this is sometimes called Bezout's Lemma). \note{This part could be proved with the Extended Euclidean Algorithm.} By the Well-Ordering property, we know that there exists some $c = \min(I \cap \mathbb{Z}_{>0})$. We know that $c \geq d$ since it must be the case that $d$ divides $c$. On the other hand, if we can show that $c$ is a common divisor of $a$ and $b$ then we know that $c \leq d$ as well. We know that $a = cq + r$ for $0 \leq r \leq c$. Then we know that $c \in I$ implies that $c = ax + by$ so $r = a-cq = a(1-xq) + b(-yq)$ so $r \in I$. Since $c$ is the minimum positive element we know that $c = 0$ and so $a = cq$ so it divides $a$. Repeat for $b$. Then $c \leq d$ and $c \geq d$ so $c=d$. This also gives us the definition of the GCD which is the divisor of $a$ and $b$ which is divisible by all other common divisors.
\end{proof}

\begin{lemma}
Let $a$ and $b$ be relatively prime. If $a$ divides $bc$ then $a$ divides $c$.
\end{lemma}

\begin{proof}
Note that $(a,b) = 1$, so there exist some $x,y \in \mathbb{Z}$ such that $1 = ax + by$. Multiplying through by $c$, we get that 
\[ c = cax + cby. \]
Since $a$ divides $cb$ it divides $cby$ and it trivially divides $cax$ so $a$ divides $c$.
\end{proof}

\begin{corollary}
If $p$ is prime and $p$ divides $ab$ then $p$ divides $a$ or $p$ divides $b$.
\end{corollary}

\begin{corollary}
If $p$ divides $\prod a_i$ then for some $i$ we know that $p$ divides $a_i$ (this is the above corollary with induction).
\end{corollary}

\begin{theorem}
All integers have a unique prime factorization. For every $n \in \mathbb{Z}_{\geq 2}$ there exists a unique set of primes $p_1, \cdots, p_k$ and positive integers $a_1 ,\cdots, a_k$ such that $n = \prod_{i=1}^k p_i^{a_i}$.
\end{theorem}

\begin{proof}
Assume that we have two (more than one) such lists of primes and their powers. Denote them $P = p_1, \cdots, p_k$ (possible with repeats) and $Q = q_1, \cdots, q_\ell$. Assyme by way of contradiciton that the lists are disjoint (otherwise we cancel the like terms). We know that $p_1$ divides $\prod_{i=1}^\ell q_i$, so $p_1$ must divide $q_i$ for some $i$. This can happen if and only if $p_1 = q_i$. This contradicts the disjointness of our list and presents a contradiciton.
\end{proof}

\begin{problem}
How many primes are there?
\end{problem}

\begin{theorem}
There are infinitely many primes.
\end{theorem}

\begin{proof}[Euclid's Proof]
Assume by way of contradiction we have a finite list of primes $p_1, \dotsc, p_k$ of all primes. Let $M = \prod p_i$, and consider $M+1$. By the existence of prime factorization, we know that $M+1 = \prod_{i=1}^k p_i^{a_i}$. Without a loss of generality assume that $a_1 \not= 0$. Then $p_1$ divide $M+1$ and since $p_1$ divides $M$ it must be the case that $p_1$ divides $1$ as well which presents a contradiction.
\end{proof}

\begin{lemma}
For any $n \in \mathbb{Z}$ there exists a unique $a,b \in \mathbb{Z}$ such that $a$ is square free (meaning that no square number divides it) and $n = ab^2$.
\end{lemma}

\begin{proof}[Erdős' Proof]
Assume by way of contradiction that there are finitely many primes. Then any square-free number $n = \prod p_i^{a_i}$ where $a_i \in \{0,1\}$. Thus there are only $2^k$ square-free numbers. Now let's look at all numbers at most $N$ for some $N$. By the above lemma, they can be specified by $(a,b)$ where $a$ is square-free and $b^2$ is square. There are $2^k$ square-free numbers and at most $\sqrt{N}$ square numbers, so $N \leq 2^k\sqrt{N}$ for all $N$, so $2^k \geq \sqrt{N}$ for all $N$, which is very very false if $N > 2^{2k}$.
\end{proof}

\begin{definition}[Congruence]
We say that $a \equiv b \pmod{m}$ if and only if $m$ divides $b-a$. Alternatively, we say that $a \equiv b \pmod{m}$ if and only if there exists some $k$ such that $a = b + mk$.
\end{definition}

