\begin{theorem}[Some quick remarks] \hfill
\begin{enumerate}
\item Congruency is an equivalence relation on the integers (transitive, symmetric, and reflexive);
\item For some fixed $m$, we define the congruence class $\bar{a}$ to be the set $\bar{a} = \{n \in \mathbb{Z} \mid n \equiv a \pmod{m}\}$;
\item Arithmetic on these congruence classes holds; If $a \equiv b \pmod{m}$ and $c \equiv d \pmod{m}$ then $a+c \equiv b + d \pmod{m}$ and $ac \equiv bd \pmod{m}$. Thus $\bar{a} + \bar{b} = \overline{a + b}$ and $\bar{a}\bar{b} = \overline{ab}$. This forms the commutative ring $\mathbb{Z}/m\mathbb{Z}$.
\end{enumerate}
\end{theorem}

\begin{problem}
Let $a,b,m$ be fixed.
When is the congruence $ax \equiv b \pmod{m}$ solvable?
\end{problem}

\begin{enumerate}[label=\textbf{Obs. \arabic*.}]
\item If $(a,m)=1$ then we can use Bezout's theorem. This tells us that tehre exist some $X,Y$ such that $1 = aX + mY$. Then we multiply through by $b$ to get that $b = a(Xb) + m(Yb)$. Then $aXb \equiv b \pmod{m}$.
\end{enumerate}

\begin{lemma}
The congruence $ax \equiv b \pmod{m}$ has solutions if and only if the \textsc{gcd} of $a$ and $m$ divides $b$.
\end{lemma}

\begin{proof}
Let $d$ be the \textsc{gcd} of $a$ and $m$. By Bezout, there exists some $X_0, Y_0 \in \mathbb{Z}$ such that $d = aX_0 + bY_0$. Since $d$ divides $b$ there exists some $k$ such that $b = dk$. Then $b = aX_0k + mY_0k$ so $b \cong aX \pmod{m}$ for $X = X_0k$. In the other direction, just write it out. If there is a solution then $b \cong aX \pmod{m}$ so $b = aX + mY$. Since the \textsc{gcd} divides the right hand side it must divide the left as well, so $d$ divides $b$.
\end{proof}

\begin{problem}
Can there be lots of different solutions? What do solutions look like?
\end{problem}

