\begin{definition}[Subgroup]

 Let \(G\) be a group, and \(H \subseteq G\). If we have
 \begin{itemize}
 \item Identity. \(e \in H\);
 \item Closure. \(a \cdot b \in H\) for all \(a, b \in H\);
 \item Inverse. \(a \in H\) implies \(a\inverse \in H\);
 \end{itemize}
 we say \(H\) is a subgroup of \(G\), and we write \(H \subgroup G\).
\end{definition}

