 \begin{align*}
 \abs{G} &= \sum_{gH \in \flatfrac{G}{H}} \abs{gH} \\
 &= \sum_{gH \in \flatfrac{G}{H}} \abs{H} && [REF:lem:cosets-size] \\
 &= \abs{H} \abs{G : H}
 \end{align*}
 as desired.
\end{proof}

