\begin{theorem}[Direct Product Theorem]

 If \(H_1, H_2 \subgroup G\), and
 \begin{enumerate}
 \item \(H_1 \cap H_2 = \Bqty{e}\): \(H_1\) and \(H_2\) intersect trivially;
 \item \(h_1 h_2 = h_2 h_1\) for all \(h_1 \in H_1, h_2 \in H_2\): elements in \(H_1\) and \(H_2\) commute; and
 \item \(G = H_1 H_2\): for all \(g \in G\), \(g = h_1 h_2\) for some \(h_1 \in H_1\) and \(h_2 \in H_2\);
 \end{enumerate}
 then \(G \isomorphic H_1 \times H_2\).
\end{theorem}

